[Definition 7 (resolvent) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[definition]{def:resolvent}
Let $X$ be a regular diffusion with generator $\mathcal L$ and speed measure $m$.  For $\alpha>0$, the \emph{resolvent} is the operator $R_\alpha\coloneqq\alpha(\alpha-\mathcal L)^{-1}$, which averages a function over an independent $\operatorname{Exp}(\alpha)$ time:
\begin{equation}
  R_\alpha f(x)\;=\;\mathbb E\bigl[f(X_{T_\alpha})\mid X_0=x\bigr]\;=\;\alpha\!\int_0^\infty G_\alpha(x,y)\,f(y)\,m(dy),
\end{equation}
with \emph{resolvent kernel} $G_\alpha$.

[Lemma lem:G-boundary-lower of arXiv:2608.19050, 'Online Permutation Embedding: \\ Optimal Stopping and Scaling Laws'] Let $p,q \ge 0$. Then
    \begin{equation}
        G(p,q) \ge (\sqrt{p} +\sqrt{q})^2,
    \end{equation}
and
    \begin{equation}
    G(0,q) \ge (\sqrt{q} + 1/2)^2.
    \end{equation}
The symmetric bound for $G(p,0)$ holds as well.

[Prop lap_dec_inv of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Let $z_0 = (a_0, b_0) \in {\mathbb R}_+^2$ be an initial condition with $a_0 \neq 0, b_0\neq 0$ and $\epsilon > 0$. Then there exist constants $c, C > 0$ such that for $l=1, 2$,
    \begin{equation}
        \forall v \in {\mathbb R},\quad\quad|\phi_l^{z_0}(-\epsilon + iv)| \leq Ce^{-c\sqrt{|v|}}.
    \end{equation}

[Lmm lmmObsIneq of arXiv:2607.29423, 'Schwarzian Field Theory at High Temperatures'] Assume that $s, s_1, t_1, t, t_2$ are points that lie on $\mathbb{R}$ in either increasing or decreasing order. 
Then for any $f \in C^1_{0,+}(\mathbb{R})$
\begin{equation}
\frac{\obs{f}{s}{t_1}_{0}\obs{f}{s_1}{t}_{0}}{\obs{f}{s_1}{t_1}_{0}}
<\obs{f}{s}{t}_{0}
< \frac{\obs{f}{s}{t_2}_{0} \obs{f}{s_1}{t}_{0}}{\obs{f}{s_1}{t_2}_{0}}.
\end{equation}

