[Proposition e: beta Z^2Phi inequality of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $d=1$. Suppose that $Z$ is a Gaussian random field, and define \linebreak $C:\R\to [0,\infty), y\mapsto \BC[Z(0), Z(y)]$. Assume that $\Phi\neq0$, and that $Z$ and $\Phi$ are independent. Further, assume that $\hat{C}$ is not purely discrete, which, e.g., is the case if $Z$ is ergodic and nondeterministic, or if $\limsup_{x\to\infty}|C(x)|<C(0)$. Then $Z^2\cdot\Phi$ is not beyond $0$-uniform and $\Psi$ is not beyond $4$-uniform.

    More precisely, if $Z$ is ergodic, $\Phi$ is solely $p_0$-uniform, $Z\cdot\Phi$ solely $p_1$-uniform, and $Z^2\cdot\Phi$ solely $p_2$-uniform, then $\Psi$ is solely $\min(p_0, p_1+2, p_2+4)$-uniform. We always have $p_2\geq 0$, and most of the time also $p_1\geq0$; see Proposition~(p: d=1 p=2 limit example of the paper). However, if, e.g., $\Phi = \lambda_1$ or $\Phi=\Z+U, U\sim\cU([0,1))$, then $p_1<0$ is possible, and we can even choose $Z$ such that $p_1$ exactly matches any value below $0$ while keeping $p_2=0$. In this way, $p$-uniformity for any $p\in[-1, 4]$ is obtainable exactly with an appropriate choice of $Z$ and $\Phi$.

    \begin{proof}
        Before we start with the main part of the proof, we show that $\hat{C}$ is not purely atomic if $Z$ is either ergodic and nondeterministic, or if $\limsup_{x\to\infty}|C(x)|<C(0)$. In both cases, we can assume that $Z$ is centered without loss of generality. In the first case, we can derive that $Z^2$ must be ergodic as well, and hence by Proposition~(p:pseudo ergodic of the paper) and Isserlis theorem,
        \begin{equation*}
            0 = \hat\beta_{Z^2\cdot\lambda_1}(\{0\}) = \pi^{-1} (\hat{C}\ast\hat{C})(\{0\}) = \pi^{-1}\sum_{x\in\R} \hat{C}(\{x\})^2;
        \end{equation*}
        see~[ISSERLIS_1918].
        As $Z$ is nondeterministic, $\hat{C}\neq0$, whereby it must have a non-trivial non-atomic part. In the second case, we can leverage the fact that $\hat{C}$ is a finite measure, and if it were purely discrete, it would be almost periodic. Thereby, for every $\varepsilon>0$, there is an $l>0$ such that $|C(x+l)-C(x)|<\varepsilon, x\in\R$; see~[Bohr_1925]. Note, however, that there is no equivalence, as the $\limsup$ can be equal to $C(0)$, even if $\hat{C}$ has no discrete component. This can happen with specific singular continuous measures, e.g., if $\hat{C}$ comes from $C(x)=\prod_{n=1}^\infty\cos(2^{-n^2}x)^2, x\in\R$.

        Let us now come to the main part of the proof. Choose $\mu\neq0$ such that it has bounded support and such that it is dominated by the non-atomic part of $\hat{C}$. From Proposition~(p: ind random field convolution formula of the paper), we can derive that
        \begin{equation}
            \hat{\beta}_{Z^2\cdot\Phi} \geq 2^{-1}\pi^{-2}\hat\alpha_\Phi(\{0\})(\hat{C}\ast\hat{C})\geq 2^{-1}\pi^{-2}\hat\alpha_\Phi(\{0\}) (\mu\ast\mu).
        \end{equation}
        Choose $\tilde{Z}$ as an invariant centered GRF with correlation function $\tilde{C}$ such that $\hat{\tilde{C}}=\mu$. Since $\Phi\neq0$, whereby $\hat\alpha_\Phi(\{0\})>0$, we can conclude from~(equation e: beta Z^2Phi inequality of the paper) that $Z^2\cdot\Phi$ is at most as $p$-uniform as $\tilde{Z}^2$. We obtain that the random field $\tilde{Z}^2$ is not beyond $0$-uniform from Theorem~(t:asymptotic variance test function of the paper) since \linebreak $\BC[\tilde{Z}(0)^2, \tilde{Z}(y)^2]= 2 \tilde{C}(y)^2, y\in\R$ by Isserlis formula, see~[ISSERLIS_1918], and therefore
        \begin{equation*}
            \frac{\BV[(\tilde{Z}^2\cdot\lambda_1)(B_r)]}{r^d} = 2\int \max(1-\tfrac{|y|}{r}, 0) \tilde{C}(y)^2 \, dy \xrightarrow{r\to\infty} 2\int \tilde{C}(y)^2\, dy>0.
        \end{equation*} 
        We continue with the analysis of $\Psi$. Let $f\in \cC_c^\infty(\R, [0,\infty))$ with $f\neq 0$, and recall Definition~(d: f_r of the paper). If we apply the more precise Theorem~(t:main theorem formula of the paper) instead of Theorem~(t: main theorem displacement of the paper), we obtain that, as $r\to\infty$,
        \begin{equ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm_global of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Let $p\in ( 4, \infty)$, $\varepsilon\in(0,1)$ and $M\ge 1$. Then, 
there exists $\nu>0$ and noise coefficients $\theta(t)$ satisfying (hyp_noise of the paper) such that, for all initial data for which
\begin{align*}
    \omega_0 \in B^{{-\frac{2}{p}}}_{g,2,p}, \qquad \|\omega_0\|_{B^{{-\frac{2}{p}}}_{g,2,p}} \le M
\end{align*} 
there exists a maximal $L^p$ solution $(\omega, \tau)$ of equation (equation main_ito of the paper) with 
\begin{align*}
    \mathbb{P}(\tau =+\infty) \ge 1-\varepsilon.
\end{align*}
Moreover for all $\theta,\theta_1\in [0,\frac{1}{2})$, and  $\theta_2\in \mathbb{N}$,
\begin{align*}
\omega &\in H^{\theta, p}_{\text{loc}}([0, \tau); H^{-2\theta}_g)
\quad a.s. \\ 
\omega &\in C([0, \tau); B^{{-\frac{2}{p}}}_{g,2,p}) \quad a.s.\\
\omega &\in C^{\theta_1, \theta_2}_{\text{loc}} ((0, \tau)\times \mathbb{T}^3) \quad a.s.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem trivial of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $H_{\mathbf{n}}(\boldsymbol \xi, \boldsymbol \eta)$ be an integrable function that does not depend on $\mathbf{z}$. Then, the function 
\begin{equation*} \begin{split}
    G^{(\mathbf{n})}(\mathbf{z}) = & \prod_{i=2}^m \prod_{k_i = 1}^{n_i} 
    \left[ \int_{C_{i,\textnormal{left}}^{\textnormal{in}}} \mathrm{d}\xi_{k_i}^{i}  +  z_{i-1} \int_{C_{i,\textnormal{left}}^{\textnormal{out}}} \mathrm{d}\xi_{k_i}^{i} \right] 
    \left[ \int_{C_{i,\textnormal{right}}^{\textnormal{in}}} \mathrm{d}\eta_{k_i}^{i} + z_{i-1} \int_{C_{i,\textnormal{right}}^{\textnormal{out}}} \mathrm{d}\eta_{k_i}^{i} \right] 	
    H_{\mathbf{n}}(\boldsymbol \xi, \boldsymbol \eta)
\end{split} \end{equation*}
satisfies 
\begin{equation*}
    \oint_{>1}\cdots \oint_{>1} G^{(\mathbf{n})}(\mathbf{z})  \prod_{i=1}^{m-1} \frac{(z_i+1)^{n_i-n_{i+1}-1}}{z_i^{n_{i+1}+1}} \mathrm{d} z_i 
    =0  
    \qquad \text{for $\mathbf{n} \in ({\mathbb N}_0^{m-1}\setminus {\mathbb N}^{m-1}) \times {\mathbb N}$.}
\end{equation*}

[Lemma l.pointwise_to_ellipticity of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Suppose that $g$ satisfies, for some $r>0$, $\delta\in (0,\nicefrac12)$, and $v_0\in \mathbb R^3$,
    \begin{equation}
        \delta \1_{B_r(v_0)} \leq g \leq 1 - \delta \1_{B_r(v_0)}.
    \end{equation}
    Then
    \begin{equation}
        A[g(1-g)](v) \gtrsim \frac{\Pi(v)}{\left\langle v \right\rangle} + \frac{\mathrm{Id} - \Pi(v)}{\left\langle v \right\rangle^3},
    \end{equation}
    where the implicit constant depends only on $r$, $\delta$, and $v_0$ only.

