body:
[Proposition 2 of arXiv:2608.04937, '2608.04937'] Assume that $B^1$ satisfies \textnormal{(A1)} and $\int^T_0|B^1-B^2|(r,X^2_r,Y^2_r,Z^2_r,\mathcal{L}^2_r)\,dr<\infty$. Then there exists a constant $c_p$ such that
\begin{equation*}
\begin{split}
\sup_{0\le t\le T}|X^1_t-X^2_t|^p
&\le c_p\Bigg(
|\xi^1-\xi^2|^p
+T^p\sup_{0\le t\le T}|Y^1_t-Y^2_t|^p\\
&\quad
+T^{\frac{1}{2}}\Big(\int_0^T|Z^1_r-Z^2_r|^2\,dr\Big)^{\frac{p}{2}}
+\Big(\int_0^T\mathcal{W}_{p}(\mathcal{L}^1_r,\mathcal{L}^2_r)\,dr\Big)^p\\
&\quad
+\Big(\int_0^T|B^1-B^2|(r,X^2_r,Y^2_r,Z^2_r,\mathcal{L}^2_r)\,dr\Big)^p
\Bigg)
\end{split}
\end{equation*}

