[Definition defn:mild-soln of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Given initial condition $(u_0,\eta_0)\in \mathcal{H}^0_\mu$, a process $U(\cdot)=\big(u(\cdot),\eta(\cdot)\big)$ is called a weak solution of (equation eqn:react-diff:mu of the paper) if $u(\cdotp)$ is $\mathcal{F}_t$-adapted and there exists $q\geq1$ such that $\mathbb{P}$--a.s. one has
\begin{align*}
u\in C_{w}([0,\infty);H)\cap L^2_{\emph{loc}}([0,\infty);H^1), \quad \eta\in C({[0,\infty)};M^0_\mu),
\end{align*}
and
\begin{align*}
\varphi(u)\in L^q_{\emph{loc}}([0,\infty);L^q(\mathcal{O})),
\end{align*}
{where $C_{w}([0,\infty);H)$ denotes the space of functions that are weakly continuous in $H$ with respect to $t$. Moreover,} for $\mathbb{P}$--a.s.
\begin{align*}
\langle u(t),v\rangle_H&=\langle u_0,v\rangle_H  -\kappa\int_0^t\langle u(r),v\rangle_{H^1} \emph{d} r-(1-\kappa)\int_0^t\langle \eta(r),v\rangle_{M^0_\mu}\\
&\quad+\int_0^t\langle \varphi(u(r)),v\rangle_H \emph{d} r+\int_0^t\langle v(r),Q\emph{d} w(r)\rangle_H,\\
\langle \eta(t),\tilde{\eta}\rangle_{M^0_\mu}&=\langle\eta_0,\tilde{\eta}\rangle_{M^0_\mu}+  \int_0^t\langle \mathcal{T}_\mu\eta(r),\tilde{\eta}\rangle_{M^0_\mu} \emph{d}r+\int_0^t\langle u(r),\tilde{\eta}\rangle_{M^0_\mu}\emph{d} r,
\end{align*}
{holds for all $v\in H^1\cap L^{q'}(\mathcal{O})$, where $q'\geq1$ is the H\"older conjugate of $q$, and for all $\tilde{\eta}\in M^0_\mu$.}

[Lemma avldptx of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathrm{D}=\mathrm{O}(1)$} and {\small$\delta>0$}, both independent of {\small$N$}. With high probability, we have the following for any admissible {\small$\mathfrak{q}_{\n}$} in the sense of Definition (definition:admissible of the paper):

\begin{align}
\sup_{\t\in[0,1]}\sup_{|\x|\leq N^{\mathrm{D}}}|\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n}}_{\t,\x}|\lesssim N^{-\frac12+\frac34\delta_{\mathbf{S}}+\delta}.
