[Lemma lem:vthd of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] {bass1992lifetimes}}]
    If for any $x\in D$, there exists $b>0$ such that
\begin{equation}
\mathrm{dist}(x',\partial D)\ge C_6(b+l(\gamma_x(x,x')))^{1/\alpha},\ \text{ for all } x'\in\gamma_x,
\end{equation}
letting $\delta(x)$ be the supremum of $b$'s that satisfy (equation eq:2193 of the paper), then this ${\delta}$ is bounded continuous, and satisfies conditions (i) and (ii) in Definition~(def:thd of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] The solution $ u_{\eps}$ of the regularised equation
		\begin{equation}

				\scrL u_{\eps} = \sum_{\ell=1}^{\ell_0} R F_\ell(v_{\eps})\xi_\ell^{\eps}, \quad u(0) = u_0
		\end{equation}
		with $ u_0 \in C^{\gamma}(\bfR^d)$ and $\gamma = \beta - \kappa $, $\kappa >0$,  
		is described by the paracontrolled expansion 
		\begin{equation}
			u= \sum_{|\CI(\tau)| < \gamma} \P (u_\tau, \widehat{Z}_{\mcI(\tau)}) + u^\#.
		\end{equation}
			For any initial condition $u_0 \in  C^\gamma(\bfR^d)$ and stochastic data $\widehat{\mcZ}_{< \gamma}=(\widehat{Z}_\tau)_{\tau\in\mcT_{<\gamma}}$, there exists a small time $T>0$ such that  \eqref{regularied} has a unique solution. Furthermore the solution $(u,u^\#)$ depends continuously on $u_0$ and $\widehat{\mcZ}_{< \gamma}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_existence_b_lower_bound of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] For all $\sigma \in \{-,+\}$ and $ \big(v^{\textup{c}},v^{\textup{exc}},v^{\textup{mea}}\big) \in \Omega_{\textup{c}} \times \Omega_{\textup{exc}}^{-\sigma} \times \Omega_{\textup{mea}}^{\sigma}$, there exists a word $b \in \Omega_{\textup{fin}}$ such that
\begin{enumerate}
\item $v^{\textup{mea}}_{-1} \sim b_1$,
\item $|v^{\textup{c}}|+|\xi^{-\sigma}(v^{\textup{c}}_{-1})|+|v^{\textup{exc}}|+|\chi^{\sigma}|+|v^{\textup{mea}}|+|b|=n$,
\item For all $j \in \llbracket 1,|b| \rrbracket$, $b_j \in A^{\sigma}$.
\end{enumerate}

