+ (f \epsilon - c) \hat{n}_{2} (1 - \hat{v}_{1} \hat{v}_{3}) \right] |\mu \rangle \nonumber \\[-2mm]
& & + \left[ (f + c) \hat{n}_{L-1} 
 + (f \epsilon + c) \hat{n}_{L-2} \hat{v}_{L-1} \hat{n}_{L}
+ (f \epsilon - c) \hat{n}_{L-1} (1
 - \hat{v}_{L-2} \hat{v}_{L}) \right] |\mu \rangle ,

