& & + [d^{-}_{1} - d^{-}_{2}(1-\epsilon)] \hat{n}_{1} \hat{n}_{3} \,  |\mu\rangle
 + q_{-} [ - d^{-}_{1} + d^{-}_{2}(1+\epsilon)]  \hat{n}_{2}\hat{n}_{3} \,  |\mu\rangle 
