\end{equation}

\emph{Product form and two factor bounds.} Write $s_r=f^{(r)}(e^{it})$. As $f^{(r+1)}=f\circ f^{(r)}$ and
$f(s)=s(q+ps)$, we have $\abs{f^{(r+1)}}=\abs{f^{(r)}}\,\left|q+ps_r\right|$; hence, with $\abs{f^{(0)}}=1$,
\begin{equation}
  \abs{f^{(n)}(e^{it})}=\prod_{r=0}^{n-1}\left|q+ps_r\right|,
\end{equation}
and $\left|s_r\right|=\abs{f^{(r)}(e^{it})}$ is nonincreasing in $r$. From
$1-\left|q+ps\right|^2=2pq(1-\operatorname{Re}s)+p^2(1-\left|s\right|^2)\ge 2pq(1-\operatorname{Re}s)$ ...","release_manifest_digest":"sha256:8fda35ef6d22c0a3ce0bbdfdcaba18487a75b35be1631fe536c4f47cc65856a7","revision_digest":"sha256:9441527eea0621f58eb074b387962f422c952438833d88bc07596961b3f7ca8f","source_id":"arxiv:2607.12564","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

body:
[Lemma lem:discrete_contraction of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Assume that $h \lesssim \gamma^{-1} \wedge \gamma/\beta$ and that $c_0/A \lesssim 1$ for sufficiently small implied constants.
    Then, for $\psi_{t_-}^\mathsf{sh}$, $\psi_{t_+}^\mathsf{sh}$ given in~(equation eq:diffuse_then_shift of the paper), $\uppsi_{t_-}^\mathsf{sh}$, $\uppsi_{t_+}^\mathsf{sh}$ the corresponding points in the twisted coordinates, and an absolute constant $c > 0$,
    \begin{align*}
        \norm{\uppsi_{t_+}^\mathsf{sh} - \uppsi_{t_+}}
        \leqslant \exp\Bigl(-c\int_{t_-}^{t_+} (\omega_+ + \eta_t^\mathsf{p})\,\mathrm{d} t\Bigr)\,\norm{\uppsi_{t_-}^\mathsf{sh} - \uppsi_{t_-}}\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 12 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Recall from \eqref{defPgamH} the definition of $\mathcal{P}^{ \gamma} H$. It holds
\begin{align} 
  \forall 0 \leq s \leq t \leq T, \quad \lim_{n \rightarrow \infty} E_{\nu_{\rho}} \big[ \langle \mathcal{M}^n(H) \rangle_t - \langle \mathcal{M}^n(H) \rangle_s \big] = (t-s) D_3  \mathcal{P}^{ \gamma} H.
\end{align}	
Furthermore, if $H \in C_c^1(\mathbb{R})$, it holds
	\begin{align} 
\forall n \in \mathbb{N}_+, \; \forall 0 \leq s \leq t \leq T, \quad		\ E_{\nu_{\rho}} \big[ \langle \mathcal{M}^n(H) \rangle_t - \langle \mathcal{M}^n(H) \rangle_s \big] \leq   C(H)(t-s).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 47 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Using the above conventions, set $M(A,B)=\sup_{x\in A, y\in B} -c(x,y)$ for non-empty $A,B\subset Q_n$. Then, 
    \begin{equation} 
        \sqrt{\mu_n(A)\mu_n(B)}\leq F_n\left( M(A,B) \right).
    \end{equation}
    It is sharp in the sense that, if $j<n$, then 
\begin{equation}
   F_n(j)=\max\{\sqrt{\mu_n(A)\mu_n(B)}: d_H(A,B)\geq n-j\}.
\end{equation}

