body:
[Lemma 47 (Aizenman-Barsky differential inequalities on the magnetization) of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Let $\gamma \in (0,1)$ and $t>0$ and assume that $\| d_\varphi\|_{\infty,1}<\infty$. Then we have
\begin{enumerate}
\item[{\rm (i)}]  $\frac{\partial \widebar{M}(t,\gamma)}{\partial t} 
\leq (1-\gamma) \| d_\varphi\|_{\infty,1} M^*(t,\gamma) \frac{\partial \widebar{M}(t,\gamma)}{\partial\gamma}$.
\item[{\rm (ii)}] $\widebar{M}(t,\gamma) \leq 
\gamma \frac{\partial \widebar{M}(t,\gamma)}{\partial\gamma} 
+ \|M(t,\gamma)\|_2^2 + t M^*(t,\gamma) \frac{\partial \widebar{M}(t,\gamma)}{\partial t}$. 
\end{enumerate}

