[Lemma lem:xi1-incr of arXiv:2609.01311, 'One-Layer Transformer Provably Learns Multiclass\\ One-Nearest Neighbor in Context'] For $\xi_1^t \ge 0$, there exist constants $c_1,c_2,c_3,c_4 > 0$ such that
\begin{align*}
\tfrac{d}{\eta}\big(\xi_1^{t+1} - \xi_1^t\big)
&\ge \tfrac{K-1}{K}\big(c_1\, e^{-6\xi_1^t} - c_2\, e^{2\xi_1^t - \xi_2^t}\big),\\
\tfrac{d}{\eta}\big(\xi_1^{t+1} - \xi_1^t\big)
&\le \tfrac{K-1}{K}\big(c_3\, e^{\poly(N,d)\,\xi_1^t}
- c_4\, e^{2(\xi_1^t - \xi_2^t)}\big).
\end{align*}

[Lemma 5 of arXiv:2606.14170, 'Uniform-in-time error estimates for McKean-Vlasov SDEs with common noise and stochastic al'] Suppose that $\mathbb{E}|X_0^i|^q<\infty$ for all $i\in\mathbb{S}_N$ and some $q>1$. Let Assumptions \ref{A1} and \ref{A2}  hold with $\lambda_1>2\lambda_2$, then there exists $C>0$ such that for any $L\in[0,L^*]$, $i\in\mathbb{S}_N$ and $\varepsilon>0$,
 \begin{align*}
\sup_{t\ge 0} \mathbb{E}|Y_t^{i,\varepsilon}|^q\le \mathbb{E}|X_0^i|^q+C,
 \end{align*}
 where $L^*$ was defined in Lemma \ref{CPoC}.

[Prop 8 of arXiv:2607.04943, '\textbf{Approximation of Random Differential Equations Driven by Physical Brownian Motion '] Let $\xi$ be a centered, exponentially mixing stationary process with $\E|\xi(0)|^p<\infty$ for all $p\geq 1$. Let $a,b\in[0,\infty)$ with $a\leq b$, then there exists a constant $C_p$ depending on $\E|\xi(0)|^p$ such that 

		(i)\begin{equation}
			\Big\|\int_a^b\xi(u)du\Big\|_p\leq C_p (b-a)^{1/2}.
		\end{equation}

		(ii)\begin{equation}
			\Big\|\int_a^b\int_a^v\xi(u)\otimes \xi(v)dudv\Big\|_p\leq C_p(b-a).
		\end{equation}

