[Proposition 5 (Measure-dependent coarse-scale laws) of arXiv:2608.22334, 'Recovering Weighted Tangent Geometry from a Single-Scale Score Field'] For fixed $c,\ell>0$ and $r\downarrow0$, finite positive constants satisfy
\begin{equation}
 \begin{aligned}
 D_{\sigma,\ell\sigma}^{\rm arc}(c)
 &=C_{\rm arc}(c,\ell)\frac{\Delta}{\sigma^2}
   +o\!\left(\frac{\Delta}{\sigma^2}\right),\\
 D_{\sigma,\ell\sigma}^{\rm param}(c)
 &=C_{\rm param}(c,\ell)\frac{\Delta^2}{\sigma^3}
   +o\!\left(\frac{\Delta^2}{\sigma^3}\right).
 \end{aligned}

\end{equation}

[Prop thm:submatrices_suffice of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] \begin{enumerate}[left=0pt]
\item(Alternating case) Let $A\in\Alt_{2n}(F)$ or $A\in\Alt_{2n+1}(F)$ with $\SN^{\alt}(A)=(\lambda_1,\ldots,\lambda_n)$. Then for any $1\le k\le n$,
\begin{equation}
2(\lambda_n+\cdots+\lambda_{n-k+1}) = \inf_{A' \text{ $2k \times 2k$ principal minor of $A$}} v(\det(A')).
\end{equation}

\item(Hermitian case) Let $A\in\Her_n(F)$ with $\SN^{\her}(A)=(\lambda_1,\ldots,\lambda_n)$. Then for any $1\le k\le n$,
\begin{equation}
\lambda_n+\cdots+\lambda_{n-k+1} = \inf_{A' \text{ $k \times k$ minor of $A$}} v(\det(A')).
\end{equation}
\end{enumerate}

