[Proposition prop:frame-expansion of arXiv:2609.02710, 'Asymptotic Mean Value Laplacian\\ on equiregular sub-Riemannian manifolds'] Let $\Omega\subset\mathbb R^n$ be a compact coordinate box.  For every
$1\le i\le k$, the coefficients of $X_i^{x,h}$ extend smoothly in
$(x,h,\xi)$ to a neighborhood of
$K\times\{0\}\times\Omega$.  Moreover, for every integer $m\ge0$, there
exist $C_{K,\Omega,m}>0$ and $h_{K,\Omega,m}>0$ such that
\begin{equation}
  \sup_{x\in K}
  \bigl\|X_i^{x,h}-\widehat X_{i,x}\bigr\|_{C^m(\Omega)}
  \le C_{K,\Omega,m}h
\end{equation}
for every $h \in (0,h_{K,\Omega,m})$.

[Lemma 10 (Spectral gap of restricted chain for small~$\epsilon$) of arXiv:2604.04823, '2604.04823'] Let~$\hat\epsilon, \eta$ be as in Lemma~\ref{l:lyapunov}. 
Then there exists a constant~$\hat c_1 > 0$, independent of~$\epsilon$ and~$h$, such that for all~$\epsilon \le \hat\epsilon$ and all~$h$ satisfying~$0<h/\epsilon^2 \le \eta$, we have
\begin{equation}
   \gap(Q_{h, \epsilon}) \ge \hat c_1 \frac{h^4}{\epsilon} .
\end{equation}
Here, $Q_{h,\epsilon} = P_{h,\epsilon}\vert_{\Omega_1}$ denotes the restriction of the chain $ P_{h,\epsilon}$ to $\Omega_1$, where $P_{h,\epsilon}$ is the Metropolis random walk with step size $h$ and the stationary density $\pi_\epsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:p_solution of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Fix $p,q\in (2,\infty)$, and assume that $u_0\in \mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^3)$ and that $\theta=(\theta_k)_{k\in {\mathbb Z}^3_0}\in \ell^2$ is  normalized and radially symmetric. Let $\tau:\Omega\to [0,\infty]$ and $u:[0,\tau)\times \Omega\to \mathbb{H}^{1,q}(\mathbb{T}^3) $ 
be a stopping time and a progressively measurable process, respectively.

\begin{itemize}
\item We say that $(u,\tau)$ is a \emph{local $(p,q)$-solution} to (equation eq:navier_stokes_intro of the paper) if there exists a sequence of stopping times $(\tau_n)_{n\geq 1}$ such that $ \tau_n\uparrow \tau$ a.s., for which the following are satisfied for every $n\geq 1$:
\begin{enumerate}[{\rm(a)}]
\vspace{0.1cm}
\item $u\in L^p(0,\tau_n;\mathbb{H}^{1,q}(\mathbb{T}^3))$ a.s.;
\vspace{0.1cm}
\item $u\otimes u\in L^p(0,\tau_n;L^{q}(\mathbb{T}^3;{\mathbb R}^{3\times 3}))$ a.s.;
\vspace{0.1cm}
\item a.s.\ for all $t\in [0,\tau_n]$ it holds that 
\begin{align*}
u(t)-u_0
= &\int_0^t \Big((1+\mu)\Delta u(s) -\mathcal{P}u(s) -\mathbb{P}\big[\nabla \cdot (u(s)\otimes u(s))\big]\Big) \,\mathrm{d} s\\
+ &\, \sqrt{\frac{3\mu}{2}}
\int_0^t {{\bf 1}}_{[0,\tau_n]}\Big(\mathbb{P}[(\theta_k\,\sigma_{k,\alpha}\cdot\nabla)u(s)\big]\Big)_ {k,\alpha}\,\mathrm{d} 
\mathcal{W}_{\ell^2}.
\end{align*}
\end{enumerate}
\item A local $(p,q)$-solution $(u,\tau)$ to (equation eq:navier_stokes_intro of the paper) is said to be a \emph{unique (pathwise) local $(p,q)$-solution} to (equation eq:navier_stokes_intro of the paper) if for any local solution $(u',\tau')$ we have $u'=u$ a.e.\ on $[0,\tau'\wedge \tau)\times \Omega$. 

\item A unique local $(p,q)$-solution $(u,\tau)$ to (equation eq:navier_stokes_intro of the paper) is said to be a \emph{unique maximal $(p,q)$-solution} to (equation eq:navier_stokes_intro of the paper) if for any local solution $(u',\tau')$ we have $\tau'\leq \tau$ a.s.\ and $u'=u$ a.e.\ on $[0,\tau')\times \Omega$. 
\end{itemize}

[Lemma lem:detect_intersection_right of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Let $z\in D$ and $r>0$ such that $2r < \delta^{1+a_3}$ and $B(z,r) \subseteq D$. Let $e \in \mathcal {E}^\delta_2(\mathcal {L})$ for some $\mathcal {L} \in \widehat{\Gamma}_2^\delta$, and suppose that $U_e \subseteq B(z,r/4)$. Then there exist $z_1,z_2 \in \partial B(z,r/2)$, $w_1 \in \partial B(z,r/4)$ (where $z_1=z_2$ is allowed) such that one of the following is true.
\begin{itemize}
\item Let $\eta^{\theta_2}_{z_1}$ be the angle $\theta_2$ flow line of $h$ starting at $z_1$ and stopped upon exiting $B(z,3r/4)$. Let $\eta^R_{w_1}$ be the angle $-\pi/2$ flow line starting at $w_1$ and stopped upon exiting $B(z,r/2)$. Then $\partial U_e \subseteq \eta^R_{w_1} \cup \eta^{\theta_2}_{z_1}$.
\item Let $\eta^{\theta_2}_{z_1}$ (resp.\ $\eta^{\theta_2}_{z_2}$) be the angle $\theta_2$ flow lines of $h$ starting at $z_1$ (resp.\ $z_2$) and stopped upon exiting $B(z,3r/4)$. Let $\eta_{w_1}^L$ be the angle $+\pi/2$ flow line starting at $w_1$. Then it hits $\eta^{\theta_2}_{z_2}$ before exiting $B(z,r/2)$. Let $\overline{w}$ denote the first hitting point, and let $\overline{\eta}^R$ be the angle $-\pi/2$ flow line starting at $\overline{w}$ and stopped upon exiting $B(z,r/2)$. Then $\partial U_e \subseteq \overline{\eta}^R \cup \eta^{\theta_2}_{z_1}$.
\end{itemize}

