[Theorem thm:alias-cell of arXiv:2608.23860, 'Revelation Control'] For the binary action menu, the exact refinement value is
\begin{equation}
\boxed{
V_B(\mathscr G)-V_B(\mathscr H)
=
\mathbb E[\min\{a_H,b_H\}].
}

\end{equation}
Thus strict value is present exactly when the coarse information has positive probability of retaining refined posterior mass on both sides of the terminal decision boundary.  More quantitatively, let $A\in\mathscr H$ with $\mathbb P(A)>0$.  If for some $\delta>0$ and $\alpha,\beta>0$,
\begin{equation}
\mathbb P(m_G\ge\delta\mid\mathscr H)\ge\alpha,
\qquad
\mathbb P(m_G\le-\delta\mid\mathscr H)\ge\beta
\qquad\text{a.s.\ on }A,

\end{equation}
then
\begin{equation}
\boxed{
V_B(\mathscr G)-V_B(\mathscr H)
\ge
\mathbb P(A)\,\delta\,\min(\alpha,\beta)>0.
}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 43 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $\mu$ be a probability measure on $[-1,1]$. 
	Let $\ell \geq 1$ and $\theta \in \cC^\ell(\R^*)$ such that $\int_{-1}^1 \abs{\theta} \diff \mu < \infty$. 
	Define $\Theta(x)$ for $x \in \R^*$ as in \eqref{eq:def_Theta}.
	Then, the following properties hold.
	\begin{enumerate}
		\item The function $\Theta$ is in $\cC^{\ell-1}(\R^*)$ and, for any $0 \leq k \leq \ell-1$ and $x \in \R^*$, \eqref{eq:derivative_Theta} holds.
		Moreover, $\Theta$ is $\cC^{\ell}$ on $\R \setminus [-1,1]$ and \eqref{eq:derivative_Theta} holds with $k=\ell$ and $x \notin [-1,1]$.

		\item If $\int \frac{1}{1-t} \diff \mu(t) < \infty$, then $\Theta$ is $\ell$ times differentiable at 1 and \eqref{eq:derivative_Theta} holds with $k=\ell$ and $x=1$.

		\item If $\mu$ has a density $\varrho$ such that, for some $M>0$, for any $x \in[-1,1]$, $\varrho(x) \leq M \sqrt{1-x}$, and if, for any $x \geq 1$, $\theta(x) = T_\ell[\theta,1](x)$, then
		\begin{equation} 
			\abs{\Theta^{(\ell)}(x)-\Theta^{(\ell)}(1)}
			\begin{cases}
				\leq 8 M (\ell+1) \left( \sup_{[1/2,1]} \lvert \theta^{(\ell)} \rvert \right) (x-1)^{1/2} & \\
				\qquad {} + 2^{\ell+2} (\ell+1)!  
				\left( \int \abs{\theta} \diff \mu + \sum_{k=0}^\ell \lvert \theta^{(k)}(1) \rvert \right) (x-1), & \text{for } x \in [1,2], \\
				= o((x-1)^{1/2}), & \text{as } x \downarrow 1.
			\end{cases}
		\end{equation}
	\end{enumerate}

