[Lemma lem:relu-fourier of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] The Fourier transform of $\mathsf{ReLU}(t) = \max\{0,t\}$ is given by the tempered distribution such that for every test function $\psi \in \cS(\RR)$,
\begin{align}
    \dotp{\widehat{\mathsf{ReLU}}}{\psi } =  \dotp{\mathrm{f.p.}\,\frac{-1}{\xi^2}}{\psi} +   i\pi \psi'(0).
\end{align}
Here $\mathrm{f.p.}\, \frac{1}{\xi^2}$ is the Hadamard finite part distribution defined as
\begin{align}
    \dotp{\mathrm{f.p.}\,\frac{1}{\xi^2}}{\psi} = \lim_{\varepsilon \to 0^+} \int_{|\xi|>\varepsilon} \frac{\psi(\xi) - \psi(0)}{\xi^2} \, d\xi.
\end{align}

[Theorem 6 (Exact Skellam regimes) of arXiv:2609.02590, 'Directional Optimal Sub-Gamma Scales for Infinitely Divisible Laws'] For the centered Skellam law \eqref{eq:centered-skellam}, the right scale has
the following regimes:
\begin{equation}
 \cplus(X_{\lambda,p})=
 \begin{cases}
  0,&p=0,\\
  \displaystyle\max_{t>0}\Psi_p(t),&0<p<p_+,\\
  \displaystyle\frac{2p-1}{3},&p_+\leq p\leq1.
 \end{cases}

\end{equation}
For $0<p<p_+$, the maximum is attained at a positive finite argument and is
strictly larger than $\max\{0,(2p-1)/3\}$. No uniqueness is asserted. The left
scale is
\begin{equation}
 \cminus(X_{\lambda,p})=
 \begin{cases}
  \displaystyle\frac{1-2p}{3},&0\leq p\leq p_-,\\
  \displaystyle\max_{t>0}\Psi_{1-p}(t),&p_-<p<1,\\
  0,&p=1,
 \end{cases}

\end{equation}
and the middle regime is again interior controlled.

[Proposition crude_bound of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any $g,n \ge 0$ such that $2g+n-3 \ge 0$ and any compact $K \subset (\mathbb{R}_{+})^{n}$ we have 
    \begin{align*}
        \forall \mu \in [0,\mu_c),\text{ }\forall \mathbf{L}\in K, \hspace{0.3cm} |\mathcal{T}_{n,g}(\mathbf{L},\mathbf{M})| \le  C_{n,g,K}\bigg(\frac{-M_1}{M_0}\bigg)^{3g-3+n},
    \end{align*}
    where $C_{n,g,K} > $ is a constant that depends on $n,g$ and $K$.
    Moreover, we have
    \begin{align*}
        \alpha_{n,g}(\mathbf{M}) \underset{\mu \to \mu_c}{\sim} C_{n,g}\bigg(\frac{-M_1}{M_0}\bigg)^{3g-3+n},
    \end{align*}
    where $C_{n,g} > 0$ only depends on $n$ and $g$.

[Lemma 59 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation from Definition \ref{Def.ParametersEdge}. Then,
\begin{equation}
\SFb(\zc(\kappa);\kappa) - \SFb(c;\kappa) < 0 \mbox{ and }\SFt(\zc(\kappa);\kappa) - \SFt(c;\kappa) > 0. 
\end{equation}

[Lemma 48 (Lemma 4.10 in \cite{MSS24}) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $\cT_1, \cT_2$ be two spanning trees of a connected graph $G$. If $|E(\cT_2) \setminus E(\cT_1)| = k$, then
    \begin{equation}
        \frac{\diam(\cT_2)}{k+1} - 1 \leq \diam(\cT_1) \leq (k+1) \diam(\cT_2) + k   .
    \end{equation}

