[Lem 14 of arXiv:2604.13134, '\bf From Gaussian to Gumbel: extreme eigenvalues of complex Ginibre products with exact ra'] Uniformly on $x\in [-\widetilde{\ell}_{1,\infty}(n), \widetilde{\ell}_{2,\infty}(n)],$ we have the following estimates.
	\begin{enumerate}
		\item If $1\leq j\leq j_n,$ then
		\begin{equation}
			\widetilde{M}^{(n)}_{j, j}(x)=\frac{(1+O((\log\alpha_n)^{-1}))}{\sqrt{2}\pi\alpha_n^{1/4}\tilde{u}^{3/2}_n(j, x)}e^{-\frac{\widetilde{u}^{2}_n(j,x)}{2}}.
		\end{equation} 
		\item If $j_n< j< t_n,$ then
		\begin{equation}
			\widetilde{M}^{(n)}_{j, j}(x)\lesssim\frac{1}{\alpha_n^{1/4}\widetilde{u}^{3/2}_n(j,x)}e^{-\frac{3\widetilde{u}^{2}_n(j,x)}{8}}+n^{-4/5} .
		\end{equation} 
		\item For the endpoint $j=t_n,$
		\begin{equation}
			\widetilde{M}^{(n)}_{t_n, t_n}(x)\leq	n^{-4}.
		\end{equation}
	\end{enumerate}

[Proposition prop:coupl of arXiv:2412.04032, 'Cutoff for the mixing time of the Facilitated Exclusion Process'] [lacoin_simple_2017] Assume that $P=P(K)$ goes to infinity with $K$, and $P\le K/2$ for all $K$. Let $\sigma \sim \pi^{\textsc{ssep}}_{K,P}$, let $x \in \mathbb{Z}$ and $H \ge 0$. Let $\zeta^{(1)}=\zeta^{(1),H} = \Psi(x+H, \sigma)$ and $\zeta^{(2)}=\zeta^{(2),H} = \Psi(x-H, \sigma)$. Notice that $\zeta^{(1)} \ge \zeta^{(2)}$. 
For all $s>0$ and $\varepsilon \in (0,1)$, there exists $C(s,\varepsilon)>0$ such that if $H \le s \sqrt{P}$, for all $t \ge C(s, \varepsilon) K^2$,
\eqs{\mathbb{Q}_{(\zeta^{(1)}, \zeta^{(2)})}\left(\zeta^{(1)}(t) \neq \zeta^{(2)}(t)\right) \le \varepsilon,}
using the same coupling as before. (Proof in the paper; no proof environment follows the statement in the TeX.)

