body:
[Lem 8 of arXiv:2606.11774, 'Martingale Solutions to a Stochastic Keller-Segel System with nonlocal Source and Super-li'] Let $d\ge3,\,\alpha,\,\beta >1, \,\gamma\ge 2$ and $\alpha+1>\beta$. 	Under Assumption \ref{ass}, for $n\in\mathbb N$ and $N>0$, let  $(u_n,{\tau_n^N})$ be a pathwise unique local strong solution to (\ref{equ2}). If \begin{align}
     \max\{3,\gamma,\alpha+1\}<\frac{2}{d+2}(\alpha-1+\beta)+2,
 \end{align}
    then for all $T>0$, there exists a positive  constant $C(T)$ independent of $n$ and $N$  such that
    \begin{align}
\sup_{n\ge1}\mathbb{E}\Big(\sup_{t\in[0,T\wedge{\tau_n^N}]}\|u_n(t)\|_{L^2(\mathcal{O})}^2\Big)\leq C(T),
   \\
\sup_{n\ge1}\mathbb{E}\Big(\int_{0}^{T\wedge{\tau_n^N}}\|\nabla u_n(t)\|_{L^2(\mathcal{O})}^2dt\Big)\leq C(T),
  \\
\sup_{n\ge1}\mathbb{E}\Big(\int_{0}^{T\wedge{\tau_n^N}}\|u_n(t)\|_{L^{\alpha+1}(\mathcal{O})}^{\alpha+1}\|u_n(t)\|_{L^{\beta}(\mathcal{O})}^{\beta}dt\Big)\leq C(T).
    \end{align}
    Moreover,  for any $k\in[1,\frac{2}{d+2}(\alpha-1+\beta)+2)$, 
   there exists a positive  constant $C(T,k)$  independent of $n$ and $N$  such that
 \begin{align}
\sup_{n\ge1}\mathbb{E}\Big(\int_{0}^{T\wedge{\tau_n^N}}\|u_n(t)\|_{L^{k}(\mathcal{O})}^{k}dt\Big)\leq C(T,k).
 \end{align}

