[Lemma LXi of arXiv:2510.22701, 'Gaussian fluctuations in Mean Field Stable matchings'] Suppose  that $d>1$. For $1\leqslant k\leqslant m_n$, we have that 
    \begin{align}
          \Xi_k \leqslant C (n-k+1)^{2-1/d}.
    \end{align}
    Furthermore, for $2\leqslant k\leqslant m_n$, we have that
    \begin{align}
        n^{2-1/d} I_{(\kappa_n-1)/n}\bclr{\tfrac{n-k}{n}}  \leqslant \Xi_k \leqslant n^{2-1/d} I_0\bclr{\tfrac{n-k+2}{n}}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:trelK of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] Suppose that $k\in L^2(\mu\otimes\mu)$ is a symmetric, non-negative definite kernel and $K$ is the corresponding integral operator given by~(equation eq:K of the paper). Then for all $\varepsilon >0$,
    \begin{equation*}
        t_\mathrm{rel}^K(P,\varepsilon)\ \leq\ \frac{1}{2}\overline t_\mathrm{rel}(P^{(2)})\cdot\left\lceil\log(C\norm{k}_{L^2(\mu\otimes\mu)}\varepsilon^{-2})\right\rceil\ \le\ \frac{e}{\sing (\mathcal{L}^{(2)})}\cdot\left\lceil\log(C\norm{k}_{L^2(\mu\otimes\mu)}\varepsilon^{-2})\right\rceil,
    \end{equation*}
    where $C\in(0,\infty)$ is a universal constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 180 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $\usigma $ be a Borel $d\times d_{1}$-valued 
  and $\ub$ be a Borel $\bR^{d}$-valued functions on $\bR^{d+1}$. Assume that $\ua:=\usigma\usigma^*$ is $\bS_{\delta'}$-valued.
Then there exist   
\begin{equation}

\widehat{D\sigma}=\widehat{D\sigma}(d, \delta',q_{0},p_{0},\beta)>0,\quad
\hat{b}=\hat{b}(d, \delta',q_{0},p_{0},\beta,
\rho_{a})>0
\end{equation}
such that if
\begin{equation}

D\usigma\in L_{1,\loc}(\bR^{d+1}),\quad
\widehat { D\usigma}_{p_{0},\rho_{a}}\leq 
 \widehat{D\sigma},
\quad\hat{\ub}_{p_{0} , \rho_{b} }
< \hat b,
\end{equation}
then

 (i) we have
 \begin{equation}

e\widehat { D\ua }_{p_{0} ,\rho_{0}}\leq 
 \widehat{Da},
\quad e\hat {\ub}_{p_{0} , \rho_{0} }
\leq  \hat b,
\end{equation}
where $(\widehat{Da},\hat b)=
(\widehat{Da},\hat b)(d,\delta',p_{0})$, are taken from Lemma 
\ref{lemma 11.26,3} when $n=1$ there;

(ii) we have
\begin{equation}

N_{1}\hat {\ub}_{p_{0},q_{0}, \rho_{b}}<\sfb_{0}(d,\delta'),
\end{equation}
where $N_{1}=N_{1}(d,\delta',q ,p,\beta ,\rho_{a} )$ is taken from \eqref{11.15,4};

(iii) we have
\begin{equation}

\ua^{\shharp}_{\rho_{a}}\leq 
\hat  a,\quad\hat {\ub}_{q_{0},p_{0}, \rho_{b}}\leq
\hat  b ,
\end{equation}
where
$$
\hat a=\hat  a(d,\delta',q,p,\beta)>0,\quad\hat b=\hat  b(d,\delta',q,p,\beta,\rho_{a} )>0,
$$ 
are taken from Theorem \ref{theorem 5.8,20};

(iv) we have
\begin{equation}

e\widehat { D\usigma }_{p_{0},\rho_{0}}\leq 
 \widehat{D\sigma},\quad e\hat {\ub}_{p_{0} , \rho_{0} }
\leq  \hat b,
\end{equation}
where $(\widehat{D\sigma},\hat b )=(\widehat{D\sigma},\hat b )(d,\delta' ,p_{0},n)$ are taken from
Theorem \ref{theorem 6.21.1} with integer $n>d/4$ there and the degree of the polynomial equal to two. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 20 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] A sequence $(u_{\varepsilon })_{\varepsilon >0}\subset
		L^{\Phi}(Q\times \Omega )$ is said to 
		strongly stochastically $\Sigma $-converge in $L^{\Phi}(Q\times \Omega
		) $ to some $u_{0}\in L^{\Phi}(Q\times \Omega ;\mathcal{X}_{A}^{\Phi})$ 
		 if  the following condition is verified: 
		\begin{equation}
			\begin{array}{l}
				\textup{Given}\; \eta>0\; \textup{and}\; \varphi \in L^{\Phi}(Q\times\Omega; A)\; \textup{verifying}\; \|u_{0}- \varphi\|_{L^{\Phi}(Q\times \Omega ;\mathcal{X}_{A}^{\Phi})} \leq \dfrac{\eta}{2}\;  \\
				\textup{there exists}\; \rho>0\; \textup{such that} 	
				\|u_{\varepsilon}-\varphi^{\varepsilon}\|_{\Phi,Q\times\Omega} \leq \eta\;\; \textup{for\, all}\; 0<\varepsilon\leq \rho.
			\end{array}
		\end{equation}

		We denote this by $u_{\varepsilon }\rightarrow u_{0}$ 
			in $L^{\Phi}(Q\times \Omega )$-strong $\digamma\,\Sigma $.

[Lemma l:admissible-random-variable of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] Let $K$ be a compact subset of $\Sigma\setminus\{a_{2g+2}\}$ Then, there exists $r_0>0$ such that, for every $0<r<r_0$, the following holds
\begin{enumerate}
 \item for any $\psi\in\Omega^1_c(\Sigma\setminus \{a_{2g+2}\},\mathfrak{g})$ supported in $K$, $\langle A,\psi\rangle$ is $\widetilde{\mathcal{F}}_{\gamma_r}^G(1)$ measurable;
 \item for any type $\operatorname{I}$ or $\operatorname{II}$ curve $\gamma$ supported in $K$, $\mathrm{g}_\gamma(1)$ is $\widetilde{\mathcal{F}}_{\gamma_r}^G(1)$ measurable;
 \item for any $\psi\in L^\infty(\Sigma)$ and for any approximable current $\mathbf{T}$ supported in $K$, $W_{\psi,\mathbf{T}}$ is $\widetilde{\mathcal{F}}_{\gamma_r}^G(1)$ measurable.
\end{enumerate}

[Lemma 8 of arXiv:2604.15152, 'The Multinomial Allocation Model and the Random Box Load'] Assuming $q_1\le1/4$, define $R_0(n,r)$ by
\begin{align*}
\rE[\hat q_r]&=\rE[p_{r}(\xi)]+n^{-1}R_0(n,r).
\end{align*}
Then for $0\le r\le n$ and $n\ge 1$,
\[-(r!)^{-1}\beta ^{r}(r^2+2)\le  R_0(n,r)\le (r!)^{-1}r(2\beta)^{r}.\]

