[Lemma energy_estimate_lemma_statement of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Let $\sigma$ represent the mobility, i.e. $\sigma(\alpha):=\alpha(1-\alpha)$. Then
    \begin{align} 
        \mathbb{E}_{\mathbb{Q}} \left[ \sup_{H \in C([0,T];C^1([0,1]))} \left\{ \int_0^T \int_0^1 \nabla H_s(x) \rho_s(x) dxds - 2 \int_0^T \int_0^1 [H_s(x)]^2 \sigma(\rho_s(x))dxds\right\}\right]  { < \infty.}
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2606.28793, 'Randomized second order Riesz projections on the Hamming cube'] Let $r\ge1$ and $0<p<\infty$.  There is a constant $D_{p,r}<\infty$ such that, for every Banach space $E$ and every finite symmetric diagonal-free array $(a_{i_1,\ldots,i_r})\subset E$,
\begin{align*}
&\left\|
   \sum_{i_1,\ldots,i_r}^{\ne}
   a_{i_1,\ldots,i_r}\varepsilon_{i_1}\cdots\varepsilon_{i_r}
 \right\|_{L^p(E)}  \le
D_{p,r}
\left\|
   \sum_{i_1,\ldots,i_r}^{\ne}
   a_{i_1,\ldots,i_r}
   \varepsilon_{i_1}^{(1)}\cdots\varepsilon_{i_r}^{(r)}
\right\|_{L^p(E)},
\end{align*}
and conversely
\begin{align*}
&\left\|
   \sum_{i_1,\ldots,i_r}^{\ne}
   a_{i_1,\ldots,i_r}
   \varepsilon_{i_1}^{(1)}\cdots\varepsilon_{i_r}^{(r)}
\right\|_{L^p(E)} \le
D_{p,r}
\left\|
   \sum_{i_1,\ldots,i_r}^{\ne}
   a_{i_1,\ldots,i_r}\varepsilon_{i_1}\cdots\varepsilon_{i_r}
 \right\|_{L^p(E)}.
\end{align*}
Here $\sum^{\ne}$ means that the indices in each summand are pairwise distinct, and $\varepsilon^{(1)},\ldots,\varepsilon^{(r)}$ are independent Rademacher sequences. (Proof in the paper; no proof environment follows the statement in the TeX.)

