[Proposition prop: tree-reduct of arXiv:2604.08462, 'Convergence of $k$-point functions in\\ high dimensional percolation'] For each $k \geq 3$,
\begin{equation}

\begin{gathered}
\text{each $T \in \mathfrak{T}_k$ has a non-leaf vertex $v$ whose two in-edges originate from leaves labeled $I, J \neq 0$.}
\end{gathered}
\end{equation}

[Definition 50 of arXiv:2607.18104, '2607.18104'] For a given  Bernoulli path $h_0$, define the \textbf{ASEP height function} 
\begin{equation}
(y,t) \mapsto h^{\ASEP}(h_0,0;y,t)
\end{equation} as follows. For $t=0$, we set $h^{\ASEP}(h_0,0;y,0)=h_0(y)$ for all $y\in \Z$. Let $\eta_0$ denote the corresponding particle configuration for $h_0$ according \eqref{eq:PathConfiguration}, and let $(\eta_t)_{t \geq 0}$ be the corresponding ASEP. For times $t>0$, we define the height function $h^{\ASEP}(h_0,0;y,t)$ as follows. Whenever a particle jumps in $(\eta_t)_{t \geq 0}$ from site $y$ to site $y+1$ at time $r$, then we set
\begin{equation}
h^{\ASEP}(h_0,0;z,r) = \begin{cases}
h^{\ASEP}(h_0,0;z,r^-) + 1 & \text{ for } z=y ,  \\
h^{\ASEP}(h_0,0;z,r^-)  & \text{ for } z \neq y . 
\end{cases}
\end{equation} Similarly, whenever a particle jumps in $(\eta_t)_{t \geq 0}$ from site $y$ to site $y-1$ at time $r$, then we set
\begin{equation}
h^{\ASEP}(h_0,0;z,r) = \begin{cases}
h^{\ASEP}(h_0,0;z,r^-) - 1 & \text{ for } z=y-1 , \\
h^{\ASEP}(h_0,0;z,r^-)  & \text{ for } z \neq y-1 .
\end{cases}
\end{equation} For starting times $s\geq 0$ for $h^{\ASEP}(h_0,s;z,r)$, we consider the above construction, but with respect to $\eta_s(x)=h_0(x-1)-h_0(x)$ for all $x \in \Z$.

[Definition 15 (Finite $S$-transform) of arXiv:2606.19115, 'Finite free perpetuities'] Let $p \in \polplus$ such that $p(x)\neq x^n$ and $r_n$ the multiplicity of the root $0$ in $p$. The finite $S$-transform of $p$ is the map 
\[S_p^{(n)} \colon \left\{-\frac{k}{n}\colon  k =1,2,\dots, n-r_n \right\} \to \R_{> 0}\] such that
\begin{equation}

\strans{p}{n}\left(-\frac{k}{n}\right) := \frac{\coef{k-1}{n}(p)}{\coef{k}{n}(p)} \quad \text{ for } \quad k=1,2, \dots, n-r_n.
\end{equation}

[Theorem 47 (Local-to-global Peter--Weyl fusion-tree transfer) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Fix $1\le r\le\infty$ and a typed Peter--Weyl fusion tree $\mathscr D$.
In boundary slot $j$, let
$K_j\in\cK_{m_j}^{\mathrm{alg}}$ be an algebraic kernel in the specified
configuration, and put $q=\sum_jm_j$.  For
$S\subset[q]$ and
$\boldsymbol I\in\mathfrak A_{\mathscr D}(S)$, define the unordered
nonnegative sum
\begin{equation}

 \mathfrak F_{\mathscr D,r}^{\boldsymbol I}(S)
 :=
 \sum_{\boldsymbol\lambda\in\Lambda_{\mathrm{int}}(\mathscr D)}
 \prod_{v\in V_{\mathrm{loc}}(\mathscr D)}
  \mathfrak f_{v,r,I_v^{\boldsymbol I}}(\boldsymbol\lambda_v)
 \prod_{e\in E(\mathscr D)}
  \norm{U_{e;\lambda_{e,-},\lambda_{e,+}}},
\end{equation}
where an unordered sum means the supremum over its finite subsums.  Then,
for every finite
$\Lambda\Subset\Lambda_{\mathrm{int}}(\mathscr D)$ and every admissible
tree cut $\boldsymbol I$,
\begin{align}

 &\norm{\Flat_S(\Theta_{\mathscr D,\Lambda}
       (K_1,\ldots,K_N))}_{\Sch_r}\notag\\
 &\quad\le
 \left(
 \sum_{\boldsymbol\lambda\in\Lambda}
 \prod_{v\in V_{\mathrm{loc}}(\mathscr D)}
  \mathfrak f_{v,r,I_v^{\boldsymbol I}}(\boldsymbol\lambda_v)
 \prod_{e\in E(\mathscr D)}
  \norm{U_{e;\lambda_{e,-},\lambda_{e,+}}}
 \right)
 \prod_{j=1}^N\Prof_{m_j,r}(K_j).
\end{align}
When $q=0$, the probabilistic conclusions below are interpreted using the
zero-order conventions $\cT_K^{(0)}=I_0(K)=K$ and $C_0=A_0=1$ fixed above.

For $1\le r<\infty$, set
\begin{equation}

 \mathcal M_{\mathscr D,r}
 :=
 \max_{S\subset[q]}
 \min_{\boldsymbol I\in\mathfrak A_{\mathscr D}(S)}
 \mathfrak F_{\mathscr D,r}^{\boldsymbol I}(S).
\end{equation}
If $\mathcal M_{\mathscr D,r}<\infty$, the series
\[
 \sum_{\boldsymbol\lambda\in\Lambda_{\mathrm{int}}(\mathscr D)}
 \theta_{\mathscr D,\boldsymbol\lambda}(K_1,\ldots,K_N)
\]
converges absolutely and unconditionally in $\mathfrak T_{q,r}$, independently
of the exhaustion or ordering of the internal labels.  Denote its sum by
$\Theta_{\mathscr D}(K_1,\ldots,K_N)$.  It obeys
\begin{equation}

 \norm{\Flat_S(\Theta_{\mathscr D}(K_1,\ldots,K_N))}_{\Sch_r}
 \le
 \min_{\boldsymbol I\in\mathfrak A_{\mathscr D}(S)}
 \mathfrak F_{\mathscr D,r}^{\boldsymbol I}(S)
 \prod_{j=1}^N\Prof_{m_j,r}(K_j),
\end{equation}
and hence
\begin{equation}

 \Prof_{q,r}(\Theta_{\mathscr D}(K_1,\ldots,K_N))
 \le \mathcal M_{\mathscr D,r}
       \prod_{j=1}^N\Prof_{m_j,r}(K_j).
\end{equation}
Thus $\Theta_{\mathscr D}$ extends uniquely to the corresponding simultaneous
profile completions.  If $2\le r<\infty$ and $1\le p<\infty$, then
\begin{align}

 &\norm{\cT_{\Theta_{\mathscr D}(K_1,\ldots,K_N)}^{(q)}}
       _{L^p(\Omega;\Sch_r)}\notag\\
 &\qquad\le C_q(p+r)^{q/2}\mathcal M_{\mathscr D,r}
       \prod_{j=1}^N\Prof_{m_j,r}(K_j).
\end{align}

For $1\le r<\infty$, still assuming
$\mathcal M_{\mathscr D,r}<\infty$, suppose that all
stochastic legs are labelled copies of the complexification of one real
Hilbert space and that every finite-truncation map
$\Theta_{\mathscr D,\Lambda}$ is same-field compatible.  Then
$\Theta_{\mathscr D,\Lambda}^{\mathrm W}$ converges in multilinear operator
norm to a continuous map
\[
 \Theta_{\mathscr D}^{\mathrm W}:
 \prod_{j=1}^N\mathfrak W_{m_j,r}\longrightarrow\mathfrak W_{q,r}.
\]
If, moreover, $2\le r<\infty$, then, for $1\le p<\infty$,
\begin{align}

 &\norm{I_q(\Theta_{\mathscr D}^{\mathrm W}
       (K_1,\ldots,K_N))}_{L^p(\Omega;\Sch_r)}\notag\\
 &\qquad\le A_q(p+r)^{q/2}\mathcal M_{\mathscr D,r}
       \prod_{j=1}^N\norm{K_j}_{\mathfrak W_{m_j,r}}.
\end{align}
For $r=\infty$, \eqref{eq:truncated-fusion-transfer} remains valid for every
finite truncation; no infinite-label profile completion is asserted at that
endpoint.

[Lem 20 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] For all $\lambda \in (0,\infty)$ large enough,
    \begin{equation*}
        P[\text{Po}(\lambda) \geq \lambda + \lambda^{3/4}/2] \leq \exp(-\lambda^{1/2}/9), \quad P[\text{Po}(\lambda) \leq \lambda - \lambda^{3/4}/2] \leq \exp(-\lambda^{1/2}/9)
    \end{equation*}
    hold. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $u$ be a quasi-classical solution of \eqref{eq:model-half-space}--\eqref{eq:model-half-space-bc} with $g\equiv0$. Assume that
\[
f=D_i f^i,
\qquad
f^i\in C_x^{\alpha}(\bar Q_T^+;L_\omega^\gamma).
\]
Then
\begin{equation}
|D_1u|_{(\alpha,\alpha/2);Q_T^+}^{L_\omega^\gamma}
\le C\Bigl(
|u|_{0;Q_T^+}^{L_\omega^\gamma}
+\sum_{i=1}^n |f^i|_{\alpha;Q_T^+}^{L_\omega^\gamma}
\Bigr),
\end{equation}
where $C$ depends only on $n$, $\alpha$, $\gamma$, $\kappa$, and $K$.

[Lem 3 of arXiv:2609.03418, 'Sampling and Density Theorems for the Fractional Opdam--Cherednik Transform'] Let $\mu,\nu\in\mathbb R$, and define \begin{align} \mathcal I(\mu,\nu) := \int_{-1}^{1} G_{\mu}^{\alpha,\beta}(x) G_{\nu}^{\alpha,\beta}(-x) A_{\alpha,\beta}(x)\,dx . \end{align} 
Let 
\[ \kappa_{\alpha,\beta} := \frac{A_{\alpha,\beta}(1)\sinh(2)} {2(\alpha+1)}\]
and $\mu_j\neq0$ be a zero of
$\Psi_{\alpha,\beta}(\mu) = \varphi_{\mu}^{\alpha+1,\beta+1}(1). $
Then, for $\nu\neq\mu_j$,
\begin{align}
\mathcal I(\mu_j,\nu)=
i\kappa_{\alpha,\beta}
\varphi_{\mu_j}^{\alpha,\beta}(1)
\frac{(\rho+i\nu)\Psi_{\alpha,\beta}(\nu)}
{\mu_j-\nu}.
\end{align}
At $\nu=\mu_j$,
\begin{align}
\mathcal I(\mu_j,\mu_j)=
-i\kappa_{\alpha,\beta}
\varphi_{\mu_j}^{\alpha,\beta}(1)
(\rho+i\mu_j)
\Psi_{\alpha,\beta}'(\mu_j).
\end{align}
Moreover, for every $\nu\in\mathbb R$,
\begin{align}
\int_{-1}^{1}
G_{\nu}^{\alpha,\beta}(-x)
A_{\alpha,\beta}(x)\,dx=
\kappa_{\alpha,\beta}
\Psi_{\alpha,\beta}(\nu).
\end{align}

