[Defn 10 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$.
	\begin{enumerate}[(1)]


	\item We call $x\in\Omega$ a \emph{regular point} of $\phi$ if there exists a convex open neighborhood $V$ of $x$ and a semiconvex function $\psi: V \to \R$ with linear modulus touching $\phi$ from below at $x$ in $V$. We denote by $\reg(\phi)$ the set of regular points of $\phi$ and call it the \emph{regular set} of \( \phi \).

	\item We call $x\in\Omega$ a \emph{cut point} of $\phi$ if $x$ is not a regular point of $\phi$. We denote by $\cut(\phi)$ the set of cut points of $\phi$ and call it the \emph{cut locus} of $\phi$, that is, 
	\begin{align*}
	\cut(\phi)= \Omega \setminus \reg(\phi).
	\end{align*}
	\end{enumerate}

[Corollary 12 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Denote by $g_n(x,y)$ the Green's function up to time $n$, i.e.\ 
    \begin{equation*}
        g_n(x,y) := \sum_{k=0}^n q^\omega_k(x,y),
    \end{equation*}
    where $q^\omega_k(x,y)$ is the $k$-step transition kernel of the lazy random walk on $\mathbb{L}^d$ with weights $\weight(e) = \exp(-\beta \omega_e)$. If $\beta \geq 0$ is fixed and $\omega_e \in [-K, K]$ for some $K \geq 0$ and all edges $e \in E^d$, then for all $x \in \Z^d$
    \begin{equation} 
        \sum_{z \in \Z^d} g_n(x,z)^2 \asymp 
         \begin{dcases}
            \sqrt{n} & \text{ if } d=3, \\
            \log n & \text{ if } d=4, \\
            1 & \text{ if } d \geq 5,
        \end{dcases}
    \end{equation}
    and for all $x,y \in \Z^d$ with $\Vert x - y \Vert^2 \leq n$
    \begin{equation}  
        \sum_{z \in \Z^d} g_n(x,z) g_n(y,z) \gtrsim
         \begin{dcases}
            \sqrt{n} - \Vert x-y \Vert & \text{ if } d=3, \\
            \log n - 2 \log \Vert x-y \Vert & \text{ if } d=4.
        \end{dcases}
    \end{equation}

