[Theorem 4 (Risk stability of SGD) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Let the Hessian be a positive trace-class operator with spectrum
\[
\bH=\diag(\lambda_1,\lambda_2,\ldots),
\qquad
\lambda_1=\lambda_{\max}\geq\lambda_2\geq\cdots>0,
\]
and suppose
\(\sigma>0.\)
Then SGD is risk stable if and only if
\begin{equation}

\eta<\frac{2B}{(B+1)\lambda_{\max}}
\end{equation}
and
\begin{equation}

\kappa_{\sgd}(\eta)
:=
\sum_{i\geq1}
\frac{\eta\lambda_i}{2B-(B+1)\eta\lambda_i}
<1.
\end{equation}

[Defi of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [AGS08]
    Let $(S,d)$ be a metric space and $F:S\to (-\infty,\infty]$ measurable. A function $g:S\to [0,\infty]$ is a strong upper gradient for $F$ if for every absolutely continuous curve $v\in AC(a,b;S)$ the function $g\circ v$ is Borel and \begin{align*}
        \left\lvertF(v(t))-F(v(s))\right\rvert\leq \int_s^tg(v(r))\left\lvertv'\right\rvert(r)dr \quad \forall a< s\leq t< b.
    \end{align*}
    In particular, if $g\circ v \left\lvertv'\right\rvert\in L^1(a,b)$ then $F\circ v$ is absolutely continuous and \begin{align*}
        \left\lvert(F\circ v)'(t)\right\rvert\leq g(v(t))\left\lvertv'(t)\right\rvert\quad \text{ for a.e. } t\in (a,b).
    \end{align*}

[Lem bound for F1 of arXiv:2607.27472, 'The stochastic Keller--Segel system in critical spaces'] Assume  (equation Eq_standard of the paper) and  (equation Eq_pc1_new of the paper)--(equation Eq_pc5_new of the paper), then we have the bounds
		\begin{align}\begin{split}&\|
				\mathrm{div}(u\nabla v) -\mathrm{div}(\overline{u} \nabla \overline{v}) \|_{H^{s,q} (\mathbb{T}^d) } \\& \lesssim  \| v\|_{H^{{\gamma_v },q_v}(\mathbb{T}^d)} \|u- \overline{u}\|_{H^{\gamma,q}(\mathbb{T}^d)} +\|\overline{u}\|_{H^{\gamma,q}(\mathbb{T}^d)} \|v- \overline{v}\|_{H^{\gamma_v,q_v}(\mathbb{T}^d)},
			\end{split}
		\end{align}
		and 
		\begin{align}\begin{split}&\|
				\mathrm{div}(u\nabla v)  \|_{H^{s,q} (\mathbb{T}^d) } \,\lesssim \,  \|u\|_{H^{\gamma,q}(\mathbb{T}^d)}\| v\|_{H^{\gamma_v,q_v}(\mathbb{T}^d)},
			\end{split}
		\end{align}
		for all $(u,v),(\overline{u},\overline{v})\in H^{\gamma,q}(\mathbb{T}^d)\times H^{\gamma_v,q_v}(\mathbb{T}^d)$, where $ \gamma= s+2-(1+\kappa)/p$, and $\gamma_v$ is defined analogously with $s$ replaced by $s_v$.

