[Lemma lem.LD of arXiv:2509.21253, '\bf Capacity in high dimensional percolation'] There exists a constant $C>0$ (independent of $s$), such that for any $x,y\in \mathcal H$, 
		\begin{enumerate}
			\item $\tau_{\mathcal H}(x,y) \le C\cdot h(x,y)$ 
			\item  $h*\varphi(y) \le C$. 
			\item $ \sum_{z\in \mathcal H} h(y,z)\cdot  (h*\varphi(z))^2 \le C\cdot h*\varphi(y)$.  
		\end{enumerate}

