[Theorem 25 of arXiv:2606.06757, 'Path-Dependent Ergodic Optimal Control \\ and Backward Stochastic Differential Equations'] Assume that there exists a measurable function $\zeta : \R \times \mathbf{C}_r \to \R^d$ such that $Z^{\tau, \xi}_t= \zeta(t, \X^{\tau, \xi}_t)$ for any $t \geq \tau$ and $\xi \in \mathbf{C}_r$, where $(Y^{\tau}, Z^{\tau}, \Lambda)\in\mathbf{E}_{\tau}(\mathbf{C}_r) \times {\rm{UC}}_{\tau}$ is the solution of the ergodic backward SDE constructed in Theorem \ref{thm:existence_uniqueness} and Remark~\ref{rmk:ebsde_flow_path}. Let
     \begin{equation*}
         \begin{array}{cc}
              \displaystyle \overline{\Lambda}(T) = \int_0^T \int_{\mathbf{C}_{r}} H(t, \chi, \zeta(t, \chi)) \,  m_t(d\chi) dt 
              ~~\mbox{and}~~
              \overline{Y}^\tau_T:=Y^\tau_T-\Lambda(T)+\overline{\Lambda}(T),
              & \, T \in \R \, .
         \end{array}
     \end{equation*}
Then, under Assumption \ref{ass:diff}, $(\overline Y,Z,\overline\Lambda)\in\mathbf{E}_{\tau}(\mathbf{C}_r) \times {\rm{UC}}_{\tau}$ is a solution of the ergodic backward SDE.

[Lem thm:master-lemma-bernoulli of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $p,r\in (0,\infty)$, $\beta \in\mathds{R}$, $\mu,\nu\in (-\infty,0]$, and $\delta\in (0,1)$ such that $\beta p+d+\frac{\nu p}{\max\left\{r,p\right\}} (1-\delta)<0$.
Let further $(\xi_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ and $(\lambda_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ be two families of random variables with $\xi_{j,t,m}\in\mathds{R}$ and $\lambda_{j,.t,m}\in\left\{0,1\right\}$ for $(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d$.
Finally, set
\begin{equation*}
\varrho_{j,m}\mathrel{\mathop:}= 2^{j\mu}\lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j }}^\nu
\end{equation*}
for $j\in\mathds{N}_0$ and $m\in\mathds{Z}^d$.
Then for all $j\in\mathds{N}_0$ and $t\in \left\{F,M\right\}^d$, we have
\begin{equation}
\widetilde{Z}_{j,t}\mathrel{\mathop:}= \mnorm{\lr{\lr{1 + \frac{\left\lVertm\right\rVert_\infty}{2^j}}^\beta  \lambda_{j,t,m}\abs{\xi_{j,t,m}}}_{m\in\mathds{Z}^d}}_{\ell_p}\lesssim 2^{j\frac{d}{p}+j\frac{\mu}{\max\left\{r,p\right\}}(1-\delta)}\widetilde{\Xi}^{\frac{1}{p}},
\end{equation}
where the implied constant only depends on $d$, $p$, $\beta$, $\mu$, $\nu$, $r$, and $\delta$.
Here 
\begin{align}
\widetilde{\Xi}_t&\mathrel{\mathop:}= \sup_{j \in \mathds{N}_0} \Biggl(\frac{1}{M_j} \sum_{\tau=1}^{M_j} \varrho_{j,\phi(\tau)}^{\frac{p}{\max\left\{r,p\right\}}(\delta-1)}\lambda_{j,t,\phi(\tau)}\abs{\xi_{j,t,\phi(\tau)}}^p\nonumber\\
&\hspace{2.5cm}+\sup_{\ell\geq j} \frac{1}{N_\ell} \sum_{\tau=M_\ell + 1}^{M_{\ell+1}}\varrho_{j,\phi(\tau)}^{\frac{p}{\max\left\{r,p\right\}}(\delta-1)} \lambda_{j,t,\phi(\tau)}\abs{\xi_{j,t,\phi(\tau)}}^p\Biggr),\nonumber\\
\intertext{for $t\in\left\{F,M\right\}^d$ and}
\widetilde{\Xi}&\mathrel{\mathop:}= \max_{t\in\left\{F,M\right\}^d}\widetilde{\Xi}_t,
\end{align}
where $\phi:\mathds{N}\to \mathds{Z}^d$ is a bijection such that $\tau\mapsto \left\lVert\phi(\tau)\right\rVert_\infty$ is nondecreasing, and for $j\in\mathds{N}_0$,
\begin{align*}
N_j&\mathrel{\mathop:}=\#\setcond{m\in\mathds{Z}^d}{2^j<\left\lVertm\right\rVert_\infty\leq 2^{j+1}},\\
\intertext{and}
M_j&\mathrel{\mathop:}= \#\setcond{m\in\mathds{Z}^d}{\left\lVertm\right\rVert_{\infty}\leq 2^j}=(2^{j+1}+1)^d.
\end{align*}

