[Lemma continuityoflevelsets of arXiv:2607.21862, '\bf Uniform Large Deviations of Mckean-Vlasov Stochastic Fractional $(\alpha,p)$-Laplacian'] Let conditions  {\bf A} and {\bf B1}
be satisfied. If $\psi_{0,n}\rightarrow\psi_{0}$
in $\mathbb{H}$, then for every $s\geqslant0$, the family of level sets $\{I^s_{\psi_{0,n}}\}_{n=1}^\infty$
converges to the level set $I^s_{\psi_{0}}$ with respect to the Hausdorff metric of $C([0,T],\mathbb{H} )\bigcap L^p([0,T], \mathbb{V}_1  )\\ \bigcap L^q([0,T], \mathbb{V}_2)$:
\begin{align}
\lim_{n\rightarrow\infty}
\sup_{\psi\in I^s_{\psi_{0}}}{\rm dist}_{C([0,T],\mathbb{H} )\bigcap L^p([0,T], \mathbb{V}_1  )\bigcap L^q([0,T], \mathbb{V}_2)}\big(\psi,I^s_{\psi_{0,n}}\big)=0,
\end{align}
and
\begin{align}
\lim_{n\rightarrow\infty}
\sup_{\psi\in I_{\psi_{0,n}}^s}{\rm dist}_{C([0,T],\mathbb{H} )\bigcap L^p([0,T], \mathbb{V}_1  )\bigcap L^q([0,T], \mathbb{V}_2)}\big(\psi,I^s_{\psi_{0}}\big)=0.
\end{align}

[Corollary 48 of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $n\ge2$, and every $k\ge0$,
\begin{equation}
 \Delta_k^{(n)}(J(K))\in
 V_k^{(n)}\Z[q^{\pm1}].
\end{equation}

[Definition def:KLDobrushin of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi \in \mathcal{P}(\mathcal{X}), P \in \mathcal{S}(\pi)$. Then the KL-divergence Dobrushin coefficient of $P$, $c_{KL}(P)$, is defined to be
	\begin{align*}
		c_{KL}(P) := \max_{M,N \in \mathcal{S}(\pi), M \neq N} \dfrac{D^{\pi}_{KL}(MP \| NP)}{D^{\pi}_{KL}(M \| N)} \in [0,1].
	\end{align*}

