[Corollary 12 (Descents in symmetric shelf shuffle) of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] When $p=q=1/2$, we have 
\begin{align*}
\mathbb{E}[D_n] &= \frac{n-1}{2}, \\
\Var(D_n) &=\frac{n+1}{4}-\frac{m}{2}
+\frac{(n+1)mS_n(m)-(n+2)S_{n+1}(m)}{m^n}.

\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:factorization of arXiv:2605.09377, 'A factorization formula for the partition function in the semi-discrete parabolic Anderson'] For $\beta$ sufficiently small, the following holds: For any $\sigma \in (0,1)$ there exists $\theta = \theta(\sigma) > 0$, independent of $\beta$, such that for all $x,y\in\mathbb{Z}^d$ and $s < t$ with $\| x - y \| < (t - s)^\sigma$, the partition function $Z_{x,s}^{y,t}$ has the representation 

\begin{equation}     
Z_{x,s}^{y,t} = p_{t-s}^{y-x} \left(Z_{x,s}^{\infty} Z_{-\infty}^{y,t} + \delta_{x,s}^{y,t} \right),
\end{equation} 

where the error term $\delta_{x,s}^{y,t}$ defined by the formula above satisfies 

\begin{equation}   
\lim_{(t-s) \to \infty} (t-s)^{\theta} \sup_{x, y \in \mathbb{Z}^d: \|x-y\| < (t-s)^{\sigma}} \langle \lvert \delta_{x,s}^{y,t} \rvert \rangle = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma prop:M_expansion of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] Let $\lambda_i, i \in [\![rn ]\!]$, and $Q_{a,b}, a\in [\![r ]\!], b\in [\![rn ]\!]$ be fixed numbers. For $m\in [\![r ]\!]$, $\mathcal{A}\subset [\![rn ]\!]$, let $Q_m(\mathcal{A})=\prod_{a\in \mathcal{A}} Q_{m,a}$.

 Then
\begin{align*}
 \det \mathbf{M}({\lambda}, \mathbf{Q})&= \sum_{(\mathcal{A}_1,\dots,\mathcal{A}_r)\in {\mathcal P}_{r,n}} \!\!\operatorname{sgn}(\sigma_{\underline{\mathcal{A}}}) \prod_{m=1}^r Q_{m}(\mathcal{A}_m) \Delta(\mathcal{A}_m).
\end{align*}

[Corollary 135 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Estimate \eqref{5.25,1} says that the operator
$f\to bP_{\alpha,k}f$ is bounded in $L_{q_{1},q_{2}}$. Its conjugate (with time reversed)
is then also bounded as an operator in 
$L_{q'_{1},q'_{2}}$, where $q_{i}'=q_{i}
/(q_{i}-1)$, that is
$$
\|P_{\alpha,k}(bf)\|_{L_{q'_{1},q'_{2}}}
\leq N\|b\|_{\dot E_{q,q,\alpha} }
\|f\|_{L_{q'_{1},q'_{2}}}.
$$
In case $q_{1}=q_{2}=2$ and $\alpha=1$ we have that, if $q>2$, then
$$
\|P_{1,k}(bf)\|_{L_{2} }
\leq N\|b\|_{\dot E_{q,q,1} }
\|f\|_{L_{2} }. 
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_new2.1 of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $N\ge 1$, $D_1 \subset \widetilde{B}(N)$, $x\in \partial B(2N)$ and $D_2\subset [\widetilde{B}(3N)]^c$ and for each $j\in \{1,2\}$, 
   		\begin{equation} 
				\widetilde{\mathbb{P}}_{x}\big(\tau_{D_j}=\tau_{v}<\tau_{D_{3-j}} \big) \asymp \widetilde{\mathbb{P}}_{x}\big(\tau_{D_j}=\tau_{v}<\infty \big) ,\  \ \ \forall v  \in \widetilde{\partial }D_j.	
				\end{equation}

