[Theorem 4 (Propagation of chaos in the strong sense) of arXiv:2605.15718, 'Mean-field derivation of a two-dimensional signal-dependent parabolic-elliptic Keller-Sege'] \text{} \\
Let $T >0$ and the assumptions \ref{ass_ks} hold. If we further assume that there exists some $C>0$ such that \\
 $\|\nabla\log u^\varepsilon\|_{L^\infty(0,T;L^\infty(\mathbb{R}^2))}
 \leq C$ for all $\varepsilon >0$ it holds \\  
 $\forall l \in \N : \forall \alpha \in (0,\frac{1}{2}) : \forall \beta \in (0,\frac{\alpha}{2}): \forall b \in (0,2\frac{\alpha}{\beta}-4 ) : \exists C>0 : \forall N \geq l, \varepsilon \in (0,1] \text{ with } \varepsilon \geq N^{-\beta} : $
\begin{align*}
\|u^\varepsilon_{N,l}-u^{\otimes l}\|^2_{L^\infty(0,T;L^1(\mathbb{R}^{2l}))}\leq  C \max\big\{ \varepsilon^{b} , \varepsilon\big\}.
\end{align*}
Here $u^\varepsilon_{N,l}(t)$ denotes the $l$-th marginal density of the joint density $u^\varepsilon_N(t)$ of the distribution of $(X^\varepsilon_{N,i}(t))_{1\leq i\leq N}$. \\ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 (Restart system) of arXiv:2608.30715, 'Endpoint Energy Atoms Force Local Pressure Concentration in Three-Dimensional Navier--Stok'] For every fixed \(\tau\in(s,T_*)\),
\begin{equation}
 r_\tau(\tau)=c_\tau(\tau)=g_\tau(\tau)=0

\end{equation}
and
\begin{equation}
 \partial_tr_\tau+(u\cdot\nabla)r_\tau+\nabla\pi_w
 =\nu\Delta r_\tau.

\end{equation}
In addition,
\begin{equation}
 \partial_tc_\tau+\Pp[(u\cdot\nabla)c_\tau]
 =\nu\Delta c_\tau-\Pp[(\nabla u)^Tg_\tau],

\end{equation}
and
\begin{equation}
 \partial_tg_\tau+\Qq[(u\cdot\nabla)g_\tau]
 =\nu\Delta g_\tau-\Qq[(u\cdot\nabla)v_\tau].

\end{equation}

[Defi def:elec_energy of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [Electric energy]
Let $I\subset \IR$ be an interval.
\begin{enumerate}
    \item We call electric fields on $I$ the set of all vector fields $E$ in $L^p_{loc}(I\times \IR,\IR\times \IR)$, for some $1<p<2/(s+1)$ fixed
\item Let $\xi$ be a finite point configuration in $I$ and $E$ an electric field on $I$. We say that $E$ is compatible with $\xi$ in $I$ provided 
\begin{align}
    -\textup{div}\,\left(\left\lverty\right\rvert^sE\right)=c_s\left(\xi-\delta_{\IR}\right) \text{ in }I\times \IR,
\end{align}
in the sense of distributions. Here  $\delta_{\IR}$ is the Radon measure on $\IR\times \IR$ defined by \begin{align*}
    \int_{\IR^2} f(x,y) d\delta_{\IR}(x,y)=\int_{\IR} f(x,0)dx,\quad f\in C_c(\IR^2,\IR).
\end{align*}
Similarly, in (equation eq:hypersurf of the paper) the point configuration $\xi$ is interpreted as a measure on $\IR^2$ via  
\begin{align*}
    \int_{\IR^2} f(x,y) d\xi(x,y)=\int_{\IR} f(x,0)d\xi(x)\quad f\in C_c(\IR^2,\IR).
\end{align*}
\item If $E$ is compatible with $\xi$ in $I$, for $\eta\in (0,1)$  we define the $\eta$-truncation of the electric field $E$ as
\begin{align*}
    E_{\eta}(x,y):=E(x,y)-\sum_{p\in \xi\cap I}\nabla f_{\eta}((x,y)-(p,0)),
\end{align*}
    where $f_{\eta}$ is the function
    \begin{align*}
        f_{\eta}(x,y):=\left(g(x,y)-g(\eta)\right)_+
    \end{align*}
     and $g(\eta)$ is defined by $g(\eta)=g(\eta,0)$.
\item Let $\xi$ be a point configuration on $\IR$. We define the global electric energy of $\xi$ as
\begin{align*}
     \tilde{\mathcal W}^{elec}(\xi):=\inf_E \left(
    \lim_{\eta\to 0}\left( 
    \limsup_{n\to \infty}\frac{1}{\left\lvert\Lambda_n\right\rvert}\frac{1}{c_s}\int_{\Lambda_n\times \IR}\left\lverty\right\rvert^{s}\norm{E_{\eta}}^2-g(\eta)
    \right)
    \right),
\end{align*}
where the $\inf$ is taken over electric fields $E$ that are compatible with $\xi$ in $\IR$.
\item For $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ we set \begin{align*}
    \mathcal W^{elec}(\mathsf{P}):=\int \tilde{\mathcal W}^{elec}(\xi)\mathsf{P}(d\xi).
\end{align*}


\end{enumerate}

[Lem lem13 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $\delta_1$ be as in Lemma (lem11 of the paper). Then there exist $B=B(a,h)>0$, $\Gamma_2=\Gamma_2(a,h)>0$ and $\Gamma_3=\Gamma_3(a,h)>0$
  such that if ((init of the paper)) holds, and if $T\in (0,T_{max}]$ is such that
  \begin{equation} \label{uut}
	|u| + |u_t| \le \delta_1
	\qquad \mbox{in } \Omega\times (0,T),
  \end{equation}
  then for
  \begin{equation} \label{F1}
	{\mathcal{F}}_1(t):=\frac{1+Ba}{2} \int_\Omega |\nabla u|^2
	+ \int_\Omega H^{(1)}(u,u_t) + B \int_\Omega H^{(2)}(u,u_t),
	\qquad t\in (0,T_{max}),
  \end{equation}
  we have
  \begin{equation} \label{13.1}
	\Gamma_2 \int_\Omega v^2 \le {\mathcal{F}}_1(t) \le \Gamma_3 \int_\Omega |\nabla u|^2 + \Gamma_3 \int_\Omega |\nabla u_t|^2
	\qquad \mbox{for all } t\in [0,T)
  \end{equation}
  and 
  \begin{eqnarray}\label{13.2}
	{\mathcal{F}}_1'(t) + \Gamma_2 {\mathcal{F}}_1(t)
	\le \Gamma_3 \int_\Omega |u|\cdot |f(u,u_t,\nabla u,\nabla u_t)|
	+ \Gamma_3 \int_\Omega |u_t|\cdot |f(u,u_t,\nabla u,\nabla u_t)|
	+ \Gamma_3 \int_\Omega |u_t|^3

  \end{eqnarray}
  for all $t\in (0,T)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 of arXiv:2604.10705, '#1'] Let $X:[0, T] \to \mathbb{R}^d$ be a semimartingale satisfying
\begin{align*}
dX(s) = a(s, X_{\wedge s})\mathrm{d}s + \sigma(s, X_{\wedge s^-})\mathrm{d}B(s),
\end{align*} 
with $a = (a_1,...,a_d)$, and $\sigma = (\sigma_{i,j})_{1\leq i\leq d, 1\leq j\leq m}$ such that $a_i \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$, $\sigma_{i,j} \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$, and $B$ a standard $m$-dimensional Brownian motion. Furthermore, let $g \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d), r \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$ be such that $g$ is integrable and $r$ is positive. Define the non-anticipative functional $f \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$ by,
\begin{align*}
f(t, x) &= \mathbb{E}\left[e^{-\int_t^T r(s, X_{\wedge s})\,\mathrm{d}s} g(T,X_{\wedge T})|X_{\wedge t} = x_{\wedge t}\right].
\end{align*}
Then, if $f \in \mathfrak{C}^2([0, T], \mathbb{R}^d)$, its functional derivatives satisfy 
\begin{align}
\partial f(t, X_{\wedge t}) + \langle a(t, X_{\wedge t}), \tilde{\nabla}f(t, X_{\wedge t^-})\rangle - r(t, X_{\wedge t})f(t,X_{\wedge t})\nonumber &\\
+ \frac{1}{2}Tr(\tilde{\nabla}^2 f(t, X_{\wedge t}) \sigma(t, X_{\wedge t})\sigma(t, X_{\wedge t})^T) = 0&\,\,\text{a.s.}
\end{align} 
\begin{proof}
Let $h \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$ satisfy
\begin{align*}
h(t, X_{\wedge t}) = e^{-\int_0^t r(s, X_{\wedge s})\,\mathrm{d}s}f(t,X_{\wedge t}).
\end{align*}
By the tower property of conditional expectation,
\begin{align*}
h(t, X_{\wedge t}) = \mathbb{E}\!\left[e^{-\int_0^T r(s, X_{\wedge s})\,\mathrm{d}s}\,
g(T,X_{\wedge T})\,\Big|\,\mathcal{F}_t\right].
\end{align*}
Since $r$ is positive and $g$ is integrable, the terminal variable
$e^{-\int_0^T r\,\mathrm{d}s}\,g(T,X_{\wedge T})$ is integrable, so $h$
is a true martingale. On the other hand, a direct application of
Theorem~\ref{Coinvariant Ito} gives
\begin{align}
dh(t, X_{\wedge t}) = e^{-\int_0^t r(s, X_{\wedge s})\,\mathrm{d}s}
\Big( -r(t, X_{\wedge t})f(t,X_{\wedge t})+\partial f(t, X_{\wedge t})
+ \langle a(t, X_{\wedge t}),\tilde{\nabla}f(t, X_{\wedge t^-})\rangle
\nonumber &\\
+ \tilde{\nabla}f(t, X_{\wedge t^-})^T\sigma(t, X_{\wedge t^-})dB(t)
+ \frac{1}{2}Tr(\tilde{\nabla}^2 f(t, X_{\wedge t})
\sigma(t, X_{\wedge t})\sigma(t, X_{\wedge t})^T\Big)
\,\,\text{a.s.}&
\end{align}
By the uniqueness of the semimartingale decomposition, the drift terms
in \eqref{h-dynamics} must vanish. Canceling the exponential factor,
we arrive at \eqref{F-Kac}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:light:tails of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Let $\mathcal{X}=\mathbb{R}^d$ and $\mathcal{Y}\subseteq\mathbb{R}^d$ be an open (connected, possibly unbounded) domain of $\mathbb{R}^d$ endowed with the Euclidean metric and assume that $\rho$ has light tails in the following sense: there exist $C,\delta>0$, $R\geq0$, $L\geq 0$ such that
\begin{equation}
\nabla^2U_\rho(x)\succeq\begin{cases}
    C\,|x|^{\delta}\quad&\text{ for }|x|>R\,,\\
    -L\quad&\text{ for }|x|\leq R\,.
\end{cases} 
\end{equation}
Further assume that $\nu$ satisfies (eq:TI of the paper). Then we distinguish two cases.
\begin{enumerate}[label=(\roman*)] 
     \item If $c(\cdot,\cdot)$ satisfies
    \begin{equation}
 \nabla_1^2c(x,y),\nabla^2_2c(x,y)\succeq h(c)\quad\text{ and }\quad\norm{\nabla_{1}\nabla_{2} c(x,y)}_2\vee\norm{\nabla_{1}^2c(x,y)}_2\leqH(c)\, 
\end{equation}
uniformly in $x\in\mathbb{R}^d$ and $y\in\mathcal{Y}$, for some constants $h(c),\,H(c) \in \mathbb{R}$, then Sinkhorn's algorithm converges exponentially fast and for $\varepsilon$ small enough (as in (equation esp:small:light:tails:del:not:0 of the paper)) the rate is  
\begin{equation*}
1-\frac{\varepsilon^{2+\nicefrac2\delta}}{\varepsilon^{2+\nicefrac2\delta}+\varepsilon^{1+\nicefrac2\delta}\tau\delta_H+2\tauH(c)^2\,(\varepsilon^{\nicefrac2\delta}+(L+2)^2\,C^{-\nicefrac2\delta}(\varepsilon+2\delta_H)^{\nicefrac2\delta})}
\end{equation*}
    where $\delta_H\coloneqq H(c)-h(c)$.
     \item  When $\mathcal{X}=\mathcal{Y}=\mathbb{R}^d$ and $c(x,y)\coloneqq \langle x-y,\,\Sigma (x-y)\rangle/2$ is the (anisotropic) quadratic cost, Sinkhorn's algorithm converges exponentially fast and for $\varepsilon$ small enough (as in (equation esp:small:light:tails:del=0:Sigma of the paper)) the rate is
    \begin{equation*}
1-\frac{\varepsilon^2}{\varepsilon^2+2\,\tau\,\|\Sigma\|_2^2\,\Bigl(1+(L+1)^2\bigl[R^2\vee {C^{-\nicefrac2\delta}}\bigr]\Bigr)}\,.
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:stabAction of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] Let $\varphi \in C^{\infty}(\Lambda_{L})$ and $p \geq 1$.  
The following uniform bound holds:
\begin{align}
\sup_{N \in \mathbb{N}, \epsilon>0 }\bigg \|\int_{\Lambda_{L}}\frac{1}{N}: \|Z_{\epsilon}(x)\|^{4}_{\mathbb{R}^{N}}:_{m} \varphi(x) dx \bigg \|_{L^{p}(d\mu_{m,L}^{\otimes N})} &\lesssim \|\varphi\|_{L^{2}(\Lambda_{L}) }  m^{-1} (p-1)^{2}.

\end{align}
Furthermore, for any  $\epsilon, \kappa>0$ and $\delta< \frac{1}{2}$ it holds
\begin{align}
&\bigg \|\int_{\Lambda_{L}}\frac{1}{N} \big (: \|Z_{\epsilon}(x)\|^{4}_{\mathbb{R}^{N}}:_{m}-:\|Z_{\kappa}(x)\|^{4}_{\mathbb{R}^{N}}:_{m} \big ) \varphi(x) dx \bigg \|_{L^{p}(d\mu_{m,L}^{\otimes N})} \nonumber \\
&\qquad\qquad \lesssim \|\varphi\|_{L^{2}(\Lambda_{L}) } |\epsilon-\kappa|^{\delta} m^{-(1+\delta) }(p-1)^{2}.
\end{align}

