Here $ \Nn $ and $ \dRyyRNN $ are as in \As{A2}\,\thetag{iii} and (equation :2!z of the paper), respectively.

[Definition d:dir-space of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] We call $(X,d,\mu, \mathcal{E}_p, \mathcal{F}_p, \Gamma_p)$ a local $p$-Dirichlet space if the following hold:
		\begin{enumerate}  
			\item \textbf{Locally compact space}: $(X,d,\mu)$ is a locally compact metric space equipped with a Radon measure $\mu$.
			\item \textbf{Completeness:} 	The space $\mathcal{F}_p$  is a subspace of $L^p(X,\mu)$ and
			$\mathcal{E}_p: \mathcal{F}_p \to [0,\infty)$ is a non-negative function such that $\mathcal{F}_p$ is a Banach space when equipped with the norm $\norm{f}_{\mathcal{F}_p}=(\norm{f}_{L^p}^p+\mathcal{E}_p(f))^{1/p}$.
			\item \textbf{Homogeneity:} For all $f\in \mathcal{F}_p$ there exists a finite non-negative Borel measure $\Gamma_p \langle f \rangle$ on $X$ such that $\Gamma_p \langle f \rangle(X)= \mathcal{E}_p(f)$   and for all $\lambda \in \mathbb{R}$
			\[
			\Gamma_p\langle \lambda f\rangle = |\lambda|^p \Gamma_p\langle f\rangle.
			\]
			\item \textbf{Sublinearity:} For every $f,g\in \mathcal{F}_p$ and every Borel set $A\subset X$, 
			\begin{equation} 
				\Gamma_p\langle f+g\rangle(A)^{\frac{1}{p}}\le \Gamma_p\langle f\rangle(A)^{\frac{1}{p}}+\Gamma_p\langle g\rangle(A)^{\frac{1}{p}}
			\end{equation}
			\item \textbf{Chain rule:} For all $f\in \mathcal{F}_p$, $g\in \Lip(\mathbb{R})$ with $g(0)=0$,  we have $g \circ f \in \mathcal{F}_p$ and
			\begin{equation} 
				d\Gamma_p\langle g\circ f\rangle \le \LIP[g]^p d\Gamma_p\langle f\rangle.
			\end{equation}
			\item \textbf{Locality:} For every $f\in \mathcal{F}_p$ and open set $A\subset X$, if $f|_A=c$ $\mu$-a.e., then $\Gamma_p\langle f\rangle(A)=0$. 
			\item \textbf{Weak lower semicontinuity:} For every $f\in L^p(X)$, and for any sequence of functions $(f_i)_{i \in \mathbb{N}}$ in $\mathcal{F}_p$ such that $f_i\to f \in L^p(X)$ with $\sup_{i\in \mathbb{N}} \mathcal{E}_p(f_i)<\infty$, then $f\in \mathcal{F}_p$ and
			\begin{equation} 
				\Gamma_p\langle f \rangle(A)\le \liminf_{i\to \infty} \Gamma_p\langle f_i \rangle(A)
			\end{equation}
			for every Borel set $A\subset X$. 
		\end{enumerate}

[Cor box-product-bifun of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] For any compact Lie group $G$, the functor
    \begin{equation}
        {-}\boxtimes{-}\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Top}\times\cat{$\bm G$-$\textbf{\textup{L}}$-Top}\to\cat{$\bm G$-$\textbf{\textup{L}}$-Top}
    \end{equation}
    is homotopical and a left Quillen bifunctor.
    \begin{proof}
        We may factor $((eq:box-product-single-G of the paper))$ as
        \[
            \cat{$\bm G$-$\textbf{\textup{L}}$-Top}\times\cat{$\bm G$-$\textbf{\textup{L}}$-Top}\xrightarrow{\;{-}\boxtimes{-}\;}\cat{$\bm{(G\times G)}$-$\textbf{\textup{L}}$-Top}\xrightarrow{\;\Delta^*\;}\cat{$\bm G$-$\textbf{\textup{L}}$-Top},
        \]
        where $\Delta=(\textup{id},\textup{id})\colon G\to G\times G$ is the diagonal embedding. The first functor is a homotopical left Quillen bifunctor by the previous lemma, while the second one is homotopical and left Quillen by Lemmas~(lemma:restr-right-Quillen of the paper) and~(lemma:restr-inj-left-Quillen of the paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 (Growth of the Fourier coefficients for $0<\gamma<1$) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $\gamma\in(0,1)$, let $\varrho_{\varepsilon,0}$ be the initial density from \cref{eq:initialcond} with $\delta(\varepsilon)=\varepsilon^{\frac{1-\gamma}{1+\gamma}}$, let $\psi_{k,\varepsilon}$ be the $k$-th non-constant eigenfunction of $-\mathcal{L}_\varepsilon$ with eigenvalue $\lambda_{k,\varepsilon}=\lambda_k\varepsilon^{\frac{\gamma-1}{1+\gamma}}$, and let $N$ be as in \cref{lem:general-shape}.
	With the notation introduced after \cref{lem:general-shape}, define for $0\leq d\leq N-1$ and $d+1\leq j\leq N$
	\begin{equation}
		\alpha_{j,d}:=(2j-d-1)\gamma+d.
	\end{equation}
	Assume first that $x_0\neq 0$. In the non-resonant case, that is when $N>\frac{1+\gamma}{2\gamma}$, for all sufficiently small $\varepsilon>0$ one has
	\begin{equation*}
		\int \varrho_{\varepsilon,0}(x)\psi_{k,\varepsilon}(x)\,\dx
		\approx
		\exp\Bigg(\sum_{d=0}^{N-1}\sum_{j=d+1}^{N}
		\lambda_k^{\,j-d}\,\hat A_{j,j-d}(\gamma)\,
		\varepsilon^{\frac{\alpha_{j,d}-1}{1+\gamma}}
		|x_0|^{\,1-\alpha_{j,d}}
		\Bigg),
	\end{equation*}
	where the implied comparability constants are independent of $\varepsilon$. In the resonant case $N = \frac{1+\gamma}{2\gamma}$, the same asymptotic holds except that the term corresponding to $(j,d)=(N,0)$ is replaced by 
	\[
		\lambda_k^N A_{N,N}(\gamma)\left(\log|x_0| - \frac{1}{1+\gamma}\log\varepsilon\right).
	\]

	If $x_0=0$ and $\psi_k(0)=0$, then the Fourier coefficient vanishes. If $x_0=0$ and $\psi_k(0)\neq0$, then in the non-resonant case $N>\frac{1+\gamma}{2\gamma}$ one has
	\begin{equation}
		\left\lvert \int \varrho_{\varepsilon,0}(x)\psi_{k,\varepsilon}(x)\,\dx\right\rvert
		\approx
		\varepsilon^{\frac{\gamma(1-\gamma)}{1+\gamma}}
		\exp\!\Bigg(
		\sum_{d=0}^{N-1}\sum_{j=d+1}^{N}
		\lambda_k^{\,j-d}\,\hat A_{j,j-d}(\gamma)\,
		\varepsilon^{\frac{\gamma(\alpha_{j,d}-1)}{1+\gamma}}
		\Bigg).
	\end{equation}
	In the resonant case $N=\frac{1+\gamma}{2\gamma}$, the same asymptotic holds except that the term corresponding to $(j,d)=(N,0)$ is replaced by $-\lambda_k^{N}A_{N,N}(\gamma)\,\frac{\gamma}{1+\gamma}\log\varepsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 15 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that $X=(X_t)_{t\in[0,T]}$ satisfies Assumption \ref{a1} (i). Let $0\leq \alpha < d$ and $0\leq \beta \leq 1$ be such that \eqref{eq:key-restriction} holds, and let $\zeta$ be as in  Proposition \ref{prop:moment-bounds}.
		\begin{enumerate}	
			\item[(i)]  There are positive constants $c_{10}$ and $c_{11}$ such that for any $x \in \rd$, any subinterval $I\subset [0,T]$ and any $u>0$ we have
			\begin{equation}

				\mathbb{P}\Big(L^{\alpha,X}(x,I)\geq \lvert I\rvert ^{1-H(d-\alpha)}[\log(e+|I|)]^{2d\zeta} u^{H(\theta+d-\alpha)}\Big) \leq c_{10}\exp(-c_{11}u),
			\end{equation}
			and this remains true if $x$ is replaced by $x+X_\tau$ with $\tau\in I$.

			\item[(ii)] There are positive constants $c_{10}$ and $c_{11}$ such that for any $x,y \in \rd$, any subinterval $I\subset [0,T]$ and any $u>0$ we have
			\begin{multline}

				\mathbb{P}\Big(\lvert L^{\alpha,X}(x,I)-L^{\alpha,X}(y,I)\rvert \geq  \lvert I\rvert ^{1-H(d-\alpha+\beta)}[\log(e+|I|)]^{2d\zeta} \lvert x-y\rvert ^{\beta} u^{H(\theta+d-\alpha+\beta)}\Big)\\
				\leq c_{10}\exp(-c_{11}u),
			\end{multline}
			and this remains true if $x$ and $y$ are replaced by $x+X_\tau$ respectively $y+X_\tau$ with $\tau\in I$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.29131, '2606.29131'] Suppose that Assumption {\rm\ref{a1-1}}{\rm(i)} and Assumption {\rm\ref{a1-2}} hold, and
that there exists $\beta>0$ such that
\begin{equation}
\lim_{\e \to 0}\xi_{1,\beta}(\e)=0,
\end{equation}
where $\xi_{1,\beta}(\e)$ is defined by \eqref{e1-8a}. Fix this $\beta$.
For any $n\ge1$, let $v_n^\e$ be defined by \eqref{e2-14a} above with $h\in \M_{\beta}$. Then, for any $n\ge1$, there exists a constant $C_0(n)>0$ such that for all $\e>0$,
\begin{equation}
\begin{split}
\|v_{n}^\e\|_{L^2(\R^d;dx)}\le
C_0(n)\left(\xi_{1,\beta_0}(\e)+\xi_{2,\beta_0}(\e)\right)^n,
\end{split}
\end{equation}
where $\beta_0:=\min\{\alpha,\beta\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

