[Definition 27 of arXiv:2506.09609, 'Schramm-Loewner evolution contains a topological Sierpi\'nski carpet when $\kappa$ is clos'] Given any vertex set $\{\mathcal{A}_m\}_{m \geq 0}$ satisfying Conditions~\ref{condition:fractal-1} and~\ref{condition:fractal-2}, let 
    \begin{equation}
        \mathcal{S}_0:= \{ B(x, 1) : x \in \mathbb{Z}^2\} \quad \mbox{and} \quad \mathcal{S}_m := \{ B(x , 10 \varrho N^{m-1}) : x \in \mathcal{A}_{m-1} \} \quad \mbox{for } m \geq 1.
    \end{equation}
    We consider \textbf{self-avoiding} paths $P=(x_1,x_2,\ldots,x_L)$ where each $x_i$ takes values in $\cup_{m=0}^\infty \mathcal{S}_m$. By self-avoiding we mean that $x_i \neq x_j$ for any $i \neq j$. The length of $P$ is denoted by ${\rm len}(P)=L$. The diameter of $P$ is referred to as the $|\cdot|_\infty$-diameter of $\cup_{i=1}^L x_i$ viewed as a subset of $\mathbb C$. We say that $P$ is \textbf{connected} if $d(x_i, x_{i+1}) \leq 40 \varrho$ for $1 \leq i \leq L-1$.

    For $k \geq 0$, we say that a self-avoiding connected path is at level $k$ if it consists only of boxes of the form $\cup_{m=0}^k \mathcal{S}_m$. In particular, a self-avoiding connected path at level $0$ consists only of boxes of the form $B(x,1)$.

[Lemma 15 of arXiv:2603.28226, '2603.28226'] Assume that $(\mathcal F_n)_{n\ge1}$ is an $\alpha$-regular atomic filtration. Fix $N\ge1$ and an atom $A\in\mathcal A_N$. Let $g\in L^1(\mathcal F_\infty)$ and $\lambda>0$. If
\begin{equation}

 \frac{1}{\mathbb P(A)}\,\mathbb E[|g| \, \mathbf1_A]\le \lambda,
\end{equation}
then there exists a finite or countable collection of pairwise disjoint atoms $\{A_j\}_{j\in J}$ contained in $A$ such that

\smallskip
\noindent\textup{(i)}
\begin{equation}

 \lambda<\frac{1}{\mathbb P(A_j)}\,\mathbb E[|g| \, \mathbf1_{A_j}]\le \alpha^{-1}\lambda,
 \qquad j\in J;
\end{equation}

\noindent\textup{(ii)}
\begin{equation}

 |g(\omega)|\le \lambda
 \qquad\text{for a.e. }\omega\in A\setminus\bigcup_{j\in J}A_j;
\end{equation}

\noindent\textup{(iii)}
\begin{equation}

 \sum_{j\in J}\mathbb P(A_j)
 \le \frac1{\lambda}\,\mathbb E[|g|\, \mathbf1_A].
\end{equation}

[Theorem gumbel_convergence_result of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Let $\epsilon > 0$ and choose $J$ such that it does not contain any cross terms, \emph{i.e., } \begin{equation*}
	J \subset \{(\alpha, i, i) : 1 \leq i \leq N,  1 \le \alpha \le \floor{N^{\epsilon/10}}\},
	\end{equation*} and let, \begin{equation*}
	 b_n = 2 \log n - \log \log n - \log \pi, \quad n \in \mathbb{N}.
	\end{equation*}
	Then there exists a $\delta > 0$ such that for $\epsilon < \delta$, the largest entry of $E_J$ converges in law to a Gumbel distribution, \begin{equation}
	\lim_{N \to \infty }\Prob\left(\frac{\max_{(\alpha,i,i) \in J} N |\inner{u_{\alpha},q_i}|^2 - b_{\#_{J}}}{2} \leq x\right) = \mathrm{e}^{-\mathrm{e}^{-x}}, \quad \forall x \in {\mathbb R}.

	\end{equation} 
	Furthermore, the point process of the rescaled entries of $E_J$ converges to the Poisson process with intensity measure $\mathrm{e}^{-x} \mathop{}\!{d} x$, \emph{i.e., } for all non-negative continuous functions $g : {\mathbb R} \to {\mathbb R}$ with compact support we have, \begin{equation}
		\lim_{N \to \infty } \EX\Bigg[\exp \Big(- \sum_{(\alpha, i, i) \in J} g\Big(\frac{1}{2}(N |\inner{u_{\alpha}, q_i}|^2 - b_{\#_{J}})\Big) \Big)\Bigg] = \exp \Big(- \int_{{\mathbb R}} \big(1 - \mathrm{e}^{-g(x)}\big) \mathrm{e}^{-x} \mathop{}\!{d} x \Big).

	\end{equation} 
	Finally, let $F_{\chi^2(1)}$ and $f_{\chi^2(1)}$ denote the cdf and pdf of the $\chi^2(1)$ distribution, and let $\Phi$ denote the cdf of a standard Gaussian. For $k = k(N) \leq N^{\epsilon/2}$, satisfying $k \to \infty$ and $k / \#_{J} \to 0$ as $N \to \infty$, we have with, \begin{equation*}
		d_{\#_J} := F_{\chi^2(1)}^{-1}\left(1 - \frac{k}{\#_J}\right), \quad c_{\#_J} := \frac{\sqrt{k}}{\#_J f_{\chi^2(1)}(d_{\#_J})},
	\end{equation*} that,
	\begin{equation}
		\lim_{N \to \infty} \Prob \left( \frac{(N|\inner{u_{\alpha}, q_i}|^2)_{(k)} - d_{\#_J}}{c_{\#_J}} \leq x \right) = \Phi(x), \quad \forall x \in {\mathbb R}.

	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 37 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] There exists a constant $C_7=C_7(\alpha,\iota)$ such that for all parameters $\hw,\hv,(\hx_1,\ldots,\hx_{r'})$ satisfying \eqref{e:reduced-normalization}, we have
    \[
        \max\bigg\{
            \gamma_\star, \frac{1}{\alpha - \hv_1 m(z_\star)}
        \bigg\} \le C_7\,,
    \]
for $z_\star$ as defined by \eqref{e:fp.z.star} and $\gamma_\star$ as defined by Lemma~\ref{l:fp-vii-estimate-prep}.

\begin{proof} Recall the sets $J_+,J_- \subseteq [r]$ defined in \eqref{e:Jplus}, \eqref{e:Jminus}, which index the positive and negative entries of $\hv$. Let $\gamma_+(z)$ denote the contribution to \eqref{e:fp.gamma.function} from indices $j\in J_+$, and denote similarly $\gamma_-(z)$. Then, for any $z>\hw_1$, we have 
    \beq
    \gamma_-(z)
    = \alpha \sum_{j\in J_-}
            \lambda_j \bigg(
            \frac{\hv_j}{\alpha - \hv_j m(z)}
        \bigg)^2
        \le \alpha 
        \sum_{j\in J_-}
            \lambda_j
    \bigg(
            \frac{\hv_j}{\alpha}
        \bigg)^2
        \stackrel{\eqref{e:reduced-normalization}}{\le} \frac{4}{\alpha\iota^2}\,.
    \eeq
If $J_+ = \emptyset$, this upper bounds $\gamma(z)=\gamma_-(z)$ for any $z>\hw_1$. 
    In this case, we also have \[
    \frac1{\alpha - \hv_1 m(z)} \le \frac1\alpha\,,\]
for any $z>\hw_1$, so the result follows. 

Otherwise, assume $J_+ \neq \emptyset$, so $\hv_1 > 0$. By Lemma~\ref{l:fp-zmin-equal-z0}, this implies $z_{\min} > z_0$. Recall that \eqref{e:fp-uniform-bound-Jminus-contribution} above already bounds $\gamma_-(z)$ for all $z>\hw_1$. Meanwhile, both $m(z)$ and $\gamma_+(z)$ are strictly decreasing on the interval $z \in (z_0,+\infty)$. Since $z_\star \ge z_{\min} > z_0$ and $\gamma(z_\star) = \gamma_\star$, it suffices to show 
\beq

        \max\bigg\{
        \gamma_+(z_{\min})
        \le \gamma(z_{\min}),
            \frac{1}{\alpha - \hv_1 m(z_{\min})}
        \bigg\} \le C_7\,.
    \eeq
We divide the analysis into two cases:
    \begin{itemize}
        \item If $m(z_{\min}) \le \alpha / (2\hv_1)$, then 
        \begin{align*}
    \gamma_+(z_{\min})\
    &=
            \alpha \sum_{j\in J_+} \lambda_j \bigg(
            \frac{\hv_j}
            {\alpha - \hv_j m(z_{\min})}
            \bigg)^2\\
            &\le \alpha \bigg(
                \frac{\hv_1}{\alpha - \hv_1 m(z_{\min})}
            \bigg)^2 
            \le \frac{4(\hv_1)^2}{\alpha}
            \stackrel{\eqref{e:reduced-normalization}}{\le}
            \frac{16}{\alpha \iota^2}\,,\\
       \frac{1}{\alpha - \hv_1 m(z_{\min})}
           &\le \frac{2}{\alpha}\,.
        \end{align*}

        \item If $m(z_{\min}) > \alpha / (2\hv_1)$, then Lemma~\ref{l:fp-m-fns-conversion} gives
        \[
            m_2(z_{\min}) >
            m_2\bigg(m^{-1}\bigg(\frac{\alpha}{2\hv_1}\bigg)\bigg)
            \ge \frac{\alpha^2 \iota }{4(\hv_1)^2}\,.
        \]
        Since $\hv_1 > 0$, it follows from Lemma~\ref{l:fp-zmin-equal-z0} that $V'(z_{\min}) = 0$.
        Recalling the formula for $V'$ from \eqref{e:fp-V-pr}, this implies
        \[
        \frac{\alpha\lambda_1(\hv_1)^2}
            {(\alpha-\hv_1m(z_{\min}))^2}
        \le
        \gamma(z_{\min}) 
            = \frac{1}{m_2(z_{\min})}
            \le \frac{4(\hv_1)^2}{\alpha^2\iota}
            \stackrel{\eqref{e:reduced-normalization}}{\le}
            \frac{16}{\alpha^2\iota^3}\,.
        \]
Rearranging the above and recalling $(\lambda,\mu) \in \Lambda$ gives
        \[
            \frac{1}{\alpha - \hv_1 m(z_{\min})}
            \le \frac{2}{\alpha^{3/2}\iota}\,.
        \]
    \end{itemize}
In all cases, the conclusion follows.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 2 (We study these derivations) of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $K$ be a field of characteristic zero with a transcendental basis $x_1,x_2,\ldots, x_n$, where $n\in \mathbb{N}$, over a subfield $k$.

    We say that a derivation $D:K\to K$ over $k$ has \textbf{rational function coefficients that separate variables} if there exist non-zero rational functions in one variable $f_1,f_2,\ldots,f_n \in k(X)$ such that

    \begin{equation}
    D= f_1(x_1)\frac{\partial}{\partial x_1}+f_2(x_2)\frac{\partial}{\partial x_2}+\ldots+f_n(x_n)\frac{\partial}{\partial x_n}.
\end{equation}

[Lemma contraction of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Let $\lambda,\zeta$ satisfy Condition~(condition2 of the paper) and let $P=P_{\lambda,\zeta}$.
For $y,z \in \Omega_{\text{con}}$, we have
\begin{equation}
\frac{W_1(Py,Pz)}{\mathrm{dist}(y,z)} \leq 1-\frac{\xi}{n^2}.
\end{equation}

