[Theorem thm:3D-Coul-finite of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $d\in \{2,3\}, \beta^{ *}>0, b,\delta  $ such that $ (d + 2)\beta  + \delta <\frac{ 1}{d}$.   Let $ n\geqslant 1, R\in [1,n^{b }],\varepsilon _{ n} = R^{ -\delta },\beta _{n}\geqslant \beta ^{*}.$
Then   
\begin{align*}
  \sup_{ x \in B(0,\rho ^{-}_{n})}   \overline{  \textrm{Var}}^{ \varepsilon _{ n}}\left(\mathsf{P}_{ n}^{ d,\beta  }(B(x,R)\right)\leqslant C
  \begin{cases} 
  R $  if $d = 2\\
  R^{ 2}\ln(R) $  if $d = 3.
   \end{cases}\\
   \end{align*}
   where $C$ does not depend on $ R,n.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] a) For any $\varphi$ satisfying \eqref{e:critical}
 \begin{equation}
  \lim_{T\to \infty }\frac 1T I_R(T)=\frac 1{m_\varphi},

 \end{equation}
where $m_\varphi$ is given by \eqref{e:phi_x_integrable}, with the convention $\frac 1{\infty}=0$. In particular we always have
 \begin{equation}
\limsup_{T\to \infty} \frac 1T I_R(T)<\infty.
\end{equation}
b)  Under Assumption \ref{ass:beta_integrable} we have
\begin{equation}
\liminf_{T\to \infty} \frac 1{T^{(\beta+\delta)\wedge 1}} I_R(T)>0.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Let $(\rho_t^\mu)_{t\in[0, 1]}$ and $(\rho_t^\nu)_{t\in[0, 1]}$ be two density evolution curves over $\mb T^d$. 
Given time points $0 = t_0 < t_1 < \cdots < t_m = 1$, take $\bm\mu^m = (\rho^\mu_{t_0}, \cdots, \rho_{t_m}^\mu)$ and $\bm\nu^m = (\rho_{t_0}^\nu, \cdots, \rho_{t_m}^\nu)$ as marginal constraints.

Suppose that there exists $L_\rho\in(0, 1)$, such that
\begin{align*}
L_\rho \leq \rho_t^\mu(x), \rho_{t_j}^\nu(x) \leq L_\rho^{-1} \quad \hbox{uniformly for all $t\in[0, 1]$, $j\in\{0, 1, \cdots, m\}$, and $x\in\mb T^d$.}
\end{align*}

Let $R^{\bm\nu^m}$ and $R^{\bm\mu^m}$ be the multi-marginal Schr\"odinger bridges \eqref{eqn:SB-multi} connecting $\bm \nu^m$ and $\bm\mu^m$, respectively.
Under Assumption~\ref{assump: density_expansion} on $(\rho_t^\mu)_{t\in[0, 1]}$, 

we have 
\begin{align}
\KL(R^{\bm\nu^m}\,\|\,R^{\bm\mu^m})
\leq \KL(\rho_1^\nu\,\|\,\rho_1^\mu) + \frac{1}{2}\sum_{j=1}^m\int_{t_{j-1}}^{t_j}\!\int_{\mb T^d}\Big\|\nabla\bar \Phi_{t_{j-1}}^\mu - \nabla\bar\Phi_t^\nu - \frac{1}{2}\nabla\log\frac{\rho_{t_{j-1}}^\mu}{\bar\rho_t^\nu}\Big\|^2\,\dd \bar\rho_t^\nu\dd t + O\Big(\frac{1}{m}\Big),
\end{align}
where given any $\alpha\in(0, 1)$, the big-O notation omits a constant depending only on $d$, $\alpha$, $L_\rho$,  
\begin{align*}
\begin{cases}
\sum_{j=1}^m \varepsilon_j^{-1} \W_2^2(\rho_{t_{j-1}}^\nu, \rho_{t_j}^\nu),\,\,
\sup_{t\in[0,1]} \big\|\frac{\partial}{\partial t}\Phi_t^\mu\big\|_{\m C^2},\,\,
\sup_{t\in[0,1]}\|\Phi_t^\mu\|_{\m C^{4}},\,\mx{and}\\
\sup_{t\in[0, 1]}\big\{\|\rho_t^{(k)}\|_{\m C^{\max\{2+\lceil\frac{d+1}{2}\rceil, 12\}+k',\alpha}}: 2k+k'=14,\,\,k,k'\in\mb N\big\},\\
\end{cases}
\end{align*}
Also, $(\bar\rho_t^\mu)_{t\in[0, 1]}$ and $(\bar\rho_t^\nu)_{t\in[0, 1]}$ are the piecewise Wasserstein $\W_2$-geodesics connecting $\bm\mu^m$, $\bm\nu^m$, respectively, with velocity vector fields $\nabla\bar\Phi_t^\mu$, $\nabla\bar\Phi_t^\nu$, respectively, satisfying
\[
\partial_t\bar\rho_t^\mu + \nabla\cdot(\bar\rho_t^\mu\nabla\bar\Phi_t^\mu) = 0,  \qquad 
\partial_t\bar\rho_t^\nu + \nabla\cdot(\bar\rho_t^\nu\nabla\bar\Phi_t^\nu) = 0,\quad t\in[t_{j-1}, t_j] \hbox{ for each $j=1, ..., m$}.
\]
\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)

