body:
[Lemma 3 (Basic properties of \(W\)) of arXiv:2609.01436, '2609.01436'] The reduced kernel $W$ is a nonnegative Borel function on
$[0,\infty)^3$ and satisfies
\begin{equation}
 0\leq W(x,y,z)\leq W_H(x,y,z),
 \qquad (x,y,z)\in[0,\infty)^3.
\end{equation}
Moreover,
\begin{equation}
 W(x,y,z)=W(x,z,y),\qquad x,y,z\geq0.
\end{equation}

[Lemma lem:complex-pointwise of arXiv:2608.23742, 'Second-order fusion asymptotics for $\Sine_\beta$ correlation functions'] Let $\beta,\delta>0$ and $0<s\le2\delta$. There is a constant $C=C(\beta,\delta,s)$ such that, for every $N\ge1$ and every $z=x+iy\in\mathbb C$,
\begin{equation}
\mathbb E|f_N(z)|^s\le C e^{s|y|/2}.
\end{equation}
Moreover,
\begin{equation}
\mathbb E|\xi^{\beta,\delta}(z)|^s\le C e^{s|z|/2}.
\end{equation}
In particular, both expectations are uniformly bounded when $z$ ranges over a fixed compact set.

[Theorem 23 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] For every compact connected two-step pair $(G,L)$,
		\begin{equation}
			\beta_{G,L}
			=\frac{\operatorname{Scal}_G-\operatorname{Scal}_L}{6}
			=\frac1{12}\sum_{a,i}|[Y_a,X_i]|^2
			+\frac1{24}\sum_{i,j}|[X_i,X_j]|^2.
		\end{equation}
		In particular, $\beta_{G,L}\ge0$. For the tangent group $\mathbb N_{G,L}$ and its heat kernel $p_t^0$,
		\begin{equation}
			p_t^0(e)
			=\frac{t^{-Q/2}}{(4\pi)^{Q/2}}
			\int_{\lLie}\mathcal D_{G,L}(Y)\,\mathrm dY,
			\qquad
			C_{G,L}=\vol(G)p_1^0(e).
		\end{equation}
		Equivalently,
		\begin{align}
			C_L&=\frac{\vol(L)}{\vol(T)|\Wt_L|},
			\\
			\mathcal D_{G,L}(H)
			&=\prod_{\omega\in\Sigma_{\pLie}^+}
			w\bigl(\omega(H)\bigr)^{m_\omega},
			\qquad H\in\tLie,

		\end{align}
		and
		\begin{equation}
			C_{G,L}
			=\frac{\vol(G)\vol(L)}
			{(4\pi)^{Q/2}\vol(T)|\Wt_L|}
			\int_{\tLie}\Pi_L(H)^2
			\prod_{\omega\in\Sigma_{\pLie}^+}
			w\bigl(\omega(H)\bigr)^{m_\omega}\,\mathrm dH.
		\end{equation}
		The remaining Cartan integral has the integral-free expansion
		\begin{align}
			\int_{\tLie}\Pi_L(H)^2
			\prod_{j=1}^{N_{\mathrm{iso}}}
			w\bigl(\omega_j(H)\bigr)^{m_j}\,\mathrm dH
			&=\sum_{\mathcal C,\varsigma,\mu}
			\operatorname{vol}_{\tLie}
			(v_{\varsigma,1},\ldots,v_{\varsigma,r_T})
			p_{\mathcal C,\varsigma,\mu}
			\prod_{i=1}^{r_T}\mu_i!
			\notag\\
			&\qquad\quad\times
			\sum_{\mathbf n\in\mathbb N_0^{N_{\mathrm{iso}}}}
			\frac{\displaystyle
				\prod_{j=1}^{N_{\mathrm{iso}}}
				\binom{n_j+m_j-1}{m_j-1}}
			{\displaystyle
				\prod_{i=1}^{r_T}
				\bigl(A_{\mathcal C}(\mathbf n)
				(v_{\varsigma,i})\bigr)^{\mu_i+1}}.

		\end{align}
		All terms are nonnegative, and the multiple Dirichlet series converges absolutely.

