[Theorem 14 of arXiv:2609.03803, 'List-distance consistent vertices in trees are confined to a path'] Let $G=SP(w;1,\ell_2,\dots,\ell_k)$ with $k\ge4$ and $\ell_k\ge2$. If
\begin{equation}
\begin{aligned}
  &k=4 \ \text{ and either } \ \ell_2\le2 \ \text{ or } \ (\ell_2=3
     \text{ and } \ell_4\le4),\\
  \text{or }\quad
  &k=5 \ \text{ and either } \ \ell_3=1 \ \text{ or } \ \ell_5=2,\\
  \text{or }\quad
  &k\ge6, \ \ell_2=1 \ \text{ and } \ \ell_k=2,
\end{aligned}

\end{equation}
then $\ldc(G)=\lceil \ell_k/2\rceil+2$.

[Lemma mgf-bound-light-traffic of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Let $\{\lambda_n\}$ be a sequence of positive numbers such that $\lim_{n \rightarrow \infty} \frac{\lambda_n}{n} = c$. Let $n \geq \max\left\{n_0,\frac{4}{\br{1-c}^2\br{1-\frac{1}{2e}}^2}\right\}$ where $n_0$ is an integer such that $\frac{\lambda_n}{n} \leq \frac{1}{2e} \, \forall n \geq n_0$ and $\nu_n$ be the stationary distribution of the $M/M/n$ system with arrival rate $\lambda_n$ and unit service rate. We have
    \begin{align}
        \E_{\nu_n}\sqbr{e^{q-n}} \leq e^{-\frac{(1-c)n^{1-\alpha_n}}{2}} + 2n^{\alpha_n-1} + \frac{8n^{2\alpha_n-1}}{(1-c)e} \, \forall n \geq n_0.
    \end{align}
    Consequently, we have $\lim_{n \rightarrow \infty} \E_{\nu_n}\sqbr{e^{q-n}} = 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 54 of arXiv:2607.18104, '2607.18104'] Let $\varepsilon=\varepsilon(N,k):=N^{-3/2}\beta^{3/2}$ for $\beta=\beta(\alpha)$ from \eqref{def:betaASEP}. Moreover, define for all $N$ and $k$ the parameters $\rho=k/N$, and $\alpha=1-2\rho$.
For a given family of $(N,k)$-periodic Bernoulli paths $h^{\per,\varepsilon}_0 \colon \Z \rightarrow \Z$, define the \textbf{rescaled periodic ASEP height function} as the mapping $(y,t) \mapsto \hApeps(\hfix^{\per,\varepsilon}_0;y,t)$ by
\begin{align*}
\hApeps(\hfix^{\per,\varepsilon}_0;y,t) := \sigma(\alpha)^{-1}\varepsilon^{\frac{1}{3}}&\Big(2\mu(\alpha)\varepsilon^{-1}t +\mu^{\prime}(\alpha)\beta(\alpha)y\varepsilon^{-\frac{2}{3}} \\
&- h^{\pASEP}(h^{\per,\varepsilon}_0,0;2\alpha t \varepsilon^{-1} + \beta(\alpha)y\varepsilon^{-\frac{2}{3}},2(1-q)^{-1}\varepsilon^{-1}t) \Big) 
\end{align*} whenever the argument for $h^{\pASEP}$ is an integer, and linear interpolation otherwise. Here, as for \eqref{def:RescaledASEPheight}, we obtain $\hfix^{\per,\varepsilon}_0$ from $h^{\per,\varepsilon}_0$ by the rescaling
\begin{equation}
    \hfix^{\per,\varepsilon}_0(x) := \sigma(\alpha)^{-1}\varepsilon^{\frac{1}{3}}\Big(\mu^{\prime}(\alpha)\beta(\alpha)x\varepsilon^{-\frac{2}{3}} - h^{\per,\varepsilon}_0(\beta(\alpha)x\varepsilon^{-\frac{2}{3}}) \Big).
\end{equation}

[Corollary cor: sup_gauss_int of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Suppose that $f:\boldsymbol{W}\to {\mathbb R}$ is a  continuous  function that is  homogeneous of degree $k\geq  1$. Suppose that  $A,B\in \Sym_{\geq 0}(\boldsymbol{W})$ and $B\leq A$. Then
\begin{equation} 
\big\vert\, {\EuScript{I}}_B(f)\,\big\vert\leq {\EuScript{I}}_B(|f|)\leq  C(m,k)M(f)\Vert A\Vert^{k/2}_{\mathrm{op}}
\end{equation}

[Theorem thmpmf of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The state probabilities of IGCP are given by
\begin{equation}
\hat{p}(n,t)=\sum_{\Omega(k,n)}\Big(\prod_{j=1}^{k}\frac{\lambda_{j}^{n_{j}}}{n_{j}!}\Big)\sum_{\sum_{j_0=1}^{k_0}r_{j_0}=z_{k}}z_{k}!\prod_{j_0=1}^{k_0}\frac{j_0^{r_{j_0}}}{r_{j_0}!}e^{-\mu_{j_0}t(1-e^{-j_0\lambda})}\mathcal{B}_{r_{j_0}}(e^{-j_0\lambda}\mu_{j_0}t),\ n\ge0,
\end{equation}
where $\mathcal{B}_n(x)$ is the $n$th order Bell polynomial defined in (equation bell of the paper).

