[Lemma 6 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] There exist constants \( 0<c_{1}<c_{2}< \) \( \infty \) such that for any \( i \in \S \) and \( 0 \leq  u<t \),
		\begin{equation}
			c_{1} \mathrm{e}^{-\zeta(t-u)} \leq \mathbb{E}_{\mathbb{P}_2}\left[\exp \left(\int_{u}^{t} f\left(\Lambda^{i}(v)\right) \mathrm{d} v\right)\right] \leq c_{2} \mathrm{e}^{-\zeta(t-u)},
		\end{equation}
		where $\mathbb{E}_{\mathbb{P}_2}$ denotes the expectation with respect to $\mathbb{P}_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop eigenfunction of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] [Op]
Fix $\beta>0$, $N\in \mathbb{Z}_{\ge 1}$. For any $k=1,2,\ldots$, 
\begin{equation}
    p_{k}(\mathcal{D}_{1},\ldots,\mathcal{D}_{N})B_{(a_{1},\ldots,a_{N};\beta)}(x_{1},\ldots,x_{N})=p_{k}(a_{1},\ldots,a_{N})B_{(a_{1},\ldots,a_{N})}(x_{1},\ldots,x_{N};\beta).
\end{equation}
Here we evaluate the polynomial $p_k$ on the operators $\mathcal{D}_1, \dots, \mathcal{D}_N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def-Dmut of arXiv:2506.10448, 'Hitting probabilities and the Ekstr\"om--Persson conjecture'] Let $\mu \in \mathcal{P}(\mathbb{R}^d)$. For every $t\geq 0$, let 
\begin{equation}

D_\mu(t):= \{ x \in \spt \mu\mid \dimlocl \mu (x)\leq t \}.
\end{equation}
The lower Hausdorff and packing multifractal spectra of the lower local dimension of $\mu$  
are defined by 
\begin{align*}
F_{\mu}(t)& := \dimh D_\mu(t),\\
H_{\mu}(t)& :=\dimp D_\mu(t),
\end{align*}
where $\dimh$ and $\dimp$ stand for the Hausdorff and packing dimensions, respectively.

[Cor DoubIntCond of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Under the assumption of Theorem (thm:DoubInt of the paper), one has
\begin{equation}
\int_{0<s<t<1}\big(e^{2\pi i(px_{s}+qx_{t})}-e^{2\pi i(px_{t}+qx_{s})}\big)dy_{s}dy_{t}=0
\end{equation}
for all $p,q\in\mathbb{Z}\backslash\{0\}$ with $p+q\neq 0.$

[Lemma lem:branching_formulas of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] (Branching rule) For $\lambda=(\lambda_1,\ldots,\lambda_n)\in \Sig_n^+, \mu=(\mu_1,\ldots,\mu_{n-1}) \in \Sig_{n-1}^+$ with $\mu \prec_P \lambda$, let
\begin{equation}
    \psi_{\lambda/\mu}(t):= \prod_{\substack{i \in \mathbb{Z} \\ m_i(\mu) = m_i(\lambda)+1}} (1-t^{m_i(\mu)}).
\end{equation}
For $\nu \in \Sig_n^+$ with $\nu \prec_Q \lambda$, let
\begin{equation}\varphi_{\lambda/\nu}(t)=\prod_{\substack{i \in \mathbb{Z} \\ m_i(\lambda) = m_i(\nu)+1}} (1-t^{m_i(\lambda)})\end{equation}
Then for $\lambda,\nu\in\Sig_n^+,\mu\in\Sig_{n-k}^+$, we have
\begin{equation}
P_{\lambda/\mu}(x_1,\ldots,x_k;t)=\sum_{\mu = \lambda^{(0)} \prec_P \lambda^{(1)} \prec_P \cdots \prec_P \lambda^{(k)}= \lambda} \prod_{i=1}^k x_i^{|\lambda^{(i)}|-|\lambda^{(i-1)}|}\psi_{\lambda^{(i)}/\lambda^{(i-1)}}(t).
\end{equation} 
and
\begin{equation}
 Q_{\lambda/\nu}(x_1,\ldots,x_k;t) = \sum_{\nu = \lambda^{(0)} \prec_Q \lambda^{(1)} \prec_Q \cdots \prec_Q \lambda^{(k)}=\lambda} \prod_{i=1}^{k} x_i^{|\lambda^{(i)}|-|\lambda^{(i-1)}|}\varphi_{\lambda^{(i)}/\lambda^{(i-1)}}(t).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_a_t/a_est of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] We have
\begin{equation}
        \norm{\frac{a_t}{a}\circ\kappa^{-1}A}_{H^s}\lesssim\frac{\epsilon^2}{t^{1-\delta_0}}\ln (2+t)+\frac{\lambda\epsilon}{H^{\frac{3}{2}}t^{\frac{1}{2}}}+\frac{\lambda}{H^{\frac{5}{2}}},
    \end{equation}
    \begin{equation}
        \norm{\frac{a_t}{a}\circ\kappa^{-1}A}_{W^{s-3,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{3}{2}-\delta_0}}(\ln (2+t))^2+\frac{\lambda\epsilon}{H^2t^{\frac{1}{2}}}+\frac{\lambda}{H^3}
    \end{equation}
and

    \begin{equation}
        \norm{\frac{a_t}{a}\circ\kappa^{-1}A}_{W^{s-1,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{7}{6}-\delta_0}}(\ln (2+t))^2+\frac{\lambda\epsilon}{H^2t^{\frac{1}{2}}}+\frac{\lambda}{H^3}.
    \end{equation}

