[Theorem 66 (Deterministic matching lower bound and non-Cauchy criterion) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $1\le p,r<\infty$ and $q\ge0$.  For $q\ge1$, let
$(H_i)_{i\in I_0}$ be a finite family of symmetric algebraic order-$q$
kernels realized over one fixed isonormal process; at $q=0$, let them be
deterministic Schatten blocks.  Assume their
external input and output supports form a matching.  Then
\begin{equation}

 \left(\sum_{i\in I_0}
  \underline{\Prof}_{q,r}(H_i)^r\right)^{1/r}
 \le
 \left(\sum_{i\in I_0}
  \norm{I_q(H_i)}_{L^2(\Omega;\Sch_r)}^r\right)^{1/r}
 \le C_{q,p,r}
 \norm{\sum_{i\in I_0}I_q(H_i)}_{L^p(\Omega;\Sch_r)},
\end{equation}
where $C_{0,p,r}=1$.  More generally, if $X$ is a global $\Sch_r$-valued
random operator in the closed $q$th chaos and $(P_i,Q_i)_{i\in I_0}$ is a
finite matching compression, then
\begin{equation}

 \left(\sum_{i\in I_0}
  \norm{P_iXQ_i}_{L^2(\Omega;\Sch_r)}^r\right)^{1/r}
 \le C_{q,p,r}\norm X_{L^p(\Omega;\Sch_r)}.
\end{equation}
If the compressed blocks admit algebraic kernels $H_i$, the corresponding
lower-profile term from \eqref{eq:matching-lower-obstruction} may also be
included.  Applied to cutoff differences, the estimate gives a non-Cauchy
criterion in $L^p(\Omega;\Sch_r)$.

[Lemma 7 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let $m\ge k$ and $\textbf{i}=(i_0,\dots, i_{m-1})\in \{0,1\}^m$ where ~$i_0+\dots +i_{m-1}=k$. Then
\begin{equation*}
\begin{split}
        & \mathbb{P}(N_T=m,\,   (I_0,\dots, I_{m-1})= \textbf{i} \mid N_T\ge k)  = \mathbb{Q}(\tilde{N}_T  = m, \, (J_0(Y),\dots, J_{m-1}(Y))= \textbf{i}\mid K=k).
\end{split}
\end{equation*}
Moreover,
\begin{equation}
 \mu_k(\mathrm{d}y):=\mathbb{Q}(Y\in \mathrm{d}y \mid K=k) = \frac{k\delta_T y^{k-1}}{(1-(1-\delta_T)(1-y))^{k+1}}\mathrm{d}y, \qquad y\in (0,1),  
\end{equation}
where 
$\delta_T:=\mathbb{P}(H> T)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 1 of arXiv:2608.30796, 'Tumor boundary instability induced by pressure feedback'] For fixed \(\lambda>0\) and \(\gamma>0\), the translation
mode is neutral:
\begin{equation}

\mathcal{F}_1(R;\lambda,\gamma)=0
\qquad\text{for every }R>0.
\end{equation}
For each integer \(l\geq2\),
\begin{subequations}

\begin{align}
\lim_{R\to0^+}\mathcal{F}_l(R;\lambda,\gamma)
&=\frac{1-l}{2}<0,
\\
\mathcal{F}_l(R;\lambda,\gamma)
&=
\frac{l^2-1}
{2(\sqrt{\lambda}+1)(\sqrt{\lambda}+\sqrt{\gamma})R^2}
+O(R^{-3})
\qquad\text{as }R\to+\infty.
\end{align}
\end{subequations}
For fixed \(R>0\), the high-frequency behavior is
\begin{equation}

\mathcal{F}_l(R;\lambda,\gamma)
=
\frac{\partial_rp_0(R)}{R}\,l+O(1)
\qquad\text{as }l\to+\infty.
\end{equation}
Consequently, for every \(l\geq2\), the function
\(\mathcal{F}_l(\,\cdot\,;\lambda,\gamma)\) has at least one zero on
\((0,+\infty)\), while for each fixed \(R>0\), all sufficiently large
modes are stable.

[Def sequence-prior of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $\alpha,\beta,\gamma,\theta\in\mathds{R}$, $\mu,\nu\in (-\infty,0]$, and let $X$ be a (real-valued) random variable.
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{We say that $a=(a_{j,t,m})_{(j,t,m)\in J}\in\mathds{R}^J$ \emph{follows a Besov sequence prior with parameters $(\alpha,\beta,\gamma,\theta)$ and template random variable $X$} if there are i.i.d.\ random variables $\xi_{j,t,m}\sim X$ for $(j,t,m)\in \mathds{N}_0\times \left\{F,M\right\}^d\times \mathds{Z}^d$ such that 
\begin{equation}
a_{j,t,m}=2^{j\alpha}(j+1)^\theta \lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j}}^{\beta + (\gamma-\beta)\mathds{1}_{j=0}}\xi_{j,t,m}.
\end{equation}}
\item{We say that $a=(a_{j,t,m})_{(j,t,m)\in J}\in\mathds{R}^J$ \emph{follows a Besov--Bernoulli{} sequence prior with parameters $(\alpha,\beta,\gamma,\mu,\nu)$ and template random variable $X$} if there are i.i.d.\ random variables $\xi_{j,t,m}\sim X$ for $(j,t,m)\in \mathds{N}_0\times \left\{F,M\right\}^d\times \mathds{Z}^d$ and
Bernoulli$(\varrho_{j,m})$-distributed random variables $\lambda_{j,t,m}$ for $(j,t,m)\in \mathds{N}_0\times \left\{F,M\right\}^d\times \mathds{Z}^d$, independent among each other and from all the $\xi_{j,t,m}$, with
\begin{equation*}
\varrho_{j,m}=2^{j\mu}\lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j }}^\nu
\end{equation*}
such that
\begin{equation}
a_{j,t,m}=2^{j\alpha} \lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j}}^{\beta + (\gamma-\beta)\mathds{1}_{j=0}}\lambda_{j,t,m}\xi_{j,t,m}.
\end{equation}}
\end{enumerate}

[Proposition 3 of arXiv:2607.22878, 'Clustering of large deviations in heavy-tailed moving averages: the catastrophe principle '] Suppose Assumption
  \ref{ass:tail_measure} holds and $(\lambda_n)$ satisfies
  \eqref{e:lambda.n}.

 (i)   If the set
  $(pB_++(1-p)B_-)^{-1} A_{lj}$ is a 
  $\nu$-continuity set for every $(l,j)$, $p=0,1$ and a.e. $0<p< 1$, then
   \begin{align}
&\lim_{n\to\infty} \frac{\sum_{i = -\infty}^\infty E\bigl( e^{-g(i/n,
    H_i^{(n)} Z_i/\lambda_n)} \one_{\Gamma}(H_i^{(n)} Z_i/\lambda_n)\bigr) }
{n P(h^{(n)}\|Z\| > \lambda_n)}\\
\notag =&\frac{1}{\nu(\{z: \|z\|> 1\})}  \int_{-\infty}^\infty \left( 
\int_{B_y^{-1}\Gamma} e^{-g(y,B_yx)} \nu (dx)\right) \ dy.
   \end{align}

 (ii)     If the set $A_{lj}$ is a $\nu$-continuity set, then
 \begin{align}
&\lim_{n\to\infty} \frac{\sum_{i = -\infty}^\infty E\bigl( e^{-g(i/n,
    h^{(n)} Z_i/\lambda_n)} \one_{\Gamma}(H_i^{(n)} Z_i/\lambda_n)\bigr) }
{n P(h^{(n)}\|Z\| > \lambda_n)}\\
\notag =&\frac{1}{\nu(\{z: \|z\|> 1\})}  \int_{-\infty}^\infty \left( 
\int_{B_y^{-1}\Gamma} e^{-g(y,x)} \nu (dx)\right) \ dy.
 \end{align}

 In particular,
 \begin{equation}
\lim_{n\to\infty} \frac{\sum_{i = -\infty}^\infty 
    P (H_i^{(n)} Z_i\in\lambda_n\Gamma)}
{n P(h^{(n)}\|Z\| > \lambda_n)}
=\frac{1}{\nu(\{z: \|z\|> 1\})}  \int_{-\infty}^\infty \nu(B_y^{-1}\Gamma)  dy.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition tilt of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] For $\beta\in \Bbb R$ and $k\in \mathbb{N}$, we define the \textit{$\beta$-tilted $k$-point motion} to be the Markov process whose generator is given by \begin{equation}\ensuremath{\mathcal L}^{(\beta,k)}(\mathbf x,\mathbf y)=e^{\beta \sum_{j=1}^k (y_j-x_j)} \ensuremath{\mathcal L}^{(k)}(\mathbf x,\mathbf y) - \mathbf{1}_{\{\mathbf y=\mathbf x\}} \sum_{\mathbf z\in\Bbb Z^k} e^{\beta \sum_{j=1}^k (z_j-x_j)} \ensuremath{\mathcal L}^{(k)}(\mathbf x,\mathbf z)\; \text{.}
    \end{equation}
    In analogy with Definition (kpoint of the paper), we write $\mathbf P_\mathbf x^{(\beta,k)}$ and $\mathbf E_\mathbf x^{(\beta,k)}$ for the corresponding law and expectation, and $\mathbf p_t^{(\beta,k)}$ for its transition probabilities.

[Theorem 2 of arXiv:2608.30752, '2608.30752'] Let \((M,g)\) be a closed Riemannian manifold, let \(u_0:M\to S\) satisfy
the filling hypothesis, and let
\(q\in\mathcal Q^1(X_0)\) be Jenkins--Strebel. With the notation above,
\begin{equation}

  \lim_{t\to\infty}
  \frac{\mathcal E_{u_0}(X_t)}{t^2}
  =
  16\,\mathscr E_{\Delta_q}(u_0).
\end{equation}
In particular, the limit exists and is strictly positive. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 171 of arXiv:2601.16377, '2601.16377'] Fix $\hat{A} > 0$, $\hat{B}=\hat{C}>0$, and suppose that the vertical line at distance $\hat{\mathfrak t} \in (0,\hat{B} + \hat{C})$ from the left border of $\hat{A}\times \hat{B}\times \hat{C}$ hexagon does not pass through any of the tangency point of the inscribed ellipse. There exists $\tilde D_0>0$ such that, for any $\hat{D} \in [0,\hat{D}_0]$ and with the choice of $\hat{\mathfrak{h}}$ making the parameters symmetric, the simplified equilibrium measure $\tilde{\boldsymbol{\mu}}$ for the potential \eqref{eq_x284} has two bands $(\alpha_1,\beta_1)$ and $(\alpha_2,\beta_2)$ satisfying strict inequalities
 \begin{equation}

 \hat a'_1<\alpha_1<\beta_1<\hat b'_1<\hat a'_2<\alpha_2<\beta_2<\hat b'_2.
\end{equation}
 In addition, the segments $[\beta_1,\hat b_1']$ and $[\hat a'_2,\alpha_2]$ are void, while the segments $[\hat a'_1,\alpha_1]$ and $[\beta_2,\hat b'_2]$ are either both void or both saturated.

[Theorem 11 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ with $f_N\in H^{\odot p}$ 
	for all $N\geq 1$. Assume that $(X_N, N\geq 1)$ satisfies \eqref{c1}. 
	Let $Y_N=I_q(g_N), g_{N}\in H ^ {\odot q}$ with $ap<q<(a+1)p$ for some integer $a\geq 1$. Assume that
	\begin{equation}
		(Y_N, Y_{1,N}, \ldots, Y_{a,N}) \xrightarrow[N\to\infty]{(d)} 
		(Y, Y_1, \ldots, Y_a).
	\end{equation}
	Then $(X_N, Y_N)\xrightarrow[N\to\infty]{(d)}(Z,Y)$, where $Z\sim N(0,\sigma^2)$ 
	and the characteristic function of $(Z,Y)$ is given by, for every 
	$(u,v)\in\mathbb{R}^2$,
	\begin{equation}
		\varphi(u,v) 
		= e^{-\sigma^2 u^2/2}
		\sum_{\ell=0}^\infty \frac{u^\ell}{\ell!}
		\sum_{\substack{m=(m_1,\ldots,m_a)\in\mathbb{N}^a\\ 
				|m|=m_1+\cdots+m_a\leq \ell}}
		A_{\ell,m}(v)\,
		\mathbf{E}\!\left[\prod_{r=1}^{a}Y_r^{m_r}\, e^{ivY}\right],
	\end{equation}
	where the coefficients $A_{\ell,m}(v)$ are polynomials in $v/p$ defined 
	by the recursion
	\begin{equation}
		A_{0,(0,\ldots,0)} = 1, \qquad A_{\ell,m} = 0 \text{ if } |m|>\ell,
	\end{equation}
	and
	\begin{equation}
		A_{\ell+1,m} = -\frac{v}{p}\,A_{\ell,m-e_1} 
		+ \frac{i}{p}\sum_{s=1}^{a}(m_s+1)\,A_{\ell,m+e_s-e_{s+1}},
	\end{equation}
	with the convention $A_{\ell,m}=0$ whenever any component of $m$ is 
	negative or $m$ has more than $a$ components. The series \eqref{fia} 
	converges absolutely for every $(u,v)\in\mathbb{R}^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

