[Lem 13 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] Let ${\sf d}$ be a distance function consistent with the given topology on 
 $E$.
Suppose that the jumping measure $J$ satisfies 
$\frac{D_1}{{\sf d}(x,y)^{p_1}}{\m}({\d} x){\m}({\d} y)\leq
J({\d} x{\d} y)\leq \frac{D_2}{{\sf d}(x,y)^{p_2}}{\m}({\d} x){\m}({\d} y)$ for some $D_1,D_2>0$ and $0<p_1\leq p_2<\infty$. 
Fix a point $o\in E$. Take $u\in L^1_{\loc}(E;{\m})$. Then the following are equivalent. 
\begin{enumerate}
\item[\rm(1)] $\left(1\land \frac{1}{{\sf d}(\cdot,o)^{p_1}} \right)|u|\in L^1(E;{\m})$.
\item[\rm(2)] For any $U\Subset V\Subset E$ with $o\in V$, 
\begin{align*}
\int_{U\times V^c}|u(y)|J({\d} x{\d} y)
<\infty.
\end{align*} 
\end{enumerate}
Take $u\in L^2_{\loc}(E;{\m})$. Then the following are equivalent. 
\begin{enumerate}
\item[\rm(3)] $\left(1\land \frac{1}{{\sf d}(\cdot,o)^{p_1}} \right)|u|^2\in L^1(E;{\m})$.
\item[\rm(4)] For any $U\Subset V\Subset E$  with $o\in V$, 
\begin{align*}
\int_{U\times V^c}|u(y)|^2J({\d} x{\d} y)
<\infty.
\end{align*} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:Riemann Xi of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $f_{n}(z)=\Xi(2\log(n)^{-1} z)$, where $\Xi(z)=\xi\left(\frac{1}{2}+iz\right)$, \begin{equation}
		\xi(z)=\frac{1}{2}z(1-z)\pi^{-z/2}\Gamma\left(\frac{z}{2}\right)\zeta(z),
	\end{equation} and $\zeta$ is the Riemann $\zeta$-function. Then, \begin{equation}
		\llbracket A_{n,f_n}\rrbracket\Rightarrow\frac{1}{\pi}\frac{1}{x^2+1}\mathrm{d} x.
	\end{equation} Since the Cauchy distribution is invariant under $x\mapsto\frac{1}{x}$, it also follows that \begin{equation}
		\llbracket J_{n,f_n}\rrbracket \Rightarrow \frac{1}{\pi}\frac{1}{x^2+1}\mathrm{d} x.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem imp_ind of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] Fix a direction parameter $\lambda\in(0,1)$ and a unit edge $[\![\mathbf{a}, \mathbf{b}]\!]$, where $\mathbf {b}\in\{\mathbf a+\mathbf e_1,\mathbf a-\mathbf e_2\}$.
Let $\mathcal{F}_{\preceq}$ denote the $\sigma$-algebra generated by all Busemann functions $B^\rho_{\mathbf x,\mathbf y}$ of the form
\begin{align} 
\text{$\rho\ge\lambda$ and $\mathbf x,\mathbf y\preceq \mathbf a$}
\qquad \text{or} \qquad
\text{$\rho\le\lambda$ and $\mathbf x,\mathbf y\succeq \mathbf b$.}
\end{align}
Then $B^\lambda_{\mathbf a, \mathbf b}$ is independent of $\mathcal{F}_\preceq$. (Proof in the paper; no proof environment follows the statement in the TeX.)

