body:
[Proposition lem-repeat-used of arXiv:2607.22324, 'The conclave process'] {}
    Recall that we use $\mathcal W$ to denote the eventual winner of the election, and we use $\mathcal L(\mathbf X)$ to denote the set of leaders in a tuple $\mathbf X$. Suppose that $\alpha > 1$ and
    \begin{equation}{}
        M \geq (\log n)^{101}, \quad \delta \geq M^{-\frac{1}{2}} (\log n)^3, \quad (1-\delta)M \geq (\log n)^{20}\,, \quad 1-\delta >n^{-\tfrac{1}{100(\alpha + 1)}} \,.
    \end{equation}
    Define $\kappa=\kappa(n,\delta,\alpha)$ such that
    \begin{equation}{}
        \kappa = \frac{ \log\log(n) + \log(1/\delta) }{ \log(\alpha) } \,.
    \end{equation}
    Then, given any $(\mathbf X_k^{(1)},\ldots,\mathbf X_k^{(n)}) \in \overline{\Omega}_n(M,\delta)$, we have
    \begin{align*}
        \mathbb P_n^{\alpha}\left( \mathcal W \in \mathcal L(\mathbf X_k), \mathcal T=k+(1-o(1))\kappa \right)=1-o(1) \,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm thresholding of arXiv:2608.20635, 'Minimax Optimality of Score-Entropy Discrete Diffusion'] Denote by $s$ the output of Algorithm (alg:thresholding of the paper), then there exists a positive numerical constant $C_1 > 0$, such that 
\begin{align*}
	\mathbb{E}[\mathcal{L}_{\mathsf{SE}}(s, p)] \leq \frac{ C_1|\mathcal{X}| \log_v |\mathcal{X}| \zeta \log n \log (n \zeta)}{n}.  
\end{align*}

[Theorem 19 (Optimal repeated-pole rational kernel) of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] Let $a_*$ be a global optimizer of the closed degree-at-most-$m$ polynomial-square problem, and let $R_*$ be defined by \eqref{var:eq:R-def}. Then
\begin{align*}
 \deg a_*=m,
 \qquad
 R_*(t)a_*(t)=c\Lag_{m+2}(t),
\end{align*}
for some nonzero real constant $c$. Moreover, there is an index $j\in\{1,\ldots,m+1\}$ such that
\begin{align*}
 R_*(t)
 =(t-x_{j,m+2})(t-x_{j+1,m+2}),
\end{align*}
and
\begin{equation}
 a_*(t)
 =C\frac{\Lag_{m+2}(t)}
 {(t-x_{j,m+2})(t-x_{j+1,m+2})}.
\end{equation}
The deleted pair minimizes the relative adjacent-gap score, and this common value is the optimum $\mathfrak v_m$ itself:
\begin{equation}
\mathfrak v_m
 =\Vcal(a_*)
 =\Delta_{m+2}
 =\min_{1\leq r\leq m+1}
 \frac{(x_{r+1,m+2}-x_{r,m+2})^2}
 {4x_{r,m+2}x_{r+1,m+2}}.
\end{equation}
At the endpoint $m=0$, this reads $\mathfrak v_0=\Delta_2=1$. The unique half-polynomial is constant and the mean-one kernel is the unit exponential density.

Writing $n=m+2$, $x=x_{j,n}$, and $y=x_{j+1,n}$ for the minimizing pair, so that $a_*(t)=C\,\Lag_n(t)/\bigl((t-x)(t-y)\bigr)$, the normalized unit-damping density is
\begin{equation}
 \kappa_{1,a_*}(z)
 =\frac{xy(y-x)^2}{x+y}\e^{-z}
 \left[\frac{\Lag_n(z)}{(z-x)(z-y)}\right]^2,
\end{equation}
and
\begin{equation}
 \E[T_{a_*}]=\frac{2xy}{x+y},
 \qquad
 \E[T_{a_*}^2]=xy.
\end{equation}
Choosing $\lambda_{m,j}=2xy/(x+y)$ produces the optimal mean-one kernel
\begin{align*}
 \kappa_{m,j}^*(u)
 =\lambda_{m,j}\frac{xy(y-x)^2}{x+y}
 \e^{-\lambda_{m,j}u}
 \left[
 \frac{\Lag_n(\lambda_{m,j}u)}
 {(\lambda_{m,j}u-x)(\lambda_{m,j}u-y)}
 \right]^2,
\end{align*}
with removable singularities, for which
\begin{align*}
 \int_0^\infty\kappa_{m,j}^*(u)\dd u=1,
 \qquad
 \E[U_{m,j}^*]=1,
 \qquad
 \Var(U_{m,j}^*)={\gamma_{j,n}}=\Delta_n.
\end{align*}
No other kernel in the exact-degree repeated-pole square-polynomial class has smaller variance, and every optimal kernel arises this way, up to the irrelevant sign and magnitude of the half-polynomial, from one minimizing adjacent pair.

[Lemma 6 of arXiv:2606.30411, 'Notes on constants for maxima of Rademacher averages'] For $n=2m$,
\begin{equation}
    \Eb\max_{1\leq j\leq p}\Abs{\sum_{i=1}^n\epsilon_{ij}}
    =
    2\sum_{k=0}^{m-1}
    \left[1-\{1-2F_n(k)\}^p\right].
\end{equation}
For $n=2m+1$,
\begin{equation}
    \Eb\max_{1\leq j\leq p}\Abs{\sum_{i=1}^n\epsilon_{ij}}
    =
    1+2\sum_{k=0}^{m-1}
    \left[1-\{1-2F_n(k)\}^p\right].
\end{equation}

