[Definition def of Ito sol of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] A process $u=\{u(t,x); (t,x)\in\mathbb{R}_{+}\times M \}$ is called a random field solution of~(equation eq:pam2 of the paper) in the It\^o-Walsh sense [Walsh1986AnIT] if the following conditions are met:
\begin{enumerate}
\item $u$ is adapted;

\item $u$ is jointly measurable with respect to $\mathcal{B}(\mathbb{R}_{+}\times M )\otimes \mathcal{G}$; 
\item $\mathbf{E}(I(t,x)^2)<\infty$ for all $(t,x)\in\mathbb{R}_{+}\times M$;
\item The function $(t,x)\to I(t,x)$ is continuous in $L^2(\Omega)$;
\item $u$ satisfies (equation eq:PAM-mild form of the paper) almost surely for all $(t,x)\in\mathbb{R}_{+}\times M$.
\end{enumerate}

[Corollary cor_uu_frac_lim of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] For any $s \in (0,1)$ and $y \in \mathbb{R}$ we have
    \begin{multline}
        \lim_{\alpha \to \infty} \frac{u_{\alpha}\left( s+ \frac{y}{\gamma(\alpha)} \right) }{u_{\alpha}(s)} = \lim_{\alpha \to \infty} \frac{u_{\alpha}\left( s+ \frac{y}{\gamma(\alpha)} \right) }{u_{\alpha}(s)} \cdot \frac{1}{1}
        \stackrel{(equation eq_u_kk_x of the paper)}{=} \\
\lim_{\alpha \to \infty}
\frac{u_{\alpha}\left( s+ \frac{y}{\gamma(\alpha)} \right)}{u_\alpha(s)} \cdot
\frac{
u_\alpha(s) \cdot \gamma(\alpha) \cdot g_{\alpha}(s) \cdot \psi(s)  }{
 u_\alpha\left(s+ \frac{y}{\gamma(\alpha)}\right) \cdot \gamma(\alpha) \cdot g_{\alpha}\left(s+ \frac{y}{\gamma(\alpha)}\right) \cdot \psi\left(s+ \frac{y}{\gamma(\alpha)}\right) }
        \\ =
        \lim_{\alpha \to \infty} \frac{g_\alpha(s)}{g_\alpha\left( s+ \frac{y}{\gamma(\alpha)} \right)} \cdot
 \frac       {  \psi(s)  }{  \psi\left( s+ \frac{y}{\gamma(\alpha)} \right)}
        \stackrel{(equation psi_exp of the paper)}{=} e^{\psi(s)\cdot y}.
    \end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 180 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] [annealed second moment bounds for 
$\bar{D}^{\RomIII}$ and 
$\bar{D}^{\frozen,\RomIII}$]

Let $\bar{D}^{\RomIII}$ and $\bar{D}^{\frozen,\RomIII}$ 
be defined by \eqref{e:barD} and \eqref{e:barD.plus} (see also \eqref{e:drift.error.III}).  We then have
	\[
	\frac{\E[\Delta\bar{D}^{\RomIII}(q_d)^2]}
		{q_d p'(q_d)}
	\le \frac{L^{O(1)}\BUCKETS \delta}{N}
	\]
for all $0\le d\le \dmax-1$. 
The same bound holds with $\bar{D}^{\frozen,\RomIII}$ in place of $\bar{D}^{\RomIII}$.
\begin{proof}
Recalling the notation from \eqref{e:normalized.vectors.x},
we can rewrite \eqref{e:drift.error.III} as
	\[
	\frac{\Delta\bar{D}^\RomIII(q_d)}
		{[\delta_d q_d p'(q_d)]^{1/2}}
	= \frac1{|B|^{1/2}}
	\bigg(
	\sum_{a\in B}
	\frac{\bmeta^a(q_{d+1})}{|B|^{1/2}},
		\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)
	\equiv
	\frac1{|B|^{1/2}}
	\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)\,.
	\]
Note that $\bar{\bx}(q_d)$ is measurable with respect to $\cG(q_d)$, and $\bmeta^B(q_{d+1})$ is a standard gaussian in $\R^N$ conditional on $\cG(q_d)$. It follows that
	\[\frac{\E[\Delta\bar{D}^\RomIII(q_d)^2]}
		{\delta_d q_d p'(q_d)}
	\le 
	\frac{1}{M}\E\bigg[ \sum_{B\in\mathcal{B}(q_d)} 
	\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)^2\bigg]
	\le \frac{O(1)\BUCKETS
		\E[\|\bar{\bx}(q_d)\|^2]}{MN}\,,
	\]
and the claim for $\bar{D}^\RomIII$ follows by combining Lemma~\ref{l:bar.x.subgaus} with Lemma~\ref{l:sg.norm.bound}. The claim for
$\bar{D}^{\frozen,\RomIII}$ then follows by using \eqref{e:barD.vs.plus}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (Finite-volume conditional relative entropies are (in general non-uniformly) controlled by entropy-production per site) of arXiv:2608.13677, 'Asymptotically complete free-energy dissipation: \\ a coarse MLSI holds at any positive te'] \label[lemma]{lemma:MLSI_type_bound_for_finite_volume_conditional_entropies}
    For every \(n \in \mathbb{N}\) there is a \(\delta_n > 0\) such that for all \(\mu \in \mathcal{P}_\theta\) it holds 
    \begin{align}
        \frac{h_{\Lambda_n \vert \Lambda_n^c}(\mu)}{\vert \Lambda_n\vert}
        \,\leq\, \delta_n^{-1} \,\sigma(\mu).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Harer-Zagier generating function \cite{HarerZagier}) of arXiv:2606.05430, 'On a random matrix proof of\\ a bipartite Harer-Zagier formula'] Let $n$ be a non-negative integer; then the following equality holds:
    \[\sum_{g=0}^{\lfloor n/2\rfloor} \e_g(n) \cdot N^{n+1-2g} = (2n-1)!! \sum_{l=0}^{n} 2^{l}\binom{n}{l}\binom{N}{l+1}\]
    for all integers $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.02808, 'Minimizers of Laplace eigenvalues under a lower curvature bound'] Let $D>0$ and let $\varphi\colon[0,D]\to[0,\infty)$ be continuous, positive on $(0,D)$,
and such that
\begin{equation}
\varphi''+\varphi\ \le\ 0\qquad\text{in the sense of distributions on }(0,D).
\end{equation}
Then
\begin{equation}
\mu_j(\varphi)\;\ge\; j(j+1)\qquad\text{for every } j\ge 0 .
\end{equation}
If equality holds for some $j\ge1$, then $D=\pi$ and $\varphi$ is a positive constant
multiple of $\sin$, so that $X_\varphi$ is the Legendre model. (Proof in the paper; no proof environment follows the statement in the TeX.)

