body:
[Lem 23 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] For every $r>0$, there exists $\tau_\eps > 0$ such that for every $t\in[0,\tau_\eps]$ and $x \in \overline{\widetilde{\oO}}$, we have
\begin{equation} 
    |\widehat{X}^\eps_t(x)-x|\leq r\;, \qquad
        \|\nabla^\sft\widehat{X}^\eps_t(x) - \id \| \leq r\;.
\end{equation}
As a result, for sufficiently small $r$, $\widehat{X}^\eps_t$ is injective for $t \in [0, \tau_\eps]$, and $\widehat{X}^\eps_t (\d \widetilde{\oO}) = \d \oO_t^\eps$.

If in addition, $\|v_\eps\|_{\lL_t^\infty \cC_x^2([0,T]\times 
\overline{\widetilde{\oO}})}$ is uniformly bounded in $\eps$, then for every $\oO \Subset \widetilde{\oO}$, there exists $\tau>0$ independent of $\eps$ such that
\begin{equation*}
    \oO \Subset \big\{ \widehat{X}_t^\eps(y): \; y \in \widetilde{\oO} \big\}
\end{equation*}
for all $t \in [0,\tau]$ and all sufficiently small $\eps$. Finally, if in addition,  $\|\nabla^3 v_0\|_{\lL_{t,x}^\infty([0,\tau] \times \overline{\oO_1})}$ is finite for some $\oO\Subset\oO_1\Subset\widetilde\oO$, then the inverse $\widehat{S}_t^\eps: \overline{\oO} \rightarrow \RR^d$ satisfies
\begin{equation*}
    \begin{split}
    \big\|\widehat{S}_t^\eps - \widehat{S}_t^0 \big\|_{\lL^\infty(\overline{\oO})} &\lesssim \big\| \widehat{X}_t^\eps - \widehat{X}_t^0 \big\|_{\lL^\infty(\widetilde{\oO})}\;,\\
    \big\|\nabla^\sft \big( \widehat{S}_t^\eps - \widehat{S}_t^0 \big) \big\|_{\lL^\infty(\overline{\oO})} &\lesssim \big\| \widehat{X}_t^\eps - \widehat{X}_t^0 \big\|_{\lL^\infty(\widetilde{\oO})} + \big\|\nabla^\sft \big( \widehat{X}_t^\eps - \widehat{X}_t^0 \big) \big\|_{\lL^\infty(\widetilde{\oO})}\;.
    \end{split}
\end{equation*}
The proportionality constants are independent of $t \in [0,\tau]$.

