[Theorem thm:dissipation_of_E of arXiv:2602.00988, 'Wealth exchange under ceiling and flooring constraints: a modified Bennati–Dragulescu–Yako'] Let ${\bf p}(t) = \{p_n(t)\}_{n\geq 0}$ be a classical solution to the system of nonlinear ODEs (equation eq:law_limit of the paper)-(equation eq:two-classes of the paper) with ${\bf p}(0) \in \mathcal{A}$. There exist fixed $k_1>0$ and $k_2>0$ such that for all $t \geq 0$ we have
\begin{equation}
\frac{\mathrm{d}}{\mathrm{d} t} \widetilde{\mathcal{H}}_{ab}[{\bf p}] \leq 0.
\end{equation}
Moreover, $\frac{\mathrm{d}}{\mathrm{d} t} \widetilde{\mathcal{H}}_{ab}[{\bf p}] = 0$ if and only if ${\bf p}$ coincides with ${\bf p}^*$ (equation eq:equi of the paper). Consequently, ${\bf p}(t) \xrightarrow{t\to \infty} {\bf p}^*$ strongly in $\ell^p$ for each $1 < p < \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:8 of arXiv:2504.12293, 'Near-existence of bigeodesics in dynamical exponential last passage percolation'] There exists a constant $C$ such that for all $n$ and all $j_1,j_2,k_1,k_2\in [\![-\varepsilon n^{1/3}, \varepsilon n^{1/3}]\!]$,
  \begin{equation}

   \int_0^1\mathbb{P}(\mathfrak{p}_n \in \Gamma_{u_{j_1}}^{v_{k_1},0}\cap \Gamma_{u_{j_2}}^{v_{k_2},t})dt=  \frac{1}{|\mathrm{Box}_n|}\int_0^1\mathbb{E}[|\Gamma_{u_{j_1}}^{v_{k_1},0}\cap \Gamma_{u_{j_2}}^{v_{k_2},t}\cap \mathrm{Box}_{ n}|]dt \leq Cn^{-2}\mathrm{Cov}(T_{u_{j_1}}^{v_{k_1}},T_{u_{j_2}}^{v_{k_2}}).
  \end{equation}

[Lem upsilem of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] It follows that
$\underline{\psi}\in C^{1}_{0}(\overline{B_{1}^2})$ for any sufficiently large $t$ and $\underline{\psi}_t \in C^{1}_{0}(\overline{B_{1}^2})$ for a.e. sufficiently large $t$. In addition, we have
\begin{equation*}
\lVert \underline{\psi}\rVert_{C^{1}(B_{1}\setminus B_{1/2})}\le C \zeta_2 t^{-5/2}\quad\text{and} \quad |\underline{\psi}|\le C \zeta_2 t^{-5/2}\psi_1 \quad \text{in $B_{1}^2$}
\end{equation*}
for any $t$ sufficiently large and
\begin{equation*}
    \lVert \underline{\psi}_{t}\rVert_{C^{1}(B_{1}\setminus B_{1/2})}\le C \zeta_2 t^{-5/2}\quad\text{and} \quad |\underline{\psi}_{t}|\le C\zeta_2 t^{-5/2}\psi_1 \quad \text{in $B_{1}^2$}
\end{equation*}
for a.e. $t$ sufficiently large, where $C>0$ is independent of $t$.

