{"artifact_digest":"sha256:f2674c8c9e0e09fee92c9e9ea645a3803e56fd97f3bf6931cccb3d3e4a35ad89","artifact_path":"objects/sha256/f2/f2674c8c9e0e09fee92c9e9ea645a3803e56fd97f3bf6931cccb3d3e4a35ad89.md","bundle_digest":"sha256:ef996e5bbaf32f6ce193408f4e0730cfcb867309e0e69800f144284356ae7378","bundle_entry_key":"2509-06730-theorem-16-cor-16","bundle_id":"population.tex-extract-s0_059","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-v2-20260907/bundle_s0_059.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2509-06730-cor-16-cor-16","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: We first show that for any $K$, $\mu_\infty^K$ has a density with respect to the Lebesgue measure.
