[Lemma renormalization of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Let $f:\Omega\longrightarrow\mathbb{R}$ be a local function whose support is included in $\{0,\hdots ,\ell_0 -1\}$ for some $\ell_0\ge 1$. There exists a constant $C_{14}=C_{14}(\kappa ,\rho ,\mathcal{E} ,f)>0$ such that for any $t\in [0,T]$, and $\ell\ge \ell_0$ and any measurable function $v:[0,T]\longrightarrow\ell^2(\mathbb{Z})$, we have 
    \begin{equation}

        \mathbb{E}_{\rho ,\mathcal{E}}\left[\left(\int_0^t\sum_{x\in\mathbb{Z}}\tau_x\big\{ \mathbb{E}_{\ell }[f]-\mathbb{E}_{2\ell}[f]\big\} (s)v_s(x)\,\mathrm{d} s\right)^2\right] \le C_{14} \frac{\ell^\beta}{N^a}\int_0^t\| v_s\|^2\,\mathrm{d} s,
    \end{equation}
    where
    \begin{equation*}
        \beta = \begin{cases}
            2 & \mbox{ if }\nabla\psi_f(\rho ,\mathcal{E})\neq 0,\\
            1 & \mbox{ if } \nabla\psi_f(\rho ,\mathcal{E} )=0\mbox{ and }\mathrm{Hess}(\psi_f)(\rho ,\mathcal{E})\neq 0,\\
            0 & \mbox{ if } \nabla\psi_f(\rho ,\mathcal{E})=0\mbox{ and }\mathrm{Hess}(\psi_f)(\rho ,\mathcal{E})=0.
        \end{cases}
    \end{equation*}

