[Theorem t:suboptimal_Lq_Rpositive of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Let $p,q\in (2,\infty)$ be such that $\mathtt{Sob}=1-\frac{2}{p}-\frac{d}{q}$ satisfies  (equation eq:assumption_suboptimal_Lq_finite_time1 of the paper), and set $q_{{\rm max}}\stackrel{{\rm def}}{=}-\frac{d^2}{d-2}\frac{1}{\mathtt{Sob}}$, 
with the convention $q_{{\rm max}}=\infty$ if $d=2$. Then, for all $p_0\in (p,\infty)$, $r\in (1,p_0]$, and $q_0\in (2,q_{{\rm max}})$ satisfying (equation eq:suboptimal_Lq_finite_time_suboptimality_condition of the paper), there exists a constant $C_0>0$ such that, for all $N\geq 1$, any interval $I=(0,T)\subseteq {\mathbb R}_+$ with $T\in (0,\infty]$, and 
\begin{equation}

w_0\in L^r_{{\mathscr F}_0}(\Omega;\mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^d))\qquad \text{ and }\qquad F\in L^r_{\mathscr{P}}(\Omega;L^p(I ;L^q(\mathbb{T}^d;{\mathbb R}^{d\times d}))),
\end{equation}
such that $\int_{\mathbb{T}^d} w_0 =0$ a.s., the unique energy solution $w^N$ to the oscillating stochastic Stokes system (equation eq:turbulent_Stokes_scaling_uniform_estimates of the paper) provided by Lemma (l:global_energy_estimate of the paper) satisfies
\begin{align}
\nonumber
\big({\mathbf E}\|w^N\|_{L^{p_0}(I;L^{q_0} (\mathbb{T}^d))}^{r} \big)^{1/r}
&
\leq C_0 \big({\mathbf E}\|w_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^d)}^r\big)^{1/r} + C_0  \big({\mathbf E}\|F\|_{L^p(I;L^q(\mathbb{T}^d))}^r\big)^{1/r}\\

 &+ C_0\big({\mathbf E}\|w^N\|_{L^{p}(I;H^{-1,q} (\mathbb{T}^d))}^r \big)^{1/r}. 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Janson of arXiv:2606.30475, 'Ancestries in random $d$-DAGs'] {Jan2023}}]
 Let $d\geq 2$. Then, as $n\to\infty$, both in distribution and for all moments,
 \begin{equation}
  n^{-\frac{d-1}{d}}|D_n| \to \frac{(d-1)^{1/d}\pi}{d\sin(\pi/d)} \gamma^{1/d},
 \end{equation}
 where $\gamma$ is a gamma-distributed random variable with parameters $\frac{d}{d-1}$ and 1, thus having density $\Gamma\left(\frac{d}{d-1}\right)^{-1} x^{-\frac{1}{d-1}} e^{-x}$ for $x>0$. In particular, this means
 \begin{equation}
  n^{-\frac{d-1}{d}} \mathbb{E} |D_n|
  \to \frac{(d-1)^{1/d} \pi}{d\sin(\pi/d)} \cdot \frac{\Gamma\left(\frac{d}{d-1}+\frac{1}{d}\right)}{\Gamma\left(\frac{d}{d-1}\right)} \qquad \text{as }n\to\infty.
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm.poly-tails of arXiv:2505.15283, 'Quantization of Probability Distributions via Divide-and-Conquer: Convergence and Error Pr'] Assume that $\lim_{x\to \infty} x^\alpha\mu[x,\infty) = c \in (0,\infty),\ \alpha>1$ as $x \to \infty$ and let $\mu^{(n)} = T(\mu,n)$. Then we have
    \begin{equation*}
        \lim_{n \to \infty} \frac{\log(W_1(\mu,\mu^{(n)}))}{n} = 
        \log 
        \left(
        \left(
            1-\frac{1}{\alpha}
        \right)^{(\alpha-1)}
        \vee
        \frac{1}{2}
        \right).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin Admissibility of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] A non-degenerate weight pair $({\mathbf{a}},{\mathbf{b}})$ will be called \emph{admissible} if there exists a coupling of the random compositions $(C_n)_{n\geq 0}$  with distributions $(\PComp{{\mathbf{a}},{\mathbf{b}}}{n})_{n\geq 1}$ respectively, in such a way that 
	\begin{align*}
	C_0\covered C_1\covered C_2\covered \dots\covered C_n\covered C_{n+1}\covered\dots.
	\end{align*}

