[Corollary A025 of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Let $\kappa \in (8/3, 4)$ and $\beta \in [-1, 1]$. Let $\rho^\prime$, $\rho_\BR$, and $\rho_\rL$ be as in~(A021 of the paper) such that $\beta = \beta(\kappa^\prime, \rho^\prime)$. Consider the following algorithm:
	\begin{itemize}
		\item One samples a $\cwBCLE_{\kappa^\prime}(\rho^\prime)$ in $\BH$. Then, inside each connected component of each true (resp.\ false) loop of this $\cwBCLE_{\kappa^\prime}(\rho^\prime)$, one samples an independent $\ccwBCLE_\kappa(\rho_\BR)$ (resp.\ $\cwBCLE_\kappa(\rho_\rL)$).
		\item Inside each (both true and false) loop of the $\ccwBCLE_\kappa(\rho_\BR)$'s and $\cwBCLE_\kappa(\rho_\rL)$'s of the previous step, one samples an independent $\cwBCLE_{\kappa^\prime}(\rho^\prime)$. Then, inside each connected component of each true (resp.\ false) loop of these $\cwBCLE_{\kappa^\prime}(\rho^\prime)$'s, one samples an independent $\ccwBCLE_\kappa(\rho_\BR)$ (resp.\ $\cwBCLE_\kappa(\rho_\rL)$). Then, we iterate this step.
	\end{itemize}
	Then the collection of all the true loops of all the simple BCLEs has the law of a nested $\CLE_\kappa^\beta$ in $\BH$.

[Theorem thm:positive-layer-transfer of arXiv:2609.03637, 'On the abstract approach to spectral constants:\\ a proof of the Clou\^atre--Ostermann--Ra'] Let \(\mathcal A\subset C(X)\) be a uniform algebra, let
\(\theta:\mathcal A\to B(\mathcal H)\) be a bounded unital homomorphism, and let
\(P:\mathcal A\to B(\mathcal H)\) be a bounded complex-linear map satisfying
\begin{equation}
 P(1)=2I

\end{equation}
and
\begin{equation}
 \operatorname{Re} h\geq0\ \text{on }X
 \quad\Longrightarrow\quad
 \operatorname{Re} P(h)\geq0.

\end{equation}
Suppose that, for every \(f\in\mathcal A\) and every \(n\geq1\),
\begin{equation}
 \bigl[P(f^n)-\theta(f^n),\,\theta(f)^*\bigr]=0.

\end{equation}
Then \(\left\lVert \theta\right\rVert\leq2\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 5 of arXiv:2511.00679, 'Stochastic solutions to abstract telegraph-type equations involving fractional dynamics'] The solution of the d-dimensional space-time fractional telegraph equation 
\begin{align*}
&\bigg[(D_t^{\alpha})^2+2\lambda D_t^{\alpha}+(-\Delta)^{\beta/2}\bigg] u = 0,\quad t> 0, \ \alpha\in(0,1], \beta \in(0,2], \\
&u(0)=f,\ \alpha \in(0,1],\\
& D_t^{\alpha}u(0)=0,\ \alpha \in(1/2,1],
\end{align*}
is given by the convolution product $u_\alpha(t,x)=(f\ast \Phi_\alpha(t))(x),$ for each $x\in\mathbb R^d,$where
\begin{equation*}
\Phi_\alpha(t,x)=\frac{1}{(2\pi)^{\frac d2}||x||^{\frac d2-1}}\int_0^\infty r^{\frac d2}J_{\frac d2-1}(r||x||)\widehat\Phi_\alpha(t,r)\de r,\quad t>0
\end{equation*}
and 
\begin{align*}
\widehat \Phi_\alpha(t,\xi) :=\frac{1}{2}\left[
\bigg(1+\frac{\lambda}{\sqrt{\lambda-||\xi||^{\beta}}}\bigg)E_{\alpha,1}(r_1t^{\alpha})+\bigg(1-\frac{\lambda}{\sqrt{\lambda-||\xi||^{\beta}}}\bigg)E_{\alpha,1}(r_2t^{\alpha})\right],
\end{align*}
where 
\begin{align}
\nonumber & r_1 := -\lambda+\sqrt{\lambda^2-||\xi||^{\beta}},\\
\nonumber & r_2 := -\lambda-\sqrt{\lambda^2-||\xi||^{\beta}}.
\end{align}
Furthermore, for $\alpha\in(0,\frac12],$  $$u_\alpha(t,x)=\mathbb E_x\left[f(S_d^\beta(\mathcal{L}^\alpha(t) ))\right] ,\quad t>0,x\in\mathbb R^d. $$

[Lemma lem:Lem45 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Pick $\varsigma\in(0,1)$ satisfying\footnote{Note the $4$ appearing below stems from (equation eq:fix_kernel of the paper).}  
\begin{equs}
    (2/\varsigma-1)^4\leqslant2\,. 
\end{equs}
Then, there exists $\tilde{T} = \tilde{T}_{\Xi} \in(0,1]$, such that, for any $T \in (0,\tilde{T}]$, $\eta > 0$,  $p\in\N$, and $\eps \in (0,1]$, 
    \begin{equs}
         \norm{K_{\varsigma^pT}\big( F_{\eps,T}[0]+R_{\eps,T}\big)}_{L^\infty_{0;T}}\leqslant 2 C_F(\varsigma^pT)^{-1+H-\eta}\mathcal{G}_{\tt u}(1)\,,
    \end{equs}
where $C_F$ is as per Corollary~(coro:1 of the paper). Consequently, by interpolation, we have that 
\begin{equs}
     \norm{K_{\mu}\big( F_{\eps,T}[0]+R_{\eps,T}\big)}_{L^\infty_{0;T}}\lesssim C_F \mathcal{G}_{\tt u}(1)\mu^{-1+H-\eta}
\end{equs}
uniformly in $\mu\in(0,1]$.

