[Definition 8 of arXiv:2606.20948, '\textsc{Slot decomposition of\\ continuous Box-Ball Systems}'] [Mapping  $\cN$ to a carrier process]\rm
Let $\sN\in\cN$ with $\sN=\sN_+\cup \sN_-$. Recall the construction of the excursion $\vep[\sM]$ from $\sM\in\cN_o$ in Definition \ref{17}, and let 
$\tau(\vep)$ be the length of the excursion $\vep$. We have $\tau(\vep)=\se(\vep)=\se(\vep)-\so(\vep)$ as $\so(\vep)=0$ for $\vep \in \cN_0$. Consider the sequence $(\su_k,\sM_k)_{k\ge1}$ obtained in \eqref{250} from $\sN_+\in\cN_+$. Denote $\so_0\vcentcolon =0$, $\se_0\vcentcolon =0$, and for $k\ge1$, 
\begin{align}
 \vep_k&\vcentcolon =\vep[\sM_k], \quad \se_k\vcentcolon =\se(\vep_k),\\
 \so_k&\vcentcolon = \so_{k-1}+ \se_{k-1}+ \su_k, \quad k\ge1.
\end{align}
For $\sN_+\in\cN_+$, we define the carrier process $\zeta_+=\zeta[\sN_+]:\RR_+\to\RR_+$ by concatenating excursions $\vep_k$ separated by intervals of lengths $\su_k$, as follows
\begin{gather}

 \zeta(x) \vcentcolon =
 \begin{cases}
 \vep_k(x-\so_k), 
 &\so_k< x\le \so_k+\se_k, \\
  0, 
 &\so_{k-1}+\se_{k-1}< x \le \so_{k}, 
 \end{cases},\qquad k\ge1.
\end{gather}

The reflection with respect to the vertical axis of $\sN_-\in\cN_-$ is given by
\begin{align}

  \Reflect(\sN_-) &\vcentcolon = \{(-x, \ell):(x, \ell)\in\sN_-\} \in\cN_+.
\end{align}
For $\sN_-\in \cN_-$, we define $\zeta_-=\zeta[\sN_-]:\RR_-\to\RR_+$ by reflecting the previous construction, 
\begin{align}
 \zeta[\sN_-] &\vcentcolon = \Reflect\bigl[\zeta[\Reflect(\sN_-)]\bigr],  
 \\
\text{where}\quad\Reflect\zeta(x)&\vcentcolon = \zeta(-x). \notag
\end{align}
The mapping from $\sN\in \cN$ to the carrier process $\zeta=\zeta[\sN]$ is given by
\begin{align}

  \zeta[\sN](x) =
  \begin{cases}
    \zeta[\sN_+](x),&x\ge 0\\
    \zeta[\sN_-](x),&x<0.
  \end{cases}
\end{align}

[Lemma 17 of arXiv:2606.29131, '2606.29131'] Let $\Lambda_\e^7 f(x,y)$ be defined by \eqref{e2-3-4}.
For every $\beta>0$, there exists $C_3:=C_3(\beta)>0$ such that for every $f\in \M_{\beta}$, $x\in \R^d$ and $y\in \T^d$,
\begin{equation}
|\Lambda_\e^7 f(x,y)|\le C_3\left(\e+\gamma_{3,\beta}(\e)+\gamma_9(\e)\right)\left(\sum_{i=1}^3\|f\|_{\M_{\beta},i}\right)(1+|x|)^{-d-\beta}.
\end{equation}

[Defi def:nonstandard_LR_coefs of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] \begin{enumerate}
\item (Alternating case) Given $\mu\in\Sig_{2n},\nu\in\Sig_n$, we define the \emph{alternating Littlewood-Richardson coefficient} $c_{\mu,\nu}^{\alt,\lambda}(t)\in\mathbb{Z}[t]$ given by
\begin{equation}
P_\mu(x_1,x_1t,\ldots,x_n,x_nt;t)P_\nu(x_1,\ldots,x_n;t^2)=\sum_{\lambda\in\Sig_n} c_{\mu,\nu}^{\alt,\lambda}(t)P_\lambda(x_1,\ldots,x_n;t^2)
\end{equation}
\item (Hermitian case) Given $\mu,\nu\in\Sig_n$, we define the \emph{Hermitian Littlewood-Richardson coefficient} $c_{\mu,\nu}^{\her,\lambda}(t)\in\mathbb{Z}[t]$ given by
\begin{equation}
P_\mu(x_1^2,\ldots,x_n^2;t^2)P_{\nu}(x_1,\ldots,x_n;-t)=\sum_{\lambda\in\Sig_n} c_{\mu,\nu}^{\her,\lambda}(t)P_{\lambda}(x_1,\ldots,x_n;-t)
\end{equation}
\end{enumerate}

[Lemma 11 of arXiv:2606.01742, 'Large deviation principles for SPDEs with locally Lipschitz coefficients'] Assume that Hypotheses \ref{cond-initial}, \ref{cond-dif}  and  \ref{3} hold. If $L_\sigma>0$, then
\begin{align}
\sup_{N>0}\sup_{x\in \R}\E\left[\left|u_N^{ \varepsilon,h_ \varepsilon}(t,x)\right|^k\right]\leq 4^k\left(\|u_0\|_{L^\infty(\R)}+1\right)^ke^{8(2\sqrt{k\varepsilon}L_{\sigma}+ML_{\sigma})^4kt}
\end{align}
uniformly for all $t>0$, $\e>0$, $k\geq 2$ and for every $M\geq L_b^{1/4}L_{\sigma}^{-1}$.

