[Thm 1 of arXiv:2607.14674, 'On the entropy of the log-normal distribution'] The entropy $H[g_r]$ of the family of densities \eqref{eq:SC} is given as the power series
\begin{equation}
H[g_r]=H[g]+\alpha r -\sum_{k=1}^\infty \frac{\beta_k}{2k(2k-1)}r^{2k},\quad -1\le r\le 1,
\end{equation}
where
\begin{eqnarray}
\alpha&=&\frac{1}{\sqrt{2\pi}}\int_{-\infty}^\infty \exp(-t^2/2) t\sin(2\pi t)\,dt,\\
\beta_k&=&\frac{1}{\sqrt{2\pi}}\int_{-\infty}^\infty\exp(-t^2/2)\sin^{2k}(2\pi t)\,dt, k=1,2,\ldots.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 19 of arXiv:2608.01081, 'The Optimal Rate in the Averaged Random-Marginal Central Limit Theorem for Log-Concave Mea'] For $A-2z=|x-y|^2>0$,
\begin{align}
 S_n(a,b,z)
 &:=\E_\Theta
 K(\ip{x}{\Theta},\ip{y}{\Theta})\notag\\
 &=m_n\left[
 \sqrt{A-2z}
 +\frac{(5A+2z)\sqrt{A-2z}}{12(n+1)}
 +\frac{D^2}{4(n+1)\sqrt{A-2z}}
 \right].
\end{align}
The right-hand side extends continuously to $x=y$, where it is zero.

[Lemma Feller's lemma of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $X_t,X$ be a family of $[0,\infty]$-valued random variables such that $\mathbb{P}\left(X <\infty\right) = 1$. Assume that for all $\rho>0$,
    \begin{equation}
        \mathbb{E}[e^{-\rho X_t}] \longrightarrow \mathbb{E}[e^{-\rho X}] \quad \text{as} \quad t\to\infty.
    \end{equation}
    Then, 
    \begin{equation}
        \mathbb{P}\left(X_{t} = +\infty\right) \to 0 \quad \text{as} \quad t\to\infty,
    \end{equation} 
    and conditioned on the event $\{X_{t}<\infty \}$, $X_{t}$ converges weakly to $X$. In particular, for all $x \in [0,\infty)$ which is a point of continuity for  $\mathbb{P}(X\leq x)$, $\mathbb{P}\left(X_{t}\le x\right) \to \mathbb{P}\left(X\le x\right)$ as $t\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $\mu$ and $\eta$ be two finite measures. Then the following holds:
	\begin{enumerate}
		\item[(i)]
		For all $t > 0$ it holds that
		\begin{equation*}
			V_t(\mu+ \eta)(x) \leq V_t(\mu)(x) + V_t (\eta)(x), \quad x\in\R.
		\end{equation*}
		\item[(ii)] If $\mu \leq \eta$, then 
		\begin{equation*}
			V_t(\mu)(x) \leq V_t(\eta)(x),\quad x\in \R,
		\end{equation*}
		for all $t > 0$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2608.29501, 'Disorder Thresholds and Free Energy of Brownian Directed Polymers with\\ Product and Radia'] Let \(0<\alpha<1\) and let \(Z\sim N(0,1)\).  There is
\(C_\alpha<\infty\) such that, for every \(a\in\R\) and \(s\ge0\),
\begin{equation}
  \E\big[(1+|a+\sqrt sZ|)^{-\alpha}\big]
  \le C_\alpha(1+s)^{-\alpha/2}.

\end{equation}
For every \(L<\infty\), there is \(c_{\alpha,L}>0\) such that
\begin{equation}
  |a|\le L\sqrt s
  \quad\Longrightarrow\quad
  \E\big[(1+|a+\sqrt sZ|)^{-\alpha}\big]
  \ge c_{\alpha,L}(1+s)^{-\alpha/2}.

\end{equation}

