[Thm config3 of arXiv:2506.01306, 'Asymptotic of Coulomb gas integral, Temperley-Lieb type algebras and pure partition functi'] \indent
\begin{itemize}
 \item[Configuration 1] Neither $x_i$ nor $x_{i+1}$ are endpoints of an integration contour of $\mathcal{J}^{(m,n)}_\alpha(\boldsymbol{x})$. 


\begin{equation}
   \lim_{x_i,x_{i+1}\rightarrow p} (x_{i+1}-x_i)^{\frac{6}{\kappa}-1}\mathcal{J}^{(m,n)}_\alpha(\boldsymbol{x}) = 0   
\end{equation}


\item[Configuration 2] Both $x_i$ and $x_{i+1}$ are endpoints of a single, common integration contour $\Gamma_1$ of $\alpha$. Hence, this contour is $\Gamma_1=\mathscr{P}\left(x_i, x_{i+1}\right)$ or $\left[x_i, x_{i+1}\right]^{+}$. (The superscript + indicates that we form the contour $\left[x_i, x_{i+1}\right]^{+}$by slightly bending $\left[x_i, x_{i+1}\right]$ into the upper half-plane, keeping the endpoints fixed.)

\begin{equation}
   \lim_{x_i,x_{i+1}\rightarrow p} (x_{i+1}-x_i)^{\frac{6}{\kappa}-1}\mathcal{J}^{(m,n)}_\alpha(\boldsymbol{x}) = n(\kappa) \mathcal{J}^{(m,n)}_{\hat{\alpha}} (\boldsymbol{\hat{x}} )
\end{equation}


\item[Configuration 3] Either $x_i$ or $x_{i+1}$ is an endpoint of a single integration contour $\Gamma_1$ of $\mathcal{J}^{(m,n)}_\alpha(\boldsymbol{x})$, but the other is not an endpoint of any contour. 

We assume that $i>1, \kappa>4, x_i$ is an endpoint of $\Gamma_1$, and $\Gamma_1$ does not pass over the interval $\left(x_i, x_{i+1}\right)$.

With $\kappa>4$, $\Gamma_1$ is a simple contour, and we decompose it into one simple contour $\Gamma_1^{\prime}$ with its right endpoint at $x_{i-1}$ and another $\Gamma_1^{\prime \prime}$ with its endpoints at $x_i$ and $x_{i-1}$. (We might have $\Gamma_1^{\prime}=\emptyset$ and $\Gamma_1=\Gamma_1^{\prime \prime}$.) Also, the limit breaks into
\begin{equation} 
\begin{aligned}
\lim _{x_{i}, x_{i+1}\rightarrow p}\left(x_{i+1}-x_i\right)^{6 / \kappa-1} \mathcal{J}^{(m,n)}_\alpha= & \lim _{x_{i+1} \rightarrow x_i}\left(x_{i+1}-x_i\right)^{6 / \kappa-1}\left(\left.\mathcal{J}^{(m,n)}_\alpha\right|_{\Gamma_1 \mapsto \Gamma_1^{\prime}}\right) \\
& +\lim _{x_{i+1} \rightarrow x_i}\left(x_{i+1}-x_i\right)^{6 / \kappa-1}\left(\left.\mathcal{J}^{(m,n)}_\alpha\right|_{\Gamma_1 \mapsto \Gamma_1^{\prime \prime}}\right) .
\end{aligned}
\end{equation}
The first limit on the right side of (config3 of the paper) falls under case 1 and, therefore, vanishes. Meanwhile, the second limit on the right side of (config3 of the paper)  still falls under case 3. 

\begin{equation}
   \lim_{x_i,x_{i+1}\rightarrow p} (x_{i+1}-x_i)^{\frac{6}{\kappa}-1}\mathcal{J}^{(m,n)}_\alpha(\boldsymbol{x}) = \mathcal{J}^{(m-1,n)}_{\hat{\alpha}} (\boldsymbol{\hat{x}} )
\end{equation}

\item[Configuration 4]  $x_i$ is an endpoint of one contour $\Gamma_1$ , and $x_{i+1}$ is an endpoint of a different contour $\Gamma_2$.

With $\kappa>4$ and $\Gamma_1$ and $\Gamma_2$ simple contours, we decompose $\Gamma_1$ (resp. $\Gamma_2$ ) into one simple contour $\Gamma_1^{\prime}$ (resp. $\Gamma_2^{\prime}$ ) with an endpoint at $x_{i-1}$ (resp. $x_{i+2}$ ) and another $\Gamma_1^{\prime \prime}$ (resp. $\Gamma_2^{\prime \prime}$ ) with its endpoints at $x_{i-1}$ and $x_i$ (resp. $x_{i+1}$ and $x_{i+2}$ ). In some cases, we might have $\Gamma_1^{\prime}=\emptyset$ and $\Gamma_1^{\prime \prime}=\Gamma_1$ (resp. $\Gamma_2^{\prime}=\emptyset$ and $\Gamma_2^{\prime \prime}=\Gamma_2$ ). This decomposition contains within it three sub-cases: neither $\Gamma_1$ nor $\Gamma_2$ passes over $\left(x_i, x_{i+1}\right)$, only $\Gamma_2$ passes over $\left(x_i, x_{i+1}\right)$, or only $\Gamma_1$ passes over $\left(x_i, x_{i+1}\right)$. Similarly, the limit decomposes into
\begin{equation}
\begin{aligned}
\lim _{x_{i}, x_{i+1}\rightarrow p}\left(x_{i+1}-x_i\right)^{6 / \kappa-1} \mathcal{J}^{(m,n)}_\alpha & =\lim _{x_{i+1} \rightarrow x_i}\left(x_{i+1}-x_i\right)^{6 / \kappa-1}\left(\left.\mathcal{J}^{(m,n)}_\alpha\right|_{\left(\Gamma_1, \Gamma_2\right) \mapsto\left(\Gamma_1^{\prime}, \Gamma_2^{\prime}\right)}\right) \\
& +\lim _{x_{i+1} \rightarrow x_i}\left(x_{i+1}-x_i\right)^{6 / \kappa-1}\left( (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 8 of arXiv:2608.09419, 'Left-tail expansions for Schr\"oder branching processes with explicit convergence rates'] \lb{C1}
 Under assumptions of Theorem \ref{T1}, suppose also that 
\[\lb{c001}
 1-\{re^{i\vp}:\ \vp\in(-\vp_0,\vp_0),\ r\in(0,r_0)\}\ss\mJ_P(0).
\]
Then $\Pi(z)$ can be analytically extended to the sector $S_{\vp_0}:=\{z:\ |\arg z|<\vp_0\}$. The image of this sector satisfies $\Pi(S_{\vp_0})\ss\mJ_P(0)\cup\{1\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Le33 of arXiv:2411.09949, '$W_{\bf d}$-convergence rate of EM schemes for invariant measures of supercritical stable '] Suppose that for some $\gamma \in [0,1]$ and $\kappa_0 > 1$,
\begin{align}
\kappa_0^{-1} |\xi| \leqslant |\sigma(x) \xi| \leqslant \kappa_0 |\xi|, \quad \|\sigma(x) - \sigma(y)\| \leqslant \kappa_0 |x - y|^\gamma.
\end{align}
Let $\jmath(x,z) := (|z| / |\sigma^{-1}(x) z|)^{d+\alpha} / \det(\sigma(x))$. Then, for any $x, v \in \mathbb{R}^{d}$,
\begin{align}
\mathscr{L}^{(\alpha)}_{\sigma(x)} f(v)
= \frac{1}{2} \int_{\mathbb{R}^d} \delta^{(2)}_z f(v) \frac{\jmath(x, z)}{|z|^{d+\alpha}} \, \mathrm{d} z,
\end{align}
and there exists a constant $\widetilde\kappa_0 > 1$ such that for all $x, y, z \in \mathbb{R}^d$,
\begin{align}
\widetilde\kappa_0^{-1} \leqslant \jmath(x, z) \leqslant \widetilde\kappa_0, \quad |\jmath(x, z) - \jmath(y, z)| \leqslant \widetilde\kappa_0 |x - y|^\gamma.
\end{align}

[Lemma lem:limit and functional of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] If $\phi$ is a Banach-Mazur limit, then 
		\[\liminf_{n\to \infty}x_n\le \phi(\mathbf{x})\le\limsup_{n\to\infty}x_n\]
		for each $\mathbf{x}=(x_1,x_2,\cdots)\in \ell^\infty$. In particular, if the limit $\lim_{n\to\infty}x_n$ exists, then $\phi(\mathbf{x})= \lim_{n\to\infty}x_n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

