[Theorem 4 of arXiv:2605.11279, 'Flocking with Multiple Types: Competition, Fluid Limits and Traveling Waves'] Suppose the jump steps are independent $\expo(1)$ random variables; that is, $Z \sim \expo(1)$. 
    \begin{enumerate}[label = (\alph*)]
        \item  For a traveling wave solution $H = \parens*{H_+, H_-}$ for \eqref{originalFluid} with mass partition $(\rho^+, \rho^-)$ and speed $\gamma$ to exist, we must necessarily have
        \begin{align*}
            \rho^+ &= \dfrac{1 - \alpha^+ - \alpha^- + \dsqrt{\parens*{1 - \alpha\displaystyle^+ - \alpha\displaystyle^-}^2 + 4\alpha^-}}{2}, \\
            \rho^- &= \dfrac{1 + \alpha^+ + \alpha^- - \dsqrt{\parens*{1 - \alpha\displaystyle^+ - \alpha\displaystyle^-}^2 + 4\alpha^-}}{2}, \\
            \intertext{and} 
            \gamma &= v_+\rho^+ + v_-\rho^- \\
            &= \dfrac{\parens*{v_+ + v_-} + \parens*{v_+ - v_-} \parens*{\dsqrt{\parens*{1 - \alpha\displaystyle^+ - \alpha\displaystyle^-}^2 + 4\alpha\displaystyle^-}-\alpha\displaystyle^+ - \alpha\displaystyle^-}}{2}.
        \end{align*}
        In particular, $\rho^+ = \rho^- = \dfrac{1}{2}$ if and only if $\alpha^+ - \alpha^- = \dfrac{1}{2}$.

        \item  Suppose $v_+ > v_- = 0$. Then a traveling wave solution $H = (H_+, H_-)$ exists; furthermore, it satisfies the following:
        \begin{enumerate}[label = (\arabic*)]
            \item  For each $t\in\real$, $H_+(t) \geq H_-(t)$;

            \item  The ``asymptotic right-tail exponent'' for the traveling wave is given by
            \begin{align*}
                \lim_{t\to-\infty} \dfrac{\log H_\pm(t)}{t} &= \dfrac{v_+-\gamma+\alpha^+ +\alpha^- +\rho^+-\rho^-}{2\gamma} \\
                &-\dfrac{1}{2} \sqrt{\parens*{\!\dfrac{v_+ - \gamma +\alpha^+ - \alpha^- -1}{\gamma}\!}^2 + \dfrac{4\parens*{\alpha\displaystyle^+ -\rho\displaystyle^-} \parens*{\rho\displaystyle^+ +\alpha\displaystyle^-+\gamma}}{\gamma\displaystyle^2}\!} > 0,
            \end{align*}
            where the quantity in the square root is necessarily positive.

            \item  The ``asymptotic left-tail exponent'' is given by 
            \begin{align*}
                \lim_{t\to\infty}\!\curlbr*{\!-\dfrac{\log\sqbr*{1\!-\!H_\pm(t)}}{t}\!}\!=\!-\dfrac{v_+\!-\!\gamma\!+\alpha^+\! +\!\alpha^-}{2\gamma}\!+\! \dfrac{1}{2}\sqrt{\!\parens*{\!\dfrac{v_+ - \gamma\!+\!\alpha^+\!-\!\alpha^-}{\gamma}\!}^2\!+\!\dfrac{4\alpha\displaystyle^+ \parens*{\alpha\displaystyle^-\!+\!\gamma}}{\gamma\displaystyle^2}}\!>\!0.
            \end{align*}
        \end{enumerate}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop CM UT LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exists a deterministic constant $c_3 \in (0,\infty)$ such that, 
  for any $x_0 \in M$, $r \in (0, 1 \wedge r_*)$, and $n, N \in \mathbb{N}$ with $4n \leq N$ and $c_1 Nr^{d^{\mathrm{min}}_\mathrm{w}} < 1 \wedge t_*$,
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0, r)}
    \hat{P}_{\bm{x}}\!\left(\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r)) \geq c_3 n r^{d_{\mathrm{cp}}}\right) 
    \geq 
    \tilde{c}_1 e^{-\tilde{c}_2 n},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} > 2,
  \end{equation}
  and 
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0, r)}
    \hat{P}_{\bm{x}}\!\left(\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r)) \geq c_3 n r^{d_{\mathrm{f}}} \log (N/n)\right) 
    \geq 
    \tilde{c}_1 e^{-\tilde{c}_2 n},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} = 2.
  \end{equation}

[Lemma Phi-1Lip of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] For every $n\geq 0$ and all $x,y\in \lbrack 0,1]$, 
\begin{equation}
|\Phi _{n}(x)-\Phi _{n}(y)|\leq |x-y|.  
\end{equation}
In particular, the family $(\Phi _{n})_{n\geq 0}$ is equicontinuous and
uniformly bounded on $[0,1]$.

