body:
[Theorem thm:B of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha\in (\frac{d}{2},d)$ and $(\zeta,\gamma) \in R_2$ (see Figure (diagram2 of the paper)).
Then $(S_n)_{0\leq n \leq N}$ has end-to-end fluctuations of order $N^{\xi}$ under ${\ensuremath{\mathbf P}} _N$, where $\xi= \frac{\alpha (1-\gamma)}{2\alpha-d} \in (\frac12,1)$.
Additionally, as $N\to\infty$, we have the following convergence in distribution to a well-defined random variable,
\begin{equation}

\frac{1}{N^{2\xi -1}}\log {\ensuremath{\mathbf Z}} _N \overset{(d)}{\longrightarrow}{\ensuremath{\mathcal T}} _{\hat{\beta}} :=\sup_{s\in {\ensuremath{\mathcal D}} , \mathrm{Ent}(s) <+\infty} 
\big\{ \hat{ \beta} \pi(s) -  \mathrm{Ent}(s) \big\}.
\end{equation}
Here $\pi(s):=\sum_{(x,\omega)\in{\ensuremath{\mathcal P}} }\omega\mathbbm{1}_{\{x\in s[0,1]\}}$, where ${\ensuremath{\mathcal P}} $ is the  Poisson point process introduced in Theorem (thm:R1b of the paper) and
\begin{equation}
{\ensuremath{\mathcal D}} :=\{s:[0,1]\to{\ensuremath{\mathbbm R}} ^d: s(0)=0.~s~\text{is continuous and a.e. differentiable}\},
\end{equation}
and
\begin{equation}
\mathrm{Ent}(s):=\frac d2\Big(\int_0^1\|s'(t)\|{\ensuremath{\mathrm d}}  t\Big)^2.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 of arXiv:2506.08910, 'Critical points of random polynomials and finite free cumulants'] Let $\{q_N\}_{N=1}^{\infty}$ be a sequence of real rooted polynomials indexed by their degree of the form \begin{equation}
			q_{N}(x)=\prod_{j=1}^{N}\left(x-X_{j,N}\right).
		\end{equation} We say a sequence of polynomials $\{q_{N}\}$ is generated by the L\'evy triple $(c,\sigma^2,\nu)$ if \begin{enumerate}
		\item For any $N\in\N$, $X_{1,N}, X_{2,N},\dots, X_{N,N}$ are iid random variables. 
		\item There exists $\sigma\geq 0$, $c\in\R$, and a measure $\nu$ on $\R$ satisfying \begin{equation}
			\int_{\R}\min(x^2,1)\ \dd \nu(x)<\infty,\quad\text{and}\quad \nu(\{0\})=0,
		\end{equation} such that  $S_{N}=\sum_{j=1}^{N}X_{j,N}$ converges in distribution as $N\rightarrow\infty$ to a random variable $Y$ with log-characteristic function  \begin{equation}
		\log\E e^{itY}=-\frac{\sigma^2}{2}t^2+itc+\int_{\R}\left(e^{itx}-1-\frac{itx}{1+x^2}\right)\dd\nu(x).
	\end{equation}
	\end{enumerate}

