body:
[Theorem 9 of arXiv:2605.29608, '2605.29608'] Let $(Y_{k})_{k\in\mathbb{Z}^{+}}$ and $\mu_{N}$ be defined as in Theorem \ref{thm: transitionmatrix}. If the coupling constant $\hat{J}\in [0,+\infty)$, then for any real-valued function $f:\Omega\to\mathbb{R}$, we have
	\begin{align*}	
		\left\|\frac{1}{M}\sum_{k=1}^{M}P_{\text{W}}^{k}f-E_{\mu_{N}}[f]\right\|_{L^{2}(\mu_{N})}
		\leq\frac{\|f\|_{L^{2}(\mu_N)}}{M}\bigg(2+ \frac{e^{2\hat{J}}(e^{4\hat{J}}+1)}{2}\big(\frac{1}{2}+\hat{J}e^{\frac{e^{2\hat{J}}-1}{2}}\big)N\bigg),
	\end{align*}
	where $\|\cdot\|_{L^{2}(\mu_N)}$ denotes the norm associated with the inner product $\langle \cdot, \cdot \rangle_{\mu_N}$, and
	\begin{align*}
		P_{\text{W}}^{k}f(x)=\sum_{y\in\Omega}f(y) P^{k}_{\text{W}}(x,y),\qquad x\in\Omega, 1\leq k\leq M.
	\end{align*}
	Moreover,
	\begin{align*}
		E^{\mathbb{P}_{\mu_{N}}}\left[\left( \frac{1}{M}\sum_{k=1}^{M}f(Y_{k})-E_{\mu_{N}}[f]\right)^{2}\right]
		\leq\frac{\|f\|^{2}_{L^{2}(\mu_N)}}{M}e^{2\hat{J}}(e^{4\hat{J}}+1)\big(\frac{1}{2}+\hat{J}e^{\frac{e^{2\hat{J}}-1}{2}}\big)N,
	\end{align*}	
	where $\mathbb{P}_{\mu_{N}}$ denotes the law of the process started from $\mu_N$.

