[Lemma lem:nonrevup of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $\varepsilon \in (0, 1]$. Suppose $\Phi_{\ast}^{(n)} \geqslant c_1$ for some constant $c_1 > 0$. For constant $\theta > 0$, let
    \begin{equation*}
        t_n = mn (t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n}) + \theta), \text{ and } t_n' = mn (t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n}) - \theta),
    \end{equation*}
    for $n \in \mathbb{N}$. Then there are constants $\theta, C > 0$ so that $\pi(\mathrm{Centre}(C)) \geqslant 1 - \varepsilon$, and the following hold.
    \begin{enumerate}[label=(\alph*)]
        \item For all $\mathbf{x} \in \Omega_n$ and $n$ large enough, we have
        \begin{equation*}
            \Ps{\mathbf{x}}{X^{(n)}_{t_n} \in {\mathrm{Centre}(C)}} > 1-\varepsilon.
        \end{equation*}
        \item We can find a sequence of starting states $(\mathbf{x}_n)_{n \geqslant 1}$ such that for $n$ large enough, we have
        \begin{equation*}
            \Ps{\mathbf{x}_n}{X^{(n)}_{t_n'} \in {\mathrm{Centre}(C)}} < \varepsilon.
        \end{equation*}
    \end{enumerate}

