body:
[Proposition 9 (Riemann curvature of the ansatz metric) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] For the metric \eqref{eq:ansatz-metric}, with $X, Y, Z, W$ basic horizontal, $\xi^* = \xi/H$ the unit Reeb field, and $\nu = \partial_s$:

	\emph{(i) Horizontal components.}
	\begin{equation}
		\begin{aligned}
			&\mathrm{Rm}_g(X, Y, Z, W) \;=\; \mathrm{Rm}_{g_s}(X, Y, Z, W) \\
			& \;+\; \frac{1}{4} \sum_{i,j=1}^r (q_i H + \kappa_i)(q_j H + \kappa_j) \Big( \pi^*g_i(X_i, Z_i)\, \pi^*g_j(Y_j, W_j) \;-\; \pi^*g_i(X_i, W_i)\, \pi^*g_j(Y_j, Z_j) \Big),
		\end{aligned}
	\end{equation}
	with $\mathrm{Rm}_{g_s}$ given by \eqref{eq:leaf-curvature}; moreover $\mathrm{Rm}_g(X, Y, Z, \xi^*) = 0$.

	\emph{(ii) Vertizontal components.}
	\begin{equation}
		\mathrm{Rm}_g(X, \xi^*, \xi^*, Y) \;=\; \frac{1}{4} \sum_{i=1}^r \frac{(q_i H)^2}{F_i^2}\; \pi^*g_i(X_i, Y_i) \;-\; \frac{H'}{2H} \sum_{i=1}^r \big( q_i H + \kappa_i \big)\, \pi^*g_i(X_i, Y_i) .
	\end{equation}

	\emph{(iii) Codazzi components.} The only non-vanishing components with exactly one $\nu$-slot are
		\begin{equation}
		\mathrm{Rm}_g(X, Y, \xi^*, \nu) \;=\; 2\, \mathrm{Rm}_g(X, \xi^*, Y, \nu) \;=\; \sum_{i=1}^r q_i H \left( \frac{F_i'}{F_i} - \frac{H'}{H} \right) \pi^*\omega_i(X_i, Y_i) ;
	\end{equation}
	in particular $\mathrm{Rm}_g(X, Y, Z, \nu) = 0$ and $\mathrm{Rm}_g(X, \xi^*, \xi^*, \nu) = 0$.

	\emph{(iv) Radial components.}
	\begin{align}
			\mathrm{Rm}_g(X, \nu, \nu, Y) &\;=\; -\sum_{i=1}^r F_i F_i''\; \pi^*g_i(X_i, Y_i), \nonumber \\

			\mathrm{Rm}_g(\xi^*, \nu, \nu, \xi^*) &\;=\; -\frac{H''}{H}, \\
			\mathrm{Rm}_g(X, \nu, \nu, \xi^*) &\;=\; 0 .\nonumber
	\end{align}

	Together with the symmetries of the curvature tensor, (i)--(iv) determine $\mathrm{Rm}_g$ completely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Pro 6 of arXiv:2605.30779, '2605.30779'] Let \(\beta\in\{1,2\}\) and \(\{\xi_{\beta,j}\}_{j\ge1}\) be i.i.d.\ random variables, independent of \(\{a_{\beta,j}^{\Theta}\}_{j\ge1}\), with \(\xi_{\beta,j}^2\sim\chi_\beta^2\). Define the Airy-Green function
  \begin{equation}
    \mathcal G^{(\beta)}_{\Theta}(w)
    :=
    \lim_{x\to-\infty}
    \left[
      \sum_{j:\,a_{\beta,j}^{\Theta}>x}
      \frac{\beta^{-1}\xi_{\beta,j}^2}{w-a_{\beta,j}^{\Theta}}
      -\frac{2}{\pi}\sqrt{-x}
    \right].
  \end{equation}
  For every fixed finite vector \(\Theta\), the limit in \eqref{eq:defn_Airy_Green_multiple} exists almost surely for every
  \[
    w\in
    \mathbb C\setminus
    \bigl\{
    a_{\beta,j}^{\Theta}:j\ge1
    \bigr\},
  \]
  uniformly on compact subsets avoiding the poles. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm intro3 of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\varphi(x)=|x|^{-s}$ for $0<s<1$ or $\varphi(x)=-\log|x|$.    Let $\mathsf{P}_0,\mathsf{P}_1$ be the laws of two stationary point processes with unit intensity with $\mathcal F^{elec}_{\beta}(\mathsf{P}_i)<\infty$, $i=0,1$. Then there exists a coupling $ \mathsf{Q}^0$ of $\mathsf{P}^0_0$ and $\mathsf{P}^0_1$ such that for $0\leq t\leq 1$ ($s=0$ corresponding to the $\log$ case)
    \begin{align*}
        \mathcal F^{elec}_{\beta}(\mathsf{P}_{t})&\leq  (1-t) \mathcal F^{elec}_{\beta}(\mathsf{P}_{0})+t\mathcal F^{elec}_{\beta}(\mathsf{P}_{1})\\
        &-\frac{(\mathbbm{1}_0(s)+s(s+1))(1-t)t\beta}{4}\int \sum_{(0,0)\neq (x,y)\in \bar\xi} (x-y)^2\inf_{z\in [x,y]}\left\lvertz\right\rvert^{-s-2} \mathsf{Q}^0(d\bar\xi).
    \end{align*}
In particular, $\mathcal F^{elec}_{\beta}$ has a unique minimizer. (Proof in the paper; no proof environment follows the statement in the TeX.)

