[Prop 8 (Maximum principle with one boundary for \eqref{moving frame-u}) of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] For any fixed $t_*\ge 0$ and for any  continuous  function $X(t,i)$ defined for $t\ge i+t_*$ and $i\in[0,i_\dagger)$  satisfying $X(t,i)$  for each $i\in[0,i_\dagger)$ is nondecreasing in $t\in(i+t_*,+\infty)$, and  $X(t,0)\ge \max_{s\in[0,i]}X(t-i+s,s)$, let $u(t,i,x)$ be a  bounded and continuous  function defined for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and  $x\ge X(t,i)-R$,  such that
	\begin{equation}

		\begin{aligned}
			\left\{\begin{split}
				&	\partial_t u(t,i,x)  + \partial_i u(t,i,x) \le 0,~~~~~~~ ~~~~~~~~~~~~~~~~~t\ge i+t_*, ~i\in(0,i_\dagger), ~x\ge X(t,i) -R, \\
				&	u(t,0,x)\le \S_0 \int_0^{i_\dagger} \omega(i) e^{-\alpha_*c_* i} \K_* *u(t,i,x)\md i,  ~~~~~~~~~~~~~~~~~~~t\ge  i_\dagger+t_*,   ~x\ge X(t,0).
			\end{split}\right.		
		\end{aligned}
	\end{equation}
	Assume further that $u(t,0,x)\le0$ for $t\in [ t_*,i_\dagger+t_*]$ and $x\ge X(t,0)$, that\footnote{For this boundary assumption, it will be sufficient to assume: $u(t,i,x)\le 0$ for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and $x\in[X(t,i)-R,X(t,i)]$.}  $u(t,0,x)\le 0$ for $t\ge t_*$ and $x\in[X(t,0)-R,X(t,0)]$, and $u(t,i,X(t,i))\le 0$ for $t\ge i+i_\dagger+t_*$ and $i\in[0,i_\dagger)$, then $u(t,i,x)\le 0$  for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lemma-Kernel-Identification of arXiv:2609.01964, 'The critical exponent for the two-dimensional semilinear wave equation with strong damping'] For every fixed $r>0$, the inverse Fourier representation of $G_1^{(2)}(t,r)$ defines a function in $\mathcal C\bigl((0,\infty)\bigr)\cap L^1_{\mathrm{loc}}\bigl([0,\infty)\bigr)$. Moreover, for every $T>0$, one estimates
	\begin{align}
		|G_1^{(2)}(t,r)|\lesssim_T1+|\log r|
	\end{align}
	for $0<t\leqslant T$ and $0<r\leqslant1$. Furthermore,
	\begin{align}
		G_1^{(2)}(t,r)\geqslant0
	\end{align}
	for every $t>0$ and $r>0$.

