body:
[Prop wired random cluster properties of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] The following properties hold. Fix $\Lambda\subset \mathbb Z^d$ and $\beta\geq 0$.
\begin{enumerate}
\item[$\bullet$]\textup{(Domain Markov Property)} For every $\Lambda' \subset \Lambda$, every $\theta\in \{0,1\}^{\overline E(\Lambda[\mathsf{h}]) \setminus \overline E(\Lambda'[\mathsf{h}])}$, and every $\mathsf{s}\in (\mathbb R^+)^{\overline{\Lambda}\setminus\Lambda'}$ satisfying $\mathsf{s}_{|\partial^{\textup{ext}} \Lambda}=\mathsf{b}$,
\begin{equation}
\Psi^{1}_{\Lambda,\beta,\mathsf{h}}[(\omega,\mathsf{a}) \mid (\omega|_{\overline E(\Lambda[\mathsf{h}])\setminus \overline E(\Lambda'[\mathsf{h}])},\mathsf{a}|_{\overline{\Lambda}\setminus \Lambda'})=(\theta,\mathsf{s})]=\Psi^{(w^\theta,\mathsf{s})}_{\Lambda',\beta,\mathsf{h}_{|\Lambda'}}[(\omega,\mathsf{a})],
\end{equation}
where $w^{\theta}$ is the partition of $(\partial^{\mathrm{ext}} \Lambda')^{\mathfrak{g}}$ where $x,y$ are in the same partition class if and only if they are in the same connected component in the graph obtained from  $((\overline{\Lambda}\setminus \Lambda')^{\mathfrak g}, \{ e \in \overline E(\Lambda[\mathsf h])\setminus \overline E(\Lambda'[\mathsf h]):\theta_e=1\})$ by identifying the vertices in the elements of the wired partition $w$. 

\item[$\bullet$] \textup{(Absolute value FKG inequality)} For every  $A \subset \overline \Lambda$, $\eta \in (\mathbb R^+)^A$, and all increasing and square integrable functions $F,G: (\mathbb{R}^+)^{\overline{\Lambda} \setminus A}\to\mathbb{R}$, 
\begin{equation} 
\mu_{\Lambda,\beta,\mathsf{h}}^{1}[F\cdot G \mid \mathsf a|_A=\eta]\geq \mu_{\Lambda,\beta,\mathsf{h}}^{1}[F \mid \mathsf a|_A=\eta]\mu_{\Lambda,\beta,\mathsf{h}}^{1}[G \mid \mathsf a|_A=\eta].
\end{equation}
    \item[$\bullet$] \textup{(FKG inequality)} For every $A \subset \overline\Lambda$, $\eta \in (\mathbb R^+)^A$, and all increasing and square-integrable functions $F,G: \{0,1\}^{\overline E(\Lambda[\mathsf h])}\times (\mathbb R^+)^{\overline{\Lambda}}\to\mathbb{R}$,
we have
\begin{equation} 
\Psi_{\Lambda,\beta,\mathsf{h}}^{1}[F\cdot G \mid \mathsf a|_A=\eta]
\geq
\Psi_{\Lambda,\beta,\mathsf{h}}^{1}[F \mid \mathsf a|_A=\eta] \Psi_{\Lambda,\beta,\mathsf{h}}^{1}[G \mid \mathsf a|_A=\eta].
\end{equation}
\item[$\bullet$] \textup{(Comparison to the free measure)} One has
    \begin{equation}
    \Psi^0_{\Lambda,\beta,\mathsf{h}}\preccurlyeq \Psi^{1}_{\Lambda,\beta,\mathsf{h}}.
\end{equation}
\item[$\bullet$]\textup{(Monotonicity in parameters)} For every $A\subset \overline\Lambda$, every $\eta_1,\eta_2\in (\mathbb{R}^+)^{A}$ such that $\eta_1\leq \eta_2$, every external magnetic fields $\mathsf{h}_1,\mathsf{h}_2\in (\mathbb R^+)^\Lambda$ with $\mathsf h_1\leq \mathsf h_2$, and every $0\leq\beta_1\leq \beta_2$ we have
\begin{equation} 
\Psi_{\Lambda,\beta_1,\mathsf h_1}^1[\:\cdot \mid \mathsf{a}|_A=\eta_1] \preccurlyeq \Psi_{\Lambda,\beta_2,\mathsf h_2}^1[\:\cdot \mid \mathsf{a}|_A=\eta_2].
\end{equation}
    \item[$\bullet$] \textup{(Monotonicity in domain with gap)} Let $\beta,h \geq 0$. There exists $r=r(\beta,h)>0$ such that, for every $\Lambda_1 \subset \Lambda_2 \subset \mathbb Z^d$ finite and such that $\mathrm{d}(\Lambda_1, \partial \Lambda_2) \geq r$, and every $\mathsf h_1 \in (\mathbb R^+)^{\Lambda_1}$ and $\mathsf h_2 \in (\mathbb R^+)^{\Lambda_2}$ such that $\mathsf h_1 \geq (\mathsf h_2)_{|_{\Lambda_1}}$, $\mathsf h_1,\mathsf{h}_2\leq h$, we have that
    \begin{equation}
        \Psi^1_{\Lambda_1, \beta, \mathsf h_1} \succcurlyeq \Psi^1_{\Lambda_2, \beta, \mathsf h_2}. 
    \end{equation}
\end{enumerate}

[Lemma dir_E[multi_edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e^{\textnormal{tail}} = \delta^{\textnormal{tail}}\in O(1)$ and $\delta_e^{\textnormal{head}} = \delta^{\textnormal{head}}\in O(1)$ and
\begin{enumerate}
    \item $\mathds{E}[(d_U^{\textnormal{out}})^{2\delta^{\textnormal{tail}}}], \mathds{E}[(d_U^{\textnormal{in}})^{2\delta^{\textnormal{head}}}] \in o(n)$
    \item $\exists c>0: \mathds{P}(d_U^{\textnormal{out}} \geq 2\delta^{\textnormal{tail}}),\mathds{P}(d_U^{\textnormal{in}} \geq 2\delta^{\textnormal{head}}) \geq c$ 
\end{enumerate}
then
\begin{align*}
    \mathds{E}[M_n] &= \frac{(\delta^{\textnormal{tail}}-1)!(\delta^{\textnormal{head}}-1)!}{2} n^2 \mathds{E}[d_U^{\textnormal{out}}] \mathds{E}[d_U^{\textnormal{in}}] \\
    &\hspace{0.5cm} \times \Big( \frac{\mathds{E}[(d_U^{\textnormal{out}})^2] - \mathds{E}[d_U^{\textnormal{out}}]}{n \mathds{E}[d_U^{\textnormal{out}}]^2} \Big)^{\delta^{\textnormal{tail}}} \Big(  \frac{\mathds{E}[(d_U^{\textnormal{in}})^2] - \mathds{E}[d_U^{\textnormal{in}}]}{n \mathds{E}[d_U^{\textnormal{in}}]^2} \Big)^{\delta^{\textnormal{head}}} (1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:xi of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] We say that $(S_n)_{0\leq n\leq N}$ has end-to-end fluctuations $r_N$ under ${\ensuremath{\mathbf P}} _N$, if for any $\varepsilon>0$, there exists some $\eta\in(0,1)$, such that for $N$ large enough,
\begin{equation*}
{\ensuremath{\mathbbm P}} \Big({\ensuremath{\mathbf P}} _N\Big(\max_{0\le n\le N}|S_n|\in[\eta,\eta^{-1}]r_N\Big)>1-\varepsilon\Big)>1-\varepsilon.
\end{equation*}
If $r_N$ is of the form $N^\xi$, then $\xi$ is the end-to-end exponent.

[Prop eq:OP_BT of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For $\mu > - \frac12$, ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with $k_j > -1$, $1 \le j \le d_2$, define 
\begin{equation} 
 \bm Q_{\bm j, \bm k, m}^n(\bm x,\bm y) = \bm T_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) (1-|\bm y|)^m 
      \bm B_{\bm k, m}^\mu \left(\frac{\bm x}{1-|\bm y| }\right),
\end{equation}
where $\alpha = 2 \mu + d_1-1$. Then
$\{\bm Q_{\bm j, \bm k, m}^n: |\bm k| = m, \, |\bm j| = n-m, \, \bm k \in {\mathbb N}_0^{d_1}, \, \bm j \in {\mathbb N}_0^{d_2}, 0\le m \le n\}$ 
is an orthogonal basis of ${\mathcal V}_n\big({\mathbb B}^{d_1}\!\! \rtimes\triangle^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}\big)$. 
Moreover, the norm square of $\bm Q_{\bm j, \bm k, m}^n$ is given by 
\begin{equation} 
   \bm h_{\bm j, \bm k, m}^{n; \mu,{\boldsymbol{\kappa}}}  

       = \frac{(2\mu+d_1)_{2m}} {(|{\boldsymbol{\kappa}}|+ 2\mu + d_1 + d_2)_{2m}}\bm h_{\bm k,m}^{\mu, {\mathbb B}}  
       \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+2m), \triangle}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainthm thm:OdeltaRWintro of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Let $k\in \mathbb{N}$ and $\rho_\ell$ be a bounded sequence.
When $\alpha\in[0,1)$, the scaling bound in (equation eq:scalimRW of the paper) is a scaling limit with error
\begin{equation} 
\delta_{[\alpha\ell-\beta_\ell,\ell]}^M=\mathrm{O}\left(\frac{\beta_\ell+1}{\ell}\right) =o(1),
\end{equation}
When $\alpha=1$, the scaling error in (equation eq:scalimRW of the paper) is 
\begin{equation} 
\delta_{[\ell-\beta_\ell,\ell]}^M
=\mathrm{O}\left( \frac{\ell}{\beta_\ell} \delta_{[0,\ell]}^M\right) +\mathrm{O}(1)\begin{cases}
    \frac{\beta_\ell}{\ell} & n\ge 3
    \\
    m_\ell \sqrt{\frac{\beta_\ell}{\ell}} 
    & n =2 
    \\
    m_\ell^2& n =1
\end{cases},
\end{equation}
as $\ell\to +\infty$, for all $\alpha\in [0,1]$, where
\begin{equation} 
m_\ell:=\sqrt{
    \min\left\{\max\left\{ \frac{\beta_\ell}{\ell}, \beta_\ell\rho_\ell\right\},1 \right\}.
    }
    \end{equation}
 In particular, the $\mathcal{C}^k$ Scaling Bound of Random Waves of type $\alpha=1$ in fixed range $[0,\rho]$, with $\rho=\rho_\ell$, is a scaling limit, that is,  $\delta^M_{I_\ell}=\mathrm{o}(1)$, under either of the following (sufficient) conditions:
\begin{enumerate}[(i)]
    \item $n\ge 2$ and $\beta_\ell\to +\infty$;
    \item $n\ge 2$, $\frac 1{\beta_\ell}$ is bounded, and $\delta_{[0,\ell]}^M=\mathrm{o}(\ell^{-1})$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:convergence_need_to_explain of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $f(\omega,x)\in L_\omega^2L_x^2$ and $k(x,y)\in L_x^\infty L_y^2 $. Then, we have 
		\begin{equation}
			\lim_{n\uparrow\infty}\mathbb{E}\left\|f(k-k_n) \right\|_{L_{x,y}^2}^2=0.
		\end{equation}

