[Lemma lem:decay of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] For the processes defined in \S(ssec:harnack_overview of the paper),
    \begin{align*}
        \mathrm{d} \norm{(X_t, Z_t) - (X_t^\mathsf{aux}, Z_t^\mathsf{aux})}^2 = -2\,\langle (X_t - X_t^\mathsf{aux}, Z_t - Z_t^\mathsf{aux}), \mathcal{M}_t\, (X_t - X_t^\mathsf{aux}, Z_t - Z_t^\mathsf{aux})\rangle\,\mathrm{d} t\,,
    \end{align*}
    where $\mathcal{M}_t$ is a time-dependent, symmetric matrix which is given by
    \begin{align*}
        \mathcal{M}_t  \coloneqq \begin{bmatrix}
            (\gamma_t/2)\, I & (-\gamma_t/2 + \eta_t^\mathsf{x}/\gamma_t - \dot \gamma_t/(2\gamma_t))\, I + \mathcal{H}_t/\gamma_t \\
            * & (\gamma_t/2 + \dot\gamma_t/\gamma_t)\,I
        \end{bmatrix}\,,
    \end{align*}
    where $\alpha I \preceq \mathcal{H}_t \preceq \beta I$.

