body:
[Lemma one-step-descent-convex-exact of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] Let $\mathcal X\subseteq\mathbb R^n$ be nonempty, closed, and convex. Suppose that $f:\mathbb R^n\to\mathbb R$ is $\mu$-strongly convex and $L$-smooth on a convex neighborhood containing $\mathcal X$. Let
\begin{align*}
    x^\star:=\arg\min_{x\in\mathcal X} f(x).
\end{align*}
Fix $\eta>0$ and $\epsilon\in(0,1]$ such that
\begin{align*}
    \epsilon(1+L\eta)\le 2.
\end{align*}
For any $p_t\in\mathcal X$, define the exact feasible backward update
\begin{align*}
    y_t:=\pi_{\mathcal X}(p_t-\eta\nabla f(p_t)),
    \qquad
    \bar p_{t-1}:=(1-\epsilon)p_t+\epsilon y_t.
\end{align*}
Define
\begin{align*}
    \mathcal V(p):=f(p)-f(x^\star)+\frac{1}{2\eta}\|p-x^\star\|^2.
\end{align*}
Then
\begin{align*}
    \mathcal V(\bar p_{t-1})\le \rho\mathcal V(p_t),
\end{align*}
where
\begin{align*}
    \rho:=1-\epsilon\min\{1,\eta\mu\}.
\end{align*}
Moreover, if $\eta\mu<1$, then $\rho=1-\epsilon\eta\mu$.

