\begin{equation} 
\mathbbm P\mathopen{}\mathclose\bgroup\originalleft[ \max_{l \in [-k,k] \cap \mathbbm Z} |\mathcal X(l)| \leq  A k^{3/2}  \aftergroup\egroup\originalright] 
