[Lem 31 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $\alpha\in\{1,..,d\}^k$ with $k\in\N$ such that $\frac{k-1}{2k}d<1$. Then we have
\begin{align*}
    \sup_T\mathbb{E}\left[ \Vert \int_0^T...\int_0^{s_{k-1}} d(\partial_{\alpha_1}Y_{s_1})...d(\partial_{\alpha_k}Y_{s_k})\Vert^p_{B_{p,p}^{(1-\frac{d}{2})k-\kappa}}\right]<\infty
\end{align*}
for large $p$ and small $\kappa$. \\
In particular,
\begin{align*}
     \sup_T\mathbb{E}\left[ \Vert [\![\nabla W_T^k]\!]\Vert_{\mathscr{C}^{(1-\frac{d}{2})k-\kappa}}\right]<\infty.
\end{align*}

[Lemma Wulff:InteriorZero of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Fix $a\in (0,1)$. Let $\mathfrak{c}^*:S^{d-1} \to (a,a^{-1}]$. Suppose that for some $e\in S^{d-1}$, $\mathcal{H}_{e,\mathfrak{c}^*(e)}$ is not a supporting hyperplane of $\mathcal{W}(\mathfrak{c}^*)$. Then, for every $\epsilon\in (0,1)$, there exists $\delta \in (0,\epsilon)$ and $\mathcal{R}\subset S^{d-1}$ finite such that
    \begin{equation*}
        \bigcap_{r\in \mathcal{R}}\mathcal{H}^-_{r,\mathfrak{c}^*(r)+\delta} \subset \mathcal{H}^-_{e,(1-\epsilon)\mathfrak{c}^*(e)}.
    \end{equation*}

[Theorem 18 (see e.g., Knopp \cite{Knopp56InfiniteSequences}, pp.~ 125--126) of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Let $\{d_n\}_{n\ge 1}$ be a positive sequence with $\sum_{n=1}^{\infty} d_n = +\infty$, and $D_n=d_1+\dots +d_n$ be its partial sums. Then
    \begin{equation}
      \sum_{n=1}^{\infty} \frac{d_n}{D_n}=+\infty,\quad \text{and} \quad\sum_{n=1}^{\infty} \frac{d_n}{D_n D_{n-1}^{\varepsilon}} <+\infty
    \end{equation}
    for any $\varepsilon > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:group-exponent-dichotomy of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Let $G$ be an abelian group and fix $k\geq4$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $G$ has unbounded exponent, then
\begin{equation}
 |\mathcal R_G(h,k)|=h^{k-1+o_k(1)}
 \qquad(h\to\infty).
\end{equation}
\item If $mG=0$ for some positive integer $m$, then
\begin{equation}
 |\mathcal R_G(h,k)|\leq m^{k-1}
 \qquad(h\geq1).
\end{equation}
\end{enumerate}
 Consequently, when $|G|\geq k$, the spectrum sizes are bounded in $h$ if
 and only if $G$ has bounded exponent.  The bounded-exponent case has
 logarithmic growth exponent $0$, while the unbounded-exponent case has
 exponent $k-1$.

[Theorem t:hyperunifomrity classes of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi$ is a locally square-integrable invariant random complex measure. Further, let $p,q\in(-d,\infty)$, assume that $\Phi$ is $p$-uniform, and suppose that $f\in L^1$ is Fourier-smooth with exponent $q$. If $p>q$, then
\begin{equation}
    \frac{\BV[\Phi(f_r)]}{r^d} = O(r^{-q})
\end{equation}
as $r\to\infty$. If $p=q$, then
\begin{equation}
    \frac{\BV[\Phi(f_r)]}{r^d} = O(\log(r)r^{-q})
\end{equation}
as $r\to\infty$. 
Moreover, assume that $p=q>0$ and that there are $\tilde c, a\in(0,1)$ such that 
\begin{equation}
\int_a^1|\hat{f}(sk)|^2\, ds\geq \tilde{c}(1+\|k\|)^{-(d+q)}, \quad k\in \R^d.
\end{equation}
Then~(equation e:class I hyperuniformity of the paper) can only hold if $\Phi$ is beyond $p$-uniform, and it can only hold with $o$ instead of $O$ if $\Phi$ is $\lambda_d$ up to a deterministic constant factor.

\begin{remark}
   The additional property~(equation e: oscillation uniformer of the paper) is fulfilled if $f=\I_{B_1}$ and $q=1$, or if \linebreak $\lim_{\|k\|\to\infty}|\hat{f}(k)|(1+\|k\|)^{\frac{d+q}{2}}$ exists, is not $0$, and $\lambda_d(f)\neq0$.
\end{remark}

\begin{proof}[Proof of Theorem~(t:hyperunifomrity classes of the paper)]
    Let $p,q\in(-d,\infty)$, and suppose that $f\in L^1$ is Fourier-smooth with exponent $q$. The proof is mostly analogous to that of Theorem~(t:asymptotic variance test function of the paper). Similar to~(equation e:linear statistic bound 1 of the paper), we obtain that
    \begin{equation}
        \frac{\BV[\Phi(f_r)]}{r^{d-q}} = (2\pi)^{-d}r^{d+q} \int_{B_2} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) + O(1)
    \end{equation}
    as $r\to\infty$. Similar to~(equation e:linear statistic bound 2 of the paper), we can further bound the asymptotically relevant summand by
    \begin{equation}
        (2\pi)^{-d}r^{d+q} \int_{B_2} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) \leq c_1(d+q) \sum_{j=1}^{2\lceil r\rceil}  j^{-1} \big(\tfrac{j}{r}\big)^{-(d+q)} \hat\beta_\Phi\big(B_{\frac{j}{r}}\big), \quad r>0,
    \end{equation}
    for some $c_1>0$. Additionally, we suppose that $\Phi$ is $q+\vartheta$-uniform for some $\vartheta\geq 0$, whereby there is some $c_2>0$ such that $\hat{\beta}_\Phi(B_r)\leq c_2 r^{d+q+\vartheta}, r\leq 3$. We can apply these bounds to obtain
    \begin{align*}
        \sum_{j=1}^{2\lceil r\rceil}  j^{-1} \big(\tfrac{j}{r}\big)^{-(d+q)} \hat\beta_\Phi\big(B_{\frac{j}{r}}\big) &\leq c_2r^{-\vartheta}\sum_{j=1}^{2\lceil r\rceil} j^{\vartheta-1}\\
        &\leq \I\{\vartheta>0\}c_2\vartheta^{-1} + \I\{\vartheta=0\} c_2(\log(r)+1 + \log(4)), \quad r>1.
    \end{align*}
    As $r\to\infty$, the bound is $O(1)$ if $\vartheta>0$, and $O(\log(r))$ if $\vartheta=0$, which, in combination with~(equation e:lin stat bound 1 of the paper) and~(equation e:lin stat bound 2 of the paper), proves this part of the assertion.

    Now also assume that $q>0$ and that there is a $c_3>0$ such that $|\hat{f}(k)|\geq c_3 (1+\|k\|)^{-\frac{d+q}{2}}$ for $k\in \R^d$. The more general case follows afterwards. If $\Phi$ is not deterministic, there is $c_4>0$ such that $\hat\beta_\Phi(B_{c_4})>0$. Hence,
    \begin{align*}
        \frac{\BV[\Phi(f_r)]}{r^{d-q}} = (2\pi)^{-d}r^{d+q} \int |\hat{f}(rk)|^2\,\hat\beta_\Phi(dk) &\geq (2\pi)^{-d}c_3^2 r^{d+q} \int (1+\|rk\|)^{-(d+q)}\,\hat\beta_\Phi(dk)\\
        &\geq (2\pi)^{-d}2^{-1}c_3^2 c_4^{-(d+q)}\hat\beta_\Phi(B_{c_4}) \\
        &> 0,\quad r>c_4^{-1},
    \end{align*}
    whereby~(equation e:class I hyperuniformity of the paper) cannot hold with $o$ instead of $O$.

    For the other part, assume that~(equation e:class I hyperuniformity of the paper) holds. If $f$ were Fourier-smooth with a higher exponent, Theorem~(t:asymptotic variance test function of the paper) would imply that $\Phi$ is $q$-uniform. However, examining~(equation e: bound spectral by real of the paper) in the proof, we see that the Fourier-smoothness of $f$ is irrelevant for this part of the assertion. It remains to show that $\Phi$ in this case is not  (Proof in the paper; no proof environment follows the statement in the TeX.)

