body:
[Prp 31 (\textit{cf.} {\cite[PROPOSITION 1) of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] {SW-generalizedWienerfunctionals}}] \mbox{}

\begin{enumerate}
    \item[\normalfont{(1)}] Let $F \in \bW^{3, p}$ and $\Delta_F^{-1} \in L^q(\Omega)$ for $p, q\in (1, \infty)$ satisfying 
    \begin{equation}
        \frac{9}{p} + \frac{5}{q} < \frac{1}{2}. 
    \end{equation}
    Then, for any $h \in C_{\mathrm{b}}(\R)$, $h \circ F = h(F)$.
    \item[\normalfont{(2)}] Let $F \in \bW^{2, p}$ and $\Delta_F^{-1} \in L^q(\Omega)$ for $p, q\in (1, \infty)$ satisfying 
    \begin{equation}
        \frac{5}{p} + \frac{3}{q} < \frac{1}{2}. 
    \end{equation}
    Then, for any $c \in \R$, $\bar{c} \circ F = (c \cdot \bar{1}) \circ F = c \cdot (\bar{1} \circ F) = c$.
\end{enumerate}

