\begin{equation}
 \mathcal C_{a,2n}(\tau)\leq\mathcal C_a(\tau)
 \leq\mathcal C_{a,2n+1}(\tau).

\end{equation}

[Prop 16 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Assume that there exists $0\leq V_n\in C_b^2([0,\infty)\times \mathbb{R}^d),n\geq 1$, and $\delta_V\in(0,\infty)$ such that
\begin{equation}
\overline{\sf L}V_n(s,x)\leq \delta_V V(s,x),\quad V(s,x):=\liminf_n V_n(s,x), \quad (s,x)\in E.
\end{equation}
Then
\begin{equation}
    P_tV\leq e^{\delta_V t}V, \quad t\geq 0.
\end{equation}
Furthermore, if 
$\liminf_n \left({\sf \overline{L}}V_n\right)^-\geq {\sf \overline{L}}V$, then
\begin{equation}
    \int_0^{t} P_r|\overline{\sf L}V|\; dr\leq V(2e^{\delta_Vt}-1), \quad t\geq 0.
\end{equation}

