[Corollary main_corollary of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any sequence $(n_g)_{g \ge 0}$ such that $n_{g}/g^3 \to\infty$, there exists a sequence $(\mu_g)_{g \ge 0}$ such that $\mu_g \to \mu_c$ and $\mathcal{N}_{g,\mu_g} / n_g \xrightarrow[g \to \infty]{(\mathbb{P})}1$. Furthermore
   \begin{align*}
         \displaystyle \alpha_2 \bigg(\frac{n_g}{g}\bigg)^{-\frac{1}{4}}\Lambda^{\mathrm{tight}}_{g,\mu_g} \xrightarrow[g \to \infty]{\mathrm{(d)}} \mathcal{P},
     \end{align*}     
     where $\mathcal{P}$ is a Poisson point process on $\mathbb{R}_{+}$ with intensity $\frac{\cosh{t}-1}{t}\mathrm{d}t$ and $\alpha_2 = \frac{1}{\pi}\sqrt{3j_0\sqrt{5}}=1.27848\ldots$ where $j_0$ is the first zero of the Bessel function of the first kind $J_0$.  In the convergence, the random multiset $\Lambda_{g,\mu_g}$ is regarded as a random point process on $[0,\infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sum_eta of arXiv:2604.10214, 'Large deviations for maximum local time of simple random walk in dimensions \texorpdfstrin'] For any $\eta>0$,
\begin{align}
\sum_{\substack{0\le i<j\le n:\\ j-i\in[n^\eta,n^{\frac{10}{9}\eta})}}
{\mathbb E}\bigl[X_iX_j\mathbf 1_{\{0<|S_i-S_j|<n^{\eta/8}\}}\bigr]
=o(n^{1-\beta}).
\end{align}

