body:
[Theorem thm:ergodic by independ. of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an upper probability. Then the following statements are equivalent:
	\begin{longlist}
		\item $V$ is weakly mixing with respect to $T$;
		\medskip
		\item For any capacity preserving system $(\Omega',\mathcal{F}',V',T')$ with $V'$ being an ergodic upper probability, $V\times V'$ is ergodic with respect to $T\times T'$;
		\medskip
		\item $V\times V$ is ergodic with respect to $T\times T$.

	\end{longlist}

[Lemma lem:5.4 of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] If all   $l_i^{(j)}\ge 0$, then  
    \begin{equation}
        \left|\mathbb{E}\Big[\prod_{j=1}^{s} \mathrm{Tr} \Big(V_{l^{(j)}_0}\underline{\Phi_{a_1^{(j)}}V_{l_1^{(j)}}}\cdots\underline{\Phi_{a_{k_j}^{(j)}}V_{l_{k_j}^{(j)}}}\Big)\Big]\right|\le 4^{k_1+\cdots+k_s} \mathbb{E}\Big[\prod_{j=1}^{s} \mathrm{Tr} \Big( \widehat{V}_{l^{(j)}_0}\underline{\widehat{\Phi_{2}V_{l_1^{(j)}}}}\cdots\underline{\widehat{\Phi_{2}V_{l_{k_j}^{(j)}}}}\Big)\Big].
    \end{equation}

[Lemma 20 (Pointwise slice identity) of arXiv:2604.20514, 'Macroscopic loops in the random loop model on sparse random graphs'] Let \(\omega\) be a configuration, and let \(s\in S^1\setminus T(\omega)\) be a regular time. Then
\begin{equation}
I_{\mathrm{same}}(\omega;e,s)=I_+(\omega;e,s)+I_-(\omega;e,s)
\qquad\text{for every }e\in E,

\end{equation}
and
\begin{equation}
\sum_{e\in E} I_{\mathrm{same}}(\omega;e,s)
=
\sum_{\gamma\in\cL(\omega)} e_G(S_\gamma(s)).

\end{equation}

[Lemma 70 (Relationship between $\{\geop{t},\geop{u},\geop{x^2},\geop{x^3}\}$ and $\{\nullgeop{\ubar},\nullgeop{u},\nullgeop{x^2},\nullgeop{x^3}\}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following identities hold:
	\begin{subequations}
		\begin{align}
			\nullgeop{\ubar} & = \frac{1}{\geop{t} \ubar} \geop{t}, 
			\\
			\nullgeop{u} & = \geop{u} - \frac{\geop{u} \ubar}{\geop{t} \ubar} \geop{t},  \\
			\nullgeop{x^A} & = \geop{x^A} - \frac{\geop{x^A} \ubar}{\geop{t} \ubar} \geop{t} =  \geop{x^A} +  \frac{\geop{x^A} \ubar}{\geop{t} \ubar}  L^B \geop{x^B} -  \frac{\geop{x^A} \ubar}{\geop{t} \ubar} \Lunit .  
		\end{align}
	\end{subequations}

	Moreover, the following identity holds:
\begin{align} 
\geop{x^A} 
& = 
\nullgeop{x^A} 
- 
\frac{\geop{x^A} \ubar}{\Lunit \ubar} \Lunit^B \nullgeop{x^B} 
+ 
\frac{\geop{x^A} \ubar}{\Lunit \ubar} \Lunit.
