body:
[Lemma 22 ({Billingsley \cite[Theorem 10.2) of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] {Billingsley}}]
  Let $\{Z_k\}_{k=1}^{\infty}$ be a sequence of random variables and let $\gamma\ge 0$ and $\theta >1$. Suppose that there exists a sequence $\{c_k\}_{k=1}^{\infty}$ of non-negative numbers such that
  \begin{equation}
    P\biggl(\biggl|\sum_{k=m}^{n} Z_k\biggr| \ge  \lambda\biggr) \le \lambda^{-\gamma} \biggl(\sum_{k=m}^{n} c_k\biggr)^{\theta}
  \end{equation}
  holds for all positive $\lambda$ and all integers $1\le m < n\le N$. Then, for all positive $\lambda$,
  \begin{equation}
    P\biggl(\max_{m < \ell \le N}\biggl|\sum_{k=m}^{\ell} Z_k\biggr| \ge  \lambda\biggr) \ll \lambda^{-\gamma} \biggl(\sum_{k=m}^{N} c_k\biggr)^{\theta}.
  \end{equation}
  Here $\ll$ depends only on $\gamma$ and $\theta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:basic-props of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] Let $Z=(Z(t), t \geq 0)$ be a continuous-time binary Galton--Watson process with birth rate $b$ and death rate $d$  being strictly positive such that $b \neq d$, and assume $Z(0)=1$. Then for $t\ge0 $
    \begin{equation}
                \mathbb{P}(Z(t)\geq j)
             = \frac{b-d}{b-de^{-(b-d)t}}\cdot\Big(1-\frac{b-d}{be^{(b-d)t}-d}\Big)^{j-1}.
    \end{equation}

