[Lemma 22 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] Let $\mu\in \Pc_{1+\varepsilon}(\Xc)$ for some $\varepsilon>0$.
Then, for all $0\le \varepsilon'<\varepsilon$,
\[
\lim_{\delta\to0}
\sup_{\substack{
\gamma\in\Pi(\mu,\mu)\\
\E^\gamma[d_\Xc(X,X')]\le\delta
}}
\E^\gamma\big[d_\Xc(X,X')^{1 + \varepsilon'} \big]
=0.
\]

[Theorem cor:exp_conv_from_stab of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Let $c(x,\cdot)$ be $\mathcal{C}^1(\mathcal{Y})$ and assume that there exist $\Lambda\in(0,+\infty)$ and $N\geq 2$ such that 
\begin{equation*}
y\mapsto c(x,y)+\psi^{n}_\varepsilon(y)
\end{equation*}
is $\Lambda$-semiconcave uniformly in $x\in\supp(\rho)$ and $n\geq N-1$.
\begin{enumerate}[label=(\roman*)] 

\item If there exists $\tau\in(0,+\infty)$ such that $\nu$ satisfies (eq:TI of the paper), then for all $n\geq N-1$
\begin{equation*}
 \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n+1})\leq \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n})\leq  \bigg(1-\frac{\min\{ \tau\Lambda,\,\varepsilon\}}{\min\{ \tau\Lambda,\,\varepsilon\}+\tau\Lambda}\bigg)^{(n-N+2)} \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{0,0})\,.
\end{equation*}

\item If there exists $\tau\in(0,+\infty)$ such that $\nu^{n,n-1}$ satisfies (eq:TI of the paper) for all $n\geq N$, then 
\begin{equation*} 
 \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n+1})\leq \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n}) \leq \bigg(1-\frac{  \varepsilon }{\varepsilon+\tau \Lambda}\bigg)^{(n-N+1)} \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{0,0})
\end{equation*}
holds for all $n\geq N$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition P:ETnLB of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] Suppose $\gamma d \le 1$. Let $K_0$ be defined by (equation D:K0 of the paper).
Then there exists a constant $C_2 > 0$ and $\delta_0 \in (0, 1)$ small such that for all $\varepsilon \in (0, \delta_0)$ and $n = 2^p$ satisfying $n \le K_0 f(\varepsilon)$,
\begin{align}
{\mathbb E}[T_\varepsilon^n] \ge (C_2 n\varepsilon^d f(\varepsilon))^n.
\end{align}

