[Proposition lemma_converge_loop of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For $d\ge 3$ with $d\neq 6$ and for any admissible  $\{\mathsf{A}_h\}_{h\ge 0}$, there exists $
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d,\{\mathsf{A}_h\}_{h\ge 0})>0$ such that the following hold:
	\begin{enumerate}
		\item $\big\{\mathbb{P}\big(\mathsf{A}_h\mid \bm{0}\xleftrightarrow{[h]}\partial B(N)\big)\big\}_{0\le h\le \ensuremath{c_{\ref*{const_iic_loop}}}}$ uniformly converges as $N\to \infty$;


		\item $\big\{\mathbb{P}\big(\mathsf{A}_h\mid \bm{0}\xleftrightarrow{[h]}x\big)\big\}_{0\le h\le \ensuremath{c_{\ref*{const_iic_loop}}}}$ uniformly converges as $x\to \infty$ (where $x\in \mathbb{Z}^d$);


		\item $\big\{\mathbb{P}\big(\mathsf{A}_h\mid \mathrm{cap}(\mathcal{C}^{[h]}(\bm{0}))\ge T \big)\big\}_{0\le h\le \ensuremath{c_{\ref*{const_iic_loop}}}}$ uniformly converges as $T\to \infty$.


	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2609.01540, '2609.01540'] Assume that the distinguished end has the harmonic asymptotics
\eqref{eq:harmonic-asymptotics}.  Let \(\overline{u}\) solve
\eqref{eq:app-exterior-model}, with
\(\overline{u}-p\cdot x\in C^{2,\alpha}_{1/2}\).  Then there exist
\(c\in\mathbb R\), a homogeneous function \(w_0\) of degree \(3-n\),
and a remainder \(\zeta\) such that
\begin{equation}
 \overline{u}=p\cdot x+c+w_0+\zeta,

\end{equation}
\begin{equation}
 \zeta=
 \begin{cases}
 o_{2,\alpha}(r^{3-n}),&n\geq4,\\
 o_{2,\alpha}(1),&n=3
 \end{cases}.

\end{equation}

[Lemma 23 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu \in \mathcal{M}_F(\mathbb{R}^d)$ and let $\gamma >0$. Let $(\mathcal{X}_r)_{r \geq 0}$ be an $\text{SBM}(\gamma)$ started from $\mu$ on a probability space $(\Omega, \mathcal{F}, \mathbb{P}_\mu)$. For each $a>2$ there $\mathbb{P}_{\mu}$-a.s. exists $\delta>0$ such that if $s$, $t \geq 0$ satisfy $0 \leq t-s<\delta$ then
    \begin{equation*}
        \text{supp}(\mathcal{X}_t) \subseteq \text{supp}(\mathcal{X}_s)^{aH(t-s)}
    \end{equation*}
    where $H:[0,\infty) \rightarrow [0, \infty)$ is the function given by $H(0) = 0$ and for $x>0$ we have
    \begin{equation*}
        H(x) \coloneqq \sqrt{x((\log 1/x) \vee 1))}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

