[Corollary 47 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] If $f: \mathbb{R} \to \mathbb{C}$ is a $C^2_b$-class function, then for every $z \in \nU$, 
the processes
   \begin{equation}
      f(\duality{\bX_n(t)}{z}{}{})  - \int_0^t \widetilde{\mathscr{L}}_{n,s}(f)(\bX_n(s))\,\d s,\;\; t \in [0,T],
   \end{equation}
and 
   \begin{equation}
      \tilde{e}_\theta(\duality{\bX_n(t)}{z}{}{})-\int_0^t \widetilde{\mathscr{L}}_{n,s}(\tilde{e}_\theta)(\bX_n(s))\,\d s,\;\; t \in [0,T],
   \end{equation}
are martingales on the original probability space. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:PBW of arXiv:2411.13707, 'High-degree cubature on Wiener space \\ through unshuffle expansions'] Given a Hall basis $H$, the set
\begin{equation}
\{(h_1,\ldots,h_n) \mid n \in \mathbb N, \ h_1,\ldots,h_n \in H\}
\end{equation}
is a basis of $T(V)$, called the symmetrised Poincaré-Birkhoff-Witt (PBW) basis. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 25 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is monotonically bounded;
\item[(ii)] $F$ is $r$-monotonically bounded, for some $r\ge 1$;
\item[(iii)] Every directed dominable subset of $\Ba_{F_{+}}$ is order bounded.

[Lemma lem:contraction of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] If $v\in\mathbb R^k$ satisfies $\sum_av_a=0$, then
\begin{equation}
 \mathbb E\|vS\|_2^2
 =\rho\|v\|_2^2.
\end{equation}
Consequently,
\begin{equation}
 \mathbb E\|vR_t\|_2^2
 =\rho^t\|v\|_2^2.
\end{equation}

[Definition 22 of arXiv:2607.18104, '2607.18104'] Let $(\omega_v)_{v \in \Z^2}$ be an $(N,k)$-periodic environment for some $N \in \N$ and with $k=k(N)\in \lbr N -1\rbr$. 
We define the \textbf{periodic last passage time} $\Tper_{u,v}$ between $u$ and $v$ as
\begin{equation}
\Tper_{u,v}:=  \sup_{i \in \Z} T_{u+i(N-k,-k),v} . 
\end{equation}

[Proposition 20 of arXiv:2608.30570, '2608.30570'] Assume $\Sigma\subset\mathbb{R}^n$ is a tranlating soliton such that
    \begin{align*}
    \lim_{x\to \infty} \int_{B_1(x)\cap \Sigma}|{\bf  A}|^2d\mu=0.
    \end{align*}
    Then   $\lim_{x\to \infty}|{\bf A}|(x)=0$.

