[Prop stoc_monotonicity of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\Lambda \subset \mathbb Z^d$ be finite, and $\beta\geq0$. Let also $J_1,J_2\in (\mathbb R^+)^{E(\Lambda)}$ be such that $J_1\leq J_2$, and $\mathsf{h}_1,\mathsf{h}_2\in \mathbb R^\Lambda$ be such that $\mathsf{h}_1\leq \mathsf{h}_2$. For any increasing and bounded function $F:\mathbb{R}^{\Lambda}\to\mathbb{R}$ we have 
\begin{equation}
\langle F(\tau) \rangle_{\Lambda,\beta,J_1,\mathsf{h}_1}\leq \langle F(\tau) \rangle_{\Lambda,\beta,J_1,\mathsf{h}_2}.  
\end{equation}
Moreover, if $|\mathsf{h}_1| \leq \mathsf{h}_2$, for any increasing and bounded function $F: (\mathbb{R}^+)^{\Lambda}\to\mathbb{R}$ we have 
\begin{equation}
\langle F(|\tau|) \rangle_{\Lambda,\beta,J_1,\mathsf{h}_1}\leq \langle F(|\tau|) \rangle_{\Lambda,\beta,J_2,\mathsf{h}_2}.  
\end{equation}

[Proposition number_of_simple_closed_tight_geodesics_conditionally_AgL of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any $\mu_g \underset{g \to +\infty}{\rightarrow}\mu_c$ such that $\mu_c - \mu_g = o(g^{-2})$, any disjoint compact intervals $([a_i,b_i])_{1\le i \le n}$ and any $r_1,\cdots,r_n \ge 1$ we have
    \begin{align*}
        \mathbb{E}\bigg[\hat{N}_{g,\mu_g,a_1,b_1,r_1\dots,a_n,b_n,r_n}\indi{\mathcal{A}_{g,b_n}}\bigg] \underset{g \to +\infty}{\overset{}{\longrightarrow}} 0.
    \end{align*}
    In particular
    \begin{align*}
        \mathbb{E}\bigg[\hat{N}_{g,\mu_g,a_1,b_1,r_1\dots,a_n,b_n,r_n}\bigg|\mathcal{A}_{g,b_n}^{c}\bigg] \underset{g \to +\infty}{\overset{}{\longrightarrow}} \lambda_{a_1,b_1}^{r_1}\cdots\lambda_{a_n,b_n}^{r_n}.
    \end{align*}

