[Prop 8 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] _unique_root_examples}
Recall $f$ and $g$ from \eqref{X_{n+1}_conditional_distribution} and \eqref{g_defn} respectively. The function $g$ is monotonically increasing, and the function $\hat{G}$, defined in \eqref{hat{G}_defn}, has a unique root in $[0,1]$, whenever
\begin{enumerate}

\item $f(x)=x$ for all $x\in[0,1]$, with $p\in(1/2,1)$ and
\begin{equation}
\alpha\geqslant\frac{(2p-1)}{4(1-p)},
\end{equation}
\item $f(x)=x$ for all $x\in[0,1]$, with $p\in(1/2,1)$, when \eqref{alpha_inequality} fails to hold but we have 
\begin{equation}
\text{either }\hat{G}\left(\frac{1}{2}-\frac{\sqrt{3}}{6}\sqrt{1-\frac{4\alpha(1-p)}{2p-1}}\right)>0 \text{ or } \hat{G}\left(\frac{1}{2}+\frac{\sqrt{3}}{6}\sqrt{1-\frac{4\alpha(1-p)}{2p-1}}\right)<0.}
\end{equation}
\item $f(x)=e^{x-1}$ for all $x\in[0,1]$, $p\in(1/2,1)$ and $\alpha>0.15218(2p-1)/(1-p)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 16 of arXiv:2606.14038, 'Trivariate Hypergeometric Series Formulas\\ for Pure Partition Functions of Multiple $3$-S'] Let $A_{\u n}$ and $B_{\u n}$ be given by Theorem \ref{Theorem-AB@R}. Let $F(\u r)=\sum_{\u n\in\N_0^3} A_{\u n} \u r^{\u n}$ and $G(\u r)=\sum_{\u n\in\N_0^3} B_{\u n} \u r^{\u n}$, where $\u r^{\u n}:=r_1^{n_1} r_2^{n_2} r_3^{n_3}$. The following hold.
  \begin{enumerate}
    \item [(i)] If $\beta>1/2$, $\sum_{\u n\in\N_0^3} |A_{\u n}|<\infty$, and so $F$ is (defined and) continuous on $[-1,1]^3$, and
         \BGE F(r_1,r_2,1)=\frac{\Gamma(3\beta)\Gamma(3\beta-1)}{\Gamma(2\beta)\Gamma(4\beta-1)}\cdot \prod_{k\in [2]} f_\beta (r_{k}) .\EDE
    \item [(ii)] For all $\beta>0$,  $\sum_{\u n\in\N_0^3}  A_{\u n} \u r^{\u n} $ and $\sum_{\u n\in\N_0^3}  B_{\u n}\u r^{\u n}$ converge locally uniformly in $(-1,1)^3$, and so $F$ and $G$ are analytic in $(-1,1)^3$ and satisfy (\ref{rainbow1}) and (\ref{rainbow2}).
  \end{enumerate}

[Proposition 14 of arXiv:2607.09575, 'Probabilistic estimates for a system of\\noisy integrate-and-fire neurons'] For any given $T > 0$, consider $0 \le t \le t+h \le T$ with $h \in (0,\,1)$. Then, we may find a $C_p > 0$, independent of $h$, and an integer $N_0 = N_0(h)$ such that for all $N \ge N_0$, we have
	\begin{equation}
		\prob\left[F_{t+h}^N - F_{t-}^N > 1 + C_p h^{1/16}\right] \le C_p h^p,
	\end{equation}
	for any $p \ge 1$.

