[Lemma c and r of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Suppose $c^{\{1\}}_{N}$ is the constant defined in (equation w2 of the paper) with respect to $z_1$. Then
 \begin{equation}
     c^{\{1\}}_{N}=\frac{\sqrt{2\pi a}(N+a)!\kappa_N^\frac{1}{6}}{a!N!}a^ae^{-\frac{a}{2}}\left(N+\frac{1}{2}\right)^{N+\frac{1}{2}}\left(n+\frac{1}{2}\right)^{-\left(n+\frac{1}{2}\right)}.
 \end{equation}
 Moreover, define $r^{\{1\}}_{N}:=\sqrt{\frac{N!}{(N+a)!}}c^{\{k\}}_{N}\kappa_N^{-\frac{1}{6}}$. Then for large $N$,
 \begin{equation}
     r^{\{1\}}_{N}=1+O(N^{-1}).
 \end{equation}

[Lemma 36 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Given any~$\sigma\in(0,1/10)$, $a\ge0$ and with $\gamma_{n,a}$ as in \eqref{E:6.34ii}, for $k\le n$ let
\begin{equation}

G_{n,k}:=\bigl\{X_k\in[k^{\sigma},k^{1-\sigma}]\bigr\}\cap\bigcap_{j=k}^{n-k}\bigl\{X_j\ge\gamma_{n,a}(j)\bigr\},
\end{equation}
where~$X$ is related to~$h$ via \eqref{E:sub}. For each~$\epsilon>0$ and $\lambda>0$ there exist~$a\in\R$ and $k_0\ge1$ such that for all~$s\ge 1$ and all $u\le s$ with $s-u\le\lambda$,
\begin{equation}

Q_{n,s,u}(G_{n,k}^\cc)\le\epsilon\frac {1+u_+} n
\end{equation}
holds once $n^\sigma\ge k\ge k_0$ and $n^{1-\sigma}\ge s$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 (Definition and triangularity of $d\Gamma$) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $\p\geq2$ and $ (d\pi^{(\n)} )_{\n\in\NN^{1+d}} \subset \RR [\![ z_{k}, z_{\n} ]\!]$ such that for all $\beta$ and $\n$ it holds that $
d\pi^{(\n)}_{ \beta} \neq 0$ implies $ |\n| < \alpha+ D/\p $.
Then 
\begin{enumerate}
\item the map $ d\Gamma :  \RR [\![ z_{k}, z_{\n} ]\!] \to  \RR [\![ z_{k}, z_{\n} ]\!]$ defined by 
\begin{equation}
\begin{aligned}
d\Gamma z_{k}\coloneqq 0\,, \quad 
d\Gamma z_{\n}\coloneqq d\pi^{(\n)}\,, \quad \text{and}\quad 
d\Gamma ( \pi_{1} \pi_{2}) 
= (d\Gamma \pi_{1}) ( \Gamma \pi_{2}) + (\Gamma\pi_{1}) ( d\Gamma \pi_{2})
\end{aligned}
\end{equation} 
for $\pi_1,\pi_2\in\RR[\![z_k,z_\n]\!]$ is well-defined on $\RR [\![ z_{k}, z_{\n} ]\!]$,

\item for all $\beta,\gamma$ it holds that $ d\Gamma_{ \beta}^{ \gamma} \neq 0$ implies $ | \gamma| <
| \beta| + D/\p $ and $\langle\gamma\rangle<\langle\beta\rangle+D/\p$, and 

\item if $ (d\pi^{(\n)} )_{\n\in\NN^{1+d}} $ is such that $ d\pi^{(\n)}_{ \beta'} = 0$ for all $\beta'$ with $[\beta']<0$, then for all $\beta,\gamma$
\begin{equation}
\begin{aligned}
d\Gamma_{ \beta}^{ \gamma} \neq 0 \quad \implies \quad \gamma
\prec \beta\,.
\end{aligned}
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] Let $\tau>0, \varepsilon>0$ and	 $N\in   \mathbb{N}$ and  set  $\beta=\zeta \tau, \zeta>0$	   in  (equation Ito-FP_eps-V2 of the paper).  Let $f_{\tau,0}\in H$ and  $f^\varepsilon_{\tau,N}$  be the   quasi-regular weak solution   to  (equation Ito-FP_eps-V2 of the paper)  in the sense of (Def-sol-QR-* of the paper) with the initial data $f_{\tau,0}.$
The following holds.
\begin{itemize}
    \item   Assume there exists $f_0\in H_0$ such that   $f_{\tau, 0} \to f_0$ in $H_0$ as $\tau \downarrow 0.$ Then, we have
    \begin{align*}
    \displaystyle \text{weak}-\lim_{\tau\downarrow 0}\lim_{\varepsilon\downarrow 0}\lim_{N\uparrow +\infty}   f^\varepsilon_{\tau,N}= \rho_{0}\otimes\mathbf{M}_0 \text{ in } L^2(0,T;L^2(\Omega;H_0)), \quad \rho_0(x)=\int_D f_0(x,r) dr.
    \end{align*}
 \item     Assume that $f_{\tau,0}$ converges to $ \rho_{0}\otimes\mathbf{M}_0$ in $H_0$ as $\tau \downarrow 0.$ Then,  we have
      \begin{align*}
    \displaystyle \text{weak}-\lim_{\tau\downarrow 0}\lim_{\varepsilon\downarrow 0}\lim_{N\uparrow +\infty}   f^\varepsilon_{\tau,N}(t)= \rho_{0}\otimes\mathbf{M}_0 \text{ in } L^2(\Omega;H_0) \text{ for any } t\in [0,T].
    \end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem d32 of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Assume that $\beta \in (0,1)$  satisfies  condition
(equation eqn-beta+alpha half of the paper) with  $b\in C_{\mathrm{b}}^{\beta}(\mathbb{R}^d,\mathbb{R}^d)$. 
Moreover,  if   $\alpha \in [1,2)$, then  we assume   that   $L = (L_t)_{t\geq 0}$ is a L\'evy  process  satisfying  Hypothesis (hyp-nondeg1 of the paper), i.e.,
\textbf{(H)}, \textbf{(R)} and \textbf{(T)}. If $\alpha \in (0,1)$, then  we assume that $L$ satisfies
Hypothesis (hyp-nondeg3 of the paper). \\
  Then, there  exists  a  ${
\mathscr B}([0,\infty) \times [0,\infty) \times {\mathbb R}^d) \otimes   {
\mathscr F}/{
\mathscr B}({\mathbb R}^d) $-measurable function
\begin{equation} 
\phi : [0,\infty) \times [0,\infty) \times {\mathbb R}^d \times \Omega \to {\mathbb R}^d,
\end{equation}
such that for every $(s,x)\in [0,\infty)\times \mathbb R^d$, the process   $\big ( \phi(s,t,x , \cdot ) \big)_{t \in [s,\infty)}$
is a strong solution of Problem (equation eqn-SDE of the paper)-(equation eqn-SDE-IC of the paper).

Moreover, there exists an almost sure event $\Omega^\prime$
 such that
{\sl the following assertions hold for every $\omega \in \Omega^\prime$.}

{\vskip 2.5 mm \noindent }
(i) For any $x \in {\mathbb R}^d$,  the mapping
 \[ [0,\infty) \ni s \mapsto   \phi (s,t,x, \omega) \in \mathbb R^d \] is c\`adl\`ag locally uniformly in $t$ and $x$, i.e.,
  if  $s \in (0,\infty)$ and   $(s_k)$ is  a sequence such that   $s_k \nearrow s$,
   then, for all $T,M>0$, the following hold
   \begin{align} 
\lim_{k \to \infty} \sup_{|x| \le M}\sup_{t \in [0,T]} |\phi (s_k,t,x, \omega) - \phi (s-,t,x, \omega) | =0,
\end{align}
and if $s \in [0,\infty)$  and
 $(s^n) $  is sequence such that    $s^n \searrow s$, then, for all $T,M>0$, the following holds
\begin{align} 
 \lim_{n \to \infty} \sup_{|x| \le M}\sup_{t \in [0,T]} |\phi (s^n,t,x, \omega) - \phi (s,t,x, \omega) | =0.
\end{align}
{\vskip 2.5 mm \noindent } (ii) For all  $x \in {\mathbb R}^d$ and $s \in [0,\infty)$,
\begin{equation}
  \phi (s,t,x, \omega) =x,\quad  \mbox{ if } \, 0 \le t \le s,
  \end{equation}
   and
\begin{equation} 
 \phi (s,t,x, \omega) = x + \int_{s}^{t}b\left( \phi (s,r,x, \omega) \right) dr + L_t(\omega) - L_s(\omega),\;\;\; t \in [s,\infty).
\end{equation}

{\vskip 2.5 mm \noindent } (iii) For any $s \in [0,\infty)$, the function \[\mathbb R^d \ni x \mapsto \phi (s,t,x, \omega) \in \mathbb R^d\]
is continuous in $x$,  locally uniformly with respect to  $t$.\\
 Moreover,
for every  integer $n > 2d$ and every  $T>0$, there exists  a ${
\mathscr B}([0,T])\otimes {
\mathscr F}/{
\mathscr B}([0,\infty])$-measurable function  $V_n(\cdot,\cdot;T) : [0,T] \times \Omega  \to [0,\infty]$ such that
\begin{equation} 
\int_0^T V_n(s , \omega;T)\, ds < \infty
\end{equation}
 and
\begin{equation}

\begin{aligned}
\hspace{-6truecm}
\sup_{t \in [0,T]} &|\phi (s,t,x, \omega)  - \phi (s,t,y, \omega)|
\\
&\le V_n(s, \omega;T) \,  |x-y\vert^{\frac{n - 2d}{n}} [(|x| \vee \vert y|)^{\frac{2d + 1}{n}} \vee 1],\;\;\; x,y
\in {\mathbb R}^d,  \; s \in [0,T].
\end{aligned}
\end{equation}
(iv) For any $0 \le s <  r \le t < \infty$, $x \in {\mathbb R}^d$, we have
\begin{equation} 
 \phi (s ,t,x, \omega) = \phi (r ,t, \phi (s ,r,x, \omega), \omega),
\end{equation}
i.e.,
\begin{equation} 
 \phi_{s,t}  = \phi_{r,t} \circ \phi_{s,r},
\end{equation}
where
\begin{equation} 
  \phi_{s,t} (x, \omega):= \phi(s ,t,x, \omega).
  \end{equation}
  (v)
 If for some  $s_0 \in [0,\infty)$, $\tau = \tau(\omega) \in (s_0, \infty)$  and  $x \in {\mathbb R}^d$,   a c\`adl\`ag  function
 $g:  [s_0,\tau ) \to  {\mathbb R}^d$ solves the integral equation
\begin{equation} 
g(t) = x + \int_{s_0}^{t}b\left( g(r)\right)  dr
 +  L_{t} (\omega) - L_{s_0}(\omega),\;\;\; t \in [s_0,\tau),
\end{equation}
then we have $g(r) = \phi(s_0,r,x, \omega)$, for $r \in [s_0,\tau)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

