[Lemma starconvltnbnd of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] If $\beta > 0$,  $c\ge 0$ and $a \ge 0$,  then for $t_1 + t_2 = t$,  
\begin{align}
	\Big(\frac{t_1^{2\beta-1}}{1 + a t_1^{2\beta}} e^{-c(\lambda t_1^2)^{1/4}} \Big)
	\Big(\frac{t_2^{2\beta-1}}{1 + a t_2^{2\beta}} e^{-c(\lambda t_2^2)^{1/4}} \Big) \le 
		\frac{1}{2^{2\beta -2}} \Big(\frac{t^{2\beta-1}}{1 + a t^{2\beta}} e^{-c(\lambda t^2)^{1/4}} \Big) .
\end{align}

