[Definition 4 (Gaussian concentration) of arXiv:2602.14618, 'Finitary coding and Gaussian concentration\\ for random fields'] Let $d\geq 1$ and $Y=(Y_i)_{i\in\Zd}$ be a $B$-valued random field where $B$ is a standard Borel space. Then $Y$ satisfies a Gaussian concentration bound if there exists a constant $C>0$ such
that, for any local function $f:B^{\Zd}\to\R$ with the bounded-difference property, and for any $\lambda>0$,  one has
\begin{equation}
\log\E\big(\e^{\lambda (f(Y)-\E[f(Y)])}\big)\leq \frac{\sC}{2} \lambda^2 \|\delta f\|_2^2\,.    
\end{equation}

[Corollary 11 (Oscillation-only work) of arXiv:2608.30715, 'Endpoint Energy Atoms Force Local Pressure Concentration in Three-Dimensional Navier--Stok'] The relative pressure-work identity can be written as
\begin{equation}
 \frac12\norm{r_\tau(t)}_2^2
 +\nu\int_\tau^t\norm{\nabla r_\tau}_2^2\dd\rho
 =\int_\tau^t
 \ip{u}{\mathfrak h_\tau}_{\BMO,\Hh^1}\dd\rho.

\end{equation}
If \(\Aa_a[w]\ge m\), then
\begin{equation}
 \limsup_{t\uparrow T_*}
 \int_\tau^t
 \ip{u}{\mathfrak h_\tau}_{\BMO,\Hh^1}\dd\rho
 \ge\frac m2.

\end{equation}
The right-hand pairing is unchanged when its BMO representative is altered
by a spatially constant velocity.

[Corollary cor:polynomial_decay of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] Assume that the following conditions hold:
\begin{itemize}
\item \textbf{(Related to initial data in Fourier space)} 
Let $\rho$ and $\kappa$ be as in (equation eq:decay of the paper) and (thm:poly of the paper), respectively. Assume that
\[
\rho_{j,j'} - \kappa_{j,j'} > 2, \quad j=1,\dots,d,\; j'=1,\dots,\nu_j.
\]

\item \textbf{(Size of initial data with respect to $\varepsilon$)} 
Let $\omega \notin \Omega_{\delta}$ with $\delta\sim\varepsilon^{1+\eta}$, where
\begin{equation}
0 \le \eta < \min\left\{ 2\Bigl(\frac{1}{\nu}-\mu_1\Bigr)\eta_2-\mu_2,\; \eta_3\right\}. 
\end{equation}
Here $0<\mu_1 \ll 1/\nu, 0<\mu_2 \ll 1$, $\eta_2$ and $\eta_3$ are given by
\begin{align}
\eta_2 &= \sum_{j=1}^{d} \sum_{j'=1}^{\nu_j}
\bigl(\rho_{j,j'} - \kappa_{j,j'} - 1\bigr), \\
\eta_3 &= \frac{2}{3}(\alpha-1)-\frac{\mu_3}{3}, 
\quad 0<\mu_3 \ll 1.

\end{align}
\end{itemize}
 Then the randomized Fourier coefficients satisfy the following almost sure polynomial decay estimates:
\begin{align}
\bigl|c(\boldsymbol{n}) g_{\boldsymbol{n}}(\omega)\bigr|
\le \varepsilon^{-\frac{1}{2}-\frac{\eta}{2}} \,\tnorm{\boldsymbol{n}}_{-(\rho-\kappa)},\quad\omega\notin\Omega_\delta,
\end{align}
where
\begin{align}
\rho - \kappa 
= \bigl( \rho_{1,1}-\kappa_{1,1}, \dots, \rho_{1,\nu_1}-\kappa_{1,\nu_1}; \dots; \rho_{d,1}-\kappa_{d,1}, \dots, \rho_{d,\nu_d}-\kappa_{d,\nu_d} \bigr).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2609.02732, 'Conservation of mass for solutions of Leibenson's equation on Riemannian Manifolds'] \normalfont
		We say that a non-negative function $u=u(x, t)$ is a \textit{weak
			subsolution} of (\ref{dtv}) in $\Omega\times I$, if 
		\begin{equation}  
			u\in C\left(I; L^{q+1}(\Omega)\right)\quad \textnormal{and}\quad 
			u^{q}\in L_{loc}^{ p}\left(I; W^{1, p}(\Omega)\right),
		\end{equation} where (\ref{dtv}) holds weakly in $\Omega\times I$, which means that for all $t_{1}, t_{2}\in I$ with $t_{1}<t_{2}$, and all non-negative \textit{test functions} 
		\begin{equation}  
			\psi\in W_{loc}^{1, 1+\frac{1}{q}}\left(I;
			L^{1+\frac{1}{q}}(\Omega)\right)\cap L_{loc}^{p}\left(I; W_{0}^{1,
				p}(\Omega)\right),
		\end{equation}
		we have 
		\begin{equation}  
			\left[\int_{\Omega}{u\psi }\right]_{t_{1}}^{t_{2}}+\int_{t_{1}}^{t_{2}}{
				\int_{\Omega}{-u\partial_{t}\psi+|\nabla u^{q}|^{p-2}\langle\nabla u^{q},
					\nabla \psi\rangle}}\leq 0.
		\end{equation}

[Theorem Th25 of arXiv:2411.09949, '$W_{\bf d}$-convergence rate of EM schemes for invariant measures of supercritical stable '] Let $\alpha\in(\frac12,2)$. Under $(\mathbf{H}^\gamma)$ and (equation 926-2 of the paper),
for any $\beta\in(0,\alpha)$,
there is a constant $C=C(\Theta,\beta)>0$ such that for
$f:=\int^\infty_0 P_t\bar g {\mathord{{\rm d}}} t$ with $\bar g=g-\mu(g)$ and $g\in{\mathbf C}^\gamma$,
\begin{align}
\|f\|_{{\mathbf C}^{1}_{\rm log}}+\|f\|_{{\mathbf C}^{\beta+\gamma}_{\rm log}}
\lesssim_{C}\|g\|_{{\mathbf C}^\gamma}.
\end{align}

