[Definition of arXiv:2509.23069, 'Every cutoff profile is possible'] Let $((X^{(n)}_t)_{t\geq 0})_{n\geq 1}$ be a sequence of ergodic Markov chains, in discrete or continuous time. We say that that $((X^{(n)}_t)_{t\geq 0})_{n\geq 1}$ exhibits a total variation \textbf{cutoff} at a (sequence of) times $\left( t_n \right)_{n \geq 1}$ if for every $\varepsilon>0$, we have 
    \begin{equation}
        \mathrm{d}^{(n)}\left( \left\lfloor (1-\varepsilon) t_n \right\rfloor \right) \xrightarrow[n\to \infty]{} 1 \quad \text{ and } \quad \mathrm{d}^{(n)}\left( \left\lceil (1+\varepsilon) t_n \right\rceil \right) \xrightarrow[n\to \infty]{} 0,
    \end{equation}
where for $n\geq 1$, $\mathrm{d}^{(n)}(\cdot)$ is the distance to stationarity for the chain $(X^{(n)}_t)_{t\geq 0}$.

[Lemma 13 of arXiv:2604.15753, 'The truncation property and continuity for \\ the long-range contact process on $\mathbb{Z'] Let $\lambda \in \Lambda$ and $\delta>0$. Then, for any $L,T>0$ and $A \subset B_L$, a.s.\ on $H_{L,T}^{A}(k)$, $k \in \bN$, it holds that
\begin{equation} 
\bP_{\lambda,\delta} \left( \exists s>0 \colon A_s^A = \emptyset  \mid \cF_{L,T} \right) \geq \left(e(1+\lambda_{\infty})\right)^{-k}.
\end{equation}

[Thm 8 of arXiv:2511.20875, 'Double $q$-Wigner Chaos and the Fourth Moment'] Let $X_k= I_0( f_k)$ and $Y_k= I_0( g_k)$ with $ f_k=f_k^* \in H^{\otimes m}$ and $ g_k=g_k^* \in H^{\otimes n}$ where $\tau_0(X_k^2)+\tau_0(Y_k^2)\to \sigma^2$ as $k\to \infty$ and $m,n\in \mathbb{N}$ have opposite parities.  
     Then the following are equivalent: \begin{enumerate}
          \item $\lim_{k\to \infty}\kappa_4(X_k+Y_k)=0$.
          \item  $\displaystyle{\lim_{k\to\infty} f_k \overset{p}{\frown} f_k = 0}$ in $H^{\otimes 2(m-p)}$ for $p=1,\ldots,m-1$ and $\displaystyle{\lim_{k\to\infty} g_k \overset{p}{\frown} g_k = 0}$ in $H^{\otimes 2(n-p)}$ for $p=1,\ldots,n-1$.
         \item $X_k+Y_k$ converges in distribution toward $ S(0,\sigma^2)$. 
     \end{enumerate}

[Definition 89 (Transfer-impedance matrix) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Recall that we fixed an (arbitrary) orientation of the edges with $e^-$ and $e^+$ denoting the starting and ending points of an edge $e$. Let $v_e(\cdot)$ be the voltage on the vertices when a unit current flow $\theta_e$ is sent from $e^-$ to $e^+$, i.e.\ $v_e(\cdot)$ is the (unique) harmonic function on $V \setminus \{e^-, e^+\}$ with $v_e(e^-) = \effR{}{e^-}{e^+}$ and $v_e(e^+) = 0$. The transfer-impedance matrix $Y$ is a $|E| \times |E|$ matrix with entries given by
    \begin{equation*}
        Y(e,f) := w(f) \big[ v_e(f^-) - v_e(f^+) \big] = \theta_e(f^-, f^+).
    \end{equation*}

[Lemma lem:gamma-sum of arXiv:2609.02820, 'Sharpness and critical scaling of parking'] For every $n\geq1$,
	\begin{equation}
		\sum_y\sup_{m\leq n}\Gamma_m(y)\leq C\kappa_d(n)\,.
	\end{equation}

[Mainthm 1 of arXiv:2609.02576, 'Sharp estimates for the Jacobi and trigonometric Dunkl heat kernels'] Let $k_1,k_2\geq 0$ be such that $k_1+k_2>0$. The $W$-invariant Opdam--Cherednik heat kernel satisfies the bound
	\begin{equation*}
		\hOC_t(x,y)\simeq t^{-1/2} e^{-\frac{(x-y)^2}{4t}} e^{-\rho^2 t} e^{-\rho(x+y)} (1+x)(1+y) \frac{(t+1+x+y+xy)^{k_1+k_2-1}}{(t+xy)^{k_1+k_2}},
	\end{equation*}
	uniformly in $t>0$ and $x,y>0$, where $\rho=k_1/2+k_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

