[Phasethm t:2b of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Uniformly in $s \in \mathbb{R}$ on compacts, $(r_n, n-r_n)$-clustered sets ${\rm A} \subset {\rm D}^\circ_n$ and subsets ${\rm W} \subseteq {\rm D}$,
\begin{equation}

\bigg| \mathbb{P} \big( \widecheck{T}_{\rm A} \leq t_n^B + sn\,,\,\, \widecheck{X}_{\rm A} \in {\rm e}^{n} {\rm W} \big) -
	\exp \Big(-{\rm e}^{-(s-\log \frac{1}{\sqrt{n}} \|{\bf \Xi}_{{\rm A}, r_ n}\|)}\Big){\bf \Xi}^\circ_{{\rm A}, r_n}({\rm W}) \bigg| \underset{n \to \infty} \longrightarrow 0 \,.
\end{equation}
Moreover, for any fixed $s \in \mathbb{R}$, if $n$ is large enough, then, uniformly in all ${\rm A} \subset {\rm D}_n$ (not necessarily clustered),
\begin{equation}

\mathbb{P} \big( \widecheck{T}_{{\rm A}} > t_n^{B} + sn \big) \leq 2 {\rm e}^{-s}\frac{|{\rm A}|}{\sqrt{n}} \,.
\end{equation}
Lastly, for any fixed $s \in \mathbb{R}$,
\begin{equation}
	\frac{{\mathbf T}_{n,t_n^B+sn}/|{\rm D}_n| - (t_n^B+s n)}{n} \overset{\mathbb{P}}{\underset{n \to \infty}\longrightarrow} 0 \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lmlboundekk of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] Suppose a population evolves according to Def.\ (hapltwo of the paper).  Then there is a constant $B > 0$ with
\begin{esplit}{eglboundekk}
 \frac{(N)_2}{c_N} \EE{ \frac{(X_1)_{k_1}(X_2)_{k_2} }{ (S_N)_{k_1+k_2} }\ensuremath{\mathds{1}_{\left\{ S_N \ge N \right\}}} | \ensuremath{{\alpha_1}}, \ensuremath{{\kappa}} }\frac{ \varepsilon_N}{(N)_2} \le  \frac{B}{N^{\ensuremath{{\alpha_1}}+\ensuremath{{\kappa}}-1 }} \varepsilon_N
\end{esplit}
for all $k_1, k_2 \ge 2$.

[Defn 9 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] We define $BS_\xi$ as the set of functions $p:\R^{2d}\to \C$ such that:
    \begin{enumerate}
        \item for all $x\in \R^d$, $p(x,\cdot)\in \mathscr{C}^\infty(\R^d)$ satisfies: for all $\gamma\in \N^d$, there exists $C_\gamma>0$ (independent of $h$ and $x$) such that
        \begin{equation*}
            \bb{\partial^\gamma_\xi p(x,\xi)}\leq C_\gamma,
        \end{equation*} 
        \item for all $x\in \R^d$, $p(x,\cdot)$ is $\Z^d$ periodic in the sense of \eqref{Def Z^d-périodicité en xi}.
    \end{enumerate}

