body:
[Theorem T:01law of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] \index{zero-one law}
  Assume condition (equation E:main of the paper). Further assume $\ell < \alpha (\gamma+1/2)$ if $\beta = 2$ and $\gamma \in (0, 2]$ in part {\rm (i)}
  below. Fix $a \ge 0$.
  \begin{enumerate}[\rm (i)]

    \item If $\rho \in (0, 1)$, then for any compact interval $I$ in $(0, \infty)$
          and any $x_0 \in \mathbb{R}^d$, there exist constants $K_1, K_2, K_3, K_4 \in [0,
              \infty]$ such that for each $t_0 \in I$,
          \begin{align}
            \lim_{\varepsilon \to 0^+} \sup_{t,s\in I: 0<|t-s|\le \varepsilon} \frac{|u(t,x_0)-u(s,x_0)|}{|t-s|^\rho\sqrt{\log(1+|t-s|^{-1})}} = K_1 \quad \text{a.s.},
          \end{align}
          \begin{align}
            \lim_{\varepsilon \to 0^+} \sup_{t: 0<|t-t_0|\le \varepsilon} \frac{|u(t,x_0)-u(t_0,x_0)|}{|t-t_0|^\rho\sqrt{\log\log(|t-t_0|^{-1})}} = K_2 \quad \text{a.s.},
          \end{align}
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \sup_{t : |t-t_0| \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho (\log\log(1/\varepsilon))^{-a}} = K_3 \quad \text{a.s.},
          \end{align}
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \inf_{t_0 \in I} \sup_{t : |t-t_0| \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho(\log(1/\varepsilon))^{-a}} = K_4 \quad \text{a.s.}
          \end{align}

    \item If $\tilde\rho \in (0, 1)$, then for any $t_0 > 0$, for any compact
          interval $J$ in $\mathbb{R}^d$, there exist constants $K_1', K_2', K_3', K_4' \in
            [0, \infty]$ such that for any $x_0 \in J$,
          \begin{align}
            \lim_{\varepsilon\to0^+} \sup_{x,y\in J: 0<|x-y|\le \varepsilon} \frac{|u(t_0,x)-u(t_0,y)|}{|x-y|^{\tilde\rho}\sqrt{\log(1+|x-y|^{-1})}} = K_1' \quad \text{a.s.},
          \end{align}
          \begin{align}
            \lim_{\varepsilon\to0^+} \sup_{x: 0<|x-x_0|\le \varepsilon} \frac{|u(t_0,x)-u(t_0,x_0)|}{|x-x_0|^{\tilde\rho}\sqrt{\log\log(|x-x_0|^{-1})}} = K_2' \quad \text{a.s.},
          \end{align}
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \sup_{x: |x-x_0|\le \varepsilon} \frac{|u(t_0, x) - u(t_0, x_0)|}{\varepsilon^{\tilde{\rho}}(\log\log(1/\varepsilon))^{-a}} = K_3' \quad \text{a.s.},
          \end{align}
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \inf_{x_0 \in J} \sup_{x: |x-x_0| \le \varepsilon} \frac{|u(t_0, x) - u(t_0, x_0)|}{\varepsilon^{\tilde{\rho}}(\log(1/\varepsilon))^{-a}} = K_4' \quad \text{a.s.}
          \end{align}

  \end{enumerate}

[Lemma 27 of arXiv:2604.04823, '2604.04823'] For any sufficiently large~$a\geq 1$, there exist $\hat\epsilon (a), \eta, \hat  \gamma,\lambda > 0$ such that for all~$\epsilon, h, \gamma$ with
    \begin{equation}
\epsilon \leq \hat\epsilon\,,\quad
h \le \eta\epsilon^2\,,
\quad\text{and}\quad
\gamma < \hat  \gamma\,,
\end{equation}
    it holds that
    \begin{equation}
        \hat Q_{h, \epsilon}W / W (x) - 1 \leq -\lambda \gamma h^2\,,\quad \forall x \in \paren*{\Omega\setminus\Omega_h} \cap B(0, \rho a\sqrt{\epsilon})^c \cap B(m_1,  a\sqrt{\epsilon})^c\,. 
    \end{equation}
    Here, $\rho$ is defined as in~\eqref{e:rho-def}.

