[Lemma 34 (Random Schatten interpolation) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $1\le r<2<q<\infty$ and choose $0<\theta<1$ so that
\begin{equation}

 \frac12=\frac\theta r+\frac{1-\theta}{q}.
\end{equation}
If $B\in L^2(\Omega;\Sch_r)\cap L^2(\Omega;\Sch_q)$, then
\begin{equation}

 \norm B_{L^2(\Omega;\Sch_2)}
 \le
 \norm B_{L^2(\Omega;\Sch_r)}^\theta
 \norm B_{L^2(\Omega;\Sch_q)}^{1-\theta}.
\end{equation}
Equivalently, whenever $B\ne0$,
\begin{equation}

 \norm B_{L^2(\Omega;\Sch_r)}
 \ge
 \frac{\norm B_{L^2(\Omega;\Sch_2)}^{1/\theta}}
 {\norm B_{L^2(\Omega;\Sch_q)}^{(1-\theta)/\theta}}.
\end{equation}

[Lemma 10 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] There exists a universal constant $\gamma > 0$ such that for $p > \fr{1}{2}-\gamma$,
there is a constant $\alpha_p > \fr{(2-p)^2}{2}$ such that, for all $\eps = \eps_d > \poly(d)^{-1}$,
there is a function $f(d) > \poly(d)^{-1}$ (which may depend on $\eps_d$) such that  the following event
(determined by the percolation configuration) holds with probability tending to $1$.
\begin{equation}
    \left\{ \text{For all choices of } a,b,\ell,\sigma, \text{ we have }
    \pi\Box{\scrC(a,b;\ell;\sigma;S) > \eps \cdot 2^{a+b}} \leq \Exp{- f(d) \cdot \alpha_p^d}
    \right\}.
\end{equation}

[Proposition 25 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\in(2,3)$. For every $t\in[0,T]$,
    \begin{equation*}
        \begin{aligned}
            &\mathbb{E}\left[\sup_D\sum_{i=0}^{n-1} \Big\lVert \augpr{X}^{\mu,1}_{t_i,t_{i+1}}-\augpr{Y}^{\nu,1}_{t_i,t_{i+1}} \Big\rVert^p_{\mathbb{R}^{d+1}}\right]\\
            &=\mathbb{E}\left[\sup_D\sum_{i=0}^{n-1} \Big\lVert\left(X^{\mu}_{t_{i+1}}-X^{\mu}_{t_i}\right)-\left(Y^{\nu}_{t_{i+1}}-Y^{\nu}_{t_i}\right)\Big\rVert^p_{\mathbb{R}^d}\right]\\
            &\leq \widetilde{C}\int_0^t\left(\mathbb{E}\left[\big\lVert\augpr{X}^{\mu}-\augpr{Y}^{\nu}\big\rVert_{\textup{$p$-var};[0,s]}^p\right] + \int_{\widehat{G\Omega}_p(\mathbb{R}^{d+1})\times \widehat{G\Omega}_p(\mathbb{R}^{d+1})}C_s\lVert x-y \rVert_{\textup{$p$-var};[0,s]}^p\pi(dx,dy)\right)ds,
        \end{aligned}
    \end{equation*}
    where $D=D_{[0,t]}$ is a partition of $[0,t]$, $\widetilde{C}=\widetilde{C}(p,T,L)$, $C_s=C_s(d,p,N,T,\alpha_\infty,\Gamma_s)$, $\alpha_\infty:=\max_{0\leq |I|\leq N}|\alpha_I|$ where $\alpha_I$ are the coefficients in \eqref{eq:linear_comb_in_sig_MKV_SDE}, $\Gamma_s:=\max\{\lVert x\rVert_{\textup{$p$-var};[0,s]},\lVert y\rVert_{\textup{$p$-var};[0,s]}\}$, and $\pi\in\Pi(\mu,\nu)$ is an arbitrary coupling of $\mu$ and $\nu$.

[Lem shockstoisland of arXiv:2604.12963, 'Shocks, instability, and the twenty networks\\ of infinite geodesics in the Directed Lands'] Let $\omega\in\Omega_0$ and $\theta\in\Theta^\omega$. Let $(z,t_2)\in\IG\theta$. Suppose that $\Upsilon_{(z,t_2)}\dir{L}{\theta}{-}$ and $\Upsilon_{(z,t_2)}\dir{R}{\theta}{+}$ are misordered.  Let
    \begin{align}
        t_1=\sup\bigl\{r<t_2:\Upsilon_{(z,t_2)}\dir{L}{\theta}{-}(r) = \Upsilon_{(z,t_2)}\dir{R}{\theta}{+}(r)\bigr\}.
    \end{align}
    Then $-\infty<t_1<t_2$, $\Upsilon_{(z,t_2)}\dir{L}{\theta}{-}(t_1) = \Upsilon_{(z,t_2)}\dir{R}{\theta}{+}(t_1)$, $\Upsilon_{(z,t_2)}\dir{L}{\theta}{-}(r)<\Upsilon_{(z,t_2)}\dir{R}{\theta}{+}(r)$,  
    for all $r\in(t_1,t_2)$, and 
    \begin{align}
    U=\bigl\{ (y,r)\in\mathbb{R}^2\,:\, r\in(t_1,t_2),\, \Upsilon_{(z,t_2)}\dir{L}{\theta}{-}(r)<y<\Upsilon_{(z,t_2)}\dir{R}{\theta}{+}(r)\bigr\}
    \end{align}
    is a stability island $\mathbb{I}^\theta_{(x,s)}$ for any $(x,s)\in U$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2609.03993, 'The Endpoint Fractional Riesz Estimate on the Hamming Cube'] Let $(T_t)_{t\geq 0}$ be a quatum Markov semigroup on $(\cN,\tau)$ and $(P_t)_{t\geq 0}$ be its subordinated
		Poisson semigroup, and assume $\Gamma_2\ge0$. Let $a:(0,\infty)\to\mathbb C$ be measurable.
		Assume
		\begin{equation}
			c_a^2=\sup_{s>0}s\int_s^\infty
			\frac{|a(v-s)|^2}{v^2}\,dv<\infty.

		\end{equation}
		Define
		\begin{equation*}
			M_af=\int_0^\infty a(t)\,\partial_tP_tf\,dt.
		\end{equation*}
		Then
		\begin{equation*}
			\|M_af\|_{\BMO_c(\Gamma)}
			\lesssim c_a\|f\|_{\BMO_c(\Gamma)}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2607.11608, '2607.11608'] Let $p > 2$ if $d=1,2 $, or  $2 < p < \frac{2 d}{d - 2 }$ if $d \ge 3$. Then, 
\begin{align}
\|u\|^p_{L^p(\R^d)}\le \textup{C}_{\textup{GNS}}(p,d)\|u\|^{\frac{(p-2)d}{2}}_{\dot{H}^{1}(\R^d)}\|u\|^{2+\frac{p-2}{2}(2-d)}_{L^2(\R^d)}. 

\end{align}
Moreover, the optimal constant $\textup{C}_{\textup{GNS}}$ is achieved by a function in $H^1(\R^d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] If $\varphi\in H^{n/2}$ and $h\sim \mathbb P$, 
	then $h+\varphi$ is distributed according to 
	\begin{equation}
		\exp\paren{\scalar{h}{\tilde {\mathsf p}\varphi}-\frac12 \tilde{\mathfrak p}(\varphi,\varphi) } \, d\mathbb P(h).
	\end{equation}

