[Definition Lipschitz function of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] Given $(\mathcal{X},d)$ a metric space, a function ${f: \mathcal{X}\to \mathbb{R}}$ is called $L$-Lipschitz if 
		\begin{align*}
			\forall x,y\in\mathcal{X}, \qquad \vert f(x)-f(y)\vert\leqslant L d(x,y). 
		\end{align*}
		The family of all $1$-Lipschitz functions is denoted by $1\text{-}\mathrm{Lip}(\mathcal{X})$.

[Lem 4 of arXiv:2607.03360, 'Smoluchowski-Kramers Approximation Meets Khasminskii Averaging Principles in Nonequilibriu'] Let $u\in C_p^{\vartheta,\dl}$ with $0<\vartheta\leq 2, 0<\dl \leq 1$. Define $u_n$ by \eqref{mol-u}. Then we have 
\beq{u-un}
|u(\cdot, y)- u_n(\cdot, y)|_\infty \leq C_0 n^{-\vartheta} (1+|y|^{\wdh n})\text{ and } |\nabla_x^k u_n(\cdot, y)|_\infty \leq C_0 n^{k-\vartheta}(1+|y|^{\wdh n}),
\eeq
for $k=1,2$ and $C_0$ is a constant independent of $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:Bhat of arXiv:2607.19844, 'Binomial probabilities at a fixed distance from the mode:\\ size-biasing and the complete '] Let $\widehat B_n$ be the Appell sequence defined, for all $n\ge0$, by
	\begin{equation}
		\widehat B_n(t):=\tfrac12\bigl[B_n(t)+B_n(t+1)\bigr],
		\qquad\text{equivalently}\qquad
		\sum_{n\ge0}\widehat B_n(t)\frac{z^{n}}{n!}=\frac{z}{2}\coth\frac{z}{2}\;e^{tz} .
	\end{equation}
	For $n\ge1$ this may be written as
	\begin{equation}
		\widehat B_n(t)=B_n(t)+\tfrac n2\,t^{n-1}\qquad(n\ge1),
	\end{equation}
	by the difference identity (equation eq:appell of the paper); for $n=0$ the averaged definition gives
	$\widehat B_0=B_0=1$, whereas the right-hand side of (equation eq:Bhat-alt of the paper) would contain the
	meaningless term $0\cdot t^{-1}$.  Only (equation eq:Bhat of the paper) is used at $n=0$.

[Definition 3 of arXiv:2605.26439, '2605.26439'] We say that $\{Y_t\}_{t\geq 0}$ is null-controllable at time $T>0$ if there exists  a constant $C>0$ such that for any $y\in \mathcal H$, there exists $h\in L^2(0,T;U)$ satisfying
        \begin{equation*}
            Y_T=0,\quad \|h\|_{L^2(0,T;U)}\leq C\|y\|_{\mathcal H} .
        \end{equation*}

[Lemma lem:Push-TASEP-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The seed functions $\psi_{t,r,n}$ and $\phi_{t,r,n}$
defined in \S(sec:Push-TASEP-kernel-reform of the paper) satisfy the
semi-discrete linear problem
(equation eq:sc-linear-1 of the paper)--(equation eq:sc-linear-j of the paper)
and its adjoint
(equation eq:sc-adjoint-1 of the paper)--(equation eq:sc-adjoint-j of the paper)
with shifts
$T = e^{\partial_r}$, $\partial_1 = \partial_t$,
$S_2 = e^{\partial_n}$ and constant scalar edge weights
$(c_1, \lambda_1) = (2, 2)$,
$(c_2, \lambda_2) = (2, 1)$.
Explicitly:
\begin{align}
\partial_t \psi_{t,r,n}
&= 2\bigl(\psi_{t,r+1,n}
   - \psi_{t,r,n}\bigr),
 \\
\psi_{t,r,n+1}
&= 2\psi_{t,r+1,n} - \psi_{t,r,n},

\end{align}
and
\begin{align}
\partial_t \phi_{t,r+1,n}
&= 2\bigl(\phi_{t,r+1,n}
   - \phi_{t,r,n}\bigr),
 \\
\phi_{t,r+1,n}
&= 2\phi_{t,r,n+1} - \phi_{t,r+1,n+1}.

\end{align}

