body:
[Theorem 12 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] Under the same assumptions as in Lemma~\ref{lem:primitive-kl}, there exists a constant \(C_\mathrm{risk}\) depending on \(I,J,\beta,H,\kappa,K,\xi_\star,d\) and \(V\), but not on \(n\), such that
\begin{equation}
  \inf_{\wh\Xi_n}
  \sup_{\xi\in\mathfrak X_\beta(J)}
  \E_\xi\norm{\wh\Xi_n-\xi}_{L^2(I)}^2
  \geq C_\mathrm{risk} n^{-2\beta/(2\beta+3)}.
\end{equation}
Moreover, for constants 
\(C_\mathrm{sep}>0\) and \(p\in(0,1)\)
depending on the same variables as \(C_\mathrm{risk}\),
\begin{equation}
  \inf_{\wh\Xi_n}
  \sup_{\xi\in\mathfrak X_\beta(J)}
  \Pi_\xi^{\otimes n}\!\biggl(
    \norm{\wh\Xi_n-\xi}_{L^2(I)}
    \geq C_\mathrm{sep} n^{-\beta/(2\beta+3)}
  \biggr)
  \geq p.
\end{equation}
The infimum is over all measurable estimators based on \(X_1,\ldots,X_n\sim \Pi_\xi\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 (Sobolev estimates) of arXiv:2609.03558, 'Local well-posedness of the higher-order nonlinear Schr\"{o}dinger equation on the half-li'] Let $b\in \{0,1\}$. Then, the unique solution of \eqref{cauchy2} satisfies the space estimate
	\begin{equation}
		\sup_{t\in[0,T]}\left\| z(\cdot,t) \right\|_{H_x^{s}(\mathbb{R})}\leq \left\|F\right\|_{L_t^1((0,T); H_x^{s}(\mathbb{R}))}, \quad s\in \mathbb{R}.
	\end{equation}

	Moreover, if  $-1+b\leq s \leq 2+b$ with $s\neq \frac 12+b$, then
	the following time estimate holds
\begin{equation}
\sup_{x\in\mathbb{R}}\left\| \partial_x^bz(x,\cdot) \right\|_{H_t^{\frac{s+1-b}{3}}(0,T)}\leq c \, 
\|F\|_{L_t^2((0,T); H_x^{s}(\mathbb{R}))}
	\end{equation}

	for some constant
    $c = c(s, T, \alpha, \beta, \delta) \geq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2609.02050, '2609.02050'] Let $D$ be a diagram that avoids the configurations in Figure~\ref{fig-upper} and let $C^{(1)},\ldots,C^{(m)}$ be all the diagrams $C=(C_1,C_2,\ldots,C_n)$ with $|C_j|=|D_j|$ for $j\in[n]$ and ${\bf x}^{C}={\bf x}^a$, where ${\bf x}^a$ is a monomial in $\chi_{D}({\bf x})$. For simplicity, write ${\bf y}^{(a)}={y}^{F_{led}^{C^{(a)}}}$  Then we have the following results:
		\begin{enumerate}
			\item[(a)] For $1\leq a \leq m$, the leading monomial ${\bf y}^{(a)}$ appears in the polynomial $\det\left(Y_D^{C^{(a)}}\right)$.

			\item[(b)] The leading monomials $\{{\bf y}^{(a)}\}$ are distinct.
		\end{enumerate}

[Theorem Thm_NashMoserSubmersionTheorem of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let ${\mathbf{X}}$ and ${\mathbf{B}}$ be tame Fréchet manifolds,
  ${\mathbf{V}}$ a tame Fréchet space bundle over ${\mathbf{X}}$,
  $\mathrm{pr}_{\mathbf{B}} \mskip0.5mu\colon\thinspace {\mathbf{X}} \to {\mathbf{B}}$ a uniform submersion,
  $s \in \Gamma({\mathbf{X}},{\mathbf{V}})$ a tame smooth section, and
  $\nabla$ a partial connection on ${\mathbf{V}}$ with respect to the vertical tangent bundle $\VerticalTangentBundle{{\mathbf{X}}}{{\mathbf{B}}} \coloneq \ker T\mathrm{pr}_{\mathbf{B}} \subseteq T{\mathbf{X}}$.
  If
  there is a finite rank vector bundle $\mathrm{Def}$ over ${\mathbf{X}}$ and
  a map of tame Fréchet space bundles $\pi \mskip0.5mu\colon\thinspace T{\mathbf{X}}/{\mathbf{B}} \twoheadrightarrow \mathrm{Def}$ such that the thickening
  \begin{equation}

    \begin{pmatrix}
      \nabla s \\
      \pi
    \end{pmatrix}
    \mskip0.5mu\colon\thinspace
    T{\mathbf{X}}/{\mathbf{B}} \to {\mathbf{V}} \oplus \mathrm{Def}
  \end{equation}
  is an isomorphism of tame Fréchet space bundles,
  then:
  \begin{enumerate}
  \item

    the zero locus
    \begin{equation*}
      {\mathbf{Z}} \coloneq s^{-1}(0) \subseteq {\mathbf{X}}
    \end{equation*}
    is a tame Fréchet submanifold,
  \item

    the projection $\mathrm{pr}_{\mathbf{B}} \mskip0.5mu\colon\thinspace {\mathbf{Z}} \to {\mathbf{B}}$ is a uniform submersion, and
  \item

    $\VerticalTangentBundle{{\mathbf{Z}}}{{\mathbf{B}}} = \ker T(\mathrm{pr}_{\mathbf{B}}|_{{\mathbf{Z}}}) \cong \mathrm{Def}|_{\mathbf{Z}}$.
  \end{enumerate}

