body:
[Theorema WPHs of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] Let $s\geq 0 $ and  $0<b< 1-s$. 
    \begin{enumerate}
        \item (subcritical) If 
        \begin{align*}
            1< \alpha < \begin{cases}
            1+ \frac{4-2b}{1-2s}\quad &\text{if} \quad s<1/2 \\ 
            \infty \quad &\text{if} \quad s \geq 1/2
        \end{cases},
         \end{align*} 
         then (equation INLS of the paper) is locally well-posed in $H^s.$ 
        \item (critical) If $s> 1/2$ and $\alpha=1+\frac{4-2b}{1-2s},$ then (equation INLS of the paper) is locally well-posed in $H^s$ and globally well-posed for the small data.
        \item (mildly ill-posed) If $s>0,\quad 0<b<1 \leq b+s<5/2, \; \alpha-1 \in 2\mathbb{N} \quad \text{and,\; if}\quad b+s \geq 1,\quad b+s \not \in \mathbb{N},$ then  (equation INLS of the paper) is mildly ill-posed in $H^s.$ 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 3 of arXiv:2608.12804, 'Scaling Limits for Ising Models on Inhomogeneous Random Graphs and Applications'] Let $T$ be a trace--class operator with eigenvalues $\lambda_i$, counted with algebraic multiplicity. Then the \emph{Fredholm determinant} of $I+T$ ($I$ being the identity operator) is defined as,
    \begin{equation*}
        \det(I+T) = \prod_i(1+\lambda_i)
    \end{equation*}

[Thm 2 of arXiv:2510.26216, 'A functional Breuer-Major theorem with Poisson noise'] Fix $d\in\NN^+$, $\alpha > \frac{1}{2} + \frac{1}{2d}$ and $\gamma_0>d_\alpha+1$. Suppose that there exist $C_\psi>0$ and $M_0\in \NN$ such that
    \begin{equation}  
        |\psi(x)| \le C_\psi (1 + |x|)^{-\alpha}
    \end{equation}
        for all $x\in\RR$ and
    \begin{equation}  
        \phi(x) \in \cC^{\gamma_0}_{M_0}.
    \end{equation}
    Then, the process $\mathcal{T}^{\ge d} Y_n$ converges in law to $\mu B$ in the Skorohod space $\mathbf{D}([0,1])$, where $(B_t)_{t \in [0,1]}$ is a standard Brownian motion, and
	\begin{equation} 
    	\mu^2 = \sum_{u\in\ZZ}\mathbf{E} [\mathcal{T}^{\ge d}\phi\left(X_0\right)\mathcal{T}^{\ge d}\phi\left(X_u\right)].
	\end{equation}

[Lemma lem: bdry rem properties of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $\varepsilon >0$, define the boundary remainder map ${\rm rem}^0_\varepsilon: \boldsymbol{\mathfrak B}^0 \times \mathcal L^0 \rightarrow \mathcal L^0$ for every $(\Xi^0,u) \in \boldsymbol{\mathfrak B}^0 \times \mathcal L^0$ by 
\begin{equation}
{\rm rem}^0_\varepsilon(\Xi^0, u)_t := - 4J_t^0 \overline{H}^* \Xi^{0,3}_t + {\rm reg}_{\mathbb T^2,\varepsilon}\Big( 4J_t^0 \overline{H}^* \Xi^{0,3}_t  + \ell^0_\infty(u)_t  \Big), \quad \forall t \geq 0.
\end{equation}
This a continuous linear map $\boldsymbol{\mathfrak B}^0 \times \mathcal L^0  \rightarrow \mathcal {L}^0$ and also as a map from $\boldsymbol{\mathfrak B}^0 \times \mathcal {L}^0_w \rightarrow \mathcal L^0_w$. It satisfies 
\begin{equation}
\ell^{0}_\infty({\rm rem}_{\varepsilon}(\Xi^0, u))={\rm reg}_{\mathbb{T}^2,\varepsilon} \left( \ell^{0}_\infty(\Xi^0,u) \right).
\end{equation} 
Furthermore, the map satisfies the following properties: there exists $C>0$  and for every $\varepsilon > 0$ there exists $C_\varepsilon > 0$ such that:
\begin{enumerate}
\item[(i)] $\|{\rm rem}^0_\varepsilon(\Xi^0, u)\|_{\mathcal {L}^0} \leq C (\| \Xi^0\|_{\boldsymbol{\mathfrak B}^0} + \|u\|_{\mathcal L^0})$.
\item[(ii)] for $T \in (0,\infty]$, $\|\overline H Z^{0}_T({\rm rem}^0_\varepsilon(\Xi^0, u))\|_{L^4([-1,1]\times\mathbb T^2)} \leq C (\|\Xi^0\|_{\boldsymbol{\mathfrak B}^0} + \|\overline H Z^{0}_T(u)\|_{L^4([-1,1]\times\mathbb T^2)})$.
\item[(iii)] $\|\ell^0_\infty({\rm rem}_\varepsilon^0(\Xi^0, u))\|_{\mathcal H^0} \leq C_\varepsilon ( \|\Xi^0\|_{\boldsymbol{\mathfrak B}^0}+ \|u\|_{\mathcal {L}^0})$.
\item[(iv)] $\|{\rm rem}^{0}_{\varepsilon}(\Xi^0,u)-u\|_{\mathcal{L}^0} \to 0$ if $u\in \mathcal{L}^0$ and $\|\ell^{0}_{\infty}({\rm rem}^{0}_{\varepsilon}(\Xi^0,u))-\ell_{\infty}^{0}(u)\|_{\mathcal{H}^0} \to 0$ if 
$\ell_{\infty}^{0}(u) \in \mathcal{H}^0$. 
\end{enumerate}

[Definition of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] The ${\mathbb{F}}$-valued square root Wishart matrix with parameters $ m> n-1$ is the distribution of the $n\times n$ lower triangular matrix $\mathbf{X}$ with the following independent entries:
\begin{align*}
 x_{i,j}\sim \begin{cases}
 {\mathbb{F}} N(0,1)& \text{if $i>j$},\\
 \dfrac{1}{\sqrt{\beta}} \chi_{\beta (m+1-i)}& \text{if $i=j$},\\
 0& \text{if $i<j$}.
 \end{cases}
\end{align*}
 We denote this distribution by $\mathtt{SqW}_\beta(n,m)$.

