[Corollary LM of arXiv:2605.10452, 'A secretary for Messrs. Luce and Mallows'] When the weights for the Luce distribution are given by $\theta_j=q^j$, for $q\in(0,\infty)$, one has
\begin{equation}
P_n^{\mathcal{L}_\text{inv};\{q^j\}_{j=1}^n}(\mathcal{S}^\downarrow(n,M))=P_n^{\mathcal{M};q}(\mathcal{S}^\downarrow(n,M)).
\end{equation}

[Proposition 19 of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] For every $i=1,\ldots,N$ the processes $\eAi{M}$ are semi-martingales described by
	\begin{equation}

		d\eAi{M} = 2\eBi{M}\sum_{k=1}^N\sigX{k}\sum_{\aRi}\alpha_k \eaBi{M-1} dB_k + (V^{(1)}_{M}(X)+\eBi{M}V_{M}^{(2)}(X))dt\/,
	\end{equation}
	where
\begin{align*}
	V^{(1)}_M(X) &= \sum_{k=1}^N \siggX{k}\left(\sum_{\aRi}\alpha_k \eaBi{M-1}\right)^2+2\sum_{\aRi}|\alpha|^2\eaAi{M-1}\kaX
\end{align*}
and
\begin{align*}	
	V^{(2)}_M(X) &= 2\sum_{k=1}^N\siggX{k}\anbRi\alpha_k\beta_k\eabBi{M-2}+2\sum_{k=1}^N \bX{k}\sum_{\aRi}\alpha_k \eaBi{M-1}\\
  &+2\anbRi\ab\eabBi{M-2}k_\beta(x)-2\sum_{\beta\notin\Ri}\sum_{\aRi}\frac{\left<\alpha,\sigma_\beta(\alpha)\right>}{|\beta|^2}\easBi{M-2}{\sigma_\beta(\alpha)}k_\beta(x)\/.
\end{align*}

