[Lemma 36 of arXiv:2604.21669, 'Discontinuous transition in 2D Potts:\\ II. order-order interface convergence'] Let \(0<J<U\) satisfy \(\sinh 2J=e^{-2U}\). There exists \(n_0\geq 1, c,c_0\in (0,+\infty)\) such that for any \(n\geq n_0\), \(m_n\geq c_0n\), any \(\eta_L, \eta, \eta_R,\eta_L', \eta', \eta_R'\) such that
	\begin{itemize}
		\item \((v_L+\eta_L\concatenate \eta\concatenate \eta_R, v_L'+\eta_L'\concatenate \eta'\concatenate \eta_R') \in \goodCl_n\),
		\item \(W_L(v_L+\eta_L\concatenate \eta \concatenate \eta_R) = v_L + \displace(\eta_L)\), \(W_R(v_L+\eta_L\concatenate \eta \concatenate \eta_R) = v_L + \displace(\eta_L\concatenate \eta)\),
		\item \(W_L(v_L'+\eta_L'\concatenate \eta' \concatenate \eta_R') = v_L' + \displace(\eta_L')\), \(W_R(v_L'+\eta_L'\concatenate \eta' \concatenate \eta_R') = v_L' + \displace(\eta_L'\concatenate \eta')\),
	\end{itemize}
	\begin{equation*}
		\Big|\frac{\Phi_n\big( \tilde{\calK} = \eta,\, \tilde{\calK}^* = \eta' \bgiven \tilde{\calK}_L = \eta_L,\, \tilde{\calK}_R = \eta_R,\, \tilde{\calK}_L^* = \eta_L',\, \tilde{\calK}_R^* = \eta_R',\, \connection,\, \connection' \big)}{\Phi\big( \tilde{\calK} = \eta \bgiven \tilde{\calK}_L = \eta_L,\, \tilde{\calK}_R = \eta_R,\, \connection \big)\Phi\big( \tilde{\calK}^* = \eta' \bgiven \tilde{\calK}_L^* = \eta_L',\, \tilde{\calK}_R^* = \eta_R',\, \connection' \big)} -1 \Big|
		\leq
		e^{-c\scale_n}.
	\end{equation*}

