[Theorem thm:existence_all_cases of arXiv:2505.14012, 'Ergodicity for stochastic neural field equations'] Assume that Assumptions (assu:space of the paper) and (assu:noise of the paper) are satisfied. Then, for any $p\ge 2$ and for any initial datum $u(0)\in L^p(\Omega,\mathcal{F}_0,\mathbb{P};H)$, there exists a unique $\mathbb{P}$-a.s. continuous and adapted
strong solution $u(t)$, $t\in [0,T]$ of (equation eq:gen_model of the paper), and there exists a constant $C_{p,T}>0$, such that
\begin{align*}
\mathbb{E}(\|u(t)\|^p)\leq C_{p,T}\left(1+\mathbb{E}\|u(0)\|^p\right),\quad t\in[0,T].
\end{align*}

[Corollary 9 (Application to light tails -- random thresholds) of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] Under the Assumptions of Corollary~\ref{cor:light_det} and with the notation of Corollary~\ref{cor:heavy_rand} it holds, as $n\to\infty$,
 \begin{align*}
  &
    n^{1/2-d}
    \left(
    q_{X_0}
    \left(
    1
    -
    \frac{k}{n}
    \right)
    \right)^{1-\beta}
    \\&
    \cdot
    \
      \left(
      \frac
      {
      \sum_{i=1}^{k}
        \log(
        X_{n-i+1:n}
        /
        X_{n-k:n}
        )
      }
      {n \PP[X_0>u_n]}
      \ - \
      \EE[\log(X_0/u_n) \mid X_0>u_n]
      \right)
      \
      \stackrel{\PP}{\longrightarrow}
      \
      0\,.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 8 of arXiv:2606.02570, 'Stochastic completeness for landmark space'] Suppose that the radial scalar function $k\colon [0,\infty)\to\R$ is smooth on $(0,\infty)$ and that it possesses a positive continuous Fourier transform $\widehat{k}\colon\R^d\to\R$. For $M>0$, we set
    \begin{displaymath}
        \widehat{k}_M:=\inf_{\|\xi\|\leq 2M} \widehat{k}(\xi).
    \end{displaymath}
    Fix a landmark configuration $\lm\in \Land$. Then, for any
    \begin{displaymath}
        M\geq \frac{12}{q(\lm)}\left(\frac{\pi\left(\Gamma\left(1+\frac{d}{2}\right)\right)^2}{9}\right)^\frac{1}{1+d}
    \end{displaymath}
    or, simply,
    \begin{displaymath}
        M\geq\frac{7 d}{q(\lm)},
    \end{displaymath}
    the minimal eigenvalue $\lambda_{\min}\left(g^{-1}(\lm)\right)$ of the cometric at the landmark configuration $\lm$ satisfies
    \begin{displaymath}
        \lambda_{\min}\left(g^{-1}(\lm)\right)
        \geq \frac{\widehat{k}_M}{2\Gamma\left(1+\frac{d}{2}\right)}\left(\frac{M}{2^{3/2}}\right)^d.
    \end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_[P,partial_alpha] of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] We have
    \begin{equation}
        \norm{[D_t^2-iA\partial_\alpha,\partial_\alpha^k]\tilde{\theta}}_{L^2}\lesssim\frac{\epsilon^3}{t^{1+\delta}}+\frac{\lambda\epsilon}{H^{\frac{3}{2}}t^{\frac{1}{2}}}+\left(\frac{\epsilon^2}{t^{1+\delta}}+\frac{\lambda}{H^3}\right)\sqrt{\mathfrak{E}_s}
    \end{equation}
and
\begin{equation}
        \norm{[D_t^2-iA\partial_\alpha,\partial_\alpha^k]\tilde{\sigma}}_{L^2}\lesssim\frac{\epsilon^3}{t^{1+\delta}}+\frac{\lambda\epsilon}{H^{\frac{3}{2}}t^\frac{1}{2}}+\left(\frac{\epsilon^2}{t^{1+\delta}}+\frac{\lambda}{H^3}\right)\sqrt{\mathfrak{E}_s}
    \end{equation}
for $1\leq k\leq s$.

