[Definition 1 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $G=(V,E)$ be a finite graph and let $\vp \in \R^V$ be distributed according to
\begin{equation}
	\left< \cdot \right>_{G,\beta,h} = \left< \cdot  \right>_{G,\beta, h, \l} \propto \exp\Big( \beta \sum_{uv \in E} J_{uv} \vp_u \vp_v  + h \sum_{u \in V}  \vp_u \Big) \prod_{u \in V} \d\l(\vp_u)
\end{equation} 
where $J : E \to [0,\infty)$ are the coupling constants, $\beta \geq 0$ is the inverse temperature, $h \in \R$ is the external magnetic field and $\l$ is a reference measure satisfying the assumptions above.

[Theo 9 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Assume that conditions $({\bf A1})$-$({\bf A3})$ are satisfied. We have 
\begin{enumerate}
\item For each $s, t \in  [0, T],\; t \leq s$, $(X^{t,x,\varepsilon},Y^{t,x,\varepsilon},Z^{t,x,\varepsilon})$ the solution of \eqref{Eq1} converges in $\mathcal{S}^2(\R)\times\mathcal{S}^2(\R)\times\mathcal{H}^2(\R^n)$ when $\varepsilon\rightarrow 0$, to $(\mathcal{X}^{t,x},\mathcal{Y}^{t,x},0)$ solution of \eqref{u}.
\item Let denote $Y^{t,x}(t)$ the limit of $Y^{\varepsilon,t,x}(t)$ when $\varepsilon \rightarrow 0$ and set $u(t,{\bf 1}(x))=Y^{t,x}(t)$. Then the function $u$ is a viscosity solution of PDE the following path-dependent PDE 
\begin{eqnarray}
\left\{
\begin{array}{l}
\displaystyle \frac{\partial u (t,{\bf 1}(x))}{\partial t}+b(t,{\bf 1}(x),{\bf 1}(u(t,{\bf 1}(x))),{\bf 1}(0))\frac{\partial u(t,{\bf 1}(x))}{\partial x}\\\\\displaystyle+f\left(t,{\bf 1}(x),{\bf 1}(u(t,{\bf 1}(x))),{\bf 1}(0)\right)=0\\\\
u(T,{\bf 1}(x))=g({\bf 1}(x)),
 \end{array}
 \right.
 \end{eqnarray}
\item The function $u$ is bounded, continuous Lipschitz in $\varphi$ and uniformly continuous in time.
\item Furthermore, if $u\in C^{1,1}_{b}([0, T]\times  L_{-T}^{\infty}(\mathbb{R}))$, since \eqref{u} has a unique continuous solution, the function $u$ is a classical solution of \eqref{u1}.
\end{enumerate}

