[Corollary cor:PTASEP-scalar of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The one-point Fredholm determinant
$F_{t, a, n} = \det(I - K_{t, a, n})$ satisfies
\begin{equation}
pF_{t+1, a, n+1}F_{t+1, a+2, n}
+ qF_{t+1, a+1, n}F_{t+1, a+1, n+1}
- F_{t, a+1, n}F_{t+2, a+1, n+1}
= 0,
\end{equation}
at every $(t, a, n)$ with $a < h_{n+1}(t+1) - 1$.

[Proposition prop_rainbow of arXiv:2609.02136, 'Gamma approximation and Poisson--Gaussian invariance principle on Poisson chaos'] For every $r\geq2$,

\noindent
\begin{align}
 \cum_r\bigl(H_m^{(q)}(c,t)\bigr)
\xrightarrow{m\to\infty} tc^r.

\end{align}

Consequently, with $P_t\sim\Pois(t)$,
\noindent
\begin{align}
 H_m^{(q)}(c,t)&\xrightarrow{\mathrm d}c(P_t-t),
 \notag\\
 \mathbb{E}\left[H_m^{(q)}(c,t)^r\right]
 &\longrightarrow\mathbb{E}\left[c(P_t-t)^r\right],
 \quad r\geq1.

\end{align}
Moreover,
\noindent
\begin{align}
 \mathcal J_4\bigl(H_m^{(q)}(c,t)\bigr)
 =qtc^4(1+3a_m)^{q-1}
 \xrightarrow{m\to\infty} qtc^4.

\end{align}

