[Definition W SPDE-1 of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let $\mathcal{V}[\cdot]$ and $\rho_0$ be defined as in Definition (RKS smooth spde of the paper), for any $\varepsilon,\eta\in(0,1)$, a weak solution  $\rho$ of (equation SPDE-1 of the paper) with initial data $\rho(\cdot, 0)=\rho_0$ is a nonnegative, $\mathcal{F}_{t}$-predictable process that satisfies the following properties.
\begin{enumerate}
		\item Conservation of mass: almost surely for every $t\in[0,T]$,
		\begin{equation}
		\|\rho(\cdot,t)\|_{L^{1}_{\mathbb{T}^{2}}}=\left\|\rho_0\right\|_{L^{1}_{\mathbb{T}^{2}}}.
		\end{equation}




		\item Pathwise entropy dissipation estimates: almost surely, 
		\begin{align}
 \int_0^t\int_{\mathbb{T}^2}
|\nabla\sqrt{\rho}|^2\mathrm{d}x\mathrm{d}s
\lesssim&\int_{\mathbb{T}^2}\Psi(\rho_0)\mathrm{d}x+\sqrt{\varepsilon}\int_0^t\int_{\mathbb{T}^2}
\frac{s_{\eta}(\rho)}{\rho}\nabla\rho\cdot
\xi_{K}
+\varepsilon N_KT+1,
\end{align}
for all $t \in [0,T]$.  

\item The equation: 
for every $\psi \in C^{\infty}_{\mathbb{T}^2}$, almost surely for every $t \in[0, T]$,
\begin{align}
\int_{\mathbb{T}^2} \rho(x, t) \psi(x) & =\int_{\mathbb{T}^2} \rho_0 \psi-\int_{0}^{t} \int_{\mathbb{T}^2} \nabla \rho \cdot \nabla \varphi+\int_{0}^{t} \int_{\mathbb{T}^2}(\rho \mathcal{V}[\rho]) \cdot \nabla \psi \nonumber\\
&+\sqrt{\varepsilon}\int_{0}^{t} \int_{\mathbb{T}^2} s_{\eta}(\rho) \nabla \psi \cdot \xi_{K}-\frac{\varepsilon F_{1,K}}{2} \int_{0}^{t} \int_{\mathbb{T}^2} \left[s_{\eta}^{\prime}(\rho)\right]^{2} \nabla \rho \cdot \nabla \psi. 
\end{align}
\end{enumerate}

