body:
[Lemma 8 of arXiv:2608.30602, '2608.30602'] Let $0<\lambda_0<1$, and suppose that 
	$m(\lambda)= \mathcal{O}_{[b]+2}\big(|\log\lambda|^{-a} \lambda^b\big)$ 
	for $\lambda\in (0,\lambda_0)$ and some fixed $a\ge 0$ and $b>-1$. Then
	\begin{equation}
		\left|\int_0^\infty e^{i\lambda x} m(\lambda) \chi(\lambda/\lambda_0) 
		\, d\lambda\right| \lesssim_{m,\lambda_0} 
		\frac{1}{\langle x\rangle^{b+1}\log^{a}(2+|x|)}, \quad x \in \mathbb{R},
	\end{equation}
	where the cut-off function $\chi$ is given in \eqref{cut-off-fun}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:ridgeless_main of arXiv:2608.23938, 'Generalization, memorization, and overfitting \\for diffusion models trained in the lazy h'] Assume Assumptions (ass:high_dim of the paper) and~(ass:input_dist of the paper), and $\sigma >0$ hold.  Then, the risk of the empirical Bayes denoiser $\widehat {\boldsymbol f}^\star$ is given by
    \begin{equation}
    \left|\mathcal{R}(\widehat {\boldsymbol f}^\star)
    - 2 \frac{\rho^2}{\sigma^2} \frac{{\rm Tr}({\boldsymbol \Sigma})}{d}\right| \prec \frac{1}{\sqrt{d}}.
    \end{equation}




    If we further assume Assumption (ass:universal-kernel of the paper), the post-processed gradient flow estimator (equation eq:gf-endpoint-postprocessing of the paper) satisfies
    \begin{equation}
        \left|\lim_{\mathsf{t} \to \infty} \mathcal{R}(\widetilde {\boldsymbol f}_{\mathsf{t}}) - 2 \frac{\rho^2}{\sigma^2} \frac{{\rm Tr}({\boldsymbol \Sigma})}{d}\right| \prec \frac{1}{\sqrt{d}}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let~\eqref{co:6} hold and $\rho > 0$ be such that
\begin{equation}
\int_{0}^{\infty}\frac{l(s,N(s))^{2}}{1 + s^{2\rho}}\,\mathrm{d}s < \infty.
\end{equation}
Then any solution $I$ to~\eqref{eq:SIS epidemic model} with positive paths satisfies
\begin{align*}
\liminf_{t\uparrow\infty}\frac{1}{t^{\rho}}\log(I_{t}) &= \liminf_{t\uparrow\infty} \frac{1}{t^{\rho}}\int_{0}^{t}h\big(s,I_{s},N(s),\mathcal{L}(I_{s})\big)\,\mathrm{d}s\\
 &\leq \limsup_{t\uparrow\infty} \frac{1}{t^{\rho}}\int_{0}^{t}h\big(s,I_{s},N(s),\mathcal{L}(I_{s})\big)\,\mathrm{d}s = \limsup_{t\uparrow\infty}\frac{1}{t^{\rho}}\log(I_{t})\quad\text{a.s.}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $h,T>0$ such that $\frac Th\in \mathbb{N}$.  For $k\in \{1,\dots,\frac Th\}$ let $\tilde \beta_k$ and $\beta_k$ be $\mathcal{F}_{kh}$ adapted and uniformly bounded by some $b>0$.
    Assume that a recursion scheme is given by
    \begin{align*}
        X_{kh+t}=X_{kh}+\beta_k \bigl(B_{kh+t}-B_{kh}\bigr)+\tilde\beta_k \bigl(\bB_{kh+t}-\bB_{kh}\bigr) \qquad t \in [0,h].
    \end{align*}
    Then it holds that
    \begin{align*}
        \Prob\bigl( \sup_{t \in [0,T]} |X_t| >M \bigr) \le \exp\Bigl(-\frac{M^2}{4b^2T}\Bigr).
    \end{align*}
    In particular for any $\lambda>0$ 
    \begin{align*}
        \E\Bigl[\exp(\lambda |X_T|)\Bigr]<\infty.
    \end{align*}

[Theorem 97 of arXiv:2601.16377, '2601.16377'] Take two variational data satisfying Assumptions~\ref{Assumption_A} and \ref{Assumption_B}. Assume that for any $h \in [H]$ the complex domain $\amsmathbb{M}_h$ in Assumption~\ref{Assumption_B} is common to the two variational data. Then, there exists $\eps > 0$ depending only on the constants in the assumptions such that, if the variational datum $\textnormal{I}$ satisfies the off-criticality Assumption~\ref{Assumption_C} and for any $g,h \in [H]$ the inequalities
\begin{equation*}
\begin{split}
\max\big(|\hat a_h^{\prime\,\textnormal{I}}-\hat a_h^{\prime\,\textnormal{II}}|\,,\,|\hat b_h^{\prime\,\textnormal{I}}-\hat b_h^{\prime\,\textnormal{II}}|\,,\,|\hat n_h^{\textnormal{I}}-\hat n_h^\textnormal{II}|\,,\,|\theta_{g,h}^{\textnormal{I}} - \theta_{g,h}^{\textnormal{II}}|\big) & \leq \eps, \\
 \int_{\max (\hat a_h^{\prime\,\textnormal{I}},\hat a_h^{\prime\,\textnormal{II}})}^{\min(\hat b_h^{\prime\,\textnormal{I}},\hat b_h^{\prime\,\textnormal{II}})} \big|V_h^{\textnormal{I}}(x)-V_h^\textnormal{II}(x)\big| \dd x & \leq \eps, \\
\sup_{z\in \amsmathbb{M}_h} \big|\phi^{\pm,\textnormal{I}}_h(z)-\phi^{\pm,\textnormal{II}}_h(z)\big| & \leq \eps,
\end{split}
\end{equation*}
then the variational datum $\textnormal{II}$ also satisfies Assumption~\ref{Assumption_C}.

[Lemma of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] A sequence $\{P_{N}, N\geq{1}\}$ of probability measures defined on $D([0,T],H^{-m}(\mathbb T))$ is tight if the following two conditions hold:
\begin{equation*}
    \begin{split}
       & (\text{a}) \lim_{A\rightarrow{\infty}}\limsup_{N\rightarrow{\infty}}P_{N}\Big(\sup_{0\leq{t}\leq{T}}\|\pi_{t}\|_{-m}>A\Big)=0\\
       &(\text{b})\lim_{\delta\rightarrow{0}}\limsup_{N\rightarrow{\infty}}P_{N}\big(\omega_{\delta}(\pi)\geq{\varepsilon}\big)=0,\;\text{
for every}\; \varepsilon>0.
    \end{split}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma gamma_exponential_finite  of arXiv:2504.14457, 'Abstract'] For the covariance function $\gamma(s,r)=s^{a_1}r^{a_1}|s-r|^{a_2}$, we have
\begin{align}
    \int_0^t\int_0^t dudv\gamma(u,v)<\infty \hspace{8mm} \text{for all } t>0.
\end{align}

