[Theorem thm:idla-heavy-tail of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds, 
and that~(equation ass:stable-alpha of the paper) holds with $\alpha \in (1,2)$. Then, there exist
constants $c_\alpha, c'_\alpha$
with $0 < c_\alpha \leq c'_\alpha < 1/2$, such that, 
\begin{equation}

 c_\alpha \leq  \liminf_{m \to \infty} \frac{r_m}{m} \leq \limsup_{m \to \infty} \frac{r_m}{m} \leq c'_\alpha, 
  \ \text{a.s.}
\end{equation}
Moreover, one may take for the constant $c_\alpha$ in~(equation eq:r-m-heavy of the paper) the expression
\begin{align}

    c_\alpha & =  \frac{(\alpha -1)  (2-\alpha)^{2-\alpha}}{(4-\alpha)(3-\alpha)^3} .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:laplace-IG of arXiv:2411.06195, 'Restrictions of some reinforced processes to subgraphs'] If $X\sim \operatorname{IG}(\frac{a}{2},\frac{a^2}{2})$ for some $a>0$, then
  \begin{align}
    E[e^{(1-s)X}]=e^{a(1-\sqrt s)}, \quad s\ge 0. 
  \end{align}

[Defi 1 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] \begin{itemize}
\item [(a)] A triple of stochastic processes $(X^{t,x,\varepsilon},Y^{t,x,\varepsilon},Z^{t,x,\varepsilon})$ is said to be an adapted solution of the delayed FBSDE \eqref{Eq1} if, $(X^{t,x,\varepsilon},Y^{t,x,\varepsilon},Z^{t,x,\varepsilon})\in \mathcal{S}^2(\R)\times\mathcal{S}^{2}(\R)\times \mathcal{H}^2(\R)$and if equation \eqref{Eq1} is satisfied $\P$-almost surely.
\item [(b)] A pair of deterministic functions $(\mathcal{X}^{t,x},\mathcal{Y}^{t,x})$ is called a solution of the delayed system of ordinary differential equations \eqref{u} if, $(\mathcal{X}^{t,x},\mathcal{Y}^{t,x})\in L_{-T}^{\infty }\times L_{-T}^{\infty}$ and if system \eqref{u} is satisfied. 
\end{itemize}

