    \mathbb{P}_{\rho_0} \big( \mathcal{E}_{\mathrm{cluster}}^c \big)
    \le C_{\textnormal{\tiny (C:big_cluster of the paper)}} \ell_0^{2 + (m - 1)\beta - ms}.
  \end{equation}

