[Theorem 8 of arXiv:2605.15386, 'The non-central gamma sum and difference distributions: exact distribution and asymptotic '] Let $\alpha_1,\alpha_2,\beta_1,\beta_2>0$ and $\lambda_1,\lambda_2\geq0$. For the asymptotic expansions involving the sum $X_1+X_2$ we further suppose that $\beta_1>\beta_2$.

\vspace{3mm}

\noindent 1. Suppose that $\lambda_1\neq0$.
	Then, as $x\rightarrow\infty$,
	\begin{align}
		f_{X_1\mp X_2}(x)&\sim\frac{1}{2\sqrt{\pi}}\bigg(\frac{1}{\beta_2}\pm\frac{1}{\beta_1}\bigg)^{-\alpha_2}\beta_1^{-\alpha_1}\beta_2^{-\alpha_2}\bigg(\frac{\lambda_1}{\beta_1}\bigg)^{(1-2\alpha_1)/4}\exp\bigg(-\lambda_1-\frac{\lambda_2\beta_2}{\beta_2\pm\beta_1}\bigg)\nonumber\\
		&\quad\times x^{(2\alpha_1-3)/4}\exp\bigg(2\sqrt{\frac{\lambda_1x}{\beta_1}}-\frac{x}{\beta_1}\bigg)\sum_{l=0}^{\infty}\frac{c_l(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)}{x^{l/2}},
	\end{align}
	where $c_0(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)=1$ and
\begin{align}
c_l(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)&=

\sum_{j=0}^l\frac{(3/2+j-\alpha_1)_{l-j}(\alpha_1-j-1/2)_{l-j}}{(l-j)!4^{l-j}}\nonumber\\
&\quad\times \bigg(\frac{\beta_1}{\lambda_1}\bigg)^{l/2-j}\bigg(\frac{1}{\beta_1}\pm\frac{1}{\beta_2}\bigg)^{-j} L_j^{(\alpha_2-1)}\bigg(-\frac{\lambda_2\beta_1}{\beta_1\pm\beta_2}\bigg), \quad l\geq1.  
\end{align}    

	2. Suppose that $\lambda_1=0$. Then, as $x\rightarrow\infty$,
	\begin{align}
		f_{X_1\mp X_2}(x)\sim \frac{\beta_1^{-\alpha_1}\beta_2^{-\alpha_2}}{\Gamma(\alpha_1)}\bigg(\frac{1}{\beta_2}\pm\frac{1}{\beta_1}\bigg)^{-\alpha_2}x^{\alpha_1-1}\exp\bigg(-\frac{x}{\beta_1}-\frac{\lambda_2\beta_2}{\beta_2\pm\beta_1}\bigg)\sum_{k=0}^{\infty}\frac{d_k(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2)}{x^k},
	\end{align}
		where $d_0(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2)=1$ and

	\begin{align}

		d_k(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2)&=(-1)^k(1-\alpha_1)_k\bigg(\frac{1}{\beta_1}\pm\frac{1}{\beta_2}\bigg)^{-k}L_k^{(\alpha_2-1)}\bigg(-\frac{\lambda_2\beta_1}{\beta_1\pm\beta_2}\bigg), \quad k\geq1. \nonumber




	\end{align}
3. Suppose that $\lambda_2\neq0$.
	Then, as $x\rightarrow-\infty$,
	\begin{align}
		f_{X_1- X_2}(x)&\sim\frac{1}{2\sqrt{\pi}}\bigg(\frac{1}{\beta_1}+\frac{1}{\beta_2}\bigg)^{-\alpha_1}\beta_1^{-\alpha_1}\beta_2^{-\alpha_2}\bigg(\frac{\lambda_2}{\beta_2}\bigg)^{(1-2\alpha_2)/4}\exp\bigg(-\lambda_2-\frac{\lambda_1\beta_1}{\beta_1+\beta_2}\bigg)\nonumber\\
		&\quad\times |x|^{(2\alpha_2-3)/4}\exp\bigg(2\sqrt{\frac{\lambda_2|x|}{\beta_2}}+\frac{x}{\beta_2}\bigg)\sum_{l=0}^{\infty}\frac{c_l(\alpha_2,\alpha_1,\beta_2,\beta_1,\lambda_2,\lambda_1)}{x^{l/2}}.
	\end{align}


	4. Suppose that $\lambda_2=0$. Then, as $x\rightarrow-\infty$,
	\begin{align}
		f_{X_1-X_2}(x)\sim\frac{\beta_1^{-\alpha_1}\beta_2^{-\alpha_2}}{\Gamma(\alpha_2)}\bigg(\frac{1}{\beta_1}+\frac{1}{\beta_2}\bigg)^{-\alpha_1}|x|^{\alpha_2-1}\exp\bigg(\frac{x}{\beta_2}-\frac{\lambda_1\beta_1}{\beta_1+\beta_2}\bigg)\sum_{k=0}^{\infty}\frac{d_k(\alpha_2,\alpha_1,\beta_2,\beta_1,\lambda_1)}{|x|^k}.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:basic-facts-no-assumptions of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\Omega,\mathcal{Z})$ be a gamble space and $X,Y:\Omega\to\overline{\mathbb{R}}$ variables.
  Then we have
  \begin{enumerate}
  \item $\overline{\textsf{\textbf{E}}} (X + c) = \overline{\textsf{\textbf{E}}} X + c$ for all $c\in\mathbb{R}$ (translation)
  \item $X \leq Y \implies \overline{\textsf{\textbf{E}}} X \leq \overline{\textsf{\textbf{E}}} Y$ (monotonicity).
  \end{enumerate}

