body:
[Ppn 45 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $F^{\rvii}$ and $F^{\rviii}$ be as defined by \eqref{e:fp.F.vii} and \eqref{e:fp.F.rviii} respectively. There exists a positive constant $c$, depending on the parameters in Remark~\ref{r:fp-rpr}, such that we have
    \[
        \P(F^{\rvii} \ge t) \le
        \P\bigg(F^{\rviii} \ge t +
            \frac{\epsilon'}{10}\bigg) + e^{-cN}
    \]
for all $t\in\R$.
That is, $F^{\rvii}$ is approximately stochastically dominated by
$F^{\rviii}$.

\begin{proof}
Recall from \eqref{e:fp.F.vii} that $F^{\rvii}$ involves a supremum over $\|\by\|^2=N$ and a supremum over $\btheta_+\in\bTheta_+$, and we may exchange the order of these to write
    \begin{align*}
    F^{\rvii}
    &=\sup_{\btheta_+\in\bTheta_+}\bigg\{
    \sup_{\|\by\|^2=N}
    \bigg[
     \frac{(\dbD \by, \by)}{N}+\frac{(\dbX \by, \by)}{N}
            +\frac{2\|\btheta_+\|}{(M\alpha)^{1/2}} \frac{(\dbg_+,\by)}{N}
            + \frac{2(\gamma_-)^{1/2}(\dbg_-,\by)}{N}\bigg]\\
            &\qquad+\frac{2(\hbg_+,\btheta_+)}{M}
    -\frac{(\btheta_+,(\hbD_+)^{-1}\btheta_+)}{M}
    +\alpha \sum_{j\in J_-} \frac{\lambda_j \hv_j}{\alpha
        -\hv_j m(z_\star) }
        -m(z_\star)\gamma_-
        \bigg\}\,.
    \end{align*}
We will use Proposition~\ref{p:fp-g} to show that in the first line above, the supremum over $\|\by\|^2=N$ can be upper bounded, up to small additive error, by the $g$ term in \eqref{e:fp.F.rviii.plus}; this will imply the claimed result. 
To this end, consider any $\gamma_+ \ge 0$, and note $(\gamma_+)^{1/2} \dbg_+ + (\gamma_-)^{1/2} \dbg_-$ is equidistributed as $(\gamma_+ + \gamma_-)^{1/2} \dbg$, where $\dbg$ is a standard gaussian in $\R^N$. By Lemma~\ref{l:fp-uniform-bound},
\beq

    \gamma_- 
    \stackrel{\eqref{e:fp.gamma.minus}}{\le} \gamma_\star
    \le C_7
    = C_7(\alpha,\iota)\,.
\eeq
We now apply Proposition~\ref{p:fp-g} with constant $C_9 = (C_8 / \alpha)^2 + C_7$, with $C_8=C_8(\alpha,\iota)$ as in Lemma~\ref{l:fp-theta-plus-bdd} and \eqref{e:fp.restricted.Theta}.  This implies that with probability at least $1-e^{-cN}$, simultaneously for all $\gamma_+ \ge 0$ such that $\gamma_+ + \gamma_- \in [0,C_9]$, we have
    \beq

        \sup_{\|\by\|^2=N} \bigg\{
            \frac{(\dbD \by, \by)}{N}
            + \frac{(\dbX \by, \by)}{N}
            + \frac{2(\gamma_+)^{1/2}(\dbg_+,\by)}{N}
            + \frac{2(\gamma_-)^{1/2}(\dbg_-,\by)}{N}
        \bigg\}
        \le g(\gamma_+ + \gamma_-)
        + \frac{\epsilon'}{10}
        \,.
    \eeq
In particular, by \eqref{e:fp-vi-to-vii-gamma-minus}, the estimate \eqref{e:fp-v-to-vii} holds for all $\gamma_+ \in [0,(C_8 / \alpha)^2]$. Finally, let 
    \[
    \gamma_+ 
    = \frac{\|\btheta_+\|^2}{M\alpha}
    \le \bigg(\frac{C_8}{\alpha}\bigg)^2\,,
    \]
where the last inequality is by the restriction of $\btheta_+$ to $\bTheta_+$, as in \eqref{e:fp.restricted.Theta}. We conclude that with probability at least $1-e^{-cN}$, we have
    \[
        \frac{(\dbD \by, \by)}{N}
        + \frac{(\dbX \by, \by)}{N}
        +\frac{2\|\btheta_+\|}{(M\alpha)^{1/2}} \frac{(\dbg_+,\by)}{N}
        + \frac{2(\gamma_-)^{1/2}(\dbg_-,\by)}{N}
        \le g\bigg(
            \frac{\|\btheta_+\|^2}{M\alpha}
            + \gamma_-
        \bigg) +\frac{\epsilon'}{10}\,.
    \]
    for all $\|\by\|^2=N$ and all $\btheta_+\in\bTheta_+$. This shows that with probability at least $1-e^{-cN}$, we have
    \[
        F^{\rvii}\le
        \sup_{\btheta_+ \in \bTheta_+}
        \bigg\{
            F^{\rviii,+}(\btheta_+)
        \bigg\} 
        + \alpha \sum_{j\in J_-} \frac{\lambda_j \hv_j}{\alpha - \hv_jm(z_\star)}
        - m(z_\star) \gamma_-
        + \frac{\epsilon'}{10}\,.
    \] 
Finally, we note that relaxing the supremum to $\btheta_+ \in \bbR^{B_+}$ as in \eqref{e:fp.F.rviii} only makes the value of $F^{\rviii}$ larger, so the conclusion follows.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:mainhere of arXiv:2511.08479, '\Large From disordered systems to the Critical 2D Stochastic Heat Flow'] Let $Z_{\Omega_{\delta} ; \beta_\delta, h_\delta}^{\omega}$ be the disordered partition function defined as in (equation eq:Zom of the paper).
Suppose the reference measure $\ensuremath{\mathbf P}_{\Omega_{\delta}}^{\text {ref }}$ satisfies Assumption~(ass:main of the paper) for some exponent
$\gamma<d/2$. Then choosing
\begin{equation}
\beta_\delta =\hat\beta \delta^{\frac{d}{2}-\gamma}, \qquad h_\delta= - \log {\ensuremath{\mathbb E}} [e^{\beta_\delta \omega_x}] +  \hat h \delta^{d-\gamma}
\qquad \mbox{for some } \hat\beta>0 \mbox{ and } \hat h\in \mathbb{R} \,,
\end{equation}
we have
\begin{equation*}
	Z_{\Omega_\delta; \beta_\delta, h_\delta}^\omega
	\ \xrightarrow[\,\delta \downarrow 0\,]{(d)} \
	\mathscr{Z}^W_{\Omega; \hat\beta, \hat h},
\end{equation*}
where $W$ is a white noise on $\Omega$, and $\mathscr{Z}^W_{\Omega; \hat\beta, \hat h}$ admits the following {\it Wiener-It\^o chaos expansion}
\begin{align}
\mathscr{Z}^W_{\Omega; \hat\beta} := 1 +
	\sum_{k=1}^{\infty} \;
	\frac{1}{k!} \,
	\idotsint_{\Omega^k}
	\boldsymbol{\psi}^{(k)}_{\Omega}(x_1, \ldots, x_k)
	\, \prod_{i=1}^k \, (\hat \beta W(\text{\rm d} x_i) +\hat h {\rm d}x_i) \,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] For each $\Phi\in \sC_{t_0}$, $\xi\mapsto \mathcal{I}_{t_0,\xi}$ is a lower semicontinuous (l.s.c.) map from $H$ to $[0,+\infty]$. Furthermore, for each $M<+\infty$,
\begin{align*}
  \Lambda_{M,t_0,K}:=\{\Phi\in \sC_{t_0}: \mathcal{I}_{t_0,\xi}(\Phi)\leq M, \, \xi\in K\}
\end{align*}
is a compact subset of $\sC_{t_0}$.

