[Thmd 5 ({\bf{Theorem 3}}, \cite{DenRe}) of arXiv:2606.08115, '2606.08115'] Let the assumptions (G) and (M) hold, $p \ge 1$. Then
\begin{enumerate}
\item[1)] there exists a positive constant $C$ and vector $\ov{x}_0 \in K$ such that for every vector $\ov{x} \in K$ the following inequality holds
\begin{equation*}

\pr \left( \tau(\ov{x}) > n \right) \le C \frac{u \left( \ov{x} + \ov{x}_0\right)}{n^{p/2}};
\end{equation*}
\item[2)] uniformly in $\ov{x} \in K$ such that $\left|\ov{x}\right| \le \sqrt{n}/\ln n$
\begin{equation*}

\pr \left( \tau(\ov{x}) > n \right) \sim \frac{\varkappa \widehat{V}(\ov{x})}{n^{p/2}}, \;\; n \to \infty,
\end{equation*}
where $\varkappa > 0$ is a constant, which does not depend on $\ov{x}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

