[Theorem of arXiv:2608.10415, 'Continuous random variables'] The cumulants have the following properties:
\begin{enumerate}
\item $k_n(cf)=c^nk_n(f)$.

\item $k_1(f+d)=k_1(f)+d$, and $k_n(f+d)=k_n(f)$ for $n>1$.

\item $k_n(f+g)=k_n(f)+k_n(g)$, if $f,g$ are independent.
\end{enumerate}

[Proposition prop:GRet_bound of arXiv:2605.16086, 'Loop pruning and downward deviations for maximum local time of discrete-time simple random'] There exists \(c=c(E)>0\) such that for any \(K\ge 256\) and any integer interval \(I\subset\mathbb{Z}\) whose length \(|I|\) is sufficiently large and an integer multiple of \(2L\),
\begin{align}
&\mathbb{P}\big(m=r,\, \mathsf{Ret}^{+}_J(\mathbf a)\big)\le e^{-cKr}
\ \  \forall\,r\in\mathbb{N}^+,\,J\subset[r],\,\mathbf a\in \mathcal{P}^+(J)\text{ with }\|\mathbf a\|_1\ge \tfrac1{64} Kr,\\
&\mathbb{P}\big(m=r,\, \mathsf{Ret}^{-}_J(\mathbf a)\big)\le e^{-cKr}
\ \  \forall\,r\in\mathbb{N}^+,\,J\subset[r],\,\mathbf a\in \mathcal{P}^-(J)\text{ with }\|\mathbf a\|_1\ge \tfrac1{64} Kr.
\end{align}

[Lemma how to prove convergence of disordered measures of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] {}
	Suppose that there exist $\beta_{\delta}$ such that the following conditions are satisfied:
	\begin{enumerate}[label = {(\alph*)}]
		\item{}
		$\mathrm{P}_{\Omega_{\delta}}^{\mathrm{ref}}$ converges in ${\ensuremath{\mathcal M}} _1(E)$ to a probability distribution ${\ensuremath{\mathbf P}} _{\Omega}$;
		\item{}
		for every function $G \in {\ensuremath{\mathcal C}} _b(E)$, for every $\ensuremath{\mathbf{f}} \in {\ensuremath{\mathcal D}} (\Omega)$, there exist a random variable ${\ensuremath{\mathcal Z}}_{\Omega}^{\boldsymbol\zeta}$ measurable with respect to $\boldsymbol\zeta$ such that, as $\delta \downarrow 0$,
		\[
		\big(\langle \boldsymbol\zeta_{\delta},\ensuremath{\mathbf{f}} \rangle, Z_{\Omega_{\delta}}^{\omega,\beta_{\delta}}(G)\big) \xrightarrow{\ (d)\ } \big(\langle \boldsymbol\zeta,\ensuremath{\mathbf{f}} \rangle, {\ensuremath{\mathcal Z}}_{\Omega}^{\boldsymbol\zeta}(G)\big)\,.
		\]
		\item{}
		The random variable ${\ensuremath{\mathcal Z}}_{\Omega}^{\boldsymbol\zeta}(1)$ is almost surely strictly positive.
	\end{enumerate}
	Then there exist a random probability measure \({\ensuremath{\mathbf P}} _{\Omega}^{\boldsymbol\zeta} \in {\ensuremath{\mathcal M}} _1(E)\) such that we have the following joint convergence in distribution in $H_{\rm loc}^{-s}(\Omega) \times {\ensuremath{\mathcal M}} _1(E)$, $s > \frac{D}{2}$,
	\begin{equation*}
		(\zeta_{\delta}, \mathrm{P}_{\Omega_{\delta}}^{\omega,\beta_{\delta}}) \xrightarrow{(d)} (\boldsymbol\zeta, {\ensuremath{\mathbf P}} _{\Omega}^{\boldsymbol\zeta}) \quad\text{ as } \delta\downarrow 0 \,. 
	\end{equation*}

