body:
[Lem 10 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] If $n_1\ge n_2+1$, then
\beq
	\QQ_2^{(n_1,n_2)}=(-1)^{n_1+n_2}
	\sum_{\substack{0\le i,j\le n_2\\2n_2-n_1+1\le i+j\le n_2}}
	\binom{n_2}{i}\binom{n_2}{j}\binom{n_1-n_2-1}{n_2-i-j}
	\J^{2^{n_2-i}1^{n_1}2^i}_{2^{n_2-j}1^{n_1}2^j}.
\eeq
If $n_1\le n_2$, then
\beq
	\QQ_2^{(n_1,n_2)}=(-1)^{n_2-1}
	\sum_{\substack{0\le i,j\le n_2\\i+j\ge2n_2-n_1+1}}
	(-1)^{i+j}\binom{n_2}{i}\binom{n_2}{j}
	\binom{i+j-n_2-1}{n_2-n_1}
	\J^{2^{n_2-i}1^{n_1}2^i}_{2^{n_2-j}1^{n_1}2^j}.
\eeq

