[Definition 32 (\cite{Gromov1987}, Appendix B.1 \cite{Chevyrev2022}) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] \begin{enumerate}[i)]
        \item An $\mathbb{R}$-tree is a metric space $\mathfrak{T}$ such that for every three points $x,y,\rho\in \mathfrak{T}$ there exists a point $c=x\wedge y$ such that the geodesic segments $[\rho ,x],[\rho ,y]$ intersect in the segment $[\rho ,c]$ and also $c\in [x,y]$.
        \item For a topological space $\mathcal{X}$, a function $x:[0,T_x]\rightarrow\mathcal{X}$ is called tree-like if $x$ is continuous and there exists an $\mathbb{R}$-tree $\mathfrak{T}$, a continuous function $\varphi:[0,T_x]\rightarrow\mathfrak{T}$, and a map $\psi:\mathfrak{T}\rightarrow\mathcal{X}$ such that $\varphi(0)=\varphi(T_x)$ and $x=\psi\circ\varphi$.
        \item Let
        \begin{equation*}
            \overleftarrow{x}:[0,T_x]\rightarrow\mathcal{X};\qquad \overleftarrow{x}(t):=x(T_x-t)
        \end{equation*}
        denote the time-reversal of $x$. For another function $y:[0,T_y]\rightarrow\mathcal{X}$, we denote by $x*y$ the concatenation of $x$ and $y$. That is,
        \begin{equation*}
            x*y:[0,T_x+T_y]\rightarrow\mathcal{X};\qquad x*y(t)=\begin{cases}
                x(t)\quad &t\in[0,T_x]\\
                y(t)\quad &t\in(T_x,T_x+T_y].
            \end{cases}
        \end{equation*}
        We say that $x$ and $y$ are tree-like-equivalent, and write $x\sim_t y$, if $x*\overleftarrow{y}$ is tree-like.
    \end{enumerate}

[Lemma 16 of arXiv:2605.11279, 'Flocking with Multiple Types: Competition, Fluid Limits and Traveling Waves'] Suppose $Z\sim \expo(1)$ and $v_+>v_- = 0$. The following statements about the system of first-order ODEs \eqref{sysFluid1} are true:
    \begin{enumerate}[label = (\alph*)]
        \item  The system of first-order ODEs \eqref{sysFluid1} has exactly two fixed points (or equilibria) given by $(0, 0)$ and $(1, 1)$.

        \item  The linearized version of \eqref{sysFluid1} at $(0, 0)$,
        \begin{align}

            {\setlength{\nulldelimiterspace}{0pt}
            \left\{
            \begin{aligned}
                &\dot{x} = -\dfrac{v^+ -\gamma + \alpha^+ - \rho^-}{\gamma} x + \dfrac{\rho^- \parens*{\rho\displaystyle^+ + \alpha\displaystyle^- + \gamma}}{\gamma \rho\displaystyle^+} y \\
                &\dot{y} = \dfrac{\rho\displaystyle^+ \parens*{\alpha\displaystyle^+ - \rho\displaystyle^-}}{\gamma \rho\displaystyle^-} x - \dfrac{\rho\displaystyle^+ + \alpha\displaystyle^-}{\gamma} y
            \end{aligned}
            \right.},
        \end{align}
        has a stable equilibrium at $(0, 0)$, in the sense that both eigenvalues of the associated Jacobian at $(0, 0)$,
        \begin{align}

            J(0, 0) = \begin{bmatrix}
                -\dfrac{v_+ -\gamma + \alpha^+ - \rho^-}{\gamma} & \dfrac{\rho\displaystyle^-\parens*{\rho^+ + \alpha^- + \gamma}}{\gamma \rho\displaystyle^+} \\
                \dfrac{\rho^+\parens*{\alpha^+-\rho^-}}{\gamma \rho\displaystyle^-}& -\dfrac{\rho^+ + \alpha^-}{\gamma}
            \end{bmatrix},
        \end{align}
        are real and negative.

         In addition, let $\lambda_1 < \lambda_2 < 0$ denote the two eigenvalues of $J(0, 0)$. Then an eigenvector corresponding to $\lambda_1$ has coordinates of opposite signs, while an eigenvector corresponding to $\lambda_2$ has coordinates of the same sign. (In each case, the corresponding eigenvector has non-zero coordinates.) 

        \item  The linearized version of \eqref{sysFluid1} at $(1, 1)$,
        \begin{align}

            {\setlength{\nulldelimiterspace}{0pt}
            \left\{
            \begin{aligned}
                &\dot{x} = -\dfrac{v^+ -\gamma + \alpha^+}{\gamma} x + \dfrac{\rho^- \parens*{\alpha\displaystyle^- + \gamma}}{\gamma \rho\displaystyle^+} y \\
                &\dot{y} = \dfrac{\rho\displaystyle^+ \alpha\displaystyle^+}{\gamma \rho\displaystyle^-} x - \dfrac{\alpha\displaystyle^-}{\gamma} y
            \end{aligned}
            \right.},
        \end{align}
        has a one-dimensional unstable manifold, in the sense that the associated Jacobian $J(1, 1)$ has two real eigenvalues $\lambda_u$ and $\lambda_s$ such that $\lambda_s < 0 < \lambda_u$. Moreover, the eigenvector $\vv_u = \begin{bmatrix} x_u & & y_u\end{bmatrix}\tran$ corresponding to $\lambda_u$ satisfies
        \begin{align*}
            \dfrac{v^+ - \gamma + \alpha\displaystyle^+}{v_+ - \gamma + \alpha\displaystyle^+ - \rho\displaystyle^-} < \dfrac{y_u}{x_u} < \dfrac{\alpha\displaystyle^+}{\alpha\displaystyle^+ - \rho\displaystyle^-}.
        \end{align*}
    \end{enumerate}

