[Lemma lem:CapVolume of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] For any $\mathbf{v}\in\mathbb{S}^{m-1}_+$, ${\boldsymbol{\beta}}\in (-1,\infty)^m$ and $s\in(s_1(\mathbf{v}),\|\mathbf{v}\|_1)$ we have
    \begin{align*}
        \mathbb{P}_{m}(C^+(\mathbf{v},s);{\boldsymbol{\beta}}) 
             &\asymp(\|\mathbf{v}\|_1-s)^{\beta+m} \prod_{i=1}^m v_i^{-\beta_i-1}.
    \end{align*}
    Note that $s\in (s_1(\mathbf{v}),\|\mathbf{v}\|_1)$ implies in particular that the latter interval is not empty and $\|\mathbf{v}\|_1\neq s_1(\mathbf{v})$, which is equivalent to $v_i>0$ for all $i\in\{1,\ldots,m\}$.

[Theorem Nkq<1 of arXiv:2509.24452, 'A family of non-uniform distributions on the set of parking functions generated by random '] Consider $N^{(n)}_k$ as in (equation Nk of the paper)  under the measure $\mathcal{P}_n^{(q)}$ with $q<1$.

\noindent i. For fixed $k$, $\lim_{n\to\infty}\frac{N^{(n)}_k}n\stackrel{\text{\rm dist}}{=}(1-q)q^{k-1}$;

\noindent ii. If $\lim_{n\to\infty} nq^{k_n}=\infty$, then $\lim_{n\to\infty}\frac{N^{(n)}_{k_n}}{nq^{k_n}}\stackrel{\text{\rm dist}}{=}\frac{1-q}q$.

\noindent iii. If $L:=\lim_{n\to\infty} nq^{k_n}\in(0,\infty)$, then $N^{(n)}_{k_n}$ converges in distribution to the Poisson distribution with parameter $\frac{1-q}qL$;

\noindent iv. If $\lim_{n\to\infty} nq^{k_n}=0$, then $\lim_{n\to\infty}N^{(n)}_{k_n}\stackrel{\text{\rm dist}}{=}0$; (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:double-well-vanish of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Consider the following one-dimensional McKean-Vlasov SDE,
\begin{equation}
\mathop{}\!\mathrm{d} X_t=-\left[V'(X_t)+\theta\left(X_t-\mathbf E [X_t]\right)\right]\mathop{}\!\mathrm{d} t+\sigma(X_t)\mathop{}\!\mathrm{d} B_t.
\end{equation}
where
\[
V'(x)=
\begin{cases}
    x\big(x-\frac{31}{32}\big)\big(x+\frac{31}{32}\big), & x\in \big(-\frac{31}{32},\frac{31}{32}\big),\\
    0, & x\in \big(-1,-\frac{31}{32}\big]\cup\big[\frac{31}{32},1\big),\\
    x(x-1)(x+1), & x\in (-\8,-1]\cup [1, \8).
\end{cases}
\]
If the parameter $\theta$ and the Lipschitz function $\sigma\colon\mathbb R\to\mathbb R$ satisfy
\begin{equation}
    \theta\geq\frac{27(9+\sqrt{17})}{128},\quad 0<\inf_{x\in\mathbb R}\sigma^2(x)\leq \sup_{x\in\mathbb R}\sigma^2(x)<\frac{51\sqrt{17}-171}{256},
\end{equation}
and let $r=\frac{9-\sqrt{17}}{8}$, then the exactly same results as in Theorem (thm:double-well of the paper) are valid. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:psi_def of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Fix $n \in \mathbb{N}$ and words ${\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}} \in V$ and ${\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}} \in V$. We define the switching operator 
    ${\bf\Psi}_{{\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}}}^{{\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}}}: \eTA \to \eTA$ by
    \begin{equation}
        {\bf\Psi}_{{\color{NavyBlue}{\mathbf{u_1}}}, \ldots, {\color{NavyBlue}{\mathbf{u_n}}}}^{{\color{NavyBlue}{\mathbf{w_1}}}, \ldots, {\color{NavyBlue}{\mathbf{w_n}}}} \colon 
        \mathbbm{x} \mapsto \sum_{{\color{NavyBlue}{\mathbf{v_0}}}, \ldots, {\color{NavyBlue}{\mathbf{v_n}}}} \mathbbm{x}^{{\color{NavyBlue}{\mathbf{v_0 w_1 v_1 \ldots w_n v_n}}}} 
        ({\color{NavyBlue}{\mathbf{v_0}}} {\color{NavyBlue}{\mathbf{u_1}}} {\color{NavyBlue}{\mathbf{v_1}}} \ldots {\color{NavyBlue}{\mathbf{u_n}}} {\color{NavyBlue}{\mathbf{v_n}}}).
    \end{equation}

[Thm 1 of arXiv:2604.10395, 'A remark on the comparison of the sum and the maximum of positive random variables'] Assume that $X_1$ has a strictly positive density $f$ supported on
$(0,\infty)$ and that there exist four positive constants $c_1, c_2, \alpha$, and $\beta$ such that 
\begin{equation} 
\lim_{x \to +0} \frac{f(x)}{x^{\alpha-1}} = c_1.  
\end{equation}  
\begin{equation}
\lim_{x \to \infty} \frac{-\log f(x)}{x^{\beta}} = c_2.  
\end{equation}  
Assume that $n \ge 2$ and 
\begin{equation}
\beta < \frac{\log n}{\log n + h(\alpha) - h(n\alpha)}. 
\end{equation}
Then there is no constant $C$ such that $S_n = CM_n$ in distribution. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition al-converges of arXiv:2603.01823, 'on a fractional stochastic heat equation arising from the disordered pinning model'] For $k_0\in 2\mathbb N$ and $\rho_{k_0,L}$ defined in (equation e:rho-kL of the paper), if $\rho_{k_0,L}\in \mathcal{H}^{\otimes k_0}$, then for all integers $1\le k\le k_0$,
\begin{enumerate}

\item  As $n\to\infty$, $\mathscr{E}_n(\nu_L,\nu_L')$ converges in $L^k(\mathbf{P}_{(t,x)}^{\otimes 2})$, and the limit is the mutual energy $\mathscr{E}(\nu_L, \nu_L')$ defined in Definition~(def:al of the paper);

\item $\Vert\mathscr{E}(\nu_L,\nu_L')\Vert^k_{L^k(\mathbf{P}_{(t,x)}^{\otimes2})}=\Vert\rho_{k,L}\Vert^2_{\mathcal{H}^{\otimes k}}.$ 
\end{enumerate}

[Lemma lem:pole-mixed-hermite-coupling of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Assume (equation eq:pole-coefficient-class of the paper).  Fix
$\alpha,K\geq0$, $0<r\leq T$, $N_{\mathrm H}\geq1$, and
$C_{\mathrm{cmp}}>0$.  Let
$J\subset(0,1]$ be an interval with $\inf J>0$,
and let $q_{\mathrm{lo}}=\Pi_{\mathrm{lo}}q_{\mathrm{lo}}$ belong to the graph
class $W^{1,2}(J;L^2(\gamma_d))\cap L^2(J;\mathscr D_\gamma)$.  There exists a constant
$C_0=C_0(N_{\mathrm H},T,\lambda,\Lambda)>0$ such that, with all norms restricted to $J$,
\begin{align}
 \norm{(\mathcal P_r-\mathcal P_{\mathrm{Br}})q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}
 +\norm{(\mathcal J_r-\mathcal J_{\mathrm{Br}})q_{\mathrm{lo}}}_{\mathscr Y_{\alpha,K,r}}
 \leq C_0\mathcal M_d(a)r
       \norm{(I+\mathcal N)q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}},
 \\
 \norm{\Pi_{\mathrm{hi}}\mathcal P_rq_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}
 \leq C_0\mathcal M_d(a)r
       \norm{(I+\mathcal N)q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}.

\end{align}
If, in addition, $q_{\mathrm{hi}}=\Pi_{\mathrm{hi}}q_{\mathrm{hi}}$ belongs to
the same graph class and satisfies the ellipticity-controlled comparison
\begin{equation}
 \norm{q_{\mathrm{hi}}}_{\gamma_d}
 +s^{-1}\norm{Dq_{\mathrm{hi}}}_{\gamma_d}
 +s^{-1}\norm{D^2q_{\mathrm{hi}}}_{\gamma_d}
 \leq C_{\mathrm{cmp}}\norm{\mathcal J_rq_{\mathrm{hi}}}_{\gamma_d}
 \quad\text{for a.e. }s\in J,

\end{equation}
then there exists a constant
$C=C(N_{\mathrm H},T,\lambda,\Lambda,C_{\mathrm{cmp}})>0$ such that
\begin{align}
 \norm{\Pi_{\mathrm{lo}}\mathcal P_rq_{\mathrm{hi}}}_{\mathscr X_{\alpha,K,r}}
 &\leq C\mathcal M_d(a)r
       \norm{\mathcal J_rq_{\mathrm{hi}}}_{\mathscr Y_{\alpha,K,r}},
 \\
 \left|\inner{\mathcal J_rq_{\mathrm{lo}}}
                   {\mathcal J_rq_{\mathrm{hi}}}_{\mathscr Y_{\alpha,K,r}}\right|
 &\leq C\mathcal M_d(a)r
       \norm{(I+\mathcal N)q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}
       \norm{\mathcal J_rq_{\mathrm{hi}}}_{\mathscr Y_{\alpha,K,r}}.

\end{align}

