[Lem spinFraction:ExpectContraction of arXiv:2607.09841, 'Mixing and cutoff for the systematic scan dynamics of the mean-field ferromagnetic Potts m'] Let $\gamma_n$ be the unique positive real root of the equation $ \sum_{i= 1}^n \gamma_n^{-i} = nq/\beta$.
Then, for all integer $t \ge 0$ such that $t \leq n\sqrt{n}$ there exist constants $\rho = \rho(\beta, q)$ and $C = C(\rho, \beta, q)$ such that 
for any $\sigma_0 \in \Sigma_n^{\rho}$
\begin{align*}
        \mathbb{E}\big[ \lVert \alpha(\sigma_{t}) - \hat{e} \rVert_2^2 \big] \leq C \rho^2 \gamma_n^{2t}  +\frac{C}{n}.
    \end{align*}
\begin{proof}
We let $t_m = t_m(t) =\max\{1, t-n+1\}$. From (equation eqn:spinFraction:alphaDefn of the paper), the following holds for all $ t \geq 0$ and $\ell \in Q$
\begin{align*}
    \alpha_\ell(\sigma_t) = \frac{1}{n} \sum_{i = t-n+1}^0 \mathbf{1}\big(\sigma_0(n+i) = \ell\big) + \frac{1}{n}\sum_{i = t_m}^{t} \mathbf{1}\big(J_i = \ell\big),
\end{align*}
and thus
\begin{align}
    \mathbb{E}\big[\alpha_\ell(\sigma_t)\big] 
        &= \frac{1}{n} \sum_{i = t-n+1}^0 \mathbf{1}\big(\sigma_0(n+i) = \ell\big) + \frac{1}{n}\sum_{i = t_m}^{t} \mathbb{E} \big[\mathbf{1}(J_i = \ell)\big]  \notag\\
        &= \frac{1}{n} \sum_{i = t-n+1}^0 \mathbf{1}\big(\sigma_0(n+i) = \ell\big) + \frac{1}{n}\sum_{i = t_m}^{t}  \mathbb{E}\Big[g_\beta^\ell\Big(\alpha(\sigma_{i-1}) - \frac{1}{n}u_{i-n}\Big)\Big]. 
\end{align}
From Lemmas~(lem:BurnIn:XFractionDominatesGibbsProbability of the paper) and~(lemma:g:taylor of the paper)(equation lemma:g:taylor:Taylorg_beta^lFinal of the paper), we obtain
\begin{align*}
    \mathbb{E}\Big[g_\beta^\ell\Big(\alpha(\sigma_{i-1}) - \frac{1}{n}u_{i-n}\Big)\Big]
    &\leq \frac{\beta}{n} + \mathbb{E}\Big[g_\beta^\ell\big(\alpha(\sigma_{i-1}) \big)\Big] \\
    &\leq \frac{\beta}{n} + \frac{1}{q} + \frac{\beta} {q}\mathbb{E}\Big[\alpha_\ell(\sigma_{i-1}) - \frac{1}{q} \Big]  + 3q\beta^2 \mathbb{E}\big[  \lVert\alpha(\sigma_{i}) - \hat e \rVert_2^2\big]\\
    &\leq \frac{\beta}{n} + 3q\beta^2\mathrm{Var}\big(\alpha(\sigma_i)\big) + \frac{1}{q} + \frac{\beta} {q}\mathbb{E}\Big[\alpha_\ell(\sigma_{i-1}) - \frac{1}{q} \Big]  + 3q\beta^2 \big\lVert \mathbb{E}[  \alpha(\sigma_{i}) - \hat e ] \big\rVert_2^2.
\end{align*} 
By Lemma~(lem:spinFraction:variance of the paper), there exists a constant $C_1 > 0$ such that the following holds for all $t \in \{0, \cdots, n\sqrt n\}$
\begin{align*}
    \mathbb{E}\Big[g_\beta^\ell\Big(\alpha(\sigma_{i-1}) - \frac{1}{n}u_{i-n}\Big)\Big]
    &\leq \frac{C_1}{n}  + \frac{1}{q} + \frac{\beta} {q}\mathbb{E}\Big[\alpha_\ell(\sigma_{i-1}) - \frac{1}{q} \Big]  + 3q\beta^2 \big\lVert \mathbb{E}[  \alpha(\sigma_{i}) - \hat e ] \big\rVert_2^2.
\end{align*}
Plugging the above inequality into (equation lem:spinFraction:ExpectContraction:1 of the paper) 
\begin{align*}
    \mathbb{E}\big[\alpha_\ell(\sigma_t) \big] 
    \leq & \frac{C_1}{n} +  \frac{1}{n} \sum_{i = t-n+1}^0 \Big[\mathbf{1}\big(\sigma_0(n+i) = \ell\big)  \Big] \\
    &+ \frac{t - t_m +1}{nq} + \frac{1}{n}\sum_{i = t_m}^{t}  \frac{\beta} {q}\mathbb{E}\Big[\alpha_\ell(\sigma_{i-1}) - \frac{1}{q} \Big]  + \frac{3q\beta^2}{n}\sum_{i = t_m}^{t}\big\lVert \mathbb{E}[  \alpha(\sigma_{i-1}) - \hat e ] \big\rVert_2^2 ,
\end{align*}
and subtracting $1/q$ from both sides yields,
\begin{align}
    \mathbb{E}\Big[\alpha_\ell(\sigma_t) - \frac{1}{q}\Big] 
    \leq & \frac{C_1}{n} +  \frac{1}{n} \sum_{i = t-n+1}^0 \Big[\mathbf{1}\big(\sigma_0(n+i) = \ell\big) - \frac{1}{q} \Big] \notag\\
    &+ \frac{1}{n}\sum_{i = t_m}^{t}  \frac{\beta} {q}\mathbb{E}\Big[\alpha_\ell(\sigma_{i-1}) - \frac{1}{q} \Big]  + \frac{3q\beta^2}{n}\sum_{i = t_m}^{t}\big\lVert \mathbb{E}[  \alpha(\sigma_{i-1}) - \hat e ] \big\rVert_2^2  .
\end{align}
Let $\{x_t\}_{t \geq 0}$ be a sequence of vectors in $\mathbb{R}^q$ such that for all $j \in Q$ and $t \geq n$, we have the recursion
\begin{align*}
x_t^{(j)} &=  \frac{\beta}{nq}\sum_{i = t-n}^{t-1} x_i^{(j)} +\frac{C_2}{n} \sum_{i = t-n}^{t-1}  \lVert x_i \rVert_2^2 + \frac{C_2}{n}.
\end{align*}
