[Lem 28 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] Suppose $Y \in \cC_{x,loc}^3$, and there exists $(A, A') \in \dD_W^{2\alpha}$ with $A \in \cC_{x,loc}^2$, $A' \in \cC_{x,loc}^1$ and $B \in \cC_{x,loc}^1 \cap \cC_t^\gamma$ such that
    \begin{equation*}
        Y(t;x) - Y(s;x) = A(s;x) (W_t - W_s) + A'(s;x) \WW_{s,t} + B(s;x)(t-s) +\oO((t-s)^{1+\gamma})\;,
    \end{equation*}
    and that $Y(t;\cdot)$ is injective with $\sigma_{\min}(\nabla^
    \sft Y(t;x)) \geq c > 0$. Then $Z(t;\cdot):= Y(t;\cdot)^{-1}$ satisfies
    \begin{equation*}
        Z(t;x) -Z(s;x) = C(s;x) (W_t - W_s) + C'(s;x) \WW_{s,t} + D(s;x)(t-s) +\oO((t-s)^{1+\gamma})\;,
    \end{equation*}
    where 
    \begin{equation*}
        \begin{split}
        C(s) &= - (\nabla^\sft Y)^{-1} A\;, \qquad D(s) = -(\nabla^\sft Y)^{-1} B\;,\\
        C'(s) &= - (\nabla^\sft Y)^{-1} \bigg[ A' - 2 \, \Sym \Big( \big(\nabla^\sft A\big) \big( (\nabla^\sft Y)^{-1} A \big) \Big)\\
        &\phantom{11111}+ \langle \nabla^2 Y, \; (\nabla^\sft Y)^{-1} A, \, (\nabla^\sft Y)^{-1} A  \rangle \bigg]\;.
        \end{split}
    \end{equation*}
    The right-hand sides above are all evaluated at $s$ (and $(s; Z(s))$ for spacetime dependent quantities). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:bernton43mod of arXiv:2506.03999, 'Large deviations for scaled families of Schr\"odinger bridges with reflection'] For any compact set $K \subseteq \calX \times \calY$, 
