[Proposition 10 of arXiv:2606.23433, 'Emergence of Common Noise: Quantitative Conditional Propagation of Chaos'] \textbf{A }Suppose that Assumption \ref{ass:H} holds.\
Fix some $k < l $ and let $X_{j},Y_{j}\in L_{t_{j}}^{2}({\mathbb{R}}
^{d\times N}),$ for all $j=0,...,k.$ Then
\begin{eqnarray}
&& E\left\vert
\sum_{j=0}^{k}(h_{t_{j},t_{j+1}}(X_{j})-h_{t_{j},t_{j+1}}(Y_{j}))\right\vert
_{N}^{2}   \notag \\
&& \quad \quad \quad \le 2C^2_{stb}(1+L^2_{\varphi
})(1+(t_{k}-t_{0}))\sum_{j=0}^{k}E\left\vert X_{j}-Y_{j}\right\vert
_{N}^{2}(t_{j+1}-t_{j}).  
\end{eqnarray}
\textbf{B }If moreover for every $j=0,...,k,$ the components $
X_{j}^{1},...,X_{j}^{N}$ are i.i.d., conditionally on $\mathcal{F}_{t_j}^W,$
then 
\begin{equation}
E\left\vert \sum_{j=0}^{k}(h_{t_{j},t_{j+1}}(X_{j})-\widehat{h}
_{t_{j},t_{j+1}}(X_{j}))\right\vert _{N}^{2}\leq \frac{
2C^2_{stb}(t_{k}-t_{0})(1+t_{k}-t_{0})\left\Vert \varphi \right\Vert
_{\infty }^{2}}{N }.  
\end{equation}

