body:
[Definition recap of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] The satisfaction relations $\Vdash^i$, $\Vdash^{\text{c}}$, $\Vdash^{\text{h}}$, $\Vdash^e$ are defined as follows:
  \begin{itemize}
    \item For the $\bot$ case:
          \begin{itemize}
            \item $x \not \Vdash^\bullet \bot$, for $\bullet \in \set{ i, h, e }$.
            \item $x \Vdash^{\text{c}} \bot \mathrel{\;\ratio\Longleftrightarrow\;} x \in W_\bot$, where $W_\bot$ is the set of fallible worlds.
          \end{itemize}
    \item For the $\Box$ case:
          \begin{itemize}
            \item $x \Vdash^\iota \Box \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x \, \forall y' \sqsupset x' \, (y' \Vdash^\iota \varphi)$, for $\iota \in \set{ c, i, h }$.
            \item $x \Vdash^e \Box \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \forall y \sqsupset x \, (y \Vdash^e \varphi)$.
          \end{itemize}
    \item For the $\Diamond$ case:
          \begin{itemize}
            \item $x \Vdash^\iota \Diamond \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x \, \exists y' \sqsupset x' \, (y' \Vdash^\iota \varphi)$, for $\iota \in \set{ c, i }$.
            \item $x \Vdash^\varepsilon \Diamond \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \exists y \sqsupset x \, (y \Vdash^\varepsilon \varphi)$, for $\varepsilon \in \set{ h, e }$.
          \end{itemize}
  \end{itemize}

[Proposition 24 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] For every $R<\infty$, we have
\begin{align}
    \lim_{N\to\infty}\sup_{q\in\mcl Q_\infty^\D:\:|q|_{L^\infty}\leq R}\E_x\Delta_N(x,q)=0.
\end{align}

[Cor of arXiv:2505.15726, 'Fluctuations of Young diagrams for symplectic groups and semiclassical orthogonal polynomi'] Now we note that in the double-scaling limit $n=H K,\;m=\frac{\lambda}{2}K,\; \lambda\in (0,1),\; H\in (0,1/2),\; K\to \infty$ one can find for $ k+1\leq m$
\begin{align}
	\mathcal{S}_{k}^{[2m+1]}=\mathcal{S}^{[2m+1]}_{k-1}-A_{k+1}^{[2m+1]}\mathcal{S}_{k-1}^{[2m+1]}+A_{k}^{[2m+1]}\mathcal{S}_{k-2}^{[2m+1]}=\mathcal{S}_{k-2}^{[2m+1]}+O(1/K).
\end{align}
For odd m, we extend the recursion (equation WKB1 of the paper),(equation WKB2 of the paper) with the conditions
\begin{align*}
	&A_{k}^{[2m+1]}=\begin{cases}-\frac{a_{2m+1-2(k-1)}^2}{a_{2m+2-2(k-1)}^2},\quad k\leq m,\\
	0,\quad k>m,
\end{cases}\\
&B_{k}^{[2m+1]}=\begin{cases}
	1-A_{k+1},\quad k<m,\\
	1+a_1^2/a_2^2,\quad k=m,\\
	1,\quad k>m
\end{cases}
\end{align*}
so that the three-term relations stabilize at $k\geq m+1$ and we can write
\begin{align}
	\frac{r_{2m+1}^2}{a_{2m+2}^2}=\frac{\mathcal{R}^{[2m+1]}_{m}}{\mathcal{S}^{[2m+1]}_{m}}=\frac{\mathcal{R}^{[2m+1]}_{m+1}}{\mathcal{S}^{[2m+1]}_{m+1}}=\frac{\mathcal{R}^{[2m+1]}_{0}}{\mathcal{S}^{[2m+1]}_{0}}+O(1/K)=1+\frac{a_{2m+1}^2}{a_{2m+2}^2}+O(1/K).
\end{align}
Then, the asymptotics of the coefficients of three term relation (equation hat_g_TTR of the paper) for $p=1/2$ are
\begin{align}
	    &\hat{b}_0=0, \quad \hat{b}_k=0 \; (k>0),\\
    & \hat{a}^2_{2m}=\frac{a^2_{2m}a^2_{2m+1}}{r^2_{2m-1}}=\frac{a_{2m}^2a_{2m+1}^2}{a_{2m}^2+a_{2m-1}^2}+O(1/K),\\
    &\hat{a}^2_{2m+1}=r^2_{2m+1}=a_{2m+1}^2+a_{2m+2}^2+O(1/K).
\end{align}

In order to find the next terms of the asymptotic expansion in the limit under consideration, it is useful to note that the coefficients of the three-term recurrence relations (equation WKB1 of the paper) and (equation WKB2 of the paper) are slowly varying functions\footnote{A function \( f(k) \) is referred to as slowly varying if \( f(k) = F(\eta k) \), where \( \eta \) is a small parameter and \( F \) is a smooth function.} of the natural parameter:  
\begin{align}  
	&A_{k+1}^{[2m+1]}-A_{k}^{[2m+1]}=-\left(\frac{a_{2m+1-2k}^2}{a_{2m+2-2k}^2}-\frac{a_{2m+1-2(k-1)}^2}{a_{2m+2-2(k-1)}^2}\right)= O(1/K^2).  
\end{align}  
One may then employ the WKB method [Braun1978TMF] to construct the asymptotic solution of the three-term recurrence relations (equation WKB1 of the paper) and (equation WKB2 of the paper). 
\begin{comment}
Since the difference equation under study is linear and second order, any it's solution can be represent as the linear combination of two fundamental solutions. Thus, we consider on the asymptotic solutions of the equation
\begin{align}
	A_{k+1}^{[2m+1]}C_{k-1}+B_{k+1}^{[2m+1]}C_k-C_{k+1}=0,
\end{align}
for $k+1=m, \; m=g K,\; K\to \infty$.
 First, we need to define the sign of the discriminant in the considered limit $k+1=m$ 
\begin{align}
	&D_k^{[2m+1]}=\bigg(B_{k+1}^{[2m+1]}\bigg)^2+4A_{k+1}^{[2m+1]},\\ \notag
	&D_{m-1}^{[2m+1]}=\bigg(B_{m}^{[2m+1]}\bigg)^2+4A_{m}^{[2m+1]}=\bigg(1+\frac{a_{1}^2}{a_2^2}\bigg)^2-4\frac{a_{3}^2}{a_4^2}=\\
	&=\bigg(1+\frac{K}{2(K-1)}\bigg)^2-\frac{3(K-2)}{(K-3)}=\frac{(3K-2)^2}{4(K-1)^2}-\frac{3(K-2)}{(K-3)}<0.
\end{align}
So the limit under consideration is in ''classicaly resolved'' domain. Define the variables
\begin{align}
	&\mathcal{A}(k)=\sqrt{-A_{k+1}^{[2m+1]}}=\frac{a_{2m+1-2k}}{a_{2m+2-2k}},\\
	&\mathcal{B}(k)=-B_{k+1}^{[2m+1]}/(2\mathcal{A}(k))=\cos \varphi(k),
\end{align}
we can express the fundamental solutions (see [Braun1978TMF]) in the form 
\begin{align}
	C_{m}^\pm=(\sin\varphi(m))^{-1/2}
\exp\!\Biggl\{\int_{k_0}^{m}\Bigl[\ln \mathcal{A}(k)
\;\pm\; 
i\Bigl(
\varphi(k)
+\frac{1}{2\mathcal{A}(k)}\frac{d\mathcal{A}}{dk}\,\cot \varphi(k)
\Bigr)
\Bigr]
\,dk
\Biggr\}+O(1/K).
\end{align}
\end{comment} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop geographic ineq decoupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $u\in \widetilde{\mathcal{W}}_n$ be such that $|u|_\gamma\leqslant (\lambda_\gamma+\varepsilon) n$ for $\gamma\in \{1,2\}$ and set $(u^1,\ldots, u^r)=F_{n}(u)$. For $\gamma\in \{1,2\}$, we denote by $\underline v^{(\gamma)}$ the list $ (u^{j_\gamma(1)},\ldots, u^{j_\gamma(r_\gamma)})$. 
	Assume that $\underline v^{(\gamma)}\neq(e,\ldots,e)$ for $\gamma\in \{1,2\}$.
	Then, for all $w\in \Phi_n(u)$, 
	\begin{equation}

		d_{\mathrm{LP}}(L^{(\gamma)}[u],L[w])\leqslant  h\Big(\frac {{|\underline v^{(\gamma)}|}}{|u|_\gamma}\Big)+2h\Big(\frac{|\underline v^{(\gamma)}|}{T_\gamma}\Big).
	\end{equation}

