    \caption{$3A$}

\end{figure}
\begin{figure}[ht]
   \centering
   \includegraphics[width=0.9\linewidth]{3S.pdf}
   \caption{$3S$}

\end{figure}

\begin{figure}[ht]
    \centering
    \includegraphics[width=1.0\linewidth]{6AS.pdf}
    \caption{$6AS$}

\end{figure}

\begin{figure}[ht]
    \centering
