[Lemma lem:FN-kernel of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] For every $N\ge1$ and $0<x<1$,
\begin{align}
 F_N(x)
 &=\int_{-\log x}^{\infty}
      \bigl(\vartheta(e^{-s})^N-1\bigr)\,\mathrm d s,
 \\
 &=\int_0^x\frac{\vartheta(t)^N-1}{t}\,\mathrm d t.

\end{align}
Moreover,
\begin{equation}
 \mathcal D_N(g_{a,N},g_{b,N})=F_N(ab),\qquad 0<a,b<1.
\end{equation}

[Lemma 43 of arXiv:2606.24887, '2606.24887'] If $m: \CC\setminus \R \rightarrow \CC$ is the Stieltjes transform of a probability measure on $\R$ then
		\begin{equation*}
			|m(\ii \eta)| \le \frac{1}{\eta }~ 
			\qquad \text{ and } \qquad ~| m(\ii \eta^\prime ) - m(\ii \eta) | \le \frac{\eta^{\prime} -\eta}{\eta^2}
		\end{equation*}
		for all $0 < \eta \le \eta^{\prime}$.

