[Corollary 134 (Central limit theorem) of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the additional Assumption~ \ref{Assumptions_extra}. Let $L \in \amsmathbb{Z}_{> 0}$ and a $L$-tuple of integers $\boldsymbol{h} \in [H]^L$ both independent of $\N$, let a (possibly $\N$-dependent) $L$-tuple of functions $\boldsymbol{f}(z)$ such that $f_l(z)$ is a holomorphic function of $z \in \amsmathbb{M}_{h_l}$ for any $l \in [L]$. Assume there exists a constant $C > 0$ such that $\max_{l} \sup_{z} |f_l(z)| \leq C$.

We define the random $L$-dimensional Gaussian vector $\textnormal{\textbf{\textsf{Gau\ss{}}}}[\boldsymbol{f}]$ with mean and covariance
\begin{equation}

\begin{split}
\textnormal{\textsf{Mean}}_l[\boldsymbol{f}] & = \oint_{\gamma_{h_l}} \frac{ \dd z}{2\ii\pi}\,
f_l(z)\,\,W_{1;h_l}^{[1]}(z) , \\
\textnormal{\textsf{Cov}}_{l_1,l_2}[\boldsymbol{f},\boldsymbol{f}] & = \oint_{\gamma_{h_{l_1}}} \oint_{\gamma_{h_{l_2}}} \frac{\dd z_1\,\dd z_2}{(2\ii\pi)^2}\,
 f_{l_1}(z_1) f_{l_2}(z_2)
\,\mathcal{F}_{h_{l_1},h_{l_2}}(z_1,z_2)
\end{split}
\end{equation}
If $\boldsymbol{\ell}$ is $\P$-distributed with filling fractions deterministically as per Assumption~\ref{Assumptions_extra}, then as $\N \rightarrow \infty$
\begin{equation}

\Bigg(\sum_{i = 1}^{N_{h_l}} f_{l}\bigg(\frac{\ell^{h_l}_{i}}{\N}\bigg) - \N
\int_{\hat{a}_{h_l}'}^{\hat{b}_{h_l}'} f_{l}(x)\mu_{h_l}(x)\dd x\Bigg)_{l=1}^L \mathop{\sim}^{\textnormal{mom}} \quad \textnormal{\textbf{\textsf{Gau\ss{}}}}[\boldsymbol{f}],
\end{equation}
and the convergence in the sense of Definition~\ref{Definition_convergence_moments} is uniform for fixed choice of constants in the assumptions. If furthermore $\theta_{g,g} = 1$ for every $g \in [H]$, the result holds with $\textnormal{\textsf{Mean}}_l[\boldsymbol{f}] = 0$ for every $l \in [L]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop hil-equi of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Let $\rho_0:\pi_1S\to\mathrm{PSL}_n(\mathbb{R})$ be a Hitchin representation and let
$\psi^H_t$ be its Hilbert flow.  Then $\psi^H_t$ has a unique measure of
maximal entropy, the Bowen-Margulis measure $\widetilde m_H$, with full support, such that 
\begin{equation}
  \frac{1}{\lvert\mathcal S_0(L)\rvert}
  \sum_{\gamma\in\mathcal S_0(L)}
  \widetilde{\mathcal L}_\gamma
  \xrightarrow{\;\ast\;}
  \widetilde m_H
\end{equation}
as $L \to \infty$.

