[Proposition Identify_DPPP of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For $\lambda> \sqrt{2}$, let $\mu = \lambda+\sqrt{\lambda^{2}-2}$, $\theta_0= PPP(\frac{1}{\sqrt{2\pi}}e^{-\mu x}dx),$ then as $t \to \infty$,
\begin{equation}
  \theta_{t}^{\lambda} \Rightarrow \widetilde{\mathcal E}_{\infty}^\lambda,
\end{equation}
where the convergence is in the sense of vague convergence on the space of all point configurations. Furthermore 
\begin{equation}
 \widetilde{\mathcal E}_{\infty}^\lambda = DPPP(\mu C_M(\alpha(\lambda))e^{-\mu x}dx,\mathcal{D}^{\mu}),
\end{equation}
 where $C_M(\cdot)$ is as in (equation rename-C(f)-for-M-for-supercritical of the paper) and
$\mathcal D^{\mu}(\cdot)$ is a decoration point process with the law
\begin{equation}
     \mathbb P(\mathcal{D}^{\mu} \in \cdot) = \lim_{t\to\infty}\mathbb P(\sum_{k = 1}^{n(t)}\delta_{\{\chi_{k}(t) - M_{t} \}} \in \cdot | M_{t} \ge \mu t).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lHop of arXiv:2411.05369, 'Stochastic games of parental vaccination decision making and bounded rationality'] The generalized L'H\^opital rule  [Young] 
\begin{equation} 
    \liminf_{t\to \infty} \dfrac{f'(t)}{g'(t)}\leq \liminf_{t\to \infty} \dfrac{f(t)}{g(t)}\leq\limsup_{t\to \infty} \dfrac{f(t)}{g(t)}\leq\limsup_{t\to \infty} \dfrac{f'(t)}{g'(t)} 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:sLND-tilde-U of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Recall that $\theta_1$ is given in (equation e:theta12 of the paper). Assume  (equation e:DL of the paper) holds and
\begin{equation}
    \theta_1<1.
\end{equation}
\begin{enumerate}
  \item The Gaussian process $\tilde U_x=\left\{\tilde U_x(t),t\in\mathbb{R}\right\}$ has stationary increments with spectral measure
  \begin{equation*}
    F_{\tilde U}(\ensuremath{ \mathrm{d}} \tau)=\frac{C\ensuremath{ \mathrm{d}}  \tau}{|\tau|^{2\theta_1+1}}.
  \end{equation*}
  \item The Gaussian process $\tilde U_x$ satisfies the strong local nondeterminism  property: there exists
  a constant $C>0$ such that for any $n\in\mathbb{N}$ and $t,t^1,\dots,t^n\in\mathbb{R}$,
  \begin{equation}
    \mathrm{Var}\big(\tilde U_x(t)|\tilde U_x(t^1),\dots,\tilde U_x(t^n)  \big)\ge C\min_{k=0,\dots,n} |t-t^k|^{2\theta_1} ,
  \end{equation}
  where $t^0=0$.
  \item 
  For all $t,s \ge0$,
  \begin{equation*}
    \mathbb E\left[ |\tilde{U}_x(t)-\tilde{U}_x(s)|^2 \right]= C_1|t-s|^{2\theta_1},
  \end{equation*}
  where
  \begin{equation}
      C_1=2C_{H_0}\int_{\mathbb{R}}\frac{1-\cos\big(\tau \big)}{|\tau|^{2\theta_1+1}}\ensuremath{ \mathrm{d}}  \tau \int_{\mathbb{R}^d}\frac{\prod_{j=1}^{d}c_{H_j}|\xi_j|^{1-2H_j}}
      {1+2|\xi|^\alpha\cos\left(\frac{\pi\beta}{2}\right)+|\xi|^{2\alpha}}\ensuremath{ \mathrm{d}} \xi.
  \end{equation}
Consequently, $\left\{\frac{\tilde{U}_x(t)}{\sqrt{C_1}},t\ge0\right\}$ is a (standard) fractional Brownian motion with Hurst index $\theta_1\in(0,1)$.
\end{enumerate}

