[Lemma lem:truncated_expectation_diff_ineq_at_doubling_scales2 of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] If $\alpha\leq d/3$ then there exist positive constants $c_1$ and $c_2$ such that
\begin{align*}
\frac{\partial}{\partial r} \log \tilde \mathbb E_{r,\lambda} |K| 
&\geq c_1 r^{-\alpha-1}  \tilde \mathbb E_{r,\lambda} \min\{|K|, c_1 r^{(d+\alpha)/2}\} \geq c_2 r^{-1}
\end{align*}
for every $r\geq 1$ and $0\leq \lambda \leq 1$. Consequently, 
there exists a positive constant $c_3$ such that
\[
\tilde \mathbb E_{2r,\lambda}|K| \geq (1+c_3) \tilde \mathbb E_{r,\lambda}|K|
\]
for every $0\leq \lambda \leq 1$ and $r\geq 1$.

[Deff def:equiv-lambda-def of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Define the system

\begin{equation}
    \begin{aligned}
        du(\cdot) &= [A_uu(\cdot) + \hat f(\cdot,z(\cdot),\theta)u(\cdot)]dt + \hat \sigma(\cdot,z(\cdot),\theta)u(\cdot)H_udW_t \\
        dz(\cdot) &= [A_zz(\cdot) + f_z(\cdot,u(\cdot),z(\cdot),\theta))]dt + \sigma_z(\cdot,u(\cdot),z(\cdot),\theta)H_zdW_t \,,
    \end{aligned}
\end{equation}
obtained from (equation SPDE of the paper) by linearizing in $u$ in the first $d$ components. By this we mean that $\hat f,\hat \sigma: D \times \mathbb{R}^{m-d} \times \Theta \to \mathbb{R}^d$ are calculated from $f_u,\sigma_u$ by ignoring any term which is nonlinear in $u$. Then we define
\begin{equation}
\begin{aligned}
    \Lambda &\coloneqq \sup_\nu \mathbb{E}_\nu\Big[-\int_D \sum_{i=1}^d A_iv_i(\cdot) + \hat f_i(\cdot,z(\cdot),\theta)v_i(\cdot) d\mu(\cdot)\\
    &+ \frac{1}{2}\sum_{n \geq 1} a_n^2\Big(\int_D \sum_{i=1}^d\hat \sigma_i(\cdot,z(\cdot),
    \theta)v_i(\cdot)(e_n)_i(\cdot)d\mu(\cdot)\Big)^2\Big] \,,
\end{aligned}
\end{equation}
where $v = u/\|u\|_{L^1}$, $(v,z,\theta) \sim \nu$, and $\nu$ ranges over all invariant measures (stationary distributions) on $\{(v,z) \in C(\overline D)_+ \mid \|v\|_{L^1} = 1\} \times \Theta$ for $(u_t/\|u_t\|_{L^1},z_t,\theta)$, where $(u_t,z_t,\theta)$ solves (equation eq:general-linearized-SPDE of the paper).

[Lemma distribution of Y ;lemma of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] For $r \in (0,1)$, the distribution function of $Y_k(r)$ satisfies  
\begin{align}
    F_r(t) = \mathbb{P}(Y_k(r) \leq t ) = 
    \begin{cases}
         \quad\frac{1}{4(r-t)^2},  \quad &\textit{if}  \quad  \quad  -\infty < t \leq r - \frac{1}{1+r}\\ 
         \quad1- \frac{1}{4(r-t)^2},  \quad \quad &\textit{if}  \quad \quad   r + \frac{1}{1-r} \leq t < \infty,
    \end{cases}
\end{align}
and, for $r< t < r + \frac{1}{1-r}$ 
\begin{align}
     \mathbb{P}(Y_k(r) > t ) \leq 1 \wedge \frac{1}{4(t-r)^2}.
\end{align}
\begin{figure}
    \centering
    \includegraphics[width = 0.445\textwidth]{Distribution_of_Y_left.png}
    \includegraphics[width = 0.51\textwidth]{Distribution_for_Y_right.png}
    \caption{The unit circle is shown in black, together with curves $\mathcal{C}_t$ for various values of $t$, corresponding to the tail probabilities of $Y_r(k)$: left-sided tail (left) and right-sided tail (right).
    }
    \end{figure}
As a consequence, there exists absolute constants $C_1, C_2, >0$ such that for all $m \geq 2 $, 

\begin{equation}
    \biggl|\int_{-m}^m x dF_r(x)\biggr| \leq \frac{C_1}{m}, 
\end{equation}
and 
\begin{equation}
   C_2 \log m \leq   \biggl|\int_{-m}^m x^2 dF_r(x)\biggr| \leq C_1 \log m.
\end{equation}

