body:
[Prop 47 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] For $N \in \N$, let $u_{N}$ be generated by $\mathcal{S}_{N}[A]$ with $A(u) = u^{m+1}$ with initial measure $\delta$. There is a constant $C=C(m,d)>0$ such that the following holds: 
	\begin{enumerate}[(i)]
		\item  $\int_{\R^{d}}u_{N}(x,t)\,dx = 1$ for all $t \in [0,\infty)$.
		\item  For all $t \in (0,\infty)$ and $N \geq 2/t$,
		\begin{equation*}
			0 \leq u_{N}(\cdot,t) \leq Ct^{-d\beta}.
		\end{equation*}
		\item  For all $t \in (0,\infty)$, $N \geq 2/t$, and $r > 2\sqrt{d}\xmesh$,
		\begin{equation*}
			\int_{|x| > r} u_{N}(x,t) \,dx\leq C\exp\left(- rt^{-\beta}/C\right).
		\end{equation*}
		\item  For all $t \in (0,\infty)$, $N \geq 2/t$, and $r > 2\sqrt{d}\xmesh$,
		\begin{equation*}
			[u_{N}(\cdot,t)]_{\TV(B_{r})} \leq Ct^{-d\beta}r^{d-1}.
		\end{equation*}
	\end{enumerate}

