[Definition Integer-valued Gaussian free field on a general graph of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] To each finite connected rooted graph $G := (W , E , \rho)$ (with vertex set $W$, edge set $E$, root $\rho \in W$) equipped with conductances $J := (J_{yz})_{\{y,z\} \in E} \in (0 , \infty)^E$, we associate the space of functions $\Omega_W := \left\{ \varphi : W \to \ensuremath{\mathbb{Z}} \, : \, \varphi(\rho) = 0 \right\}$ and equip it with the probability distribution
	\begin{equation*}
	\mathbb{P}_{G , J}^{\ensuremath{\mathbb{Z}}\mathrm{-GFF}}( \{ \varphi \}) := \frac{1}{Z_{G , J}} \exp \left( - \sum_{yz \in E}  \frac{\left( \varphi(y) - \varphi(z) \right)^2}{J_{yz}} \right).
	\end{equation*}
	We denote by $\mathrm{Var}_{G , J}^{\ensuremath{\mathbb{Z}}\mathrm{-GFF}}$ the variance with respect to the measure $\mathbb{P}^{\ensuremath{\mathbb{Z}}\mathrm{-GFF}}_{G , J}$.

[Lem 5. lem: sub-aging fucntion, smaller parts of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] Fix $l \in \mathbb{N}$.
  The following statements hold.
  \begin{enumerate} [label = (\roman*)]
    \item 
      For every $r>0$,
      \begin{equation}
        \lim_{\eta \to 0} 
        \limsup_{n \to \infty}
        \limsup_{(s,t) \in T_{3}(l)}
        \int_{D_{R_{n}}(\rho_{n}, r) \times \mathbb{R}_{\geq 0} \times (0, \eta]} 
          e^{-ws/v} P_{\rho_{n}}^{\nu_{n}}(X_{n}^{\nu_{n}}(t) = x)\, 
        \dot{\pi}_{n}(dx dw dv) 
        = 0.
      \end{equation}
    \item 
      It holds that 
      \begin{equation}
        \lim_{r \to \infty} 
        \limsup_{n \to \infty}
        \limsup_{(s,t) \in T_{3}(l)}
        \int_{D_{R_{n}}(\rho_{n}, r)^{c} \times \mathbb{R}_{\geq 0} \times \mathbb{R}_{>0}} 
          e^{-ws/v} P_{\rho_{n}}^{\nu_{n}}(X_{n}^{\nu_{n}}(t) = x)\, 
        \dot{\pi}_{n}(dx dw dv) 
        = 0.
      \end{equation}
    \item 
      For every $r, \eta>0$,
      it holds that  
      \begin{equation}
        \lim_{W \to \infty} 
        \limsup_{n \to \infty}
        \sup_{(s,t) \in T_{3}(l)}
        \int_{D_{R_{n}}(\rho_{n}, r)^{c} \times [W, \infty) \times [\eta, \infty)} 
          e^{-ws/v} P_{\rho_{n}}^{\nu_{n}}(X_{n}^{\nu_{n}}(t) = x)\, 
        \dot{\pi}_{n}(dx dw dv) 
        = 0.
      \end{equation}
  \end{enumerate}

