[Theorem 3 (Existence in the degenerate case) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Let $x_0\in\Cc$. Assume \ref{ass:cont}, \ref{ass:sigma}, \ref{ass:k:dom}, and \ref{ass:face:sign}. Then there exists a filtered probability space carrying an $N$-dimensional Brownian motion $B$ and a continuous $\Cc$-valued semimartingale $X=(X_1,\ldots,X_N)$, defined up to its lifetime $\life{X}>0$, such that 
        \begin{align}
            X(t) &= x_0 + \int_0^t \sigma(s,X(s))\,dB(s) + \int_0^t b(s,X(s))\,ds + \sum_{\alpha\in R_+}\alpha
            \int_0^t \frac{k_\alpha(s,X(s))}{\langle X(s),\alpha\rangle} \mathbf 1_{\{\langle X(s),\alpha\rangle>0\}}\,ds\/,

    \end{align}
    for every $t\in[0,\life{X})$. In particular, for every $\alpha\in R_+$ the singular integrals in \eqref{eq:degenerate-existence-indicator} are finite on compact subintervals of $[0,\life{X})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:diff_of_V of arXiv:2512.21159, '\textsc{From multitype branching Brownian motions\\ to branching Markov additive processes'] With the notation of Lemma (lem:property of PF of the paper), each of the functions $\theta\mapsto \lambda(\theta)$, $\vec{Y}(\theta)$ and $\vec{V}(\theta)$ is infinitely differentiable on  $(0, \bar{\theta})$. Moreover, we have 
    \begin{equation}
        \lambda'(\theta) = \vec{Y}^{\top}(\theta)\mathcal{M}'(\theta)\vec{V}(\theta),
    \end{equation}
    where $\mathcal{M}'(\theta)$ is the entry-wise derivative of $\mathcal{M}(\theta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition equivalentLevyCoupling of arXiv:2509.23086, 'On Optimal Markovian Couplings of L\'evy Processes'] Let $\mu,\nu\in \Lambda(\mathbb R^d)$ and $\gamma\in \Lambda(\mathbb R^{2d})$. The following are equivalent:

    (i) $\gamma\in \Gamma^\Lambda(\mu,\nu)$;

    (ii) for all bounded measurable functions $f$ that vanish on a neighbourhood of $0$, we have
    \begin{equation}
        \int_{\mathbb R^{2d}} f(x)d\gamma(x,y)= \int_{\mathbb R^d} f(x)d\mu(x),\qquad \int_{\mathbb R^{2d}} f(y)d\gamma(x,y)=\int_{\mathbb R^d} f(y)d\nu(x);
    \end{equation}

    (iii) for all bounded twice differentiable functions $f\in C_b^2(\mathbb{R}^d)$ that vanish on a neighbourhood of $0$, (equation marg-int of the paper) holds;

    (iv) for all bounded continuous functions $f\in C_b(\mathbb{R}^d)$ that vanish on a neighbourhood of $0$, (equation marg-int of the paper) holds;

    (v) for all bounded continuous functions $f\in C_b(\mathbb R^{d})$ such that $|f(x)|\le C|x|^2$ for some $C\ge 0$, (equation marg-int of the paper) holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (KL calibration--refinement bound for occupancy ratios) of arXiv:2608.24858, 'Bellman Calibration for Marginalized Importance Weighting in Offline Reinforcement Learnin'] Suppose that \(w_\pi>0\) \(\nu\)-almost surely. For every normalized
\(\omega>0\) for which \(\mathrm{Cal}_{\rm KL}(\omega)\) and
\(\mathrm{Ref}_{\pi,{\rm KL}}(\omega)\) are finite,
\[
  \|\omega-w_\pi\|_{L^1(\nu)}
  \leq
  \frac{1}{1-\gamma}
  \left\{
    \sqrt{2\,\mathrm{Cal}_{\rm KL}(\omega)}
    +
    \sqrt{2\,\mathrm{Ref}_{\pi,{\rm KL}}(\omega)}
  \right\}.
\]

[Corollary 84 (Native valuation exchange and flag reconstruction) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] For every nonzero $q\in M_{\lambda,n}^*$,
\begin{equation}
 d_{\rm sp}^{\rm nat}(q)=a_F(q),

\end{equation}
and
\begin{equation}
 F_rM_{\lambda,n}
 =\bigcap_{\substack{q\in M_{\lambda,n}^*\\
                d_{\rm sp}^{\rm nat}(q)\le r-1}}
 \ker q.

\end{equation}
Moreover, some fixed designed geometric response of $q$ satisfies
\begin{equation}
 s_N(T_q)
 \sim C_q\frac{(\log N)^{a_F(q)-1}}{N},
 \qquad C_q>0.

\end{equation}
Thus forward depth and dual reconstruction require one full-support kernel,
not two separate exposure constructions.

[Proposition 116 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mf A$ be a regular HTM, $I$ and $J$ be sets, and $K = I\times  J$. Let $\sm{\mf A}{k\in K}{f(k)}$ and $x = \sum_{k\in K} f(k)$.
  \begin{enumerate}
  \item [(i)] Let $\sm{\mf A}{j\in  J}{f(i,j)}$ for every $i\in I$. Then $x = \sum_{i\in I}\sum_{j\in J}f(i,j)$.
  \item [(ii)] Let $\sm{\mf A}{i\in  I}{f(i,j)}$ for every $j\in J$. Then $x = \sum_{j\in J}\sum_{i\in I}f(i,j)$.
  \end{enumerate}

