[Prop Prop_InfinitesimalSliceUniformisers of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $({\mathbf{p}}_0,[{\mathfrak l}_0]) \in \mathbf{Dir} \times \mathbf{Ram}$
  there is a \defined{local infinitesimal uniformiser};
  that is:
  an open neighbourhood $({\mathbf{p}}_0,[{\mathfrak l}_0]) \in \mathscr{U} \subseteq \mathbf{Dir} \times \mathbf{Ram}$ and
  a tame smooth map
  \begin{align*}
    \mathscr{F}^\mathbf{Ram}|_\mathscr{U} &\to \mathrm{Vect}(X) \\
    ({\mathbf{p}},[{\mathfrak l}];v) &\mapsto \bar v = \bar v({\mathbf{p}},[{\mathfrak l}];v)
  \end{align*}
  such that:
  \begin{enumerate}
  \item

    for every $({\mathbf{p}},[{\mathfrak l}];v) \in \mathscr{F}^\mathbf{Ram}|_\mathscr{U}$
    \begin{equation*}
      ({\mathbf{p}},[{\mathfrak l}];v) \cdot \mathrm{lift}_{\mathbf{p}}^K(\bar v) \in \mathscr{F}_{{\mathbf{p}},[{\mathfrak l}]}^{\mathbf{Sl}},
    \end{equation*}
  \item

    $\bar v({\mathbf{p}},[{\mathfrak l}];-)$ is $\mathbb{R}$--linear,
    and
  \item

    for every $({\mathbf{p}},[{\mathfrak l}];v) \in \mathscr{F}^\mathbf{Ram}|_\mathscr{U}$
    \begin{equation*}
      \Abs{\bar v({\mathbf{p}},[{\mathfrak l}];v)}_{H^{k+1}} \lesssim_k \Abs{v}_{H^k}.
    \end{equation*}
  \end{enumerate}  
  Moreover,
  given a compact subset $K \subseteq X {\backslash} \mathrm{Br}({\mathfrak l})$,
  the local infinitesimal uniformiser can be chosen such that
  $\bar v({\mathbf{p}},[{\mathfrak l}];v)|_K = 0$ for every $({\mathbf{p}},[{\mathfrak l}];v) \in \mathscr{F}^\mathbf{Ram}|_\mathscr{U}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2604.06516, 'From stochastic individual-based models to free-boundary Hamilton-Jacobi equations'] For almost every $a_0\in \R$, we have
      \begin{equation}

          \int_{\R^+\times\R} \mathds{1}_{\widetilde \Omega_{a_0}\setminus\Gamma_{a_0}}(t,x)dtdx=0,
   \end{equation}
   and
   \begin{equation}

          \forall (t,x)\in \Gamma_{a_0}\cup \widetilde \Omega_{a_0}^c,\qquad \lim_{a\downarrow a_0} u_a(t,x)=u_{a_0}(t,x).
   \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:spaceXYZdefi of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] For $V \in \cV_{\varnothing}$ and $K \in \cK_{j,\varnothing}$,  we define norms
\begin{align}
	\norm{V}'_{j} = r_j^{-1 + \kt} \norm{V}_{\cV_j (\ell)} , 
	\qquad \norm{K}''_{j} = r_j^{- {\ka} + \kt} \norm{K}_{\cW_j}
\end{align}
and Banach spaces
\begin{align}
	& X_j = \Big\{ \sum_{\km \in \kA_0 \cup \kA_1} V^{(\km)} (\vec{\textbf{a}}) : V^{(\km)} \in C \big( \operatorname{HB}_{\epsilon_p} ; \cV^{(\km)} \big) \Big\} , \\
	& Y_j = \Big\{ \sum_{\km \in \kA_2 \cup \kA_3 \cup \kB_0 \cup \kB_1}  V^{(\km)} (\vec{\textbf{a}}) : V^{(\km)} \in C \big( \operatorname{HB}_{\epsilon_p} ; \cV^{(\km)} \big) \Big\}  ,\\
	& Z_j = \Big\{ K (\vec{\textbf{a}}) : K \in C \big( \operatorname{HB}_{\epsilon_p} ; \R \cK_j \big)  \Big\}   ,
\end{align}
i.e.,  they are spaces of continuous function of $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}$.
They are endowed with norms
\begin{align}
\begin{split}
	\norm{x_j}_{X_j} = \sup_{\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}} \norm{x_j (\vec{\textbf{a}})}'_j,  \qquad \norm{y_j}_{Y_j} &= w_Y \sup_{\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}} \norm{y_j (\vec{\textbf{a}})}'_j , \\ 
	\norm{z_j}_{Z_j} &= w_Z \sup_{\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}}  \norm{z_j (\vec{\textbf{a}})}''_j  
\end{split}
\end{align}
for some constants $w_Y, w_Z >0$,  that are chosen sufficiently large later in the proof of Proposition~(prop:Stdefi of the paper) and (prop:nupcctty of the paper).

Projection on each space is denoted $\operatorname{proj}_X,\operatorname{proj}_Y$ and $\operatorname{proj}_Z$,  respectively.

[Lem 9 of arXiv:2607.27932, '2607.27932'] Let $\tau_{\lambda,\varepsilon}(\sigma)$ be defined as in \eqref{label_bizarre1}.
For any $\lambda\in\bRb^d$ and $0<\varepsilon<\varepsilon_0$, it holds: for any $\delta>0$,
\begin{equation}
\lim_{\sigma\to0}\PP\left(\exp\left[\frac{2}{\sigma^2}\left(\widehat\h_\varepsilon(\lambda)-\delta\right)\right]<
\tau_{\lambda,\varepsilon}(\sigma)<\exp\left[\frac{2}{\sigma^2}\left(\widehat\h_\varepsilon(\lambda)+\delta\right)\right]\right)=1\,,
\end{equation}
for  

\begin{equation}
\widehat\h_\varepsilon(\lambda):=\lim_{\rho\rightarrow 1}\widehat\h^\rho_{\varepsilon}(\lambda)=\left\{
\begin{array}{ll}
\inf_{x\in\mathbb R^d,y\in\partial \mathbb B(\lambda;\varepsilon)}v(x,y) &\quad\mbox{if}\,\,\|\lambda-\lambda_1\|<
\varepsilon,\\
\inf_{x\in\partial \mathbb B(\lambda;\varepsilon),y\in\mathbb R^d}v(x,y)&\quad\mbox{if}\,\,\|\lambda-\lambda_2\|<
\varepsilon,\\
\inf_{x\in\partial \mathbb B(\lambda;\varepsilon),y\in\partial \mathbb
B(\lambda;\varepsilon)}v(x,y)&\quad\mbox{if}\,\,\min_{i=1,2}\|\lambda-\lambda_i\|\ge \varepsilon.	
\end{array}
\right.
\end{equation}
Additionally,
\begin{equation}

\lim_{\sigma\to0}\PP\left({\rm
dist}\left((x^\sigma_{\tau_{\lambda,\varepsilon}(\sigma)},y^\sigma_{\tau_{\lambda,\varepsilon}(\sigma)}),\mathbb{B}(\lambda;\varepsilon)\times\mathbb{B}(\lambda;\varepsilon)\right)\leq\delta\right)=1\,.
\end{equation}

