[Lemma 18 of arXiv:2609.02423, '2609.02423'] Let $\nu$ be any chart and let $m_{N,\Gamma}$ be the symbol defined in
\eqref{eq:mNy-band-def}, whose high-frequency support is contained in
\eqref{eq:band}.  Set
$m_{N,1}=m_{N,\Gamma}\psi_{\mathrm{tan}}$.
Assume $\delta\le\min\{c_0^2,(4K^2)^{-1}\}$.  Then, for every $f$ with
Fourier support in $\{\rho(\theta)\le\delta N\}$ and every
$g\in L^2(\R^2)$,
\begin{equation}
 \norm{\B_{m_{N,1}}(f,g)}_{L^2}
 \le C_K\bigl[(1+\log N)\norm{\partial_xf}_{L^\infty}
 +\norm{f}_{L^\infty}\bigr]\norm g_{L^2}.
\end{equation}
In particular, uniformly in the weight centre,
\[
 \abs{\ip{\B_{m_{N,1}}(u_{\ll N},z_N)}{a_*z_N}}
 \le C_K\bigl[(1+\log N)\norm{u_x(t)}_{L^\infty}
 +\norm{u(t)}_{L^\infty}\bigr]\norm{z_N(t)}_2^2.
\]

[Proposition prop:exp_est of arXiv:2606.00325, 'Ergodicity for a class of stochastic Hasegawa-Mima equations with dissipation'] Let $\phi$ be a solution of (equation eq:main of the paper) in the sense of (def-sol-H1 of the paper), then the following exponential bound holds
    \begin{align*}
    \mathbb{P}\left( \sup_{t\ge 0} \left(\|\phi(t)\|_V^2 - \|\phi_0\|_V^2 + \frac{1}{2}\int_0^t \|\phi(s)\|_W^2 ds - \kappa t \right) \ge R\right) \le e^{-\frac{R}{2C\kappa}},
\end{align*}

