[Proposition 3 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Suppose that $\Phi$ has a $\mathfrak D$-pullback random attractor $\mathcal A$, that $\varphi_P$ has a $\mathfrak D_P$-global attractor $\mathcal A_P\in\mathfrak D_P$, and that $\mathfrak D_X$ is nonempty. Then
	\begin{align}
		\Pi_P\mathcal A(\omega)=\mathcal A_P,
		\qquad \omega\in\Omega,
	\end{align}
	where $\Pi_X(x,\mu)=x$ and $\Pi_P(x,\mu)=\mu$.

[Theorem thm:tailrl-harmonic-decomposition of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] The TailRL{} objective decomposes as
\begin{equation}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{\mathrm{Best\text{-}of\text{-}k}(\theta;x)-1}{k},

\end{equation}
and, under the regularity conditions of (lem:tailrl-regularity of the paper), its gradient satisfies
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{1}{k}
\nabla_\theta \mathrm{Best\text{-}of\text{-}k}(\theta;x).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem mk1k2inftyIIthm of arXiv:2608.04730, 'A new look at some aspects of one-dimensional random sequential adsorption and its continu'] Let $m_{k_1;k_2;II}$ and $m_{k_1;k_2;II_1}$ be as in Theorem (k1k2IIthm of the paper).
One has
\begin{equation}
m_{k_1,\infty;II_1}:=\lim_{k_2\to\infty}m_{k_1,k_2;II_1}=D\approx 0.4166,
\end{equation}
and
\begin{equation}
m_{k_1,\infty;II}:=\lim_{k_2\to\infty}m_{k_1,k_2;II}=D+(1-D)m_{k_1}\approx 0.4166+0.5834\thinspace m_{k_1},
\end{equation}
where
\begin{equation}
D=\frac12\int_0^\infty e^{-\frac12x}e^{-\int_0^x\frac{1-e^{-y}}ydy}dx\approx0.4166.
\end{equation}
Thus also,
\begin{equation*}
\lim_{k_1\to\infty}m_{k_1,\infty;II}=D+(1-D)m_\infty\approx0.8528.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2608.05679, 'Small ball probabilities and Chung's law of the iterated logarithm for Gaussian Volterra p'] Assume that
\begin{equation}
\begin{aligned}
	\alpha>-\frac12,\qquad
	\gamma\in\left(-1,-\frac12\right),\qquad
	H=\alpha+\beta+\gamma+\frac32>0.
\end{aligned}
\end{equation}
Then there exist constants $\kappa_1,\kappa_2\in(0,\infty)$ such that, for
every $t>0$ and $0<\varepsilon<t^H$,
\begin{equation}
\exp\left(
-\kappa_1
\left(\frac{t^H}{\varepsilon}\right)^{\frac{2}{2\gamma+3}}
\right)
\leq
\mathbb{P}
\left\{
\sup_{s\in[0,t]}|X(s)|\leq\varepsilon
\right\}
\leq
\exp\left(
-\kappa_2
\left(\frac{t^H}{\varepsilon}\right)^{\frac{2}{2\gamma+3}}
\right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: bdry cubic of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $T>0$ and every $u \in \mathbb H^0$,
  \begin{equation}
  \mathbb E \left[ \int_{[-1,1]\times \mathbb T^2} 4\llbracket (\overline HW_T^0)^3\rrbracket \overline HZ_T^0(u)dx + \frac 12 \|u\|_{L^2_tL^2_z}^2 -\delta^0_T \right]=  \mathbb E\left[ \frac 12\|\ell^0_T(u)\|_{L^2_t L^2_z}^2 \right]. 	
  \end{equation}

