body:
[Thm eq:TnJ of arXiv:2606.02340, 'Transitivity in Inhomogeneous Random Tournaments'] Suppose $W$ is a $\triangle$-regular tournamenton, with  $\zeta(W) \in [0, 1)$, and $T_n \sim T(n, W)$. 
Then, almost surely, as $n \rightarrow \infty$, 
\begin{align}
\hat X_\triangle(T_n)|T_n \stackrel{D}{\longrightarrow} \tau_W \cdot Z+\sum_{\lambda\in\mathrm{Spec}^-(\triangle_{W})}\lambda(Z_\lambda^2-1), 
\end{align} 
where $Z, \{Z_\lambda\}_{\lambda\in\mathrm{Spec}^-(\triangle_{W})}$ are i.i.d. $N(0,\,1)$ and $\tau_W^2$ is as defined in (equation eq:tau_W of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $G, H$ be correlated random graphs. From here on out, we set
    \begin{equation}
        I = G \land_{\sigma^*} H \qquad \text{and} \qquad U = G \lor_{\sigma^*} H.
    \end{equation}
    These are the true intersection and union graphs associated with the system. 
    Furthermore, if $t \geq 0$, we set
\begin{equation}
     V_{\geq t} = V_{\geq t}(I) = \{ v \in V: w_I(v) \geq t \}; \qquad V_{\leq t} = V_{\leq t}(I) = \{ v \in V: w_I(v) \leq t \}
\end{equation}
the level sets for the balanced load function associated with $I$.

[Definition 6 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm(\cite[Definition 2.3]{DuanJTP2025})
  A pair $(u,K)$  is called  a deterministic flat solution of the mean reflected SPDE  \eqref{SPDE} if the process $K$ is deterministic and}
\begin{itemize}
\item[(i)]  {\rm $u$ is a continuous random process on $[0,T]\times[0,1]$ with $\mathbb{E}\left[|u|_{\infty}^T\right]<\infty$ for any $T>0$; $u(t,x)$ is $\mathcal F_t$ measurable and satisfies the constraint \eqref{Restraincondition}.}
\item[(ii)] {\rm $K$ is a  measure on $\mathbb R_+\times(0,1)$ such that $K([0,T]\times(\e,1-\e))<\infty$ for every  small $\e>0$ and $T>0$.}
\item[(iii)]{\rm$(u,K)$ solves the parabolic SPDE in the following sense: for $\forall t\in \mathbb R_+$, $\varphi\in C^2_0([0,1])$,
\begin{align*}
&\langle u(t), \varphi \rangle-\int^t_0\langle u(s), \varphi'' \rangle \mathrm{d}s+\int_0^t\int_0^1   f(s,x, u) \varphi(x) \mathrm{d}s\mathrm{d}x\\
&\,=\langle u_0, \varphi \rangle+\int_0^t\int_0^1 \sigma(s,x, u)\varphi(x) W(\mathrm{d}s,\mathrm{d}x)+\int_0^t\int_0^1\varphi(x)K(\mathrm{d}s,\mathrm{d}x),\ \ \text{a.s.}.
\end{align*}}
\item[(iv)] {\rm $K$ increases only when needed. That is, $\int_0^{\infty}\int_0^1 \mathbb{E}\left[h(s,x,u(s,x))\right] K(\mathrm{d}s,\mathrm{d}x)=0$.}
\end{itemize}

[Proposition 10 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $0< \delta < \eta < \frac{1}{3}$, and $S_n(\delta,\eta)$ be defined by \eqref{eq:diagonal_safety_region}. Let $K$ denote the set
    \begin{equation}
        K := K(a,b):= \left\{(k,l)\in\Z^2\setminus\{(0,0)\}:\pi \left( \frac{k^2}{b^2}+\frac{l^2}{a^2} \right) \leq 10n\right\}.
    \end{equation}
    Then
    \begin{equation}
        \lim\limits_{n\to\infty} \sup\limits_{(a,b) \in S_n(\delta, \eta)} \sum_{(k,l)\in K} |\mathcal{L}^{0}_n(X_{k,l}(a,b))| e^{-\frac{X_{k,l}(a,b)}{2}} = 0.
    \end{equation}

