[Definition 14 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] We say that \eqref{eq:SPDE_n} has a weak solution $(X_t^0,\ldots, X_t^n )_{t\geq 0}$, if there exists a filtered probability space $(\Omega, \mathcal{F}, (\mathcal{F}_{t})_{t\geq 0}, \bbP)$ such that $(X_t^0,\ldots, X^n_t)_{t\geq 0}$ is an adapted $\big(\mathcal{C}_{tem}^+\big)^{n+1}$-valued 
		continuous process with $X_0^k =f^k $ for $0\leq k \leq n$, and such that $(\dot{W}^k)_{0\leq k \leq n}$  is a family of independent  space-time white noises and for every $(t,x) \in (0,\infty)\times \R$ and $0 \leq k \leq n$ almost surely
		\begin{equation*}
			\begin{split}
				&X_t^k(x) = \int_\R p_t(x-y) X_0^k(y)dy + \int_\R \int_0^t p_{t-s}(x-y)g^k_s(y)dsdy \\
				& \hspace{2cm}+ \int_\R \int_0^t p_{t-s}(x-y) \sqrt{X_s^k(y)}W^k(dsdy),\quad \bbP-a.s.,
			\end{split}
		\end{equation*}
		with $g^0 \equiv 0$.

[Lemma 23 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] We have $\bbP$-almost surely that for $r\in [0,1]$,
    \begin{align*}
        \frac{f_t(rJ_{ij},J_{i,-j})}{f_t(\bfJ_i)}=\exp\bigg(\frac{\beta(r-1)}{\sqrt N}J_{ij}\int_0^tX_s^j dB_s^i-\frac{\beta^2(1-r)^2}{2N}|J_{ij}|^2\int_0^t |X_t^j|^2\,ds\bigg).
    \end{align*}
    In particular there exist constants $C_{\fru},C \in (0, \infty)$ that depend only on $(\beta,T,A,\sigma^2)$ such that if  $\sqrt N > C_{\fru}$, for all $r$ we have
    \begin{align*}
        \bbE_\bbP\bigg[\Big| 
        \frac{f_t(rJ_{ij},J_{i,-j})}{f_t(\bfJ_i)}\Big|^8\bigg]\leq C
    \end{align*}

