[Theorem t.densityLp of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] {Fix any $p\geq1$. Suppose that $V\in H^1(\mathbb{T})$ and 
\begin{equation}

  \begin{split}
    & \|V\|_{L^2(\mathbb{T})}<\frac{1}{100p},\\
    &
    {\frak Q}(p):= \sup_{N\ge1}\bar \mathcal{Q}_{p,N}(0)<+\infty.
\end{split}\end{equation}
Then there exist $N_0>0$, $\lambda(p)>0$, and   ${\frak C}_{*,j}>0$, $j=1,2$
depending only on $p$, ${\frak Q}(p)$,  $\|V\|_{H^1(\mathbb{T})}$, such that 
\begin{equation}

\bar \mathcal{Q}_{p,N}(t)\le {\frak C}_{*,1}\bar \mathcal{Q}_{p,N}(0)
\exp\left\{-\lambda(p)t\right\}+{\frak C}_{*,2}
,\quad t\ge0,\,N\ge N_0.
\end{equation}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm Tightness Lemma of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Fixing a $\delta>0$, for $n$ large enough we have
    \begin{equation*}
        \mathbb{P}\bigg(\sup_{t,s \in [0,T]}\bigg|\frac{G(M(t)/\sqrt{n},\theta(t))-G(M(s)/\sqrt{n},\theta(s))}{|t-s|^{1/2-\delta}}\bigg|>u\bigg) \leq Ce^{-c \frac{u^2}{\log(n)}}+Ce^{-c\frac{n}{\log(n)}},
    \end{equation*}
    where $C,c$ may depend on $T$ and $\delta$.

