[Prop 25 of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] The following properties hold:
\begin{enumerate}[{\rm (a)}]
\item  $\mssd_{\U}^{(r)}$ is a pseudo-distance on~$\U$. Furthermore, $\mssd_{\U}^{(r)}(\gamma, \eta)=0$ implies $\gamma_{B_r}=\eta_{B_r}$$;$
\item  $\mssd_{\U}^{(r)}$ is $\tau_\mrmv^{\times 2}$-continuous for every $r>0$ and  
\begin{align*}
\gamma_n \xrightarrow{\tau_\mrmv} \gamma \in \U \quad \iff \quad \mssd_{\U}^{(r)}(\gamma_n, \gamma) \to 0 \qquad \text{for every}\ r>0 \ ;
\end{align*}

\item   every $\mssd_{\U}^{(r)}$-Lipschitz function belongs to~$\mathcal B(\sigma_r)$. In particular, 

\begin{align}
\Lip(\U, \mssd_{\U}^{(r)}) \subset \mathcal C(\U, \tau_\mrmv) \cap \mathcal B(\U, \sigma_r) \ ;
\end{align}

\item   $\mssd_{\U}^{(r)}\nearrow \mssd_{\U}$ as $r \nearrow \infty$. In particular, 
\begin{align}
 &\Lip(\U, \mssd_{\U}^{(r)})  \subset \Lip(\U, \mssd_{\U}^{(s)}) \subset  \Lip(\U, \mssd_{\U}) \comma 
 \\
\notag &\Lip_{\mssd_{\U}}(u)\le \Lip_{\mssd_{\U}^{(s)}}(u)\le  \Lip_{\mssd_{\U}^{(r)}}(u) \comma \quad 0<r \le s \fstop
\end{align}

\end{enumerate}

