body:
[Lemma lem:dynamicEntropyTransfers of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Assume the hypotheses of (thm:dynamicLinearStatisticsCLT of the paper).  Then:
\begin{enumerate}[(i)]
\item
\begin{align}
\sup_{N\ge1}\sup_{0\le t\le T}
\mathsf{H}\pa*{f_N^t\vert{\mathbb{Q}}_{N,\beta}(\mu^t)}<\infty.
\end{align}
\item For each terminal pair $(t,\phi)$, with $f^r=\mathsf{U}^{r,t}\phi$,
\begin{align}
\sup_{0\le r\le t}
{\mathbb{E}}_{X_N\sim f_N^r}
\brak*{|\mathsf A_1(\nabla f^r,X_N,\mu^r)|}
\le \frac{C_{t,\phi,T}}{N}.
\end{align}
\item If $(q^r)_{0\le r\le T}$ is a deterministic family of bounded measurable functions with $\sup_r\osc(q^r)<\infty$, then
\begin{align}
\sup_{0\le r\le T}
{\mathbb{E}}_{X_N\sim f_N^r}
\brak*{\left|\int_{{\mathbb{R}}^\mathsf{d}} q^r\,\mathop{}\!\mathrm d(\mu_N^r-\mu^r)\right|}
\le \frac{C_{q,T}}{\sqrt N}.
\end{align}
\end{enumerate}

