[Theorem 4 (Empirical measure convergence) of arXiv:2604.17526, '2604.17526'] Suppose~$\set{P_k}_{1 \leq k \leq K}$ are Markov transition kernels satisfying Assumptions~\ref{a:reversible}--\ref{a:L1Linf}.
  Given~$\delta > 0$, choose
  \begin{equation}
    N = \frac{64C_w}{\delta^2}
    \quad\text{and}\quad
    T = \max\set*{T_0, (4+\abs{\log_2 \delta})t_{\mix, 1}^\infty}\,.
\end{equation}
  Let~$\set{X^i_K, \tilde w^i_K}_{1 \leq i \leq N}$ be~$N$ independent realizations of the points and weights returned by Algorithm~\ref{a:ais2}, with~$K+1$ levels, running time~$T$, and kernels~$\set{P_k}$.
  For every bounded measurable $f$, we have
  \begin{equation}
    \norm[\Big]{
      \sum_{i=1}^N w^i_K f(X^i_K) - \ip{f, \pi_{K+1}}
    }_{L^2(\P)}
    \leq \norm{f}_\infty \delta\,,
    \quad\text{where}\quad
    w^i_K \defeq \frac{\tilde w^i_K}{\sum_{j = 1} \tilde w^j_K}
    \,.
  \end{equation}
  Moreover, if~$\mu_{K+1, N}$ is the empirical measure defined by
  \begin{equation}
    \mu_{K+1, N} \defeq \sum_{i=1}^N w^i_K \delta_{X^i_K}\,,
  \end{equation}
  then for every~$s > d/2$
  \begin{equation}
    \E\norm[\big]{\mu_{K+1, N} - \pi_{K+1}}_{H^{-s}}^2
      \leq C_s \delta^2
      \,.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 42 (Finite-time extension) of arXiv:2607.19752, 'Weak Equilibrium Measures and Capacity--Hitting Identities\\ for the Hypoelliptic Third-Or'] For every $q\ge1$, every $M<\infty$, and every compact
$K_0\subset\mathsf O$,
\[
    \sup_{\substack{
        0\le\delta\le1,\ z\in K_0\\
        0<t\le M}}
    \mathbb E_z\left[
        \lambda_{\min}\left(
            T_t^{-1}\mathcal M_{t,r}^{\delta,\mathsf O}T_t^{-1}
        \right)^{-q}
    \right]<\infty .
\]
The same estimate holds for the adjoint cutoff family.

[Lemma 37 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] We have
\begin{align*}
A_k &= \frac{\Delta(u_k\rho_0)}{2} - \sum_{l=1}^k \frac{b_l\Delta^lA_{k-l}}{2^ll!}\\
B_k &= \Big[\frac{\Delta(v_k\rho_0)}{2} + v_k\rho_1\Big] + \frac{\Delta s_v^{k-1, 1}}{2} + s_v^{k-1, 2} - \sum_{l=1}^{k}\frac{b_{l}\Delta^{l}B_{k-l}}{2^{l}l!} + \sum_{l=1}^{k}\frac{b_{l}\Delta^{l}s_v^{k-l, 1}}{2^{l}l!},
\end{align*}
where $s_v^{a, b} \coloneqq \sum_{i=0}^a v_i\rho_{a+b-i}$ for every $a, b\in\mb Z_+$.

