[Corollary 66 (Uniform capture in $\mathbb D^{1,2}$) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] If
\begin{equation}
 \sum_{a,p}p(\norm{A_{a,p}}^2+\norm{r_{a,p}}^2)
 \le M_1R^2,

\end{equation}
then
\begin{equation}
 \widehat N_s^{(\infty)}\le M_1R^2\Id,
 \qquad
 \sum_a\norm{P_{V_{s,j}}r_{a,s}^{[j]}}^2
 \ge\frac{\widehat{\mathfrak H}_s^{[j]}}{dM_1R^2},

\end{equation}
and
\begin{equation}
 \sum_{s,j}\widehat{\mathfrak H}_s^{[j]}
 \le dM_1R^4.

\end{equation}

