[Lemma 3 (Residual lifetime process, Section 4 of \cite{BertoinLeGallLeJan1997}) of arXiv:2604.01852, 'The on/off Brownian snake'] Let $E$ be a complete and separable metric space, let $x \in E$ and let $w \in \mathcal{W}_x$. Consider a Brownian snake $X$ under $\mathbb{P}_w$ (respectively $\mathbb{N}_x$) as defined in Theorem \ref{theorem bivariate brownian snake}. Let $D$ be an open subset of $E$, let $x \in D$ and let $F = E \backslash D$. For $v \in \mathcal{W}_x$, set $\tau(v) \coloneqq \inf(\{t \geq 0, v(t) \notin D \})$. Assume that $P^\xi_x(\tau<\infty)>0$. Then define
    \begin{equation*}
        U_t \coloneqq (\zeta(X_t) - \tau(X_t))^+ \hspace{0.5cm} \eta_r \coloneqq \inf\Big(\Big\{t, \int_0^t \mathbbm{1}_{\{\tau(X_u)<\zeta(X_u)\}} du > r \Big\}\Big),
    \end{equation*}
    and then the process $(U_{\eta_r}, r \geq 0)$ is a reflecting Brownian motion $\mathbb{P}_w$-a.s., (respectively is a stopped reflecting Brownian motion $\mathbb{N}_x$-a.e.). Furthermore, it follows that there exists a local time at level $0$ for $(U_t)_{t \geq 0}$ which is the limit
    \begin{equation*}
        \ell(t) \coloneqq \lim_{\varepsilon' \rightarrow 0}\frac{1}{\varepsilon'} \int_{u=0}^t \mathbbm{1}_{\{\tau(X_u) < \zeta(X_u) < \tau(X_u) + \varepsilon'\}} du
    \end{equation*}
    which exists for every $t \geq 0$ $\mathbb{P}_w$-a.s. (respectively $\mathbb{N}_x$-a.e.) and defines a continuous increasing process. As before, let $d\ell(t)$ denote the Lebesgue-Steiltjes measure associated with $\ell(t)$. Under $\mathbb{N}_x$, for a measurable function $\Phi$ we have
    \begin{equation}
        \mathbb{N}_x\Big(\int_{t=0}^\sigma \Phi(X_t)d\ell(t)\Big) = E_x^\xi(\Phi(\xi) \mathbbm{1}_{\tau(\xi) < \infty})
    \end{equation}
    and in particular we have
    \begin{equation}
        \mathbb{N}_x(\ell(\infty)) = P^\xi_x(\tau(\xi)<\infty).
    \end{equation}
    \begin{proof}
        This result is given in \cite{BertoinLeGallLeJan1997} at the start of Section 4 prior to the introduction of exit measures. In particular, \eqref{equation local time general} is given in \cite[Equation (35)]{BertoinLeGallLeJan1997} and \eqref{equation local time contribution} is a particular instance of this result.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Teorema 17 (Reconstruction of the flow) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $ V=(Y, C, \tau, H)$ be an infinitesimal stochastic transformation (as before, $Y=(\tilde{Y},m)$). Then, it is possible to reconstruct the corresponding one-parameter group $ T_{\lambda}$ by choosing $\Phi_{\lambda}, f_{\lambda}, B_{\lambda},\eta_{\lambda},h_{\lambda}$ as solutions to the following system
 \begin{equation} \begin{matrix} \partial_{\lambda}(\Phi_{\lambda}(x,t))=Y(\Phi_{\lambda}(x,t)) & \partial_{\lambda} f_{\lambda}(t)=m(f_{\lambda}(t))\\
 \partial_{\lambda}(B_{\lambda}(x,t))=C(\Phi_{\lambda}(x,t)) B_{\lambda}(x,t) & \partial_{\lambda}(\eta_{\lambda}(t))=\tau(f_{\lambda}(t))\eta_{\lambda}(t)\\ \partial_{\lambda}(h_{\lambda}(x,t))=\sqrt{\eta_{\lambda}}B_{\lambda}^{-1}(x,t) H(\Phi_{\lambda}(x,t)) & \\\end{matrix} \end{equation} with initial conditions \begin{equation*} \begin{matrix} \Phi_0=Id_{\mathbb{R}^n};& f_0=id_{\mathbb{R}}; & B_0=I_m; & \eta_0=1; & h_0=0. \end{matrix} \end{equation*}

[Con conj: minority pr of arXiv:2606.19583, 'Power-law hypothesis and (un)fairness of PageRank on undirected multi-type PAMs'] Consider the two-colored PAM with $m_1=m_2=m$,
\begin{equation*}
\kappa(1,2)=\kappa(2,1)=\varepsilon,\qquad
 \kappa(1,1)=\kappa(2,2)=1-\varepsilon,
 \end{equation*}
 and probability $\mu_1$ of being a minority vertex. Then, for every $c>0$ sufficiently small, there is some $\delta(c)>0$ such that, for every $m \in \mathbb{N}$,
\begin{itemize}
     \item[$\rhd$] $\limsup_{n \to \infty}\frac{R_\mathrm{mino}(G_n)}{n+n_0}<\mu_1$ \ almost surely for every $0<\varepsilon<\frac{1}{2}-\delta(c)$ and $\mu_1 \in (0,\frac{1}{2});$ 
 \item[$\rhd$] $\liminf_{n \to \infty}\frac{R_\mathrm{mino}(G_n)}{n+n_0}>\mu_1$ \ almost surely for every $\varepsilon>\frac{1}{2}+\delta(c)$ and $\mu_1 \in (0,\frac{1}{2})$. 
  \end{itemize}
 In words, for sufficiently large graphs, the proportion of the total minority PageRank among the total PageRank $n+n_0$ is lower than the proportion of minority vertices in the network when the attachment kernel $\kappa$ is homophilic, while it is larger when $\kappa$ is  heterophilic. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 4 of arXiv:2607.20838, 'Long-memory Markov chains with power-law intensities'] Let $I(K) = \int_{K}^{\infty} \bar{F}_{\varepsilon}(u) \D u$. 
	For all $x,c>0$, the inter-arrival time $\tau_n$ satisfies
	\begin{equation}
		\mathbb{E}_{x,c}[\tau_n] \le \frac{\mu_{\varepsilon}}{\mu + k_p x} + \dfrac{I\left((\mu + k_p x)c\right)}{\mu}, \quad\quad k_p = \frac{1-2^{\,1-p}}{p-1}.
	\end{equation}
	For any $x_* > 0$, the conditional expectation $\mathbb{E}_{x,c}[\tau_n]$ satisfies:
	\[
	\mathbb{E}_{x,c}[\tau_n] \le 
	\begin{cases} 
		\dfrac{\mu_{\varepsilon}}{\mu + k_p x} + \dfrac{I((\mu + k_p x)c)}{\mu}, & x \ge x_*, \\[3ex]
		\dfrac{\mu_{\varepsilon}}{\mu} + \dfrac{I(\mu c)}{\mu}, & 0 \le x < x_*.
	\end{cases}
	\]

