\begin{align*}
    S_{c\Lap}(t) = -t + S_{-c\Lap}(-t) = -t + S_{c\Lap}(-t).
\end{align*}
Combining the three displays,
\begin{align*}
    S_X(t) = -t + S_{-X}(-t) \le -t + S_{c\Lap}(-t) = S_{c\Lap}(t).","release_manifest_digest":"sha256:9e1777136eea6332f92fb01da49e047ac14fcdbc2903ff1b88d146f888229438","revision_digest":"sha256:a364d70027ab0430543f5d5908453437bc84f695ccbd44d9f1a47257c06647c6","source_id":"arxiv:2609.02398","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

