body:
[Proposition 8 (Bias and variance bounds) of arXiv:2604.17526, '2604.17526'] Let~$U$ be a double well potential that satisfies Assumptions~\ref{a:criticalpts}--\ref{a:massRatioBound}, and let~$\epsilon_1 \in (\epsilon_{\min}, \epsilon_{\max}]$.
  Let~$\nu > 0$ be a fixed constant.
  There exists constants~$\bar C_w = \bar C_w(U, \nu)$, and~$C_T = C_T(U)$ such that the following holds.
  For any~$\epsilon \in (\epsilon_{\min}, \epsilon_{1}]$ choose
  \begin{equation}
    K = \ceil[\bigg]{ \frac{1}{\epsilon \nu} }
    \quad\text{and}\quad
    T > \max\set[\Big]{
      t_{\mix, \epsilon_1}^\infty,
      C_T \paren[\Big]{\frac{1}{\epsilon} + \log K}
    }
    \,,
  \end{equation}
  and choose~$\epsilon_2$, \dots, $\epsilon_{K+1} = \epsilon$ so that~$\set{1/\epsilon_k}_{1 \leq k \leq K+1}$ are linearly spaced.
  Run Algorithm~\ref{a:aisLMC} with this choice of parameters and obtain the point~$X_K$, and unnormalized weight~$\tilde w_K$.
  Then, for all bounded measurable test functions~$f$, we have the bias and variance estimates
  \begin{align}
    \abs[\bigg]{\frac{\E \tilde w_{K} f(X_{K})}{\E \tilde w_{K}} - \ip{f, \pi_{\epsilon}}}
      &\leq 2^{2- T / t_{\mix, 1}^\infty} \norm{f}_\infty
    \,,
    \\

	\var\paren[\bigg]{\frac{\tilde w_{K} f(X_{K})}{\E \tilde w_{K}}}
	  &\leq 4 \bar C_w \norm{f}_\infty^2
	  \,.
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def: J of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For any $\rho\in{\mathcal T}_b$ with $k+1$ leaves and $\ell\in\{1,\ldots,m_L(\rho)+1\}$ we define recursively a multi-index  
		$J_{\rho,\ell}:\{0,1,\ldots,k\}^\ell_<\to\mathbb{N}$ as follows: 
		\begin{itemize} 
		\item $J_{\bullet_i,1}=\un{(0)}$ and, given 
		$J_{V^-(\rho),m_L(\rho)}: \{0,\ldots,k-1\}^{m_L(\rho)}_<\to\mathbb{N}$, recall (equation V- of the paper),
			\item for $j\in\{0,\ldots,k\}$
			\[
			J_{\rho,1}(\,j) := \sum_{i_1<\cdots <i_{m_L(\rho)}<k} 
			\un{(i_1<j )}\, J_{V^-(\rho),m_L(\rho)}(i_1,\ldots,i_{m_L(\rho)})\,,
			\]
			\item for $\ell\in\{2,\ldots,m_L(\rho)\}$, $\boldsymbol{j}_\ell=(\,j_1,\ldots,j_{\ell})\in\{0,\ldots,k\}^\ell_<$:
			\begin{equation}
			J_{\rho,\ell}(\,\boldsymbol{j}_\ell) := \sum_{i_{\ell}<\cdots <i_{m_L(\rho)}<k} 
			\un{(\, j_\ell \le i_\ell)}\, J_{V^-(\rho),m_L(\rho)}(\,j_1,\ldots,j_{\ell-1},i_{\ell},\ldots ,i_{m_L(\rho)})\,,
			\end{equation}
			\item for $\boldsymbol{j}_{m_L(\rho)+1}=(\,j_1,\ldots,j_{m_L(\rho)+1})\in\{0,\ldots, k\}^{m_L(\rho)+1}_<$:
			\begin{equation}
				J_{\rho,m_L(\rho)+1}(\,\boldsymbol{j}_{m_L(\rho)+1}) := 
				J_{V^-(\rho),m_L(\rho)}(\,j_1,\ldots,j_{m_L(\rho)})\,.
			\end{equation}


		\end{itemize}

[Lem 16 (Weak initial trace condition) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] Let $(u,\nu)$ be the pair constructed in the proof of Theorem \ref{thm:existence-obstacle-solution}.

Then, we have
\begin{equation*}
\lim_{\tau\downarrow0}\frac1{\tau}\int_0^\tau\Vert u(t)-u^0\Vert_{L^2(\mathbb T^N)}^2\dd t=0,\qquad \mathbb P\text{-a.s.,}
\end{equation*}
and therefore,
\begin{equation*}
\lim_{\tau\downarrow0}\frac1{\tau}\int_0^\tau\Vert u(t)-u^0\Vert_{L^1(\mathbb T^N)}\dd t=0,\qquad \mathbb P\text{-a.s.,}
\end{equation*}
which means that the pair $(u,\nu)$ satisfies the weak initial trace condition in Definition \ref{def:dfn-1}.

[Theorem 3 of arXiv:2609.00209, 'Exit Times for Brownian Motion and Location Detection'] Let $\mathcal E$ be an elliptic domain as above with $a\neq b$ and let $u_1(x,y)=\mathbb{E}^{(x,y)}[\tau_{\mathcal E}]$ and $u_2(x,y)=\mathbb{E}^{(x,y)}[\tau_{\mathcal E}^2]$  be the first two moments of the exit time from $\mathcal E$. Then
\begin{align*}
u_1(x,y)&=\frac{a^2b^2}{2(a^2 + b^2)}\left(1-\frac{x^2}{a^2} - \frac{y^2}{b^2}\right),\\
u_2(x,y)&= u_1(x,y)(Ax^2 + By^2 + C),
\end{align*}
where
\begin{align*}
    A &= -\frac{b^2(5a^2+b^2)}{6(a^4+6a^2b^2 + b^4)}, \\
    B&= -\frac{a^2(a^2 + 5b^2)}{6(a^4+6a^2b^2 + b^4)}, \\
    C&= \frac{a^2b^2(5a^4 + 26a^2b^2 + 5b^4)}{6(a^2+b^2)(a^4+6a^2b^2 + b^4)}.
\end{align*}
Given positive real numbers $c_1$ and $c_2$, if the level curves $u_1(x,y)=c_1$ and $u_2(x,y)=c_2$ intersect, then their intersection is  either four points, two points, or a single point determined by $c_1$ and $c_2$.

