body:
[Lemma 51 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $j\geq 1$ and $l\geq 0$.
There is a constant $C_{j,l}>0$ depending only on $j$ and $l$
(in particular depending neither on $D$ nor $b$),
such that a.s., for every $z,w\in D$ with $z\neq w$,
\begin{multline}

V_{A_{0,b}}(z)^{l}V_{A_{0,b}}(w)^{l}
G_{D\setminus A_{0,b}}(z,w)^{j}
\ind_{\{\ell_{0,b}(z)=\ell_{0,b}(w)=b\}}
\\
\leq C_{j,l} (1\vee\diam(D)^{j/4})
\Big(
1\vee\log\Big(\dfrac{2(1\vee\diam(D))}{\vert w-z\vert}\Big)^{j+2l}
\Big)
\,
\ind_{z\stackrel{D\setminus A_{0,b}}{\longleftrightarrow} w,\,\ell_{0,b}(z) = b}.
\end{multline}

[Cor uniquePelec of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For every $\beta>0$ the functional
    \begin{align}
        \mathcal F_{\beta}^{elec}: \mathcal P_{s,1}(\Gamma)\to \IR \cup \{+\infty\}, \mathsf{P}\mapsto \beta \mathcal W^{elec}(\mathsf{P})+\mathcal E(\mathsf{P})
    \end{align}
    has a unique minimizer.

[Lemma lemma-5.7e of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let $\beta=\beta_\text{\rm c}$, $\alpha\in(-\ffrac12,\ffrac12)$ and let $A:=[\frac{b^3-1}{(b-1)^2(b+1)^3}]^{1/2}$ be the constant on the right of (equation Eq:3.18u of the paper).  For $0\le k\le n$ set
\begin{equation}

\fraktura e_k:=\sum_{j\ge\min\{\sqrt k, n-\sqrt k\}}\fraktura d_j,
\end{equation}
where~$\{\fraktura d_j\}_{j\ge0}$ is the sequence from Assumption~(ass-1 of the paper). Then 
\begin{equation}

\Gamma_{k,1}(0,0)=\exp\Bigl\{- 2(b-1)A^2 k^{-1}+O(k^{-3/2})+O(k^{-1}\fraktura e_{k-1})+O(\fraktura d_{\min\{k-1,n-k+1\}})\Bigr\}
\end{equation}
and, for $j=2,\dots,k-1$ and~$\eta$ defined by~$\text{\rm  e}\mkern0.7mu^{-\eta}:=b^{-\frac12(1-2|\alpha|)}$,
\begin{equation}

\begin{aligned}
\Gamma_{k,j}(0,0) = \bigl(b^{-(1+2\alpha)(j-1)}+&b^{-(1-2\alpha)(j-1)}\bigr)(b-1)^2 A^2 k^{-1}
\\
&+O(\text{\rm  e}\mkern0.7mu^{-\eta j}k^{-3/2})+O\bigl(\text{\rm  e}\mkern0.7mu^{-\eta j}k^{-1}(\fraktura e_{k-1}+\fraktura e_{k-j})\bigr),
\end{aligned}
\end{equation}
where the error bounds are uniform in $j$, $k$ and~$n$ such that $2\le j< k\le n+1$ and in~$\alpha$ on compact subsets of $(-\ffrac12,\ffrac12)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 38 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] Let $\mathscr{L}_n$ be the infinitesimal generator of  SDE (\ref{FSDE}) under Assumption \ref{A1}. For the function $V_n(x)=1+x_1^2+\cdots +x_n^2$, there exist constants $C,c> 0$ such that 
		\begin{equation}

			\mathscr{L}_nV_n(x)+cV_n(x)\leq C , \forall x\in \mathbb{R}^n.
		\end{equation}

