body:
[Thm structural results-exponential-decay of arXiv:2609.01499, 'On the rigidity of sloped height functions in $d\ge 3$ \\ and non-crossing surfaces'] (Exponential decay)
    Suppose the same assumptions as in Theorem~(thm:main-localization of the paper). Let $\mu$ be a Gibbs measure with ergodic, minimal gradient measure of slope $\mathfrak{s}$. Then there exist $C,c>0$, depending only on $\beta_0(d)$ of~(equation eq:main assumption of the paper) and the dimension $d$, such that the following holds:
        \begin{enumerate}
            \item For each $v\in\mathbb{Z}^d$ and $t>0$,
            \begin{equation}
                \mu(|\phi_v - h(\mathcal L_v)|\ge t)\le Ce^{-ct}.
            \end{equation}
            \item Let $f_1,f_2:\mathbb{Z}^{\mathbb{Z}^d}\to[-1,1]$ be local in the sense that $f_i(\phi)$ depends only on the restriction of $\phi$ to a finite $\Lambda_i\subset\mathbb{Z}^d$, for each $i\in\{1,2\}$. Then
            \begin{equation}
                \mathbb{E}\left[|\mathrm{Cov}_{\mu | h_0, \alpha}(f_1(\phi), f_2(\phi))|\right]\le C\sum_{u\in\Lambda_1} e^{-cd(u,\Lambda_2)}
            \end{equation}
            where $\mathrm{Cov}_{\mu | h_0,\alpha}$ denotes covariance when $\phi$ is sampled from (the extremal measure) $\mu$ conditioned on $h_0$ and $\alpha$, where the expectation $\mathbb{E}$ is over $h_0$ and $\alpha$ and where $d(u,A)=\inf_{v\in A}\|u-v\|_1$ is the graph distance in $\mathbb{Z}^d$ from $u$ to $A$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:CE-macro-DobrushinBC of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix $n\geq 0$ and $g\geq 0$. In the setting of (prop:CE-meso of the paper), under the relaxed condition $|\partial_{\mathtt v} F|\vee |\partial_{\mathtt v} V| \leq  O(L e^{\sqrt{\log L}})$ and the modified definition of the event $\ensuremath{\mathcal G}$ as
    \begin{align*} \ensuremath{\mathcal G} := \left\{|\gamma| \leq Le^{\sqrt{\log L}}\right\}\cap \bigcap_{i=0,1}\left\{|D_i \cap F| \leq \Big(\frac{3\beta}{{\widehat\pi}_\infty(\phi_o > H+1-n-i)}\Big)^2\right\}\,,\end{align*}
the following holds. The probability distribution $\mathfrak{p}_{V;F}^\eta$ on $\gamma\in\ensuremath{\mathcal G}$ given by 
		\begin{equation*}
        \mathfrak{p}_{V;F}^{\eta}(\gamma) := 
		\frac1{{Z}^\eta_{V;F}} \exp\bigg(-{\ensuremath{\mathscr E}}^*_\beta(\gamma) + \frac{\uprho_{n}}{N_n}|D_0 \cap F|+ \mathfrak{I}_V(\gamma) + \upxi_{n+1}\sum_{i\geq 2}|D_i \cap F|\bigg)
		\end{equation*}
		with $N_n$ from (eq:Nn-def of the paper), $\uprho_{n}$ from (eq:rho-n-def of the paper), and a normalizer ${Z}^\eta_{V;F}$, satisfies that
		\begin{align}
			\pi^\eta_{V;F}(\gamma \mid \ensuremath{\mathcal G}) = \exp\left(O\Big(\sqrt L e^{\frac{\log L}{\log\log L}}\Big)\right)\mathfrak{p}_{V;F}^{\eta}(\gamma)
		\end{align}
        uniformly over all $\gamma\in \ensuremath{\mathcal G}$.

[Corollary coro:Charact of Gamma of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Suppose that $(\Omega, \mathcal{H}, \hat{\mathbb{E}})$ is a regular sublinear expectation space. Then for any $X\in \mathcal{H}^d$ with $X\sim \Gamma$, we have
     \begin{equation*}
         \Gamma=\{\mathbb E_P[X]: P\in \mathcal{P}\},
     \end{equation*}
     where $\mathcal{P}$ is given by (equation Prob set for X of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem ito-convergence of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Consider the setup of (general-mild-existence of the paper) and (def:yosida of the paper), and suppose $\theta_F = \theta_G = 0$. Let $\Phi: \mathcal{B} \to \mathbb{R}$ be twice continuously differentiable with linearly bounded first and second derivatives: $\|\Phi'(x)\|_{\mathcal{L}(\mathcal{B},\mathbb{R})} + \|\Phi''(x)\|_{\mathcal{L}(\mathcal{B},\mathcal{L}(\mathcal{B},\mathbb{R}))} \lesssim 1 + \|x\|_B$. Then for all $T > 0$, $p \geq 2$:
    \begin{itemize}
        \item $\lim_{n \to \infty} \mathbb{E}\Big[\int_0^T |\Phi'(x_n(t))F_n(x_n(t)) - \Phi'(x(t))F(x(t))|^pdt\Big] = 0$.
        \item $\lim_{n \to \infty} \mathbb{E}\Big[\int_0^T \|\Phi'(x_n(t))G_n(x_n(t)) - \Phi'(x(t))G(x(t))\|_{\mathcal{U}^*}^pdt\Big] = 0$.
        \item $\lim_{n \to \infty} \mathbb{E}\Big[\int_0^T |\operatorname{tr}_{G_n(x_n(t))}\Phi''(x_n(t)) - \operatorname{tr}_{G(x(t))}\Phi''(x(t))|^pdt\Big] = 0$. (For any operator $T$ on $\mathcal{U}$ we define $\operatorname{tr}_{T}\Phi''(x) = \sum_{j \geq 1} \Phi''(x)[Tu_j, Tu_j]$ where $(u_j)$ is an orthonormal basis for $\mathcal{U}$.)
    \end{itemize}
    Thus,
    \begin{align*}
        \int_0^t \Phi'(x_n F_n(x_n))ds + \int_0^t \Phi'(x_n G_n(x_n)) dW_s + \frac{1}{2}\int_0^t \operatorname{tr}_{G_n(x_n)}\Phi''(x_n)ds \\
        \to \int_0^t \Phi'(x)F(x)ds + \int_0^t \Phi'(x)G(x)dW_s + \frac{1}{2}\int_0^t \operatorname{tr}_{G(x)}\Phi''(x)ds
    \end{align*}
    in $L^p(\Omega; C([0,T], \mathbb{R}))$, where we omitted the dependence of $x_n$ and $x$ on $s$.

