body:
[Corollary 33 (Localized cubic coordinate) of arXiv:2607.10813, '2607.10813'] Fix an adapted localization pair $(\chi,\rho)$ and $a\in\mathfrak C$.
For every $M>0$ and every finite $p\ge2$, the sequence
$\mathcal R_{a,\Lambda}^{\chi,\rho}$ in
\eqref{eq:localized-cubic-split} converges in
\begin{equation}
 L^p\!\left(\Omega;
 C_T(H^M\cap\mathcal C^M)\right)
\end{equation}
to a compactly supported path $\mathcal R_a^{\chi,\rho}$.  The limit obeys
\begin{equation}
 \|\mathcal R_a^{\chi,\rho}\|_{C_T(H^M\cap\mathcal C^M)}
 \lesssim_{M,\chi,\rho}
 \|V_{a^\perp}\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
 \|\Psi_a\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}.
\end{equation}
More generally, if $f_j,g_j\in C_T\mathfrak T_{J_{\mathrm{ps}}}$, then
with
$\mathcal R^{\chi,\rho}(f,g):=
 \chi(((\rho-1)f)\circ g)$,
\begin{align}
 &\|\mathcal R^{\chi,\rho}(f_1,g_1)
      -\mathcal R^{\chi,\rho}(f_2,g_2)\|_{C_T(H^M\cap\mathcal C^M)}
 \notag\\
 &\quad\lesssim_{M,\chi,\rho}
 \|f_1-f_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
 \bigl(\|g_1\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
      +\|g_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}\bigr)
 \notag\\
 &\qquad\quad+
 \|g_1-g_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
 \bigl(\|f_1\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
      +\|f_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}\bigr).

\end{align}
The finite-cutoff Wick decomposition from
\eqref{eq:cubic-wick-decomposition} and
\eqref{eq:localized-cubic-split} gives
\begin{equation}
 \Gamma_{a,\Lambda}^{\chi,\rho}
 =\chi\Gamma_{a,\Lambda}^{(3)}
  +\chi\Gamma_{a,\Lambda}^{(1)}
  +\mathcal R_{a,\Lambda}^{\chi,\rho}.
\end{equation}
Set
\begin{equation}
 \Gamma_a^{\chi,\rho}:=\chi\Gamma_a+\mathcal R_a^{\chi,\rho}.
\end{equation}
Then
\begin{equation}
 \Gamma_{a,\Lambda}^{\chi,\rho}
 \longrightarrow \Gamma_a^{\chi,\rho}
\end{equation}
in
\[
 L^p\!\left(\Omega;
 C_T\mathcal C^{-\beta_{\Gamma,a}-\kappa}
 \cap L_T^\infty B_{2,\infty}^{-\beta_{\Gamma,a}-\kappa}\right).
\]
Along a fixed-profile dyadic family the convergence holds almost surely along
the full sequence; along an arbitrary admissible cofinal sequence it holds in
probability.  In all cases the decomposition
\begin{equation}
 \Gamma_a^{\chi,\rho}
 =\chi\Gamma_a^{(3)}+\chi\Gamma_a^{(1)}
  +\mathcal R_a^{\chi,\rho}
\end{equation}
is preserved in the limit.

[Lemma Phi-pointwise of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] For every fixed $x\in (0,1)$, the sequence $\{\Phi
_{n}(x)\}_{n=0}^{\infty }$ converges pointwise 
\begin{equation}
\lim_{n\rightarrow \infty }\Phi _{n}(x)=\Phi _{\infty }(x),  
\end{equation}

where we denoted the limit by $\Phi _{\infty }(x)$.

