body:
[Proposition Prop-TaylormadeIto-1 of arXiv:2512.13200, 'Martingales on a Euclidean manifold with a boundary and reflected BSDEs in non-convex doma'] Let {Assumption (ass:3 of the paper) hold.}

 Consider a $C^1$ $\Gamma$-convex function $\psi : \bar{\mathcal{D}} \rightarrow \mathbb{R}$ (resp., $\psi : \bar{\mathcal{D}} \times \bar{\mathcal{D}}\rightarrow \mathbb{R}$) and a (Euclidean) semimartingale $(X_t)_{t \in [0,T]}$ with values in $\bar{\mathcal{D}}$ (resp., $\bar{\mathcal{D}}\times \bar{\mathcal{D}}$). Then,
 \begin{align*} 
 \psi(X_t) \geqslant \psi(X_s) +\int_s^t \nabla \psi (X_u) \mathrm{d} X_u, \quad \forall \, 0 \leqslant s \leqslant t \leqslant T.
 \end{align*}
 More generally, consider any continuous function $S: \bar{\mathcal{D}} \rightarrow \mathcal{S}^+$ (resp. $S: \bar{\mathcal{D}}\times \bar{\mathcal{D}} \rightarrow \mathcal{S}^+$), where $\mathcal{S}^+ \subset \mathbb{R}^{2 \times 2}$ (resp., $\mathcal{S}^+ \subset \mathbb{R}^{4 \times 4}$) is the set of all symmetric positive semidefinite matrices, such that the following holds for all geodesics $\gamma$:
 \begin{equation}

    \psi(\gamma_t) \geqslant \psi(\gamma_0)+\langle \nabla \psi(\gamma_0),\dot \gamma_0 \rangle t + \int_0^t (t-s) \dot \gamma_s^\top S(\gamma_{s})\dot \gamma_s \mathrm{d} s.
 \end{equation}
 Then, we have
 $$\psi(X_t) \geqslant \psi(X_s) +\int_s^t \nabla \psi (X_u) \mathrm{d} X_u + \frac12 \int_s^t  \langle \mathrm{d} X_u, S(X_u) \mathrm{d} X_u \rangle, \quad \forall 0 \leqslant s \leqslant t \leqslant T.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $p,q\in(2,\infty)$ satisfy $p>(n+2)q/2$, and let $\theta\in(0,1)$. Suppose that $u$ solves \eqref{eq:model-half-space} in $Q_1^+$ with homogeneous boundary condition on $\{x_1=0\}\cap\partial Q_1^+$. Then
\begin{align*}
|Du|_{0;Q_\theta^+}^{L_\omega^q}
&\le C\Bigl(\|u\|_{L_\omega^qL_t^qL_x^p(Q_1^+)}
+\|f\|_{L_\omega^qL_t^qL_x^p(Q_1^+)}
+\|g\|_{L_\omega^qL_t^qW_x^{1,p}(Q_1^+;\elltwo)}\Bigr),
\end{align*}
where $C$ depends only on $n$, $p$, $q$, $\theta$, $\kappa$, and $K$.

[Lemma 35 of arXiv:2607.18104, '2607.18104'] Fix some $c_0>0$. 
There exists a coupling $\mathbf{P}_{N,n}$ between the patched and periodic LPP landscapes, and constants $c,C>0$, such that for all $n\in \N$, we find some $N_0=N_0(n)$ such that for all $N \geq N_0$, 
\begin{equation*}
\mathbf{P}_{N,n}\Big( \LLpeps(x,s;y,t)=\LLpaeps(x,s;y,t) \, \forall (x,s;y,t) \in \mathcal{D}_{c_0n^{-1}} \cap \SetT \Big) \geq 1 - C\exp(-cn^{\frac{1}{6}}) .
\end{equation*}

