body:
[Definition 19 of arXiv:2507.06186, '2507.06186'] For any $\ka,\eps,t>0$, we let $\mc K_{\ka,\eps}(t)$ denote the integral operator on $L^2(D)$ with kernel
\begin{align}

\mc K_{\ka,\eps}(t;x,y)=p_t(x-y)\mbf E_B\left[\mbf 1_{\{\tau_D(B^{x,y}_t)>t\}}\exp\left(-\ka\int_0^t\xi_\eps\big(B^{x,y}_t(r)\big)\d r\right)\right],\qquad x,y\in D,
\end{align}
where we assume that $B^{x,y}_t$ and $\xi_\eps$ are independent, and we use $\mbf E_B$ to
denote the (conditional) expectation with respect to the randomness in $B$ only.

[Theorem 2 of arXiv:2608.05866, 'The Berry--Esseen Estimate \\in the Free Central Limit Theorem'] \begin{equation}
\Delta(\mu^{(n)},\omega)\le CL_{3,n}\left(=\frac{C}{B_n^3}\sum_{j=1}^n\int_{\R}|x|^3\,\mu_j(dx)\right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2609.02842, 'Global Well-posedness and Asymptotic Analysis of a Damped Nonlinear Wave Equation with a C'] Let $\vartheta_0\in D(\mathcal{A})\cap\mathcal{M}$ and $\vartheta_1\in H_0^1(\varOmega)$ with $(\vartheta_0,\vartheta_1)=0$. 	Let $\vartheta$ be the unique strong solution of \eqref{eq:mains}--\eqref{MID}. Then there exists a sequence $\{t_n\}_{n\in\mathbb{N}}$, $t_n\to\infty$ as $n\to\infty$ and $\vartheta_{\infty}\in H_0^1(\varOmega)\cap\mathcal{M}$  such that 
		\begin{equation*}
			\vartheta (t_n)\to  \vartheta_\infty\ \text{ strongly in }\ H_0^1(\varOmega).
		\end{equation*}
		Moreover, $\vartheta_\infty$ is a  weak solution of the following system:
		\begin{equation}
			\left\{
			\begin{aligned}
				\A\vartheta_\infty+|\vartheta_\infty|^{p-2}\vartheta_\infty
				&=\lambda_\infty \vartheta_\infty
				&&\text{ in }\ H^{-1}(\varOmega),\\

				\|\vartheta_\infty\|_{L^2(\varOmega)}&=1,
			\end{aligned}
			\right. 
		\end{equation}
		where $	\lambda_{\infty}= \|\nabla\vartheta_\infty\|^2 _{L^2(\varOmega)}+\|\vartheta_\infty\|^p_{L^p(\varOmega)}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 55 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Let $v : [0,1] \times \T^d \to \R^d$ be such that $\nabla \cdot v =0$ and $v \in L^\infty([0,1] \times \T^d)$. Let $X^\kappa_t(y)$ denote the solution to~\eqref{eq:main SDE} with $v$ in place of $U$. Suppose for some $t \in (0,1]$
    \[\limsup_{\kappa \to 0} \int_{\T^d} \Var_W(X^\kappa_t(y))\,dy >0.\]
    Then there exists bounded initial data $\phi$ such that
    \begin{equation}

    \begin{cases}
        \partial_t f + v \cdot \nabla f =0,\\
        f(0,\cdot) =\phi(\cdot),
    \end{cases}\end{equation}
    admits at least two distinct bounded solutions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2604.07697, 'Stochastic fractional heat equation with general rough noise'] Recall $\Box(x,y,h)$ defined in \eqref{nota alpha 2}. For any $0<H<\frac12$ and $1<\alpha<2$,  there exists a positive constant $c_\alpha$ such that
\begin{equation}
\left|\Box(x,y,h)\right|\le c_{\alpha}
\begin{cases}
|y||h|\left(\frac{1}{1+|x|}\right)^{3+\alpha}, &|y|\le1, |h|\le 1;\\ 
|D(x+y,h)|+|D(x,h)|,& |y|>1,\text{ or } |h|>1.
\end{cases}
\end{equation}

