[Lemma ll3.1 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] Let $M>0$.	For any $\{h^{\varepsilon}\}_{\varepsilon\in(0,1)}\subset\mathcal{A}_{M}$ and $p \geq 1$,
	\begin{equation}
		\mathbb{E}\Big[\sup\limits_{t\in[0,T]}|X_t^{\varepsilon,h^\varepsilon}|^{2p}\Big]\lesssim_{p,M,T}(1+|x|^{2p}+|y|^{pq}),
	\end{equation}
	\begin{equation}
		\mathbb{E}\bigg[\Big(\int_0^T|Y_t^{\varepsilon,h^\varepsilon}|^qdt\Big)^p\bigg]\lesssim_{p,M,T}(1+|y|^{2p}).
	\end{equation}

[Theorem t:averaging set trigonometric polynomial of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $n\in\N,m\in\N_0$, and suppose that $p$ is a real-valued trigonometric polynomial of degree $m$. Then 
    \begin{equation}
        \{p(2\pi j/n+u):j\in\{1,...,n\}\}
    \end{equation}
    is an averaging set of $p$ of order $\lceil\frac{n}{m}\rceil-1$ for all $u\in\R$, but not of order $\frac{n}{\textnormal{gcf}(n,m)}$ for almost all $u\in\R$.

    Further, suppose that $p_1,..., p_d$ are real-valued trigonometric polynomials of degrees \linebreak $m_1,...,m_d\in\N_0$. Then 
    \begin{equation}
        \big\{\big(p_1(2\pi j/n+u),...,p_d(2\pi j/n+u)\big):j\in\{1,...,n\}\big\}
    \end{equation}
    is an averaging set of $(p_1,...,p_d)$ of order $\lceil\frac{n}{\max(m_1,...,m_d)}\rceil-1$ for all $u\in\R$, but not of order $\frac{n}{\max(\textnormal{gcf}(n,m_1),...,\textnormal{gcf}(n,m_d))}$ for almost all $u\in\R$.
    \begin{proof}
        We show only the first assertion. The second follows in just the same way. We assume that $m\in\N$, as the assertion is trivial for $m=0$. First, we have to show that
        \begin{equation}
            \frac{1}{2\pi} \int_0^{2\pi} p(x)^k \, dx = \frac{1}{n}\sum_{j=1}^n p(2\pi j/n+u)^k,\quad k\in\{0,...,\lceil\tfrac{n}{m}\rceil-1\}, u\in\R.
        \end{equation}
        This follows from Proposition~(p:trig poly avset of the paper) and the fact that $p^k$ is a trigonometric polynomial of degree $km\leq (\lceil\tfrac{n}{m}\rceil-1) m\leq n-1$. For the second part, let $l:=\frac{m}{\textnormal{gcf}(n,m)}\in\N$. Note that $p^{\frac{n}{\textnormal{gcf}(n,m)}}$ is a trigonometric polynomial of degree $\frac{n}{\textnormal{gcf}(n,m)}m=ln$. Further,
        \begin{equation*}
            \frac{1}{n}\sum_{j=1}^n e^{iln(2\pi j/n+u)} = e^{ilnu} \frac{1}{n}\sum_{j=1}^n e^{2\pi ilj} = e^{ilnu},\quad u\in\R.
        \end{equation*}
        As $p^{\frac{n}{\textnormal{gcf}(n,m)}}$ is real-valued and of degree $ln$, this monomial has non-zero coefficient. Hence,
        \begin{equation*}
            \frac{1}{n}\sum_{j=1}^n p(2\pi j/n+u)^{ln} = a e^{ilnu} + q(u), \quad u\in\R,
        \end{equation*}
        where $a\in\C\setminus\{0\}$ and $q$ is a trigonometric polynomial which is linearly independent of the monomial. Hence, all level sets of the RHS are null sets.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 (Stability, Lemma 5.11 in \cite{yang2019edge}) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Let $c_0>0$ be a sufficiently small constant and fix constants $C_0,\epsilon>0$. The self-consistent equation $f(z,\al)=0$ is stable on $S(c_0,C_0, \epsilon)$ in the following sense. Suppose that the $z$-dependent function $\delta$ satisfies $n^{-2} \le \delta(z) \le (\log n)^{-1}$ for $z\in S(c_0,C_0, \epsilon)$ and is Lipschitz continuous with Lipschitz constant $\lesssim n^2$. Suppose moreover that, for each fixed $E$, the function $\eta \mapsto \delta(E+\ii\eta)$ is non-increasing for $\eta>0$. Suppose that $u_2: S(c_0,C_0,\epsilon)\to \mathbb C$ is the Stieltjes transform of a probability measure. Let $z\in S(c_0,C_0,\epsilon)$ and assume that for all $z'\in L(z)$ we have
\begin{equation}
\left| f(z', u_2)\right| \le \delta(z').
\end{equation}
Then
\begin{equation}
\left|u_2(z)-m_{2c}(z)\right|\le \frac{C\delta}{\sqrt{\kappa+\eta+\delta}},
\end{equation}
for some constant $C>0$ independent of $z$ and $n$, where $\kappa$ is defined in (\ref{KAPPA}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 (Obtuse probability on concentric
circles) of arXiv:2608.06591, 'Random Triangles on Concentric Circles'] \protect\hypertarget{thm-main}{}

Let \(X\) and \(Y\) be independent and uniform on \((0, \pi/2)\). Then
\begin{equation}\phantomsection{
p_k = \frac{1}{2}\,
  \Pr\!\left(r_i^2 \sin^2 X + r_j^2 \sin^2 Y > r_k^2\right) ,
}\end{equation} and consequently
\begin{equation}\phantomsection{
P(\text{obtuse}) = \frac{1}{2}\sum_{k=1}^{3}
  \Pr\!\left(r_i^2 \sin^2 X + r_j^2 \sin^2 Y > r_k^2\right) .
}\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

