[Theorem 10 of arXiv:2608.06232, 'The mean absolute deviation of the classical discrete distributions:\\ collapse identities'] As $N\to\infty$ with $(\kappa,\eta)=(K/N,n/N)$ in a compact subset of $(0,1)^{2}$,
	\begin{equation}
	\begin{aligned}
		\E|X-\mu|
		&\sim\sqrt{\frac{2Nad}{\pi}}\;
			\exp\Bigl(\sum_{m\ge1}\frac{\tilde a_m(h)}{N^{m}}\Bigr),\\
		\tilde a_m
		&=\frac{(-1)^{m+1}}{m(m+1)}
			\Bigl[(W_m-1)\,B_{m+1}-\widehat\Xi_m\,B_{m+1}(h)\Bigr],
	\end{aligned}
	\end{equation}
	uniformly, in the truncated sense of \S\ref{sec:prelim}, where
	\[
	\begin{aligned}
		W_m&=\kappa^{-m}+(1-\kappa)^{-m}+\eta^{-m}+(1-\eta)^{-m},\\
		\widehat\Xi_m&=\bigl(a^{-m}+d^{-m}\bigr)+(-1)^{m+1}\bigl(b^{-m}+c^{-m}\bigr).
	\end{aligned}
	\]
	Here $Nad=nK(N-K)(N-n)/N^{3}=\sigma^{2}\,(N-1)/N$.  In particular, using $ad=bc$,
	\begin{equation}
		\tilde a_1=\frac1{12}\Bigl[\frac1{\kappa(1-\kappa)}+\frac1{\eta(1-\eta)}-1\Bigr]
		-\frac{B_2(h)}{2\,ad} .
	\end{equation}

[Defn def: 2perGGM of arXiv:2411.13465, 'Height-offset variables and pinning at infinity for gradient Gibbs measures on trees'] Let $\bar{\mu}$ be a Gibbs measure for the Ising model defined by $\bar{Q}$. Then we call the annealed measure $\nu^{\bar{\mu}}$ on $(\Omega^\nabla, \mathcal{F}^\nabla)$ with marginals
\begin{equation}
\begin{split}
\nu^{\bar{\mu}}(\eta_{\Lambda \cup \partial \Lambda}=\zeta_{\Lambda \cup \partial \Lambda})=\frac{1}{Z_{\Lambda \cup \partial \Lambda}}\sum_{\bar{\omega}_{\Lambda \cup \partial \Lambda} \in \mathbb{Z}_2^{\Lambda \cup \partial \Lambda}}\bar{\mu}(\bar{\sigma}_{\Lambda \cup \partial \Lambda}=\bar{\omega}_{\Lambda \cup \partial \Lambda})
\prod_{(x,y) \in {}^\rho\Vec{E}_{\Lambda \cup \partial \Lambda}}\rho^Q(\zeta_{(x,y)} \mid \bar{\omega}_y-\bar{\omega}_x),
\end{split}
\end{equation}
where $\Lambda \Subset V$, the \textbf{gradient Gibbs measure of height period $2$ associated with the hidden Ising measure (or \textit{fuzzy chain}) $\bar{\mu}$}.

[Definition xtilde of arXiv:2606.03079, 'Mean Field Limits for Stochastic, Underdamped Reactive Langevin Dynamics Models'] For reaction $\mathcal{R}_{\ell}$, define subspaces $\tilde{\mathbb{X}}^{(\ell)}\subset \mathbb{X}^{(\ell)}$ and $\tilde{\mathbb{V}}^{(\ell)}\subset \mathbb{V}^{(\ell)}$ by removing all particle substrate position and velocity vectors in $\mathbb{X}^{(\ell)}$ and $\mathbb{V}^{(\ell)}$ respectively for which two particles of the same species have the same position or the same velocity. That is
\begin{align*}
\tilde{\mathbb{X}}^{(\ell)}&=\mathbb{X}^{(\ell)} \backslash\{\bm{x}
 \in \mathbb{X}^{(\ell)} | x_{r}^{(j)}=x_{k}^{(j)} \textrm { for some } 1 \leq j \leq J, 1 \leq k \neq r \leq \alpha_{\ell j}\},\nonumber\\
\tilde{\mathbb{V}}^{(\ell)}&=\mathbb{V}^{(\ell)} \backslash\{\bm{v}
 \in \mathbb{V}^{(\ell)} | v_{r}^{(j)}=v_{k}^{(j)} \textrm { for some } 1 \leq j \leq J, 1 \leq k \neq r \leq \alpha_{\ell j}\}.\nonumber
\end{align*}

[Proposition 21 of arXiv:2608.21063, '\textbf{Non-bijective scaling limits and phase transitions of planar maps}'] For every $p>0$ there is a constant $E_p>0$ such that for all $n\ge 1$
	\begin{align*}
		\sum_{m=1}^{n} \Ex{\Di(\mV_m)^p} \le E_p n^{1+p/4}.
	\end{align*}

