body:
[Lemma 11 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $(\mathcal{Z}^{(\rm d)}_r, \mathcal{Z}^{(\rm a)}_r)_{r \geq 0}$ be the process given in Theorem \ref{theorem ooSBM ffd convergence} and let $(\mathcal{Z}_r)_{r \geq 0}$ be constructed from it as in \eqref{equation overlayed supports}. Let $(\Tilde{\mathcal{Z}}_r)_{r \geq 0}$ be the process given in Proposition \ref{proposition damped sbm}. Let $s > 0$. Then we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. that
    \begin{equation*}
        \text{supp}(\mathcal{Z}_s) = \text{supp}(\mathcal{Z}^{(\rm d)}_s) \cup \text{supp}(\mathcal{Z}^{(\rm a)}_s) = \text{supp}(\mu_{\rm d}) \cup \overline{\bigcup_{i \in I} \{\hat{w}^i_{T^{1/m}_{s,n,i}}: m \in \mathbb{N}, 1 \leq n \leq M_i^{1/m}\}};
    \end{equation*}
    \begin{equation*}
        \text{supp}(\Tilde{\mathcal{Z}}_s) = \overline{\bigcup_{i \in \Tilde{I}}\{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = s, \hat{\Tilde{v}}^i_r=0\}},
    \end{equation*}
    \begin{proof}
        Fix $s>0$. We split the measure $\mathcal{Z}_s$ into measures $\mathcal{Z}_{s, i}$, for $i \in I$, which consist of the active and dormant contributions from the snakes $x^i$, $i \in I$. Specifically, for $i \in I$, $\mathcal{Z}_{s, i}$ is the measure such that for any Borel-measurable function $\Phi$ we have
        \begin{equation}
            \langle \mathcal{Z}_{s, i}, \Phi \rangle = \int_{r=0}^{\sigma(f^i)} \Phi(\hat{w}^i_r) d\ell_{s, i}(r)
        \end{equation}
        and it follows that, by Theorem \ref{theorem ooSBM ffd convergence} that
        \begin{equation*}
            \mathcal{Z}_s = e^{-\Tilde{c}s}\mu_{\rm d} + \sum_{i \in I:s_i<s}\mathcal{Z}_{s, i}.
        \end{equation*}
        The local time processes $(\ell_{s, i}(r))_{r \geq 0}$ are all continuous and increasing a.s. and so, as the processes $(\hat{w}^i_r)_{r \geq 0}$ are also all continuous a.s., we have, by Lemma \ref{lemma support continuous integral}, that
        \begin{equation*}
            \text{supp}(\mathcal{Z}_{s, i}) = \{\hat{w}^i_r: r \in \text{supp}(d\ell_{s, i}) \}
        \end{equation*}
        for all $i \in I$ a.s. For the remainder of this proof of this first result we work under this almost-sure event. Fix $i \in I$. We note that 
        \begin{equation*}
            \{\hat{w}^i_r: r \in \text{supp}(d\ell_{s, i}) \} = \{\hat{w}^i_{\eta(s, u, i)}: u \in \text{supp}(d\hat{\ell}_{s, i})\} 
        \end{equation*}
        as $\ell_{s, i}$ and $\hat{\ell}_{s, i}$ are related by a time change given by the inverse of $\eta$. To see this, take $\tau = \int_{r=0}^{\sigma(f^i)} \mathbbm{1}_{\text{Res}^i_r(s)>0} dr$ and define a right inverse $\Tilde{\eta}:[0,\sigma(f^i)] \rightarrow [0,\tau]$ of $\eta(s, \cdot, i)$ by $\Tilde{\eta}(w) = \int_{r=0}^w \mathbbm{1}_{\text{Res}^i_r(s)>0} dr$. Then $\Tilde{\eta}$ is a continuous function and $\ell_{s, i}$ is a continuous increasing function, and therefore we have for any Borel-measurable $\Phi$
        \begin{equation*}
            \langle d\hat{\ell}_{s, i}, \Phi \rangle = \int_{x=0}^{\sigma} \Phi(\Tilde{\eta}(x))d\ell_{s, i}(x).
        \end{equation*}
        Therefore, by Lemma \ref{lemma support continuous integral}, we have that $\text{supp}(\hat{\ell}_{s, i}) = \{\Tilde{\eta}(x): x \in \text{supp}(\ell_{s, i})\}$ and so
        \begin{equation*}
            \text{supp}(d\ell_{s, i}) = \{\eta(s, u, i): u \in \text{supp}(d\hat{\ell}_{s, i})\}.
        \end{equation*}
        \par
