[Corollary 19 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] If $f \in \cC^k_1(\cB)$, then there exists functions $f^j\in \cC^{k-j}(\cB^{j+1})$, and a constant $C_k$ such that if $(\cA,\tau)\in\W$, $y\in\cA^{\cB}_{c,\sa}$, 
\begin{equation}

    \sup_{x\in \cA_{\sa},\ \norm{x}_{\cA,c}\leq R}\ \norm{f(x+y) - f(x) - f^1(x,y) \dots - f^{k-1}(x,y,\dots,y) } \leq C_k \norm{f}_{k,c,R+\norm{y}_{\cA,c}} \left( \norm{y}_{\cA,c}\right)^{k}. 
\end{equation}
Besides, for all $x,y_1,\dots,y_j,z\in\cA^{\cB}_{c,\sa}$, $i\in [1,j]$,
$$ f^j(x,y_1,\dots,y_i+z,\dots,y_j) = f^j(x,y_1,\dots,y_i,\dots,y_j) + f^j(x,y_1,\dots,z,\dots,y_j).$$
And finally, if we define
$$    \norm{f^j}_{\cA,c,R,T} \coloneqq \sup \left\{\norm{f^j(x,y_1,\dots,y_j)}_{\cA^{\ell,m}} : x,y_1,\dots,y_j \in \cA_{\sa,c}^{\cB,d}, \; \norm{x}_{\cA,c,d} \leq R, \norm{y_i}_{\cA,c,d} \leq T\right\}.
$$
then by similarly defining $\norm{\cdot}_{j,c,R,T}$ as in Definition \ref{def.NCsmooth} but with $\norm{\cdot}_{\cA,c,R,T}$ instead of $\norm{\cdot}_{\cA,c,R}$, then for all $i\leq k-j$ there exists a constant $C_i$ such that
\begin{equation}

    \norm{f^j}_{i,c,R,T} \leq C_i \norm{f}_{\cC^k,R} (T+1)^i,
\end{equation}

[Lemma lem:pretil of arXiv:2609.00889, 'Dominant-Degree Conditions for Ramsey--Tur\'an Factors of Non-Directed Cycle Orientations'] The digraph $D$ has a $\widetilde C$-tiling $\mathcal F_E$ satisfying
\begin{enumerate}[label=\rm(\roman*)]
\item every copy in $\mathcal F_E$ contains exactly one vertex of $E_{\rm bad}$ and $E_{\rm bad}\subseteq V(\mathcal F_E)$;
\item $|V(\mathcal F_E)|=\ell|E_{\rm bad}|\le2\ell\varepsilon n\le\sqrt\varepsilon n$;
\item {for every $i\in[k]$, $|V(\mathcal F_E)\cap V_i|\le 3\sqrt\varepsilon\,m$ for sufficiently large $n$.}
\end{enumerate}

[Definition 48 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\xi \in W$ be arbitrary. A path $(Y,Y') \in \scrd_X^{2 \alpha}([0,T_0],W)$ for some $T_0 \in (0,T]$ is called a \emph{local solution} to the RDE \eqref{RDE} with $Y_0 = \xi$ if $Y' = f(Y)$ and
\begin{align}
Y_t = \xi + \int_0^t f_0(s,Y_s) ds + \int_0^t f(s,Y_s) d\mathbf{X}_s, \quad t \in [0,T_0].
\end{align}
If we can choose $T_0 = T$, then we also call $(Y,Y')$ a \emph{(global) solution} to the RDE \eqref{RDE} with $Y_0 = \xi$.

[Lemma 11 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] For any $w\in W^{1,r}$, $r\ge1$ it holds
    \begin{equation*}
        \nabla u=0 \qquad\text{for a.e. }x\in\{u=0\},
    \end{equation*}
    and for any $w\in W^{2,r}$, $r\ge1$
    \begin{equation*}
        D^2u=0 \qquad\text{for a.e. }x\in\{u=0\}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm l:restrict-to-Good of arXiv:2607.18194, 'Temperature chaos in directed polymers'] There exists $c>0$ such that for all sufficiently small $\varepsilon>0$ and all $k\in \llbracket 0,M\rrbracket$,  we have
    \begin{multline*}
        \limsup_{n\to\infty} \frac{1}{n^{2/3}}
        \mathbb{E}_\mathrm{re}\left[
            \left|
                \mathcal{H}^{\xi,(n)}(0,x;1,y) - \mathcal{H}^{\eta_k,(n)}(0,x;1,y)
            \right|^2
        \right]\\
        \leqslant
        2
        \limsup_{n\to\infty} \frac{1}{n^{2/3}}
        \mathbb{E}_\mathrm{re}\left[
            \left|
                \mathcal{H}^{\xi,(n)}_{{\,\mathrm{TF}_k}} - \mathcal{H}^{\eta_k,(n)}_{{\,\mathrm{TF}_k}}
            \right|^2
            \1_{\xi,\eta_k \in \mathsf{Good}_{\varepsilon,n}}
        \right]
        + e^{-c\log^2(1/\varepsilon)},
    \end{multline*}
    where $\mathcal{H}^{\xi,(n)}_{{\,\mathrm{TF}_k}}$ is defined in (equation e:def-Zreg-Hreg of the paper).

