[Lemma 19 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $p>2$.
There exists $C>0$ depending only on $p$ such that the following holds.
\begin{enumerate}
	\item Let $f \in \cC^2(\R)$ and $\alpha \in [0,1]$. Then, letting $a \coloneqq \int_{-1}^1 f(t) \frac{\diff t}{\sigma(t)}$, the function $\psi_\alpha$ defined by
	\begin{equation} 
		\psi_\alpha(\lambda) = 
		\begin{cases}
			\displaystyle
			-\frac{1}{\pi r_\alpha(\lambda)} 
			\int_{-1}^1 \frac{f(t)-f(\lambda)}{t-\lambda}
			\frac{\diff t}{\sigma(t)},
			& \text{if } \lambda \in [-1,1], \medskip \\
			\displaystyle 
			\frac{\displaystyle\int_{-1}^1 \frac{\psi_\alpha(t)}{\lambda-t} \diff \mu_{V_\alpha}(t)+f(\lambda)-a}{\displaystyle\int_{-1}^1 \frac{1}{\lambda-t} \diff \mu_{V_\alpha}(t) -\frac{1}{2} V_\alpha'(\lambda)},
			& \text{if } \lambda \in \R \setminus [-1,1],
		\end{cases}
	\end{equation}
	is $\cC^1$ on $\R$, satisfies $\Xi_\alpha[\psi_\alpha] = f-a$ and $\norme{\psi_\alpha}_{\cC^1} \leq C \norme{f}_{\cC^2}$. We write $\psi_\alpha = \Xi_\alpha^{-1}[f]$, with a slight abuse of notation.

	\item If moreover $f \in \cC^3(\R)$, then $\psi_\alpha \in \cC^2(\R^*)$ and, for any $\lambda \in \R$,
	\[
	\abs{\psi_\alpha''(\lambda)} \leq C \norme{f}_{\cC^3} \times
	\begin{cases}
	    (1+\abs{\lambda}^{p-3}) & \text{if } p < 3, \\
	    (1+(\log1/\abs{\lambda})_+) & \text{if } p = 3, \\
	    1 & \text{if } p>3.
	\end{cases}
	\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma projection-decomposition of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] Let $x\in\mathcal{U}, x+\Delta \in \mathcal{U}$, where $\mathcal{U}$ is defined as in (equation eq:cU of the paper), and define $p:=\pi_\mathcal{M}(x)$. Suppose that $q:=\pi_\mathcal{M}(x+\Delta)$ lies in the local graph chart around $p$, so that
$q=\Psi_p(\alpha)=p+U_p^\top\alpha+V_p^\top\phi_p(\alpha)$ for some $\alpha\in\mathcal{A}_p$. Then
\begin{align*}
    \alpha = M U_p\Delta,
\end{align*}
where $M\in\mathbb{R}^{d\times d}$ satisfies
\begin{align*}
    \|M-I\|\le \frac13 .
\end{align*}

