[Lemma L:pointwise_conv-B of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] The following assertions hold on $\overline{\Omega}$.
\begin{enumerate}
\item[(i)] If $s,t \in [0,T]$ such that $s \le t $ and   $\phi,\psi  \inU$, then
\begin{align}
	 &\lim_{n \to \infty } \int_{s}^{t} \duality{ \mathscr{A}_n {\overline{u}}_{n} (\sigma) }{ \psi }{}\; \duality{{\overline{u}}_{n}(\sigma)}{\phi}{} \, \mathrm{d}\sigma
	\\&\hspace{2truecm}=\int_{s}^{t} \duality{ \mathscr{A} \overline{u} (\sigma) }{ \psi }{}\;\duality{\overline{u}(\sigma)}{\phi}{}\, \mathrm{d}\sigma.
\nonumber
\end{align}
\item[(ii)] If $\phi \in  {H}$, then  in  $L^2([0,T]\times Y,\Leb\otimes \nu)$, 
\begin{align}
	&\ip{P_n F(r,{\overline{u}}_{n}(r),y)}{\phi}{H}  \to \ip{F(r,\overline{u}(r),y)}{\phi}{H}.
\end{align}
In particular, for every $\phi \in  U$,
\begin{align}
	 &\lim_{n \to \infty } \int_s^t \int_{Y} \left(P_n F(r,{\overline{u}}_{n}(r),y),  \phi \right)_H^2 \, \nu(\mathrm{d} y) \, \mathrm{d}r 
         \\\nonumber 
	&\hspace{2truecm}
     \int_s^t \int_{Y} \left(  F(r,\overline{u} (r),y),\phi \right)_H^2 \, \nu(\mathrm{d} y) \, \mathrm{d}r.
\end{align}

\item[(iii)] Moreover, if $\phi,\psi  \in U$, then
\begin{align}
			&\lim_{n \to \infty }
	\int_{s}^{t} \duality{ B_n \bigl( {\overline{u}}_{n} (\sigma )  \bigr) }{\psi }{} \;\duality{{\overline{u}}_{n}(\sigma)}{\phi}{} \, \mathrm{d}\sigma
    \\
	&\hspace{2truecm}= \int_{s}^{t} \duality{ B\bigl( \overline{u} (\sigma ) \bigr) }{\psi }{}\;\duality{\overline{u}(\sigma)}{\phi}{}  \, \mathrm{d}\sigma.
\nonumber
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] Let $ \M$ a weakly stationary random measure on $ \T.$
 There exists a non-negative measure $ \S$ on $ \Z$ such that
for $ f,g: \T\to  \mathbb C $ bounded,
\begin{align}

  \textrm{Cov}\left(\M(   f),\M(g)\right) =     \int_{ \mathbb{Z} _{\lambda }}  \what{f}{\lambda }  \overline{  \what{g}{\lambda }}d\S.
\end{align}
$ \S$ is called the  {\it spectral measure} of $ \M.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm.3 of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Consider TASEP ($q=0$). Conditionally on the event $U_0 = u$ with $x = \tfrac{1+u}{2}$, the asymptotic size of the convoy of particle $0$ satisfies
\begin{equation}
    \frac{\# \mathcal{C}_0^{n,\left(0\right)}}{\sqrt{n}}
    \Big|_{U_0=u} \xrightarrow[n \to \infty]{d}
    \bigl|\mathcal{N}\left(0,2x\left(1-x\right)\right)\bigr|,
\end{equation}
where $\mathcal{N}\left(0,2x\left(1-x\right)\right)$ denotes a normal random variable with mean $0$ and variance $2x\left(1-x\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

