body:
[Definition def:diagram of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] A \emph{diagram} $\Gamma$ is a ribbon graph satisfying the following two conditions:
\begin{itemize}
    \item Every unmarked vertex has degree at least 3;
    \item Every marked vertex has degree at least 2.
\end{itemize}

For the diagram, we will frequently use   the following notation:
\begin{itemize}
    \item  {\bf Edge set}: let \(E(\Gamma)\) denote the set of all edges of \(\Gamma\), with \(E_{\mathrm{int}}(\Gamma)\) and \(E_{\mathrm{b}}(\Gamma)\) denoting the sets of interior and open (boundary) edges, respectively;
    \item {\bf Vertex   set}: let \(V(\Gamma)\), \(V_{\mathrm{int}}(\Gamma)\) and \(V_{\mathrm{b}}(\Gamma)\) denote the sets of all, interior, and boundary vertices, respectively;
    \item  {\bf Boundary  set}: for each \(j \in [s]\), let \(\partial D_j \subset E(\Gamma)\) denote the set of edges forming the boundary of face \(j\).
     \item  {\bf Diagram  set}: let $\mathscr{D}_{s;\beta}$ be the set of all $s$-cell diagrams (on orientable surfaces when $\beta=2$) and  \(\mathscr{D}_{s;\beta}^* \subset \mathscr{D}_{s;\beta}\) be the subset of connected diagrams.
\end{itemize}

[Corollary 107 (Third-order propagation identity) of arXiv:2608.04993, '2608.04993'] For $z=(x,A,q)\in\mathsf Z_{\eta;\mathcal S_2,1}(H)$, let
$S^{S,(3)}$ and $S^{I,(3)}$ be the third homogeneous levels furnished by
\Cref{thm:all-order-generation}.  Define the mixed transport coordinates
\begin{equation}

 B^{q x}_{s,t}:=\int_s^t q_{s,u}\otimes \dd x_u,
 \qquad
 B^{x q}_{s,t}:=\int_s^t x_{s,u}\otimes \dd q_u,
\end{equation}
where both integrals are Young integrals.  Then
\begin{equation}

 S^{S,(3)}_{s,t}
 =S^{I,(3)}_{s,t}
  +\frac12B^{q x}_{s,t}
  +\frac12B^{x q}_{s,t}.
\end{equation}
Moreover,
\begin{align}
 B^{q x}_{s,t}
 &=B^{q x}_{s,u}+B^{q x}_{u,t}+q_{s,u}\otimes x_{u,t},
 \\
 B^{x q}_{s,t}
 &=B^{x q}_{s,u}+B^{x q}_{u,t}+x_{s,u}\otimes q_{u,t}.

\end{align}
Thus the third-order coordinates are transported from the existing first- and
second-order channels and are derived restart coordinates of the step-two
state.

[Corollary BE2-cor of arXiv:2411.13788, '\bf Gradient bounds and Liouville property for a class of hypoelliptic diffusion via coupl'] Let $f\in C^1\left(\mathbb{R}^{m_0}\times\mathbb{R}^{m_1}\right)$ be a  globally Lipschitz function. Then for any $t\ge0$, $x^{(1)}\in \mathbb{R}^{m_0}, x^{(2)}\in\mathbb{R}^{m_1}$, we have
\begin{equation}
2\Gamma(P_tf)(x^{(1)},x^{(2)})\le P_t\left(\left\|\nabla^{(1)}f+tB_1\nabla^{(2)}f\right\|_{A_0}^2\right)(x^{(1)},x^{(2)}).
\end{equation}
and the following reverse inequality:
\begin{equation}
2P_t\left(\Gamma(f)\right)(x^{(1)},x^{(2)})\ge \left\|\nabla^{(1)}P_tf(x^{(1)},x^{(2)})-t B_1\nabla^{(2)}P_tf(x^{(1)},x^{(2)})\right\|_{A_0}^2.
\end{equation}

[Lemma lem.coarse_grained_VF0 of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given ${\scaleobj{1}{\square}}_m \in \mathcal{G}^{(N)}_k$, then the following estimates hold for every integer $0 \leqslant h \leqslant k-2$, and $1 \leqslant i = \vert F\vert \leqslant N$ with $F \subseteq E_d({\scaleobj{1}{\square}}_m)$, and every $\mathsf{r} \in (\frac{50}{27}, 2)$: 
		\begin{itemize}
			\item For every ${\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}}_m)$ and edge $e \cap {\scaleobj{1}{\square}} \neq \emptyset$, we have
			\begin{align}
				|\nabla V_m(F,0)(e)| \leqslant 2^{\vert F_\circ \vert} \sum_{e' \in \mathcal{E}(\mathscr{C}_{**}^F(\mathsf{r} {\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}_m))} |\nabla V_m(F_*,0)(e')|\Ind{F_\circ \subseteq E_d(\mathsf{r} {\scaleobj{1}{\square}})}.
			\end{align}
			\item There exists a finite positive constant $C(\mathsf{r},N,d,h,k)$, such that for every real number $\alpha > 0$, we have
			\begin{multline}
				\sum_{\substack{|F|=i\\F\subseteq E_d({\scaleobj{1}{\square}}_m)}}\sum_{\substack{{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}}_m)} }|{\scaleobj{1}{\square}}|^{\alpha} \sum_{e\in E_d\left(\mathsf{r}{\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}_m \right)} |\nabla V_m(F,0)(e)|^2 \\
				\leqslant C \sum_{i_1 = 0}^i \sum_{\substack{|F|=i_1\\F\subseteq E_d({\scaleobj{1}{\square}}_m)}}\sum_{\substack{{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h+1}({\scaleobj{1}{\square}}_m)} }|{\scaleobj{1}{\square}}|^{\alpha+4+i-i_1} \sum_{e\in \mathcal{E}\left(\mathscr{C}_{**}^{F}(\mathsf{r}{\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}_m)\right)} |\nabla V_m(F,0)(e)|^2. 
			\end{multline}
		\end{itemize}

