[Prop 15 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $\kappa>0$ and $\gamma >1$. Assume that $\bs{\eta}_N\in \R^N$ is such that

\begin{itemize}

\item[i)] $1- \frac{ \ln|P^\prime(\eta_k)| }{ \ln(2\veps_N) }  \, \geq \,  \kappa$ for all $k \in \intn{1}{N}$;

\item[ii)] $|\eta_a - \eta_b| \, \geq \, N^{-\ga}$ for all $a \neq b \in \intn{1}{N}$;

\item[iii)] $N^{\f{3}{2}} \vartheta_N \to 0$ as $N \to +\infty$.

\end{itemize}

 Let $\op{A}$ be as defined in \eqref{definition matrice A}. Then, there exists $N_0 \in \mathbb{N}$ such that, for all $N \geq N_0$, the following lower bound holds

\bem

\det_{N-1}[ \op{A} ] \, \geq  \,  | \ln(2\veps_N)|^{N-1} (1 - \mathrm{O}( N^{\f{3}{2}}  \vartheta_N)) \\

\times \prod_{j=1}^N  \Big( 1- \frac{ \ln|P^\prime(\eta_j)| }{\ln(2\veps_N)}    - \mathrm{O}\big( \frac{\ln N}{N}\big) - \mathrm{O}\big( N^{\f{3}{2}} \vartheta_N \big) \Big)^{1- \frac{1}{N}} \;.

\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm RT of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For $\mu > -\frac12$, define the fourth-order differential operator 
\begin{align} 
  {\mathfrak D}_{\mu}^{{\mathbb R} \rtimes \triangle} u: = \,& -\frac14 (1-|{\bm y}|)^3 \Delta_{{\bm x}}^2 + (1-|{\bm y}|) {\langle} {\bm x},\nabla_{\bm x}{\rangle} \Delta_{\bm x} 
   - ({\langle} {\bm x},\nabla_{\bm x}{\rangle} + {\langle} {\bm y},\nabla_{\bm y}{\rangle}) ^2  \\
   & +  \left(1+ \frac{1}{2} ({\kappa}_{d_2+1} + d_1)\right) \Delta_{\bm x} - 
     \sum_{i=1}^{d_2} \left[ y_i \partial_{y_i}^2 + ({\kappa}_i+1) \partial_{y_i} \right] \notag \\
    & + (|{\bm k}|+d_1+d_2) \big( {\langle} {\bm x},\nabla_{\bm x}{\rangle}+ {\langle} {\bm y},\nabla_{\bm y}{\rangle}\big). \notag
\end{align}
Then ${\mathcal V}_n({\mathbb R}^{d_1}  \rtimes \triangle^{d_2}, \bm W_{{\boldsymbol{\kappa}}}^{{\mathbb R} \rtimes \triangle})$ is an eigenspace 
of $ {\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb R} \rtimes \triangle}$ for each $n \in {\mathbb N}_0$. More precisely, 
\begin{align} 
  {\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb R} \rtimes \triangle} u =  - n (n+ |{\boldsymbol{\kappa}}|+  d_1 + d_2) u, \qquad 
         \forall u \in {\mathcal V}_n\big({\mathbb R}^{d_1}  \rtimes \triangle^{d_2}, \bm W_{\mu}^{{\mathbb R} \rtimes \triangle}\big).
\end{align}

[Lem 9 (Lemma 6.3, \cite{univ_euclidean}) of arXiv:2607.27535, 'Universal topological statistics on \\ triangulated singular spaces'] Let $K_\bullet$ be a filtered simplicial complex and let $\sigma$ be a simplex that enters $K_\bullet$ at some point. Then for every $\alpha$, following is true:
    \begin{align*}
        \big| \Pi_k(K_\bullet \backslash \sigma)(\alpha) - \Pi_k(K_\bullet)(\alpha) \big| \le \mathbf{1}[\dim(\sigma) \in \{k, k+1\}].
    \end{align*}
    where we abbreviate $\Pi_k(K_\bullet)(\alpha) = \big| \Pi_k(K_\bullet) \cap [\alpha, \infty) \big|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

