[Lemma 15 of arXiv:2607.26564, 'Stochastic Scalar Conservation Laws on Moving Hypersurfaces'] For any $\epsilon \in (0,1)$, let $u^\epsilon$ be the solution of equation \eqref{eq75}. Then $u^\epsilon$ satisfies the following moment estimate:
\begin{equation*}
\mathbb{E}[\sup_{t \in [0,T]}\| u^\epsilon(t)\|^2_{L^2(\Gamma_t)}] + \epsilon\mathbb{E}[\int_0^T\int_{\Gamma_t}|\nabla_{\Gamma_t}u^\epsilon(t,x)|^2\mathrm{dvol}_{\Gamma_t}(dx)dt]
\leq C,
\end{equation*}
where the positive constant $C$ does not depend on $\epsilon$.

[Proposition 2 of arXiv:2608.19576, 'Convex order preservation for graphon mean-field systems'] Assume that Assumption \ref{A:assump:1} is in force. 
    \begin{itemize}
        \item[\textup{(i)}] There exist $h_0, C > 0$ such that
        \begin{equation*}
            \sup_{u \in I}\mathbb{E}\Big[\big\|X^u\big\|_K^2\Big] \vee \sup_{h \in (0, h_0)} \sup_{u \in I}\mathbb{E}\Big[\big\|\bar{X}^{u,h}\big\|_K^2\Big] < C.
        \end{equation*}
        Moreover, there exists a constant $\kappa$ such that for any $h \in (0,h_0)$,
        \begin{equation*}
            \sup_{t \geq 0} \sup_{u \in I} \mathbb{E}\Big[\big|\bar{X}^{u,h}_t - \bar{X}^{u,h}_{[t]^h}\big|^2\Big] \leq \kappa (t-[t]^h) \leq \kappa h,
        \end{equation*}
        where we used the notation $[t]^h := \lfloor \frac{t}{h}\rfloor \cdot h$.

        \item[\textup{(ii)}] Recall $h_0 > 0$ defined in \textup{(i)}. Then, there exists $\gamma >0$ such that for any $h \in (0, h_0)$,
        \begin{equation*}
            \sup_{u \in I} \mathbb{E} \Big[\big\|X^u - \bar{X}^{u,h}\big\|_K^2\Big] \leq \gamma h^{1 \wedge 2\rho}.
        \end{equation*}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem resampling_is_positive of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] There exists a constant $g=g(p',R,M_0,c,\xi)>0$ such that for all percolation configurations $\omega$ on $B(x,n^{-1}R^{\kappa-f+1})$
\begin{equation}
    \mathbf{P}(E_\textrm{res} \, | \, \omega)\cdot \mathbf{1}_F(\omega)\geq g \cdot \mathbf{1}_F(\omega),
\end{equation}
whenever $\xi cR^{-f}n\geq R.$

[Lemma 16 of arXiv:2608.17509, '2608.17509'] Let \(a>1\). The limiting log-moment generating function \(\Lambda_a\) belongs to \(C^\infty(\mathbb{R})\), with
\[
\Lambda_a'(\theta)
=
\frac{1}{2\pi}
\int_0^{\infty}
\frac{e^{\theta}r_a(\xi)}
{1+(e^{\theta}-1)r_a(\xi)}
\,\mathrm{d}\xi,
\]
\[
\Lambda_a''(\theta)
=
\frac{1}{2\pi}
\int_0^{\infty}
\frac{e^{\theta}r_a(\xi)(1-r_a(\xi))}
{\left(1+(e^{\theta}-1)r_a(\xi)\right)^2}
\,\mathrm{d}\xi .
\]
Moreover, \(\Lambda_a\) is strictly increasing and strictly convex on \(\mathbb{R}\), and
\begin{equation}

\lim_{\theta\to-\infty}\Lambda_a'(\theta)=0,
\qquad
\lim_{\theta\to+\infty}\Lambda_a'(\theta)=+\infty.
\end{equation}
Consequently, the Legendre--Fenchel transform 
\(
\widetilde{J}_a(x):=\sup_{\theta\in\mathbb{R}}\{\theta x-\Lambda_a(\theta)\}
\)
is finite precisely on \([0,\infty)\), and \(J_a:=\widetilde{J}_a|_{[0,\infty)}\) is a good rate function on \([0,\infty)\).

