[Theorem t:DirInt of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Fix~$\pi\in\msP(\mbfT)$, and let~$\mbbV_\pi$ be any dense linear subspace of~$L^2(\pi)$.
The quadratic form~$\tparen{\widehat\boldsymbol\mssE_\pi,\mbbV_\pi\otimes \Cyl{}{}}$ defined by
\begin{align*}
\widehat\boldsymbol\mssE_\pi(\mbfu,\mbfv)\eqdef \sum_{i,j}^{m,n} \int_{\mbfT} \phi_i(\mbfs)\, \psi_j(\mbfs)\, \boldsymbol\mssE^\mbfs(u_i,v_j)\mathop{}\!\mathrm{d}\pi(\mbfs)\,\mathrm{,}\;\, \qquad \mbfu,\mbfv\in \mbbV_\pi \otimes \Cyl{}{}\,\mathrm{,}\;\, 
\end{align*}
is closable on~$L^2(\widehat\boldsymbol\nu_\pi)$ and its closure~$\big({\widehat\boldsymbol\mssE_\pi,\msD(\widehat\boldsymbol\mssE_\pi)}\big)$ is a Dirichlet form independent of~$\mbbV_\pi$.

Furthermore:
\begin{enumerate}[$(i)$]
\item the $L^2(\widehat\boldsymbol\nu_\pi)$-semigroup of~$\big({\widehat\boldsymbol\mssE_\pi,\msD(\widehat\boldsymbol\mssE_\pi)}\big)$ is the unique $L^2(\widehat\boldsymbol\nu_\pi)$-bounded linear extension~$\widehat\boldsymbol\mssH^\pi_\bullet$ of
\[
(\widehat\boldsymbol\mssH_\bullet\mbfu)(\mbfs,\mbfx) \eqdef \big({(\mssI\otimes \boldsymbol\mssH^\mbfs_\bullet) \mbfu}\big)(\mbfs,\mbfx) = \sum_i^m \phi_i(\mbfs)\, (\boldsymbol\mssH^\mbfs_\bullet u_i)(\mbfx) \quad \text{on}\quad \mbbV_\pi \otimes \Cyl{}{} \,\mathrm{;}\;\,
\]
\item the generator~$\big({\widehat\boldsymbol\mssL_\pi,\msD(\widehat\boldsymbol\mssL_\pi)}\big)$ of~$\big({\widehat\boldsymbol\mssE_\pi,\msD(\widehat\boldsymbol\mssE_\pi)}\big)$ is the unique $L^2(\widehat\boldsymbol\nu_\pi)$-self-adjoint (i.e.\ the $L^2(\widehat\boldsymbol\nu_\pi)$-Friedrichs) extension of the operator~$(\widehat\boldsymbol\mssL,\mbbV_\pi\otimes\Cyl{}{})$ defined by
\begin{equation}
(\widehat\boldsymbol\mssL \mbfu)(\mbfs,\mbfx)\eqdef \big({(\mssI\otimes \boldsymbol\mssL^\mbfs)\mbfu}\big)(\mbfs,\mbfx) = \sum_i^m \phi_i(\mbfs)\, (\boldsymbol\mssL^\mbfs u_i)(\mbfx) \quad \text{on}\quad \mbbV_\pi \otimes \Cyl{}{} \,\mathrm{.}
\end{equation}

\item $\big({\widehat\boldsymbol\mssE_\pi,\msD(\widehat\boldsymbol\mssE_\pi)}\big)$ admits carr\'e du champ operator~$\tparen{\widehat\boldsymbol{\mathsf{\Gamma}}_\pi,\dom{\widehat\boldsymbol{\mathsf{\Gamma}}_\pi}}$, the closure of the bilinear form~$(\widehat\boldsymbol{\mathsf{\Gamma}},\mcC_b(\mbfT)\otimes\Cyl{}{})$ defined by
\begin{equation}
\widehat\boldsymbol{\mathsf{\Gamma}}(\mbfu,\mbfv)\eqdef \widehat\boldsymbol\mssL(\mbfu\, \mbfv)-\mbfu\, \widehat\boldsymbol\mssL \mbfv -\mbfv\, \widehat\boldsymbol\mssL \mbfu\,\mathrm{,}\;\, \qquad \mbfu,\mbfv\in\mcC_b(\mbfT)\otimes\Cyl{}{}\,\mathrm{,}\;\,
\end{equation}

\item $\big({\widehat\boldsymbol\mssE_\pi,\msD(\widehat\boldsymbol\mssE_\pi)}\big)$ is $\widehat\tau_\mrmp$-quasi-regular and properly associated with a Hunt process~$\widehat\boldsymbol\mssW_\pi$ with state space~$\widehat\mbfM$;

\item a $\widehat\boldsymbol\nu_\pi$-measurable set~$\mbfA\subset \widehat\mbfM$ is $\widehat\boldsymbol\mssE_\pi$-invariant if and only if~$\mbfA\in \class[\widehat\boldsymbol\nu_\pi]{\mbfC\times\mbfM}$ for some Borel~$\mbfC\subset \mbfT$;

\item Assume each~$\boldsymbol\mssW^\mbfs$,~$\mbfs\in\mbfT$, is defined on a same measurable space~$(\Omega,\msF)$. Then,~$\widehat\boldsymbol\mssW_\pi$ can be realized as the stochastic process on~$\widehat\Omega\eqdef \boldsymbol\Omega\times \mbfT$ with~$\boldsymbol\Omega$ as in~(equation eq:r:StandardStochB:1 of the paper) and with trajectories and transition probabilities respectively given by
\begin{equation}
\widehat\mbfX^\pi_\bullet(\omega,\mbfs)\eqdef \big({\mbfs,\mbfX^\mbfs_\bullet(\omega)}\big) \quad\text{and} \quad \widehat P^\pi_{(\mbfs,\mbfx)}\eqdef P^\mbfs_\mbfx\,\mathrm{,}\;\, \qquad \mbfx\in\mbfM\,\mathrm{,}\;\, \mbfs\in\mbfT\,\mathrm{,}\;\,\omega\in\Omega \,\mathrm{;}\;\,
\end{equation}

\item
the process $\widehat\boldsymbol\mssW_\pi$ is the ---unique up to $\widehat\boldsymbol\nu_\pi$-equivalence--- $\widehat\boldsymbol\nu_\pi$-sub-stationary $\widehat\boldsymbol\nu_\pi$-special standard process solving the martingale problem for $(\widehat\boldsymbol\mssL_\pi,\mcC_b(\mbfT)\otime (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma SL_ineuqality of arXiv:2601.04997, 'Fluctuations of the Boundary-Driven Symmetric Zero-Range Process from the NESS'] For each $j=0, 1, 2$, the following holds. If $A\le \widetilde A$, then the sequences of eigenvalues $\{\gamma_n\}_n, \{\widetilde\gamma_n\}_n$ of $\textsc{SL}_j(A)$ and $\textsc{SL}_j(\widetilde A)$, respectively, satisfy $\gamma_{n-1}\le\widetilde\gamma_n$ for each $n\ge2$.

\begin{proof} Fix $j\in\{0, 1, 2\}$ and consider the differential equations on $(0, 1)$
\begin{equation*}
    \psi_n''(u)+A(u)^{-1}\widetilde \gamma_n \psi_n(u)=0 \quad \text{and} \quad \widetilde\psi_n''(u)+ \widetilde A(u)^{-1} \widetilde \gamma_n\widetilde\psi_n(u)=0.
\end{equation*}
Since $A(u)^{-1} \widetilde \gamma_n\ge \widetilde  A(u)^{-1} \widetilde \gamma_n $ for each $u\in(0, 1)$, by the Sturm Comparison Theorem~[br89], the number of zeroes of any solution to the first equation is at least the number of zeroes of any solution to the second one. Moreover, the same theorem implies that the number of zeroes of any solution to the differential equation
\begin{equation*}
    \psi_n''(u)+A(u)^{-1} \gamma \psi_n(u)=0
\end{equation*}
is a non-decreasing function of $\gamma$. But now, by~[br89], any eigenfunction $\psi_n$ of $\textsc{SL}_j(A)$ corresponding to $\gamma_n$ has exactly $n-1$ zeroes in the open interval $(0, 1)$. This completes the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 (Quantitative stability of the finite probe map) of arXiv:2608.14475, '\vspace{-1.2cm}\textbf{Finite Gaussian Reconstruction of Polynomial Orbits:\\ From Correla'] Let
\[
 V_{d,m}=\mathcal P_{d,m},
 \qquad
 N=\dim V_{d,m}=\binom{d+m}{m},
 \qquad
 D=r_*(d,m),
\]
and equip \(V_{d,m}\) with the \(O(d)\)-invariant tensor norm
\begin{equation}
 \|P\|_V^2
 =\sum_{k=0}^m\|T_k(P)\|_{\mathrm{HS}}^2.

\end{equation}
Define
\begin{align}
 \mathbf J_{d,m}(P)
 &=
 \bigl(M_{P,r}(\Sigma)\bigr)_{
  1\leq r\leq D,\ \Sigma\in\mathcal S_r},
 \\
 \delta_{\mathrm{orb}}(P,Q)
 &=
 \min_{U\in O(d)}\|Q-P\circ U\|_V,
 \\
 A_{d,m}
 &=
 D(6D-3)^{2N-1}.

\end{align}
There exists \(c_{d,m}>0\) such that, for every \(P,Q\in V_{d,m}\),
\begin{equation}
 \boxed{
 \|\mathbf J_{d,m}(P)-\mathbf J_{d,m}(Q)\|
 \geq
 c_{d,m}
 \left(
  \frac{\delta_{\mathrm{orb}}(P,Q)}
  {\sqrt2(1+\|P\|_V^2+\|Q\|_V^2)}
 \right)^{A_{d,m}}.}

\end{equation}
Consequently, on the ball \(\|P\|_V,\|Q\|_V\leq R\),
\begin{equation}
 \boxed{
 \delta_{\mathrm{orb}}(P,Q)
 \leq
 \sqrt2(1+2R^2)c_{d,m}^{-1/A_{d,m}}
 \mathfrak E_{\mathrm{probe}}(P,Q)^{1/(2A_{d,m})}.}

\end{equation}
There is also a constant \(L_{d,m,R}\) such that
\begin{equation}
 \sqrt{\mathfrak E_{\mathrm{probe}}(P,Q)}
 \leq
 L_{d,m,R}\delta_{\mathrm{orb}}(P,Q).

\end{equation}
Thus the quotient metric and the finite probe metric are globally
bi-H\"older on coefficient balls.  On the isolated-leading-part locus the same metric is obtained from the
finite jet of the Gaussian formal branch in
\cref{thm:normal-symbol-torelli}.  The exponent
\eqref{eq:explicit-stability-exponent} is explicit and deliberately
non-sharp; the constant \(c_{d,m}\) is not claimed in closed numerical
form.

[Lemma Lemma-KMTrate-200 of arXiv:2412.08932, 'Gaussian heat kernel asymptotics for conditioned random walks'] \ \\
1. There exists a constant $c >0$ such that, for any $n\geqslant 1$, $1\leqslant k \leqslant N_n$ and $x,u\geqslant 0$, 
\begin{align*}
\left| \mathbb{P} \left( \frac{x+S_{n-k}}{\sigma\sqrt{n}}  \leqslant u,  \tau_x > n-k \right) 
- \int_{0}^{u}  \psi \left(\frac{x}{\sigma\sqrt{n}} , y   \right)  dy  \right|  
\leqslant   c \left(n^{-\frac{\delta}{2(3+\delta)}} + \frac{N_n}{n}\right).
\end{align*}
\\
2. Moreover, there exists a constant $c >0$ such that, 
for any $n\geqslant 1$, $1\leqslant k \leqslant N_n$, $u\geqslant 0$, $a \in (0,1]$  and $x \geqslant \sigma a \sqrt{n}$, 
\begin{align*}
\left| \mathbb{P} \left( \frac{x+S_{n-k}}{\sigma\sqrt{n}}  \leqslant u,  \tau_x > n-k \right) 
- \int_{0}^{u}  \psi \left(\frac{x}{\sigma\sqrt{n}} , y   \right)  dy  \right|  
\leqslant \frac{c}{a} H \left( \frac{x}{\sigma\sqrt{n}} \right) \left(n^{-\frac{\delta}{2(3+\delta)}} + \frac{N_n}{n}\right).
\end{align*}

