[Theorem 5 of arXiv:2607.28004, 'Folding representations of reflected diffusions'] Let Assumption~\ref{ass:coefficients_Z} on the coefficients of the system \eqref{eq:RSDE_YZ} hold. Then:
    \begin{enumerate}[label = (\roman*),noitemsep]
        \item  For every $z \in E$, the function $f(\cdot,z)$ of \eqref{eq:f_Z} is the unique solution to the parameter-dependent nonlinear ODE \eqref{eq:ODE_Z}, where $\widehat \sigma(\cdot,z)$ is given by \eqref{eq:sigma_hat}. Moreover, $f$ is of class $C^1$, $f(\cdot,z)$ belongs to the class $W^{2,1}_{\mathrm{loc}}(I)$ for every $z \in E$, and $f(x,\cdot)$ is of class $C^2$ for every $x \in I$;
        \item  Consider the SDE system
        \begin{equation} 
        \begin{aligned}
            dX_t & = \alpha(X_t,Z_t)dt + dB_t + \sigma_X(X_t,Z_t)^\top d\overline W_t, \\
            dZ_t & = \overline b_Z(X_t,Z_t)dt + \overline \sigma_Z(X_t,Z_t)d\overline W_t,
        \end{aligned}
        \end{equation}
        where $\overline b_Z(x,z) = b_Z(f(|x|,z),z)$,  $\overline \sigma_Z (x,z) = \sigma_Z(f(|x|,z),z)$, $B$ and $\overline W$ are independent univariate and $m$-dimensional Brownian Motions respectively, and $\alpha$, $\sigma_X$ are given by \eqref{eq:alphaZ} and \eqref{eq:sigmaX} respectively. 
        This system has a globally defined weak solution, which is unique in law, for any initial values $(X_0,Z_0) = (x,z) \in \R \times E$;
        \item  The process $(Y,Z) = (f(|X|,Z),Z)$, with $(X,Z)$ as in \eqref{eq:SDE_system_halfline} and $f$ given by \eqref{eq:f_Z}, satisfies the RSDE system \eqref{eq:RSDE_YZ} on $I \times E$ with initial condition $(Y_0,Z_0) = (f(|X_0|,Z_0),Z_0)$, scalar Brownian Motion $W$ as in \eqref{eq:WZ}, and reflection term
        \begin{equation} 
            \Phi = \int_0^\cdot \sigma(0,Z_t)\sqrt{1-\|\rho(0,Z_t)\|^2}\, dL_t^0(X).
        \end{equation}    \end{enumerate}

[Cor eq:magique of arXiv:2506.01746, '\bf Optimal Bregman quantization: existence and uniqueness of optimal quantizers revisited'] If $x\!\in U^n$ is a stationary quantizer at level $n\ge 1$  (i.e. has pairwise distinct components with $P$-negligible Bregman--Voronoi boundary and  satisfies the $\phi_{_F}$-master equation~(equation eq:Mastereq of the paper)), then all induced quantizations $\widehat X$ are $\mathbb{P}$-$a.s.$ equal and
\begin{equation}
e_{2}(x, P,\phi_{_F})^2 = \mathbb{E} \, F(X)-\mathbb{E}\, F\big(\widehat X^{x}\big).
\end{equation}
In particular, if $x^{(n)}$ is an optimal $F$-Bregman quantizer then
 \begin{equation}
e_{2,n}(P,\phi_{_F})^2 = \mathbb{E} \, F(X)-\mathbb{E}\, F\big(\widehat X^{x^{(n)}}\big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

