\prod_{i=1}^{k} |\lambda_i(A)| &= \rho\big( C_k(A) \big) && \text{by \eqref{E:UIN-s1=norm-2b}}\\
&\leq \|C_k(A)\|_{\mathrm{op}} \\
&= s_1\big( C_k(A) \big) && \text{by \eqref{E:UIN-s1=norm-1}}\\
&= \prod_{j=1}^{k} s_j(A) && \text{by \eqref{E:UIN-s1=norm-3}}.
\end{align*}
Equality holds for $k=n$ since
\begin{equation*}
\prod_{i=1}^{n} |\lambda_i(A)| = |\det A| = \prod_{i=1}^{n} s_i(A).","release_manifest_digest":"sha256:a8aac13f8d080575ec6ebb3afcb7bae84ce96b4d5da26e20e29fbe82d670355b","revision_digest":"sha256:a6efae96f9de16f1870c06dd29e0dcb877e087cabc427d8fd9ce40b1cb187aaf","source_id":"arxiv:2609.02837","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

