[Lemma 14 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Assume that $\{\delta_{i}, 1\le i\le n \}$ and $\{\zeta_{i}, 1\le i\le n \}$ are two independent sequences of random variables, where $\delta_{i}\sim\textnormal{Bernoulli}(p_{i})$ are independent and $\zeta_{i}$ are independent centered $\alpha$-sub-exponential random variables.
       Let $a=(a_{1},\cdots, a_{n})$ be a  fixed vector. Then for $0<\alpha\le 1$ and $t\ge 0$
       \begin{align}
       	\mathbb{P}\Big\{\big\vert \sum_{i=1}^{n}a_{i}\delta_{i}\zeta_{i}\big\vert\ge t   \Big\}\le 2\exp\Big(-c(\alpha)\min\Big\{\frac{t^{2}}{L(\alpha)^{2}(\sum_{i}a_{i}^{2}p_{i})}, \Big(\frac{t}{L(\alpha)\Vert a\Vert_{\infty}}\Big)^{\alpha}  \Big\}   \Big),\nonumber
       \end{align}
   where $L(\alpha)=\max_{i}\Vert \zeta_{i}\Vert_{\Psi_{\alpha}}$ and $c(\alpha)$ is a positive constant depending only on $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 24 of arXiv:2606.20908, 'On It\^o-Stratonovich formula for rough sheets'] For a path $x\in \cp_{1,1}^{\ga_1,\ga_2}$, the tensor-like increment $\bx^{1i;2\otimes j}$, seen as an element of $\cac_2\bigl(\cac_2\otimes \cac_2\bigl)$, is defined by
\begin{equation}
\bx^{1i;2\otimes j}_{s_1s_2;t_1t_2;t_3t_4} := \int_{s_1<\sigma_1<\sigma_2<s_2}\Big(\int_{t_1}^{t_2}d_{12}x_{\sigma_1;\tau_1}\Big)\Big(\int_{t_3}^{t_4}d_{ij}x_{\sigma_2;\tau_2}\Big),
\end{equation}
where similarly to Hypothesis~\ref{hyp:rs2}, we interpret the right hand side of~\eqref{E:x^(1i;2xj)} in the geometric sense.

[Lem 5 of arXiv:2603.29549, 'Multitype PCR branching processes'] The function $\bar F$ has a continuous inverse on $\Real_+^d$. The subset 
\begin{equation}
\Gamma = \big\{\bar x\in \Real_+^d: x_{d_0+1}=...=x_d=0\big\}
\end{equation}
is both backward and forward invariant with respect to $\bar F$. The restriction of the inverse to $\Gamma$ admits the formula:
\begin{equation}
\bar F^{-1}(\bar y) = \frac {f^{-1}(y)}{y}\bar y, \quad \bar y\in \Gamma.
\end{equation}

[Lemma 18 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $H \subset V$ with $|H| \leq 3$. Then, there exists $ K_{uu'} \geq 0$ for every $u,u' \in H$, $r_{u} > 0$ for each $u \in H$ and a constant $Z > 0$ such that
	\begin{equation}
		\left< \vp(A) \right>_{G} = \Big( \prod_{u \in A} r_u  \Big) \frac{1}{Z}\sum_{ \sigma \in \left\{ \pm 1 \right\}^H} \sigma(A) \exp\Big( \sum_{u,u' \in H} K_{uu'} \sigma_u \sigma_{u'} \Big) \quad \text{ for any $A \subset H$.}
	\end{equation} 
	Moreover, we may choose $r_u = 1$ for any $u \in H \cap \Vis$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RandomWalkBound of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $\alpha > 0$ be a constant and let $N \in \mathbb{N}$ with $N/2 \geqslant \alpha$. Let $(Z_t)_{t \geqslant 0}$ be a rate $1$ simple random walk on $[N]$ with a bias of $\alpha/N$ to the right with reflection, i.e., 
    \begin{equation*}
        \cP{Z_t = y}{Z_{t_{-}} = x} = \begin{cases}
            \frac{1}{2} + \frac{\alpha}{N} & \text{ if } y = x + 1 \text{ and } x < N \text{ or } x = y = N,  \\
            \frac{1}{2} - \frac{\alpha}{N} & \text{ if } y = x - 1 \text{ and } x > 1 \text{ or } x = y = 1, 
        \end{cases}
    \end{equation*}
    for all $x \in [N]$, for a jump at time $t$. For $x \in [N]$, let $\tau_{x}$ denote the first time when the walker $(Z_t)$ reaches site $x$. Then there exists some universal constants $c_0, \varepsilon_0 > 0$ such that for all $\varepsilon \in (0, \varepsilon_0)$,
    \begin{equation}
        \cP{\tau_N \leqslant \varepsilon N^2/\alpha}{Z_0 = 1} \leqslant \Exp{-c_0 \alpha \varepsilon^{-1}}
    \end{equation}
    for all $N$ sufficiently large.

