body:
[Corollary 4 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] There are absolute constants $K_0,c,C>0$ such that the following holds.
Let $0<s\le c\sqrt n$ and assume
$\mathcal I_{n,d}(s)\ge1$. Then there are independent centered,
variance-one coordinates with $\psi_2$ norm at most $K_0$ and a convex
one-Lipschitz function $f$ such that, for every $m\in\R$,
\begin{equation}
 \Pp\left\{
 \abs{f(X^{\otimes d})-m}
 \ge c n^{(d-1)/2}s
 \right\}
 \ge\exp\big(-C\mathcal I_{n,d}(s)\big).
\end{equation}

[Definition of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] The tame Fréchet space bundles ${\mathbf{E}}_{00}$ and ${\mathbf{F}}_{00}$ defined in (Prop_BundleOfAdmissibleZModTwoZSpinors of the paper) decompose into
  \begin{equation*}
    {\mathbf{E}}_{00} = {\mathbf{E}}_{00}^+ \oplus   {\mathbf{E}}_{00}^-
    \quad\text{and}\quad
    {\mathbf{F}}_{00} =   {\mathbf{F}}_{00}^+ \oplus {\mathbf{F}}_{00}^-.
  \end{equation*}
  with ${\mathbf{E}}_{00}^\pm$ denoting the \defined{universal bundle of admissible chiral $\mathbb{Z}/2\mathbb{Z}$ spinors}.
  The latter contains the open subset
  \begin{equation*}
    {\mathbf{E}}_{00}^{\pm,*} \subseteq {\mathbf{E}}_{00}^\pm
  \end{equation*}
  of \defined{non-degenerate} admissible chiral $\mathbb{Z}/2\mathbb{Z}$ spinors.
  For every $({\mathbf{p}},[{\mathfrak l}];\Phi) \in  {\mathbf{E}}_{00}^{\pm,*}$,
  the map ${\mathbf{L}}_\Phi$ constructed in (Prop_AdmissibleZ2ZSpinor_LeadingOrderTerm of the paper) corestricts to
  \begin{equation*}
    {\mathbf{L}}_\Phi^\pm \in \Gamma\paren{Z,\Hom_\mathbb{A}(\overline{NZ},\check S_{\mathbf{p}}^\pm)}. 
  \end{equation*}
  The images define a family of local chiral residue conditions
  \begin{equation*}
    ({\mathbf{E}}_{00}^{\pm,*},f,{\mathbf{V}}^\pm).
  \end{equation*}
  If $\rk_\mathbb{A}\check S^\pm = 2$, this family satisfies the hypothesis of (Prop_TotallyReal=>UniformlyFredholm_Chiral of the paper).

[Def 43 (Backbone exploration) of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $x,y\in V_ g$. Let $
\in \Omega_{G_{ g}}$ with $\sn=\{x,y\}$. The backbone of $
$, denoted by $\Gamma(
)$, is the unique oriented and edge self-avoiding path from $x$ to $y$, supported on edges $uv$ with $
_{uv}$ odd, and which is minimal for $\prec$. The backbone $\Gamma(
)=\{x_ix_{i+1}:  0\leq i < k\}$ is obtained via the following procedure:
 egin{enumerate}
    \item[$(i)$] Set $x_0=x$. The first edge $x_0x_1$ of $\Gamma(
)$ is the earliest of all the edges $e$ emerging from $x_0$ for which $
_e$ is odd.
    All edges $e$ containing $x_0$ and satisfying $e\prec x_0x_1$ and $e
eq x_0x_1$ are called \emph{explored} and have $
_e$ even.
    \item[$(ii)$] Each edge $x_ix_{i+1}$ with $i\ge 1$ is the earliest of all edges $e$ emerging from $x_i$ that have not been explored previously, and for which $
_e$ is odd.
    \item[$(iii)$] The exploration stops when it reaches $y=x_k$ for the first time.
\end{enumerate}
Let $\overline{\Gamma}(
)$ denote the set of explored edges, i.e. $\Gamma(
)$ together with all explored even edges.

[Theorem 2 of arXiv:2609.02801, 'Ratio and limiting zero distribution asymptotics for symmetric multiple orthogonal polynom'] If   \( \Gt (z) \) is the Stieltjes transform of the zero limiting distribution 
of the rescaled polynomial sequence \((Q_n(z))_{n\geq 0} \), then one has  
\begin{equation}   
  \Gt (z) 
   = - \frac{1}{r} \int_0^1 \frac{\displaystyle \partial_z \Phi(z,t) }{\Phi(z,t)} \, \mathrm{d}t , 
\end{equation}
uniformly on compact sets of $\mathbb{C} \setminus \Sigma$, where \(\Phi(z,t)\) is given by  \eqref{eq:ratio}-\eqref{eq:6} and such that $z^r\Phi(z,t) \to 1$ as $z \to \infty$. Moreover, we have 
\begin{align}
	\Gt (z) 
	&= - \frac{1}{r\,z}  
	\left( 1- \frac{(r+1)}{\gamma} \frac{1}{\left(F(y) A_r(F(y))\right)^{\frac{1}{\gamma}}} \int_0^{F(y)}  \left(u \, A_r(u)\right) ^{1/\gamma}	\frac{1}{u}\mathrm{d}u  \right), 
\end{align}
with  \(y=z^{r+1}\), with  \(A_r\) and \(F\) as in \eqref{eqF}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 6 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Let $\Lambda>3$. There exist positive constants $c_{\Lambda}$ and $c$, where $c_{\Lambda}$ depends only on $\Lambda$ (and $d$), such that
    \begin{align*}
        c_{\Lambda}r^{-2}\le \bP[0 \leftrightarrow Q_{z,r}]\le cr^{-2},\qquad \forall z\in Q_{0,\Lambda r}\setminus Q_{0,3r}.
    \end{align*}

