body:
[Lemma lem:localenergy of arXiv:2602.05477, 'On the Resistance Conjecture'] If $\Omega\subset X$ is open, then the following hold.
    \begin{enumerate}  
			\item \textbf{Homogeneity:} For every $f\in \mathcal{F}_{p,\loc}(\Omega)$ there exists a finite non-negative Borel measure $\Gamma_p \langle f \rangle$ on $\Omega$ and for all $\lambda \in \mathbb{R}$
			\[
			\Gamma_p\langle \lambda f\rangle = |\lambda|^p \Gamma_p\langle f\rangle.
			\]
			\item \textbf{Triangle inequality:} For every $f,g\in \mathcal{F}_{p,\loc}(\Omega)$ and every Borel set $A\subset \Omega$, 
			\begin{equation} 
				\Gamma_p\langle f+g\rangle(A)^{\frac{1}{p}}\le \Gamma_p\langle f\rangle(A)^{\frac{1}{p}}+\Gamma_p\langle g\rangle(A)^{\frac{1}{p}}
			\end{equation}
            \item \textbf{Addition of constant:} For all $f\in \mathcal{F}_{p,\loc}(\Omega)$ and $c\in \mathbb{R}$ we have $f+c\in \mathcal{F}_{p,\loc}(\Omega)$ and $\Gamma_p\langle f\rangle=\Gamma_p\langle f+c\rangle$.
			\item \textbf{Lipschitz contractivity:} For all $f\in \mathcal{F}_{p,\loc}(\Omega)$ and $g\in \Lip(\mathbb{R})$,  we have $g \circ f \in \mathcal{F}_{p,\loc}(\Omega)$ and
			\begin{equation} 
				d\Gamma_p\langle g\circ f\rangle \le \LIP[g]^p d\Gamma_p\langle f\rangle.
			\end{equation}
			\item \textbf{Strong locality:} For every $f\in \mathcal{F}_{p,\loc}(\Omega)$ and any open set $A\subset \Omega$, if $f|_\Omega=c$ $\mu$-a.e., then $\Gamma_p\langle f\rangle(A)=0$. 
		\end{enumerate}

[Corollary 6 (Finite and Euclidean latent spaces for the unnormalized recursion) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose the hypotheses of Theorem~\ref{thm:unnormalized_rate} hold.  In each of the following cases, the
displayed bound holds simultaneously for all $n\ge 16\alpha_{\mrm U}$ on an event of probability at least
$1-\delta$.
\begin{enumerate}[label=(\roman*)]
\item If $\mbb L$ is finite with cardinality $J$ and is equipped with the discrete metric, then
\[\norm{\theta_n^{\mrm U}-\theta^*}
        \le
        \frac{3}{1-\gamma}
        \sqbk{\frac{17n_0^{\mrm U}}{n+n_0^{\mrm U}}}^{\lambda_{\mrm U}} 
        +\frac{328\tmix}{c_\wedge(1-\gamma)^2}
        \sqbk{
        \sqrt{\frac{\alpha_{\mrm U}(\cL_n^{\mrm U}(\delta)+\log J)}{n+n_0^{\mrm U}}}
        +
        \frac{\alpha_{\mrm U}^{2}}{(\lambda_{\mrm U}-1)(n+n_0^{\mrm U})}
        }.\]

\item Suppose there are constants $\cD\ge0$ and $d_{\mbb L}\ge1$ such that for all $\epsilon>0$
\begin{equation}
        \cN_\rho(\veps)
        \le
        \crbk{1+\frac{\cD}{\epsilon}}^{d_{\mbb L}}. 
\end{equation}
Then\[
        \norm{\theta_n^{\mrm U}-\theta^*}\le
        \frac{3}{1-\gamma}
        \sqbk{\frac{17n_0^{\mrm U}}{n+n_0^{\mrm U}}}^{\lambda_{\mrm U}}+
        \frac{328\tmix}{c_\wedge(1-\gamma)^2}
        \sqbk{
        \sqrt{
        \frac{
        \alpha_{\mrm U}(\cL_n^{\mrm U}(\delta)
        +d_{\mbb L}\log\!\crbk{1+\cD/\epsilon_n^{\mrm U}})}
        {n+n_0^{\mrm U}}}
        +
        \frac{\alpha_{\mrm U}^{2}}{(\lambda_{\mrm U}-1)(n+n_0^{\mrm U})}
        }.\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

