[Lemma lem:fine-relative-triangulation of arXiv:2608.15923, 'Universality of two-dimensional Markovian holonomy fields'] Let $K$ be a finite piecewise-smooth graph embedded in $\Sigma$, containing $o$ and carrying $\partial\Sigma$. For every $\varepsilon>0$, there exists a smooth triangulation $\mathcal T$ of $\Sigma$ such that:
\begin{enumerate}
\item $K$ and $\partial\Sigma$ are subcomplexes of $\mathcal T$;
\item every edge of $\mathcal T$ has length at most $\varepsilon$;
\item every two-simplex of $\mathcal T$ has diameter at most $\varepsilon$.
\end{enumerate}

[Thm 5 (Sharp function-field surjection moments) of arXiv:2609.01413, 'Sharp Threshold for Universality of Rational Canonical Forms over a Finite Field'] Let $(\alpha_n)_{n\geq1}$ satisfy
    \begin{equation}

        \liminf_{n\to\infty}
        \frac{n\alpha_n}{\log n}>1,
    \end{equation}
    and let $A_n\in\Mat_n(\F_p)$ be an $\alpha_n$-balanced random
    matrix. Then, for every fixed finite $\F_p[t]$-module $G$,
    \begin{equation}

        \lim_{n\to\infty}
        \E\#
        \Sur_{\F_p[t]}(X_n,G)
        =
        1.
    \end{equation}

[Lemma l:m1 of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Let $\mu$ be a spectral measure with density in $C^2(\mathbb{R}^d)$ such that $\|\mathcal{F}[\mu]\|_{L_1(\mathbb{Z}^d)} < \infty$. Let $\rho$ be a signed measure with Jordan decomposition $\rho = \rho_+ - \rho_-$, and assume that $\mu+\rho \ge 0$. Then there exist positive constants $T_0=T_0(\rho)$, $c_1=c_1(d)$ and $c_2=c_2(d)$, such that, for all $\beta \in [0,d)$, $\varepsilon<\|\mu\|$, and $T>T_0$,
\begin{align}

&  \mathbb{P} \Big[ \inf_{x \in B(T)} f_{\mu+\rho}(x) \ge - \sqrt{2 (\|\mu\|-\varepsilon) ( d - \beta)   \log T} \Big] \\
& \nonumber  \qquad \qquad \qquad \le 2 \exp \Big( \tfrac{-  c_1 \|\mu\|}{ \|\mathcal{F}[\mu]\|_{L^1(\mathbb{Z}^d)}}T^{\beta + \frac{\varepsilon}{\|\mu\|}(d-\beta) -c_2 \sqrt{\frac{\|\rho_{-}\|}{\|\mu\|}}}  \Big)  + e^{-e^{T^{c_1}}} .
\end{align}
Moreover, if $\int_{\mathbb{R}^d} |\lambda|^2 d\rho_-(\lambda) \le q < \infty$, then (equation e:m15 of the paper) holds for  constants $T_0$ and $c_2$ chosen to depend only on $q$ and $d$.

