[Theorem 1 of arXiv:2609.02711, 'Differentiability of the Leading Lyapunov Exponent \\ of a linear differential equation wi'] Under Hypothesis  \ref{hyp:un},
  for all $z$, there exists a measurable
set $\tilde{\Omega}_z$ such that $\prob{\tilde{\Omega}_z} = 1$, a real
number $\Lambda(z)$

and two random variables $U_z, V_z$ with values in $\rdpp$, such that for all $\omega \in \tilde{\Omega}_z$:
\begin{enumerate}
  \item $1 = \valabs{U_z(\omega)} = \crochet{V_z(\omega), U_z(\omega)}$.
  \item $\Lambda(z)$ is the leading Lyapunov exponent of the differential equation
  \begin{equation}
    \frac{dy}{dt} = A(z, \omega_t) y(t),
  \end{equation}
  and we have the integral formula
  \begin{equation}
    \Lambda(z) = \esp{\crochet{A(z, \omega_0) U_z, \vun}}.
  \end{equation}

    \item The function $z \to \Lambda(z)$ is differentiable almost
    everywhere on $(a, b)$ with derivative
  \begin{equation}
    \Lambda'(z) = \esp{\crochet{\partial_z A(z, \omega_0) U_z, V_z}}.
  \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 ({cf.,e.g.,\cite[Lemma~1.1) of arXiv:2604.21389, 'Existence and uniqueness for \\ singular stochastic differential equations \\ with piecewi'] {le2006one}~\cite[Lemma IX.3.3]{revuz2013continuous}}]

Let $\epsilon>0$ be fixed and assume that $X$ is a continuous semimartingale such that for every $t>0$:
\begin{equation}
\int_0^t \frac{\mathds{1}_{(0,\epsilon)}(X_s)}{\varrho(X_s)}\vd\langle X,X\rangle_s <\infty \quad \mathbb{P}-\text{a.s.}

\end{equation}
for a measurable function $\varrho \colon (0,\infty) \to (0,\infty)$ such that $\int_0^{\epsilon} 1/\varrho(x) \vd x =+\infty$.
Then the right local time $\ell_\cdot^0(X)=0$ $\mathbb{P}$-a.s.. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:main1 of arXiv:2511.08479, '\Large From disordered systems to the Critical 2D Stochastic Heat Flow'] The Critical 2D SHF $(\mathscr{Z}_{s,t}^{\vartheta}(\mathrm{d} x , \mathrm{d} y))_{0 \le s \le t <\infty}$ is translation invariant in law:
\begin{equation*}
	(\mathscr{Z}_{s+\mathsf{a}, t+\mathsf{a}}^\vartheta(\mathrm{d} (x+\mathsf{b}) , \mathrm{d} (y+\mathsf{b})))_{0 \le s \le t <\infty}
	\stackrel{\rm dist}{=}
	(\mathscr{Z}_{s,t}^{\vartheta}(\mathrm{d} x , \mathrm{d} y))_{0 \le s \le t <\infty}
	\quad \ \forall \mathsf{a} \ge 0, \ \forall \mathsf{b} \in \mathbb{R}^2 \,,
\end{equation*}
and it satisfies the following scaling relation:
\begin{equation}
	(\mathscr{Z}_{\mathsf{a} s, \mathsf{a} t}^\vartheta(\mathrm{d} (\sqrt{\mathsf{a}} x) , \mathrm{d} (\sqrt{\mathsf{a}} y)))_{0 \le s \le t <\infty}
	\stackrel{\rm dist}{=}
	(\mathsf{a}\, \mathscr{Z}_{s,t}^{\vartheta+ \log \mathsf{a}}(\mathrm{d} x , \mathrm{d} y))_{0 \le s \le t <\infty}
	\quad \ \forall \mathsf{a} > 0 \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

