[Definition eq:general_OU of arXiv:2601.04997, 'Fluctuations of the Boundary-Driven Symmetric Zero-Range Process from the NESS'] Let $\mathfrak{A}_\theta:\mathcal{S}_\theta\to\mathcal{S}_\theta$, $\mathfrak{B}_\theta:\mathcal{S}_\theta\to L^{2, \theta}([0, 1])$ {and let $\{\mathscr{W}_t, t\in[0, T]\}$ be an $\mathcal{S}_\theta'$-valued Brownian motion.} We say that an $\mathcal{S}_\theta'$-valued stochastic process $\{\mathscr{Y}_t, t\in[0, T]\}$ with continuous trajectories is a \textit{solution to the generalised Ornstein-Uhlenbeck equation}
\begin{equation}
    \partial_t\mathscr{Y}_t=\mathfrak{A}_\theta \mathscr{Y}_t +\mathfrak{B}_\theta \mathscr{\dot W}_t
\end{equation}
if, for any $H\in\mathcal{S}_\theta$,
the processes $\{\mathscr{M}_t(H), t\in[0, T]\}$ and $\{\mathscr{N}_t(H), t\in[0, T]\}$ defined by
\begin{align}
    &\mathscr{M}_t(H):=\mathscr{Y}_t(H)-\mathscr{Y}_0(H)-\int_0^t\mathscr{Y}_s(\mathfrak{A}_\theta H)\de s,
    \\&\mathscr{N}_t(H):=\mathscr{M}_t(H)^2-t\|\mathfrak{B}_\theta H\|_{L^{2, \theta}}^2\nonumber
\end{align}
are $\mathcal{F}_t$-martingales, where $\mathcal{F}_t:=\sigma\{\mathscr{Y}_s(H): s\le t, H\in\mathcal{S}_\theta\}$.

[Lemma 4 (\citeauthor{F10}, \citeyear{F10}, Eq.~(5.101)) of arXiv:2606.06739, 'The relationship between the transition functions of the labeled and unlabeled versions of'] For $\bm m=(m_1,\ldots,m_k)$ with $m_1\ge\cdots\ge m_k\ge1$, $\bm n=(n_1,\ldots,n_l)$ with $n_1\ge\cdots\ge n_l\ge1$, $k,l\in{\bf N}$, $m=|\bm m|$, and $n=|\bm n|$,
\begin{align}
\frac{\int_{\overline{\nabla}_\infty}P_{\bm m}P_{\bm n}\,d\text{PD}_\theta}{\int_{\overline{\nabla}_\infty}P_{\bm n}\,d\text{PD}_\theta}
&=C(\bm m)\sum_{r=0}^{k\wedge l}\bigg[\sum_{\substack{I\subset\{1,\ldots,k\}:\\ |I|=r}}\;\sum_{\substack{\gamma:I\mapsto\{1,\ldots,l\}\\ \text{\rm one-to-one}}}\nonumber\\
&\quad\;{}\dfrac{\prod_{i\in I}(m_i+n_{\gamma(i)}-1)!\,\prod_{i\in I^c}(m_i-1)!}{\prod_{i\in I}(n_{\gamma(i)}-1)!}\bigg]\frac{\theta^{k-r}}{(n+\theta)_{(m)}},
\end{align}
where $I^c:=\{1,\ldots,k\}-I$.

