body:
[Theorem 19 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $\xi$ be a boundedly exchangeable graph process on $S$ directed by $\nu$. For every $B \in \widehat{\Bcal}(S)$ where $\pbb(\nu(B) = 0) < 1$ there exists an infinite jointly exchangeable matrix $A^B \in \rbb^{\nbb \times \nbb}$ such that the adjacency matrix $(A, N)$ of any i.i.d.\ representation of $\xi\vert_B$ satisfies for all $n \geq 1$:
    \begin{equation} 
        A \mid (N = n) \overset{d}{=} A^B[n]
    \end{equation}
    Moreover, the distribution of $A^B$ is unique.

[Lemma 19 (Hodge a priori estimates: null-form rhs) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] Let $\Ufield,\Vfield$ be as above, recall $\sigma=s-1>(n-1)/2$, and let
$F[\Ufield]$ be the canonical Hodge representative \eqref{eq:FU}.  Then $F[\Ufield]\in C(I;L^4)$, with
\begin{equation}
 \|F[\Ufield]\|_{L^\infty(I;L^4)}\le C_\delta R^2 ,
\end{equation}
and, for every $\rpar\in[0,1]$ such that
$\Ufield\in H^{\sigma,1+\rpar}_{\breg}$,
\begin{equation}
 \|dF[\Ufield]\|_{L^2(I;Y^{\sigma,\rpar})}
 \le C_{\delta,\rpar} 
 \|\Ufield\|_{H^{\sigma,1}_{\breg}} 
 \|\Ufield\|_{H^{\sigma,1+\rpar}_{\breg}} .
\end{equation}
In particular at $\rpar=0$,
\begin{equation}
 \|dF[\Ufield]\|_{L^2(I;H^\sigma)}\le C_\delta R^2 .
\end{equation}
Finally,
\begin{equation}
 \|dF[\Ufield]-dF[\Vfield]\|_{L^2(I;H^\sigma)}
 \le C_\delta R(1+R) D .
\end{equation}

[Theorem DPP-path-stoch of arXiv:2412.05698, 'Controlled rough SDEs, pathwise stochastic control and dynamic programming principles'] Suppose that  (assum-path-stoch of the paper) holds. Then, for any $y \in \mathbb{R}^{d_Y}$,  $s\in[0,T]$, 
$h\in[0,T-s]$ and $i=1,2$, 

\begin{equation}
\bar{\mathcal{V}}(s,y;\omega)= {\ensuremath{\operatorname{essinf}}_{\eta \in \mathcal{A}^i}}\ \mathbb{E}[ \bar{\mathcal{V}}(s+h, \bar{Y}^{s,y,\bar{\eta}}_{s+h}; \cdot) \mid {\mathfrak F}^{\mathbf{W}}_T] (\omega) \quad\text{a.e. } \omega,
\end{equation}
where the left-hand side is continuous on $[0,T]\times \mathbb{R}^{d_Y}$ a.s. as in Theorem (rep-value-fct of the paper).

[Theorem eqn|UFirstElements of arXiv:2504.08938, 'Fourier Levels and Almost Sure Bounds on Higher-Order Derivatives in First-Passage Percola'] The first four elements of the sequence $\left(\mathcal U_n\right)$ and the first three elements of the sequence $\left(\mathcal L_n\right)$ are 
\begin{eqnarray}
\left(\mathcal U_1,\mathcal U_2, \mathcal U_3, \mathcal U_4\right)&=&(1,1,1,2);
\\
\left(\mathcal L_1,\mathcal L_2, \mathcal L_3,\mathcal L_4\right)&=&(0,-1,-1,-2).

\end{eqnarray}

[Definition 1 (Tempered fractional Brownian motion
\cite{MeerschaertSabzikar2013}) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] For $H \in (0,1)$ and $\lambda > 0$, the \emph{tempered fractional
Brownian motion} (tfBm)
$B_{H,\lambda} = (B_{H,\lambda}(t))_{t \ge 0}$ is the centred
Gaussian process defined by
\begin{equation}

B_{H,\lambda}(t) = \frac{1}{\Gamma(H+\frac{1}{2})} \int_{\mathbb{R}}
\Bigl[ e^{-\lambda(t-s)_+}(t-s)_+^{H-\frac{1}{2}}
      - e^{-\lambda(-s)_+}(-s)_+^{H-\frac{1}{2}} \Bigr] \, dW(s),
\end{equation}
where $W$ is a standard two-sided Brownian motion and
$x_+ = \max(x,0)$.

[Theorem 3 (Reduction; conditional on Hypothesis~\ref{hyp:red}) of arXiv:2608.15987, 'Threshold cascades of interacting diffusions on unimodular random trees: a conditional bra'] Under Hypothesis~\ref{hyp:red}, the failed cluster of the root converges in distribution (as a random rooted tree) to the family tree of the multitype Galton--Watson process on type set $D$ with mean matrix
\begin{equation}
M_{d,d'}=m_*\,q(d')\,p_{d,d'},\qquad d,d'\in D,
\end{equation}
where $p_{d,d'}$ is the transmission probability \eqref{eq:wald}. In particular the survival probability of the cascade is positive iff $\rho(M)>1$, and zero iff $\rho(M)\le1$, where $\rho(M)$ is the Perron root of the nonnegative matrix $M$.

[Lem setup2 of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Let $H\in \mathcal{H}$ be connected and let $\eps \leq \alpha \leq 1$ be real. We get $\abs{\sete[e^{if}]} = n^{-\omega_{\lambda,\ell,\eps}(1)}$ as long as
\begin{cond}
    \item  $n^{-\alpha+\eps} \leq \Delta_H^2 \leq 1.1\pi^2 (p(1-p))^{e(H)}$;
    \item  For any graph $H' \succ H$, we have $n^{v(H')} \Delta_{H'}^2 < n^{v(H)- \alpha - \eps}$.
\end{cond}

[Corollary cor:smallpmode of arXiv:2608.11378, 'On the most likely geodesic in last passage percolation'] There is $p_{n} > 0$ such that if $\omega_x \sim \mathrm{Ber}(p)$ with $0 < p \le p_n$, then for any path $\gamma$,
    \begin{equation*}
        \mathbb{P}(\gamma^{\raisebox{-0.5ex}{$\scriptstyle\ulcorner$}} \in \Gamma^*_n ) \ge \mathbb{P}(\gamma \in \Gamma^*_n).
    \end{equation*}
    This inequality is strict unless $\gamma \in \set{\gamma^{\raisebox{-0.5ex}{$\scriptstyle\ulcorner$}}, \gamma^{\raisebox{-0.5ex}{$\scriptstyle\lrcorner$}}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2608.29976, 'The Pego Theorem for the Hilbert--Schmidt Class'] Let $1\le p\le 2$ and  $F\subset\mathcal{T}^p(\mathcal{H})$. We say that $F$ is
uniformly $\mathcal{T}^p$-equicontinuous if for every $\varepsilon>0$, there is
an open neighbourhood $V$ of $0\in\Xi$ such that
\begin{equation*}
\|\alpha_x(A)-A\|_{\mathcal{T}^p} < \varepsilon, \quad \text{for all } A\in F,\ x\in V.
\end{equation*}

[Theorem glue_characterisation of arXiv:2608.13716, 'Graph Causal Optimal Transport \\ and Wasserstein Distances'] For a DAG $G$, the following are equivalent:
    \begin{enumerate}
        \item $G$ has the causal gluing property;
        \item $G$ has the bicausal gluing property;
        \item $G$ is transitively closed and has no splits.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:convergence_p_D/t of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] For $x,y>0$,
\begin{align*}
    \lim_{t\to 0^+} \frac{p_t^D(x,y)}{t} = \nu(x,y).
\end{align*}

