[Definition def:weighted-minimal of arXiv:2609.02234, 'An $n(\log n)^{o(1)}$ bound for nested cycles without geometric crossings'] Let $K>0$. An $n$-vertex graph $G$ is \emph{$K$-minimal} if $e(G)>K\Phi(n)$ and every nonempty proper $W\subset V(G)$ satisfies
\begin{equation}
  e(G[W])\le K\Phi(|W|).
\end{equation}

[Thm limmild of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] Assume that either Hypotheses (Hyp1C of the paper) or Hypotheses (Hyp2L of the paper) holds. For every $x\in H$ and $T>0$ there exists a unique $H$-valued càdlàg process $\{X(t,x)\}_{t\in [0,T]}$ such that for every $\{x_n\}_{n\in{\mathbb N}}\subseteq E$ converging to $x$ we have
\begin{align}
&\lim_{n{\rightarrow}+\infty}\sup_{t\in [0,T]}{\left|X(\cdot,x_n)-X(\cdot,x)\right|}_{H}=0,\qquad \mathbb{P}-{\rm a.s.},
\end{align}
where $\{X(t,x_n)\}_{t\in [0,T]}$ is the unique mild solution of (equation eqFO of the paper) with initial datum $x_n$. In addition for every $t\in [0,T]$ and $x,z\in {H}$ we have
{\small
\begin{align}
&{\left|X(t,x)\right|}_{H}\leq e^{\zeta t}{\left|x\right|}_{H}+\int_0^te^{\zeta (t-s)}\left({\left|F(Z_A(s))\right|}_{H}+2\max\{0,\zeta\}{\left|Z_A(s)\right|}_{H}\right)ds+|Z_A(t)|_H,\;\;\mathbb{P}{\rm-a.s.}\\
&{\left|X(t,x)-X(t,z)\right|}_{H}\leq  e^{\zeta t}{\left|x-z\right|}_{H},\;\;\mathbb{P}{\rm-a.s.},
\end{align}
}
where $\zeta$ is the constant defined in (equation zeta of the paper).

[Theorem 1 of arXiv:2605.07184, 'Convergence of Stochastic Gradient Descent with mini-batching and infinite variance'] Let
  \Cref{assumption:function_H,
    assumption:regvar-GNZ,assumption:gradient_noise_new_as,
    assumption:function_H_taylor_exp,
    assumption:learning-rate-rv} hold with $\gamma_1 L<1$. Assume also that
  \Cref{eq:diffw} holds. Then, as $N\to\infty$,
  \begin{align*}

    w_N(\bstheta_N-\bstheta^*)\Rightarrow  Z_{\infty} \; , 
  \end{align*}
  with $Z_{\infty}$ a stable random vector with characteristic function given by
  \begin{subequations}
    \begin{align}

      \esp\left[\exp(iu^\top Z_\infty)\right]
      &= \exp\left(\int_{\Rset^d\setminus\{0\}}\Big(e^{iu^\top x}-1-iu^\top x\Big)
        \,\widetilde{\nu}(\rmd x)\right), \ \ 
      \\

      \widetilde{\nu} & =\int_{t=0}^{\infty}\nu(e^{t\,\nabla H(\bstheta^*)}\cdot)\,\rmd t \; ,
    \end{align}
  \end{subequations}
  and $\nu$ is the exponent measure of  $\GNZ_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] \cite{nnang2014deterministic}
		An $H$-supralgebra $A$\ on $\mathbb{R}^{d}_{y}$\ is ergodic\ if and
		only if 
		\begin{equation*}
			\lim_{r\rightarrow +\infty }\left\| \frac{1}{\left| B_{r}\right| }
			\int_{B_{r}}u(\cdot +y)dy-M(u)\right\| _{\Phi,A}=0\text{\ for all }u\in \mathfrak{X}^{\Phi}_{A}
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

