[Theorem thm:3d-coul of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $ x_{ n}\in B(0,\rho _{ -}^{ (n)}),n\geqslant 1$, $ \mathsf{P}^{ d,\beta }$ a limit point of $   \{  \tau _{ -x_{ n}}\mathsf{P}^{ d,\beta }_{ n};n\geqslant 1\}$ in the vague topology. Let $ \gamma>0,\varphi \in   \mathscr  F_{ \gamma }$ $ \Leb$-a.e. continuous.

\begin{itemize}
\item  {\bf 2D:}  $  \mathsf{P}^{ 2,\beta }$ is stationary (by  [leble-stationary])   and $ 2$-hyperuniform: as $ R\to \infty $ 
\begin{align*}
  \textrm{Var}\left(\mathsf{P}^{ 2,\beta }( \varphi _{ R})\right)  = O(R^{ 2-\min(\gamma,2) }\ln(R)^{ {\bf 1}\{ \gamma  = 2 \}}),
 \end{align*}
\item  {\bf 3D:} There is $ R^{ \circ}\geqslant 1$ such that for $R\geqslant R ^{\circ }, L \geqslant  { R^{ 2d + 1-\min(1,\gamma )}},$  
\begin{align}

\sup_{ x_{ 0}\in \mathbb{R}^{ d}}\displaystyle\int_{ [-L/2,L/2 ]^{ d}}  \textrm{Var}\left(\mathsf{P}^{ 3,\beta }(\tau _{ x_{ 0} + x}\varphi _{ R})\right)\frac{ dx}{L^{ d}}\leqslant C_{ \varphi }R^{ 3-\gamma }\ln(R)^{ {\bf 1}\{ \gamma  = 1 \}}.
 \end{align}
 If $ \mathsf{P}^{ 3,\beta }$ is stationary, it is $ 1$-hyperuniform.
\begin{align*}
  \textrm{Var}\left(\mathsf{P}^{ 3,\beta }(\varphi _{ R})\right) = O(R^{ 3-\gamma }\ln(R)^{ {\bf 1}\{ \gamma  = 1 \}}).
\end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2609.00702, 'On the Set-Valued Katugampola Fractional Integral: Properties and Regular Selections'] Let $F:I\rightrightarrows \mathbb{R}$ be a set-valued function and $\mathfrak{I}$ be the collection of all integrable selections of $F.$ Riemann-Liouville set-valued fractional integral of $F$ is defined as 
    \begin{equation*}
        \begin{aligned}
            _a\mathfrak{D}^{\nu}F(t)=\bigg\{\frac{1}{\Gamma(\nu)}\int_a^t(t-x)^{\nu-1}f(x)dx:f\in\mathfrak{I}\bigg\}
        \end{aligned}
    \end{equation*}
    where $\nu>0$ is a real number.

[Theorem 15 (Strict endpoint chain for $1\le p<2$) of arXiv:2605.11451, '2605.11451'] For every $1\le p<2$ and every $k\ge1$,
\begin{equation}
 b_{p,k+1}<b_{p,k}.
\end{equation}
Consequently, for every $n\ge2$,
\begin{equation}
 A_{p,n,0}(u^{(1)})>
 A_{p,n,0}(u^{(2)})>
 \cdots>
 A_{p,n,0}(u^{(n)}).
\end{equation}

