[Theorem the3.1 of arXiv:2411.13266, '\bf A new maximal regularity for parabolic equations and an application'] Let $p\in [1,+\infty]$, $\alpha\in (0,1)$ and $\lambda>0$, and let $a(t)=(a_{i,j}(t))_{n\times n}$ be a symmetric $n\times n$ matrix valued Borel bounded function such that ((3.1 of the paper)) holds. Let $f\in L^p(\mathbb{R};{\mathcal C}_{\vartheta,\varsigma}^{\alpha,\rho}({\mathbb R}^n))$ ($\vartheta\in \{l,b\}, \, \varsigma\in \{d,s,c,w\}$). Further assume that $\rho$ is  a slowly varying function at zero when it is increasing. Then there exists a positive constant $C$ such that for every $\gamma>0$,
\begin{eqnarray}
\int\limits_{\mathbb{R}}\|G_\lambda f(t,\cdot)\|_{\vartheta,2,0}dt+\gamma |\{t: [\nabla^2 G_\lambda f(t,\cdot)]_{\alpha,\rho}>\gamma\}|\leqslant
 C\int\limits_{\mathbb{R}}\|f(t,\cdot)\|_{\vartheta,\alpha,\rho}dt, \ \ {\rm when} \ \ p=1,
\end{eqnarray}
and
\begin{eqnarray}
\Bigg(\int\limits_{\mathbb{R}}\|G_\lambda f(t,\cdot)\|_{\vartheta,2+\alpha,\rho}^pdt\Bigg)^{\frac{1}{p}}\leqslant C\Bigg(\int\limits_{\mathbb{R}}\|f(t,\cdot)\|_{\vartheta,\alpha,\rho}^pdt\Bigg)^{\frac{1}{p}}, \ {\rm when} \ \ p\in (1,+\infty],
\end{eqnarray}
where the integrals in ((3.5 of the paper)) are interpreted as the essential supermum when $p=+\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] Let  $\beta\in(0,1)$,  $q\in(1-\beta,1]$, $\delta\in(0,\infty)$, $N\in\{2,3,\dots\}$
and let $v^*$ be as in \cref{def:v_star}.
Moreover, let $\bY=(Y_n)_{n\in-\N_0}$ be a vector of independent real-valued $L^2$-integrable  random variables for which $Y_{-N+1},\dots,Y_0$ are identically distributed  with
\bas{
 \P(Y_0^2\ge \delta)\ge q.
}
Let $\tilde\cE'=\{\sum_{k=-N+1}^0 \1_{\{Y_k^2\ge \delta\}}\ge 2\}$. Then one has that
\bas{
\E\bigl[&\1_{\tilde \cE' }(1+ v^*(\bY)^{-1}) (\|\bY\|_{\ell_\varrho}^2+1) \bigr]\\
&\le\Bigl(1+ \frac\beta{(1-\beta)} \Bigl(\frac { q}{\beta-(1-q)}\Bigr)^2\, \delta^{-1}\Bigr) 
\,\E\bigl[\|\bY\|_{\ell_\varrho}^2+1\big|\min(Y_0^2,Y_{-1}^2)\ge \delta\bigr].
}
Moreover, for a sequence $\bY=(Y_n)_{n\in-\N_0}$ of i.i.d.\ $ L^2 $-integrable random variables with~\cref{eq63645} one has that
\bas{
\E\bigl[&(1+ v^*(\bY)^{-1}) (\|\bY\|_{\ell_\varrho}^2+1) \bigr]\le\Bigl(1+ \frac\beta{(1-\beta)} \Bigl(\frac { q}{\beta-(1-q)}\Bigr)^2\, \delta^{-1}\Bigr) 
\,\E\bigl[\|\bY\|_{\ell_\varrho}^2+1\bigr].
}

