body:
[Theorem 159 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit} and \ref{Assumptions_analyticity}. Let $L \in \amsmathbb{Z}_{> 0}$ and a $L$-tuple of integers $\boldsymbol{h} \in [H]^L$ both independent of $\N$, let a (possibly $\N$-dependent) $L$-tuple of functions $\boldsymbol{f}(z)$ such that $f_l(z)$ is twice continuously differentiable in $\amsmathbb{A}_{h_l}^{\mathfrak{m}}$ and is a holomorphic function of $z$ in a $\N$-independent complex neighborhood $\amsmathbb{K}_h$ of $\bigcup_{k = k^-(h_l)}^{k^+(h_l)} [\overline{\alpha}_k,\overline{\beta}_k]$. Assume there exists a constant $C > 0$ such that $\max_{l} \sup_{z \in \amsmathbb{K}_h} |f_l(z)| \leq C$.

Let $\textnormal{\textsf{\textbf{Gau\ss{}}}}[\boldsymbol{f}]$ be a $L$-dimensional random Gaussian vector independent of the $K$-dimensional discrete Gaussian vector $\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}$ appearing in Theorem~\ref{Theorem_CLT_for_filling_fractions_saturation}, having covariance
\begin{equation}

\textnormal{\textsf{Cov}}_{l_1,l_2}[\boldsymbol{f}] = \sum_{k_1=k^-(h_{l_1})}^{k^+(h_{l_1})} \, \sum_{k_2=k^-(h_{l_2})}^{k^+(h_{l_2})} \oint_{\gamma_{l_1}} \oint_{\gamma_{l_2}}
 f_{l_1}(z_1) f_{l_2}(z_2)
\,\mathcal{F}_{k_1,k_2}(z_1,z_2)\,\frac{\dd z_1 \dd z_2}{(2\ii\pi)^2}.
\end{equation}
and $l$-th component of the mean equal to the sum of $\mathbbm{Rest}[f_l]$ in \eqref{Elink1} and $\mathbbm{Rest}'[f_l]$ in \eqref{Elinkm2} below.
Then, we have as $\N \rightarrow \infty$
\begin{equation}

\left(\sum_{i = 1}^{N} \mathbbm{1}_{[a_{h_l},b_{h_l}]}(\ell_i) f_l\bigg(\frac{\ell_i}{\N}\bigg) - \N \int_{\hat{a}'_{h_l}}^{\hat{b}'_{h_l}} f_l(x)\,\mu_{h_l}(x)\,\dd x\right)_{l = 1}^{L} \,\,\mathop{\sim}^{\textnormal{d}} \,\,\textnormal{\textsf{\textbf{Gau\ss{}}}}[\boldsymbol{f}] + \big(\mathsf{Shift}_{h_l}[f_l]\big)_{l = 1}^{L}.
\end{equation}
The convergence in Definition~\ref{Definition_asymptotic_equivalence} is uniform for fixed constants in the assumptions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_M of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] A probability measure $\mathbb{P}$ on $(\Omega,\mathcal{B}(\Omega))$ is of class $\mathscr{M}_{\gamma,\delta}$, written $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}$, if the following properties hold:
\begin{itemize}
\item $\mathbb{P}(Y_t \geq 0 \,\, \forall t \geq 0) = 1$.
\item The process $M = (M_t)_{t \geq 0}$ defined by (equation eq_Mdef of the paper) is a continuous local martingale with respect to $(\mathscr{F}_t)_{t \geq 0}$ with quadratic variation $\langle M\rangle$ satisfying

\begin{equation} 
		\mathbb{P}(\langle M \rangle_t - \langle M\rangle_s \geq I_t - I_s \,\,\, \forall  \,t \geq s \geq 0)  = 1.
\end{equation}

\end{itemize}
If $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}$ and $\mathbb{P}(Y_0 = x) = 1$ for some $x \geq 0$, we write $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}(x)$.

[Definition 1 (Talagrand complexity measure) of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let $r>0$, $p>0$ and let $d$ be a (pseudo) metric over $\mathcal B$. The Talagrand complexity measure for $\mathcal B \subseteq \mathcal F$ is defined as
	\[
	\gamma_{p,r}(\mathcal B,d)
	:=
	\inf_{T^\infty \in \mathcal T_r(\mathcal B)}
	\sup_{f \in \mathcal B}
	\sum_{l=0}^{\infty}
	2^{l/p}\, d\big( D(f,T_l) \big).
	\]

[Lemma 7 of arXiv:2605.04684, 'Ergodicity of stochastic functional differential equation with jumps and finite delay'] Suppose that Assumption \ref{A1}  holds. Given \(\alpha > 0\),  take \(\lambda = \lambda_0\) in \eqref{EQ:0527:06} such that \eqref{eq:jinm} below is satisfied, then
    \begin{equation*}
        \E \left[\|X_t-Y_t\|_{\infty}^2\right] \leq C\|\xi-\eta\|_{\infty}^2\e^{-\alpha t}.
    \end{equation*}

