[Proposition prop:upper of arXiv:2606.11248, 'Persistent Homology of the Planar Wiener Sausage: Brownian Scaling and a Logarithmic Expec'] There exists an absolute constant $c_{+}<\infty$ such that, for every fixed $r>0$,
\begin{equation}
\limsup_{T\to\infty}\frac{(\log T)^{2}}{T}\,\mathbb{E}[\beta_{1}^{T}(r)]\le\frac{c_{+}}{r^{2}}.
\end{equation}

[Prop 14 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $\left(\mu_t:=u(t,x)dx\right)_{t\geq 0}$ be a given solution to the linear Fokker-Planck equation \eqref{eq:LFPshort}, and assume that $\mathbf{H_{a,b}^{\sqrt{u}}}$, $\mathbf{H_{\sf \lesssim u}}$, and $\mathbf{H^{\sf TV}_0}$ hold.
Further, let
\begin{equation*}
X=\left(\Omega,\mathcal{F},\mathcal{F}(t),X(t)=(X_1(t),X_2(t)),\mathbb{P}_{s,x}, (s,x)\in E, t\geq 0\right)
\end{equation*} 
be the right process provided by both \Cref{thm:main0} and \Cref{thm:main1}, $D\subset \mathbb{R}^d$ be open, $T\in (0,\infty)$, and $F\in b\mathcal{B}([0,\infty)\times \mathbb{R}^d)$ for which there exists $N>0$ such that $F(s,\cdot)=0, s\geq N$.
Furthermore, let us set
\begin{align*}
    \tau
    &:=\inf\left\{t>0 : X(t)\in [0,\infty)\times \mathbb{R}^d\setminus(0,T)\times D\right\}, \mbox{ and note that } \tau \leq T-s \;\mathbb{P}_{s,x}\mbox{-a.s.} \mbox{ for } s\in [0,T],\\
    \rho(t,x)&
    :=\mathbb{E}_{t,x}\left\{F(X(\tau))\right\},\quad t\in[0,\infty), x\in E(t).
\end{align*}
The following assertions hold.
\begin{enumerate}
    \item[(i)] $\rho$ is a solution to problem \eqref{eq:BKE} in the following sense:
    \begin{enumerate}
        \item[(i.1)] $\rho$ is $\mathcal{B}(E)$-measurable, finely continuous on $[[0,T)\times D]\cap E$ (it is finely continuous on $E$ if $F$ is finely continuous), and under $\mathbb{P}_{s,x}, \;(s,x)\in \left[[0,T)\times D\right]\cap E$,
        \begin{equation*}
            \left(\rho(X(t\wedge\tau))_{t\geq 0}\right) \mbox{ is a c\`adl\`ag } (\mathcal{F}(t\wedge \tau))\mbox{-martingale}\quad \mbox{and}\quad \lim\limits_{t\nearrow \tau }\rho(X(t))=F(X(\tau))\; \mbox{a.s.}
        \end{equation*}
        Moreover, we have
        $
            \rho(T,x)=F(T,x), \quad x\in D \;\mu_T\mbox{-a.e.}
        $
        \item[(i.2)] If $F$ is finely continuous and $F\in {\sf D({\overline L}_p)}$ for some $p\in (1,\infty)$ then $\rho \in {\sf D({\overline L}_q)}$ and
        \begin{equation*}
            {\sf L_q}\rho=0 \quad \mbox{on } [0,T)\times D \;\overline{\mu}\mbox{-a.e.} \quad \mbox{for every } 1\leq q\leq p.
        \end{equation*}
    \end{enumerate}
    \item[(ii)] $\rho$ is the unique solution to problem \eqref{eq:BKE} in both of the following meanings:
    \begin{enumerate}
        \item[(ii.1)] Let $v\in b\mathcal{B}(E)$ be such that under $\mathbb{P}_{s,x}, \;(s,x)\in \left[[0,T)\times D\right]\cap E$,
        \begin{equation*}
            \left(v(X(t\wedge\tau))_{t\geq 0}\right) \mbox{ is a c\`adl\`ag } (\mathcal{F}(t\wedge \tau))\mbox{-martingale}\quad \mbox{and}\quad \lim\limits_{t\nearrow \tau }v(X(t))=F(X(\tau))\; \mbox{a.s.}
        \end{equation*}
        Then $v(s,x)=\rho(s,x)$ for every $(s,x)\in [[0,T)\times D]\cap E$.
        \item[(ii.2)] Let $v\in b\mathcal{B}(E)$ be finely continuous such that
        \begin{equation}
            v \in {\sf D({\overline L}_1)},\quad    {\sf L_1}v=0 \quad \mbox{on } [0,T)\times D \;\overline{\mu}\mbox{-a.e.}, \quad \mbox{and } \lim\limits_{t\nearrow \tau }v(X(t))=F(X(\tau)) \quad \mathbb{P}_{\overline{\mu}|_{(0,T)\times D}}\mbox{-a.e.}
        \end{equation} 
        Then there exists a set $E'\in \mathcal{B}(E)$ such that $E\setminus E'$ is $\overline{\mu}$-inessential and $v(t,x)=\rho(t,x)$ for every $(t,x)\in [[0,T)\times D]\cap E'$.
    \end{enumerate}
\end{enumerate}

