[Proposition prop:blow_up_elliptic_ratio of arXiv:2511.12692, 'A stochastic flow approach to De Giorgi--Nash--Moser estimates for SPDE\lowercase{s} with '] We consider in $d=2$ the SPDE 
\begin{align}\begin{split}
    \mathrm{d} u\,=\, \bigl(\partial_1 (a^{11} \partial_1 u) \,+\, \partial_2 (a^{22} \partial_2 u) \bigr)\,\mathrm{d} t \,&-\, \sin(2\pi x_1)\partial_{1} u \,\mathrm{d} w_t^1 \,-\, 
    \cos(2\pi x_1)\partial_1 u \,\mathrm{d} w_t^2\\&-\, \sin(2\pi x_2)\partial_2 u \,\mathrm{d} w^3_t \,-\, \cos(2\pi x_2)\partial_2 u\, \mathrm{d} w^4_t,
\end{split}\end{align}
where $a^{11},a^{22} \colon[0,T]\times\Omega\times \mathbb{T}^d\to {\mathbb R}$ are $\mathcal{P}\otimes\mathcal{B}(\mathbb{T}^d)$-measurable such that for some $\delta \in (0,1)$, ${\mathbb P}$-a.s.,
\begin{equation}

    \frac{1}{2} +\delta  \,\le\, a^{ii}(t,x)  \,\le\, \frac{1}{2} + \delta^{-1},
\end{equation}
for all $i\in \{1,2\}$, $t\in [0,T]$ and $x\in {\mathbb R}^d$.
Then, defining for  the 
diffusion coefficient $\alpha^{ij}$ of the transformed equation (equation Eq16 of the paper)  the  quantity
\begin{equation}

\Lambda(t,x):=
{\sup_{\eta\in {\mathbb R}^2 : |\eta| = 1 } |\eta_i \alpha^{ij}(t,x) \eta_j | }  \bigg/ {   \inf_{\eta\in {\mathbb R}^2 : |\eta| = 1 } |\eta_i \alpha^{ij}(t,x) \eta_j | },
\end{equation}
we have 
$
{\mathbb P}(\Lambda(t,x) >k)>0
$
for all  $(t,x)\in (0,T] \times\mathbb{T}^d$ and $k>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 12 of arXiv:2609.00183, '2609.00183'] For $\eta>0, r \in (0,1),$ we define
    \begin{align*}
        \calS_{0,\eta,r}^k(v)=\{x\in \calS_0^k(v): v \text{ is  not } (\eta,s,k+1)-\text{homogeneous at } x \text{ for  any } s \in [r,1]\}
    \end{align*}
    \begin{align*}
        \calS_{0,\eta}^k(v)=\{x\in \calS_0^k(v): v \text{ is not } (\eta,s,k+1)-\text{homogeneous at } x \text{ for any } s\in (0,1]\}
    \end{align*}

[Lemma lem: two rare events upper bound with conditioning of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Let $I\subset \Lambda_{M}$ be a subset of $\Lambda_{M}.$ There exists a constant $c_9>0$ such that 
for any boundary condition $\bar\eta_I$ on $\overline{\mathrm{Ball}(I)}$ and any configuration $\xi$, we have
    \begin{equation}
\mu^{\xi,\bar\eta_I}_{\Lambda_{M}\setminus{\mathrm{Ball}(I)}}(\mathcal R)\leq c_9^{|I|}\mu^{\xi}_{\Lambda_{M}}(\mathcal R).
\end{equation}
    \begin{equation}
\mu^{\xi,\bar\eta_I}_{\Lambda_{M}\setminus{\mathrm{Ball}(I)}}(\mathcal S)\leq c_9^{|I|}\mu^{\xi}_{\Lambda_{M}}(\mathcal S).
\end{equation}
Here, notice that although $\bar\eta_I$ is an extended-Ising configuration, it naturally works as a boundary condition for the Ising measure.

