[Proposition contrainte of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Define $\  B(\lambda,\eta):= \eta^{-\frac{2}{3}} b(\lambda,\eta) $.  

\noindent 1. The expression of $B(\lambda,\eta)$ is given by
\begin{equation}
B(\lambda,\eta)= \eta^{-\frac{2}{3}}\langle N_{\lambda,\eta},\Phi\rangle = \int_{\mathbb{R}^d}(\lambda- \mathrm{i} \eta^{\frac{1}{3}} v)M_{\lambda,\eta}(v)M(v)\mathrm{d}v .
\end{equation}
2.  The $\eta$ order of $B(\lambda,\eta)$ in its expansion with respect to $\lambda$ is given by
\begin{equation}
\underset{\eta \rightarrow 0}{\mathop{\rm lim}} \ \frac{\partial B}{\partial \lambda}(0,\eta) = \int_{\mathbb{R}^d} M^2(v)\mathrm{d}v .
\end{equation}
3.  There exists $\tilde\eta_0, \tilde\lambda_0>0$ small enough, a function $\tilde{\lambda}: \{|\eta|\leqslant\tilde\eta_0\} \longrightarrow \{|\lambda|\leqslant\tilde\lambda_0\}$ such that,
for all $(\lambda,\eta)\in [0,\tilde\eta_0[\times\{|\lambda|<\tilde\lambda_0\}$,  $\lambda = \tilde{\lambda}(\eta)$ and the constraint is satisfied: $$B(\lambda,\eta)= B(\tilde{\lambda}(\eta),\eta)=0.$$
Consequently, $\mu(\eta) := \eta^{\frac{2}{3}} \tilde{\lambda} (\eta)$ is the eigenvalue associated to the eigenfunction $M_\eta: = M_{\tilde{\lambda}(\eta),\eta}$ for the operator $\mathcal{L}_\eta$, and the couple $\big(\mu(\eta),M_\eta \big)$ is solution to the spectral problem (equation M_mu,eta of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm equivalent_cost of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$, $i=0,1$. The map \begin{align*}
    \iota:  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)\to  \mathsf{Cpl}_s( \mathsf{gap}(\mathsf{P}_0), \mathsf{gap}(\mathsf{P}_1)),  \mathsf{Q}\mapsto ( \mathsf{sq}\circ\mathrm{Pr}^{\Gamma}_0, \mathsf{sq}\circ\mathrm{Pr}^{\Gamma}_1)_{\#} \mathsf{Q}^0
\end{align*}
is a bijection. Furthermore, it holds that 
\begin{align}
    \int \sum_{(x,y)\in \bar\xi\cap \Lambda_1}\left\lvert(x^+-x)-(y^+-y)\right\rvert^p \mathsf{Q}(d\bar\xi)=\int \left\lvert \mathsf{s}_1- \mathsf{s}'_1\right\rvert^p\iota( \mathsf{Q})(d \mathsf{s},d \mathsf{s}').
\end{align}    
In particular
  \begin{align*}
        \mathscr W_p(\mathsf{P}_0,\mathsf{P}_1)=\mathscr W_{gap,p}( \mathsf{gap}(\mathsf{P}_0), \mathsf{gap}(\mathsf{P}_1)) 
    \end{align*}
    and there exists an $\mathscr W_p-$optimal $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$.

[Lemma d_{i|j of arXiv:2608.29986, 'Khovanov-Rozansky homology over $\F[U,V]$'] }
Let $i, j \in \ensuremath{\mathbb{N}} _0$ be such that they are not both $0$. Then
$$d_{i|j} = \frac{1}{j!}\sum_{k=0}^{j} (-1)^k \binom{j}{k} F^{j-k}d_{i+j}F^k.$$

