[Corollary 24 of arXiv:2608.30602, '2608.30602'] Let $h_0(z)=\log z\,\chi(z)$ and $h_1(z)=\log z\,\tilde{\chi}(z)$, and let
$|v(x)|\lesssim\langle x\rangle^{-3-}$.
Then, for $j=0,1$, we have
\begin{equation*}
h_j(\lambda|x-y|)-h_j(\lambda a)+\lambda\,r_y(x)\,h_j'(\lambda a)
=e^{\pm i\lambda a}\,\mathcal{A}_{h_j}^{\pm}(\lambda,a,b),
\end{equation*}
where the remainders satisfy, for all $\lambda\in(0,1/2)$ and $k=0,1,2$,
\begin{equation}
\bigl\|v(x)\partial_\lambda^k\mathcal{A}_{h_0}^{\pm}(\lambda,a,b)\bigr\|_{L_x^2}
\lesssim\lambda^{\frac32-k}a^{-\frac12},
\qquad\text{whenever }\lambda a\gtrsim 1,
\end{equation}
and
\begin{equation}
\bigl\|v(x)\partial_\lambda^k\mathcal{A}_{h_1}^{\pm}(\lambda,a,b)\bigr\|_{L_x^2}
\lesssim\lambda^{\frac32-k}a^{-\frac12},
\qquad\text{whenever }\lambda a\lesssim 1.
\end{equation}

[Prop 11 of arXiv:2609.01413, 'Sharp Threshold for Universality of Rational Canonical Forms over a Finite Field'] We have
\begin{equation}
\Aut\left(\bigoplus_{i=1}^k\bigoplus_{j\ge 1}(\F_p[t]/(f_i^{\l^{(f_i)}_j}))\right)=\prod_{i=1}^k\Aut_{f_i}(\lambda^{(f_i)}),
\end{equation}
where for all $1\le i\le k$, $\Aut_{f_i}(\lambda^{(f_i)})$ is the group of automorphisms of $\bigoplus_{j\ge 1}(\F_p[t]/(f_i^{\l^{(f_i)}_j}))$, and
\begin{equation}
\#\Aut_{f_i}(\lambda^{(f_i)})=p^{\deg f_i\cdot(|\l^{(f_i)}|+2n(\l^{(f_i)}))}\prod_{j\ge 1}(p^{-\deg f_i};p^{-\deg f_i})_{m_j(\l^{(f_i)})}.
\end{equation}
Here, the notation $(a;q)_m:=(1-a)(1-aq)\cdots(1-aq^{m-1}),m\ge 0$ refers to the $q$-Pochhammer symbol with the convention that $(a;q)_0=1$.

[Theorem TU of arXiv:2510.12480, 'Cyclic and alternating $U$-statistics'] With notations and assumptions 
as in Section~(Sprel of the paper),
the following holds.
\begin{romenumerate}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
We have
\begin{align}
  \operatorname{\mathbb E}{} U_n(f) = \tbinom n2\mu
\end{align}
and, as \ensuremath{{n\to\infty}}, we have the weak law of large numbers
\begin{align}
  \frac{1}{\binom n2} U_n(f)\overset{\mathrm{p}}{\longrightarrow} \mu.
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
As \ensuremath{{n\to\infty}},
\begin{align}
n^{-3}\operatorname{Var}[U_n(f)]\to
  \sigma^2:=\tfrac{1}{3}
\bigl(\operatorname{\mathbb E}{} [f_1(X)^2] + \operatorname{\mathbb E}{} [f_2(X)^2] + \operatorname{\mathbb E}{} [f_1(X)f_2(X)]\bigr)
\end{align}
and 
\begin{align}
  n^{-3/2}\left(U_n(f)-\tbinom n2 \mu\right) \overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2).
\end{align}
Furthermore, $\sigma^2>0$ unless $f_1(X)=f_2(X)=0$ a.s.

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If\/ $f_1(X)=f_2(X)=0$ a.s., and thus $\sigma^2=0$, then
\begin{align}

  \operatorname{Var}[U_n(f)] = \tbinom{n}{2}\operatorname{Var} [f(X_1,X_2)]
=\tfrac{1}{2}n^2\operatorname{Var} [f(X_1,X_2)] + O(n).
\end{align}
Moreover, there exists
a finite or infinite sequence of real numbers $(\lambda_r)_1^R$ such that
\begin{align}
  n^{-1}\left(U_n(f)-\tbinom n2 \mu\right) \overset{\mathrm{d}}{\longrightarrow} W:=\sum_{r=1}^R\tfrac12\lambda_r(\zeta_r^2-1),
\end{align}
where $(\zeta_r)_1^R$ are independent standard normal variables.
The coefficients
$(\lambda_r)_1^R$ 
are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{{\widehat{f}}-\mu}$ 
on $L^2({\mathcal X}\times\ensuremath{[0,1]},\nu\times\ell)$
(where $\ell$ is Lebesgue measure)
defined as in (equation Tg of the paper) using (equation hff of the paper).
We have
\begin{align}
\operatorname{Var} W=
 \tfrac12 \sum_{r=1}^R\lambda_r^2 = \tfrac12\operatorname{Var}[f(X_1,X_2)]
<\infty.
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TU2 of the paper) where
furthermore
$f$ is symmetric, 
the coefficients
$(\lambda_r)_1^R$ in (equation tu2 of the paper) are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{f-\mu}$ 
on $L^2({\mathcal X},\nu)$.

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TU2 of the paper) where
furthermore
$f$ is antisymmetric, 
then also
\begin{align}

  n^{-1}{U_n(f)} \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{q=1}^{Q_+}\lambda^{\mathsf a}_q\eta_q,
\end{align}
where $(\eta_q)_1^{Q_+}$ are independent random variables with the stochastic area
distribution (equation area of the paper), and
the coefficients 
$(\lambda^{\mathsf a}_q)_1^{Q_+}$  are the positive numbers such that the imaginary
number $\mathrm{i}\lambda^{\mathsf a}_q$ is an eigenvalue of the 
anti-self-adjoint
operator $T_f$ on $L^2_{\mathbb C}({\mathcal X},\nu)$.
We have
\begin{align}
  \operatorname{Var} W = \sum_{q=1}^{Q_+}(\lambda^{\mathsf a}_q)^2 = \tfrac12\operatorname{Var}[f(X_1,X_2)].
\end{align}

\end{romenumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lem:ftc of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] Let $f(x)$ be a Riemann-integrable function on $[0,1]$ and set $L=\int_0^1 f(x) \,dx$. For $\varepsilon>0$, define the sets
\[
D=\{x\in [0,1]:\, f(x)<0 \} , \quad L_\varepsilon=\{ x\in [0,1]: f(x)\in [0,L+\varepsilon] \}. 
\]
Then one of the following holds:
\begin{equation}

\left| \int_D  f(x) \, dx \right| \ge \frac \varepsilon 2.
\end{equation}
or
\begin{equation}

\mu(L_\varepsilon \cup D) \ge \frac \varepsilon {2(L+\varepsilon)}. 
\end{equation}
where $\mu(\cdot)$ denotes the Lebesgue measure.

[Pro eq:Pro1 of arXiv:2411.02141, '\bf Uniqueness of Maximum Scores in Countable-Outcome Round-Robin Tournaments'] Assuming Model $M_{[0,\,1]}$, we have
\begin{align*}

\lim_{n\rightarrow \infty}\mathbb{P}\left(s^{\star}_n>t_n \right)=1.
\end{align*}

