[Pro 5 of arXiv:2607.04730, 'Variance gamma approximation to sums of triplewise independent random variables'] Let $Z\sim \mathrm{VG}(r,\theta,\sigma,\mu)$ with density given in \eqref{den:VG}. Then a Stein equation for $Z$ is given by
    \begin{align}
        \sigma^{2}(x-\mu)f^{\prime\prime}(x)+\left(\sigma^{2}r+2\theta(x-\mu)\right)f^\prime(x)+\left(r\theta-(x-\mu)\right)f(x)=h(x)-\mathbb{E}(h(Z)),
    \end{align}
    where $h\in \mathcal{H}$ is a real-valued test function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:stable_equivalence_def of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] A random variable $X$ is said to have a stable distribution if one of the equivalent following properties is met.
\begin{itemize}
\item \textbf{Sum stability for linear combination.} For any $a,b>0$ there exist two constants $c>0$ and $d\in \mathbb{R}$ such that 
    \begin{align}
        a X_1 + b X_2 \stackrel{d}{=} cX + d,
    \end{align}
    where $X_1$ and $X_2$ are independent copies of $X$.

\item \textbf{Sum stability for $n$ terms sum.} For any $n\in \mathbb{N}$ such that $n\geq 2$, there exist two constants $c_n>0$ and $d_n \in \mathbb{R}$ such that 
    \begin{align}
        X_1 + X_2 + \cdot + X_n \stackrel{d}{=} c_n X + d_n,
    \end{align}
    where $X_1,X_2, \cdots, X_n$ are independent copies of $X$ and for all $n\in N$ there exists $\alpha \in (0,2]$ called the \emph{stability index} such that $c_n = n^{1/\alpha}$.


\item \textbf{General Central Limit Theorem.} There exist $Y_1,\cdots, Y_n$ i.i.d. random variables and two sequences $(a_n)_{n\in\mathbb{N}}$, $(b_n)_{n\in \mathbb{N}}$, where $\forall n\in \mathbb{N}, a_n>0$ and $b_n \in \mathbb{R}$ such that
\begin{align}
 a_n\left(\sum_{i=1}^n Y_i\right) - b_n \stackrel{d}{\rightarrow} X,
\end{align}
when $n\rightarrow +\infty$

\item \textbf{Stable characteristic function.} There exist $0<\alpha\leq 2, \sigma \geq 0, \beta \in [-1,1]$ and $\delta \in \mathbb{R}$ such that the characteristic function $\phi_X$ of $X$ is given for all $u\in \mathbb{R}$ by
\begin{align}
\phi_X(u) = \begin{cases}
    \exp \left( - \sigma^\alpha |u|^\alpha \left(1- i\beta sign(u) \tan \left(\frac{\pi\alpha}{2} \right) \right) + i\delta u \right)& \text{if } \alpha \neq 1 \\
    \exp \left(- \sigma |u|(1+ i\beta \frac{2}{\pi} sign(u) \log(|u|)) + i \delta u \right) &\text{if } \alpha =1.
\end{cases}
\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

