[Definition of arXiv:2609.00233, 'A survey on mapping class groups of 3-manifolds'] We define
\begin{multline*}
\overline{\Diff}^+(M,(B_h),(T_i),(M_j)) \coloneqq \\
\{ f \in \Diff^+(M,(B_h),(T_i),(M_j)) \mid f \big| _{T_i} \colon T_i \rightarrow T_i \text{ is orientation preserving for every $i$} \}
\end{multline*}

[Definition def:NSP:statement of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] A linear operator $\mathcal{A}: \R^{d_1 \times d_2} \to \R^{m}$ is said to satisfy 
	the \emph{NSP} of order $r \in \N$, $1 \leq r < d$ with constant $0 < \eta_r < 1$ if 
	\begin{equation} 
		\sum_{i=1}^{r} \sigma_i(\mathbf{N}) \leq \eta_r \sum_{i=r+1}^{d} \sigma_i(\mathbf{N})
	\end{equation}
for all  $ \mathbf{N} \in \ker(\mathcal{A})$. Here, $\sigma_i(\mathbf{N})$ denotes the $i$-th largest singular value of the matrix $\mathbf{N}$.

[Lemma 16 of arXiv:2607.29495, 'Fast Mixing for Low-Temperature Potts Models via Poisson Trees'] Fix integer $q\geq 2$ and $\beta>0$. Let $G=(V,E)$ be a graph and 
$\nu=\nu_{G;q,\beta}$ be the Edwards--Sokal distribution.  Let $\mu=\mu_{G;q,\beta}$ and $\pi=\pi_{G;q,\beta}$ be the Potts and RC distributions. 

Suppose that $\mu$ satisfies
entropy factorisation with constant $C_{\mathrm{spin}}$. 
Then, with $C_{\mathrm{joint}} \coloneqq O(q^3  \emm^{3\beta \Delta}C_{\mathrm{spin}})$, for every function $g\ge0$ on the joint spin-edge space $[q]^V\times \{0,1\}^E$,
\begin{equation}
\Ent_\nu(g) \leq C_{\mathrm{joint}}
        \bigg(
        \sum_{v\in V}
        \E_\nu\left[\Ent^{\circ}_v(g)\right]
        + \sum_{e\in E}
        \E_\nu\left[\Ent^{\circ}_e(g)\right]
        \bigg).
\end{equation}
As a corollary, $\pi$ satisfies
entropy factorisation with constant $C_{\mathrm{joint}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 8 (Spinal derivation of the governing equations) of arXiv:2607.16833, 'Dynamical Equations for Poisson Galton--Watson Trees and Component Densities of Sparse Inh'] Under Assumption~\ref{ass:eigenfunction}, let
$F:\cN_f(S)\to\mathbb R$ be bounded and supported on $\cN_N(S)$ for some
$N$.  For $0<u<1/\rho$,
\begin{equation}
 \frac{\dd}{\dd u}\int F(\mu)P_{\alpha,u}^{\Lambda}(\dd\mu)
 =\int F(\mu)\left\{\frac{T(\mu)-1}{u}-A(\mu)\right\}
 P_{\alpha,u}^{\Lambda}(\dd\mu),
\end{equation}
and
\begin{equation}
 \int F(\mu)P_{\alpha,u}^{\Lambda}(\dd\mu)
 =\frac1u\int_0^u\int
 F(\mu)\{T(\mu)-sA(\mu)\}
 P_{\alpha,s}^{\Lambda}(\dd\mu)\dd s.
\end{equation}
Thus the $\varphi$-transform and ascension construction recover the same
dynamical equations as Theorem~\ref{thm:dynamics} on the spectrally
subcritical side.

[Proposition 20 of arXiv:2608.29501, 'Disorder Thresholds and Free Energy of Brownian Directed Polymers with\\ Product and Radia'] Assume \(\kappa=2\), and suppose that \(0\le V\le C_VG_{\bm\alpha}\).
There is \(C_{\mathrm{form}}<\infty\) such that
\begin{equation}
  \int_{\R^d}V(x)f(x)^2\dd x
  \le C_{\mathrm{form}}\norm{\nabla f}_2^2,
  \qquad f\in H^1(\R^d).

\end{equation}
Consequently,
\begin{equation}
  F_V(h)=0
  \qquad\text{for }0\le h\le
  h_{\mathrm{form}}:=\frac{1}{2C_{\mathrm{form}}}.

\end{equation}

[Proposition 26 (Marchenko--Pastur $D$-transform) of arXiv:2608.19594, 'Mesoscopic Rectangular Spikes under Subspace Local Laws:\\Outlier Values and Singular Subs'] For $z>b$,
\begin{align}
 \phi(z)&=\frac{z^2+c-1-\Delta(z)}{2cz},\\
 \widetilde\phi(z)&=\frac{z^2-c+1-\Delta(z)}{2z},\\
 d(z)&=\frac{2}{z^2-(1+c)+\Delta(z)}.
\end{align}
Consequently,
\begin{equation}
  d(b+)=\frac1{\sqrt c},
  \qquad \theta_\star=c^{1/4}.
\end{equation}
For $\theta>c^{1/4}$,
\begin{align}
 \rho(\theta)^2
 &=\theta^2+(1+c)+\frac c{\theta^2}
 =\frac{(1+\theta^2)(c+\theta^2)}{\theta^2},\\
 \cL(\theta)
 &=\frac{1-c/\theta^4}{1+c/\theta^2},\\
 \cR(\theta)
 &=\frac{1-c/\theta^4}{1+1/\theta^2},\\
 \cLR(\theta)
 &=\sqrt{\frac{1-c/\theta^4}{1+c/\theta^2}}
   \sqrt{\frac{1-c/\theta^4}{1+1/\theta^2}}.
\end{align}

