[Lemma lem : domof of arXiv:2609.00105, 'Weighted composition operators and classification of weighted Hardy spaces'] Let $\mathcal{H}$ be a weighted Hardy space in $d$ variables with generating function $G(t)=\sum_{n=0}^\infty a_nt^n$. Let $r^2\in(0,\infty]$ be the radius of  convergence of $G$ then,
    \begin{enumerate}
    \item If $r=\infty$, then $\mathbb{C}^d$ is a maximal domain for $\mathcal{H}$.

    \item If $r<\infty$ and $G(r^2) = \infty$, then $r\mathbb{B}_d$ is a maximal domain for $\mathcal{H}$.

    \item If $r<\infty$ and $G(r^2) < \infty$, then $\overline{r\mathbb{B}_d}$ is a maximal domain for $\mathcal{H}$.
    \end{enumerate}

[Lemma 11 (Lower bounds for $\Xi_1$ and $\Xi_2$) of arXiv:2608.26259, 'Cutoff with an $O(1)$ window for Potts Glauber Dynamics\\on lattice at High Temperature'] Assume $\alpha\le \tfrac12$.
There exist explicit constants $C_1=C_1(d,p_{\mathrm{stop}})>0$ and $C_2=C_2(d,p_{\mathrm{stop}})>0$ such that
for every integer $l\ge1$,
\begin{align}
\mu\big(\ell(x_1)=l,\ b(x_1)=1\big) &\ge C_1\,\alpha\,e^{-\eta l}, \\
\mu\big(\ell(x_1)=l,\ b(x_1)=2\big) &\ge C_2\,\alpha^2\,e^{-\eta l}. 
\end{align}

