[Lemma l:taurx of arXiv:2411.04773, 'Meeting of squared Bessel flow lines and application to the skew Brownian motion'] Let $r\in {\mathbb R}$. Almost surely: for all $x\ge r$ and $t\ge 0$,
\begin{enumerate}[(i)]
    \item $L_t^r\le x$ for all $t\in [0, \tau_x^r)$, $L_t^r=x$ for $t=\tau_x^r$ and $L_t^r>x$ for all $t>\tau_x^r$;
    \item $X^r_{\tau^r_x}=0$ and $B_{\tau^r_x}=x$;
    \item $\mathcal L(t,x)>\mathcal L(\tau^r_x,x)$ for $x<L_t^r$ and $\mathcal L(t,x)\le \mathcal L(\tau^r_x,x)$ for $x\ge L_t^r$. In particular, $L^r_t=\sup\{x>r\,:\, \mathcal L(t,x)>\mathcal L(\tau^r_x,x)\}\lor r$ where $\sup\emptyset=-\infty$ by convention;
    \item $\mathcal L(t,x)>\mathcal L(\tau_x^r,x)$ if and only if $t>\tau_x^r$;  if $\mathcal L(t,x)<\mathcal L(\tau_x^r,x)$, then $L_t^r<x$.
\end{enumerate}

[Cor WHnlambda of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Let $\{H_n\}_{n\ge 1}$ be a sequence of weighted $r$-uniform hypergraphs as described above with vertices colored uniformly with $c_n$ colors as in (equation eq:cn of the paper). Suppose 
    \begin{align}
    \lim_{n \to \infty}\bE \mathsf{W}(H_n) = \lambda \text{ and } \lim_{n \to \infty}\Var \mathsf{W}(H_n) = \lambda, 
    \end{align}
    for some $\lambda \ge 0$. Then, as $n \rightarrow \infty$, $\mathsf{W}(H_n) \dto \Pois(\lambda)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Ito formula of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] Let $\mathcal{H}_1 \subset \mathcal{H}_2 \subset \mathcal{H}_3$ be a triplet of embedded Hilbert Spaces where $\mathcal{H}_1$ is dense in $\mathcal{H}_2$, with the property that there exists a continuous nondegenerate bilinear form $\inner{\cdot}{\cdot}_{\mathcal{H}_3 \times \mathcal{H}_1}: \mathcal{H}_3 \times \mathcal{H}_1 \rightarrow \mathbb{R}$ such that for $\phi \in \mathcal{H}_2$ and $\psi \in \mathcal{H}_1$, $$\inner{\phi}{\psi}_{\mathcal{H}_3 \times \mathcal{H}_1} = \inner{\phi}{\psi}_{\mathcal{H}_2}.$$ Suppose that for some $T > 0$ and stopping time $\tau$,
\begin{enumerate}
        \item $\boldsymbol{\Psi}_0:\Omega \rightarrow \mathcal{H}_2$ is $\mathcal{F}_0-$measurable;
        \item $f:\Omega \times [0,T] \rightarrow \mathcal{H}_3$ is such that for $\mathbbm{P}-a.e.$ $\omega$, $f(\omega) \in L^2([0,T];\mathcal{H}_3)$;
        \item $B:\Omega \times [0,T] \rightarrow \mathscr{L}^2(\mathfrak{U};\mathcal{H}_2)$ is progressively measurable and such that for $\mathbbm{P}-a.e.$ $\omega$, $B(\omega) \in L^2\left([0,T];\mathscr{L}^2(\mathfrak{U};\mathcal{H}_2)\right)$;
        \item   $\boldsymbol{\Psi}:\Omega \times [0,T] \rightarrow \mathcal{H}_1$ is such that for $\mathbbm{P}-a.e.$ $\omega$, $\boldsymbol{\Psi}_{\cdot}(\omega)\mathbbm{1}_{\cdot \leq \tau(\omega)} \in L^2([0,T];\mathcal{H}_1)$ and $\boldsymbol{\Psi}_{\cdot}\mathbbm{1}_{\cdot \leq \tau}$ is progressively measurable in $\mathcal{H}_1$;
        \item  The identity
        \begin{equation} 
            \boldsymbol{\Psi}_t = \boldsymbol{\Psi}_0 + \int_0^{t \wedge \tau}f_sds + \int_0^{t \wedge \tau}B_s d\mathcal{W}_s
        \end{equation}
        holds $\mathbbm{P}-a.s.$ in $\mathcal{H}_3$ for all $t \in [0,T]$.
    \end{enumerate}
The the equality 
  \begin{align} \norm{\boldsymbol{\Psi}_t}^2_{\mathcal{H}_2} = \norm{\boldsymbol{\Psi}_0}^2_{\mathcal{H}_2} + \int_0^{t\wedge \tau} \bigg( 2\inner{f_s}{\boldsymbol{\Psi}_s}_{\mathcal{H}_3 \times \mathcal{H}_1} + \left\Vert B_s \right\Vert^2_{\mathscr{L}^2(\mathfrak{U};\mathcal{H}_2)}\bigg)ds + 2\int_0^{t \wedge \tau}\inner{B_s}{\boldsymbol{\Psi}_s}_{\mathcal{H}_2}d\mathcal{W}_s\end{align}
  holds for any $t \in [0,T]$, $\mathbbm{P}-a.s.$ in $\mathbb{R}$. Moreover for $\mathbbm{P}-a.e.$ $\omega$, $\boldsymbol{\Psi}_{\cdot}(\omega) \in C([0,T];\mathcal{H}_2)$.

[Proposition prop:relation_marginals of arXiv:2411.11425, 'Non-equilibrium steady states with a spatial Markov structure'] Let $\{\Lambda^n\}_{n\geq1}$be symmetric. Assume $a,b \in \mathbb{R}^+$, $\theta \in \mathbb{R}$ and $n \geq 1$, then 

    \begin{equation}
        \Lambda_{a,b}^{n,j}(\theta) = \Lambda_{b,a}^{n,n-j+1}(\theta)
    \end{equation}

    for all $j\in\{1,...,n\}$.

[Lemma tildelambdadecomp of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $\beta \in (0, 1)$.  
For sufficiently small $\epsilon_p$ so that $\tilde{\lambda} \ge 0$, 
there exist covariance matrices $(H_t)_{t\ge 0}$ invariant under lattice symmetries with range $< t$ and Fourier transform $\widehat{H}_t$ that satisfy
\begin{align}
	\frac{1}{\tilde{\lambda}} = \int_0^\infty \widehat{H}_t {\rm d} t , \qquad
	\widehat{H}_t (p) \le C \frac{t^{2\beta-1}}{1 + \textbf{a}^{(\emptyset)}t^{2\beta} }  e^{-c( \lambda t^2 )^{1/4}}
\end{align}
for some $C,c>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem charac of arXiv:2602.12713, 'GIG random matrices \\ and \\ a Yang-Baxter extension of the Matsumoto-Yor property'] Assume that $X$ and $Y$ are independent random matrices valued in $\Omega_+$ having strictly positive twice differentiable densities on $\Omega_+$. Let $\alpha,\beta\ge 0$ be two distinct numbers. Let 
		\begin{equation}
		\begin{cases} U=(\alpha X+Y)^{-1}(\beta X+Y)Y^{-1}
		\\
			V=(\alpha X+Y)^{-1}(\beta X+Y)X^{-1}.
			\end{cases}
		\end{equation}

		\bigskip
		If $U$ and $V$ are independent then there exist $\lambda\in\mathbb R$ and $a,b\in\Omega_+$ such that
			\begin{equation}
			X\sim\mathrm{MGIG}(\lambda,\alpha a,b)\quad\mbox{and}\quad Y\sim\mathrm{MGIG}(-\lambda,a,\beta b)
		\end{equation}
		and
		\begin{equation}
		U\sim\mathrm{MGIG}(\lambda,\alpha b,a)\quad\mbox{and}\quad V\sim\mathrm{MGIG}(-\lambda,b,\beta a).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] Let $f: M \to \mathbb{R}$ be a bounded and measurable function. Then there exists some $T_0 > 0$ and $C > 0$ such that for all $t \geq T_0$,
    \begin{align*}
        \sup\limits_{x \in M}\norm{\nabla R_{t}f(x)} \leq C\exp(-\lambda_1 t)\norm{f}_{L^\infty(\diffref)}
    \end{align*}

