body:
[Definition 4 (Bures-Wasserstein Distance, \cite{petric2019got}) of arXiv:2608.27500, 'Optimal Transport for Network Comparison: \\ A Review with Machine Learning Applications'] The Bures-Wasserstein distance between the graph signal distributions $\mu=\mathcal{N}(0,L^\dagger)$ and $\nu=\mathcal{N}(0,(L')^\dagger)$ is
\begin{align}
    BW(\mu,\nu)^2=\text{tr}\bigg[L^\dagger+(L')^\dagger-2\bigg((L^\dagger)^\frac{1}{2}(L')^\dagger(L^\dagger)^\frac{1}{2}\bigg)^\frac{1}{2}\bigg].
\end{align}

[Lem 7 of arXiv:2607.24166, 'Strong rate of convergence for the Euler--Maruyama scheme of additive fractional SDEs with'] Let $p \ge 2$, $n \in \bN$, and $(s, t) \in \Delta_{[0, 1]}$.
    Suppose that $b$ is Lipschitz continuous.
    If $H \in (1/2,1)$, then there exists a constant $C >0 $ independent of $n$, $s$, and $t$ such that
    \begin{equation}
        \Big\| \int_s^t \{ b(B^H_r + \varphi_{\kappa_n(r)}^n) - b(B^H_{\kappa_n(r)} + \varphi_{\kappa_n(r)}^n) \} \rd r \Big\|_{L^p} \le C n^{-1} (t - s)^{H}.
    \end{equation}
    If $H \in (0,1/2]$, then for any $\varepsilon \in (0, 1/2)$, there exists a constant $C >0 $ independent of $n$, $s$, and $t$ such that
    \begin{equation}
        \Big\| \int_s^t \{ b(B^H_r + \varphi_{\kappa_n(r)}^n) - b(B^H_{\kappa_n(r)} + \varphi_{\kappa_n(r)}^n) \} \rd r \Big\|_{L^p} \le C n^{-(1/2 + H) + \varepsilon} (t - s)^{1/2 + \varepsilon}.
    \end{equation}

