[Lemma 13 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] For every $\omega \in \Omega_{\lambda,\Lambda}$, $x \in \bbZ^d$ and $N \in \bbN$
    \begin{equation}
        \bbE^{\omega,+}_N [\varphi_x - m^\omega_x(\varphi)] = \begin{cases}
            \frac{1}{\sqrt{2\pi \mu^\omega_x}} \bbE^{\omega,+}_N \bigg[ \frac{\exp \left(-\frac{\mu^\omega_x}{2} m^\omega_x(\varphi)^2 \right)}{\phi(m^\omega_x(\varphi) \sqrt{\mu^\omega_x})} \bigg] \,, &\mbox{ for } x \in V_N \,, \\
            0 \,, &\mbox{ for } x \in V_N^c \,,
        \end{cases}
    \end{equation}
    where $\phi$ is the standard normal cumulative distribution function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 36 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $\mu:=(\mu_t)_{t\geq 0}\subset \mathcal{P}(\mathbb{R}^d)$ be a weakly continuous solution to the nonlinear Fokker-Planck equation \eqref{eq:NLFPshort}, such that $\mu_t:= u(t,x) dx,\; t\geq 0$ for a jointly measurable density
$u:[0,\infty)\times \mathbb{R}^d\rightarrow \mathbb{R}_+$.  
Furthermore, assume that the "linearized" conditions
\begin{equation*}
\mathbf{H_{a^u,b^u}^{\sqrt{u}}},\quad \mathbf{H_{\sf \lesssim u}}({\sf L^u}), \quad \mathbf{H^{\sf TV}_0}({\sf L^u}) \quad \mbox{ are fulfilled}.
\end{equation*}
Let $X$ be the process provided by \Cref{thm:MVE}, $\alpha>0$, and consider the mapping
\begin{equation*}
     \mathbb{R}^d\supset A\longmapsto {\sf Cap}^\alpha_{(\mu_t)}(A):= \inf\left\{\mathbb{E}_{\delta_0\otimes \mu_0}\left\{e^{-\alpha D^{(2)}_{G}}\right\} : A\subset G, \; G\subset \mathbb{R}^d \mbox{ open}\right\}.
\end{equation*}
Then ${\sf Cap}_{(\mu_t)}^\alpha$ is a Choquet capacity on $\mathbb{R}^d$ endowed with the norm topology.
Moreover, ${\sf Cap}_{(\mu_t)}^\alpha$ is tight.

