[Lemma lem:RT of arXiv:2607.12564, 'Power-law and log-periodic degree tails for a family of probability generating function eq'] There exist $C,c>0$, depending only on $p$ and $j$, such that
\begin{equation}
  \mathbb{P}(D^*_n=k)\le C\lambda^{-n}\exp\!\Bigl\{-c\,\frac{k}{\lambda^{n}}\Bigr\},
  \qquad n\ge0,\ k\ge j .
\end{equation}
Consequently, writing $N_k=\lfloor\log_\lambda k\rfloor$ and $m=n-N_k$,
\begin{equation}
  \mathbb{P}(D^*_n=k)\le\lambda^{-n}\mathcal D_m,\qquad
  \mathcal D_m=\begin{cases}C\exp\{-c\lambda^{-m}\},& m<0,\\[2pt] C,& m\ge0,\end{cases}
\end{equation}
and $\mathcal D_m$ is weighted-summable:
\begin{equation}
  \sum_{m\in\mathbb{Z}}\mathcal D_m\,\lambda^{-(\rho+1)m}<\infty .
\end{equation}

[Lemma 14 of arXiv:2607.26944, 'Improved bounds on the inradius and inverse inradius process of the convex hull of planar '] For every $\alpha \in (0, 1)$ it holds that
    \begin{equation*}
        \Var(\sfr) \ge \alpha^2 \big(\E[\sfr]\big)^2 \mleft[ 1 - \big( 1 - F_R(2(1 - \alpha)\E[\sfr]) \big)^2 \mright].
    \end{equation*}
    Furthermore, taking only the first term of the series for $F_R(x)$, setting $\alpha = 0.1$, and using the lower bound $\E[\sfr]\ge 0.393$ from~\cite{CPS}, we obtain
    \begin{equation*}
        \Var(\sfr) \ge 2.7 \cdot 10^{-6}.
    \end{equation*}

