[Lmm lmmUniqLineExpExten of arXiv:2607.29423, 'Schwarzian Field Theory at High Temperatures'] In the setting of Theorem~(thrUniqLineSchw of the paper), we have that for any $N>0$ and any continuous bounded function $F\in C(\mathbb{R}^N)$,
\begin{equation}
\int_{C^1_{0,+}(\mathbb{R})} F\left(\Big\{\obs{f}{s_{j}}{t_j}_0\Big\}_{j=1}^{N}\right) \mathop{}\!\mathrm{d}\mathcal{P}(f)
=
\int_{C^1_{0,+}(\mathbb{R})} F\left(\Big\{\obs{f}{s_{j}}{t_j}_0\Big\}_{j=1}^{N}\right) \mathop{}\!\mathrm{d}\mathscr{M}_{\varkappa^2}^{\infty}(f).
\end{equation}

[Definition eq:CE(Dir) of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] For a given $\delta > 0$, we say that $(\mathcal{E},\mathcal{F})$ satisfies the \emph{cutoff energy condition} (eq:CE(Dir) of the paper) if there is a constant $C \geq 1$ satisfying the following. For all $x \in X$ and $R \in (0,\diam(X))$ there is a cutoff function $\xi \in \mathcal{F}$ for $B(x,r) \subseteq B(x,2r)$ such that
    \begin{equation}
        \tag{$\textup{CE}_{\delta}(\Psi)$}
        \int_{B(y,r)} \,d\Gamma\Span{\xi} \leq C\left( \frac{r}{R} \right)^\delta \frac{\mu(B(y,r))}{\Psi(r)}
    \end{equation}
    for all $y \in X$ and $0 < r \leq 3R$.
    If $\Psi(r) = r^\beta$ for some $\beta \geq 2$, we write \hyperref[eq:CE(Dir)]{$\textup{CS}_\delta(\beta)$} instead.

[Defi Dini of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] An increasing continuous function $\omega_f: \mathbb{R}_{+}\rightarrow \mathbb{R}_{+}$ is called a Dini function if 
				\begin{equation}
					\int_{0+} \frac{\omega_f(s)}{s}\mathrm{d}s < +\infty.
				\end{equation}
				A measurable function $\omega_f: \mathbb{R}_{+}\rightarrow \mathbb{R}_{+}$ is called a slowly varying function at zero if for every $\lambda >0$
				\begin{equation*}
					\lim_{s\rightarrow 0} \frac{\omega_f(\lambda s)}{\omega_f(s)} = 1.
				\end{equation*}
				A measurable function $f: \mathbb{R}^d \rightarrow \mathbb{R}$ is said to be Dini continuous if there is a Dini function $h$ such that 
				\begin{align}
					|f(x)-f(y)| \leq \omega_f(|x-y|).
				\end{align}

[Lemma lem:detect_intersection_left of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Let $z\in D$ and $r>0$ such that $2r < \delta^{1+a_3}$ and $B(z,r) \subseteq D$. Let $e \in \mathcal {E}^\delta_0(\mathcal {L})$ for some $\mathcal {L} \in \widehat{\Gamma}_0^\delta$, and suppose that $U_e \subseteq B(z,r/4)$. Then there exist $z_1 \in \partial B(z,r/2)$, $w_1 \in \partial B(z,r/4)$ such that one of the following is true.
\begin{itemize}
\item Let $\eta^{\theta_0}_{z_1}$ be the angle $\theta_0$ flow line of $h$ starting at $z_1$ and stopped upon exiting $B(z,3r/4)$. Let $\eta^R_{w_1}$ be the angle $-\pi/2$ flow line starting at $w_1$, reflected off $\eta^{\theta_0}_{z_1}$ in the opposite direction, and stopped upon exiting $B(z,r/2)$. Then $\partial U_e \subseteq \eta^R_{w_1} \cup \eta^{\theta_0}_{z_1}$.
\item Let $\eta^{\theta_0}_{z_1}$ be the angle $\theta_0$ flow line of $h$ starting at $z_1$ and stopped upon exiting $B(z,3r/4)$. Let $\eta_{w_1}^L$ be the angle $+\pi/2$ flow line starting at $w_1$. Then it hits $\eta^{\theta_0}_{z_1}$ before exiting $B(z,r/2)$. Let $\overline{w}$ denote the first hitting point, and let $\overline{\eta}^R$ be the angle $-\pi/2$ flow line starting at $\overline{w}$, reflected off $\eta^{\theta_0}_{z_1}$ in the opposite direction, and stopped upon exiting $B(z,r/2)$. Then $\partial U_e \subseteq \overline{\eta}^R \cup \eta^{\theta_0}_{z_1}$.
\end{itemize}

