[Prop precompact2 of arXiv:2606.30517, '\textsc{Convergence towards Ideal Poisson--Voronoi tessellations with a focus on Diestel--'] Assume $0\neq\nu=\lim_{n \to \infty} \lambda_n\iota_{t_n}^* \mu$, where $t_n\to\infty$.
		Assume the growth conditions of (prop:precompact of the paper) and that, for some $a\in\mathbb R$, one has $\forall j\in\mathbb Z: \nu(\mathrm{Lip}_1^{a_j})=0$, where $a_j\coloneqq a+jr_0$. Then,
		for all $j\in\mathbb N$, 
		\begin{eqnarray}

			(p_1-1)p_1^{j-1}\leq &{\nu\left(\mathrm{Lip}_1^{[a_{j-1},a_j]}\right)}/{\nu\left(\mathrm{Lip}_1^{\leq a}\right)}&\leq (p_2-1)p_2^{j-1},\\

			p_1^{j}\leq &\nu\left(\mathrm{Lip}_1^{\leq a_j}\right)/ \nu\left(\mathrm{Lip}_1^{\leq a}\right)& \leq p_2^j.
		\end{eqnarray}
		In particular, if $p_1=p_2=p$, then $\forall j:\nu\left(\mathrm{Lip}_1^{[a_{j-1},a_j]}\right) = (p-1)p^{j-1+\xi}$, where $p^{\xi}= \nu(\mathrm{Lip}_1^{\leq a})$.

[Theorem thm:lehner-sc of arXiv:2606.14687, 'Lehner's operator norm formulas, semidefinite programming, and spiked matrix models'] {Lehner-1999-NormFreeOperatorMatrixCoefficients}}]

    Suppose $(\mathfrak{s}_i)_{i = 1}^n$ is a free semicircular family of operators on a suitable Hilbert space and let $\mathfrak{1}$ be the identity operator on that space.
    Then,
    \begin{align*}
      \Lambda_{\mathsf{sc}}(\bm A_0, \bm A_1, \dots, \bm A_n) &\colonequals \lambda_{\max}\left(\bm A_0 \otimes \mathfrak{1} + \sum_{i = 1}^n \bm A_i \otimes \mathfrak{s}_i\right) \\
      &= \inf_{\substack{\bm Z \in \mathbb{C}^{d \times d}_{\mathsf{herm}} \\ \bm Z \succ \bm 0}} \lambda_{\max}\left(\bm Z + \bm A_0 + \sum_{i = 1}^n \bm A_i\bm Z^{-1}\bm A_i\right). \addtocounter{equation}{1}\tag{\theequation} 
    \end{align*}
    Further, the infimum in (equation eq:lehner-sc of the paper) can be restricted to those $\bm Z$ for which the expression inside $\lambda_{\max}(\cdot)$ equals a scalar multiple of $\bm I_d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:tailrl-harmonic-decomposition of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] If $J_{\mathrm{TailRL{}}}(\theta;x)>-\infty$, then
\begin{equation}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{\text{Best-of-}k(\theta;x)-1}{k}.

\end{equation}
Under the regularity conditions of (lem:tailrl-regularity of the paper),
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{1}{k}
\nabla_\theta\text{Best-of-}k(\theta;x).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:char_velo of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\mathbf{q} \in \mathcal{Q}$ and $q_{k} > 0$ for some $k \in {\mathbb{N}}$. Then, we have
                \begin{align}
                    v^{\mathrm{eff}}_{k}\left(\mathbf{q}\right) = k v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right) + 2 \sum_{\ell = 1}^{k - 1} \ell \alpha_{\ell}\left(\mathbf{q} \right) v^{\mathrm{eff}}_{k-\ell}\left(\theta^{\ell} \mathbf{q} \right), 
                \end{align}
            and 
                \begin{align}
                    v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right) = \bar{r}_{k}\left(\mathbf{q}\right).
                \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:diag of arXiv:2504.18739, 'discrete analogues of second-order Riesz transforms'] For all $j=1,2,\ldots,d$,  
\begin{align}
    \|\mathcal{R}^{(jj)}\|_{\ell^p\to\ell^p}\le \gamma(p)=\|R^{(jj)}\|_{L^p\to L^p}.   
\end{align}
 Furthermore, there exist dimensional constants $C_1$ and $C_2$ such that 
\begin{align}
    C_1\|R^{(jj)}_{\mathrm{dis}}\|_{\ell^p\to\ell^p}
    \le \|\mathcal{R}^{(jj)}\|_{\ell^p\to\ell^p}
    \le C_2\|R^{(jj)}_{\mathrm{dis}}\|_{\ell^p\to\ell^p}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:ctyp-LB of arXiv:2608.19050, 'Online Permutation Embedding: \\ Optimal Stopping and Scaling Laws'] \begin{equation}
    c_\mathrm{typ} = \sup_{k \in \NN} \Big(\frac{2}{(k+1)(k+2)} \sum_{j=1}^k \sqrt{\beta_j^\mathrm{typ}}\Big)^2 \geq \sup_{k \in \NN} \Big(\frac{2}{(k+1)(k+2)} \sum_{j=1}^k \sqrt{\beta_j^-}\Big)^2.
\end{equation}

[Prop 12 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $a>0$, $M=a|\mathbb{B}_R|$ and consider a sequence $(u_l)_{l\ge 1}$ in $\Sigma_a$. For $l\ge 1$, we set $\lambda_l:=\|u_l\|_\infty^{1/d}$, 
\begin{equation}
	P_l(x):=\frac{1}{\lambda_l^d}u_l\left(\frac{x}{\lambda_l}\right)\,,\quad x\in \bar{\mathbb{B}}_{\lambda_l R}\,,
\end{equation} 
and
\begin{equation}
	\varphi_l(x):=\frac{1}{\lambda_l^{d-2}}\phi'\left(u_l\right)\left(\frac{x}{\lambda_l}\right)\,,\quad x\in \bar{\mathbb{B}}_{\lambda_l R}\,.
\end{equation}
Then there are $P\in C(\mathbb{R}^d)$ and $\varphi\in C^2(\mathbb{R}^d)$ such that, up to a subsequence, 
\begin{equation*}
	P_l\rightarrow P \ \text{ in }\ C(\mathbb{R}^d)\,,\qquad \varphi_l\rightarrow \varphi \ \text{ in }\ C^2(\mathbb{R}^d)\,.
\end{equation*}
Assume in addition that $\|u_l\|_\infty\to\infty$ as $l\to\infty$. Then both $P$  and $\varphi$ are non-increasing with respect to $r=|x|$ with $P(0)=1$, and $P$ has compact support $\bar{\mathbb{B}}_{\rho_0}$ for some $\rho_0\in (0,\infty)$. Furthermore, $\varphi$ satisfies
\begin{equation}
	-\Delta \varphi=\left(\frac{m-1}{m}\right)^{1/(m-1)}\varphi_+^{1/(m-1)}\ \text{ in }\ \mathbb{R}^d
\end{equation}
with $\varphi_+=\max\{\varphi,0\}$, 
\begin{subequations}
\begin{equation}
	P^{m-1} = \dfrac{m-1}{m} \varphi_+ \;\;\text{ in }\;\; \mathbb{R}^d\,, 
\end{equation} 
and
\begin{equation}
 	\varphi(x)=\left\{\begin{array}{ll}
	\dfrac{m}{m-1} \rho_0^{2-d} \zeta\left(\dfrac{x}{\rho_0}\right)\,, & x\in \bar{\mathbb{B}}_{\rho_0}\,,\\[20pt]
	\dfrac{M_c}{\sigma_d}\dfrac{|x|^{2-d}-\rho_0^{2-d}}{d-2} \,, & x\in \R^d\setminus\bar{\mathbb{B}}_{\rho_0}\,.
\end{array}\right.
\end{equation}
\end{subequations}
Finally, it holds that $M\ge M_c$, the critical mass $M_c$ being defined in~\eqref{Mc}.

