[Lemma 33 (Negligibility of remaining integrals) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose $x_{max}^+ < x_{max}^-$ (i.e., $\alpha_b \in (0, \pi)$). Let $0 \leq \alpha_0 < \alpha_b$. Then, for $\delta > 0$ small enough, there exist constants $D > 0$, $\e' > 0$, $\eta > 0$, and $r_0 > 0$ such that for all $r \geq r_0$ and all $\alpha \geq 0$ satisfying $|\alpha - \alpha_0| < \eta$, the following estimates hold:
\begin{equation}
\Big|\int_{R^\pm_{\delta}}\phi^{z_0}(x)\frac{\gamma(x,Y^+(x),Z^+(x))}{\partial_y\gamma_+(x,Y^+(x))}e^{-r(\cos(\alpha)x+\sin(\alpha)Y^+(x))}
 dx\Big| \leq De^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b) + \e')},
\end{equation}
and:
\begin{itemize}
    \item If $b_0 > 0,$ then \begin{equation}I_2(r\cos(\alpha),r\sin(\alpha)) \leq De^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b) + \e')}
    \end{equation}
    \item If $b_0 \leq 0,$ then
    \begin{equation}
\Big|\int_{R^\pm_{\delta}}\frac{e^{(a_0-a)x+b_0Z^+(x) - bY^+(x)}}{\partial_y\gamma_+(x,Y^+(x))}e^{-r(\cos(\alpha)x+\sin(\alpha)Y^+(x))}
 dx\Big| \leq De^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b) + \e')}
\end{equation}
\end{itemize}

