\rho_{i,j} = {\Big\vert} -\displaystyle{\frac{\psi_{i,j}}{\sqrt{\psi_{ii} \psi_{jj}}}}{\Big\vert},\quad
i\neq j,{\mbox{ and }}\rho_{ii}=1 {\mbox{ for }} i=j. 

\end{equation}
