[Thm product convolution and HL process of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] \begin{enumerate}[left=0pt]
\item(Alternating case)Let $\theta=(a_1,\ldots,a_n), \psi,\psi_1,\ldots,\psi_k$ be sequences (finite or infinite) of real numbers $b_j,b_j^{(1)},\ldots,b_j^{(k)}$ such that 

\begin{enumerate}[left=0pt]
\item For all integer signatures $\nu\prec_Q\lambda\in\Sig_n$, we have 

$$Q_{\lambda/\nu}(\psi;t^2),Q_{\lambda/\nu}(\psi_1;t^2),\ldots,Q_{\lambda/\nu}(\psi_k;t^2)\ge 0;$$

\item$\Pi_t(\theta';\psi)=\Pi_{t^2}(\theta;\psi),\Pi_t(\theta';\psi_1)=\Pi_{t^2}(\theta;\psi_1),\ldots,\Pi_t(\theta';\psi_k)=\Pi_{t^2}(\theta;\psi_k)<\infty$. Here $\theta'$ follows from (defi: change of specialization of the paper).
\end{enumerate} Suppose $\nu\in\Sig_n^+$ is distributed by the Hall-Littlewood measure of indeterminant $t^2$ with specializations $\theta,\psi$, and for all $1\le i\le k$, $\mu_i\in\Sig_{2n}^+$ is distributed by the Hall-Littlewood measure of indeterminant $t$ with specializations $\theta',\psi_i$ for each $i=1,2,\ldots,k$. Then for every fixed $\lambda,\lambda^{(1)},\ldots,\lambda^{(k)}\in\Sig_n^+$, we have the probability

$$\mathbf{P}(\mu_\tau\boxtimes_\theta\ldots\boxtimes_\theta\mu_1\boxtimes_\theta^{\alt}\nu=\lambda^{(\tau)},\quad\forall 0\le\tau\le k)$$
(here $\lambda^{(0)}=\lambda$) is equal to

\begin{equation}
\frac{Q_{\lambda}(\psi;t^2)Q_{\lambda^{(1)}/\lambda}(\psi_1;t^2)\cdots Q_{\lambda^{(k)}/\lambda^{(k-1)}}(\psi_k;t^2)P_{\lambda^{(k)}}(\theta;t^2)}{\Pi_{t^2}(\theta;\psi)\Pi_{t^2}(\theta;\psi_1)\cdots\Pi_{t^2}(\theta;\psi_k)}
\end{equation}

\item(Hermitian case)Let $\theta=(a_1,\ldots,a_n),\psi,\psi_1,\ldots,\psi_k$ be sequences (finite or infinite) of square of real numbers $b_j^2,(b_j^{(1)})^2,\ldots,(b_j^{(k)})^2$ such that
\begin{enumerate}
\item For all integer signatures $\nu\prec_Q\lambda\in\Sig_n$ such that $|\lambda|-|\nu|$ an even integer, we have $$Q_{\lambda/\nu}(\psi;-t),Q_{\lambda/\nu}(\psi_1^*;-t),\ldots,Q_{\lambda/\nu}(\psi_k^*;-t)\ge 0;$$

\item $\Pi_{-t}(\theta;\psi),\Pi_{t^2}(\theta';\psi_1)=\Pi_{-t}(\theta;\psi_1^*),\ldots,\Pi_{t^2}(\theta';\psi_k)=\Pi_{-t}(\theta;\psi_k^*)<\infty$. Here $\theta',\psi_1^*,\ldots,\psi_k^*$ follows from (defi: change of specialization of the paper).
\end{enumerate} Suppose $\nu\in\Sig_n^+$ is distributed by the Hall-Littlewood measure of indeterminant $-t$ with specializations $\theta,\psi$, and for all $1\le i\le k$, $\mu_i\in\Sig_n^+$ is distributed by the Hall-Littlewood measure of indeterminant $t^2$ with specializations $\theta',\psi_i$ for each $i=1,2,\ldots,k$. Then for every fixed $\lambda,\lambda^{(1)},\ldots,\lambda^{(k)}\in\Sig_n^+$, we have the probability

$$\mathbf{P}(\mu_\tau\boxtimes_\theta\ldots\boxtimes_\theta\mu_1\boxtimes_\theta^{\her}\nu=\lambda^{(\tau)},\quad\forall 0\le\tau\le k)$$
(here $\lambda^{(0)}=\lambda$) is equal to

\begin{equation}
\frac{Q_\lambda(\psi;-t)Q_{\lambda^{(1)}/\lambda}(\psi_1^*;-t)\cdots Q_{\lambda^{(k)}/\lambda^{(k-1)}}(\psi_k^*;-t)P_{\lambda^{(k)}}(\theta;-t)}{\Pi_{-t}(\theta;\psi)\Pi_{-t}(\theta;\psi_1^*)\cdots\Pi_{-t}(\theta;\psi_k^*)}
\end{equation}
\end{enumerate}

[Lemma 2 of arXiv:2607.22374, 'Asymptotic properties of the heat equation driven by stochastic measure'] (Lemma 3.1~\cite{radt09}, Lemma 2.3~\cite{radbook}) Let $\mu$ be an SM on $(\xx,\bb)$, $f_k:\ {\xx}\to \rr,\ k\ge 1$, be measurable functions such that
$\hat{f}(x)=\sum_{k=1}^{\infty} |{f_k}(x)|$ is integrable with respect to~$\mu$. Then
\begin{equation*}
\sum_{k=1}^{\infty}\Bigl(\int_{\xx} f_k\,d\mu \Bigr)^2<\infty\quad
\mbox{\textrm ~a.~s.}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 12 ({\cite{partA}}) of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] The \emph{half-signature bordism bicategory} $\Bord{sig/2}$ is the symmetric monoidal bicategory with 
    \begin{itemize}
        \item Objects and 1-morphism: as in $\Bord{sig}$ in Definition \ref{defn:bordsig}.
        \item 2-morphisms: Equivalence classes of pairs $(M,n)$ such that $n\in\mathbb{Z}$ has the same parity as 
        \begin{equation*}
            m(M) := b_1(\ol{M}) + b_0(\ol{M}) + \frac12 b_1(\ol{\parout M}) + b_0(\ol{\parout M}),
        \end{equation*}
        where $b_i$ denotes the $i^\text{th}$ Betti number, $b_i(X) := \dim H_i(X;\mathbb{R})$.
    \end{itemize}
    The composition of 1-morphisms, the vertical and horizontal composition of 2-morphisns, and the monoidal structure are as in in $\Bord{sig}$ in Definitions \ref{defn:bordsig} and \ref{defn:comp}.

[Lemma 3 of arXiv:2606.00945, 'Ising model and percolation: from hexagonal lattice to 3-12 lattice'] Let $z^{\diamond}$ be a midpoint of an edge in $\Omega_{\312}^\delta$ separating two dodecagons, we have 
\begin{align}
    \IO_{\312}^\delta(x;z^\diamond)=\IO_6^\delta\left(\frac{x^3+x^2}{x^3+1};z^\diamond\right).
\end{align}

[Definition 6 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Let $B$ be a standard Brownian motion on $\mbb R^d$ (which is started at
the origin). For every $x\in\mbb R^d$, we define
\begin{align}

B^x=x+B.
\end{align}
For any stochastic process $Z$ (e.g., $B^x$), we denote the hitting time
\[\tau_D(Z)=\inf\{s\geq0:Z(s)\not\in D\}.\]
Then, we define the total mass of $u_{\ka,\eps}$ (which we denote $\msf M_{\ka,\eps}(t)$) as
\begin{align}

\int_Du_{\ka,\eps}(t,x)\d x:=\msf M_{\ka,\eps}(t)=\int_D\mbf E_B\left[\mbf 1_{\{\tau_D(B^x)>t\}}\mr e^{\ka\int_0^t\xi_\eps(t-u,B^x(u))\d u}\right]\d x
\end{align}
for every $\eps,t>0$, where we assume that $\xi$ and $B$ are independent,
and $\mbf E_B$ means that we are only taking the expectation with respect to $B$---i.e., conditional on $\xi$.
(This is clearly well-defined since $\xi_\eps$ is continuous.)

[Theorem of arXiv:2608.10415, 'Continuous random variables'] The basic random matrices $Z\in M_N(L^\infty(X))$ are as follows:
\begin{enumerate}
\item In the case $N=1$ the random matrix is a usual random variable, $f\in L^\infty(X)$, automatically normal, and its law as defined above is the usual law.

\item In the case $X=\{.\}$ the random matrix is a usual scalar matrix, $A\in M_N(\mathbb C)$, and in the normal case, the law is $\mu=\frac{1}{N}\left(\delta_{\lambda_1}+\ldots+\delta_{\lambda_N}\right)$.
\end{enumerate}

[Lemma 21 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] Let $\mathbf{w} := \sqrt{\dt} G_{\ell+1}^m(Y_{\ell}^i)$ and let $\mathcal{E}_{\mathrm{mlp}}$ be the corresponding MLP remainder from \eqref{eq:X_step_expansion}. Then
    \begin{equ}
        |\mathcal{E}_{\mathrm{mlp}}| \leq \mathsf c |\mathbf{w}|^3
    \end{equ}
    almost surely.

