body:
[Theorem thm:A of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha\in (0,d)$ and $(\zeta,\gamma)\in R_3$ (see Figures (diagram2 of the paper) and (diagram3 of the paper)). Then $(S_n)_{0\leq n \leq N}$ has end-to-end fluctuations of order $N$ under ${\ensuremath{\mathbf P}} _N$, and as $N\to\infty$, we have the following convergence in distribution to a well-defined random variable, 
\begin{equation}
\frac{1}{ \beta_N N^{d/\alpha}} \log {\ensuremath{\mathbf Z}} _N  \stackrel{(d)}{ \longrightarrow} \hat{\ensuremath{\mathcal T}} _\infty:= \sup_{s\in {\ensuremath{\mathcal D}} , \hat{\mathrm{E}}\mathrm{nt}(s) <+\infty}\pi(s).
\end{equation}
Here
\begin{equation}
\hat{\mathrm{E}}\mathrm{nt}(s):=\inf_{\varphi\in\Phi}\int_0^1 J_d((s\circ\varphi)'(t)){\ensuremath{\mathrm d}}  t,
\end{equation}
where $J_d(\cdot)$ is a rate function obtained by
\begin{equation}
J_d(x):=-\lim\limits_{N\to\infty}\frac{1}{N}\log{\ensuremath{\mathbf P}} (S_N=\lfloor xN\rfloor)
\end{equation}
and
\begin{equation}
\Phi:=\{\varphi:[0,1]\overset{\rm onto}{\longrightarrow}[0,1]: \varphi~\text{is non-decreasing and a.e. differentiable}\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Propn 17 of arXiv:2604.27205, 'An Analysis of the Diaconis-Holmes-Neal Markov Chain Sampler Under Generalized Unimodal Un'] Suppose $\{R_l\}_{l = 1}^{r(n)}$ is the sequence of return times (in steps) of the intermediate returns contained in any overshoot. Then, with probability bounded below by a positive constant and for some constant $\tilde{c} > 4$,
        \begin{equation}
            r(n) < \frac{\tilde{c}d^{**}m_{j^*}(n)}{4z'} 
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$. For any $0 \le \theta \le d$ and $x, y \in \mathbb{R}^d$,
        \begin{equation}

            \mathbb{E} \delta(W_t -x) |W_t - y|^{-\theta} \le C |t|^{-(d-\theta)/2} |x - y|^{-\theta} |x|^{-\theta}.
        \end{equation}
        Similarly, for any $0 < k < d$ and $0 \le \theta \le k/2$,
        \begin{align}

        \mathbb{E} |W_t -x|^{-k} |W_t - y|^{-k} &\le C |t|^{-k/2} |x-y|^{-k}, \\

            \mathbb{E} |W_t -x|^{-k} |W_t - y|^{-\theta} &\le C |t|^{-(k-\theta)/2} |x|^{-\theta}|x-y|^{-\theta}.
        \end{align}
        Here, $C$ may depend on $d$ and $k$ but not on $t$, $x$, $y$, or $\theta$.

[Proposition prop:main of arXiv:2605.03703, 'Scaling Limits of Bivariate Nearly-Unstable Hawkes Processes and Applications to Rough Vol'] Under Assumption~(ass:kernels of the paper), set
\[
\nu_i=(m_i\lambda_i)^{-1/2},
\qquad
\gamma_{12}=\frac{m_1}{m_2\lambda_1},
\qquad
L_{12}=b_\infty^{12}\|\psi^{12}\|_1(K_1*K_2).
\]
Then:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $V^{T,2}$ admits the decomposition
\begin{equation}
V_t^{T,2}=D_t^T+\mathcal S_t^T+\mathcal C_t^T,
\end{equation}
where
\begin{equation}
\mathcal S_t^T=\frac{1-a_T^2}{m_2T^{\alpha_2-1}}
\int_0^{Tt}\psi_T^2(Tt-u)\,dM_u^{T,2},
\end{equation}
\begin{equation}
\mathcal C_t^T=\frac{1-a_T^2}{m_2T^{\alpha_2-1}}
\int_0^{Tt}\Psi_T^{12}(Tt-u)\,dM_u^{T,1}.
\end{equation}
Moreover $\langle\mathcal S^T,\mathcal C^T\rangle\equiv0$.

\item The effective cross-kernel is
\begin{equation}
L_{12}=b_\infty^{12}\|\psi^{12}\|_1(K_1*K_2).
\end{equation}
It belongs to $L^2(\mathbb R_+)$ and satisfies
\begin{equation}
L_{12}(t)\sim C_{12}t^{\alpha_1+\alpha_2-1},
\qquad t\downarrow0,
\end{equation}
with
$C_{12}=b_\infty^{12}\|\psi^{12}\|_1/
(\tilde\delta_1\tilde\delta_2\Gamma(\alpha_1+\alpha_2))$.

\item The covariance of the limiting process is
\begin{equation}
\mathrm{Cov}(V_t^1,V_t^2)
=\gamma_{12}\nu_1^2
\int_0^tK_1(t-s)L_{12}(t-s)b_1(s)\,ds.
\end{equation}
In the stationary comparison $b_1(s)\equiv\bar V^1$ this becomes
\begin{equation}
\mathrm{Cov}(V_t^1,V_t^2)
=\gamma_{12}\nu_1^2\bar V^1
\int_0^tK_1(u)L_{12}(u)\,du.
\end{equation}
\end{enumerate}

