[Theorem 35 (Young--L\'{o}eve's inequality) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Given $x\in C^{\textup{$p$-var}}([0,T],\mathbb{R}^d)$ and $y\in C^{\textup{$q$-var}}([0,T];L(\mathbb{R}^d,\mathbb{R}^e))$, where $L(\mathbb{R}^d,\mathbb{R}^e)$ denotes the space of linear functional from $\mathbb{R}^d$ to $\mathbb{R}^e$, there exists a unique (indefinite) Young integral of $y$ against $x$ denoted by $\int_0^\cdot ydx$. Moreover, the indefinite Young integral has finite $p$-variation and
    \begin{equation*}
        \Bigg|\int_0^\cdot ydx\Bigg|_{p-\textup{var};[s,t]} \leq C|x|_{p-\textup{var};[s,t]}\left(|y|_{p-\textup{var};[s,t]} + |y_0|\right),
    \end{equation*}
    where $C=C(p,q)$.

[Lemma 3 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $1\le q<\infty$. Assume that $|F|\in L^1_{\loc}(\Omega_T)$ and that $u\in  L^q_{\loc}(0,T;W^{1,q}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$.
Then there exists a constant $c=c(n,q,L)$ such that
	\begin{equation}
    \fiint_{Q}\frac{|u-u_{Q }|^{q}}{\rho^{q}}\,dz
            \le c\fiint_{Q}|\na u|^{q}\,dz       
            +c\left(\fiint_{Q } |F| \,dz\right)^{q}
    \end{equation}
    for every parabolic cylinder $Q=Q_{\rho} \Subset\Omega_T$.

[Lemma lem:integrationbytails of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Let $f$ be a polynomial of degree $\ell \ge 2$ in $i.i.d.$ standard Gaussian inputs $\mathbf{x}$ with $\Expectedsub{\mathbf{x}}{f(\mathbf{x})} = 0$ and variance $\sigma \coloneqq \sqrt{ \mathrm{Var}{f(\mathbf{x})}}$. Let further $c$ be the constant in the exponent of the tail bound from (prop:hypercontractivity of the paper) and assume that $|f(\mathbf{x})| \le U$ for all $\mathbf{x} \in S$ where $S$ is some measurable set. Assume $U\sigma^{\frac{2}{\ell-2}} \le \frac{c^2}{4}$ if $\ell \ge 3$, and that $\sigma \le \frac{c}{2}$ if $\ell = 2$. Note that in case $\ell = 2$, we allow $U = \infty$. Then, there is a constant $C > 0$ independent of $f$ such that \begin{align*}
        \Expectedsub{\mathbf{x}}{ \mathds{1}( \mathbf{x} \in S) \exp(f(\mathbf{x})) } \le 1 + (C \ell)^{\frac{\ell + 2}{2}} \sigma.
    \end{align*}

