[Definition traffic freeness of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] We say that $\mathbf{A}_{N}^{(1)},\cdots,\mathbf{A}_{N}^{(L)}$ are \emph{asymptotically traffic independent} whenever $\mathbf{A}_{N}:=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ converges in traffic distribution and for any *-test graph $T=(V,E,\gamma,\epsilon)$,
        \begin{equation}
            \tau_{N}\left(T(\mathbf{A}_{1}^{(N)},\cdots,\mathbf{A}_{L}^{(N)})\right)\underset{N\rightarrow\infty}{\longrightarrow}\sum_{\substack{\pi\in\mathcal{P}(V) \\ \mathrm{s.t.}\mathcal{GCC}(T^{\pi}) \\ \text{is a tree}}}\prod_{S\in\mathcal{CC}(T^{\pi})}\lim_{N\rightarrow\infty}\tau_{N}^{0}\left(S(\mathbf{A}_{N}^{(\ell(S))})\right),
        \end{equation}
    where $\ell(S)$ is the index of the family of the labels of the colored component $S$. Since the injective traces in the product can also be written in terms of (non-injective) traces, asymptotic traffic independence entirely characterizes the limiting traffic distribution of $\mathbf{A}_{N}=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ in terms of the traffic distributions of the $\mathbf{A}_{N}^{(l)}$'s.

[Proposition Prop3.1 of arXiv:2602.23124, '\textsc{ Necessary and Sufficient Conditions for the Lacunary/Hereditary Laws of Large Num'] On a given probability space $\,(\Omega, \mathcal F, {\mathbb P})$, consider a sequence of real-valued, measurable functions $f_1, f_2, \cdots$   containing a    subsequence  $\,f_{k_1}, f_{k_2}, \cdots \,$ with the  stable convergence    (equation B0 of the paper).   

\smallskip
\noindent
{\bf (i)}  Suppose  that   $\,\lim_{N \to \infty} \big(  \frac{1}{\,N\,} \sum_{n=1}^N f_{k_n}   - D_N \big) =\,0 \,~ \text{holds in} ~{\mathbb P}\text{\,--\,probability}$ for {\rm some}   $\,{\cal T}-$measurable correctors    $\,D_1, D_2, \cdots\,,$ along this subsequence  $\,f_{k_1}, f_{k_2}, \cdots\,$ and    all its subsequences.  Then,    the approximating exchangeable  functions    $\,g_1, g_2, \cdots\,$  of (equation A7 of the paper)      also satisfy
 \begin{equation} 

   \lim_{N \to \infty} \bigg(  \frac{1}{\,N\,} \sum_{n=1}^N g_{n}   -   D_N \bigg) =\,0 \quad \text{in} ~{\mathbb P}\text{\,--\,probability}  \end{equation}
   with  the  same  $\,{\cal T}-$measurable      $\,D_1, D_2, \cdots\,,$ as well as with the ${\cal T}_*-$measurable $\, \Delta_1, \Delta_2, \cdots\,$  of (equation 6.2 of the paper).  



\smallskip
\noindent
{\bf (ii)}  In the same setting,   suppose that the subsequence $\,f_{k_1}, f_{k_2}, \cdots,$  and all its subsequences,  satisfies  $\,\lim_{N \to \infty}    \frac{1}{\,N\,} \sum_{n=1}^N f_{k_n}    = 0 \,,~   {\mathbb P}-\text{a.e.}$ Then the   exchangeable    $\,g_1, g_2, \cdots\,$  of (equation A7 of the paper)     also have this property:   
 \begin{equation} 

  \lim_{N \to \infty}    \frac{1}{\,N\,} \sum_{n=1}^N g_{n}  \,   =\,0 \,,~\quad  {\mathbb P}-\text{a.e.}    
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2608.31099, '\bf On (fake) Stationarity in Stochastic Volterra Equations with Affine Drift and Regular '] Let  Assumptions~\eqref{assum:convolKernel} and~\eqref{assum:CoefsVolterra} be in force and consider the Volterra process~\eqref{eq:Volterra}. Let $T\ge0$ and $p>\max\{2,\frac1\delta\vee\frac{1}{\widehat\theta}\vee\frac1\theta\}$ be such that $\sup_{t\le T} \E[ |X_t|^p ]$ is finite. Then $X$ admits a version which is H\"older continuous on $[0,T]$ of any order $a<\delta\wedge\widehat\theta\wedge\theta-\frac1p$. Denoting this version again by $X$, one has
		\begin{equation} 
			\E\left[ \left( \sup_{s\neq t\in[0,T]} \frac{|X_t-X_s|}{|t-s|^a} \right)^p \right] \le C_{a,p, K, b,\sigma,T}\,\Big[\big(1+ \E[\sup_{0\leq u\le T} |x_0(u)|^{p} ]\big)\vee \big(1+\sup_{0\leq u\le T} \E[  |X_u|^{p} ]\big)\Big].

		\end{equation}
		for all $a\in[0,\delta\wedge\widehat\theta\wedge\theta-\frac1p)$ and $C_{a,p, K, b,\sigma,T}$, a positive constant that only depends on $a$, $p$, $K$, $b$,$\sigma$ and $T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 51 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $A,D$ satisfy \eqref{eq:costanti}. Also let $q$ be a real number and $k \ge 0$ be an integer satisfying 
		\begin{equation}

			q \in [N^{A\delta-1}, \varepsilon_0], \quad k \le \ell_0 (q) + 5.
		\end{equation}

		\noindent Further let $q' \ge 0$ satisfy
		\begin{flalign}

			q' \in [q - 2^k N^{(D+2)\delta-1}, q - 2^{k}  N^{(D-2) \delta-1}]; \qquad \mathsf{t} = q'^{-1} k 2^k N^{1+6A\delta}.
		\end{flalign} 

		\noindent Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu \in \mathcal P^+$ (recall Definition \ref{def:P+}) and assume that, w.o.p. under $\mu$, 
		\begin{flalign}

			\begin{aligned} 
				& H_0 (w) \le \mathcal{H}_{q} (w) + N^{\delta-1}, \qquad  \text{for each $w \in \bigcup_{\ell=1}^{k+1} \mathcal{A}_{\ell}^{q}$ }. 
			\end{aligned}
		\end{flalign}

		\noindent Then we have w.o.p. that
		\begin{flalign}

			H_t (z) \le \mathcal{H}_{q'} (z), \qquad \text{for each $z \in \bigcup_{\ell = 1}^k \mathcal{A}_{\ell}^{q'}$ and $t \in [\mathsf{t}, N^5]$}.
		\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] Assume $k>2$.  For all sufficiently small $\eps>0$, the form $\omega_\eps$ defined by \eqref{gt:eq:approximate-metric} extends to a smooth K\"ahler metric on $\widetilde X$, and
\begin{equation}
  [\omega_\eps]=\pi^*[\omega]-\eps^2[E].
\end{equation}
Moreover:
\begin{enumerate}[label=\textup{(\roman*)}]
\item on the exterior region, \(\omega_\eps=\omega\);
\item on the outer annulus, for every fixed $j\ge0$,
\begin{equation}
  \abs{\nabla^j\left[
  \eps^2\gamma_2\psi_k(\eps^{-2}d^2)
  \right]}
  \le C_j\eps^{2k-2}r_\eps^{4-2k-j};
\end{equation}
\item on the inner annulus, potentials for $\eps^{-2}\omega_\eps$ and $\omega_k$ in the rescaled coordinates are respectively
\begin{align*}
  F&=|Z|^2+|W|^2
      +\eps^{-2}\Phi(\eps Z,\eps W)
      +\psi_k(\eps^{-2}d^2),\\
  F_{\mathrm{prod}}&=|Z|^2+|W|^2+\psi_k(|Z|^2),
\end{align*}
and, on the rescaled coordinate balls specified above,
\begin{equation}
  \abs{\nabla_{Z,W}^j(F-F_{\mathrm{prod}})}
  \le C_j\eps^{j-2}d^{3-j}
  \qquad(2\le j\le6).
\end{equation}
In particular, $\eps^{-2}\omega_\eps$ is uniformly equivalent to $\omega_k$ there;
\item on the blowup region, in the coordinates
\eqref{gt:eq:blowup-coordinates},
\[
  \eps^{-2}\omega_\eps=\omega_k+O(\eps)
\]
in $C^\ell$ on compact subsets of each blowup chart, for every fixed $\ell$.  In particular, $\eps^{-2}\omega_\eps$ converges locally smoothly to $\omega_k$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lyap:symLemma of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $(\mu,\gamma, \mathbf{X})$ be a solution to the $\kappa$-MLFE{} on $[0, T]$ with potentials $(U, W)$ and initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$. Let $f : \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ be a measurable function such that for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have
\begin{equation}
    \mathbb E\Big[\big|f\big(X_0(s), X_v(s)\big)\big|^2 + \big|f\big(X_v(s), X_0(s)\big)\big|^2 \Big] < \infty.

\end{equation}
Then the following properties hold:
\begin{enumerate}
    \item For $u \in \{0, \ldots, \kappa\}$, let $\bar{u} = 0$ when $u = 0$ and $\bar{u} = 1$ otherwise. Given any $v \in \{1, \ldots, \kappa\}$ and $u \in \{0, v\}$, for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have 
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{u} \log \mu_s\big(\mathbf{X}(s)\big)\Big] = \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{\bar{u}} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
    \item For all $v \in \{1, \ldots, \kappa\}$ and $s \in \ensuremath{\mathbb{R}}_+$ we have
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{0} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big] = \mathbb E\Big[f\big(X_v(s), X_0(s)\big) \nabla_{1} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
\end{enumerate}

