[Theorem 1 of arXiv:2609.02104, 'Conformal Ricci Curvature and Spectral Estimates'] Let $\Omega\Subset M$ be a smooth bounded connected domain in an $n$-dimensional Riemannian manifold, $n\geq2$. Suppose that there exist
$\sigma\in[0,\frac{4}{n-1}),$ $f\in C^\infty(\Omega)$ with $f>0$ and $\kappa\in\mathbb R$ such that
\[
\Ric_g^{f,\sigma}\geq-\kappa g
\quad\text{on }\Omega.
\]
Then
\begin{equation}
\lambda_1(\Omega)
\leq
\frac{n-1}{D_\sigma}
\left[
\sqrt{
\kappa+
\frac{4\pi^2\bigl((n-1)-(n-2)\sigma\bigr)}
{D_\sigma r_\Omega^2}
}
+
\frac{2\pi|n-3|}
{r_\Omega\sqrt{(n-1)D_\sigma}}
\right]^2.
\end{equation}
where $D_\sigma:=4-(n-1)\sigma.$
The quantity under the square root is nonnegative under the above assumptions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:Rcrit of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For a fixed $\gamma > 0$, the \textbf{critical correlation measure} $R_{k}^{\mathrm{(Crit)}}(\gamma; dx_1, \dots, dx_k)$ is the unique Radon measure on $\mathbb{R}^k$ whose mixed moments are determined by its sinc transform. Specifically, for any $t_1, \dots, t_k > 0$ and $m \in \{4, 8, 10\}$, the measure satisfies
\begin{equation}
    \int_{\mathbb{R}^k} \prod_{j=1}^k \frac{\sin^{m} (t_j\sqrt{-x_j})}{(t_j\sqrt{-x_j})^{m}} \, R_{k}^{\mathrm{(Crit)}}(\gamma; dx_1, \dots, dx_k) = \sum_{\Pi \in \mathscr{P}([k])} \prod_{\pi \in \Pi} \tau_{\gamma}(\pi),
\end{equation}
where the right-hand side is expressed via the partition sum of limiting cumulants, with the critical cumulant limit $\tau_{\gamma}$ given by the sum over connected typical diagrams
\begin{equation*}
    \tau_{\gamma}(\{t_j\}_{j \in \pi}) = \sum_{\Gamma \in \mathcal{T}_{|\pi|}} \gamma^{|E|-|V|} \int \left[ \prod_{j \in \pi} \mathcal{Q}_m(\xi_j) \right] \mathcal{F}^{\mathrm{(Crit)}}_{\Gamma}( \{\xi_j t_j\}_{j\in \pi};\gamma^\alpha) \prod d\xi_j.
\end{equation*}

[Theorem 8 (Solutions to the PDE system~\eqref{eqn: asymp-Schro}) of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Suppose $\rho_0,\rho_1, \cdots, \rho_K\in\m C^\infty(\mb T^d)$ and satisfy $\rho_0 > 0$,
\begin{align*}
\int_{\mb T^d}\rho_0(x)\,\dd x = 1,
\quad\mx{and}\quad
\int_{\mb T^d}\rho_k(x)\,\dd x = 0 
\quad\forall\,k\in[K].
\end{align*}
Then there exist $\{u_k\}_{k=0}^{K}$ and $\{v_k\}_{k=0}^{K}$ satisfying Equations~\eqref{eqn: asymp-Schro}, that is,
\begin{align*}
\{(u_k, v_k): k=0, 1, \cdots, K\} = \schro(\rho_0, \rho_1, \cdots, \rho_K).
\end{align*}

Moreover, we have:
\begin{itemize}
\item $u_0$ and $v_0$ satisfy
\begin{align*}
\nabla\cdot(\rho_0\nabla\log u_0) &= \rho_1 - \frac{\Delta\rho_0}{2},\\
\nabla\cdot(\rho_0\nabla\log v_0) &= -\rho_1 - \frac{\Delta\rho_0}{2}.
\end{align*}
As a result, there exists constants $L_u, L_v \in(0, 1)$ depending only on $\rho_0$ and $\rho_1$, such that 
$L_u \leq u_0(x) \leq L_u^{-1}$ and $L_v \leq v_0(x) \leq L_v^{-1}$ hold for all $x\in\mb T^d$.

\item For every $1\leq k\leq K-1$, $u_k$ is the solution of the elliptic PDE
\begin{align*}
\nabla\cdot\Big(\rho_0\nabla\frac{u_k}{u_0}\Big) = \frac{\rho_0 F_{k-1}}{u_0},
\end{align*}
where $F_{k-1}$ is a function depending only on $u_0, \cdots, u_{k-1}$, $v_0, \cdots, v_{k-1}$, and $\rho_0, \rho_1, \cdots, \rho_{k+1}$.

\item 

For every non-negative integer $k<K$, we have $u_k, v_k\in\m C^\infty(\mb T^d)$, and for each  $\alpha\in(0, 1)$ and $s\in\mb N^\ast$,
\begin{align*}
    \|u_k \|_ {\m C^{s+2,\alpha}},
     \|v_k \|_ {\m C^{s+2,\alpha}} \le C
\end{align*}
for the constant $C$  depending only on $d, s, k,\alpha$ and $\|\rho_0\|_{\m C^{s+2k+2,\alpha}}, \|\rho_1\|_{\m C^{s+2k,\alpha}}, \cdots, \|\rho_{k+1}\|_{\m C^{s,\alpha}}$.

\end{itemize}
\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d:ca of arXiv:2505.11389, '\bf The Poisson Multiplication Formula'] {\rm Consider $(k_1,\dots,k_m)\in \mathbb{N}^m$, as well as symmetric kernels $f_i\in L^2_s (\mu^{k_i})$, $i=1,\dots,m$. We say that the kernels $f_1,\dots, f_m$ verify {\bf Condition A} if either (a) $k_1=\cdots = k_m = 0$, or (b) $f_i\in L^1(\mu^{k_i})$ for all $i = 1,\dots,m$ and, for every $\sigma \in \Pi(k_1,\dots,k_m)$, one has that
\begin{equation}
\int_{\mathcal{Z}^{|\sigma|}} \Big| (f_1\otimes \cdots \otimes f_m)_\sigma \Big| d\mu^{|\sigma |} <\infty.
\end{equation}
}

