body:
[Lemma prop:concentration of arXiv:2411.04116, 'Poisson genericity in numeration systems with exponentially mixing probabilities'] Let $\mu$ be an invariant and exponentially $\psi$-mixing measure on $\Omega^{\mathbb N}$. 
Let $k\in \mathbb N$ be  large enough and $j\ge 0$. Also, let $S\subset \mathbb R^{+}$ be a finite union of bounded intervals and denote by $\sup S$ the supremum of $S$. 
\begin{enumerate}

\item   
For  
 $\varphi_{k,S}:\Omega^\mathbb N \to \mathbb R$, 
$
\varphi_{k,S}(x)={\mathds{E}}_{\mu_k}[M_k^x(S)]
$ 
we have, for any $t>0$,
\begin{align*}
    \mu\pare{\{ x\in \Omega^\mathbb N: \abs{\varphi_{k,S}(x) - {\mathds{E}}_\mu [\varphi_{k,S}] } \geq t \}} 
    \leq 
    2\exp\pare{
\frac{-t^2}
    {\|\Delta\|^28k^4 (\sup S) K^2 \rho^k}}.
\end{align*}

\item For  
 $\varphi_{k,j,S} : \Omega^{\mathbb N} \to [0,1]$,
$
\varphi_{k,j,S} (x)=\mu_k(\{w\in\Omega^k: M_k^x(w)(S)=j\})
$
we have, for any $t > 0$,
\begin{align*}
    \mu\pare{\{ x\in \Omega^\mathbb N: \abs{\varphi_{k,j,S}(x) - {\mathds{E}}_\mu [\varphi_{k,j,S}] } \geq t \}} 
    \leq 
    2\exp\pare{{\frac{-t^2}{\|\Delta\|^28 k^2 (\sup {S})     K^2 \rho^k} }}.
\end{align*}

\end{enumerate}
The numbers   $\rho\in (0,1)$, and $K>0$
 are the contraction ratio and the constant 
given in (equation eq:rhoK of the paper); and
$\Delta$ is the matrix of $\eta$-mixing coefficients associated with the mixing measure $\mu$.

[Lemma lem:plbXj of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Under Assumption (assump:initdiff of the paper), for all $T \in [0,\infty)$ and $\xi \in (0,\infty)$,
\begin{equation} 
\sup_{j \in \mathbb{Z}, u \in \mathbb{R}} e^{u\xi}\mathbb{P}( \inf_{0 \leq s \leq T} X_j(s) - x_j \leq -u ) < \infty,
\end{equation}
and 
\begin{equation} 
\sup_{j \in \mathbb{Z}, u \in \mathbb{R}} e^{u\xi + c_0(\xi) j} \mathbb{P}( \inf_{0 \leq s \leq T} X_j(s) \leq -u ) < \infty,
\end{equation}
where $c_0(\xi)$ is the quantity appearing in (equation eq:posbd of the paper).

