[Theorem thm:2lift of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $\widetilde G_N$ be the  random 2-lift of a uniformly random $d$-regular graph with $d\gg N^{2/3+\tau}$, then
  \begin{equation}
    N^{\frac{2}{3}}\Bigl(\tfrac{\lambda_2(\widetilde G_N)}{\sqrt{d-1}} - 2\Bigr)
    \;\xrightarrow[N\to\infty]{\mathrm{D}}\;
    \mathrm{TW}_1.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 18 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We introduce the following two paths:
\begin{enumerate}
\item We define the \emph{(one-parameter) bracket} $[ \mathbf{X} ] : [0,T] \to {\rm Sym}(V \otimes V)$ as
\begin{align}
[ \mathbf{X} ]_t := X_{0,t} \otimes X_{0,t} - 2 \, {\rm Sym}(\bbx_{0,t}), \quad t \in [0,T].
\end{align}
\item We define the \emph{(two-parameter) bracket} $[ \mathbf{X} ] : [0,T]^2 \to {\rm Sym}(V \otimes V)$ as
\begin{align}
[ \mathbf{X} ]_{s,t} := X_{s,t} \otimes X_{s,t} - 2 \, {\rm Sym}(\bbx_{s,t}), \quad s,t \in [0,T].
\end{align}
\end{enumerate}

[Corollary 27 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] In the orange region, for $0\le m\le p$, it holds
    \begin{align} 
       \hat{P}_{a,y,\theta}(z)=\sum_{i=0}^m\frac{\theta^\frac{i(i+1)}{2}}{i!}\left(\frac{-zy}{a+1}\right)^ic_{m-i,0},~~~~~y\in A_m,
    \end{align}
    where $c_{0,0}=\frac{1}{1-zF(z)}$ and \begin{align}
            c_{k,0}
