[Cor thm:Corner of the invertible matrix of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $t=1/q$, and $m>n\ge 1$ be integers.
\begin{enumerate}[left=0pt]
\item(Alternating case)\begin{enumerate}[left=0pt]
\item Let $A$ be the top left $2n\times2n$ submatrix of a Haar-distributed element of $\Alt_{2m}(\mathfrak{o})\cap \mathrm{GL}_{2m}(\mathfrak{o})$. Then $\SN^{\alt}(A)\in\Sig_n^+$ has distribution given by the Hall-Littlewood measure $\mathbf{P}_{2n<2m}^{\alt}(\cdot\mid0)$ defined by

\begin{equation}
\mathbf{P}_{2n<2m}^{\alt}(\lambda\mid0)=\frac{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)Q_\lambda(t,t^3,\ldots,t^{2m-2n-1};t^2)}{\Pi_{t^2}(1,t^2,\ldots,t^{2n-2};t,t^3,\ldots,t^{2m-2n-1})}.
\end{equation}

\item Let $A$ be the top left $(2n+1)\times(2n+1)$ submatrix of a Haar-distributed element of $\Alt_{2m}(\mathfrak{o})\cap \mathrm{GL}_{2m}(\mathfrak{o})$. Then $\SN^{\alt}(A)\in\Sig_n^+$ has distribution given by the Hall-Littlewood measure $\mathbf{P}_{2n+1< 2m}^{\alt}(\cdot\mid0)$ defined by

\begin{equation}
\mathbf{P}_{2n+1< 2m}^{\alt}(\lambda\mid0)=\frac{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)Q_\lambda(t^3,t^5,\ldots,t^{2m-2n-1};t^2)}{\Pi_{t^2}(1,t^2,\ldots,t^{2n-2};t^3,t^5,\ldots,t^{2m-2n-1})}.
\end{equation}
\end{enumerate}

\item(Hermitian case)Let $A$ be the top left $n\times n$ submatrix of a Haar-distributed element of $\Her_m(\mathfrak{o})\cap \mathrm{GL}_m(\mathfrak{o})$.  Then $\SN^{\her}(A)
\in\Sig_n^+$ has distribution given by the Hall-Littlewood measure $\mathbf{P}_{n<m}^{\her}(\cdot\mid0)$ defined by

\begin{equation}
\mathbf{P}_{n<m}^{\her}(\lambda\mid0)=\frac{P_\lambda(1,-t,t^2,\ldots,(-t)^{n-1};-t)Q_\lambda(t,-t^2,\ldots,-(-t)^{m-n};-t)}{\Pi_{-t}(1,-t,t^2,\ldots,(-t)^{n-1};t,-t^2,\ldots,-(-t)^{m-n})}.
\end{equation}
\end{enumerate}

