[Lem finite-direction-renewal-bound of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] For every fixed $\beta\geqslant0$ and $\eta>0$, there are constants
$C_{\beta,\eta}<\infty$ and $\ell_0<\infty$ such that, for all
$\ell\geqslant\ell_0$ and all $t\geqslant0$,
\begin{align}
\E\sum_{v\in\mathcal{N}_t^{(\ell)}}e^{\beta \mathsf{p}_\ell(v)}
\leqslant
C_{\beta,\eta}
\exp\{(\gk_\theta(\beta)+\eta)t\}.

\end{align}
Here $\gf(0)=1$ and hence $\gk_\theta(0)=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:infinite-wass-d3 of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let  $ \mathsf{P}$ be a $ L^{ 2}_{ \text{\rm{loc}}}$  stationary point process in $ \mathbb{R}^{ d},d\geqslant 2$.  \begin{itemize}
\item [(i)]  Assume one of the equivalent conditions
 \begin{align}

  \int_{ }  R^{ -2d + 1}\textrm{Var}\left(\mathsf{P}(B_{ R})\right)dR<\infty   \\

 \mathsf{S}_{ \mathsf{P}}(\|u\|^{ -2}1_{ 0<\|u\|<1})<\infty .
\end{align}
 Then $ \mathsf{P}$ is a $ 2$-perturbed lattice
\item [(ii)]  Assume $  \textrm{Var}\left(\mathsf{P}(B_{ R})\right) = O(R^{ d})$. Then $ \mathsf{P}$ is a $ p$-perturbed lattice for $ p<d/2$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 81 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $X$ be the right process fixed above with its transition function satisfying \eqref{eq:L^1(mu)}, and $K$ be a bounded kernel on $(E,\mathcal{B})$ which satisfies $\bf (H_K^\mu)$, and set $c:=K1$. 
    Let $X^K$ be the right process provided by \Cref{prop:perturbation}.
    Then the following assertions hold.
    \begin{enumerate}
        \item[(i)] The transition function of $X^K$ extends to a $C_0$-semigroup on $L^1(\mu)$, whose generator is 
        \begin{equation*}
            L_1-c+K, \quad D(L_1-c+K)=D(L_1).
        \end{equation*}
        \item[(ii)] Let $f\in D(L_1)\cap b\mathcal{B}$ be finely continuous.
        Then there exists a set $\tilde{E}\in\mathcal{B}$ such that $E\setminus \tilde{E}$ is $\mu$-inessential and for every $x\in \tilde{E}$
        \begin{equation*}
        \mathbb{E}^K_{x}\left\{\int_0^{t} \left|L_1f-cf+Kf\right|(X^K(r))\; dr
               \right\}<\infty, \quad t\geq 0,
        \end{equation*}
        and the process
        \begin{equation}
        \left(f(X^K(t))-  f(X^K(0)) -\int_0^t (L_1f-cf + Kf)(X^K(s)) ds\right)_{t\geqslant 0}
    \end{equation}
    is a c\`adl\`ag $(\mathcal{F}^K_t)$-martingale under $\mathbb{P}^{K}_{x}$.
    \end{enumerate}

