[Proposition 9 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] \label[proposition]{prop:m-diffusion}
On $[q,1]$, 
\begin{equation}
dm_t=\beta(1-m_t^2)\,dW_t.
\end{equation}
Further, if
\begin{equation}
f(t)=\E[m_t^2]-t,
\end{equation}
then
\begin{equation}
f'(t)=\beta^2\E\big[(1-m_t^2)^2\big]-1,
\qquad
f(q)=0,
\qquad
f'(q)=\alpha-1,
\end{equation}
where $f'(q)$ is understood as a one-sided derivative.

[Corollary 9 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let $k\in \mathbb{N}$. The law of $H_{k,0},H_{k,1}, \dots, H_{k,k-1}$ can be obtained as follows:
\begin{enumerate}
    \item Select $Y$ with the probability distribution $\mu_k$ defined in \eqref{eq:muk}.
\item Conditioned on $Y=y$, select $H_{y,0}, \dots, H_{y, k-1}$, where $H_{y,0}=T$ and $H_{y,1}, \dots, H_{y, k-1}$ are i.i.d. random variables with distribution 
$$\mathbb{P}(H_{y,i}\leq j\mid H_{y,i}\leq T)= \frac{(m^j-1)}{(m^T-1)}\ \frac{r-p+y(1-p)(m^T-1)}{r-p+y(1-p)(m^j-1)}, \qquad 1\leq j\leq T,\  1\leq i < k,$$
where $m=r/p$.
\end{enumerate}
Furthermore, let $\tau$ be an ultrametric, oriented tree with node depths $x_0=T$ and $x_1, \dots, x_{k-1}  \in  \{1,\ldots, T\}$, the likelihood function of the parameters $(p,r)$ given the outcome $\{\mathbf{T}_k=\tau\}$ is
   \begin{equation*}
    \mathcal{L}(p, r,\mid  \tau,k) = \mathbb{P}(\mathbf{T}_k=\tau)=
       \int_0^1 \mu_k(\mathrm{d}y) \prod_{i=1}^{k-1} \frac{\mathbb{P}(H_{y,i} = x_i)}{\mathbb{P}(H_{y,i}\le T)}.
   \end{equation*}

[Theorem th:HDL of arXiv:2604.08154, '\small Hydrodynamic limit of the directed exclusion process'] Let $u_0:\mathbb{R}\to \mathbb{R}$ be a measurable function, and let $(\mu_\varepsilon)_\varepsilon$ be a sequence of probability measures on $\mathbf{X}$ associated to the profile $u_0$, i.e.,
	\begin{equation}
		\mu_\varepsilon\bigg(\bigg|\,	\varepsilon\sum_{x\in \mathbb{Z}} f(\varepsilon x)\,\eta(x)-\int_{\mathbb{R}} f(x)\,u_0(x)\,{\rm d} 	x\,\bigg|>\delta\bigg)\xrightarrow{\varepsilon\to 0}0\; \text{,}\;\;\quad \delta >0\; \text{,}\;\; f \in \ensuremath{\mathcal C}_c(\mathbb{R})\; \text{.}
	\end{equation}
	Then,  letting $u(\,\cdot\,,\,\cdot\,):\mathbb{R}\times [0,\infty)\to [0,1]$ 
	denote the
	entropy solution  of (equation eq:HDL of the paper) (cf.\ Section (sec:entropy-solutions of the paper)) with initial condition $u_0$, we have, for all $t>0$,
	\begin{align}
		\mathds{P}_{\mu_\varepsilon}\!\bigg(\sup_{t\in [0,T]}\bigg|\varepsilon\sum_{x\in \mathbb{Z}}f(\varepsilon x)\,\eta_{t\varepsilon^{-1}}(x) - \int_{\mathbb{R}} 
		f(x)\,u(x,t)\,{\rm d} x\,\bigg|>\delta\bigg)\xrightarrow{\varepsilon\to 0}0\; \text{,}\;\;\quad \delta >0\; \text{,}\;\; f \in \ensuremath{\mathcal C}_c(\mathbb{R})\; \text{,}\;\;	\end{align}
	where $\mathds{P}_{\mu_\varepsilon}$ denotes the law of ${\rm DEP}$ when initialized according to $\mu_\varepsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

