[Lemma 12 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] For any $g \in \mathcal F$ and any block $B \subseteq N_{n}$, 
	\begin{align*}
		\sqrt{	\operatorname{Var}\left(  |B|^{-1/2} \sum_{i \in B} g(Z_{i})     \right)  } \leq \sqrt{2} ||g||_{B},
	\end{align*}
	where 
	\begin{align*}
		||g||_{B} : =  \sqrt{ \sum_{\rho \in R(B)}  	\frac{|S_{B}(\rho)|}{|B|}    \max_{i \in B} \int_{0}^{1}  1\left\{\alpha_{ \mathcal{F} , B }(\rho) \geq u	\right\} |Q_{|g(Z_{i})|}(u) |^{2} du }. 
	\end{align*}

[Thm 85 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that $\alpha$ and $\kappa\in (1/2,1]$ satisfy $\alpha>\frac{\kappa}{3\kappa+4}+5\kappa+\frac{7}{2}$.
  Then it holds for any $K\in (0,\infty)$ and $E<\frac{\kappa}{2(3\kappa+4)(\kappa+2)}$ that
  \begin{align*}
    \bbE\left[\sup_{|x|\le K}\Big|p(t,0,x)-p_n(t,0,\floor{nx}/n)\Big|\right]\lesssim n^{-E}.
  \end{align*}
  In particular, if $\alpha>\frac{121}{14}$, we have 
  \begin{align*}
     \bbE\left[\sup_{|x|\le K}\Big|p(t,0,x)-p_n(t,0,\floor{nx}/n)\Big|\right]\lesssim n^{-E},
  \end{align*}
  for any $K\in (0,\infty)$ and $E<\frac{1}{42}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

