[Definition \cite{kottwitz1992svfinitefields}, §5 of arXiv:2609.04072, 'Oort's conjecture for split unitary Shimura varieties'] Fix a compact open subgroup $K^p \subset \mathbf G(\mathbb{A}_f^p)$. Let $\operatorname{Sh}_{K^p}$ denote the moduli stack on schemes over  $\mathcal{O}_E \otimes \mathbb{Z}_{(p)}$, sending $S$ to the groupoid whose objects consist of quadruples $(A,i,\lambda,\overline{\eta})$, where
    \begin{itemize}
        \item $A$ is an abelian scheme over $S$. 
        \item $i: \mathcal{O}_B \otimes \mathbb{Z}_{(p)} \to \operatorname{End}_S(A) \otimes \mathbb{Z}_{(p)}$ is an $\mathcal{O}_B$-action that satisfies the Kottwitz condition
        \begin{equation*}
            \det(i(b) \mid \operatorname{Lie} A) = \det (b \mid V_1)
        \end{equation*}
        for all $b \in \mathcal{O}_B$. 
        \item $\lambda: A \to A^\vee$ is a prime-to-$p$ polarization, i.e.~a prime-to-$p$ quasi-isogeny which is symmetric with respect to double-duality $A \simeq (A^\vee)^{\vee}$, induces a pointwise polarization $n\lambda$ for some $n \gg 0$, and such that the induced Rosati involution on $\operatorname{End}_S(A) \otimes \mathbb{Z}_{(p)}$ is compatible with the involution on $\mathcal{O}_B$ via the $\mathcal{O}_B$-action $i$.
        \item $\overline{\eta}$ is a $K^p$-level structure (see [kottwitz1992svfinitefields] for details).
    \end{itemize}
    An isomorphim of quadruples is a prime-to-$p$ quasi-isogeny that respects the $\mathcal{O}_B$-action, the $K^p$-level structure and the polarizations up to a similitude factor in $\mathbb{Z}_{(p)}^\times$.

[Thm 5 (Perturbation formula) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Restricted to the event $\{X_t^{i,n}\neq \dagger\}$, for $t>0$, the conditional law of $X_t^{i,n}$ given $\sigma(\cup_{s>0}\mathcal{{G}}_{s}^{i,n})$ has a random density $p^{i,n}(t,x)$, which is supported on $[\hat{A}_t^{i,n},\infty)$ and  jointly continuous in $x
    \geq \hat{A}_t^{i,n}$ and $t>0$. This density can be expressed as
	\begin{equation}
	p^{i,n}(t,x)=\hat{p}^{i,n}\Bigl(t\,,\int_{\hat{A}^{i,n}_t}^x \frac{1}{\sigma(t,y)}\dy  \Bigr)\frac{1}{\sigma(t,x)},\quad \text{for all}\quad x \geq \hat{A}_t^{i,n},\,t> 0,
	\end{equation}
	where $\hat{p}^{i,n}$ is supported on $[0,\infty)$ and satisfies the implicit Volterra relation
	\begin{align}
	\hat{p}^{i,n}(t,x) & =\int_0^\infty N(x,t,y,0)\hspace{1pt} \di \hat{\mu}^{i}_0(y) +\int_{0}^{t}\int_{0}^{\infty}\partial_{y}N(x,t; y ,r)\tilde{b}^{i,n}(r, y)\hat{p}^{i,n}(r,y)\dy \dr \nonumber\\
	& \qquad\; -\int_{0}^{t}N(x,t;0,r)\gamma(r,\hat{{C}}_{r}^{i,n})\sigma(r,\hat{{A}}_{r}^{i,n})^2p^{i,n}(r,\hat{A}^{i,n}_r)\dr
	\end{align}
     with $\hat{\mu}_0^{i}=\mathrm{Law}(X_0^i) \circ (\int_{a_0}^\cdot \frac{1}{\sigma(0,y)}\dy)^{-1}$.    Furthermore, for any $T>0$, we have
\begin{equation}
	\hat{p}^{i,n}(t,x) \leq \frac{C_1}{\sqrt{t}} \exp\Bigl( -c_1x^{2}\Bigr),\quad \text{for all}\quad x\in[0,\infty), \,t\in(0,T],
	\end{equation}
for some constants $c_1,C_1>0$, and, in turn, there are constants $c_2,C_2>0$ such that
	\begin{equation}
		p^{i,n}(t,x) \leq \frac{C_2 }{\sqrt{t}} \exp\Bigl( -c_2(x-\hat{A}^{i,n}_t)^2 \Bigr),\quad \text{for all}\quad x\in[\hat{A}^{i,n}_t,\infty), \,t\in(0,T],
	\end{equation}
	These constants can be chosen independently of $i=1,\ldots,n$ and $n\geq 1$, and we note that \eqref{eq:lamperti_aronson}--\eqref{eq:particle_aronson} confirm that the perturbation formula \eqref{eq:density_rep-1} is well-defined.

[Lemma 18 of arXiv:2608.06011, 'Strong averaging principle for multiscale time-inhomogeneous SDEs with multiplicative $\al'] For any $x\in\br^n$ and $T,t>0$, there exists $C>0$ such that
       \begin{equation*}
           \left|\frac{1}{T}\int_t^{t+T}\bar{b}(r_1,r_2,x)\d r_2-\frac{1}{\tau_2}\int_0^{\tau_2}\bar{b}(r_1,r_2,x)\d r_2\right|\leq \frac{C\tau_2}{T}(1+|x|).
       \end{equation*}

