[Proposition 12 (Uniform full-tangent flow-jet expansion) of arXiv:2608.06393, 'Intrinsic Tangential Hadamard Differentiability of Rough-BSDE Solution Maps'] Assume \(H_i\in C_b^9(\mathbb R)\).  Fix
\(M_{\mathbf x},L_{\rm br}<\infty\).  There are constants
\[
 \delta>0,\qquad \varepsilon_0>0,\qquad C<\infty,\qquad N<\infty
\]
with the following property.  For every
\(\mathbf x\in WG\Omega_p(\mathbb R^d)\) satisfying
\(\rho_p(\mathbf x)\le M_{\mathbf x}\), there is a partition
\(\Pi(\mathbf x)\) with at most \(N\) intervals.  Its endpoints depend only
on the base control.  Let
\[
 \|\tau\|_{\mathbb T_{\mathbf x}^p}\le1
\]
and choose any representative satisfying
\begin{equation}
 \rho_p(\mathbf Z)+\|a\|_{q\text{-var}}\le L_{\rm br}.             
\end{equation}
Then, for \(|\varepsilon|\le\varepsilon_0\), every interval
\(I\in\Pi(\mathbf x)\) is a valid reset interval for
\(\mathbf x^{\varepsilon;\mathbf Z,a}\), and
\begin{equation}
 \frac12\le
 \partial_y\phi_t^{\varepsilon,I}(y)
 \le\frac32
 \quad\text{for all }(t,y)\in I\times\mathbb R.                   
\end{equation}

There is a representative first variation
\(P_I^{\mathbf Z,a,[5]}\) such that
\begin{align}
 &\sup_{I\in\Pi(\mathbf x)}
 \left\|
 \mathfrak J_I^{[5]}(\varepsilon;\mathbf Z,a)
 -\mathfrak J_I^{[5]}(0)
 -\varepsilon P_I^{\mathbf Z,a,[5]}
 \right\|_{\mathfrak V_5^\Delta(I)}
 \le C\varepsilon^2,                                              \\
 &\sup_{I\in\Pi(\mathbf x)}
 \left\{
 \|\mathfrak J_I^{[5]}(\varepsilon;\mathbf Z,a)
   \|_{\mathfrak V_5^{\mathrm{aff}}(I)}
 +\|P_I^{\mathbf Z,a,[5]}\|_{\mathfrak V_5^\Delta(I)}
 \right\}
 \le C.                                                          
\end{align}
Moreover,
\begin{equation}
 \sup_{I\in\Pi(\mathbf x)}
 \|P_I^{\mathbf Z,a,[5]}\|_{\mathfrak V_5^\Delta(I)}
 \le C\|\tau\|_{\mathbb T_{\mathbf x}^p}.                         
\end{equation}
The projection of \(P_I^{\mathbf Z,a,[5]}\) onto spatial orders
\(0,\ldots,3\) is the intrinsic variation \(P_I^\tau\) from
Proposition~\ref{prop:intrinsic-flow-variation}.  Consequently,
\begin{equation}
 \boxed{
 \sup_{I\in\Pi(\mathbf x)}
 \left\|
 \mathfrak J_I^{[3]}(\varepsilon;\mathbf Z,a)
 -\mathfrak J_I^{[3]}(0)-\varepsilon P_I^\tau
 \right\|_{\mathfrak V_3^\Delta(I)}
 \le C\varepsilon^2
 }                                                               
\end{equation}
and
\begin{equation}
 \sup_{I\in\Pi(\mathbf x)}
 \|P_I^\tau\|_{\mathfrak V_3^\Delta(I)}
 \le C\|\tau\|_{\mathbb T_{\mathbf x}^p}.                         
\end{equation}
In particular, the fourth and fifth spatial derivatives obey
\begin{equation}
 \sup_{\substack{I\in\Pi(\mathbf x)\\
                  |\varepsilon|\le\varepsilon_0}}
 \sum_{\ell=4}^5
 \sup_y\left\{
 \|\partial_y^\ell\phi^{\varepsilon,I}(\cdot,y)\|_{\infty;I}
 +\|\partial_y^\ell\phi^{\varepsilon,I}(\cdot,y)\|_{p\text{-var};I}
 \right\}
 \le C.                                                          
\end{equation}

Let
\(\psi_t^{\varepsilon,I}=(\phi_t^{\varepsilon,I})^{-1}\), and define
\[
 \mathfrak I_I^{[3]}(\varepsilon)
 =
 \bigl(
 \psi^\varepsilon-\operatorname{Id},
 \partial_y\psi^\varepsilon-1,
 \partial_y^2\psi^\varepsilon,
 \partial_y^3\psi^\varepsilon
 \bigr).
\]
There is a continuous linear inverse-flow variation
\(\dot{\mathfrak I}_I^\tau\) for which
\begin{equation}
 \sup_{I\in\Pi(\mathbf x)}
 \left\|
 \mathfrak I_I^{[3]}(\varepsilon)
 -\mathfrak I_I^{[3]}(0)
 -\varepsilon\dot{\mathfrak I}_I^\tau
 \right\|_{\mathfrak V_3^\Delta(I)}
 \le C\varepsilon^2.                                              
\end{equation}
It satisfies
\begin{equation}
 \sup_{I\in\Pi(\mathbf x)}
 \|\dot{\mathfrak I}_I^\tau\|_{\mathfrak V_3^\Delta(I)}
 \le C\|\tau\|_{\mathbb T_{\mathbf x}^p}.                         
\end{equation}
Its first component is
\begin{equation}
 \dot\psi^\tau
 =-\left(\frac{U^\tau}{J}\right)\circ\psi,                         
\end{equation}
and its remaining components are the first three spatial derivatives of
\eqref{eq:inverse-first-variation}.

Finally, put
\[
 \mathcal Q(\phi,J,K,L)
 =
 \left(
 J^{-1},\frac KJ,\frac LJ-\frac{K^2}{J^2}
 \right).
\]
The same constants give
\begin{equa (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Let $\mu,\nu\in\mathcal{P}_1(E)$. Then
    \begin{equation}
        W_1(\mu,\nu)=\sup_{\substack{\varphi\in\mathrm{Lip}(E)\\\mathrm{Lip}(\varphi)\leq 1}}\left|\int_E\varphi(x)\dd(\mu-\nu)(x)\right|,
    \end{equation}
    where $\mathrm{Lip}(E)$ denotes the set of all Lipschitz functions on $E$, and for $\varphi\in\mathrm{Lip}(E)$, we denote the Lipschitz constant of $\varphi$ by $\mathrm{Lip}(\varphi)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theo:S-sgd-dynamics of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under Assumption (assum:S-sgd of the paper), suppose that the learning rate satisfies $\alpha_d\le\frac{c_0}{d\log d}$ and $\alpha_d=\Omega(d^{-\iota})$
for some constants $\iota>0$ and $c_0>0$ sufficiently small.
Then, for every finite $T>0$, the empirical order parameters converge uniformly in probability to a deterministic trajectory
$(\bar t(t),\bar\Psi(t),\bar\Omega(t))$.
More precisely, for every $k,l$ and every $\epsilon>0$,
\begin{align}
\lim_{d\to\infty}\mathbb P\left(\sup_{t\in[0,T]}|\tilde t_k^{(d)}(t)-\bar t_k(t)|+|\tilde\Psi_{kl}^{(d)}(t)-\bar\Psi_{kl}(t)|+|\tilde\Omega_{kl}^{(d)}(t)-\bar\Omega_{kl}(t)|>\epsilon\right)=0.
\end{align}
The limiting trajectory is the unique solution of
\begin{align}
\frac{d}{dt}\bar t_k&=-2\chi_k
\sum_{m=1}^K\left([\nabla_\Omega\Phi]_{km}+[\nabla_\Psi\Phi]_{km}
\right)\bar t_m-\gamma\chi_k\bar t_k,

\\
\frac{d}{dt}\bar\Psi_{kl}
&=-2\chi_k\sum_{m=1}^K\left([\nabla_\Omega\Phi]_{km}\bar\Psi_{ml}+[\nabla_\Psi\Phi]_{km}\bar\Omega_{ml}\right)
-2\chi_l\sum_{m=1}^K\left([\nabla_\Omega\Phi]_{lm}\bar\Psi_{km}+[\nabla_\Psi\Phi]_{lm}\bar\Omega_{km}
\right)
-\gamma(\chi_k+\chi_l)\bar\Psi_{kl},

\\
\frac{d}{dt}\bar\Omega_{kl}
&=
-2\chi_k
\sum_{m=1}^K\left([\nabla_\Omega\Phi]_{km}\bar\Omega_{ml}+[\nabla_\Psi\Phi]_{km}\bar\Psi_{ml}
\right)-2\chi_l
\sum_{m=1}^K
\left([\nabla_\Omega\Phi]_{lm}\bar\Omega_{km}+[\nabla_\Psi\Phi]_{lm}\bar\Psi_{km}\right)-\gamma(\chi_k+\chi_l)\bar\Omega_{kl},

\end{align}
where the gradients of $\Phi$ are evaluated at $(\bar\Psi(t),\bar\Omega(t))\in\mathcal D$ for $t\in[0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

