[Def1 si-d1 of arXiv:2410.23995, 'Sample path properties of parabolic SPDEs with non constant coefficients'] For a  jointly measurable and adapted stochastic process $H\in L^2(\Omega\times [0,T]; U)$, the stochastic integral of $H$ with respect to the standard cylindrical Wiener process $W$ is
\begin{equation}

\int_0^T H_s\, dW_s:= \sum_{j=1}^\infty \int_0^T\langle H_s,e_j\rangle_U\, dW_s(e_j).
\end{equation}

[Theorem 29 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] Under the simply connected hypotheses above, for every $t>0$,
		\begin{align}
			p_t(e)
			&=C_{G,L}t^{-Q/2}e^{\beta_{G,L}t}
			+\frac{\vol(G)}{(4\pi)^{Q/2}}t^{-Q/2}e^{\beta_{G,L}t}
			\sum_{\mathcal P\in\mathscr P_G}
			e^{-\ell_{\mathcal P}^2/(4t)}b_{\mathcal P}(t).

		\end{align}
		The series is real and absolutely convergent; more precisely,
		\[
		\sum_{\mathcal P\in\mathscr P_G}
		e^{-\ell_{\mathcal P}^2/(4t)}|b_{\mathcal P}(t)|<\infty.
		\]

[Lem 12 of arXiv:2608.16144, 'Central limit theorem in R\'enyi divergence for lattice random variables'] For all $\ell \geq 1$, we have
\begin{equation}  
\delta_{n}\sum_{k\in\mathbb{Z}}\varphi^{\ell}(x_{n,k})
=\int_{\mathbb{R}} \varphi^{\ell}(x)\,dx+O\big(e^{-2\pi^2 n/\ell h^2}\big).
\end{equation}	
In particular, we obtain
\begin{equation} 
\sum_{k\in\mathbb{Z}} q_{n,k}=1+O\big(e^{-2\pi^{2}n/h^{2}}\big).
\end{equation}

