[Theorem 2 of arXiv:2606.28793, 'Randomized second order Riesz projections on the Hamming cube'] Let $X$ be an arbitrary Banach space and let $1\leq p<\infty$.  Then for every $n\geq1$ and every $g:\Omega_n\to X$,
\begin{equation}

 \left(\E_{\eps,\delta}
 \left\|
 \sum_{j=1}^n\delta_j\Delta^{-1}D_jg(\eps)
 \right\|_X^p\right)^{1/p}
 \leq C_p\sqrt n\,\|g\|_{L^p(\Omega_n;X)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Strong solution to Hamilton--Jacobi equation) of arXiv:2605.13512, '2605.13512'] Assume \ref{ass:pde-speed}. The limiting current $v(x,t)$, given by equation \eqref{eq:vdef}, is a solution to the Cauchy problem \eqref{eq:genHJ} with flux given by \eqref{eq:discoflux}, at all points $(x,t)$ that are differentiability points of $v(x,t)$ and continuity points of $\tilde c(x,-v(x,t))$. 

Furthermore, under Assumption \ref{ass:c0strong}
almost every $(x,t) \in \bR \times \bR_+$ is a differentiability point of $v(x,t)$ and continuity point of $\tilde c(x,-v(x,t))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 (It\^{o} formula for cumulants) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] For $p\in\N$ and $T>0$, let $X_{1,t},\ldots,X_{p,t}$, $t\in[0,T]$, be complex-valued diffusion processes defined on the same probability space, i.e.
\begin{equation}
\dif X_{j,t}=\mu_{j,t}\dif t + (\bm{\sigma}_t\dif B_t)_j,
\end{equation}
where $\mu_{j,t}\in\C$, $\bm{\sigma}_t\in\C^{p\times d}$ for some $d\in\N$, and $\dif B_t$ is the standard Brownian motion in $\R^d$. Assume that $X_{j,t}$ has all finite moments for all $j\in[p]$ and $t\in [0,T]$. Then it holds that
\begin{equation}
\frac{\dif}{\dif t}\kappa\left(\lbrace X_{j,t}\rbrace_{j\in[p]}\right) = \sum_{i=1}^p \kappa\left(\mu_{i,t},\lbrace X_{j,t}\rbrace_{j\in[p]\setminus\{i\}}\right) + \sum_{1\le i<h\le p}\kappa\left(\frac{\dif}{\dif t}[X_i,X_h]_t,\lbrace X_{j,t}\rbrace_{j\in[p]\setminus\{i,h\}}\right), 

\end{equation} 
for any $t\in [0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2606.20908, 'On It\^o-Stratonovich formula for rough sheets'] Let $f\in\cp_{1,1}$ and $g\in\cp_{2,2}$ (see~\eqref{c3}), let $\kappa_{1},\kappa_{2}>0$ and $p\geq 1$, and let $\eps>0$ be a small parameter. In all items below, $U^{2}_{\kappa_{1},\kappa_{2},p}$ is the functional introduced in Definition~\ref{def:U2}.
\begin{enumerate}[label=\textnormal{\textbf{(\roman*)}}]
    \item If $U^2_{\kappa_1,\kappa_2,p}(\delta f) < \infty$, then $f \in \cp^{\kappa_1,\kappa_2}_{1,1}$; more precisely
\begin{align}
\|\delta f\|_{\kappa_1,\kappa_2} \leq c_2  U^2_{\kappa_1,\kappa_2,p}(\delta f),
\end{align}
for a universal constant $c_2 > 0$.

   \item 
   Assume that \,$\doo g\in \cp_{3,2}^{\ka_1,\ka_2}$, $\dt g\in \cp_{2,3}^{\ka_1+\eps,\ka_2}$,  and $U^2_{\ka_1,\ka_2,p}(g)<\infty$.
   Then for all $p>\frac{1}{2\eps}$ we have
   \begin{align}
   \lVert g\rVert_{\kappa_1,\kappa_2}\le c_3 \Bigl(U^2_{\ka_1,\ka_2,p}(g)+\lVert \doo g \rVert_{\ka_1,\ka_2}+\lVert \dt g \rVert_{\ka_1+\eps,\ka_2}\Bigl),
   \end{align}
   for some constant $c_3$ depending on $\varepsilon$ and $p$.

    \item 
    Suppose that $\doo g\in \cp_{3,2}^{\ka_1,\ka_2+\eps}$, $\dt g\in \cp_{2,3}^{\ka_1,\ka_2}$, and $U^2_{\ka_1,\ka_2,p}(g)<\infty$. Then for all $p>\frac{1}{2\eps}$ we have
   \begin{align}
   \lVert g\rVert_{\kappa_1,\kappa_2}\le c_4 \Bigl(U^2_{\ka_1,\ka_2,p}(g)+\lVert \doo g \rVert_{\ka_1,\ka_2+\eps}+\lVert \dt g \rVert_{\ka_1,\ka_2}\Bigl),
   \end{align}
    for some constant $c_4$ depending on $\varepsilon$ and $p$.
\end{enumerate}

