[Theorem thm:rmulmc_cvx of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Let $\hat{\boldsymbol{P}}$, $\hat{\boldsymbol{P}}{}'$ denote the kernels for~(eq:rm-ulmc of the paper) and~(eq:ULMC of the paper) respectively, and let $\boldsymbol{P}$ denote the kernel for~(eq:ULD of the paper) run for time $h$.
    Assume that $0 \preceq \alpha I \preceq \nabla^2 V \preceq \beta I$ and set $\gamma = \sqrt{32\beta}$.
    Write $W^2 \coloneqq \mathcal{W}_2^2(\bs\mu,\bs\pi)$, where $\mathcal{W}_2$ denotes the $2$-Wasserstein distance in the twisted norm $(x,p) \mapsto \sqrt{\norm x^2 + \gamma_0^{-2}\,\norm p^2}$.
    \begin{enumerate}
        \item \underline{$\alpha > 0$ case:} If $\varepsilon \in (0, \widetilde O(\frac{d^{1/2}}{\kappa^{3/2}})]$ and $h = \widetilde{\Theta}( \frac{\varepsilon^{2/3}}{\beta^{1/2} d^{1/3}})$, then $\KL(\bs\mu \hat{\boldsymbol{P}}{}^{N-1}\hat{\boldsymbol{P}}{}' \mathbin{\|} \bs\pi) \leqslant \varepsilon^2$ for all
        \begin{align*}
            N = \widetilde{\Omega}\Bigl(\frac{\kappa d^{1/3}}{\varepsilon^{2/3}} \log \frac{\alpha W^2}{\varepsilon^2}\Bigr)\,.
        \end{align*}

        \item \underline{$\alpha = 0$ case:} If $\varepsilon\in  (0,\widetilde O(\frac{\beta^{3/4} W^{3/2}}{d^{1/4}})]$ and $h = \widetilde{\Theta}(\frac{\varepsilon}{\beta^{3/4} d^{1/4} W^{1/2} + \beta W})$, then $\KL(\bs\mu\hat{\boldsymbol{P}}{}^{N-1}\hat{\boldsymbol{P}}{}' \mathbin{\|} \bs\pi) \leqslant \varepsilon^2$ for
        \begin{align*}
            N = \widetilde{\Theta}\Bigl(\frac{\beta^{5/4} d^{1/4} W^{5/2} + \beta^{3/2} W^3}{\varepsilon^3}\Bigr)\,.
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

