[Lem 122 ({\cite{KO,RT,LTDMLS}}) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any indices $i, j \in \{ x, y \}$, there exists $\mathfrak{a}_{ij} : \mathcal{T} \rightarrow \mathbb{R}$
                satisfying $\mathfrak a_{xy}=\mathfrak a_{yx}$ as well as the following two statements:
		\begin{enumerate} 
			\item For any $z \in \mathfrak{L}_{q;a,b,c}$, we have 
			\begin{flalign}
                          \displaystyle\sum_{i,j \in \{ x, y \}} 	\mathfrak{a}_{ij} (\nabla \mathcal{H}_{q;a,b,c} (z)) \cdot \partial_{ij} \mathcal{H}_{q;a,b,c} (z) = -q.

			\end{flalign}

			\item For any $\omega > 0$, there exists a constant $C = C(\omega) > 1$ such that the following holds. Whenever $\gamma\in\mathcal T$ with  $\dist (\gamma, \partial \mathcal{T}) \ge \omega$, we have
			\begin{flalign*} 
				C^{-1} \le \mathfrak{a}_{xx} (\gamma) \le C; \qquad |\mathfrak{a}_{xy} (\gamma)| \le C; \qquad C^{-1} \le \mathfrak{a}_{yy} (\gamma) \le C.
			\end{flalign*} 

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 19 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] The function $\phi$ obeys the inequalities
\begin{equation}
	s\phi'(s)\le m\phi(s) +\phi''(1)(s-1)\,,\quad s> 0\,,
\end{equation}
and
\begin{equation}
	\frac{m}{m-1}(s^{m-1}-1)\le \phi'(s)\le \frac{m 2^{m-1}}{m-1} (s^{m-1}-1)\,,\quad s\ge 1\,,
\end{equation}
with $\phi'(s)<1$ for $s\in (0,1)$.

