[Defi def:quasiaction of arXiv:2609.02346, 'Regularised double shuffle relations for planar \AZVs{}'] Let $t$ and $s$ be two trees decorated by a semigroup $(\Omega,+)$ which respective right comb representation and left comb representation are given above (equation~(equation eq:tree_combs of the paper)).
			We denote by $k+1$ (resp. $l+1$) the number of nodes on the rightmost (resp. leftmost) branch of $t$ (resp. $s$). Let $\sigma$ be a $(k+1,l+1)$-quasi-shuffle  which has for image $\IEM{1}{n}$ with $n$ a non-negative integer. We build a tree from $\sigma$:

			\begin{enumerate}
				\item  We first consider the ladder with $n$ nodes:
				\begin{center}
					\raisebox{-0.5\height}
					{\begin{tikzpicture}[line cap=round,line join=round,>=triangle 45,x=0.3cm,y=0.3cm]
							\begin{scope}
								\draw (0,1)--(0,2.5);
								\draw[dashed] (0,2.5)--(0,5);

								\filldraw [black] (0,1) circle (2pt) node[anchor=west]{\footnotesize{Node $1$}};
								\filldraw [black] (0,2) circle (2pt) node[anchor=west]{\footnotesize{Node $2$}};
								\filldraw [black] (0,5) circle (2pt) node[anchor=west]{\footnotesize{Node $n$}};
							\end{scope}
					\end{tikzpicture}}.
				\end{center}

				\item For $i\in\IEM{1}{k+1},$ we graft $F_i$ (with its decorations) as the \emph{left} son at the node $\sigma(i)$.
				\item For $i\in\IEM{k+2}{k+l+2},$ we graft $F_i$ with its decorations as the \emph{right} son at the node $\sigma(i)$.
				\item For $j\in\IEM{1}{n}$, the node $j$ drawn above is decorated by:
				\begin{itemize}
					\item $\omega_s$ if $\sigma^{-1}(\{j\})=\{s\}$ with $s\in\IEM{1}{k+1}$;
					\item $\omega_r$ if $\sigma^{-1}(\{j\})=\{r\}$ with $r\in\IEM{k+2}{k+l+2}$;
					\item $\omega_s + \omega_r$ if $\sigma^{-1}(\{j\})=\{s,r\}$ with $(s,r)\in\IEM{1}{k+1}\times \IEM{k+2}{k+l+2}$.
				\end{itemize}
			\end{enumerate}
			We denote the tree obtained from this construction $\sigma(t,s)$. 
			If $\sigma$ is a $(k+1,l+1)$-shuffle, we only require for $\Omega$ to be a set.

