body:
[Theorem thm:BCSVH-BBP of arXiv:2606.14687, 'Lehner's operator norm formulas, semidefinite programming, and spiked matrix models'] Define the function
    \begin{equation}
        B(\theta) \colonequals \left\{\begin{array}{ll} 2 & \text{if } \theta \leq 1, \\ \theta + \theta^{-1} & \text{if } \theta > 1 \end{array}\right\}.

    \end{equation}
    Let $\bm W = \bm W^{(d)} \in \mathbb{R}^{d \times d}_{\sym}$ be a sequence of real symmetric random matrices with centered jointly Gaussian entries.
    Write
    \[ \bm W^{(d)} = \sum_{i = 1}^n g_i \bm A_i^{(d)} \]
    for some $n = n(d)$, deterministic $\bm A_i^{(d)} \in \mathbb{R}^{d \times d}_{\sym}$, and independent $g_i \sim \mathcal{N}(0, 1)$.
    Let $\bm v = \bm v^{(d)} \in \mathbb{S}^{d - 1}$ be deterministic, let $\theta \geq 0$ not depend on $d$, and set
    \begin{align*}
      \bm A_0^{(d)} &\colonequals \theta\bm v\bm v^{\top}, \\
      \bm X^{(d)} &\colonequals \bm A_0^{(d)} + \bm W^{(d)}.
    \end{align*}
    Suppose that
    \begin{align}
        \mathbb{E}[(\bm W^{(d)})^2] &= \bm I_d \text{ for all } d \geq 1,  \\
        v(\bm W^{(d)}) &= o(\log(d)^{-3/2}) \text{ as } d \to \infty, 
    \end{align}
    where $v(\cdot)$ is as defined in (equation eq:BBVH-v of the paper).
    Then, the following hold, as $d \to \infty$:
    \begin{align}
      \Lambda_{\mathsf{sc}}(\bm A_0^{(d)}, \bm A_1^{(d)}, \dots, \bm A_n^{(d)}) &\to B(\theta), \\
      \lambda_{\max}(\bm X^{(d)}) &\to B(\theta) \text{ in probability.} 
    \end{align}
    Further, let $\widehat{\bm v} = \widehat{\bm v}^{(d)}$ be the leading eigenvector of $\bm X^{(d)}$.
    Then, under the same assumptions we have, as $d \to \infty$,
    \begin{equation}

        \langle \bm v, \widehat{\bm v} \rangle^2 \to B^{\prime}(\theta) = \left\{\begin{array}{ll} 0 & \text{if } \theta \leq 1, \\ 1 - \theta^{-2} & \text{if } \theta > 1 \end{array}\right\} \text{ in probability}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 9 of arXiv:2608.30155, 'Gradient Estimates Near the Natural Exponent for Very Weak Solutions to $A_p$-Weighted Qua'] Assume \eqref{struc} and \eqref{unidegen}. If  $\omega \in A_{p}$ for some $p>1$,  then for all
		$w_{0}\in W^{1,p-\delta }_{\omega}  ( B_{\rho}) $ with $\delta \in
		(0,\delta_{2}]$, there exists a very weak solution $w\in
		W^{1,p-\delta }_{\omega}  ( B_{\rho})$ to the problem
		\begin{align}
			\begin{cases}
				-\mathrm{div\,}A_{\mathbb{M}}(x,Dw)=0 & \textrm{in}\ B_{\rho} \\
				w\in w_{0}+ W^{1,p-\delta }_{\omega,0}( B_{\rho}),
			\end{cases}
		\end{align}
		which satisfies the estimate
		\begin{align}
			\int_{B_{\rho}}   |Dw|^{p-\delta} \omega \, dx   \leq c   \int_{B_{\rho}} |Dw_{0}|^{p-\delta} \omega  \, dx
		\end{align}
		where the  constant $c>0$ depends on  $ n, p, \nu, L, \Lambda $ and $ [\omega]_{A_{p}}$.

