[Proposition p.abmnsolvesmn of arXiv:2510.07682, 'From tug-of-war to Brownian Boost: \\ explicit ODE solutions for player-funded stochastic-'] Let $(a,b,m,n) \in $ \textrm{ABMN}($\kappa,\rho$). 
 The $(m,n)$-components 
 solve the \textrm{MN}  system on~$\ensuremath{\mathbb{Z}}$. We have that
  \begin{equation}
   a_i = \frac{\rho \kappa M_i^{1+\rho} N_i^\rho}{(M_i^\rho+N_i^\rho)^2}  \, \, \, \, , \, \, \, \,  b_i = \frac{\rho  \kappa  M_i^\rho N_i^{1+\rho}}{(M_i^\rho+N_i^\rho)^2}  \, \, \, \, \textrm{and} \, \, \, \,
    \frac{a_i^\rho}{a_i^\rho+b_i^\rho} =     \frac{M_i^\rho}{M_i^\rho+N_i^\rho}
  \end{equation}
for each $i \in \ensuremath{\mathbb{Z}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 over N of arXiv:2412.00279, 'Optimal local storage policy based on stochastic intensities and its large scale behavior'] $\max_{1\leqslant i\leqslant N}
\left\|
\widehat{G}_N - \widehat{G}_N^{(-i)}
\right\|_\infty
\leqslant
\frac{1}{N}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $(\mathcal{P}(\X), \tau)$ be a topological space, where $\tau$ is a topology on $\mathcal{P}(\X)$.
    \begin{enumerate}[label=(\roman*)]
        \item $\Phi$ is called \textit{$\tau$-asymptotically stable} if there exists a unique invariant measure $\mu \in \mathcal{P}(\X)$ such that:
        \begin{equation*}
            \lim_{t \to \infty} P_t(x, \cdot) = \mu \quad \text{in } (\mathcal{P}(\X), \tau), \quad \forall\, x \in \X.
        \end{equation*}
        \item $\Phi$ is called \textit{$\tau$-mean ergodic} if there exists a unique invariant measure $\mu \in \mathcal{P}(\X)$ such that:
        \begin{equation*}
            \lim_{t \to \infty} \frac{1}{t} \int_0^t P_s(x, \cdot) \d s = \mu \quad \text{in } (\mathcal{P}(\X), \tau), \quad \forall\, x \in \X.
        \end{equation*}
    \end{enumerate}

[Lemma Bound for J_4 of arXiv:2412.08932, 'Gaussian heat kernel asymptotics for conditioned random walks'] For any  $\varepsilon \in (0,\frac{1}{2}]$, there exists a constant $c=c_{\varepsilon}>0$ 
such that, for any $n\geqslant 2$ and $x\in \bb R$,
\begin{align*}
J_{3}  \leqslant c  \frac{1 + V(x) L\left(\frac{x}{\sigma\sqrt{n}}\right)}{ n^{\frac{1}{2} + \frac{\delta}{2}  - \delta\varepsilon  } } (\log n)^{3/2}.   
