[Definition 13 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] A bounded sequence $(u_{\varepsilon })_{\varepsilon >0}$
		 in $L^{\Phi}(Q\times \Omega )$  is
		said to weakly stochastically $\Sigma $-converge  in $L^{\Phi}(Q\times
		\Omega )$  to some $u_{0}\in L^{\Phi}(Q\times \Omega ;\mathcal{X}^{\Phi}_{A}) \equiv \mathcal{G}_{1}^{-1}(L^{\Phi}(Q\times\Omega\times\Delta(A)))$ if as $\varepsilon \rightarrow 0$, we have  
		\begin{equation}
			\iint_{Q\times \Omega }u_{\varepsilon }(x,\omega ) f^{\varepsilon}(x, \omega) dxd\mu
			\rightarrow \iint_{Q\times \Omega} \pounds_{A}\int u_{0}(x,\omega,y) f(x,\omega,y)dy\, dxd\mu  \;\;\;\;\;\;\;\;  
		\end{equation}
		for every $f\in \mathcal{C}_{0}^{\infty }(Q)\otimes \mathcal{C}
		^{\infty }(\Omega )\otimes A$











		We express this by writing $
		u_{\varepsilon }\rightarrow u_{0}$ in $L^{\Phi}(Q\times \Omega
		)$-weak $\digamma\,\Sigma $, where $\digamma$ stands for \textit{digamma} symbol in Latex.

[Defi See Definition $3.3$ in \cite{H.F1994} of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Given a random set $\mathscr{A}(\omega)$ and $B$ is another random set, we say $\mathscr{A}(\omega)$ attracts $B$ if $P$-a.s.
		\begin{align*}
			{\lim_{t\to + \infty}}dist (\varphi(t,\theta_{-t}\omega)B,\mathscr{A}(\omega))=0,
		\end{align*}
		where dist$(\cdot,\cdot)$ denotes the Hausdorff semi-distance.

[Lemma lem::high_tempe of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Let $A\subseteq V(\Omega_M^a)$, then we have 
	\begin{align}
\mathbb{E}_{\Omega_{M}}^{(a,\mathbf{m})}[\sigma_A]= \begin{cases}
	Z(\overline{\Omega}_M^a;A)/Z(\overline{\Omega}_M^a),& \text{if }\#A \text{ is even},\\
	Z(\overline{\Omega}_M^a;A\cup \{y_3^a-\mathfrak{i} a\})/Z(\overline{\Omega}_M^a),& \text{if }\#A \text{ is odd}.
\end{cases}
	\end{align}
In particular, we have 
	\begin{align*}
				\mathbb{E}_{\Omega_M}^{(a,\mathbf{m})} [\sigma_{y_1^a}]= \frac{Z(\overline{\Omega}_M^a;\{y_1^a,y_3^a-\mathfrak{i} a\})}{Z(\overline{\Omega}_M^a)},\quad
				\mathbb{E}_{\Omega_M^a}^{(a,\mathbf{m})} [\sigma_{y_1^a}\sigma_{y_2^a}]= \frac{Z(\overline{\Omega}_M^a;\{y_1^a,y_2^a\})}{Z(\overline{\Omega}_M^a)}.
	\end{align*}

[Corollary cor:Zdev of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Suppose $\mathbf{x} \in \mathrm{Meso}(N)$. Then, for all $t \geqslant 0$ and $\Delta>0$, we have
    \begin{equation*}
        \P{\abs{Z_t(i, j) - \mathbb{E}\!\left[Z_t(i, j)\right]} \geqslant \Delta \text{ for some } i \in [d], j \in [m]} \leqslant \frac{d^2m}{4} \frac{N}{\Delta^2} + \frac{6d^3}{m} \frac{N^2}{n^2\Delta^2} t.
    \end{equation*}

