[Prop 13 (Griffiths' inequality {\cite{GriffithsCorrelationsIsing1-1967,kelly1968general}}) of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)$ be a subgraph of $\mathbb Z^d$. Then, for every $J\in (\mathbb R^+)^{E}$, every $\mathsf{h}\in (\mathbb R^+)^{V}$, and every $A,B\subset V$,
\begin{equation}
	\langle \sigma_A;\sigma_B\rangle_{G,J,\mathsf{h}}:=\langle \sigma_A\sigma_B\rangle_{G,J,\mathsf{h}}-\langle \sigma_A\rangle_{G,J,\mathsf{h}}\langle \sigma_B\rangle_{G,J,\mathsf{h}}
\geq 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] For \(k\in\lbrace0,...,d-1\rbrace\), let \(\m x_1,...,\m x_k,\m y_{1},...,\m y_{d-k},\m y'_{1},...,\m y'_{d-k}\in\R^d\) be \(2d-k\) points in general position. We denote by \(\text{Vect}(\cdot)\) the linear subspace of real linear combination of the specified points and by \(\Sp(\cdot)\) the sphere of least dimension that passes by the specified points.
		\begin{itemize}
			\item The \(k\) points \(\m x_1,...,\m x_k\) determine a \(k\)-dimensional linear subspace \(Q=\text{Vect}(\m x_1,...,\m x_k)\in\mathcal{L}^d_k\). Within the subspace \(Q\), the points \(0\) and \(\m x_1,...,\m x_k\) lay on a unique \((k-1)\)-dimensional sphere \(\Sp(0,\m x_1,...,\m x_k)\) of radius \(\rho_0\in\R_{+}\). We denote by \(\m u_0\in\Sp_{Q}\), where \(\Sp_Q\) is the unit sphere on the space \(Q\), the unit vector pointing from the origin towards the center of \(\Sp(0,\m x_1,...,\m x_k)\). Moreover, for \(i\in\lbrace1,...,k\rbrace\), we denote by \(\m v_i\in\Sp_Q\) the unit vector pointing from the center of \(\Sp(0,\m x_1,...,\m x_k)\) towards \(\m x_i\).
			\item The \((d+1)\) points \(0,\m x_1,...,\m x_k,\m y_1,...,\m y_{d-k}\) determine a \(d\)-dimensional sphere \(\Sp(0,\m x_1,...,\m x_k,\m y_1,...,\m y_{d-k})\) of center \(c\) and radius \(\m r\in\R_{+}\). For \(j\in\lbrace1,...,d-k\rbrace\) we denote by \(\m w_j\in\Sp_{\R^d}\) the unit vector pointing from \(c\) towards \(\m y_j\), where \(\Sp_{\R^d}\) denotes the unit sphere in the space \(\R^d\).
			\item The \((d+1)\) points \(0,\m x_1,...,\m x_k,\m y_1',...,\m y_{d-k}'\) determine a \(d\)-dimensional sphere \(\Sp(0,\m x_1,...,\m x_k,\m y_1',...,\m y_{d-k}')\) of center \(c'\) and radius \(\m r'\in\R_{+}\). For \(j\in\lbrace1,...,d-k\rbrace\) we denote by \(\m w'_j\in\Sp_{\R^d}\) the unit vector pointing from \(c'\) towards \(\m y'_j\).
			\item Finally, we denote by \(\m u,\m u'\in\Sp_{Q^\perp}\) the unit vectors in the \((d-k)\)-dimensional space \(Q^\perp\) pointing respectively towards \(c\) and \(c'\) from the center of the \(k\)-dimensional ball \(\Sp(0,\m x_1,...,\m x_k)\).
		\end{itemize}
		We have for \(i\in\lbrace1,...,k\rbrace\),
		\begin{equation*}
			\m x_i = \rho_0(\urm_0+\m v_i)
		\end{equation*}

		and for \(j\in\lbrace1,...,d-k\rbrace\),
		\begin{align*}
			& \m y_j = \rho_0\urm_0+\sqrt{\m r^2-\rho_0^2}\m u+\m r\m w_j, \\
			& \m y'_j = \rho_0\urm_0+\sqrt{\m (\m r')^2-\rho_0^2}\m u+\m r'\m w'_j.
		\end{align*}

		Then for all non-negative functions we have
		\begin{equation*}
			\begin{split}
				\int\limits_{(\R^d)^{2d-k}} d\x \, d\y \, d\y' f(\x,\y,\y')
				= & \int\limits_{\mathcal{L}_k^d}d\m Q\int\limits_{\Sp_{Q}^{k+1}}d\urm_0d\vbf\int\limits_{\R_{+}}d\rho_0 \int\limits_{\Sp_{Q^\perp}}d\m u\int\limits_{\R_{+}}d\m r\int\limits_{\Sp_{\R^d}^{d-k}}d\wbf \int\limits_{\Sp_{Q^\perp}}d\m u'\int\limits_{\R_{+}}d\m r'\int\limits_{\Sp_{\R^d}^{d-k}}d\wbf' \\
				& \rho_0^{kd-1} (k!\Delta_{k}(-\urm_0,\vbf))^{d-k+1} \1_{0\leq\rho_0\leq \m r,\m r'} \\
				& \m r^{(d-k)(d-1)+1} \sqrt{\m r^2-\rho_0^2}^{d-k-2}(d-k)!\Delta_{d-k}(-\frac{\sqrt{\m r^2-\rho_0^2}}{\m r}\m u,P_{\m Q^\perp}(\wbf)) \\
				& \m (\m r')^{(d-k)(d-1)+1} \sqrt{\m (\m r')^2-\rho_0^2}^{d-k-2}(d-k)!\Delta_{d-k}(-\frac{\sqrt{\m (\m r')^2-\rho_0^2}}{\m r'}\m u',P_{\m Q^\perp}(\wbf')) \\
				& f(\rho_0(\urm_0+\vbf,\rho_0\urm_0+\sqrt{\m r^2-\rho_0^2}\m u+\m r\wbf,\rho_0\urm_0+\sqrt{\m (\m r')^2-\rho_0^2}\m u+\m r'\wbf')
			\end{split}
		\end{equation*}
		where we used the short notation \(P_{\m Q^\perp}(\wbf) = (P_{\m Q^\perp}(\m w_1),...,P_{\m Q^\perp}(\m w_{d-k}))\) (and similarly for \(P_{\m Q^\perp}(\wbf'))\) and where we denote by \(d\m u_0\), \(d\vbf=d\m v_1... d\m v_k\), \(d\m u\), \(d\m u'\), \(d\wbf=d\m w_1... d\m w_{d-k}\) and \(d\wbf'=d\m w'_1... d\m w'_{d-k}\) the respective surface area measures on the corresponding spheres and where we associate to the Grassmannian \(\mathcal{L}^d_k\) its standard measure \(Q\), normalized such that
		\begin{equation*}
			\int\limits_{\mathcal{L}^d_k} d\m Q = \binom{d}{k (Proof in the paper; no proof environment follows the statement in the TeX.)

