{"artifact_digest":"sha256:5ada783a8bfe018403feeb8f63d85ce0408c898a6a779cd8738f3bcf7beabc70","artifact_path":"objects/sha256/5a/5ada783a8bfe018403feeb8f63d85ce0408c898a6a779cd8738f3bcf7beabc70.md","bundle_digest":"sha256:d03a98ed318e435227783962eea32d93f3393421dbdce6c9fa87bdaac6cbe5ad","bundle_entry_key":"2601-04079-theorem-5-pb-tv-symmetric-bcv","bundle_id":"population.tex-extract-s0_097","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-v2-20260907/bundle_s0_097.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2601-04079-theorem-5-pb-tv-symmetric-bcv","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: The proof uses three standard ingredients.

\noindent{\em Shift-TV for unimodal pmfs.}
If $Z$ is integer-valued with unimodal pmf $h(k)=\mathbb{P}(Z=k)$, then
\begin{equation}
\TV(Z,Z+1)=\max_k h(k),
\end{equation}
by a simple telescoping argument.

\noindent{\em Anti-concentration for Poisson binomials (Barbour-Jensen; Baillon--Cominetti--Vaisman).}
If $Z=\sum_{j=1}^m \Ber(r_j)$ has variance $v=\Var(Z)$, then
[BAILLON_COMINETTI_VAISMAN_2016] proves the sharp bound
\begin{equation}
\max_k \mathbb{P}(Z=k)\le \frac{\eta_0}{\sqrt{v}}
\qquad (v>0),
\end{equation}
where $\eta_0$ is a universal constant
($\eta_0\approx 0.4688223555$, [BAILLON_COMINETTI_VAISMAN_2016]).\footnote{
L. Mattner ...","release_manifest_digest":"sha256:f8ff7816246622234c8333077542a5187180f7d7a92986f2e702283ac227dda1","revision_digest":"sha256:ae0b004ced1e7b1c816307a01ce60f06c74e19cbd83527fadc9b8e71082f101d","source_id":"arxiv:2601.04079","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

