body:
[Theorem thm:main of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For every $\varepsilon > 0$, there exist constants $c, C > 0$ such that for any $n \ge 1$, any $v \in [n]$ and any $S\in \left[ 1,c (n/v)^{1-\varepsilon} \right]$, the upper tail satisfies
    \begin{equation}
        c\frac{1+\log S}{S^2} 
        \ \leq\ \mathbb{P} \big( \widehat{\sigma}_{2}(v) \geq S v \big) 
        \ \leq\ C\frac{ 1+\log S}{S^2}.
    \end{equation}
    The upper bound holds for all $S\ge  1$.

    Moreover, there exist constants $c', C', \delta > 0$ such that for any $n \ge 1$, any $v \in [n/4]$, and any $S\in[1,\delta\sqrt{v}]$, the lower tail satisfies
    \begin{equation}
        \frac{c'}{S^2} 
        \ \leq\  \mathbb{P}\Big(\widehat{\sigma}_2(v) \leq \frac{1}{S}v\Big) 
        \ \leq\ \frac{C'}{S^2}.
    \end{equation}
    The upper bound holds for all $S \geq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 ({\cite{Bou02}}) of arXiv:2609.01965, 'A logarithmic Bogomolov--Sommese vanishing theorem on compact K\"ahler manifolds'] Let $X$ be a compact K\"ahler manifold and $L$ a pseudo-effective line bundle over $X$. 
    Then
    \begin{equation*}
        H^0(X,\Omega^p_X\otimes L^{-1})=0 \quad \text{for every } p<\nd(L),
    \end{equation*}
    where $\nd(L)$ denotes the numerical dimension of $L$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: many to one coupling of arXiv:2605.26869, 'Law of Large Numbers for a random walk on dynamic environments with drift'] For any environment satisfying ((pe:markov of the paper))-((pe:density of the paper)), (pe:drift of the paper), and (pe:couplings of the paper), there exists $L_0\geq 1$ such that the following holds. For all integers $L > L_0$, $f(L) \in [(\log L)^{90}, L^{1/10}]$ and $n\geq 1$, for any density $\rho > f(L)^{-1/40}$, 
    there exists a coupling $\mathbb{Q}_{n,L}$ of $(X^{(i)}_s)_{0 \leq s \leq n}$ for $i = 1,2$, 
    where $X^{(1)} \sim \mathbb{P}^{\rho, n}$ and $X^{(2)} \sim \mathbb{P}^{\rho + \varepsilon, L}$ with $\varepsilon \geq f(L)^{-1/40}$, such that 
    \begin{equation} 
        \mathbb{Q}_{n,L} \left( \min_{0 \leq s \leq n} \left(X^{(2)}_s - X^{(1)}_s \right) \leq - \left\lceil \frac{n}{L} -1 \right\rceil f(L) \right) 
        \leq \left( \left\lceil \frac{n}{L} \right\rceil -1 \right)^2  e^{-f(L)^{1/40}}.
    \end{equation}
    As a consequence, 
\begin{equation}
    v(\rho,n)\leq v(\rho+\varepsilon,L)+2\frac{n- L\lfloor n/L\rfloor}{n}+\left\lceil \frac{n}{L} -1 \right\rceil \frac{f(L)}{n}  +2\left( \left\lceil \frac{n}{L} \right\rceil -1 \right)^2  e^{-f(L)^{1/40}}.
\end{equation}
    \noindent
    The same holds when $X^{(1)} \sim \mathbb{P}^{\rho, L}$ and $X^{(2)} \sim \mathbb{P}^{\rho + \varepsilon, n}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 32 (Properties of the underdamped transient) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Let $\cS_{\mathrm{under}}(k)$ denote the deterministic bias contributed by the underdamped modes ($j \le J_{\max}$). Under the conditions of Proposition~\ref{prop:nes_deterministic_bias}, define the piecewise envelope $\mathcal{E}_{\mathrm{env}}(k)$ by:
\begin{equation*}
    \mathcal{E}_{\mathrm{env}}(k) := 
    \begin{cases}
    \rho^k, &\qquad k\lesssim\frac{1}{\eta},\\[2mm]
    \dfrac{\rho^k}{(\eta k)^s}, &\qquad \dfrac{1}{\eta} \lesssim k \lesssim \dfrac{1}{(1-\rho)^2},\\[3mm]
    \dfrac{1}{\eta k}\left(\dfrac{(1-\rho)^2}{\eta}\right)^{s-1}p_{\nesterov}^{\,k}, &\qquad \dfrac{1}{(1-\rho)^2} \lesssim k \lesssim \eta^{1/\beta}(1-\rho)^{-2-\frac{2}{\beta}},\\[3mm]
    \left(\dfrac{(1-\rho)^2}{\eta}\right)^{s+\frac{1}{\beta}}p_{\nesterov}^{\,k}, &\qquad k \gtrsim \eta^{1/\beta}(1-\rho)^{-2-\frac{2}{\beta}},
    \end{cases}
\end{equation*}
where $p_{\nesterov} := \rho\left(1 - \frac{(1-\rho)^2}{(1+\rho)^2}\right) = \frac{4\rho^2}{(1+\rho)^2} < \rho$. Then for every step $k \ge 0$, $\cS_{\mathrm{under}}(k)$ satisfies:
\begin{equation*}
    0 \le \cS_{\mathrm{under}}(k) \le C \mathcal{E}_{\mathrm{env}}(k).
\end{equation*}

[Lemma 7 of arXiv:2606.06231, 'Sensitivity of SDE Solutions to Perturbations of the Diffusion and Drift'] In addition to Assumptions \ref{assump:main_assumptions_1} and \ref{assump:h_assump1}, assume that $\rho(dt)$ is a finite positive measure on $[0,\infty)$ and $X_0=Y_0$.  Then, letting $\|\rho\|_{\mathrm{TV}}$ denote the total variation of $\rho$, we have
\begin{align}
&\sup_{T\geq 0}\left|\mathbb{E}\left[\int_0^T h(t,\tilde X_t)\rho(dt)\right]-\mathbb{E}\left[ \int_0^T h(t,Y_t)\rho(dt) \right]\right| \\
\leq&\frac{L_h(1+1/\epsilon)^{1/2}\|\sigma-\eta\|_{F,\infty}}{K_{\kappa,\epsilon}^{1/2}}
\left(\|\rho\|_{\mathrm{TV}}+M_h\tilde{D}\right)\notag\,,\\
&\tilde{D}\coloneqq  2\mathbb{E}[\| X_0\|^{2}]^{1/2}\int_0^\infty e^{-\tilde{K}_{\kappa,\delta}t/2}\rho(dt)+\frac{(1+1/\epsilon)^{1/2}\|\rho\|_{\mathrm{TV}}\|\sigma-\eta\|_{F,\infty}}{K_{\kappa,\epsilon}^{1/2}} \\
&+\frac{2}{\tilde{K}_{\kappa,\delta}^{1/2}}\left(2A_G+ \|\sigma\|_{F,\infty}^2    +    \frac{\kappa}{\delta}\frac{(1+1/\epsilon)\|\sigma-\eta\|_{F,\infty}^2}{K_{\kappa,\epsilon}}  \right)^{1/2}\|\rho\|_{\mathrm{TV}}  \,.\notag
\end{align}

[Lemma lem:combined-lower of arXiv:2609.01311, 'One-Layer Transformer Provably Learns Multiclass\\ One-Nearest Neighbor in Context'] For all $t \ge 0$,
\begin{equation*}
\tfrac{1}{\eta}\big(d(\xi_1^{t+1} - \xi_1^t) + 2(\xi_2^{t+1} - \xi_2^t)\big)
\ge \tfrac{K-1}{K}\big(1 - \tfrac{1}{2N}\big) C_d\, e^{-6\xi_1^t}.
\end{equation*}

