body:
[Thm general-I of arXiv:2605.21366, 'The Martin boundary of the Directed Landscape'] There exists an event of full probability on which the following hold, for any eternal solution $\mathfrak h$ and any $s\in\mathbb{R}$.
     \begin{enumerate} [label={\rm(\alph*)}, ref={\rm\alph*}]   \itemsep=3pt 
    \item For any $\vartheta\in\mathbb{R}\times\{-,+\}$, $S\in\{L,R\}$,  ${\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}}\in\{-,+\}$, and $r\in\mathbb{R}$, $I^{S,\mathfrak h}_\vartheta(s)={\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}}\infty$ is equivalent to $I^{S,\mathfrak h}_\vartheta(r)={\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}}\infty$.
    \item For each $S\in\{L,R\}$ and any $\vartheta_1\neq\vartheta_2$ in $\mathbb{R}\times\{-,+\}$, $I^{S,\mathfrak h}_{\vartheta_1}(s)=I^{S,\mathfrak h}_{\vartheta_2}(s)$ implies $I^{S,\mathfrak h}_{\vartheta_1}(r)=I^{S,\mathfrak h}_{\vartheta_2}(r)$ for all $r\le s$. We then say that  $I^{S,\mathfrak h}_{\vartheta_1}$ and  $I^{S,\mathfrak h}_{\vartheta_2}$ coalesced. 
    \item For each $S \in \{L,R\}$ and any distinct $\vartheta_1,\vartheta_2 \in \mathbb{R}\times\{-,+\}$,  if both $I^{S,\mathfrak h}_{\vartheta_1}$ and $I^{S,\mathfrak h}_{\vartheta_2}$ are finite, then they eventually coalesce. Consequently, for any $\vartheta_1\precneq\vartheta_2$ in $\mathcal V^{S,\mathfrak h}_s$, there exists $r < s$ such that  $\vartheta_2 \notin \mathcal V^{L,\mathfrak h}_r$ and $\vartheta_1 \notin \mathcal V^{R,\mathfrak h}_r$. 
    \item The representation (equation h-rep of the paper) can be restricted to $(\theta,{\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}})\in \mathcal V^{L,\mathfrak h}_s$:
    \begin{align}
    h(x,s)=\sup_{(\theta,{\raisebox{0.5pt}{\scaleobj{0.7}{\boxempty}}})\in\mathcal V^{S,\mathfrak h}_s}\bigl\{W^{\theta{\raisebox{1pt}{\scaleobj{0.6}{\boxempty}}}}(x,s;x_0,s_0)+a^{\theta{\raisebox{1pt}{\scaleobj{0.6}{\boxempty}}}}_{(x_0,s_0)}(\mathfrak h)\bigr\}
    \end{align}
More precisely, let $x_1<x_2$ be consecutive jump points of $x\mapsto \vartheta^{L,\mathfrak h}_{(x,s)}$ {\rm(}equivalently, consecutive values of $I^{L,\mathfrak h}_{\hspace{0.6pt}{\raisebox{1pt}{\scaleobj{0.6}{\bullet}}}\hspace{0.8pt}}(s)${\rm)}, allowing $x_1=-\infty$ or $x_2=\infty$ if there is no preceding or succeeding jump. Set $(\theta,{\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}})=\vartheta^{L,\mathfrak h}_{(x_2,s)}$, with the convention that if $x_2=\infty$, then $(\theta,{\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}})$ is the value attained after the last jump at $x_1$. Then
\begin{align}
\mathfrak h(x,s)=W^{\theta{\raisebox{1pt}{\scaleobj{0.6}{\boxempty}}}}(x,s;x_0,s_0)+a^{\theta{\raisebox{1pt}{\scaleobj{0.6}{\boxempty}}}}_{(x_0,s_0)}(\mathfrak h),
\quad \text{for all } x \in (x_1,x_2],
\end{align}
where the endpoint $x_2$ is excluded when infinite. An analogous statement holds with $L$ replaced by $R$, $(x_1,x_2]$ replaced by $[x_1,x_2)$, and $(\theta,{\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}})=\vartheta^{R,\mathfrak h}_{(x_1,s)}$, with the convention that if $x_1=-\infty$, the interval is $(-\infty,x_2)$ and $(\theta,{\raisebox{-0.2pt}{\scaleobj{1}{\boxempty}}})$ is the value before the first jump at $x_2$.
     \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 (Line-moment identities) of arXiv:2609.01513, 'An Independent Border-Free Type-A Cover of $Q_{221}$\\ and Improved Asymptotic Bounds for '] For a set of $d$ queens occupying exactly the line multisets
\eqref{eq:orthogonal-set}--\eqref{eq:sum-forced},
\begin{align}
  s_1+s_2&=2c,\\
  s_1^2+s_2^2-4c^2
  &=-16k\left(e^2-(2k+1)e+
  \frac{2k^2+3k+1}{3}\right).
\end{align}
Equivalently, if $s_1=c-t$ and $s_2=c+t$, then
\begin{equation}
  t^2=c^2-8k\left(e^2-(2k+1)e+
  \frac{2k^2+3k+1}{3}\right).
\end{equation}

[Theorem 10 of arXiv:2608.31145, 'Gauge-compatible tensors on statistical manifolds: splitting and submanifold geometry'] Let $M$ be a $\Theta$-CR submanifold of a $\Theta$-statistical
manifold.

\begin{enumerate}
\item For $X,Y\in\Gamma(D_{\Theta})$,
\begin{equation}
F_{\Theta}([X,Y])
=
h(X,\Theta Y)-h(Y,\Theta X).
\end{equation}

\item For $U,V\in\Gamma(D_{\Theta}^{\perp})$,
\begin{equation}
P_{\Theta}([U,V])
=
A_{\Theta U}V-A_{\Theta V}U.
\end{equation}
\end{enumerate}

Consequently:

\begin{enumerate}
\item[(a)] if
\[
\ker(F_{\Theta}|_{TM})=D_{\Theta},
\]
then $D_{\Theta}$ is integrable if and only if
\begin{equation}
h(X,\Theta Y)=h(Y,\Theta X)
\end{equation}
for all $X,Y\in\Gamma(D_{\Theta})$;

\item[(b)] if
\[
\ker(P_{\Theta}|_{TM})=D_{\Theta}^{\perp},
\]
then $D_{\Theta}^{\perp}$ is integrable if and only if
\begin{equation}
A_{\Theta U}V=A_{\Theta V}U
\end{equation}
for all $U,V\in\Gamma(D_{\Theta}^{\perp})$.
\end{enumerate}

[Lemma 14 (Lemma 5.1 of \cite{gz25}) of arXiv:2605.15386, 'The non-central gamma sum and difference distributions: exact distribution and asymptotic '] 1. Fix $a>0$, $b\in\mathbb{R}$, $m\in\mathbb{R}$ and let $u_0, u_1, \ldots $ be real-valued constants. Then, as $x\rightarrow\infty$,
	\begin{align}\nonumber
		\int_{x}^{\infty}t^m\exp\big(-at+b\sqrt{t}\big)\sum_{l=0}^{\infty}\frac{u_l}{t^{l/2}}\,\mathrm{d}t\sim\frac{x^{m}}{a}\exp\big(-ax+b\sqrt{x}\big)\sum_{p=0}^{\infty}\frac{U_p}{x^{p/2}},
	\end{align}
	where
	\begin{align*}
		U_p&=\sum_{\substack{i,j,k,l\geq0 \\ i+2j+k+l=p}}(-1)^{i+j}u_l\binom{2m+1-l}{k}\binom{2m-l-k-2j}{i}\frac{((l+k)/2-m)_j}{a^j}\bigg(\frac{b}{2a}\bigg)^{k+i}, \quad p\geq0.
	\end{align*}
	2. Fix $a>0$, $m\in\mathbb{R}$ and let $v_0,v_1,\ldots$ be real-valued constants. Then, as $x\rightarrow\infty$,
	\begin{equation}

		\int_{x}^{\infty}t^m\mathrm{e}^{-at}\sum_{j=0}^{\infty}\frac{v_j}{t^j}\,\mathrm{d}t\sim\frac{1}{a}x^m\mathrm{e}^{-ax}\sum_{k=0}^{\infty}\frac{V_k}{x^k}, \nonumber
	\end{equation}
	where $V_k=\sum_{j=0}^{k}v_j(k-m)_{k-j}/(-a)^{k-j}$ for $k\geq0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 24 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] For any $t \ge 0$, 
\begin{align*}
	&\prod_{k=1}^m ( \mu_t^\eta (A_k) )^{n_k} - \E_{\eta}\bigg[ \prod_{k=1}^m N_t^{(n_k)}(A_k^{n_k})  \bigg] = K^M\sum_{\bx \in H^M}U_M^K(t) F(\bx) - \sum_{\bx \in \Omega_M^K \cap H^M} h(\bx) V_M^K(t) F(\bx) .
\end{align*}

