[Proposition 4 of arXiv:2606.06757, 'Path-Dependent Ergodic Optimal Control \\ and Backward Stochastic Differential Equations'] Under Assumption~\ref{dissipativity_assumption}, for every $\tau \in \mathbb{R}$ and $\xi\in\mathcal{C}_\theta$, the SDE~\eqref{Functional_SDE} admits a unique strong solution $(X_t^{\tau, \xi})_{t\ge\tau}$. Moreover, the corresponding path process $(\mathcal{X}_t^{\tau, \xi})_{t\ge\tau}$ is a $\mathcal{C}_\theta$-valued time-inhomogeneous Markov process satisfying, for some constant $C>0$,
\begin{equation}
     \displaystyle |\mathcal{X}_t^{\tau, \xi} - \mathcal{X}_t^{\tau, \xi'}|_\theta \le Ce^{-\theta t}|\xi-\xi'|_\theta \, , \; d\mathbb{P}\otimes dt-\text{a.e. and} ~
     \displaystyle \sup_{\beta\in\mathcal{P}_B}\sup_{t\ge \tau} \, \E^\beta\big[|\mathcal{X}_t^{\tau, \xi}|_\theta\big]<\infty,~B>0.
\end{equation}
Moreover, there exists a evolution system of measures $(m_t)_{t \in \mathbb{R}}$ for the semi-group $P_{s, t}$.

[Corollary 3 of arXiv:2511.06196, 'Central limit theorem for high temperature spin models via martingale embedding'] In the model \cref{eq:Isingmodel}, assume that all the off-diagonal entries of the interaction matrix are nonnegative and the supremum of the Dobrushin constants satisfies $\sup_{n\geq 1}\alpha_n\leq \alpha<1$.
Let 
\be{
W_n=\frac{1}{\sqrt{n}}\sum_{i=1}^n X_i,\quad \mu_n:=\E(W_n), \quad \sigma_n^2:=\Var(W_n).
}
Then, as $n\to \infty$,
\ben{
\mathcal{W}_2 (\mathcal{L}(W_n), N(\mu_n,\sigma_n^2)\to 0.
}
If, in addition, $\|h\|_\infty$ is bounded by a universal constant, then
\ben{
\frac{W_n-\mu_n}{\sigma_n}\to N(0,1)\quad \text{in distribution.}
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma anisotropic:caff of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Assume $\Sigma\succ 0$,  $\nabla^2U_\rho\succeq \alpha_\rho$ and $\nabla^2U_\nu\preceq\beta_\nu$ for some $\alpha_\rho>0$ and $\beta_\nu\in (0,+\infty)$. If $\nabla^2\varphi^{0}_\varepsilon\succeq -\Sigma+A_0\,\Sigma$ for some matrix $A_0\succeq 0$ commuting with $\Sigma$, then for any $n\in\mathbb{N}$ we have
    \begin{equation}
    \nabla^2\varphi^{n}_\varepsilon\succeq -\Sigma +A_n\,\Sigma\quad\text{ and }\quad\nabla^2\psi^{n}_\varepsilon\preceq -\Sigma+ B_n\,\Sigma\,,
    \end{equation}
    where $(A_n)_{n\in\mathbb{N}}$ and $(B_n)_{n\in\mathbb{N}}$ are two sequences of positive semidefinite symmetric matrices iteratively defined via
    \begin{equation}
    \begin{cases}
        B_{n}=\Sigma (A_n\Sigma+\varepsilon\alpha_\rho)^{-1}\,,\\
        A_{n+1}=        \Sigma(B_n\Sigma+\varepsilon\beta_\nu)^{-1}\,,
    \end{cases}
    \end{equation}
    and converging to 
\begin{equation}
\begin{aligned}
A_\infty =&\,-\frac{\varepsilon\alpha_\rho}2\Sigma^{-1}+\biggl(\frac{\varepsilon^2\alpha_\rho^2}{4}\Sigma^{-2}+\frac{\alpha_\rho}{\beta_\nu}\biggr)^{\nicefrac12}\,,\\
B_\infty=&\,-\frac{\varepsilon\beta_\nu}2\Sigma^{-1}+\biggl(\frac{\varepsilon^2\beta_\nu^2}{4}\Sigma^{-2}+\frac{\beta_\nu}{\alpha_\rho}\biggr)^{\nicefrac12}\,.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 88 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $y \in D(A^2)$ be arbitrary. Then we have
\begin{align}
| S_{s-r,t-r}y - S_{s-q,t-q}y | \leq M e^{2 \omega T} |y|_{D(A^2)} |t-s| \, |r-q|
\end{align}
for all $s,t \in [0,T]$ with $s \leq t$ and all $q,r \in [0,s]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:hereditary-endpoint of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Suppose the seed chart is prime-energy stable with exponents $(a,\mu)$.
Then, for every fixed $t\in\mathbb Z_{\geq0}$,
\begin{equation}
 |\mathcal R(h,d+1+t)|\geq h^{2a-\mu+t-o(1)}.
\end{equation}
Thus the deficit $d-(2a-\mu)$ from the ambient exponent is invariant throughout
this prime-energy-stable suspension tower.  In particular, the endpoint
identity $2a-\mu=d$ implies
\begin{equation}
 |\mathcal R(h,d+1+t)|=h^{d+t+o(1)}
\end{equation}
for every fixed $t\in\mathbb Z_{\geq0}$.

