body:
[Theorem th:L2 of arXiv:2603.00705, '$L^2$-cutoff for the averaging process \\ on random regular graphs'] Let, for every integer $d\ge 3$,
			\begin{equation}
				\gamma=\gamma_d:= \begin{dcases}
					\varrho &\text{if}\ d\le 10\\
					\sigma &\text{if}\ d \ge 10\ ,
				\end{dcases}
			\end{equation}
			where
			\begin{equation}
			\varrho=\varrho_d:=\frac{2\sqrt{d-1}}{d}\ ,\qquad \sigma=\sigma_d:= \frac{\left(3\sqrt{d-1}-\sqrt{d-9}\right)\sqrt{d-1}}{4d}\ .
			\end{equation}
	Further, define (note that $\gamma \in (0,1)$, for all $d\ge 3$; see (equation eq:gamma-properties of the paper) below)
			\begin{equation}
				T(a):= \frac{1}{d\left(1-\gamma\right)}\log n+ a\log \log n\ ,\qquad a \in \mathbb{R}\ . 
			\end{equation}
		Then, 
		for every $\varepsilon> 0$, we have
			\begin{align}	
				\lim_{a\to -\infty}\liminf_{n\to \infty} \mathds{P}\bigg(\mathbf{E}_{\delta_1}\!
				\left[\left\|\frac{\eta_{T(a)}}{\pi}-1\right\|_2^2\right]>\varepsilon\bigg)&=1\ ,
		\\ 

				\lim_{a\to +\infty}\limsup_{n\to \infty} \mathds{P}\bigg(\mathbf{E}_{\delta_1}\!\left[\left\|\frac{\eta_{T(a)}}{\pi}-1\right\|_2^2\right]<\varepsilon\bigg)&=1\ .
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:f^ER_Bass-bounds of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Consider the Bass/{\rm SI} model~{\rm ((eqs:Bass-SI-models-ME of the paper),(eqs:ER-network of the paper))} on infinite sparse {\rm ER}~networks. 
	\begin{enumerate}
		\item 
		When $\lambda=0$, the expected/infection adoption level is the same as on networks of isolated nodes,
		i.e., 
		\begin{equation}

			f^{\rm ER}(t;p,q,I^0,\lambda=0) = f^{\rm isolated}(t;p,I^0),
			\qquad 	f^{\rm isolated}:=I^0 + (1-I^0)(1-e^{-pt}).
		\end{equation}


		\item  



		$\lim_{\lambda \to \infty} f^{ \text{\rm ER}}(t;p,q,I^0,\lambda) = f^{\rm compart}(t;p,q, I^0)$,

		where $ f^{\rm compart}$ is the expected adoption/infection level
		in the  compartmental Bass/{\rm SI} model
		\begin{equation}

			\frac{df}{dt} = (1-f)(p+qf), \qquad f(0) = I^0.
		\end{equation}

	\item  For $0<\lambda<\infty$,
		\begin{equation}

			f^{\rm isolated}(t;p,I^0)  < f^{\rm ER}(t;p,q,I^0,\lambda)  < f^{\rm compart}(t;p,q,I^0), \qquad t>0.
		\end{equation}
	\end{enumerate}

[Lemma 13 (Young / entropy inequality) of arXiv:2605.22445, 'Generalized specific entropy on Wiener space with application to Martingale Optimal Transp'] For all $x\ge 0$ and all $y\in\R$,
\begin{equation}
xy \le x\log x + e^{y-1}.
\end{equation}

[Def Random cluster representation of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] The generalised random cluster representation on a finite subset $\Lambda \subset \mathbb Z^d$ with parameters $\beta\geq  0$ and $\mathsf h\in (\mathbb R^+)^\Lambda$, and boundary conditions $(\xi,\mathsf{b})$ is the probability measure $\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}$ on $ \{0,1\}^{\overline E(\Lambda[\mathsf h])}\times (\mathbb R^+)^{\overline \Lambda} $ defined by
\begin{equation}
\mathrm{d}\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}[(\omega,\mathsf a)] = \phi^\xi_{\Lambda, \beta, \mathsf h, \mathsf a}[\omega] \mathrm{d}\mu^{(\xi,\mathsf{b})}_{\Lambda, \beta, \mathsf h}[\mathsf a].
\end{equation}
We write $\Phi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf{h}}$ for the distribution of the $\omega$-marginal of $\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}$.

[Proposition 11 (Upper semicontinuity) of arXiv:2603.27940, '\Large \bf Stability of supermartingale optimal transport problems'] Fix $r\in[1,\infty)$ and let $X, Y$ be Polish subspace of $\R$. Assume that $C:X\times\sP_r(Y)\to\R$ is measurable, upper semicontinous in the second argument, and there exists  $K>0$ so that 
    $$
    C(x,m)\leq K\left(1+\lvert x\lvert^r+\int_Y\lvert y\lvert^rm(dy)\right),\qquad \forall (x,m)\in X\times\sP_r(Y).
    $$
     For $k\in\N$, let $\mu^k\in\sP_r(X),\nu^k\in\sP_r(Y)$ with $\mu^k\cvd\nu^k$ converge in $W_r$ to $\mu$ and $\nu$, respectively. If one of the following holds: 
    \begin{itemize}
        \item[(A')] $C$ is upper semicontinuous in both arguments;
        \item[(B')] $\mu^k$ converges strongly to $\mu$. 
    \end{itemize}
    Then $$\limsup_{k\to\infty}V_S^C(\mu^k,\nu^k)\leq V_S^C(\mu,\nu).$$

[Corollary cor:f with a root at 0 of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\tilde{f}_n(z)=z^{m_n}f_n(z)$ for a sequence of $f_n\in\mathcal{LP}$ satisfying  Assumption (assump:main assumption of the paper). If $\{p_n\}_{n\geq 1}$ is a sequence of real-rooted polynomials indexed by their degree such that $\llbracket p_n\rrbracket\Rightarrow\mu$ and $\frac{m_n}{n}\rightarrow t\in [0,1)$, then \begin{equation}
		\llbracket \tilde{f}_{n}(\partial_z)p_{n}\rrbracket\Rightarrow\mathcal{D}_{1-t}\left(\mu\boxplus\mu_{c,\Sigma} \right)^{\boxplus\frac{1}{1-t}}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 50 of arXiv:2609.00758, 'Deformations of Compact Calabi--Yau and Fano Varieties with Isolated Singularities'] Let $X$ be a compact complex $n$-fold with isolated complete intersection singularities and whose resolutions satisfy the $\partial\db$ lemma. Denote by $L=\coprod_{x\in X^\sing}L_x$ the union of the links and suppose that 
\begin{equation}
\dim_\C H^2(Y,\Om^{n-1}_Y(\log E)(-E))\le\dim_\C H^2(Y,\Om^{n-1}_Y(\log E))
\end{equation}
Then the equality holds in \eq{h5}.

