body:
[Prop monot plus of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] The following properties hold.
\begin{enumerate}
    \item[$\bullet$] \textup{(FKG inequalities)} Let $\Lambda \subset \mathbb Z^d$ be finite, $\beta \geq 0$, $\mathsf h \in \mathbb R^\Lambda$. For all increasing and bounded functions $F,G:\mathbb R^\Lambda \rightarrow \mathbb R$,
    \begin{equation}
    \langle F(\tau) G(\tau) \rangle_{\Lambda,\beta, \mathsf h}^+ \geq \langle F(\tau) \rangle_{\Lambda,\beta,\mathsf h}^+  \langle G(\tau) \rangle_{\Lambda,\beta,\mathsf h}^+. 
    \end{equation}
    The same holds for the absolute value field if $\mathsf h_x \geq 0$ for every $x \in \Lambda$, namely
\begin{equation}
    \langle F(|\tau|)G(|\tau|) \rangle_{\Lambda,\beta,\mathsf{h}}^+\geq \langle F(|\tau|) \rangle_{\Lambda,\beta,\mathsf{h}}^+ \langle G(|\tau|) \rangle_{\Lambda,\beta,\mathsf{h}}^+.
\end{equation}
\item[$\bullet$] \textup{(Monotonicity in $\mathsf{h}$)} Let $\Lambda \subset \mathbb Z^d$ be finite, and $\beta\geq0$. Let also  $\mathsf{h}_1,\mathsf{h}_2\in \mathbb R^\Lambda$ be such that $\mathsf{h}_1\leq \mathsf{h}_2$. For every increasing and bounded function $F:\mathbb{R}^{\Lambda}\to\mathbb{R}$ we have 
\begin{equation}
\langle F(\tau) \rangle_{\Lambda,\beta,\mathsf{h}_1}^+\leq \langle F(\tau) \rangle_{\Lambda,\beta,\mathsf{h}_2}^+.  
\end{equation}
The same holds for the absolute value field if $|\mathsf{h}_1| \leq \mathsf{h}_2$. Namely, for every increasing and bounded function $F: (\mathbb{R}^+)^{\Lambda}\to\mathbb{R}$ we have 
\begin{equation}
\langle F(|\tau|) \rangle_{\Lambda,\beta,\mathsf{h}_1}^+\leq \langle F(|\tau|) \rangle_{\Lambda,\beta,\mathsf{h}_2}^+.  
\end{equation}
\item[$\bullet$] \textup{(Monotonicity of correlation functions)} Let $\Lambda \subset \mathbb Z^d$ be finite, $\beta\geq0$, $\mathsf{h},\mathsf{h}'\in (\mathbb R^+)^\Lambda$, and $A: \Lambda\to \mathbb{N}$. The function
$\beta \mapsto \langle \tau_A\rangle_{\Lambda,\beta,\mathsf{h}}^+$ is increasing. Moreover, if $\mathsf{h}'\leq \mathsf{h}$, one has $\langle \tau_A\rangle_{\Lambda,\beta,\mathsf{h}'}^+\leq \langle \tau_A\rangle_{\Lambda,\beta,\mathsf{h}}^+$.
\item[$\bullet$] \textup{(Comparison to the free measure)} Let $\Lambda \subset \mathbb Z^d$ be finite, $\beta\geq0$, $\mathsf{h}\in (\mathbb R^+)^\Lambda$, and $A: \Lambda\to \mathbb{N}$. One has
\begin{equation}
    \langle \tau_A\rangle_{\Lambda,\beta,\mathsf{h}}\leq \langle \tau_A\rangle^+_{\Lambda,\beta,\mathsf{h}}.
\end{equation}
\end{enumerate}

[Prop convdtX of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] Assume that Hypotheses (EU2 of the paper) hold true. For every small $\delta>0$ and $x\in E$ there exists a function $y_\delta(\cdot,x)\in C([0,T],{H})\cap C_b((0,T],E)$ such that
\begin{equation}
\lim_{\theta{\rightarrow} 0}\norm{y_{\delta,\theta}(\cdot,x)-y_{\delta}(\cdot,x)}_{C([0,T],{H})}=0,
\end{equation}
\begin{equation}
\lim_{\theta{\rightarrow} 0}\norm{y_{\delta,\theta}(\cdot,x)-y_{\delta}(\cdot,x)}_{C([\epsilon,T],E)}=0,\quad \forall\;\epsilon>0,
\end{equation}
and $y_\delta(\cdot,x)$  is the unique mild solution of (equation eqd of the paper) in $C([0,T],{H})\cap C((0,T],E)$.

In addition for every small $\delta>0$, for every $x,z\in E$ and $t>0$ we have
{\small
\begin{align}
&\abs{y_{\delta}(t,x)}_{H}\leq e^{\zeta t}{\left|x\right|}_{H}+(1+\delta\max\{0,\zeta_F\})\int_0^te^{\zeta (t-s)}\left({\left|F(f(s))\right|}_{H}+2\max\{0,\zeta_F\}{\left|f(s)\right|}_{H}\right)ds,\\
&\norm{y_{\delta}(t,x)}_E\leq e^{\zeta t}{\left\|x\right\|}_E+(1+\delta\max\{0,\zeta_F\})\int_0^te^{\zeta (t-s)}\left({\left\|F(f(s))\right\|}_E+2\max\{0,\zeta_F\}{\left\|f(s)\right\|}_E\right)ds,	\\
&{\left|y_\delta(t,x)-y_\delta(t,z)\right|}_{H}\leq  e^{\zeta t}{\left|x-z\right|}_{H}\\
&{\left\|y_\delta(t,x)-y_\delta(t,z)\right\|}_E\leq  e^{\zeta t}{\left\|x-z\right\|}_E,\\
&\abs{y_{\delta}(t,x)-y_{\tau}(t,x)}_{H}^2\leq C(\delta+\tau).
\end{align}
}
where $\zeta$ is the constant defined in (equation zeta of the paper) and $C$ is the constant given by (equation lipdelta of the paper)

[Theorem 1 of arXiv:2604.26026, 'Stochastic Ordering of Dependent Systems under Transformation Models and Archimedean Copul'] {Assume the parameter vectors $\boldsymbol{\alpha}$ and $\boldsymbol{\beta}$ are such that $\alpha_i\leq\beta_i$, for $i=1,\ldots,n$.} 
    \begin{enumerate}
    \item
    {If} $T$ is increasing in its first argument that is, $\alpha \leq \beta$ implies that, for every $x\in\mathbb{R}$, $T(\alpha, F) (x) \leq T(\beta, F) (x)$ and the generators are such that $\phi_2\circ\psi_1$ is super-additive{, then} {$X_{n:n}(\boldsymbol{\alpha})\geqst Y_{n:n}(\boldsymbol{\beta})$}.
    \item
    {If} $T$ is decreasing in its first argument that is, $\alpha\leq \beta$ implies that, for every $x\in\mathbb{R}$, $T(\alpha, F) (x) \geq T(\beta, F) (x)$ and the generators are such that $\phi_1\circ\psi_2$ is super-additive{, then} {$X_{n:n}(\boldsymbol{\alpha})\leqst Y_{n:n}(\boldsymbol{\beta})$}.
    \end{enumerate}

