[Lemma 15 of arXiv:2608.06392, '2608.06392'] Let the assumptions of {\hyperref[AISRLem-critical1]{Lemma~\ref{AISRLem-critical1}}} hold. Then
\begin{equation}
    \mu{\mathcal{S}_\mu}-\mu{s}\,\mathcal{L}(Q_F\ast{U})(s)
    \sim {\frac{1}{\,\mu\,}\int_{1/s}^\infty \frac{L(u)}{u}\,du}
    \qquad \text{as} \quad {s\downarrow{0}}.
\end{equation}

[Theorem thm:equivctdscausality of arXiv:2412.02948, 'Causal transport on path space'] A coupling $\pi \in \Pi\del{\eta,\nu}$ is a causal coupling if and only if the filtrations $\deln{\mathcal{H}^\eta_t \otimes \cbrn{\emptyset, \mathcal{W}^d}}_{t\in \sbr{0,1}}$ and $\del{\del{\mathcal{H}_t \otimes \mathcal{H}_t}^\pi}_{t+ \in \sbr{0,1}}$ on $\deln{\mathcal{W}^d \times \mathcal{W}^d, \mathcal{F}_1 \otimes \mathcal{F}_1, \pi}$ 
satisfy the  $H$-hypothesis:

  \begin{equation}

        \mathcal{M}^2\deln{\pi, \deln{\mathcal{H}^\eta_t \otimes \cbrn{\emptyset, \mathcal{W}^d} }_{t\in [0,1]}} \subseteq \mathcal{M}^2\deln{\pi, \del{\del{\mathcal{H}_t \otimes \mathcal{H}_t}^\pi}_{t+ \in \sbr{0,1}}}.
    \end{equation}

[Lemma eq:connected cluster bound of arXiv:2505.16585, 'Expanded regimes of area law for lattice Yang--Mills theories'] Let $\ell$ be a rectangular loop. For any $M \geq 0$, we have that
\begin{equs}
\#\{\mc{C} \sse \mc{P}_\Lambda^+ :\mc{C}\cup \ell\text{ is connected}, |\mc{C}|\leq M\} \leq e^{2d|\ell|} 50^{dM}.
\end{equs}

