[Proposition 13 (Supermartingale relaxation) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] For an adapted $\overline\Psi_t(\lambda)$, set
\begin{equation}
  E_t(\lambda) := \exp\!\bigl(\lambda Y_t - \overline\Psi_t(\lambda)\bigr).
\end{equation}
\begin{enumerate}[label=(\roman*),leftmargin=2em]
\item If $\overline\Psi_t(\lambda) = \Psi_t(\lambda) + D_t(\lambda)$ with $D(\lambda)$ predictable and nondecreasing, $D_0(\lambda) = 0$, then $E_t(\lambda) = \cE_t(\lambda)\,e^{-D_t(\lambda)}$ is a nonnegative supermartingale with $E_0(\lambda) = 1$, and its mean measures the discarded cumulant gap exactly:
\begin{equation}
  \E_P[E_t(\lambda)] = \E_{Q^\star_t}\bigl[e^{-D_t(\lambda)}\bigr] \leq 1 .
\end{equation}
\item In the setting of (i), for every $Q \ll P|_{\cF_t}$ the entropic equality~\eqref{eq:master-identity} relaxes to the entropic inequality
\begin{equation}
  \lambda\,\E_Q[Y_t] - \E_Q[\overline\Psi_t(\lambda)] \leq \KL(Q\|P|_{\cF_t}),
\end{equation}
with slack exactly $\KL(Q\|Q^\star_t) + \E_Q[D_t(\lambda)]$.
\item If~\eqref{eq:superexp} is a nonnegative supermartingale with $E_0(\lambda) \leq 1$ for an arbitrary adapted $\overline\Psi_t$---no exact-cumulant hypothesis---then $\log\E_P[E_t(\lambda)] \leq 0$, and~\eqref{eq:master} holds with slack $\KL(Q\|\overline Q^\star_t) - \log\E_P[E_t(\lambda)] \geq 0$, for $\dd \overline Q^\star_t/\dd P \propto E_t(\lambda)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 13 of arXiv:2604.06645, '2604.06645'] Under Assumptions \ref{assump: initial data are >= 0 and in L^oo}-\ref{assump: Integrability of kernel L}, for any fixed time horizon $T>0$,
    \begin{equation*}
\sup_{n\in \mathbb N} \mathbb E \sup_{t\in [0,T]}\sup_{x\in D}\sup_{i=1,...,m} |u_{i,n}(t,x)|^p < \infty.
\end{equation*}
In particular, system \eqref{eq: Theorem mxr system} has a unique global mild solution.

