body:
[Lemma 37 of arXiv:2604.04823, '2604.04823'] Suppose~$\underline \epsilon < \bar \epsilon$ and~$\nu \in (0, 1/\underline \epsilon)$. Set
    \begin{equation}
        N=\ceil*{1/\bar\nu\underline \epsilon}\,,\quad \epsilon_0 = \bar \epsilon\,,\quad \text{and}\quad \epsilon_N = \underline \epsilon\,,    
    \end{equation}
    and let
    $\paren*{1/\epsilon_k}_{k=0}^{N}$ be linearly spaced Then, 
    \begin{equation}
        \delta_\pt\geq M^{-1}\,, \quad\text{where}\quad M(U, \bar\nu) \defeq \exp\paren*{\bar\nu \norm{U}_{L^\infty}}\,.
    \end{equation}

