body:
[Lemma lem:approx-lemma-vapnik of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] Let $Q_\alpha(z)$ be a class of functions indexed by $\alpha\in \Lambda$, such that: 
\begin{enumerate}
    \item For each $\alpha\in \Lambda$, $Q_\alpha(z)$ is a nonnegative and measurable function
    \item Set collection $\{Q_\alpha(z)\}_{\alpha}$ has finite VC-dimension $V$, in the sense that the binary classifiers $\big\{z\mapsto \ind\{Q_\alpha(z) \ge t\}\big\}_{\alpha,t}$ has VC-dimension $V$.   
    \item For all $\alpha$, $\EE_z[Q_\alpha(z)^2] < \infty$. 
\end{enumerate} 
Then for i.i.d. dataset $\{z_i\}_{i\le n}$ drawn from a distribution such that $\EE_z[Q_\alpha(z)^2] < \infty$ for all $\alpha$, we have that for any $t > 0$ that
\begin{align}
    \PP\Big(\sup_{\alpha} \frac{\EE_z [Q_\alpha(z)]  - n^{-1}\sum_{i\le n} Q_\alpha(z_i)}{ \EE_z[Q_\alpha(z)^2]^{1/2}} >t\,  \sqrt{(1-\log t /2 )} \Big) \le 12 \frac{(2n)^V}{V!} \exp(-nt^2 /4).  
\end{align}
As a consequence, when $n \ge  V\log (2en/V) +\log(12/\delta)$, then with probability at least $1-\delta$, we have for any $\alpha\in \Lambda$ that 
\begin{align}
     \EE_z [Q_\alpha(z)]  \le  n^{-1}\sum_{i\le n} Q_\alpha(z_i) + 2 \EE[Q_\alpha(z)^2]^{1/2}\,   \sqrt{\frac{V\log(2en/V) + \log(12/\delta)}{n}}. 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 8 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Assume that conditions $({\bf A1})$-$({\bf A3})$ are satisfied.
\begin{description}
\item[(i)] For all $\delta > 0$
\begin{eqnarray*}
\lim_{\epsilon \rightarrow 0} \P\left(  \sup_{0\leq t \leq T} |X^\epsilon (t) - \mathcal{X} (t)| > \delta  \right)= 0. 	
\end{eqnarray*}
\item[(ii)] For $A\in \R$,  let define $\ Q^{\varepsilon}(A)=\P\left( Y^\varepsilon(.)^{-1}(A)\right)$. Then there exists a sub-sequence $Q^{\epsilon_n}$ which converges to $Q$  weakly in the Meyer-Zheng topology.
\end{description}

