body:
[Proposition prop:propA3 of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any integer $L \in \ensuremath{\mathbb{N}}$, any parameter $\lambda > 0$ and any collection of non-negative conductances $J:= \left( J_{xy,k} \right)_{\{x,y\} \in E(\Lambda_L), 1 \leq k \leq n}$, one has the identities:
\begin{itemize}
    \item For the partition functions:
    \begin{equation} 
        Z_{\Lambda_L, J, \lambda}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} = Z_{\Lambda_L,  J, \lambda}^{\mathrm{XY}}.
    \end{equation}
    \item For the variance of the height:
    \begin{equation*}
    \mathrm{Var}_{L  ,J , \lambda}^{\ensuremath{\mathbb{Z}}- \mathrm{XY}} \left[ \varphi(0) \right] = \left\langle \lambda \cos \left( \theta_{0g} \right) + \frac{\lambda^2}{2} \cos \left( 2 \theta_{0g} \right)  - \frac{\lambda^2}{2}  \right\rangle_{L , J, \lambda}^{\mathrm{XY}}.
    \end{equation*}
\end{itemize}

\begin{remark}
To be precise, the result is proved in~[van2023duality] for general graphs, but the extension to multigraph (considered here) is only notational.

\end{remark} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq: 678 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] {Vova25a} and [LS20]}]
Let $\Omega_{0}$ and $\Omega_{0}'$ as in (equation eq: 273 of the paper).
Define
\begin{equation*}
	\tilde{e}(\lambda)
	\coloneqq
	\exp\bigg\{ \frac{\mathrm{i}\lambda}{\pi}\int_{\Omega_{0}'}\frac{\partial\tilde{f}}{\partial\bar{z}}\Tr (G(z) - \mathbb{E} G(z))\mathrm{d}^{2}z\bigg\},
\end{equation*}
and
\begin{equation}
	\mathfrak{g} \equiv \mathfrak{g}(z, \lambda) \coloneqq \mathbb{E}[\tilde{e} (\lambda)  (G(z)-\mathbb{E}[G(z)])].
\end{equation}
Then it follows that
\begin{equation}
	\phi'(\lambda) = \frac{\mathrm{i}}{\pi}\int_{\Omega_{0}}\frac{\partial\tilde{f}}{\partial\bar{z}}
