[Theorem 24 (\textit{Convergence of the learning algorithms}) of arXiv:2607.21062, 'A new probabilistic approach for\\ mean field games of optimal stopping'] Under Assumptions \ref{assumption:1A}, \ref{assumption:1B}, \ref{assum:Tarski_1} and \ref{assum:Tarski_2} the following statements hold true.
    \begin{enumerate}
    \item[i)] The sequence $\{\underline{L}^n\}_n$ in \eqref{Sequence_underline} is non-decreasing, $\underline{L}^{n+1} \geq_{\mathcal{V}} \underline{L}^n$, and $\underline{L}^n$ converges to $\tilde{L}^{\text{min}}$ in $\mathbb{H}^2$.
    \item [ii)] The sequence $(\underline{X}^n, \underline{Y}^n, \underline{Z}^n, \underline{A}^n)$ is non-decreasing, it converges to $(\tilde{X}^{min}, \tilde{Y}^{min}, \tilde{Z}^{min}, \tilde{A}^{min})$ in $\mathbb{S}^2\times \mathbb{S}^2\times\mathbb{H}^2\times\mathbb{S}^2$.
    \end{enumerate}
    Assume, in addition, that $b, \sigma$ are independent of $m$ and $h$ is independent of $w$. Then
    \begin{enumerate}
        \item [iii)] The sequence $\{\overline{L}^n\}_n$ in \eqref{Sequence_overline} is non-increasing, $\overline{L}^{n+1} \leq_{\mathcal{V}} \overline{L}^n$, and $\overline{L}^n$ converges to  $\tilde{L}^{\text{max}}$ in $\mathbb{H}^2$.
    \item [iv)] The sequence $(\overline{X}^n, \overline{Y}^n, \overline{Z}^n, \overline{A}^n)$ is non-increasing, it converges to $(\tilde{X}^{max}, \tilde{Y}^{max}, \tilde{Z}^{max}, \tilde{A}^{max})$ in $\mathbb{S}^2\times \mathbb{S}^2\times\mathbb{H}^2\times\mathbb{S}^2$.
    \end{enumerate}

