[Proposition prop:stationary-BAR of arXiv:2607.03639, '\vspace{-0.6in}An AI-Assisted Solution to the Signed BAR Conjecture: Uniqueness in the Har'] Start the SRBM with $Z_0\sim\pi_0$ and write it in the original normalization as
\begin{equation}
 Z_t=Z_0+\mu t+\Sigma^{1/2}W_t+RY_t,
\end{equation}
where each $Y_i$ is continuous, nondecreasing, starts from zero, and increases only on $F_i$. Define, for Borel $B\subset F_i$,
\begin{equation}
 \nu_i^0(B)=\mathbb E_{\pi_0}\int_0^1\mathbf 1_B(Z_s)\,dY_i(s).
\end{equation}
Then each $\nu_i^0$ is a finite measure supported on $F_i$, and (equation eq:intro-stationary-BAR of the paper) holds.

[Theorem 15 (existence and regularity of the ULA stationary distribution) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] Suppose that $G' \in C^1_{\mathrm b}([0,\infty))$ and that \cref{ass:moment} holds.

  \begin{enumerate}[label=\textup{(\roman*)}]
    \item \textup{(existence and uniqueness)}
      For every $h > 0$ sufficiently small, $K_h$ is irreducible and has a unique stationary probability measure $\pi_h$.

    \item \textup{(smooth density on the interior)}
      The absolutely continuous part of $\pi_h$ on $(0,\infty)$ admits a density $\rho_h \in C^1((0,\infty))$ with respect to Lebesgue measure.  Equivalently, the relative density $w_h \coloneqq d\pi_h/d\pi_0$ exists and lies in $C^1((0,\infty))$.
  \end{enumerate}

[Lemma lemmaA1 of arXiv:2504.14457, 'Abstract'] For any $a>0$, we have
\begin{align}
\nonumber    \sum_{n\geq 0} \frac{x^n}{(n!)^a}\leq c_1 \exp (c_2 x^{1/a})\hspace{7mm} \text{for all }x>0,
\end{align}
where $c_1>0$ and $c_2>0$ are some constants depending on $a$. (Proof in the paper; no proof environment follows the statement in the TeX.)

