		\end{align}
		where $c_0$ is the constant appearing in \eqref{eqn-data-inter}, then for any $\delta\ge 0$, any stopping time $\tau$ and any $t \ge 0$:
		\begin{align}
			\mathbb{E}\left[e^{\left(\frac{\kappa}{1+\delta} -  L \right)t\wedge \tau  -  \frac{27[\mathrm{N}_d]^4}{16\lambda_1\nu^3\varepsilon_0^3} \int_0^{t\wedge \tau}\|\Arm(\u(s))\|_{4}^4\drm s}\left\| \u(t\wedge \tau)-\Urm(t\wedge \tau) 
			\right\|_{2}^2\right] 
			&\leq \left\|\u_0 - \Urm_0 \right\|_{2}^2.
		\end{align}

