[Theorem 5 of arXiv:2512.07156, 'Lorenz ordering of parasite loads across hosts in Isham's model of Host-Macroparasite Inte'] For each $j \in \mathbb{N}_0$, define $\beta_j = \sum_{i=j+1}^\infty \pi_C(i)$ and the function $\omega_j :[0,1] \to [0,1]$ such that 
\begin{equation}
    \omega_j(\lambda)  = \left\{ \begin{array}{ll}
    \frac{\beta_j (1-\lambda)\lambda^j}{1-G_C(\lambda)}, & \lambda \in [0,1) \\
    \frac{\beta_j}{G_C^{\prime}(1)}, & \lambda = 1
    \end{array} \right. 
    . 
\end{equation}
If $\beta_j \neq 0$, define the function $G_j : [0,1] \to [0,1]$ such that
    \begin{equation}
        G_{j}(z)  = 1 -  \int_z^1 \frac{G_C(u) - \sum_{i=0}^{j} \pi_C(i) u^i}{\beta_j u^{j+1}} du,  
    \end{equation}
Then (i) each $G_j(z)$ is a valid PGF with $G^\prime_j(1) = 1$, (ii) for any $\lambda \in [0,1]$, $\sum_{j=0}^\infty \omega_j(\lambda) = 1$, and (iii) for $\lambda \in [0,1)$,
\begin{equation}
G_M(\infty;z)  = \exp\left(\frac{\phi(1-G_C(\lambda))}{\alpha} \sum_{j=0}^\infty \omega_j(\lambda) \left(G_j(z) -1\right) \right)

\end{equation}
and for $\lambda = 1$, 
\begin{equation}
G_M(\infty;z)  = \exp\left(\frac{\phi\,  G^\prime_C(1)}{\mu_M} \sum_{j=0}^\infty \omega_j(1) \left(G_j(z) -1\right) \right).

\end{equation}

