body:
[Thm finite_oracle_ineq_p0 of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] Fix $p_0\in(0,1)$. Let
$
M_0:=m(p_0)=\lceil \frac{1}{p_0}\rceil-1$
and 
$$
\mathcal B_{p_0}
:=
\bigg\{\frac{1}{k}: k=2,\dots,M_0+1\bigg\}
.
$$
Let $\Delta_p:=\mathrm{dist}(p,\mathcal B_{p_0})=\min\{|p-q|:q\in \mathcal B_{p_0}\}$. Then, (i) there exist positive constants $C_1(p_0),C_2(p_0)$, and $c(p_0)$ such that for all $n\ge 2$ and all $p\in[p_0,1)$,
\begin{equation}

V_n(p)-W_n(p)
\le 
C_1(p_0)
\Delta_p
e^{-c(p_0)n\Delta_p^2}
 +
C_2(p_0)
e^{-c(p_0)n}
.
\end{equation}
(ii) For~$p_0>\frac{1}{2}$, there exist positive constants $C(p_0),c(p_0)$ such that for all $n\ge 2$,
\begin{equation}

\sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n(p)\bigr)
\le 
C(p_0)e^{-c(p_0)n}
,
\end{equation}
whereas for~$p_0\leq \frac{1}{2}$,  there exists a positive constant~$C(p_0)$ such that for all $n\ge 2$,
\begin{equation}

\sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n(p)\bigr)
\le 
\frac{C(p_0)}{\sqrt{n}}
.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem definingODEsystem of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] The pair $(\rho^\lambda_t,\varphi^\lambda_t)$ satisfies the following ODE system:
\begin{equation}
\left\{
\begin{array}{lllll}
\dot{\rho}^\lambda_s=\lambda\rho^\lambda_s\cos(\theta_s-2\varphi^\lambda_s)\\
\dot{\varphi}^\lambda_s=\lambda\sin(\theta_s-2\varphi^\lambda_s)\\
\varphi^\lambda_0=\zeta.
\end{array}
\right.\end{equation}

