[Proposition prop.l2control.lowerbound of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] For $T>0$, the forward-backward stochastic differential equation
    \begin{equation}
        \left\{
            \begin{alignedat}{2}
                dX(t) &= -c_0 \frac{Y(t)}{\|Y(t)\|_{2}}\,dt + dB(t),\qquad&& X(0) = 0,\\
                dY(t) &= Z(t)\, dB(t),\qquad&& Y(T) = \frac{X(T)}{\|X(T)\|_2},
                \qquad \smash{\raisebox{\normalbaselineskip}{$0 \le t \le T$,}}
            \end{alignedat}
        \right.
    \end{equation}
    has a unique solution $(X,Y,Z)$, given by
    \begin{equation}
        X(t) = \int_0^t \frac{w(t)}{w(s)}\,dB(s),\quad Y(t) = \int_0^t Z(s)\,dB(s),\quad Z(t) = \frac{2c_0 w(T)}{w(t)(1-w(T))},
    \end{equation}
    for $0 \le t \le T$, where
    \begin{equation*}
        w(t) \coloneqq -W_0\big(-e^{-2c_0^2 t - 1}\big) \in (0,1].
    \end{equation*}
    Here, $W_0$ denotes the principal branch of the Lambert $W$-function. Moreover, for $0 < t \leq T$,
    \begin{equation}
        \|X(t)\|_2 = \frac{1-w(t)}{2c_0},\qquad \frac{Y(t)}{\|Y(t)\|_2} = \frac{X(t)}{\|X(t)\|_2}.
    \end{equation}
    Consequently, the process
    \begin{equation}
        \alpha(t) \coloneqq -c_0 \frac{X(t)}{\|X(t)\|_2},\qquad 0 < t \le T.
    \end{equation}
    is the unique optimal control for $V_T^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 (\cite{nualart2006malliavin}, Chapter 1) of arXiv:2604.23462, 'Invariant measures for the open KPZ equation: the Gaussian case'] Let $W$ be either space-time white noise on $\mathbb{R}_+ \times [0,1]$ or spatial white noise on $[0,1]$. Then for any deterministic $f \in L^2$ on the corresponding domain and any random variable $F$ in the Malliavin-Sobolev space $\bb{D}^{1,2}$, we have that
        \begin{align*}
            \bb{E}\left[F \inn{W,f}\right] = \bb{E}\left[\inn{\ms{D}F, f}_{L^2}\right],
        \end{align*}
        where $\ms{D}$ denotes the Malliavin derivative operator associated to $W$. (Proof in the paper; no proof environment follows the statement in the TeX.)

