[Thm main1 of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] Let $M,\delta>0$ and $\rho_{M,\delta}$ be defined as in (72191 of the paper), and $ X_{M,\delta}(t)$ be the process 
defined in (non-indicator of the paper). Then, for any $\lambda\ge 0$, the process $X_{M,\delta,\lambda}(t)
=(X_{M,\delta}(t))^{\lambda/\delta}$ is a solution process satisfying (equation alphrecursion of the paper) with $u_0=1$, 
and the function $u_{M,\delta,\lambda}(t)=\mathbb{E}( X_{M,\delta,\lambda}(t))$ solves the problem 
(equation diffalpha-ricc of the paper) with $u_0=1$. Moreover: 
\begin{enumerate}[(i)]
\item \begin{equation}
\lim_{t\to\infty}\frac{1-u_{M,\delta,\lambda}(t)}{t^{-\gamma}}={\lambda}.\end{equation}
\item For any $t>0$,
\begin{eqnarray*}
u_{M,\delta,\lambda}(t)&>&u_{M,\delta,\lambda'}(t)\ \ \ \textup{if}\ \ 0\le\lambda<\lambda',\\
u_{M,\delta,\lambda}(t)&\le&u_{M',\delta,\lambda}(t)\ \ \ \textup{if}\ \ M< M',\ 0<\delta<\min\{\delta_M,\delta_{M'}\}\\
u_{M,\delta,\lambda}(t)&\ge&u_{M,\delta',\lambda}(t)\ \ \ \textup{if}\ \ 0<\delta<\delta'<\delta_M.
\end{eqnarray*}
\end{enumerate}

