[Lemma 1 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let $M$ be an $(\F^i,\P)$-martingale $($respectively, an $(\F_N,\P)$-martingale$)$. There exists a unique process $Z \in \H^2_{\mathrm{loc}}(\F^i,\P,\R^d)$ $($respectively, $(Z^\ell)_{\ell \in \{1,\ldots,N\}}$ with each $Z^\ell \in \H^2_{\mathrm{loc}}(\F_N,\P,\R^d))$ such that
\begin{equation*}
M_{t} = M_0 + \int_0^t Z_s \cdot \d W^i_s \; \bigg(\text{\rm respectively,} \; M_{t} = M_0 + \int_0^t \sum_{\ell =1}^N Z^\ell_s \cdot \d W^\ell_s\bigg),\; t \in [0,T],\; \P \text{\rm --a.s.}
\end{equation*}
Moreover, this property is preserved under an equivalent change of measure, see for instance {\rm\cite[Theorem III.5.24]{jacod2003limit}}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:global_subgraph_clt of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Assume that there are sequences $\sigma_n \gtrsim n$ and $\delta_n \to 0$ such that
\begin{equation}
    \mathbf{d}_\mathrm{Was}\mleft(\frac{\mathsf{E}(X) - \mathbb{E}[\mathsf{E}(X)]}{\sigma_n}, Z \mright) \leq \delta_n,
\end{equation}
where $Z \sim \mathcal{N}(0,1)$.
Then for all $\varepsilon > 0$,
\begin{equation}
    \mathbf{d}_\mathrm{Was}\mleft(\frac{\mathsf{N}_G(X) - \mathbb{E}[\mathsf{N}_G(X)]}{2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \sigma_n}, Z\mright)
    \lesssim n^{-\frac{1}{2}+\varepsilon} + \delta_n.
\end{equation}

