[Definition 3 of arXiv:2505.16701, 'Open interacting particle systems and Ising measures'] The generalized open KLS model on the one-dimensional finite integer lattice $\Lambda_L := \{1,\dots,L\}$ is defined by the generator \eqref{genASEP}
with bulk jump rates \eqref{bjr} given by \eqref{rGKLS},  \eqref{lGKLS}
for $2\leq k \leq L-2$, boundary jump rates $w_1(\cdot) = r^{-}(\cdot) + \ell^{-}(\cdot)$,  $w_L(\cdot) = r^{+}(\cdot) + \ell^{+}(\cdot)$ given by
\begin{eqnarray}
r^{-}(\bfeta) & = & \eta_{1} \bar{\eta}_{2} \left[ r^{-}_{1} \bar{\eta}_{3}
+ r^{-}_{2} (1-\epsilon) \eta_{3} \right] 
 \\
\ell^{-}(\bfeta) & = & z_{-} z^{-1} \bar{\eta}_{1} \eta_{2} 
 \left[ \ell^{-}_{1} \bar{\eta}_{3} + \ell^{-}_{2} (1+\epsilon) \eta_{3} \right]
 \\
r^{+}(\bfeta) & = & z_{+} z^{-1} \eta_{L-1} \bar{\eta}_{L}\left[ r^{+}_{1} \bar{\eta}_{L-2} + r^{+}_{2} (1+\epsilon) \eta_{L-2} \right] 
\\
\ell^{+}(\bfeta) & = & \bar{\eta}_{L-1} \eta_{L} \left[ (\ell^{+}_{1}
\bar{\eta}_{L-2} + \ell^{+}_{2} (1-\epsilon) \eta_{L-2} \right] 

\end{eqnarray}
for the boundary bonds $(1,2)$ and $(L-1,L)$ respectively,
and insertion and removal of particles with rates
\eqref{boundaryrates} given by
\begin{eqnarray}
\alpha(\bfeta) & = & z_{-} \bar{\eta}_{1} (\alpha_1 \bar{\eta}_2 + \alpha_2 \eta_{2}) 
 \\
\gamma(\bfeta) & = & \eta_{1} (\gamma_1 \bar{\eta}_2 + \gamma_2 \eta_{2}) 
 \\
\beta(\bfeta) & = &   \eta_{L} (\beta_1 \bar{\eta}_{L-1} + \beta_2 \eta_{L-1})
 \\
\delta(\bfeta) & = &  z_{+} \bar{\eta}_{L} (\delta_1 \bar{\eta}_{L-1} + \delta_2 \eta_{L-1}) 

\end{eqnarray}
for the boundary sites $1$ and $L$ respectively.

[Lemma 15 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Let $f \in \bb H^{\epsilon}(\R^d \setminus [\mathsf{blocks}])$. It holds for any $k \in K$  that 
		\begin{equation}
			 e^{\skalar{\bb \xi^*, s}}\E [f(e^{-\mathbf{s}\slash 
			\a}k \bb X) ]= g_{\bb \xi^*} * \wt{\mathds{U}}_{\bb \xi^*}(\bb s, k).
		\end{equation}
		In particular, there is $C$ independent of $f$ such that
		\begin{equation}
			 \sup_{\bb s, k} \abs{e^{\skalar{\bb \xi^*, s}}\E [f(e^{-\mathbf{s}\slash 
				\a}k \bb X)]} \le C \norm{g_{\bb \xi^*}}_{\dri} 
		\end{equation}
		 and moreover
		 \begin{equation}
		 	 \sup_{t >1} \,  (\log t)^{1/2} t^{\xi^*_1+ \xi^*_2} \abs{\E\Big[ f\big(t^{-1/\bb \alpha} \bb X\big)\Big]} ~\le~  C \norm{g_{\bb \xi^*}}_{\dri}. 
		 \end{equation}

[Lemma bound-on-loop-operations of arXiv:2505.16585, 'Expanded regimes of area law for lattice Yang--Mills theories'] For any $(s, K)$ with $s$ non-null, any edge $\mbf{e}$ of $s$, and $K : \mc{P}_\Lambda^+ \ra \N$, we have that
\begin{equs}
| \mbb{D}_+(s, \mbf{e}, K) \cup \mbb{D}_-(s, \mbf{e}, K)| \leq 4d.
\end{equs}
If additionally $(s, K) \in \Omega_B$, then
\begin{equs}
| \mbb{S}_+(s, \mbf{e}) \cup \mbb{S}_-(s, \mbf{e})| &\leq 2dB, \\
| \mbb{M}_+(s, \mbf{e}) \cup \mbb{M}_-(s, \mbf{e})| &\leq 2dB. 
\end{equs} (Proof in the paper; no proof environment follows the statement in the TeX.)

