[Proposition prop:extsphere:interiorcone of arXiv:2512.13200, 'Martingales on a Euclidean manifold with a boundary and reflected BSDEs in non-convex doma'] $ $
    \begin{itemize}
        \item  For all $x \in \partial \mathcal{D}$, $\mathfrak{n}(x) \supsetneq \{0\}$.
        \item $\mathcal{D}$ satisfies the interior cone condition: for all $x \in \partial \mathcal{D}$, there exists $\varepsilon>$ and a closed cone $\mathcal{K}$, centered at $x$ and having non-empty interior, such that $\mathcal{K} \cap B(x,\varepsilon) \subset \bar{\mathcal{D}}$.
        \item {There exist $\alpha>0$, $R>0$,  $y_1,\ldots,y_n\in \partial\mathcal{D}$ and $a_1,\ldots, a_n\in\mathbb{R}^d$, such that: $|a_i|=1$ for all $i$, $\partial\mathcal{D}\subset \bigcup_{i=1}^n B(y_i,R)$, and $\xi\cdot a_i\geq\alpha$ for all $\xi\in\mathfrak{n}_u(y)$, all $y\in \partial\mathcal{D}\cap B(y_i,2R)$ and all $i$.}
        \item $\mathcal{D}$ satisfies the exterior sphere property: i.e., there exists $R_0$ such that, for all $x \in \partial \mathcal{D}$, $u \in \mathfrak{n}_u(x)$ and $x' \in \bar{\mathcal{D}}$, 
        \begin{equation}

            (x-x')\cdot u +\frac{1}{2R_0} |x-x'|^2 \geqslant 0.
        \end{equation}

    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:resolvent-bounds-cutoff-support of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] Let $R_k := R_k(z,t)$.
Let $T \in M_N(\mathbb R)$ be any constant symmetric matrix.
    On $\{\chi_k \ne 0\}$ and when $\Re[z] =: a \in [0,1]$ and $\Im[z] =: b$ satisfies $|b| < 1$, we have $\min\Spec(|z I_{N}-\beta W_k(t)+D_k|) \geqslant \gamma$ and $\opnorm{z I_{N}-\beta W_k(t)} \leqslant 3-\gamma$.

As a result, $z \mapsto R_k(z, t)$ is analytic when $\Re[z] \geqslant 0$ and $\chi_k \ne 0$, and the following bounds hold over $\Re[z] \geqslant 0$:

\begin{enumerate}[label=(\alph*), ref=\thetheorem(\alph*)]
\item 

\begin{equation*}
\ensuremath{\left\lVert \chi_kR_k \right\rVert_\mathsf{op}}\leqslant \gamma^{-1},
\qquad
\opnorm{\frac{1}{b}\Im [\chi_kR_k]}
\leqslant \gamma^{-2}.
\end{equation*}
\item 

\begin{equation*}
\ensuremath{\left\lVert \chi_kD_kR_k^2D_k \right\rVert_\mathsf{op}}\leqslant 9\gamma^{-2}.
\end{equation*}
\item

\begin{equation*}
\schnorm{\chi_k R_k D_k T D_k R_k} \leqslant 9\gamma^{-2}\schnorm{T},
\qquad
\schnorm{\frac{1}{b}\Im[\chi_kR_kD_kTD_kR_k]}
\leqslant 18\gamma^{-3}\schnorm{T}.
\end{equation*}
\item

\begin{equation*}
\schnorm{\chi_kR_k^2D_kTD_kR_k} \leqslant 9\gamma^{-3}\schnorm{T},
\qquad
\schnorm{\frac{1}{b}\Im[\chi_kR_k^2D_kTD_kR_k]}
\leqslant 27\gamma^{-4}\left\lVert{T}\right\rVert_2.
\end{equation*}
\end{enumerate}

[Proposition eul_id_projection of arXiv:2411.13707, 'High-degree cubature on Wiener space \\ through unshuffle expansions'] The Eulerian idempotent is a projection onto $\mathcal L(V)$, and $x \in T(V)$ can be expressed as a symmetric product of Lie elements by
\begin{equation}
x = \sum_{n \geq 0} \frac{1}{n!} {(\mathrm{e}(x^{(1)}),\dots ,\mathrm{e}(x^{(n)}))} .
\end{equation}
In other words, this provides an isomorphism
\begin{equation}
\bigoplus_{n = 0}^\infty \frac{\mathrm{e}^{\star n}}{n!} \colon T(V) \xrightarrow{\cong} \bigoplus_{n = 0}^\infty \mathcal L(V)^{\odot n}.
\end{equation}
\begin{proof}
Writing $\mathbbm 1 = \exp_\star (\log_\star(\mathbbm 1))$ yields the identity
\[
x = \exp_\star (\mathrm{e})(x) = \sum_{n \geq 0} \frac{\mathrm{e}^{\star n}(x)}{n!} ,
\]
which coincides with the expression in the first statement, thanks to (equation eq:star of the paper).
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 (Survival of lineages from $-n$ infinitely often) of arXiv:2607.02019, 'Critical branching processes in random environment with immigration and an application to '] Under hypotheses (H1) and (H2) there exists $\e>0$ such that
