[Definition 8 (Spearman rank correlation coefficient) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Let $a=(a_1,\dots,a_N)$ and, $ b=(b_1,\dots,b_N)]$ be two sets of paired observations. Let $\rank(a_i)$ and $\rank(b_i)$ denote the ranks of $a_i$ and $b_i$, respectively, and define $d_i= \rank(a_i) - \rank(b_i)$.
Assuming there are no tied ranks, the Spearman  correlation coefficient between $a$ and $b$ is
\begin{align}
\rho(a,b)
=
1-\frac{6\sum_{i=1}^{N} d_i^2}
{N(N^2-1)}.
\end{align}

[Proposition 4 of arXiv:2511.00679, 'Stochastic solutions to abstract telegraph-type equations involving fractional dynamics'] Let $\{B(t):t\geq 0\}$ be the standard Brownian motion. We get that
\begin{align*}
\widehat\Phi_\frac{1}{2}(t,\xi) =\mathbb E \left[g(|B(t)|,\xi)\right],
\end{align*}
where 
$$g(t,\xi):=e^{-\lambda t}\left[\cosh(t\sqrt{\lambda^2-m(\xi)})+\frac{\lambda}{\sqrt{\lambda-m(\xi)}}\sinh(t\sqrt{\lambda^2-m(\xi)})\right].$$

[Lemma 40 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 7$, there exists $\Cl>0$ such that for any $n\ge \Cref{const_disjoint_highd1}$, $N\ge \Cref{const_disjoint_highd1}n$, $\psi=(v_1,v_2,w_1,w_2)\in \Psi(n,N)$, 
	\begin{equation}
	\mathbb{E}\Big[\mathbbm{1}_{v_1\xleftrightarrow{} w_1}\cdot \big(  \widetilde{G}(v_2,w_2) -  \widetilde{G}_{\mathcal{C}_{v_1}}(v_2,w_2) \big)  \Big]\lesssim n^{6-d}N^{4-2d}. 
	\end{equation}

