[Theorem 5 (Strict speed-up on $\Z_{\ge 0}$) of arXiv:2605.28766, 'Convex order and faster transmission in first contact percolation'] Let $\X,\X'$ be $\Z$-stationary random closed sets such that $\X$ dominates $\X'$ in terms of hitting probabilities. Additionally, assume that there exists an interval $[a,b]$,
    with $a\le b$, such that
\begin{equation}
        3\bbP(\X'([a,b])>0) < \bbP(\X([a,b])>0),
    \end{equation}
    as well as \eqref{eq:finite-waiting-time} for $\X$ and that $\X'$ has no atoms. Then, $c_\X<c_{\X'}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 41 (Asymptotics as $\alpha \to \alpha^*_\pm$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose that $x^* \in (0, \M).$
Then, the following asymptotics hold: 
\begin{itemize} 

\item[$(i)$] If $\alpha > \alpha^*_+$ and $r(\alpha -\alpha^*_+)^2 \to \infty$, then
\begin{equation}
     g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim}C_*'f_*(z_0) \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}  (x(\alpha)-x^*)}
\end{equation}
where $$C_*'= -C^+(\alpha^*_+)\frac{\gamma(x^*,Y^+(x^*),Z^+(x^*))}
{\frac{d}{dx}\gamma(x,Y^-(x), Z^+(x))\big|_{x=x^*}} > 0$$   
and where $C^+(\alpha^*_+)$ is given by~\eqref{C(alpha)}.

\item[$(ii)$]  If $\alpha >\alpha^*_+$ and $r(\alpha -\alpha^*_+)^2 \to c>0$, then 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} \frac{1}{2}C_*^+ \Big(1-\textnormal{erf}\Big(\sqrt{c} A(\alpha^*_+ )\Big)\Big) f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}
where $C^+_*$ is given by \eqref{eq:C+*}, $A(\alpha^*_+) = \frac{-x'(\alpha^*_+)}{x'_\omega(0,\alpha^*_+)}$ and where $x'_\omega(0,\alpha^*_+)$ is defined in \eqref{zop}.

\item[$(iii)$] If $r (\alpha -\alpha^*_+)^2 \to 0$, then 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} \frac{1}{2}C_*^+ f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}

\item[$(iv)$]  If $\alpha <\alpha^*_+$ and $r (\alpha -\alpha^*_+)^2 \to c>0$, then 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} \frac{1}{2}C_*^+ \Big(1+\textnormal{erf}\Big(\sqrt{c} A(\alpha^*_+ )\Big)\Big) f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}

\item[$(v)$]  If  $\alpha<\alpha^*_+$ and $r (\alpha -\alpha^*_+)^2 \to \infty$, then
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} C_*^+ f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}
\end{itemize} 
The symmetric asymptotics hold as $\alpha \to \alpha^*_-$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Deterministic nonlinear reservoir kernel) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $\psi\in C_b^1(\mathbb{R})$. For fixed $L,t,s$ and a deterministic
bounded input sequence $(u_r)_r$, as $n\to\infty$,
\begin{equation}
  K_{\psi,n,\theta}^{(L)}(t,s)
  \xrightarrow{\mathbb{P}}
  K_{\psi,\theta}^{(L)}(t,s),

\end{equation}
where
\begin{equation}
\begin{aligned}
  K_{\psi,\theta}^{(L)}(t,s)
  &:=\mathbb{E}\!\left[\psi(g_t)\psi(g_s)\right], \\
  (g_t,g_s)
  &\sim\mathcal{N}\!\left(
    0,\Sigma_{\theta}^{(L)}(t,s)
  \right).
\end{aligned}

\end{equation}
The convergence is in probability with respect to the joint randomness
of $W_r$ and $W_{\rm in}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

