[Lem lem15 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Assume ((h of the paper)), ((f0 of the paper)) and ((f1 of the paper)) 
  with some $\lambda>1$,
  and let $p\ge 2$ and $r\ge \max\{p,2\lambda\}$ be such that $p>n$ and
  \begin{equation} \label{15.1}
	p\ge n(\lambda-1)
  \end{equation}

  as well as
  \begin{equation} \label{15.01}
	r>2\lambda
	\qquad \mbox{if } n=2
  \end{equation}
  and
  \begin{equation} \label{15.02}
	\frac{np\lambda}{n+p-2} \le r < \frac{np}{n-2}
	\qquad \mbox{if } n\ge 3.
  \end{equation}
  Then there exist $b_1=b_1(p,r,a,h,f)>0, b_2=b_2(p,r,a,h,f)>0$, $\kappa_1=\kappa_1(p,f)>1$ and $\kappa_2=\kappa_2(p,h,f)>1$
  as well as $\Gamma_{10}=\Gamma_{10}(p,r,a,h,f)>0$
  and $\Gamma_{11}=\Gamma_{11}(p,r,a,h,f)>0$ such that whenever ((init of the paper)) and ((uut of the paper)) hold with some $T\in (0,T_{max}]$,
  the function defined by
  \begin{equation} \label{F}
	{\mathcal{F}}(t)
	:= \int_\Omega |\nabla v|^p
	+ b_1 \cdot \bigg\{ \int_\Omega |\nabla u|^r \bigg\}^\frac{p}{r}
	+ b_2 {\mathcal{F}}_1^\frac{p}{2}(t)

	\qquad t\in [0,T_{max}),
  \end{equation}
  with ${\mathcal{F}}_1$ taken from ((F1 of the paper)) satisfies
  \begin{equation} \label{15.2}
	{\mathcal{F}}'(t) + \Gamma_{10} {\mathcal{F}}(t)
	+ \Big\{ \Gamma_{10} - \Gamma_{11} {\mathcal{F}}^{\kappa_1}(t) \Big\} \cdot \int_\Omega |\nabla v|^{p-2} |D^2 v|^2
	\le \Gamma_{11} {\mathcal{F}}^{\kappa_2}(t)
	\qquad \mbox{for all } t\in (0,T).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq.hole_separation_id of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] For every $E \subseteq E_d({\scaleobj{1}{\square}}_m)$, we have 		
		\begin{align}
			V_m(F,j) = \sum_{\ell=0}^j \sum_{\substack{|G|= \ell \\ G\subseteq E \setminus F}} V_m(F \cup G,j-\ell \vert E),
		\end{align}
		thus it satisfies
		\begin{align}
			\vert V_m(F,j) \vert^2 \leqslant (j+1)\sum_{\ell=0}^j \vert E \vert^\ell \sum_{\substack{|G|= \ell \\ G\subseteq E \setminus F}} \vert V_m(F \cup G,j-\ell \vert E) \vert^2.
		\end{align}

