body:
[Theorem 34 (\cite{Hirano-1997}, Theorem 1) of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Let functions $f$, $h$, and $W$ satisfy the following conditions:

\begin{enumerate}
\item[(i)] $f$ and $h$ are continuous on $[0,\infty)$.

\item[(ii)] $W$ is continuous on $\mathbb{R}$ and non-negative.

\item[(iii)] There exist positive numbers $a$, $\beta$, $\varepsilon$, $\eta$ such that
\begin{equation*}
  \sup_{x>0} x^{-a}|f(x)| < \infty,
\qquad
\sup_{x>0} x^{\beta}|h(x)| < \infty,
\end{equation*}

and
\begin{equation*}

    \limsup_{x\to\infty} W(x)e^{-\varepsilon x} < \infty,
\qquad
\liminf_{x\to\infty} W(x)e^{-\eta x} > 0,
\end{equation*}
with
\begin{equation}
    \beta\eta > a > 0.
\end{equation}
\end{enumerate}

If conditions (a), (b), and (c) are satisfied, then
\begin{equation}

    \EE\!\left[
f\!\left(e^{S_n}\right)
\,h\!\left(\sum_{i=1}^{n} W(S_i)\right)
\right]
\sim c\,n^{-3/2},
\qquad n\to\infty,
\end{equation}
for some constant $c$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] There exist $C_0,C_1,C_2\ge 1$ depending on $\Lambda$ such that, for any compactly supported $g:\ZZ^d\to\RR^{d}$ and any $1\le i,j,k\le d$, if we define $F_1(A)\coloneqq\int \nabla \phi_i \cdot g$ and $F_2(A)\coloneqq\int \nabla \sigma_{ijk} \cdot g$, then for any $\theta\in(0,\frac12)$,
\begin{equation}
\expecb{|(F_1,F_2)|^{2p}}^{\frac1p}\lesssim_{ \Lambda }  (p\gamma\Gamma)^{C_0} \expecb{\Big(A (\nabla\phi_i +e_i)\cdot (\nabla\phi_i +e_i)\Big)^{p(1+\theta)}}^{\frac{1}{p(1+\theta)}} \|g\|^2_{L^2(\Z^d)},
\end{equation}
provided $\gamma\theta\ge C_1 p$ and $p\ge C_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 63 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] The  $\mathbb{R}$-valued process $L^z=(L_t^{z}: t \in [0,T])$ defined by the formula
   \begin{equation}
     L_t^{z}= \duality{\bX(t)}{z}{}{} - \duality{\bX(0)}{z}{}{} - \int_0^t \duality{\bF(\bX(s))}{z}{}{}\,\d s
   \end{equation}
is a continuous  local martingale on  $(\bZ_T,\mathbb{D},\mathbb{P}_T)$ and 
   \begin{equation}
       \lvert L_t^{z} \rvert^2 - \int_0^t \sum_{k=1}^\infty \dualitybig{\newG^{k}_0(s,\bX(s))}{z}{\nU}{\nU^\prime}{2}\, \d s \in \mathcal{M}_{\loc}^{\rc}(\mathbb{D},\mathbb{P}_T).
   \end{equation}

