[Prop weighted_L2 of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $\alpha \geqslant 0$ and $N \in \mathbb{N}$, then for all integers $h,k$ satisfying 
		\begin{align}
			h  \geqslant  \frac{(\alpha+1)(2+\varepsilon_{Me})}{\varepsilon_{Me}}, \qquad k \geqslant h+2,
		\end{align}
		there exists a finite positive constant $C = C(\mathfrak{p}, d, N, h, k)$, such that every ${{\scaleobj{1}{\square}}_m \in \mathcal{G}^{(N)}_k}$ is $N$-$\mathsf{stable}$ for the statement: for $(v_\#, \mathbf{w}_\#)$ solving (equation eq.PoissonCluster of the paper) and $\mathbf{w}_\#$ an anti-symmetric vector field  supported on $\overrightarrow{E_d^{\mathbf{a}^\#}}({\scaleobj{1}{\square}}_m)$, then the following weighted estimate holds
		\begin{multline}
			\sum_{\substack{{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}}_m)}} |{\scaleobj{1}{\square}}|^{\alpha}\sum_{e\in \mathcal{E}\left(\mathscr{C}_{**}^\#(\mathsf{r}{\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}_m)\right)} |\nabla v_\#(e)|^2\\
			\leqslant  C\sum_{\substack{{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h+1}({\scaleobj{1}{\square}}_m)}}|{\scaleobj{1}{\square}}|\sum_{e\in \mathcal{E}\left(\mathscr{C}_{**}^\#(\mathsf{r}{\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}_m)\right)} |\mathbf{w}_\#(e)|^2.
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 39 (Hölder Regularity of the Transitioned Source) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumptions \ref{ass:coefficients} and \ref{ass:smoothing} hold, and let $\varphi \in \mathcal{B}_m(H)$. For any $0 \le t < s \le T$ and any Hölder exponent $\beta \in (0, 1)$, the Fréchet gradient of the mapping $x \mapsto P_{t,s}[\varphi](x)$ is locally equi-Hölder continuous. Specifically, there exists a constant $C_3 > 0$ such that for all $x, y \in H$:
\begin{equation}

    \|\nabla P_{t,s}[\varphi](x) - \nabla P_{t,s}[\varphi](y)\|_H \le C_3 (s-t)^{-\gamma(1+\beta)} \Big(1 + \sup_{z \in [x,y]} \|z\|_H^m\Big) \|\varphi\|_{\mathcal{B}_m} \|x - y\|_H^\beta.
\end{equation}

