body:
[Corollary 89 (Trace-energy approximation under a compact covariance envelope) of arXiv:2608.04993, '2608.04993'] For every $q\ge2$ and $0<\eps\le T$,
\begin{equation}
 \sup_{P\in\Mmax}
 \left\|\sup_{t\le T}
   \|\mathsf E_t^\eps-Q_t\|_{\mathcal S_1}
 \right\|_{L^q(P)}
 \le C_\Gamma q\,\omega_\Gamma(\eps).
\end{equation}
In particular, $\mathsf E^\eps\to Q$ uniformly in time and in upper
probability for the trace norm.

[Corollary fix of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Fix speed $U_0 = 2x -1$. The expected size of the convoy in the TASEP speed process, conditioned on the initial speed $U_0$, satisfies
    \begin{equation}
        \lim_{n \to \infty}\frac{\mathbb{E}_x\left[\# \mathcal{C}_0^n\right]}{\sqrt{n}} = \sqrt{\frac{4x\left(1-x\right)}{\pi}}.
    \end{equation}
    In particular, the unconditional expectation is given by
    \begin{equation}
        \lim_{n \to \infty}\frac{\mathbb{E}\left[\# \mathcal{C}_0^n\right]}{\sqrt{n}} = \frac{\sqrt{\pi}}{4}.
    \end{equation}

[Lemma lm:boundssumrka of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] For $k\in \ensuremath{\mathds N}$, with $M \gg 1$,  $a >  0$, $1 \le \ell \ll m $ all  fixed; write $r_{k}(a) = k(k-1){(k+M)}^{-2}(k^{-a} - {(k+1)}^{-a})$.
\begin{enumerate}
\item~ When $0 < a < 1$ we have
\begin{equation}

\begin{split}
 &  \frac{a}{(M-1)^{a}} \int_{\frac{\ell}{\ell + M - 1 } }^{\frac{m+1 }{M + m  } } u^{1-a}(1-u)^{a-1}du  + O(\tfrac{1}{M^{2}})  \le  \sum_{k=\ell}^{m} r_{k}(a) \\
 & \le \frac{a}{M^{a}} \int_{\frac{\ell}{\ell + M } }^{\frac{m+1 }{M + m + 1 } } u^{1-a}(1-u)^{a-1}du  + O(\tfrac{1}{M^{2}} )
\end{split}
\end{equation}
\item   When $a = 1$ we have
\begin{displaymath}
\begin{split}
& \frac{m-\ell + 1}{(M+\ell - 1)(M+m) } + O\left( \frac{ \log M}{M^{2}} \right) \le    \sum_{k=\ell}^{m} r_{k}(a) \\
&  \le \frac{m-\ell + 1}{(M+\ell)(M+m+1) } +  O\left( \frac{ \log M}{M^{2}} \right)
\end{split}
\end{displaymath}
\item  When $1 < a < 2$ the same  bounds as  in~(equation eq:boundsrka of the paper) for Case~(item:15 of the paper)  hold.
\item   When $a = 2$
\begin{displaymath}
   \sum_{k=\ell}^{m} r_{k}(a) =     2M^{-2} \log M  +  O(M^{-2})
\end{displaymath}
\item~  When $2 < a $
\begin{equation}

\begin{split}
& \frac{a}{a-2}\frac{\ell^{2-a} }{(\ell + M - 1)^{2} } - \frac{3a}{a-1 }\frac{\ell^{1-a} }{(\ell + M - 1)^{2} } +  \frac{2\ell^{-a} }{(\ell + M-1)^{2}} \\
& + O(m^{1-a}(m + M)^{-2}) + O(M^{-3}) \le  \sum_{k=\ell}^{m}r_{k}(a) \\
& \le \frac{a}{a - 2}\frac{ \ell^{2-a}}{ (\ell + M)^{2} }  -  \frac{a}{a-1}\frac{\ell^{1-a}}{(\ell + M)^{2} }   + O(m^{2-a}(m+ 1 + M)^{-2})   + O(M^{-a})
\end{split}
\end{equation}
\end{enumerate}

