[Theorem NPOC of arXiv:2412.01070, 'A note on Lévy-driven McKean-Vlasov SDEs under monotonicity'] Assume that $\beta\in (1,2]$, that Assumptions $({\bf B}_0)$-$({\bf B}_{3})$ hold  with ${\beta}$ involved in Assumption $({\bf B}_1)$ replaced by some $p\in[1,{\beta})$, and suppose further $X^i_0\in L^\beta(\Omega^1\to\mathbb R^d,\mathscr F^1_0,\mathbb{P}^1)$ for any $1\le i\le n$.
Then, for any fixed $T>0$, there exists a constant $\bar C_T>0$ such that
\begin{equation*}
 \mathbb{E}{\mathbb W}_p^p(\bar{\mu}^n_t,\mu_t)\le \bar C_T\phi_{p,\beta,d}(n),\quad t\in[0,T],
\end{equation*}
where $\phi_{p,\beta}(n,d)$ was defined as in (equation EE* of the paper). Furthermore,
 for fixed $T>0$
and
any  $0\le q_1<q_2<1,$
there exists a constant $\hat C_T>0$ such that
\begin{equation}
\begin{split}
\mathbb{E}\Big(\sup_{t\in[0,T]}|\bar{X}^{i,n}_t-X_t^i|^p\Big)\le \frac{q_2}{q_2-q_1}\big(\hat C_T
\phi_{p,\beta,d}(n)\big)^{q_1}.
\end{split}
\end{equation}

[Proposition prop:boundary-smoothing of arXiv:2607.03639, '\vspace{-0.6in}An AI-Assisted Solution to the Signed BAR Conjecture: Uniqueness in the Har'] For every $i\in J$ and every $x\in F_i$,
\begin{equation}
 D_i g_\varepsilon(x)\longrightarrow0
 \qquad\text{as }\varepsilon\downarrow0.
\end{equation}
This convergence is pointwise in $x$.  There is a constant $C_{\rho,R}<\infty$, independent of $x$ and $\varepsilon$, such that
\begin{equation}
 \left\lvert D_i g_\varepsilon(x)\right\rvert
 \le C_{\rho,R}\operatorname{Lip}(g),
 \qquad x\in F_i,
 \quad 0<\varepsilon<1.
\end{equation}
Consequently, for every finite signed measure $\eta_i$ on $F_i$ and every bounded Borel function $a$,
\begin{equation}
 \int_{F_i}a(x)D_i g_\varepsilon(x)\,d\eta_i(x)
 \longrightarrow0
\end{equation}
whenever $a$ is fixed.

