[Lemma majd of arXiv:2412.04013, 'Rate estimates for total variation distance with applications\thanks{The author gratefully'] Let the assumptions of Proposition (malliavin-estimate of the paper) be in vigour.
Let $\phi_{i}$ denote the characteristic function of $F_{i}$ for $i\in I$. Then for each $l\geq 1$ there are constants $H_{l}$
such that for all $i\in I$,
\begin{equation}
|\phi_{i}(u)|\leq H_{l}(1+|u|)^{-l},\ u\in\mathbb{R}^{d}.
\end{equation}

[Definition 3 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] \begin{itemize}[label=(\roman*)]
        \item[(1)] $\Phi$ is said to satisfy the lower bound condition \eqref{eq:LBC_P} at $z\in\X$ if 
        \begin{equation}

            \forall\, r>0,\quad\inf_{x\in \X}\liminf_{t\to \infty }P_t(x,B(z,r))>0.\tag{\(\mathcal{C}_1\)}
        \end{equation}

        \item[(2)] $\Phi$ is said to satisfy the lower bound condition \eqref{eq:LBC_Q} at $z\in\X$ if
        \begin{equation*}

            \forall\, r>0,\quad\inf_{x\in \X}\limsup_{t\to \infty }Q_t(x,B(z,r))>0.
            \tag{\(\mathcal{C}_2\)}
        \end{equation*}
    \end{itemize}

[Lemma 4 of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] If $u\neq0$, then every $\zeta\in\spec(H_{\beta-iu})$ satisfies
\begin{equation}
 \Re\zeta>\lambda(\beta).

\end{equation}
In particular, for every $0<\delta < R <\infty$,
\begin{equation}

 \inf_{\delta\leq|u|\leq R}
 \inf_{\zeta\in\spec(H_{\beta-iu})}\Re\zeta>\lambda (\beta).
\end{equation}
Consequently, for every $0<\delta<R<\infty$, there exist $C,\eta>0$ such
that
\begin{equation}
 \sup_{\delta\leq|u|\leq R}
 \norm{\mathrm e^{-tH_{\beta-iu}}}_{2 \to 2}
 \leq C \mathrm e^{-(\lambda(\beta)+\eta)t},
 \qquad t\geq1.

\end{equation}

[Theorem thm:Q-high-epi of arXiv:2508.12464, 'On the Fitness Landscape in the $\NK$ Model'] Assume $\alpha_*<\alpha\le 1$ and recall that $\beta_c = \sqrt{2\ln 2}$. For any $\beta\leq \beta_c$,
	\begin{align}
		\lim_{N\to\infty}\mathbb{E} \bigl\langle I(Q_{1,2}=0)\bigr\rangle_\beta=1,
	\end{align}
	and for any $\beta>\beta_c$,
	\begin{align}
		\lim_{N\to\infty}\mathbb{E}\bigl\langle I(Q_{1,2}=0)\bigr\rangle_\beta&= \frac{\beta_c}{\beta},\\
		\limsup_{N\to\infty}\mathbb{E}\bigl\langle I(Q_{1,2}=1)\bigr\rangle_{\beta}&=1-\frac{\beta_c}{\beta}.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

