[Lemma 19 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\gamma \in \mathcal{P}_\mathcal{W}$, $\psi$ be the corresponding generator, $\varphi$ be its pseudo-inverse, $A \in \mathcal{A}$ and $x \in (0,1)$. Furthermore, let $H_x$ be defined according to eq. \eqref{eq:function_H_x} and $\nu_{H_x}$ be its corresponding probability measure. Then the following assertions hold:
\begin{itemize}
    \item[$(i)$] If $\gamma$ is absolutely continuous, then $\nu_{H_x}$ is absolutely continuous.
    \item[$(ii)$] If $\gamma$ is discrete, then $\nu_{H_x}$ is discrete.
    \item[$(iii)$] If $\gamma$ is singular, then $\nu_{H_x}$ is singular.
    \end{itemize}

[Theorem energy_estimate_LDP of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix a sequence $\{H_j:j\geq 1\}$ of functions in $C^{0,1}(\Omega_T)$ with compact support in $[0,T]\times(0,1)$ and a sequence $\{\eta^N:N\geq 1\}$ of configurations. There exists a finite constant $C=C(R^{\pm},l)$ such that 
    \begin{equation}
    \limsup_{\varepsilon\to0}\limsup_{N\to\infty}\frac{1}{N}\log\mathbb{P}_{\eta^N}^N\Big(\max_{1\leq j\leq k}Q_{H_j}(\rho^{N,\varepsilon})\geq m\Big)\leq -m +C(T+1),
    \end{equation}
    for all $k,m\geq1.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:control-v of arXiv:2604.20094, 'Persistence and local extinction for superprocesses in random environments'] Let $T>0$, $\gamma\in (0, 1)$. Suppose $f\in C_c^+  ({\mathbb R}^d) $
  	and $v$ is the unique solution of (equation eq:PAM of the paper). Then for any $p\in{\mathbb N}$,
	 there exists constant $C= C(d, p,\gamma, T, \|{\mathcal C}\|_\infty, \|f\|_\infty)>0$ so that
	 for any $t\in [0,T]$ and \(x, \bar x\in {\mathbb R}^d\),
  	\begin{equation}
		\begin{aligned}
			{\mathbf E} \left[ \big|\left[v(t,x)-P_tf(x)\right]-\left[v(t,\bar x)-P_tf(\bar{x})\right]\big|^{2p} \right] \leqslant C |x-\bar{x}|^{2\gamma p}.
		\end{aligned}
  	\end{equation}
  	Consequently, for any $\rho>0$,
  	\begin{equation}
  		{\mathbf E}  \left[ \left( \sup_{x\in {\mathbb R}^d} |v(t,x) |
		\phi_\rho(x)
		\right)^{2p}\right] \leqslant C(d, p,\rho,T, \|{\mathcal C}\|_\infty, \|f\|_\infty) <\infty  \quad  \hbox{for }  t\in [0,T],
  	\end{equation}
  where $\phi_\rho$ is defined by (equation def-phi of the paper).

