[Lemma 14 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Suppose that $\sO\seq \R^d$ is an open and bounded set. Let $q\in[2,\infty)$. Let $v$, $\phi$, $\Phi_j$, $\psi_n \colon [0,T]\times\Omega \to L^q(\sO)$ be progressively measurable for $j\in\{1, \ldots, d\}$ and $n\geq 1$, and suppose that
 \begin{itemize}
  \item $v_0 \in L^0_{\F_0}(\Omega; L^q(\sO))$,
  \item $v\in L^2(0, T; H^{1,q}(\sO))\cap C([0,T];L^q(\sO))$ a.s.,
  \item $\phi \in L^1(0,T;L^q(\sO))$ a.s.,
  \item $\Phi \in L^2(0,T; L^q(\sO;\R^d))$ a.s.,
  \item $(\psi_n)_{n\geq 1}\in L^2(0,T;L^q(\sO; \ell^2))$ a.s.,
 \end{itemize}
and a.s.\ for all $t\in[0,T]$, the following identity holds true for all $\varphi\in H^1(\sO)$
\begin{equation}
(v(t), \varphi)_{L^2} = (v_0, \varphi)_{L^2}
+ \int_0^t (\phi(s), \varphi)_{L^2} \ds - \int_0^t (\Phi(s), \grad \varphi )_{L^2} \ds  + \sum_{n \geq 1} \int_0^t (\psi_n(s), \varphi)_{L^2} \dWsn.
\end{equation}
Then, a.s.\ for all $t \in [0,T]$,
\begin{align*}
\|v(t)\|_{L^q(\sO)}^q
&= \|v_0\|_{L^q(\sO)}^q
+ q \int_0^t \int_{\sO} |v(s)|^{q-2}
\left[v(s)\phi(s) - (q-1)\nabla v(s)\cdot \Phi(s)\right] \dx\ds \\
&\phantom{= } + q \sum_{n \geq 1} \int_0^t \int_{\sO}
|v(s)|^{q-2} v(s)\psi_n(s) \dx \dWsn + \frac{q(q-1)}{2} \int_0^t \int_{\sO}
|v(s)|^{q-2} \|\psi(s)\|_{\ell^2}^2 \dx\ds.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2604.04823, '2604.04823'] Let~$U$ be a potential that satisfies the Assumptions~\ref{a:criticalpts}--\ref{a:massRatioBound}.
    Then, there exist~$\eta, c_1,  c_2, C_\mathrm{BV}, c_d > 0$ such that the following holds. For any~$\bar \nu\in\paren*{0, 1/\bar\theta}$ and any given temperatures~$\underline \epsilon , \bar \epsilon$ such that~$ \underline \theta \leq \underline\epsilon < \bar \epsilon \leq \bar \theta$, choose
    \begin{equation}
        N = \ceil*{\frac{1}{\bar\nu \underline \epsilon}}\,,\quad \epsilon_0=\bar \epsilon\,,\quad \epsilon_N = \underline \epsilon\,,
    \end{equation}
    and let~$\paren*{1/\epsilon_k}_{k=0}^N$ be linearly spaced. 
    For each~$k\in\set{0, \ldots, N}$, set
    \begin{equation}
        h_k = \min\set*{\eta \epsilon_k^2, 1}\,,   
    \end{equation}
    and define~$T_{h_k, \epsilon_k}$ as the lazy Metropolis random walk with step size~$h_k$ and the stationary density~$\pi_{\epsilon_k}$. 
    If we define~$P_\pt$ to be the parallel tempering chain as in Definition~\ref{d:pt-def} with the sequence~$(T_{h_k, \epsilon_k}, \pi_{\epsilon_k})_{k=0}^N$, then 
    \begin{equation}
        \gap(P_\pt) \geq D \min\set*{c_2,  c_1 \underline\epsilon^7 } \underline\epsilon^4 \,,
    \end{equation}
    where
    \begin{equation}
        D(d,\bar\nu,\epsilon_0) \defeq c_d\bar\nu^4 \exp\paren*{-C_\mathrm{BV} C_m^2 - 2\paren*{ \bar\nu +\frac{1}{\epsilon_0}} \norm{U}_{L^\infty} } h_0^2\,.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

