[Lemma lem:d4-difference-tail of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] There are constants $A_0,c,C\in(0,\infty)$ such that, for all
			$t\geq2$ and all $x\in\mathbb{Z}^4$,
			\begin{equation}
				\mathbb{E}\left[
				\exp\left\{
				c\bigl(u_t(x)-V_t(x)-A_0\log(t+2)\bigr)_+
				\right\}
				-1
				\right]
				\leq C(t+2)^{-2}\, .
			\end{equation}

[Lemma 20 (Conditional BMO product estimate) of arXiv:2608.06393, 'Intrinsic Tangential Hadamard Differentiability of Rough-BSDE Solution Maps'] Let \(\mathbb Q\) be one of the preceding Girsanov measures, and let
\(G^1,G^2,G^3\) be predictable integrands such that
\[
 \max_{1\leq j\leq3}
 \|G^j\mathbin{\cdot}W^{\mathbb Q}\|_{
      \mathrm{BMO}_2(\mathbb Q;I)}\leq B.
\]
For every \(s\geq1\), the process
\begin{align*}
 \Theta_t:={}&1+|G_t^1|^2+|G_t^2|^2
 +(1+|G_t^1|)|G_t^2|\\
 &+(1+|G_t^1|+|G_t^2|)|G_t^3|
\end{align*}
satisfies
\begin{equation}
 \|\Theta\|_{\mathfrak R_s(\mathbb Q;I)}
 \leq C_{s,B,|I|}.

\end{equation}

[Lm lacomp of arXiv:2607.12795, 'Semi-open boundary for random walking shocks'] \begin{multline}
  \Eb^{\un\varrho,\underline{m}}(L^\text{aux}\varphi)(\un\omega,\,\un\zeta)\\
  \begin{aligned}
   =\Eb^{\un\varrho,\underline{m}}\bigl\{&p(\omega_0,\,\zeta_1-1)\cdot\frac{\hat\mu^{\varrho_1,m_1}(\omega_1-1)}{\hat\mu^{\varrho_1,m_1}(\omega_1)}-p(\omega_0,\,\omega_1)+q(\zeta_0,\,\omega_1+1)\cdot\frac{\hat\mu^{\varrho_1,m_1}(\omega_1+1)}{\hat\mu^{\varrho_1,m_1}(\omega_1)}-q(\zeta_0,\,\zeta_1)\\
   +&p(\omega_K+1,\,\zeta_{K+1})\cdot\frac{\hat\mu^{\varrho_K,m_K}(\omega_K+1)}{\hat\mu^{\varrho_K,m_K}(\omega_K)}-p(\zeta_K,\,\zeta_{K+1})\\
   +&q(\zeta_K-1,\,\omega_{K+1})\cdot\frac{\hat\mu^{\varrho_K,m_K}(\omega_K-1)}{\hat\mu^{\varrho_K,m_K}(\omega_K)}-q(\omega_K,\,\omega_{K+1})\bigr\}\cdot\varphi\\
   +\Eb^{\un\varrho,\underline{m}^{1-}}\bigl\{\bigl[&p(\omega_0,\,\omega_1-1)-p(\omega_0,\,\zeta_1)\bigr]\cdot\frac{\hat\mu^{\varrho_1,m_1}(\omega_1-1)}{\hat\mu^{\varrho_1,m_1-1}(\omega_1)}\\
   +\bigl[&q(\zeta_0,\,\zeta_1+1)-q(\zeta_0,\,\omega_1)\bigr]\cdot\frac{\hat\mu^{\varrho_1,m_1}(\omega_1)}{\hat\mu^{\varrho_1,m_1-1}(\omega_1)}\bigr\}\cdot\varphi\\
   +\Eb^{\un\varrho,\underline{m}^{K-}}\bigl\{\bigl[&p(\zeta_K+1,\,\zeta_{K+1})-p(\omega_K,\,\zeta_{K+1})\bigr]\cdot\frac{\hat\mu^{\varrho_K,m_K}(\omega_K)}{\hat\mu^{\varrho_K,m_K-1}(\omega_K)}\\
   +\bigl[&q(\omega_K-1,\,\omega_{K+1})-q(\zeta_K,\,\omega_{K+1})\bigr]\cdot\frac{\hat\mu^{\varrho_K,m_K}(\omega_K-1)}{\hat\mu^{\varrho_K,m_K-1}(\omega_K)}\bigr\}\cdot\varphi.
  \end{aligned}
 \end{multline}
 Here the last two+two lines are understood to be zero if \(m_1=0\) or \(m_K=0\), respectively, and each line under the expectations is meant to be zero if any of the \(\omega_i\) or \(\zeta_i\) variables is out of the range \(I\).

[Proposition 30 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $X$ have density $f$ with respect to $\pi_{T}$ and $H(T_{1-a} (X) | \pi_{(1-a)T} ) < \infty$ for some $a < 1.$ Then 
    \begin{displaymath}
        \E_{\pi_{aT}} \Psi \big( P_{T(1-a)} f , DP_{T(1-a)} f \big) < \infty.
    \end{displaymath}
    Moreover, if $H( X | \pi_{T} ) < \infty,$ then 
    \begin{displaymath}
        \E_{\pi_{t}} \Psi \big( P_{T (1-a) } f , DP_{T (1-a) } f \big) < \infty
    \end{displaymath}
    for all $ a < 1.$

