[Theorem 84 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Suppose   that $(\sfd_{0},q,p)$ are properly tight.
Then
for   any $\rho\in(0,\infty)$,   $\cF_{\tau}$-measurable $\bR^{d}$-valued $y$,
and Borel $f\geq0$ on $\{\tau<\infty\}$ we have
\begin{equation}

E_{\cF_{\tau}}\int_{0}^{\theta_{\tau}\tau'_{\rho}(y)  }f( t, x_{\tau+t} )\,dt\leq
\hat N   \sup_{C\in\bC_{1}}
 \|  
f\| _{L_{(q,p)}(C) } , 
\end{equation}
where $\hat N$ depends only on 
$d,\delta ,\rho_{b}$, and $\rho $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm conv-fields of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D$ be a Jordan domain. For every continuous function $f:D\to\mathbb R$ with compact support in $D$, and any $k\geq1$, 
\begin{enumerate}
    \item[(i)] $\mathbb E_{\delta}^+[(\tau_\delta, f)^k]\to\mathcal{C}^{k}\ 2^{k/2}\ \mathbb E[(\field{\cos(\frac{1}{\sqrt{2}}\phi)}, f)^k]$,
    \item[(ii)] $\mathbb E_{\delta}^\varnothing[(\tau_\delta^\dagger, f)^k]\to\mathcal{C}^{k}\ 2^{k/2}\ \mathbb E[(\field{\sin(\frac{1}{\sqrt{2}}\phi)}, f)^k]$,
\end{enumerate}
as $\delta\to0$, where $\mathcal{C}$ is an explicit (lattice-dependent) constant. In particular, the fields converge in distribution with respect to the topology of the Sobolev space $H^{s}_{loc}(D)$ for any $s<-1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2607.00587, '(Non-)Hyperuniformity of Second Order Statistics\\ of Point Processes\thanks{The research '] Let $\PP$ be a stationary point process with correlation functions,
and assume that $\rho^{(2)}$ and $\rho^{(3)}$ are bounded
and that $\chi^{(4)}$ of \req{chi4} satisfies  
\begin{align}

   \int_{\R^d}\left|\chi^{(4)}(x_1,x_2,x_3,x_4+x_3)\right|\dx_3 \in L^\infty((\R^{d})^3)
\end{align}
as a function of $(x_1,x_2,x_4)\in(\R^d)^3$.
Further, let $V_\Lambda$ be defined 
by \req{G} for some even function $v\in L^1(\R^d)\cap L^2(\R^d)$. Then
\be{EVlim}
   \lim_{\ell\to\infty} \frac{1}{|\Lambda|}\,\E\bigl[V_\Lambda\bigr]
   \,=\, \int_{\R^d} v(x)\rho_2(x)\dx
\ee
and
\be{Hank17b}
\begin{aligned}
   \lim_{\ell\to\infty}
   \frac{1}{|\Lambda|}\,\Var\bigl[\Testfct_\Lambda\bigr]
   &\,=\, \int_{\R^d} \testfct(x_1) 
             \int_{\R^d} 
                \testfct(x_2)\int_{\R^d}\chi^{(4)}(x_1,0,x_3,x_3+x_2)\dx_3\dx_2\dx_1
                \\[1ex]
   &\phantom{\,=\,}
          \ +\, 4 \int_{\R^d} \testfct(x_1) 
                     \int_{\R^d} \testfct(x_2)\rho^{(3)}(0,x_1,x_2)\dx_2\dx_1
          \ +\, 2\int_{\R^d} \testfct^2(x)\rho_2(x)\dx\,.
\end{aligned}
\ee

[Lemma 19 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $2< p<\infty$  and $\la>0$. Assume that $|F|\in L^{p-1}_{\loc}(\Omega_T)$ and that $u\in  L^{p-1}_{\loc}(0,T;W^{1,p-1}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$.
Moreover, assume that $2Q_r\Subset \Om_T$ and that there exist $\eta\in C_0^1(2Q_r)$ and a constant $c>0$ such that
\begin{equation}
    \| \eta \|_{L^\infty(2Q_r)}+ r^{-1}\| \na \eta \|_{L^\infty(2Q_r)}+ r^{-2}\| \eta_t \|_{L^\infty(2Q_r)}\le c.
\end{equation}
Then there exists a constant $c=c(n,p,L)$ such that
	\begin{equation}
        \begin{split}
            &\fiint_{Q}\frac{|u\eta- (u\eta)_Q|}{\rho}\,dz\le c\fiint_Q \biggl( \frac{|u|}{r}+|\na u| \biggr) 1_{2Q_r}\,dz\\
            &\qquad + c\Bigl( \frac{\rho}{r}+1 \Bigr)\la^{2-p} \fiint_Q \biggl( \frac{|u|}{r}+|\na u|+|F|+1\biggr)^{p-1} 1_{2Q_r} \,dz,
        \end{split}
    \end{equation}
    for every parabolic cylinder $Q=\Qla \subset\mathbb{R}^{n+1}$.

