body:
[Theorem thm:linear-least-squares of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ ( \Omega, \mathcal F, {\mathbb P} ) $ be a probability space, let
$ \kappa \in (0,\infty) $,
$ m, d, M \in {\mathbb N} $,
$ \vartheta \in {\mathbb R}^d $,
let $ A \in {\mathbb R}^{ m \times d } $ have no zero columns,
let $ K \subseteq {\mathbb R}^m $ be compact,
let $ ( Y_{ n, r } )_{ (n,r) \in {\mathbb N}^2 } $ be $ K $-valued i.i.d.\ random variables with a bounded Lebesgue density,
let $ L \colon {\mathbb R}^d \times {\mathbb R}^m \to {\mathbb R} $ satisfy for all $\theta\in{\mathbb R}^d$, $y\in{\mathbb R}^m$ that
\bas{

\textcolor{magenta}{
  L( \theta, y )
  = | A \theta - y |^2
}
}
and
let $ F \colon {\mathbb R}^d \to {\mathbb R} $
satisfy for all $ \theta \in {\mathbb R}^d $ that
$
  F(\theta)
=
  {\mathbb E}[L(\theta,Y_{1,1})]
  - \inf_{\vartheta\in{\mathbb R}^d}{\mathbb E}[L(\vartheta,Y_{1,1})]
$.

Then there exists $ \eta \in (0,\infty) $
such that for every
$ \mathfrak{C} \in (0,\infty) $ there exists
$ c \in {\mathbb R} $ such that
for all $ \beta \in [ \nicefrac{ 1 }{ 2 }, 1 ) $,
$ \varepsilon \in [0,1] $, all $ {\mathbb R}^d $-valued
stochastic processes $ ( w_n )_{ n \in {\mathbb N}_0 } $ and $ ( \theta_n )_{ n \in {\mathbb N}_0 } $,
and every $ ( 0, \mathfrak{C} ] $-valued decreasing $ ( \gamma_n )_{ n \in {\mathbb N} } $
with the property that for every
$ n \in {\mathbb N} $,
$ j \in {\mathbb N} \cap [ 1, n ] $,
$ i \in \{ 1, 2, \dots, d \} $
it holds that

\begin{equation}

\begin{gathered}

\textcolor{magenta}{
  w_0 = 0
}
  ,
  \qquad

\textcolor{magenta}{
  w_n^{(i)}
  = \beta w_{n-1}^{(i)}+(1-\beta)
  \bigl[
  \textstyle
    M^{ - 1 } \sum_{r=1}^M
    ( \nabla_{ \theta_i } L )( \theta_{ n - 1 }, Y_{ n, r } )

  \bigr]^2
}
  ,
\\
\textcolor{magenta}{
  \theta_0 = \vartheta
} ,
\qquad
\textcolor{magenta}{
  \theta_n^{(i)}

  =
  \theta_{n-1}^{(i)}
  -
  \gamma_n
  \bigl[
    \varepsilon + ( 1 - \beta^n )^{ - 1 / 2 } ( w_n^{ (i) } )^{ 1 / 2 }
  \bigr]^{ - 1 }
  \textstyle

    M^{ - 1 }
    \sum_{r=1}^M
    ( \nabla_{ \theta_i } L )( \theta_{ n - 1 }, Y_{ n, r } )
}

\end{gathered}
\end{equation}
and
\textcolor{magenta}{$
  \gamma_j
  \le  \mathfrak{C} \exp( \frac\eta2 \sum_{ k = j+1 }^{ n } \gamma_k )
   \gamma_n
$}
we have for every $ n \in{\mathbb N} $ that
\bas{
\textcolor{magenta}{
  {\mathbb E}\bigl[
    F(\theta_n)
    \1_{ \cap_{ j = 0 }^{ n - 1 } \{|\theta_j|\le\kappa\}}
  \bigr]
  \le
  \exp\bigl(
  \textstyle
    - \eta \sum_{ k = 2 }^n \gamma_k
  \bigr)
  \,

    \bigl(
      \gamma_1
      ( d \| A^\mathsf{T} A \| )^{ 1 / 2 }
      +
      | F( \theta_0 ) |^{ 1 / 2 }
    \bigr)^2

  + c \gamma_n
  + c (1-\beta)^2
}
  .
} (Proof in the paper; no proof environment follows the statement in the TeX.)

