[Lemma lem:sampling of arXiv:2608.09465, 'Balancing fractional Brownian motion'] Given $J\in\mathbb{Z}$ and $\mathcal I\subseteq\{(j, k)\in\mathbb{Z}\times\mathbb{Z}: j\leq J\}$ finite, there is an equispaced grid $\mathcal T_J\subset[0,1]$ with $|\mathcal T_J|\lesssim_H 2^J+1$ such that every function of the form $g(t) = \sum_{(j,k)\in\mathcal I} c_{j,k}G^H_{j,k}(t), t\in [0, 1]$ with arbitrary real coefficients $(c_{j,k})_{(j,k)\in\mathcal I}$, satisfies
\begin{align}
\|g\|_\infty\leq 2\max_{t\in\mathcal T_J}|g(t)|. 
\end{align}

[Corollary 50 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] One has
\begin{align}
 \Nrm_{x,z}(\widetilde\Omega_\alpha)
 &=\partial_z^{\length(w)-r_\alpha}
   \Nrm_{x,z}(H_{w,\lambda})\in\RV,
 \\
 \Nrm_x(\Omega_{\alpha,k})
 &=\left.\partial_z^{\length(w)-k}
   \Nrm_{x,z}(H_{w,\lambda})\right|_{z=0}\in\RV
 \qquad(0\le k\le r_\alpha).

\end{align}
Taking $\kk=\CC$, every nonzero homogeneous Lascoux layer is Lorentzian and has
$M$-convex support.

[Lem lemma:decomposition of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Let $B=\bigtimes_{x\in I} B_x$ be a cylinder event. 
Then, for any constraint set $\ensuremath{\mathcal{C}}$, it holds that $\ensuremath{\mathbb{P}}_I(B \;|\; \ensuremath{\mathcal{C}})$ equals 
\begin{align}
&\prod_{x\in M^c} \ensuremath{\mathbb{P}}_x(B_x) \sum_{y \in M} \ensuremath{\mathbb{P}}_I(Y=y \;|\; \ensuremath{\mathcal{C}}) \prod_{x\in I_{>y}\cap M} \ensuremath{\mathbbm{1}}_{0\in B_x} \\
&\quad\cdot \ensuremath{\mathbb{P}}_y(N_y \in B_y \;|\; N_y \geq 1) \ensuremath{\mathbb{P}}_{I_{<y}\cap M}( B_{I_{<y}\cap M} \;|\;\ensuremath{\mathcal{C}}^y).
\end{align}

