[Proposition 55 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For $1\le t\le c_a$, there is an exact sequence
\begin{equation}
 0\longrightarrow R_{a+t}^{\langle a\rangle}
 \longrightarrow C_{a,t}
 \longrightarrow C_{a,t-1}\longrightarrow0.
\end{equation}
Moreover, there is a natural surjection
\begin{equation}
 \cL_{a+1}\oplus\cdots\oplus\cL_n
 \twoheadrightarrow C_{a,t}.
\end{equation}
Thus every $C_{a,t}$ is globally generated, and
\begin{equation}
 c_{c_a}(C_a\otimes\cM)
 =\prod_{t=1}^{c_a}
 \bigl(c_1(R_{a+t}^{\langle a\rangle})+h_z\bigr).
\end{equation}

[Defn 4 (Rescaled prelimiting density field) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Choose a sequence of initial states $
u_N$ (so each $
u_N$ is a probability measure on $I$). Let $P^\omega_{
u_N}(r,\dr x)$ be as in \eqref{kn}, with initial state $
u_N$ and environment $\omega = (K_i)_{i=1}^\infty$ satisfying Assumption ef{a1}. Furthermore, let $\varsigma_N$ be any sequence of deterministic vectors satisfying Assumption ef{psi_n} and let $d_N$ be related to $\varsigma_N$ via \eqref{dn}. For $t\in N^{-1}\mathbb Z_{\ge 0}$ we define the 	extbf{macroscopic quenched density field}  egin{equation}\mathfrak H^N(t,\phi):= \int_I C_{N,t,N^{-1/2}(   x-   d_Nt), 
u_N} \phi(N^{-1/2}(   x-   d_Nt))P_{
u_N}^\omega(Nt,\mathrm d   x)
,\;\;\;\;\;\;\; \phi\in C_c^\infty(\mathbb R^d).\end{equation}
Here $N\ge 1$. Then define its recentered and rescaled version as $$\mathfrak F_N:= \mathscr B_N\cdot (\mathfrak H_N-\mathbb E[\mathfrak H_N]).$$

[Lemma lem:uniform of arXiv:2607.19658, 'Hitting time mixing for random $k$-cycles'] For $t \geq t^*$, conditioned on the marked set $M_t$, $\rho_t$ is uniform on $\Omega_{t}(S_t)$. In particular, $\rho_{\tau_3}|\{\tau_3= t\}$ is uniform on $\Omega_t$. Consequently, if $k$ is odd, then
    \begin{align*}
        \rho_{\tau_3}\sim U_{\mathfrak{A}_n}.
    \end{align*}
    If $k$ is even, then
\begin{align*}
    \rho_{\tau_3}\sim \mathbf{P}(\tau_3\text{ is even}) \, U_{\mathfrak{A}_n}+\mathbf{P}(\tau_3\text{ is odd}) \, U_{\mathfrak{A}_n^c}.
\end{align*}

[Prop 13 of arXiv:2607.24170, '\large\bf ON NON-MONOTONICITY OF LOGARITHMIC ENERGY\\ FOR RANDOM MATRICES'] With $a_0,a_1$ as in \eqref{EqAZero}--\eqref{EqAOne}, put
$L_3\overset{\mathrm{def}}{=}a_0^2+a_1^2$.  Then
\begin{equation}
 \liminf_{\varepsilon\downarrow0}
 \frac{\cF_{\C}(\nu_{3,\varepsilon})}
      {\log(1/\varepsilon)}
 \geq
 L_3.
\end{equation}

[Definition 13 of arXiv:2609.03736, '2609.03736'] For a finite graph $\mathfrak G$ on $X$, Schrijver's $\vartheta'$ is
\begin{equation}
 \vartheta'(\mathfrak G)=
 \max\left\{\sum_{x,y\in X}Z(x,y):
 \begin{array}{l}
 Z\in\RR^{X\times X},\\
 Z\succeq0,\quad Z(x,y)\geq0,\quad \displaystyle\sum_{x\in X}Z(x,x)=1,\\
 Z(x,y)=0\quad\text{whenever }x\sim_{\mathfrak G}y
 \end{array}\right\}.

\end{equation}

[Thm diagfluc of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Fix $a,b > 0$ and $\ell> \bar{\mathcal{L}}(a,b)$. Let $D=\ell^2-2(a+b)\ell+(a-b)^2$. 
Define the positive real numbers   
\begin{equation} 
    \mathsf{\sigma}= \frac{\sqrt{(a+b)\ell- (a-b)^2} D^{1/4}}{2\sqrt{ab}}
    \quad \text{and} \quad 
    \mathsf{c}_\pm= \bigg(1 \pm \frac{(a-b)\sqrt{D}}{(a+b)\ell -(a-b)^2} \bigg)^{1/2}. 
\end{equation}
Then, 
\begin{equation} \begin{split} 
    &{\rm Law} \left( \left\{ \frac{ \mathcal{L}( t aN +  s \frac{a(\ell-a+b)\mathsf{\sigma}}{\ell\sqrt{D}}   N^{1/2}, t bN -  s \frac{b(\ell+a-b)\mathsf{\sigma}}{\ell\sqrt{D}}  N^{1/2})- t \ell N}{\mathsf{\sigma} N^{1/2}} \right\}_{(s,t)\in {\mathbb R}\times (0,1)}
    \, \bigg| \,  \mathcal{L}(aN, bN)= \ell N \right) \\
    &\xrightarrow{\textit{f.d.d.}}  {\rm Law} \left( \{ \mathbb{B}^{\mathrm{br}}_1(t) - |\mathbb{B}^{\mathrm{br}}_2(t) - s| \}_{(s,t)\in {\mathbb R}\times (0,1)} \right)
\end{split} \end{equation}
as $N\to \infty$, where 
\begin{equation} 
    \mathbb{B}^{\mathrm{br}}_1(t)= \frac{\mathsf{c}_+ \mathbb{B}^{\mathrm{br}}_+(t)+ \mathsf{c}_- \mathbb{B}^{\mathrm{br}}_-(t)}{\sqrt{2}}  \quad\text{and}\quad 
    \mathbb{B}^{\mathrm{br}}_2(t)= \frac{\mathsf{c}_+ \mathbb{B}^{\mathrm{br}}_+(t)- \mathsf{c}_- \mathbb{B}^{\mathrm{br}}_-(t)}{\sqrt{2}} 
\end{equation}
for two independent standard Brownian bridges $\mathbb{B}^{\mathrm{br}}_+$ and $\mathbb{B}^{\mathrm{br}}_-$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prp 81 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Set $r_n=n^{\theta},\;\theta\geq 0$ and suppose that $\kappa\in (1/2,1]$ and $\alpha>1$.
Then, for any $\zeta>\alpha^{-1}$, it holds that
\begin{align*}
  d_{\BL^{\kappa}}(\mu^{(r_n)},\mu_n^{(r_n)})
  \lesssim
  \begin{dcases}
    n^{-\frac{\alpha-1}{\alpha}}(\log n)^{1+\zeta}, & \theta=0,\;\alpha\in (1,2),\\
    n^{-\frac{\alpha-1}{\alpha}+\frac{2+\alpha}{2\alpha}\theta}(\log n)^{\zeta(1-\alpha/2)}, & \theta>0,\;\alpha\in (1,2),\\
    n^{-\frac{1}{2}}(\log n)^{1+\zeta},& \theta=0,\;\alpha=2,\\
    n^{-\frac{1}{2}+\theta}(\log n)^{\frac{1}{2}}, & \theta>0,\;\alpha=2,\\
    n^{-\frac{1}{2}}(\log n)^{\frac{1}{2}}, & \theta=0,\;\alpha\in (2,\infty),\\
    n^{-\frac{1}{2}+\theta}, & \theta>0,\;\alpha\in (2,\infty),
  \end{dcases}
  \qquad\qquad
  \bbP\mathrm{-a.s.}
\end{align*}

