[Definition 1 of arXiv:2506.13913, '2506.13913'] {}{}
 A stochastic process \(\{W_t : t \geq 0\}\) defined on a probability space \((\Omega, \mathcal{F}, \mathbb{P})\) is called a \textit{standard Brownian motion} (or standard Wiener process) if it satisfies the following properties:   
\begin{enumerate}
    \item \(W_0 = 0\) almost surely.
    \item For \(0 \leq s < t\), the increment \(W_t - W_s \sim \mathcal{N}(0, t-s)\), where \(\mathcal{N}(0, t-s)\) denotes a normal distribution with mean \(0\) and variance \(t-s\).
    \item The increments \(W_{t_i} - W_{t_{i-1}}\) are independent for \(t_0 < t_1 < \cdots < t_n\).
    \item The sample paths \(t \mapsto W_t\) are continuous almost surely.
\end{enumerate}

[Lemma 7 of arXiv:2604.14752, 'Strong and weak rates of convergence in the Smoluchowski--Kramers approximation for stocha'] There exists $C\in(0,\infty)$ such that the following holds.
\begin{itemize}
\item If $1-4\lambda_n\epsilon^2<0$, then for all $t\ge 0$,
   \begin{align}
&     |f_n^{\epsilon,0,1}(t)|\le C\lambda_n^{-1/2}e^{-\frac{t}{4\epsilon^2}},~|g_n^{\epsilon,0,1}(t)|\le Ce^{-\frac{t}{4\epsilon^2}},\\
&     |f_n^{\epsilon,1,0}(t)|\le Ce^{-\frac{t}{4\epsilon^2}}.
     \end{align}
\item If $1-4\lambda_n\epsilon^2\ge 0$, then for all $t\ge 0$ one has
  \begin{align}
&	|f_n^{\epsilon,0,1}(t)|\le C\epsilon e^{-\lambda_n t},~|g_n^{\epsilon,0,1}(t)|\le Ce^{-\frac{t}{\epsilon^2}}+C\lambda_n\epsilon^2e^{-\lambda_n t},\\
&	|f_n^{\epsilon,1,0}(t)|\le Ce^{-t\lambda_n}.
  \end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Assume that $c\in C^1([0,T])$, $\kappa \in C([0,T], \R_{\geq 0})$, and that
    \begin{equation*}
        V(0) := c(0)+X(0) \geq 0.
    \end{equation*}
    Then the weak solution to \eqref{eq:pd-vol-model-general} is unique in law.

