[Prop 12 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $n^{k+1}r_n^{dk} \to \infty$.
    Let $\{\Gamma_i\}_{i=1}^m$ be as in Theorem~\ref{MainResult.06}.
    Assume that $\{C_j\}_{j=1}^s \subset \CC_{\widetilde{\CH}_{x_0}}$ is mutually disjoint.
    Then, the joint distribution of
    \begin{equation*}
        \left(\left(D_{n^{(k+1)/d}r_n^k}(T_{-x_0} \widetilde{\Phi}_{n,\Gamma_i})\right)(C_j)\right)_{i,j} = \left(\widetilde{\Phi}_{n,\Gamma_i}\left(n^{-(k+1)/d}r_n^{-k}C_j + x_0\right)\right)_{i,j}
    \end{equation*}
    converges weakly to those of $(Z_{i,j})_{i,j}$ which is a set of independent Poisson random variables with
    \begin{equation*}
        E[Z_{i,j}] = \frac{f(x_0)^{k+1}}{(k+1)!} \int_{(\BR^d)^k} h_{\Gamma_i}\left(\delta_{\bm{0}} + \sum_{\ell=1}^k \delta_{x_{\ell}}\right) \,\prod_{\ell=1}^k dx_{\ell} \times \text{Leb}(C_j).
    \end{equation*}

