&&\hspace{.2cm}+\mathbf{1}_{n+m\geq 3}\left(\frac{\epsilon^{2-2\zeta}}{(r-s)^{1/2}}
+C^{\epsilon}_{n,n}(r-s){\bf 1}_{n=m}+C_{n,m}^\epsilon(r-s){\bf 1}_{n\neq m}\right)\nonumber\\

&&\hspace{.2cm}+ \mathbf 1_{n+m\geq 2}\epsilon^{1+\zeta}(r-s)^{\zeta}
\end{eqnarray}
where $C_{n,m}^\epsilon(,r-s),C_{n,m}^\epsilon(,r-s)$  are given in (equation C11 of the paper)--(equation Cnm of the paper) respectively.

