[Defn def-metric of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] Let $S$ be a countable set with the discrete topology (we will eventually take $S = \mathcal V\mathcal G \cup \{\infty\}$). 
We define $L^1_{\operatorname{loc}}([0,\infty) ,S)$ to be the metric space of Lebesgue measurable functions $f : [0,\infty) \to S$, with functions identified if they agree Lebesgue a.e., with the metric
\begin{equation}  
\mathbbm d(f,g) := \int_0^\infty e^{-t} \mathbbm 1_{f(t) \not= g(t)} \,dt .
\end{equation} 
It is easy to check that with this metric, $L^1_{\operatorname{loc}}([0,\infty) ,S)$ is a complete, separable metric space.

[Lemma eq:U-inside of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:semicircle-log-potential}
For \(\left\lverty\right\rvert\le\sqrt2\),
\begin{equation}
 U(y)=\frac{y^2}{2}-\frac12-\frac12\log2.
\end{equation}
For \(\left\lverty\right\rvert>\sqrt2\),
\begin{equation}
 U'(y)=y-\operatorname{sgn}(y)\sqrt{y^2-2}.
\end{equation}
Consequently, relative to its quadratic continuation from the edge,
\begin{equation}
 U(y)=\frac{y^2}{2}-\frac12-\frac12\log2
 -\int_{\sqrt2}^{\left\lverty\right\rvert}\sqrt{z^2-2}\,\,\mathrm d z,
 \qquad \left\lverty\right\rvert>\sqrt2.
\end{equation}

[Prop lowlocal of arXiv:2504.19942, 'The edge-averaging process on graphs \\ with random initial opinions'] Consider the edge-averaging process on $G=(V,E)$ where $G$ is either the $n$-cycle or the infinite path $\mathbb Z$ with i.i.d.\ $\mathrm{Uniform}\{-1,1\}$ initial opinions, and let  $\varepsilon \in (0,1/3)$. If $t^*=\min(t,n^2)\ge (10/\varepsilon )^4$, then 
   \begin{equation}
    \mathbb P \big( f_t(o) \geq \varepsilon  \big) \ge \tfrac{1}{80}\exp( -72\varepsilon ^2 \sqrt{t_*})\,.
\end{equation}

[Lemma 3 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] For every $n\ge 1$,
\begin{equation}

Z\hat C(\Delta_T^{n+1}; B_\alpha)=\hat B(\Delta_T^{n+1}; B_\alpha).
\end{equation}

