body:
[Lemma inlarge of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] For any $r\ge0$ and $t\in\left[\frac{e_0\tilde{\mu}_{n,N}}{\tilde{\sigma}_{n,N}},\infty\right)$, when $N$ is sufficiently large, we have
    \begin{equation*}
        |G_{\tau}(t)|,~|H_{\tau}(t)|\le N^{-r}C(\gamma,r)e^{-\frac{t}{2}}
    \end{equation*}
    where $C(\gamma,r)$ is a constant determined by $\frac{N}{N+a}\rightarrow\gamma\in(0,1)$ and $r$.

[Proposition ASsSCAAS of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume \( \frac{1}{3}<\beta< \gamma< H\) and let \(\mathbf{B}\) be the delayed \(\gamma\)-rough path cocycle constructed in Theorem (thm:B_delayed_cocycle of the paper). Consider the same conditions on \(A\), \(\pi\), and \(G\) as specified in Proposition (BBSTAB of the paper). We consider the following linear rough delay equation:
			\begin{equation}
				\begin{aligned}
					\mathrm{d}y_t &= A \left( y_t, \int_{-r}^{0} y_{\theta+t} \, \pi(\mathrm{d}\theta) \right) \mathrm{d}t + \epsilon G(y_t, y_{t-r}) \, \mathrm{d}\mathbf{B}_t(\omega), \\
					y_{\theta} &= \xi_{\theta} \quad \text{for} \quad \theta \in [-r, 0], \quad \xi \in \mathscr{D}_{\mathbf{B}(\omega)}^{\beta, \gamma}([-r,0]),
				\end{aligned}
			\end{equation}
			where \( y^{\xi, \epsilon}_t(\omega) \) denotes the solution. Let \( \lambda_1 \) be as defined in (equation TRFVV of the paper), and assume \( \lambda_1 < 0 \). Then, there exists \( \epsilon_0 > 0 \) such that for every \( 0 < \epsilon < \epsilon_0 \), there exists \( \lambda^\epsilon < 0 \) such that for any \( \xi \in  \mathscr{D}_{\mathbf{B}(\omega)}^{\beta, \gamma}([-r,0]) \), the following holds:
			\begin{equation}
				\limsup_{t \to \infty} \frac{1}{t} \log | y^{\xi, \epsilon}_t(\omega) | \leq \lambda^\epsilon.
			\end{equation}
			In particular, our stability result holds for every \(\xi \in C^{2\gamma}([-r, 0], \mathbb{R}^n)\), where \(\frac{1}{3} < \gamma < H\) and \(\gamma\) can be chosen arbitrarily close to \(\frac{1}{3}\).

[Corollary 20 of arXiv:2609.01020, '2609.01020'] In the situation as above, there exists $0<\e_1 \ll 1$ and $\lambda >0$ such that 
we have an isomorphism 
\begin{equation}
\psi_f(F)_{(0,0)} \simeq \rsect (B(0;\e)\times B(0;\lambda \e) \cap f^{-1}(t); F)
\end{equation}
for any $0<\e \leq \e_1$ and $t\in \CC^\ast$ such that $0<\abs{t} \ll 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 7 of arXiv:2606.15842, 'A small noise approximation for Muller's Ratchet'] Let $(S_t)_{t\geq 0}$ be the semigroup generated by $G^{(1)}$. Started in $x \in \mathbb S$, the solution of \eqref{eq:dynsys1} satisfies, for $\xi \in \mathbb R_+$, 
\begin{equation}

\begin{aligned}
  S_t g_{\xi}(x) & = g_{\xi}(x(t)) = \frac{g_{\alpha t + \xi}(x)}{g_{\alpha t}(x)}
  \exp\Big(-\theta(1-e^{- \xi})(1-e^{-\alpha t})\Big)
\end{aligned}
\end{equation}
as well as, for $\xi, \eta \in \mathbb R_+$,
\begin{align}

    G^{(1)}S_t g_{\xi} & = \exp\Big(-\theta(1-e^{- \xi})(1-e^{-\alpha t})\Big)\Big(\lambda e^{-\alpha t}(1 - e^{-\xi})\frac{g_{\alpha  t + \xi}}{g_{\alpha t}} + \frac{\partial}{\partial t} \frac{g_{\alpha  t + \xi}}{g_{\alpha t}}\Big), \\ 
    G^{(1)}S_t g_{\xi} g_{\eta} & = (S_t g_{\xi})\, G^{(1)}S_t g_{\eta} + (S_t g_{ \eta})\, G^{(1)}S_t g_{ \xi}, \\ 

    \nu \cdot G^{(2)}S_t g_{ \xi} & = 
    \frac{g_{\alpha  t + \xi}(x)g_{2\alpha t} - g_{\alpha t} g_{2\alpha t+\xi}}{g_{\alpha t}^3}\exp\Big(-\theta(1-e^{-\xi})(1-e^{-\alpha t})\Big), \\
    \nu \cdot G^{(2)}S_t g_{\xi} g_{\eta}  & = \exp\Big(-\theta(2-e^{-\xi} - e^{- \eta})(1-e^{-\alpha t})\Big) \notag \\ 
     &  \cdot 
    \frac{
    3g_{\alpha t + \xi} g_{\alpha  t + \eta}g_{2\alpha t} - 2 g_{\alpha  t + \xi} g_{\alpha t}g_{2\alpha t + \eta} - 2 g_{\alpha t + \eta} g_{\alpha t} g_{2\alpha t+\xi} + g_{\alpha t}^2 g_{2\alpha t+\xi+\eta}}{g_{\alpha t}^4}. 
\end{align}
Moreover, for $f_{t,\xi,\eta} := \nu \cdot G^{(2)}S_t g_{\xi} g_{\eta}$, there are bounded functions $g_{s, t, \xi, \eta}, g^1_{s, t, \xi, \eta}, g^2_{s, t, \xi, \eta} \in \text{span} \{g_{\xi_1} \cdots g_{\xi_m}: m \in \mathbb N, \xi_1,...,\xi_m \in \mathbb R_+ \}$ and $a, a_1, a_2$ (all not depending on $\nu$) such that 
\begin{align}

    S_s f_{t,\xi, \eta} = \frac{g_{s,t,\xi, \eta}}{g_{\alpha (s+t)}^{a}}, \qquad G^{(1)} S_s f_{t,\xi, \eta} = \frac{g^1_{s,t,\xi, \eta}}{g_{\alpha (s+t)}^{a_1}}, \qquad \nu \cdot G^{(2)} S_s f_{t,\xi, \eta} = \frac{g^2_{s,t,\xi, \eta}}{g_{\alpha (s+t)}^{a_2}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Filtered process) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] A filtered process is a five-tuple 
\begin{equation} 
\bX = \left(\Omega^{\bX}, \cF^{\bX}, \bP^{\bX}, \bF^{\bX} = (\cF_t^{\bX})_{t = 1}^N, X = (X_t)_{t = 1}^N\right),
\end{equation}
where $(\Omega, \cF, \bP, \bF)$ is a filtered probability space and $X$ is an $\R^d$-valued stochastic process on $(\Omega, \cF, \bP)$ adapted to $\bF$. We let $\cFP_2$ be the family of all filtered processes $\bX$ with $\cL(X) \in \cP_2(\bR^{Nd})$.

[Proposition 1 of arXiv:2606.02464, 'Inspections'] If $\lambda_\tau=\lambda p$ and $p\in(0,1)$, then
 \begin{equation}
      \rho>\sigma\ .
