body:
[Definition 2 (One-parameter Mittag--Leffler function) of arXiv:2608.25164, 'A time-fractional Kalman filter'] For $z,\alpha\in\mathbb C$ with $\operatorname{Re}(\alpha)>0$, define
\begin{equation}
E_\alpha(z)=E_{\alpha,1}(z)
=\sum_{k=0}^{\infty}\frac{z^k}{\Gamma(\alpha k+1)}.
\end{equation}

[Lem recur:differenceBound of arXiv:2607.09841, 'Mixing and cutoff for the systematic scan dynamics of the mean-field ferromagnetic Potts m'] Let $\{b_t\}_{t \geq n}$ be a sequence of nonnegative real numbers and define $\{d_t\}_{t \geq 0}$ as the sequence
\begin{align*}
    d_t = \begin{cases}
0 & \text{ for } 0 \leq t< n,\\
b_t +  \frac{\beta}{nq}\sum_{i = t-n}^{t-1} d_i & \text{ for } t \geq n. \\
\end{cases} 
\end{align*}
Then, there exists a constant $C \geq 1$ such that for all $t \geq n$
\begin{align*}
    d_t \leq b_t +  \frac{C \gamma_n^t}{n}  \sum_{i = n}^{t} b_i \gamma_n^{-i}. 
\end{align*}
\begin{proof}
For $t \geq n$, we write
\begin{align*}
    d_t = \sum_{i = n}^{t} c_t(i) b_i,
\end{align*}
where $c_t(i)$ is the coefficient of $b_i$ once $d_t$ is expanded. 
Observe that $c_t(t) = 1$ and $b_\ell$ appears for the first time in the expansion of $d_\ell$. Therefore, we define $c_t(\ell)$ only when $t \geq \ell \geq n$, and thus
\begin{align}
c_t(\ell) = \begin{cases}
1 & \text{ for } t = \ell,\\
 \frac{\beta}{nq}\sum_{i = \ell}^{t-1} c_i(\ell) & \text{ for } \ell < t \leq\ell +n,\\
 \frac{\beta}{nq}\sum_{i = t-n}^{t-1} c_i(\ell) & \text{ for } \ell+n < t.\\
\end{cases} 
\end{align}
It is therefore sufficient to prove that there exists a constant $C > 0$ such that  $c_t(\ell) \leq (C/n) \gamma_n^{t -\ell}$ for all $t> \ell \geq n$. We fix $\ell \geq n$ and we prove the claim by induction on $t$. From (equation eqn:recur:differenceBound:ctDefn of the paper), we see that the claim holds for $t = \ell+1$ since $c_{\ell+1}(\ell) = \frac{\beta}{qn}$. For $t \in  \{\ell + 2 ,\dots,\ell + n\}$, 
\begin{align*}
    c_t(\ell) &= \frac{\beta}{nq}  \sum_{i = \ell}^{t-1} c_i(\ell)
        = \frac{\beta}{nq} \sum_{i = \ell}^{t-2} c_i(\ell) + \frac{\beta c_{t-1}(\ell)}{nq}   
        = c_{t-1}(\ell)+ \frac{\beta c_{t-1}(\ell)}{nq}   \\
        &= c_{t-1}(\ell) \Big(1 + \frac{\beta}{qn}   \Big) \leq c_{\ell+1}(\ell) \Big(1 + \frac{\beta}{qn}  \Big)^{n-1}  
        \leq \frac{\beta e^{\beta/q}}{nq} 
        \leq \frac{\beta e^{\beta/q} \gamma_n^{-n} \gamma_n^{t-\ell}}{nq}  .
\end{align*}
By (equation eqn:recur:GammaSingConstants of the paper), there exists a constant $C_1 > 0$ such that $\gamma_n^{-n} \leq C_1$. Therefore, for $C = (\beta/q) e^{\beta/q} C_1 \geq (\beta/q) e^{\beta/q} \gamma_n^{-n}$ our claim holds for all $t$ such that $\ell  < t \leq \ell + n$ and the base case of the induction holds. Now, assume that the claim holds for all $i < t$ for some $t > \ell + n$, and then
\begin{align*}
    c_t(\ell) = \frac{\beta}{nq}  \sum_{i = t-n}^{t-1} c_i(\ell) 
        \leq \frac{C\beta}{n^2q}  \sum_{i = t-n}^{t-1}\gamma_n^{i-\ell} 
        = \frac{C \beta}{n^2 q}  \sum_{i = 0}^{n-1}\gamma_n^{i + t-n-\ell} 
        &= \frac{C \gamma_n^{t-\ell}}{n^2}  \bigg(\frac{\beta}{q} \sum_{i = 0}^{n-1}\gamma_n^{i-n} \bigg) = \frac{C\gamma_n^{t - \ell}}{n} . 
\end{align*}
where the last equality uses the definition of $\gamma_n$ in~(equation eqn:recur:gammaMain of the paper). This completes the induction and hence the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Let $\alpha \in (1/2,1)$. Suppose $U:\T^d \to\R^d$ is a $C^{\alpha-}(\T^d)$ multiscale finite range random velocity field; that is, $U$ satisfies Assumption~\ref{asmp:main for autonomous}, and \eqref{eq:main theorem hypothesis} holds for some $p > \frac{d}{\alpha-1/2}$. Suppose in addition that $\nabla \cdot U=0$ and there exists a random constant $\delta>0$ such that almost surely
        \begin{equation}

        \lim_{\ep \to 0} \ep^{-(1-\alpha +\delta)} |Z_\ep| =0.\end{equation}      
    Then almost surely, 
    \begin{enumerate}
        \item for almost every $y \in \T^d$,~\eqref{eq:main ODE autonomous data} admits a unique solution on $(-\infty,\infty)$,
        \item and for every bounded $\phi : \T^d \to \R$,~\eqref{eq:continuity} admits a unique bounded solution $f$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq: def-whitney of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Given a graph $G = (V,E)$ define the Whitney number polynomial $w_G(x,t)$ as \begin{equation}

    w_G(x,t) := \sum_{A\in \mathcal{F}(G)} x^{rk(A)}\chi_{G/A}(t)
\end{equation} where $\mathcal{F}(G)$ is the set of flats of $G$. In a graph $G = (V,E)$, a flat $A \in \mathcal{F}(G)$ is a subset of $E$ such that each connected component of the graph $(V,A)$ is an induced subgraph of $G$.

[Proposition 5 (Weak continuity identity) of arXiv:2608.29107, 'PathGuide: Dynamic Classifier-Free Guidance via On-Policy Transport Alignment'] Let \(\rho_t\) and \(b_t\) satisfy
\begin{equation}
    \partial_t\rho_t+\divg(\rho_t b_t)=0
\end{equation}
in the distributional sense on \([0,1]\times\R^d\). Then, for every
\(\psi\in C_c^1(\R^d)\), the map
\begin{equation}
    t\mapsto \int_{\R^d}\psi(x)\rho_t(x)\,\dd x
\end{equation}
is absolutely continuous and, for almost every \(t\),
\begin{equation}
    \frac{\dd}{\dd t}
    \int_{\R^d}\psi(x)\rho_t(x)\,\dd x
    =
    \int_{\R^d}
    \grad\psi(x)\cdot b_t(x)\rho_t(x)\,\dd x .
\end{equation}

[Lemma lem:interior_intersection_left of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Fix $a_1 >0$, $p \in (0,1)$. Suppose $h$ is a GFF on $\delta\mathbf{D}$ with some bounded boundary values so that the angle $\theta_0$ flow line $\eta_0$ from $-i\delta$ to $i\delta$ and the angle $\theta_0$ flow line $\overline{\eta}_0$ from $i\delta$ to $-i\delta$ in the components of $\delta\mathbf{D} \setminus \eta_0$ to the right of $\eta_0$ (and reflected off $\eta_0$) are defined. Let $z_1 \in \partial B(0,\delta/2)$, $w_1 \in \partial B(0,3\delta/16)$. Let $\eta_{z_1}^{\theta_0}$ be the angle $\theta_0$ flow line of $h$ starting from $z_1$ and stopped upon exiting $B(0,3\delta/4)$. Let $\eta_{w_1}^R$ be the angle $-\pi/2$ flow line starting from $w_1$, reflecting off $\eta_{z_1}^{\theta_0}$ in the opposite direction, and stopped upon exiting $B(0,\delta/4)$. Let $\eta_{w_1}^L$ be the angle $+\pi/2$ flow line starting from $w_1$ and stopped upon exiting $B(0,3\delta/4)$. In case $\eta_{w_1}^R$ and $\eta_{z_1}^{\theta_0}$ intersect, sample the internal metric in the regions bounded between them. 
Let $E^p$ be the event that the following hold.
\begin{itemize}
\item $\eta_{w_1}^R$ intersects the right side of $\eta_{z_1}^{\theta_0}$ with an angle difference of $3\pi/2 - \theta_0 = 0$ (before reflecting off), and they do not intersect in any other way.
\item $\eta_{w_1}^L$ does not intersect $\eta_{z_1}^{\theta_0}$.
\item There exist $x',x,y,y' \in \eta_{z_1}^{\theta_0} \cap \eta_{w_1}^R$ such that $(x,y) \in \intptsapproxbubble{U_{x',y'}}{\epsilon}$ as in~(equation eq:intpts_bubble of the paper) and $U_{x',y'} \subseteq B(0,\delta^{1+a_1})$ and $\metapproxacres{\epsilon}{U_{x',y'}}{x}{y}{\Gamma} \geq \median{\epsilon}+\epsilon^{-a_0}\mathbf{a}_{\epsilon}$.
\item The following event has conditional probability at least $p$ given $\eta_{z_1}^{\theta_0}$, $\eta_{w_1}^R$, $\eta_{w_1}^L$, $X_\delta^{\theta_0}$, $X_\delta^{+\pi/2}$, and the values of $h$ on these sets:
\begin{itemize}
\item The flow line $\eta_0$ merges into $\eta_{z_1}^{\theta_0}$ before entering $B(0,\delta/4)$.
\item The extension of $\eta_{w_1}^L$ does not intersect $\eta_0$ until it hits $\partial(\delta\mathbf{D})$.
\end{itemize}
\end{itemize}
Then $\mathbf{P}[E^p] = O(\delta^{{\alpha_{\mathrm{apr}}}})$ as $\delta \to 0$.

[Corollary cor:HD_Sak of arXiv:2508.18807, '{\bf Critical long-range percolation I: High effective dimension}'] Suppose that at least one of the hypotheses of (equation HD+ of the paper) holds. If $\alpha<2$ then
\[
  \frac{1}{r^2}\sum_{x\in B_r}\mathbb P_{\beta_c}(0\leftrightarrow x) \asymp r^{-d+\alpha}
\]
for all $r\geq 1$. In particular, the critical exponent $\eta$ is well-defined  and equal to $2-\alpha$ in the spatially-averaged sense. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Iup L-S-C of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper) such that (equation eq:small-KS of the paper) holds. For each fixed $\varphi \in C^{\infty}([0,T]\times\mathbb{T}^2)$, $\Lambda(\cdot,\varphi)$ as defined in (equation Lambda of the paper) is continuous on $L^1([0,T] \times \mathbb{T}^2)$, and consequently, the rate function $\mathcal{I}$ is lower semi-continuous  with respect to the strong $L^1$ topology, namely, for every $(\rho_n)_{n\geqslant1}$ and $\rho$ in $\mathcal{E}_{\mathrm{fin}}$, 
  \begin{equation}
\lim_{n \to \infty}\rho_n = \rho \ \text{in} \ L^1_{[0,T]}L^1_{\mathbb{T}^2} \quad \Rightarrow \quad \liminf_{n \to \infty}\mathcal{I}(\rho_n)\geqslant \mathcal{I}(\rho).
  \end{equation}

