body:
[Theorem 44 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Let $T_s^N$ be the transport map defined in Proposition \ref{prop:transportmap}, with $V_0=\frac{1}{2}\sum_{i=1}^d X_i^2$, and $V_1 = \frac{1}{2}\sum_{i=1}^d X_i^2 + W $ where $W\in\cC^{4k+7}(X_1,\dots,X_d)$. We assume that
    $$\kappa \coloneqq \sup_{1\leq p\leq d}\ \left\{ \sum_{1\leq i\leq d} \norm{\partial_i\bD_pW}_{0,\infty} + \norm{\widetilde{\partial}_i \bD_p W }_{0,\infty} \right\} < \frac{1}{4k+5},$$
    $$ \sup_{1\leq j\leq 4k+7} \norm{W}_{j,\infty} <\infty. $$    

    \noindent Then there exists $T_s^0,\in (\cC^k(X_1,\dots,X_d))^d$, as well as $T_s^m\in (\cC^{k+1-m}(X_1,\dots,X_d))^d$ for $m\in [1,k]$, continuous with repect to $s$, such that for all $s\in [0,1]$, $N\geq 1$,
    \begin{equation}

        \sup_{H\in\M_N(\C)_{sa}^d}\ \norm{T_s^N(H) - \sum_{i=0}^k \frac{T_s^i(H)}{N^{2i}} } \leq \frac{C_{W,k}}{N^{2k+2}}.
    \end{equation}
    Besides, with  $\norm{\cf}_{\cC^k,\infty} = \sum_{p=1}^d \norm{\cf_i}_{\cC^k,\infty} $ if $\cf\in (\cC^k(X_1,\dots,X_d))^d$, there exists a constant $C_{W,k}$ such that
    \begin{align}

        \norm{T_s^0 - \id }_{\cC^k,\infty}\leq C_{W,k}, \quad\quad \norm{T_s^m}_{\cC^{k+1-m},\infty}\leq C_{W,k},\quad 1\leq m\leq k.
    \end{align}

