    $$\begin{aligned}&\sup_{\epsilon_1,c,I,C_I^1,C_I^3,s_1,t_1,s_2,t_2}
\mathbb{P}^\mathcal{K}
(\exists(v_1,v_2)\in\mathcal{P}_{\epsilon_1}(c)\cup\mathcal{P}_{\epsilon_1}^0(c)\text{ associated with } D=[c_0^2n/4]:\\&
D_{\alpha,\gamma}((C_I^1v_1+C_I^3v_3)_I)\leq e^{c_\Sigma n}, \|(A_n-s_iI_n)v_i-t_iw_0\|_2\leq 2^{-n/2}\forall i=1,2)\leq 2^{-500n},
