[Theorem th:lm:SPDE of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Suppose $2H\alpha =3$, and fix $z_0 = (t_0\,,x_0) \in (0\,,\infty) \times \mathbb{R}$. Then, a.s.,
\begin{align}
    \lim_{h\to0^+} \sup_{x: 0<|x-x_0|\le h} \frac{|u(t_0\,,x)-u(t_0\,,x_0)|}{|x-x_0|\sqrt{\log(1/|x-x_0|) \log\log\log(1/|x-x_0|)}} = K_6,
\end{align}
\begin{align}
    \lim_{h\to0^+} \sup_{t: 0<|t-t_0|\le h} \frac{|u(t\,,x_0)-u(t_0\,,x_0)|}{|t-t_0|^{1/\alpha}\sqrt{\log\log(1/|t-t_0|)}} = K_7,
\end{align}
\begin{align}
    \lim_{h\to0^+} \sup_{z : 0<\phi(z,z_0) \le h} \frac{|u(z)-u(z_0)|}{\phi(z\,,z_0)\sqrt{\log\log(1/\phi(z\,,z_0))}} = K_8,
\end{align}
for some non-random numbers $K_6,K_7,K_8 \in (0\,,\infty)$ that may depend on $t_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:excon of arXiv:2411.07809, 'Pirogov--Sinai Theory Beyond Lattices'] Let $\Lambda$ be a finite induced subgraph of $G$ with $\partial
  \Lambda = \partial_{\text{ext}} \Lambda$. Then 
    \begin{equation*}
  \Xi_{\Lambda}^{\textsf{e}}  =  {\sum_{\Gamma\subset
        \overline{\mathcal C}(\Lambda)}}^{\!\!\!\!\!\textsf{e},\mathsf{Ext}} \prod_{\gamma \in
      \Gamma} \widetilde{w}_\gamma \Xi^{\textsf{e}}_{\mathsf{Int}_{\textsf{e}} \gamma}
    \Xi^{\textsf{e}}_{\mathsf{Int}_{\textsf{o}} \gamma}, \qquad \text{and} \qquad
    \Xi_{\Lambda}^{\textsf{o}}  =   {\sum_{\Gamma\subset
        \overline{\mathcal C}(\Lambda)}}^{\!\!\!\!\!\textsf{o},\mathsf{Ext}} \prod_{\gamma \in \Gamma} \widetilde{w}_\gamma \Xi^{\textsf{o}}_{\mathsf{Int}_{\textsf{e}} \gamma} \Xi^{\textsf{o}}_{\mathsf{Int}_{\textsf{o}} \gamma}. 
  \end{equation*}

[Lemme 71 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] If $\ups_j = -\vsg $, $\vsg \in \{\pm\}$, then one has the upper bound

$$\sul{i=j+1}{N} \frac{ |\lambda_j^{-\vsg} - \lambda_j^{\vsg} |}{\lambda_i^{\vsg} - \lambda_j^{-\vsg} }

+ \sum_{i=1}^{j} \frac{|\lambda_{j+1}^{-\vsg} - \lambda_{j+1}^{\vsg} | }{ \lambda_{j+1}^{-\vsg} - \lambda_i^{\vsg} } \,  \leq N  \, \, .$$

