[Lemma lem-decomp-qtf of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] There is a constant $C$ such that a sample from $M_W^f$ can be obtained by conformally welding a tuple $(\mathcal{D}_1, \mathcal{D}_2, \mathcal{D}_3, \mathcal T)$ sampled from 
		\begin{equation}
		\begin{split}
			C \int 1_{\ell_1 + \ell + \ell_3 > r + r_2} \Big(&\mathcal M^\mathrm{f.d.}_{0,2}(W; \ell_1+\ell+\ell_3 - r - r_2, \ell_1) \times \mathcal  M_{0,2}^\mathrm{f.d.}(W; \cdot, r_2) \\ &\times \mathcal M_{0,2}^\mathrm{f.d.}(\gamma^2-2; \ell_3, \cdot) \times \mathrm{QT}^f(\gamma^2-W,\gamma^2-W,\gamma^2-2; r, \ell)\Big),
		\end{split}
		\end{equation}
		where in~(equation eq-decomp-qtf of the paper) we integrate over $(\ell_1, \ell, \ell_3, r, r_2) \in (0,\infty)^5$ with respect to Lebesgue measure. 


		Moreover, for a sample from $M_W^f$, under the embedding of $\tilde \mathcal{D}$ as $(\mathbb{H}, \phi, \eta, i, \infty)$, let $\tau$ be the time that $\eta$ disconnects $i$ from $\partial \mathbb{H}$, let $G \subset \mathbb{H}$ be the connected component of $\mathbb{H} \backslash \eta$ such that $\eta(\tau) \in \overline G$ and $\overline G \cap \partial \mathbb{H}\neq \emptyset$, and let $[x_2, x_3] = \overline G \cap \partial \mathbb{H}$. Let $E$ be the event that $\eta$ hits $x_2$ before hitting $x_3$. Then a sample from $1_E M_W^f$ can be obtained from conformally welding $(\mathcal{D}_1, \mathcal{D}_2, \mathcal{D}_3, \mathcal T)$ sampled from~(equation eq-decomp-qtf of the paper) but with the integrand containing the additional factor $1_{\ell_3 > r_2}$.

[Theorem thm: enhancement converge of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Almost surely for every $(\varphi_1,\varphi_2) \sim \nu^0\otimes \nu^0$, there exist a random variable
\begin{equation}
	\Xi^\partial_\infty(\varphi_1,\varphi_2)\in \boldsymbol{\mathfrak B} 
\end{equation}
called the \emph{limiting enhanced boundary field} such that the following holds.
\begin{enumerate}
\item[\textup{(I)}] {\rm \bf (Almost sure convergence)} Almost surely in $(\varphi_1,\varphi_2) \sim \nu^0\otimes \nu^0$, we have the following convergnce in the Banach space $\boldsymbol{\mathfrak B}$: 
\begin{equation}
\lim_{T \rightarrow \infty} \Xi^\partial_T(\rho_T \ast \varphi_1, \rho_T \ast \varphi_2) =\Xi^\partial_\infty(\varphi_1,\varphi_2)
\end{equation}
\item[\textup{(II)}] { \rm  \bf (Distributional convergence)} Almost surely in $\varphi \sim \nu^0$, we have the following convergence in law:
\begin{equation}
	\big( \Xi^\partial_T(\rho_T \ast \varphi, \cdot) \big) _* \nu^0_T\rightharpoonup \big( \Xi^\partial_\infty(\varphi, \cdot) \big)_* \nu^0.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2605.28377, 'Geometric functionals of Brownian motion on Hermitian symmetric spaces of non-compact type'] Let $(e_1,\cdots,e_r)$ be a Jordan frame. Let $\phi$ be a linear map from $(V, (\cdot |\cdot))$ into itself satisfying, for every $x,y,z \in V$,
\begin{align}
\phi( \{ x \, y \, z \})=\{ \phi(x) \, y \, z \}+\{ x \, \phi(y) \, z \}+\{ x \, y \, \phi(z) \}.
\end{align}
Then for every $1\le i \neq j \le r$, one has $(\phi(e_i) | e_j)=0$.

[Propo 14 of arXiv:2604.14752, 'Strong and weak rates of convergence in the Smoluchowski--Kramers approximation for stocha'] Let Assumptions~\ref{ass:mapping-f} and~\ref{ass:noise} be satisfied. Let $\varphi:H\to\R$ be of class $\mathcal{C}^4$ with bounded first and second order derivatives.

For all $T\in(0,\infty)$ and all $\alpha\in[0,1]$, there exists a real number $C_\alpha(T)\in(0,\infty)$ such that, for all $\epsilon\in(0,1)$, all $t\in(0,T]$, all $N\in\N$ and all $(u,v)\in \HH_N$, $h\in H_N$, one has
 	\begin{align}
		\big|D_{u}\Phi^{(\epsilon,N)}(t,u,v).h\big|&\le C_\alpha(T)\vvvert \varphi\vvvert_1 t^{-\frac{\alpha}{2}}\bigl(\epsilon^{\alpha}\|h\|_H+\|h\|_{H^{-\alpha}}\bigr),\\ 
	 \frac{1}{\epsilon}|D_v\Phi^{(\epsilon,N)}(t,u,v).h|&\le C_\alpha(T)\vvvert \varphi\vvvert_1 t^{-\frac{\alpha}{2}}\|h\|_{H^{-\alpha}}. 
	\end{align}
Moreover, for all $\alpha_1,\alpha_2\in[0,1)$, there exists $C_{\alpha_1,\alpha_2}(T)\in(0,\infty)$ such that, for all $\epsilon\in(0,1)$, all $t\in(0,T]$, all $N\in\N$ and all $(u,v)\in \HH_N$, $h,k\in H_N$, one has
\begin{align}
	&|D^2_{uu}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\bigl(\epsilon^{\alpha_1}\|h\|_H\!+\!\|h\|_{H^{-\alpha_1}}\bigr)\bigl(\epsilon^{\alpha_2}\|k\|_H\!+\!\|k\|_{H^{-\alpha_2}}\bigr),\\
	&\frac{1}{\epsilon}|D^2_{uv}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\bigl(\epsilon^{\alpha_1}\|h\|_H\!+\!\|h\|_{H^{-\alpha_1}}\bigr)\|k\|_{H^{-\alpha_2}}, \\
      &\frac{1}{\epsilon}|D^2_{vu}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\|h\|_{H^{-\alpha_1}}\bigl(\epsilon^{\alpha_2}\|k\|_H\!+\!\|k\|_{H^{-\alpha_2}}\bigr),\\
      &\frac{1}{\epsilon^2}|D^2_{vv}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\|h\|_{H^{-\alpha_1}}\|k\|_{H^{-\alpha_2}}. 
	\end{align}

