[Corollary Cor:length of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] For each $\varepsilon>0$, there exists constants $A,B$ depending on $\varepsilon$ such that for all $n\ge 1$ and $v$:
\[
\mathchoice
{\mathbb P \left( \rule{0pt}{11pt} |\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon) \right)}
{\mathbb P \left(|\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon)\right)}
{\mathbb P \left(|\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon)\right)}
{\mathbb P \left(|\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon)\right)}
\le A \exp(-Bn). 
\]

[Lemma lem:perc_triangle of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 15$.
For any $\gamma > 0$, there is a $\delta = \delta(\gamma) \in (0,\delta_1)$ such that for $p \in [p_c - \delta, p_c)$ and $\mu \in \Omega_p$,
\begin{equation}
\begin{aligned}

{\sf T}^{(\mu)}(p) &\le 2 {\sf T}^{(0)}(p_c) + \gamma , \\
\tilde{\sf T}^{(\mu)}(p) &\le 2 \tilde {\sf T}^{(0)}(p_c) + \gamma , \\
{\sf B}^{(2\mu)}(p) &\le {\sf B}^{(0)}(p_c) + \gamma .
\end{aligned}
\end{equation}

[Proposition 49 of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] Define a mapping $\ki \colon [0,\infty) \to \bR_+\times \bR$ by 
\begin{equation}
\ki:=\varrho\circ \kappa\circ \eta.
\end{equation}

(i) The range of $\ki$ is the gasket $\rK$.

(ii) The jump times of the process $\ki$  coincide with those of $\eta$.

(iii) For a jump time $\ell$ of $\eta$, if $\cT$ is the spindle associated through \eqref{eq:bijection subor spindles}, we have
\begin{equation}
        (\eta_{\ell-},\eta_{\ell})=(A_{s_{\cT}},A_{t_{\cT}}),\;(\ki_{\ell-},\ki_{\ell})=(\varrho_{s_{\cT}},\varrho_{t_{\cT}}). 
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theorem_typical_distances of arXiv:2606.27357, '\textbf{Typical distances in high-genus triangulations}'] Fix $\theta \in (0,\frac{1}{2})$ and $\displaystyle \frac{g_n}{n} \to \theta$ as $n \to +\infty$. Let $e_n^1,e_n^2$ be two independent oriented edges chosen uniformly at random on $T_{n,g_n}$. Let $x_n^1$ and $x_n^2$ denote their respective starting points. Then, we have
    \begin{align}
       \frac{d_{T_{n,g_n}}(x_n^1,x_n^2)}{\log(n)} \xrightarrow[n \to +\infty]{(\mathbb{P})} D_{\theta},
    \end{align}
where $\displaystyle D_{\theta} = \frac{1}{\log(m_{\theta}^{-1})}$. The same result holds if $x_n^1,x_n^2$ are chosen to be independent uniform vertices on $T_{n,g_n}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 14 of arXiv:2605.16072, 'Stochastic integration \\with respect to a L\'evy basis'] Let $\O$ be in $\Borel(\R^d)$. 
	An infinitely divisible random measure $\Theta\colon \Borel_b(\Rp\times \O) \to L_P^0(\Omega;\R)$ is called a L\'evy basis if: 
	\begin{enumerate}
		\item[{\rm (a)}] for every $A\in\Borel_b(\Rp\times \O)$ for which there exists $t\ge 0$ such that $A\subseteq [0,t]\times \O$, 
		the random variable $\Theta(A)$ is $\F_t$-measurable; 
		\item[{\rm (b)}] for every $A\in\Borel_b(\Rp\times \O)$ for which there exists $t\ge 0$ such that $A\subseteq (t,\infty)\times \O$,  
		the random variable $\Theta(A)$ is independent of $\F_t$;
		\item[{\rm (c)}] $\Theta(\{t\}\times [-n,n]^d\cap\O)=0$ $P$-a.s.\ for all $t\ge 0$ and $n\in\N$.
	\end{enumerate}

[Thm 5 of arXiv:2607.22374, 'Asymptotic properties of the heat equation driven by stochastic measure'] Let Assumptions A\ref{assxu} -- A\ref{assxm} hold, $u^L$ is the solution to~\eqref{eq:bemfgl}, $u$ is the solution to~\eqref{eq:bemfg}. Then, for each $\delta>0$ there exist versions of $u^L, u$ such that for all $\omega\in\Omega$ for each $x\in D_L$, $L=i\delta$, $i\in\zz_+$, $0<t\le T$, for any $0<\lambda<\frac{1}{4}$ holds
\begin{equation}
|u^L(t,x)-u(t,x)|\le  C_{\delta}(\omega) C_\lambda  e^{-\frac{\lambda (L-|x|)^2}{t}} .
\end{equation}

