[Lemma terminal-string-bound of arXiv:2505.16585, 'Expanded regimes of area law for lattice Yang--Mills theories'] For all $(s,K,Q) \in \partial_1 \Omega$, we have that
\begin{equs}
\exp(10^{-2} B |Q|)|\phi(s,K)| \leq \exp((B/50) |Q|) e^{\sum_{p\in \mc{P}_{\Lambda}^+ \backslash (P\cup \partial Q)}(B-K(p))} Z_{\Lambda,P},
\end{equs}
where 
\begin{equs}
Z_{\Lambda,P}:=\int dU \prod_{p \in \mc{P}_{\Lambda}^+ \backslash P} \exp_B(2\beta \mathrm{Re}\Tr(U_p))\prod_{p \in  P} \tau_B(2\beta \mathrm{Re}\Tr(U_p))).
\end{equs}

[Lemma 3 of arXiv:2609.02147, '2609.02147'] Let $N \geq 1 $.  For any  $p \in [2, 2^*)$, there exists a constant $C_{p, N, V}>0$, depending only on  $p,N$ and $V$, such that
\begin{equation*}
    \|u\|_{p}^p \leq C_{p,N,V} \|u\|_{2}^{(1 - \beta_p)p} \abs{u}_{V}^{\beta_p p} \quad \text{for any $u \in H^1(\R^N)$},
\end{equation*}
where $\beta_p = N \left( \frac{1}{2} - \frac{1}{p} \right)$. 
Moreover, for $N \geq 3$, there exists a constant $C_{N, V}>0$, depending only on  $N$ and $V$, such that
\begin{equation*}
    \|u\|_{2^*}^{2^*} \leq C_{N,V}   \abs{u}_{V}^{2^*} \quad \text{for any $u \in H^1(\R^N)$}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Monotonicity of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] Let $n\geqslant2$, and let $\sigma$ be a locally finite, symmetric,
positive semidefinite matrix-valued Radon measure on $\mathbb R^n$. Put
$\mu:=\operatorname{tr}\sigma$ and $M(r):=\mu(B_r(0))$. If
\begin{equation}
 \operatorname{div}\left(\sigma-\frac12\mu I\right)=0,

\end{equation}
then
\begin{equation}
 \frac{M(s)}{s^{n-2}}\leqslant\frac{M(R)}{R^{n-2}}
 \qquad \forall 0<s<R.

\end{equation}

[Lem 22 of arXiv:2604.13134, '\bf From Gaussian to Gumbel: extreme eigenvalues of complex Ginibre products with exact ra'] Let $r_n$ and $s_n$ be  defined as above and  let $\Psi(t)=1-\Phi(t).$ 
 	 	\begin{itemize}\item[(1).] For any $1 \le j \le r_n$ and $|x| \le \sqrt{\log s_n}$, it holds 
 $$\aligned \widetilde{M}_{j, j}^{(n)}(x)&=\frac{2}{\pi}\int_{0}^{\pi/2}\Psi(\widetilde{v}_{\alpha}(j, x)-\sqrt{\alpha}\log\cos^2\theta) d\theta+O(s_n^{-1})
.\endaligned $$
 \item[(2).] For any $1\le j\neq k\le r_n$ with $j-k$ even and $|x| \le \sqrt{\log s_n},$ we have 
 \begin{equation} 
 	\widetilde{M}_{j, k}^{(n)}(x)=e^{-\frac{(j-k)^2}{4\alpha}}\frac{2}{\pi}\int_{0}^{\pi/2}\cos((j-k)\theta)\Psi(\widetilde{v}_{\alpha}(\frac{j+k}{2},x)-\sqrt{\alpha}\log \cos^2\theta)d\theta+O(s_n^{-9/10}). 
 \end{equation}
\item[(3).] Whenever $r_n+1\le j\le n$ and $x \ge -\sqrt{\log s_n},$ we have 
 \begin{equation}
 	\widetilde{M}_{j, j}^{(n)}(x)\ll s_n^{-1/10}\exp(-s_n^{1/6}). 
 \end{equation}
 \item[(4).] For $|x| \le \sqrt{\log s_n},$ we have 
 \begin{equation}
 	\sum_{j=r_n+1}^{n}\widetilde{M}_{j, j}^{(n)}(x)\ll \exp(-\frac{r^2_n}{3\alpha}).
 \end{equation}
 \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop pr:N_stochastic_object of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] For any $N\geq 2$, there exists a random variable $\Lambda$ such that for any $p \in [1, 6]$, we have
	\begin{equ}

		\sup_{0\leq s \leq 1}\|\mathcal{H}_{\Lambda} X[s]\|_{\Besov{-\kappa/N}{2, 2}} \leq \alpha_0\;, \quad \sup_{0\leq s \leq 1} \int_0^1 \|e^{t \Delta} \mathcal{H}_{\Lambda} X[s]\|_{\Besov{0}{4, pN}}^{pN} \mathrm{d} t \leq \alpha_0^{pN}\;.
	\end{equ}
There furthermore exist constants $C$ and $C_*$ such that
\begin{equ}

		\mathbb{E} \sup_{0\leq s \leq 1} \|\mathcal{P}_{C_*N \log N, \Lambda} X[s]\|^{2N} \leq (C\alpha_0^2)^{N} \;.
	\end{equ}

