[Prop 8 of arXiv:2608.15379, 'Stochastic Jacobi fields along discontinuous martingales on Riemannian submanifolds'] Let $\bJ=(X,J)$ be a $TM$-valued semimartingale and $\wilde{\cV}$ a $TTM$-valued adapted \cl process above $\bJ$.
\begin{itemize}
\item[(1)]If $\wilde{\cV}_-\in V_{\bJ_-}M$, then
\[
\int \lambda_{g^{\bcl}}\left( \wilde{\cV}_- \right) d^{\gamma^{\bcl}}\bJ = \int \langle v_{\bJ_-}^{-1}(\wilde{\cV}_-), dX\rangle_{\delta_{\mathbb{R}^d}}.  
\]
\item[(2)]If $\wilde{\cV}_-\in H_{\bJ_-}M$, then
\begin{align*}
\int \lambda_{g^{\bcl}}\left( \wilde{\cV}_- \right) d^{\gamma^{\bcl}}\bJ &= \int \langle (h^{\nabla}_{\bJ_-})^{-1}(\wilde{\cV}_-), dJ \rangle_{\delta_{\mathbb{R}^d}} + \frac{1}{2}\int \langle \II((h^{\nabla}_{\bJ_-})^{-1} (\wilde{\cV}_-), J_-), \II(dX^c, dX^c)\rangle_{\delta_{\mathbb{R}^d}} \\
&\h +\sum_{0<s\leq \cdot} \langle \II( (h^{\nabla}_{\bJ_{s-}})^{-1}(\wilde{\cV}_{s-}),J_{s-}),  \gamma^{\perp}(X_{s-},X_s) \rangle_{\delta_{\mathbb{R}^d}},
\end{align*}
where we set $\gamma^{\perp}(x,y)=\Pi^{\perp}_x(y-x)$ for $x,y\in M$ and denote the continuous local martingale part of an $\mathbb{R}^d$-valued semimartingale $X$ by $X^c$.
\end{itemize}

