[Theorem 21 of arXiv:2506.15044, '2506.15044'] Let $M,\; N,\;\widetilde{M}\in (\mathcal{M}^c_{\mathrm{loc}})^\mathbb{B}$.
\begin{itemize}
  \item [$(1)$] If $(T_n,M^{(n)})$ and $(T_n,N^{(n)})$ are FCSs for $M\in(\mathcal{M}^c_{\mathrm{loc}})^\mathbb{B}$ and $N\in(\mathcal{M}^c_{\mathrm{loc}})^\mathbb{B}$ respectively, then $(T_n,\langle M^{(n)},N^{(n)}\rangle)$ is an FCS for $\langle M,N\rangle\in (\mathcal{A}_{\mathrm{loc}}\cap \mathcal{C})^\mathbb{B}$, and $(T_n,\langle M^{(n)}\rangle)$ is an FCS for $\langle M\rangle\in (\mathcal{A}^{+}_{\mathrm{loc}}\cap \mathcal{C})^\mathbb{B}$.
  \item [$(2)$] For $a,b\in \mathbf{R}$, we have
      \[
       \langle M,N\rangle=\langle N,M\rangle,\quad \langle aM+b\widetilde{M},N\rangle=a\langle M,N\rangle+b\langle\widetilde{M},N\rangle.
      \]
  \item [$(3)$] If $\tau$ is a $\mathbb{B}$-inner stopping time, then we have
      \begin{equation}
       \langle M^{\tau},N^{\tau}\rangle
       =\langle M,N\rangle^{\tau}
      \end{equation}
  and
      \begin{equation}
       \langle M^{\tau}\mathfrak{I}_\mathbb{B},N^{\tau}\mathfrak{I}_\mathbb{B}\rangle
      =\langle M^{\tau},N^{\tau}\rangle\mathfrak{I}_\mathbb{B}
      =\langle M,N\rangle^{\tau}\mathfrak{I}_\mathbb{B}=\langle M^{\tau}\mathfrak{I}_\mathbb{B},N\rangle.
      \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] We say that an s-embedding $\mathcal{S} $ covering the open set $U\subseteq \mathbb{C}$ has a scale $\delta $ for the constant $ \kappa <1$ on $U$ if 
\begin{equation}
\delta = \delta^{\kappa} := \inf \{ \tilde{\delta} >0, \textrm{Lip}(\kappa, \tilde{\delta}) \textrm{ holds} \}.
\end{equation}

[Thm 1 of arXiv:2511.22156, ''] There is a Feller process $((X_t)_{t>0},(P^x)_{x\in F})$ on the Sierpi\'nski carpet $F$ with a transition density $q_t(x,y)$ satisfying the two-sided sub-Gaussian heat kernel estimate 
\begin{equation}
	\begin{split} 
		C_1\frac{1}{\mu(B(x,t^{1/\beta}))}\exp(-C_2(\frac{|x-y|^{\beta}}{t})^{\frac{1}{\beta-1}})&\leq q_t(x,y)\\&\leq C_3\frac{1}{\mu(B(x,t^{1/\beta}))}\exp(-C_4(\frac{|x-y|^{\beta}}{t})^{\frac{1}{\beta-1}})
	\end{split} 
\end{equation}
for all $x,y\in F$ and $t\leq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma zb-bdry-relns of arXiv:2608.27904, 'Instantons, indefinite 4-manifolds, and Dehn surgery'] So long as $|\theta| - |\beta| < 8 + \dim \mathscr O(\beta)$, the spaces $\mkern3mu\widetilde{\mkern-3muZ\mkern-1mu}\mkern1mu(\theta, \beta)$ and $\mkern3mu\widetilde{\mkern-3muB\mkern-1mu}\mkern1mu(\theta, \beta)$ are stratified-smooth spaces of dimensions $n = |\theta| - |\beta| - 4$ and $n = |\theta| - |\beta| - 1$, respectively.
The boundary $\partial \mkern3mu\widetilde{\mkern-3muZ\mkern-1mu}\mkern1mu(\theta, \beta)$ is given by 
\begin{equation} 
	\bigsqcup_{\alpha \in \mathsf{orb}(\mathcal M)} \mkern3mu\widetilde{\mkern-3muZ\mkern-1mu}\mkern1mu(\theta, \alpha) \times_{\alpha} \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta),
\end{equation}
and the boundary $\partial \mkern3mu\widetilde{\mkern-3muB\mkern-1mu}\mkern1mu(\theta, \beta)$ is given by the union of 
\begin{equation} 
	\bigsqcup_{\alpha \in \mathsf{orb}(\mathcal M)} \mkern3mu\widetilde{\mkern-3muB\mkern-1mu}\mkern1mu(\theta, \alpha) \times_{\alpha} \mkern3mu\widetilde{\mkern-3muM\mkern-1mu}\mkern1mu(\alpha, \beta),
\end{equation} 
and 
\begin{equation} 
	S^2 \times \mkern3mu\widetilde{\mkern-3muZ\mkern-1mu}\mkern1mu(\theta, \beta).
\end{equation} 	
Furthermore, the restriction of the source map to (equation boundary-B-2 of the paper) is projection to the first factor.

