body:
[Proposition p: d=1 hyperfluctuationg lattice thinning of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\BQ$ is a zeta distribution with parameter $s\in(2,3)$. Then $\Phi$ is solely $(s-3)$-uniform with
    \begin{equation}
        \frac{\BV[\Phi([0,r))]}{r^{4-s}} \xrightarrow{r\to\infty} \frac{\zeta(s)^2\Gamma(s-4)}{2\zeta(s-1)^3\Gamma(s)} > 0.
    \end{equation} 
    If $\BQ$ is a zeta distribution with parameter $s=3$, then $\Phi$ is $p$-uniform for any $p<0$, but not $0$-uniform.
    \begin{proof}
        First, suppose that $s\in(2,3)$. Then Jonqui\`ere's expansion yields that, as $k\to 0$,
        \begin{equation*}
            \hat\BQ(k) = 1 -i\frac{\zeta(s-1)}{\zeta(s)}k + \frac{\Gamma(1-s)}{\zeta(s)} (ik)^{s-1} + O(k^2); 
        \end{equation*}
        see, e.g.,~[Olver_Lozier_Boisvert_Clark_2010] or~[Wood_1992]. Hence, as $k\to0$,
        \begin{align*}
            \Re(1-\hat\BQ(k)) &= -\frac{\Gamma(1-s)}{\zeta(s)} \sin\Big(\frac{s\pi}{2}\Big) |k|^{s-1} + O(k^2),\\
            \Im(1-\hat\BQ(k)) &= \frac{\zeta(s-1)}{\zeta(s)}k + o(k).
        \end{align*}
        If we apply these approximations to~(equation e:renewal bartlet formula of the paper), we obtain, as $k\to0$,
        \begin{align}
            g(k) &= \frac{\zeta(s)}{\zeta(s-1)}\bigg(1+2\Re\bigg(\frac{\hat\BQ(k)}{1-\hat\BQ(k)}\bigg)\bigg)\nonumber\\
            &= \frac{\zeta(s)}{\zeta(s-1)} \bigg(2\Re\bigg(\frac{1}{1 - \hat\BQ(k)}\bigg) - 1\bigg) \nonumber\\
            &= \frac{\zeta(s)}{\zeta(s-1)} \bigg(\frac{-\frac{\Gamma(1-s)}{\zeta(s)} \sin(\frac{s\pi}{2}) |k|^{s-1} + O(k^2)}{\frac{\zeta(s-1)^2}{\zeta(s)^2}k^2 + o(k^2)} - 1\bigg)\nonumber\\
            &= \underbrace{-\frac{\zeta(s)^2\Gamma(1-s)\sin(\frac{s\pi}{2})}{\zeta(s-1)^3}}_{>0} |k|^{s-3} + O(1).
        \end{align}
        Now we can calculate that
        \begin{align*}
            \lim_{r\to\infty} \frac{\BV[\Phi([0,r))]}{r^{4-s}} &= \lim_{r\to\infty} (2\pi)^{-1}r^{s-4} \int |\hat\I_{[0,r)}(k)|^2 \, \hat\beta_\Phi(dk) \nonumber\\
            &= \lim_{r\to\infty} - (2\pi)^{-1}r^{s-2} \int_0^\infty \frac{\sin(\tfrac{rk}{2})^2}{(\tfrac{rk}{2})^2} \frac{\zeta(s)^2\Gamma(1-s)\sin(\frac{s\pi}{2})}{\zeta(s-1)^3} k^{s-3} \, dk \nonumber\\
            &= -\frac{2^{s-2}\zeta(s)^2\Gamma(1-s)\sin(\frac{s\pi}{2})}{2\pi\zeta(s-1)^3} 
            \int_0^\infty \sin(k)^2 k^{s-5}\, dk\nonumber\\
            &= \frac{\zeta(s)^2}{\pi\zeta(s-1)^3} \Gamma(s-4) \Gamma(1-s)\sin(\tfrac{s\pi}{2}) \cos(\tfrac{s\pi}{2})\nonumber\\
            &= \frac{\zeta(s)^2\Gamma(s-4)}{2\zeta(s-1)^3\Gamma(s)},
        \end{align*}
        where we first used the variance formula~(equation e: spectral covariance formula of the paper), then substitution, the Mellin transform for the last integral; see, e.g.,~[Bracewell_2000], and the gamma reflection identity and an addition theorem in the final step.
        This limit finishes the first part of the proof. Let us now assume that $s=3$. Then another formula gives the expression
        \begin{equation*}
            \hat\BQ(k) = 1 -i\frac{\zeta(3)}{\zeta(2)}k  - \frac{k^2}{2} \bigg(\frac{3}{2} - \ln(ik)\bigg) + o(k^2),
        \end{equation*}
        see~[Wood_1992].
        A similar calculation yields
        \begin{equation}
            g(k) = \frac{\zeta(2)}{\zeta(3)}\ln\Big(\frac{1}{|k|}\Big) + O(1),
        \end{equation}
        as $k\to 0$, which also proves this part of the assertion.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] We say that a graph $G$ satisfies the Poincaré Inequality if there exist $C>0$ and $C^{\prime} \geq 1$ such that for any $f \in \mathbb R^{V}$ and $r> 0:$
\begin{equation}
    \sum_{y \in B_x(r)} |f(x) - f_{r} (x)|^{2} \leq Cr^{2} \sum_{B_x(C^{\prime}r)} |\nabla f|^{2}(y) \, ,
\end{equation}
where  
\begin{equation*}
    f_{r}(x):= \frac{1}{|B_x(r)|} \sum_{y \in B_x(r)}f(y) \, .
\end{equation*}

