[Prop error-estimate-no-scale-sep of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $\mu \in C^1([0,\infty);\mathcal{P}(\mathcal{X}))$ be a solution to the full forward Kolmogorov equation (equation eq:full-forw-K of the paper) with corresponding coarse-grained dynamics $\hat{\mu}$ and let $\eta \in C^1([0,\infty); \mathcal{P}(\mathcal{Y}))$ be the solution to the effective dynamics (equation eq:eff-dyn-non-cg of the paper) with initial condition $\hat{\mu}_0,\eta_0 \in \mathcal{P}_+(\mathcal{Y})$ satisfying $\hat{\mu}_0(y), \eta_0(y) \geq c_0$ for some $c_0 > 0$ and all $y \in \mathcal{Y}$. Then, for any fixed $T > 0$ there exists a constant $C = C(L,|\mathcal{X}|,T,c_0)$ such that
    \begin{equation}
        \begin{split}
            \mathscr{H}_{\eta_t}\left(\dfrac{\hat{\mu}_t}{\eta_t}\right) &\leq 2\mathscr{H}_{\eta_0}\left(\dfrac{\hat{\mu}_0}{\eta_0}\right) + \dfrac{C}{\min_y(\alpha_{\gLSI}(\rho(\cdot |y), M^y))} \left[\mathscr{H}_\rho\left(\dfrac{\mu_0}{\rho}\right) - \mathscr{H}_\rho\left(\dfrac{\mu_t}{\rho}\right)\right]
        \end{split}
    \end{equation}
    for all $t \in [0,T]$. In particular, the implicit prefactor $\min_y(\alpha_{\gLSI}(\rho(\cdot |y), M^y))$ can be replaced by the explicit constant $\alpha > 0$ given in (equation eq:alpha of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 16 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] Suppose ${\bf (\wh{EP})} _{\leq , r_0, \gamma}$ holds with  $r_0>0$ and $\gamma>0.$ There is a constant $C=C(r_0, \gamma)\geq 1$ such that
    for every ball $B$ with radius $r_0$ and $\overline B\subsetneq \sX$,
    each open $U\subset  2^{-1}B$, $\xi\in U$ and $r\in (0, r_0)$,
\begin{equation}
\frac{\E_x[\wh \tau^B_{B_U(\xi,r)}]}{r^\gamma\P_x\big(\wh \tau^B_U>\wh \tau^B_{B_U(\xi,r)}\big)}
\geq C\left(\P_x\big(\wh \tau^B_U>\wh \tau^B_{B_U(\xi,r)}\big)+\frac{\E_x[\wh \tau^B_{B_U(\xi,r)}]}{r^\gamma}\wedge1\right) \quad\hbox{ for }x\in B_U(\xi, 3r/4).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] For all $\varepsilon>0$ there exist a positive constant $C>0$, such that, for all $n \in \mathbb{N}$ 
	\begin{equation*}
		\mathbb{E}_{0, 0}\left[ \sum_{i \in \mathrm{JRLC}(n)} \left(\frac{\tilde{\mu}^{(1)}_{i}}{n^{1/2}} \wedge 1\right) \left(\frac{\tilde{\mu}^{(2)}_{i}}{n^{1/2}} \wedge 1\right) \right]\le C n^{-1/2 + \varepsilon}.
	\end{equation*}

