[Theorem thm:sto of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For every smooth, compactly supported $\omega:\R\rightarrow\R$, $P{\geqslant1}$, $\eta>0$ and $c>0$ sufficiently small, we have
\begin{equs}
\E\big[ {\talloblong \omega\xi \talloblong}_{4}^P\big]^{1/P}\lesssim_{P} 1\quad\text{and}\quad\E\big[ {\talloblong \omega\xi \talloblong}_{4,c}^P\big]^{1/P}\lesssim_{P} 1\,,
\end{equs}
where we write $\omega\xi^\tau_{\eps,\mu}(t,s^\tau)\eqdef\omega(t)\xi^\tau_{\eps,\mu}(t,s^\tau)$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem pllt of arXiv:2411.03634, '\bf{Local limit theorems for random walks on a large discrete torus }'] For the random walk given  in  Definition (def-CRM of the paper), 
		assume    that $f$ is continuous   at $x_0$ and $f(x_0)>0$ for  some fixed  $x_0\in [0,\frac{L}{2W})^d$, and also  
		\begin{equation}

			f(x)\asymp  \big(\|x\|_2 \vee1 \big)^{-d-\alpha}, 
		\end{equation}
		where $\alpha \in  (0,2)$. 
		As $L\to \infty $ and $W\to\infty$, the following three types of local  limits  hold.
		\begin{itemize}
			\item [(I)](Subcritical regime)  When $\log W\ll n \ll (L/W)^{\alpha}$,  
			\begin{equation}
				p_n(x)=	f_{\alpha}(x,nW^{\alpha})(1+o(1)).
			\end{equation}

			\item[(II)] (Critical regime)
			When $ n \sim (L/W)^{\alpha}$ and $n\gg \log W$, 
			\begin{equation}
				p_n(x)	=\frac{1}{N}  {\theta}_{\alpha}\Big(\frac{x}{L},   \frac{n W^{\alpha}}{L^{\alpha}} \Big)\big(1+o(1)\big),
			\end{equation}	


			\item[(III)] (Supercritical regime) When  $n\gg (L/W)^{\alpha}$ and $n\gg \log L$,
			\begin{equation}	
				p_n(x)	=\frac{1}{N}\big(1+o(1)\big).
			\end{equation}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

