[Lemma 10 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] Every normal geodesic issuing from $e$ has the form
		\begin{equation}
			\gamma_{A,B}(t)=\exp\!\bigl(t(A+B)\bigr)\exp(-tA),
			\qquad A\in\lLie,\quad B\in\pLie.
		\end{equation}
		Its left-trivialized velocity is $\Ad_{e^{tA}}B$ and its speed is $|B|$. If $\gLie=\pLie+[\pLie,\pLie]$, every length minimizer has a normal lift.

[Theo 3 (\rm  Stone  local limit theorem for nonlattice random walk in cones) of arXiv:2603.26228, 'A local limit theorem for nonlattice multidimensional random walks in cones'] Assume  hypotheses  {\bf C},  {\bf M},  {\bf N} and {\bf A}. Let ${\bf B}_1\subset \mathbb R^s$ be a  bounded Borel  set  whose boundary is negligible with respect to the Lebesgue measure on $\mathbb R^s$   and $ {\bf y}_2\in G_2$ such that ${\bf B}:= {\bf B}_1\times \{{\bf y}_2\}\subset \mathcal C$.  Then,    as $n \to +\infty$,  uniformly in $ {\bf x} \in \cC$,
 \begin{equation*}
 \Big\vert n^{p/2+d/2}\bP(  \tau({\bf x})>n, {\bf x}  +S(n) \in   {\bf B})- \    \kappa_0 H_0  V({\bf x})\  \int_{\bf B}  u( {\bf y}/\sqrt{n})e^{-{\vert  {\bf y}_1\vert^2+ \vert{\bf y}_2\vert^2\over 2n}} {\rm d}{\bf y}_1\Big\vert\to 0 
\end{equation*}
where $\kappa_0$ and $H_0$ are defined in Proposition \ref{exitTime}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2605.28801, 'Microscopic Weak Selection Principle for the Logistic Branching Brownian Motion with selec'] Consider the function $\psi(x) := 6x^5-15x^4+10x^3$ and define a sequence of functions 
	$\{\psi_n\}_{n\geq 0}\subset C^2_b(\mathbb{R})$ such that 
	\[\psi_n(x): = \psi(0\vee(|x|-(n-1))\wedge1),\qquad n\in \mathbb{N}.\]
	For every $T>0$, the following holds
	\begin{itemize}
		\item[a)] For every $p\in\mathbb{N}$, there exists a constant $\tilde{C}:=\tilde{C}(p,T)$ such that
		\[\sup_K\mathbb{E}(\sup_{t\leq T}K^{-p}(N_t^K)^p)\leq \tilde{C}\sup_K [K^{-p}\mathbb{E}(N_0^K)^p].\]
		\item[b)] Let $\mu_t^K$ be a convergent subsequence of the sequence defined by \eqref{eq: defemp0}, then we have   
		\begin{equation}
			\lim_{n\to \infty}\sup_{K} \mathbb{E}\Big(\sup_{t\in[0,T]}\big<\mu^K_t,\psi_n\big>\Big)=0.
		\end{equation}
		\item[c)] Furthermore, if $u_t$ is the limit in distribution of $\mu_t^K$ in the space $D([0,T],M_F^v(\mathbb{R}))$ then
		\begin{equation}
			\lim_{n\to \infty} \mathbb{E}\Big(\sup_{t\in[0,T]} \big<\mu_t,\psi_n\big>\Big)=0.
		\end{equation}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2506.17094, 'Nonlinear random perturbations of Reaction Diffusion Equations'] For  every  $t>0$ and $\varphi \in\,L^2(0,t;H_0)$ and for every $x \in\,E$, there exists a unique mild solution $X^{t,x,\varphi}\in\,C([0,t];E)$ for equation \eqref{sbm2-bis}.	Namely
 \[X^{t,x,\varphi}(s)=S(s)x+\int_0^s e^{(s-r)A}F(X^{t,x,\varphi}(r))\,dr+\int_0^s  e^{(s-r)A}\sigma(X^{t,x,\varphi}(r),v_{t}(r,X^{t,x,\varphi}(r)))\,\varphi(r)\,dr,\]
 for every $s \in\,[0,t]$. Moreover,
 \begin{equation}
 |X^{t,x,\varphi}|_{C([0,t];E)}\leq c_{T,M}(1+|x|_E).
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:SW-length of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Fix $\varepsilon, \delta \in (0, 1)$, and $A, B$ with $B \in \ensuremath{\mathcal Y}_\delta^\blacktriangleleft(A)\setminus \{A\}$. We call $V$ an $\varepsilon$-\emph{nice} domain with respect to $A, B$ if there exists $\beta_0, v_0, \delta_0, c > 0$ such that uniformly over $\beta \geq \beta_0$ and $r \geq 1 + \varepsilon$, we have
		\begin{align}
			Z_V^{\mathsf{SW}}(A, B \mid |S| \geq r\lVertA - B\rVert_1) \leq ce^{-v_0\beta r\lVertA-B\rVert_1}Z_V^{\mathsf{SW}}(A, B)\,,\\
			Z_V^{\mathsf{SW}}(A, B \mid |\mathsf{Cpts}(S)| < 2\delta_0\lVertA-B\rVert_1) \leq ce^{-v_0\beta\lVertA-B\rVert_1}Z_V^{\mathsf{SW}}(A, B)\,.
		\end{align}

