			\frac{\mathscr Z(r)}{\mathscr Z(t)}
			\left(\frac12+\eta(r)\right)\d r.
		\end{equation}
		Moreover,
		\begin{equation}
			\lim_{t\uparrow\tau^*}
			\sup_{r\in[t,\tau^*]}
			\left|
			\frac{\mathscr Z(r)}{\mathscr Z(t)}-1
			\right|
			=0.
		\end{equation}

