[Proposition prop:global_hajek of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:hatngdef of the paper), let us write
\begin{equation}
    \widehat{\mathsf{N}}_G(x) = \mathsf{N}_G(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{E}(x).
\end{equation}
Then, for all $\zeta \in (0,1)$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P}\mleft[\mleft|\widehat{\mathsf{N}}_G(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G(X)\mright]\mright| > n^{\mathsf{v}-1.5+\zeta}\mright] \leq \exp\mleft(-cn^\zeta\mright).
\end{equation}
In particular, for all $\xi > 0$ we have
\begin{equation}
    \operatorname{Var}\mleft[\widehat{\mathsf{N}}_G(X)\mright] \lesssim n^{2\mathsf{v}-3+\xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_relation_pointandboundary of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d),
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d)>0$ such that 
	\begin{equation}
	M^{-\varsigma_d(N)}	\lesssim 	\frac{ \mathbb{P}^D\big(A\xleftrightarrow{\ge 0} x\big)}{\mathbb{P}^D\big(A\xleftrightarrow{\ge 0}  B(M)\big)}\cdot M^{(\frac{d}{2}-1)\boxdot (d-4)}	 \lesssim   M^{3\varsigma_d(M)}
	\end{equation}
for all $N\ge 1$ and $x\in \partial B(M)$ if either of the following two conditions holds:
\begin{enumerate}
	\item[(a)] $A\subset \widetilde{B}(N)$, $M\ge \ensuremath{C_{\ref*{const_relation_pointandboundary1}}}N^{( 1 \boxdot \frac{d-4}{2})+\varsigma_d(N)}$ and $D\subset  \widetilde{B}(N)\cup [\widetilde{B}(2M)]^c$;


	\item[(b)] $A\subset [\widetilde{B}(N)]^c$, $M\le \ensuremath{c_{\ref*{const_relation_pointandboundary2}}}N^{(1 \boxdot \frac{2}{d-4})-\varsigma_d(N)}$ and $D\subset  [\widetilde{B}(N)]^c \cup \widetilde{B}(\frac{1}{2}M)$.

	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_steinmethod_xmorethanu_gendif of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Fix  $x\geq u$ and $k\in \mathbb{N}$. Let the function $h$ in the ODE (equation equation_stein of the paper) be 
    \begin{align*}
        h(y):=\mathds{1}_{\{y> x\}}\frac{-2a(y)+b'(y)}{b(y)},\quad y\in \mathbb{R}\setminus \left\{y\in (x,\infty):b(y)=0 \right\}
    \end{align*} 
Then a solution $g_x: \mathbb{R}\setminus \brac{\left\{y\in(\ell,u)^\complement:a(y)=0 \right\}\cup\left\{y\in(\ell,u)\cup (x,\infty):b(y)=0 \right\}}\to\mathbb{R}$ exists and satisfies for every $y$ in its domain, 
\begin{align*}
     \left\vert  g(y) \right\rvert&\leq  \mathcal{V}_5(y):=\mathds{1}_{\{y>u\}} \frac{\left\vert -2a(y)+b'(y) \right\rvert}{\left\vert b(y) \right\rvert\left\vert 2a(y) \right\rvert }
    \end{align*}
and
\begin{align*}
    &\left\vert  g'(y) \right\rvert\\
    &\leq  \mathcal{V}_6(y):=\mathds{1}_{\{y>u\} } \brac{\abs{\frac{(1+b''(y))b(y)-(-2a(y)+b'(y))b'(y) }{b(y)^22a(y)}}+\abs{\frac{-2a(y)+b'(y)}{b(y)4a(y)^2} }}. 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:DPW_QD of arXiv:2609.02325, 'A Payne-Weinberger inequality\\for quantum dot Dirac operators'] Given $m\geqslant 0$ and  $\theta\in (-\frac{\pi}{2},\frac{\pi}{2})$, there exists a constant $C>0$ depending only on $m$ and $\theta$ such that
	\begin{equation}
		\sqrt{|\Omega|}\, \lambda_\Omega  \bigg (\theta, \frac{m}{\sqrt{|\Omega|}} \bigg)
		 - \sqrt{\pi}\, \lambda_\mathbb{D} \bigg (\theta, \dfrac{m}{\sqrt{\pi} }\bigg)
		 \leqslant C \left( \dfrac{|\partial\Omega|}{\sqrt{4\pi |\Omega|}}-1 \right)
	\end{equation}
for every bounded simply connected domain~$\Omega\subset \mathbb{R}^2$ with $C^2$~boundary. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Brown-eagleson theorem 7 of arXiv:2604.16002, 'Normal approximation for iterated inner functions'] Consider the following triangular array of real-valued random variables on a probability space $(\Omega, \cal F, \mathbb P)$:
		\begin{align}
		\begin{pmatrix}
 			X_{1,1} & 0 & 0 & \cdots \\
			X_{2,1} & X_{2,2} & 0 & \cdots \\
			X_{3,1} & X_{3,2} & X_{3,3} & \cdots \\
			\vdots & \vdots & \vdots & \ddots
		\end{pmatrix}
	\end{align}
		Let $\{\mathcal{F}_{N,n}: 0\leq n \leq N\}$ be a family of $\sigma$-algebras such that for each $N\geq 1$ fixed, 
		\begin{align}
			\cal F_{N,0} \subset \cal F_{N,1} \subset \cdots \subset \cal F_{N,N} \subset \cal F, 
		\end{align} 
		and for any $1\leq n\leq N$, 
		\begin{align} 
			X_{N,n} \text{ is $\cal F_{N,n}$-measurable}, \quad \E\big[ X_{N,n} | \cal F_{N,n-1}\big]=0.
		\end{align}
		Define
		$$
			V^2_N:= \sum_{n=1}^N \E\big[X_{N,n}^2| \cal F_{N,n-1}\big],\quad  m_N:= \max_{1\leq n\leq N} \E\big[X_{N,n}^2| \cal F_{N,n-1}\big].
		$$ 
		If the following three conditions are satisfied as $N\to \infty$: 
		\begin{itemize}
			\item [(C1)] $m_N \stackrel{p}{\longrightarrow} 0$;
			\item [(C2)] $V^2_N \stackrel{p}{\longrightarrow} \sigma^2$ (constant);
			\item [(C3)] For any $\varepsilon>0$, $$\sum_{n=1}^N \E[X_{N,n}^2 I\big(|X_{N,n}| \geq \varepsilon\big)| \cal F_{N,n-1}] \stackrel{p}{\longrightarrow}  0,$$
		\end{itemize}
		 then the $N$-th row sum of \eqref{eq-martingale-array} converges in law to $\cal N(0,\sigma^2)$ as $N\to \infty$: $$X_{N,1}+ \cdots + X_{N,n}\stackrel{d}{\longrightarrow} \cal N(0,\sigma^2).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

