[Corollary cor:ordinary-BE-kernel of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Let $K_{\mathrm{BE}}$ and $\pi_{\mathrm{BE}}$ be the transition kernel and the stationary distribution of the Bose--Einstein Markov chain on $[k]^n$. Then for all $x,y \in [k]^n$,
\begin{equation}
 K_{\mathrm{BE}}(x,y)
 =\frac{1}{\prod_{a=1}^k i_a(x)!}
 \prod_{a,b=1}^k
 \left(\frac1k\right)_{(m_{a,b}(x,y))}
\end{equation}
and
\begin{equation}
 \pi_{\mathrm{BE}}(x)
 =\frac{\prod_{a=1}^k i_a(x)!}
 {n!\binom{n+k-1}{k-1}}
 =\frac{\prod_{a=1}^k i_a(x)!}{(k)_{(n)}}.
\end{equation}

[Proposition 19 (Uniform-in-time first Malliavin derivative bounds) of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Let $p\in\left\{4,8\right\}$. Assume
Assumptions~\ref{ass:smooth}, \ref{ass:second-malliavin-uniform}(i),
\ref{ass:coeff-level-new}(i)(ii), and
\ref{ass:first-malliavin-uniform}. Then, there exists a constant
$C_p>0$ such that, for all $N\ge 1$, all $0\le s\le u$, and all
$i,j\in\left\{1,\dots,N\right\}$,
\begin{equation}

\E\left(
\norm{D_s^j X_u^{i,N}}^p
\right)^{1/p}
\le
C_p e^{-\kappa_p \left( u-s \right)/8}
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\frac{1}{N}\mathbf{1}_{\left\{ i\ne j \right\}}
\right).
\end{equation}
In particular,
\begin{equation}

\frac{1}{N}\sum_{i=1}^N
\E\left(
\norm{D_s^j X_u^{i,N}}^p
\right)^{1/p}
\le
\frac{C_p}{N} e^{-\kappa_p \left( u-s \right)/8}.
\end{equation}

[Theorem thrm:lump of arXiv:2511.01058, 'Limit profiles and cutoff for the Burnside process on Sylow double cosets'] Define \(T: S_{pk} \to \{k,\ldots 2k\}\) by
    \begin{equation}
        T(\sigma)=a \Longleftrightarrow |H\sigma H|=p^a. 
    \end{equation}
    Then the Sylow--Burnside kernel \(P\) lumps under \(T\) and the lumped transition kernel is given by
    \begin{equation}
        \overline{P}(a,b)=\sum_{y=0}^{2k-\max\{a,b\}}\binom{2k-a}{y} \left(\frac{p-1}{p}\right)^y  \frac{p^{a+b-2k}}{(p(k-y))!}f(b-y;k-y),
    \end{equation}
    where \(f(a;k)\) is the number of Sylow \(p\)-double cosets in \(S_{pk}\) of size \(p^a\). Furthermore, if \(Z = \sum_{a=k}^{2k}f(a;k)\) is the total number of Sylow \(p\)-double cosets, then the lumped stationary distribution is given by
    \begin{equation}
        \overline{\pi}(a) = \frac{f(a;k)}{Z}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 167 (Euler-generated parameter-field completion) of arXiv:2608.04993, '2608.04993'] Assume the hypotheses of \Cref{lem:trace-clock-Euler-sections} and suppose
also that $\cP$ is uniformly tight on
$\Omega=C_0([0,T];H)$.  The fixed-parameter classes admit compatible
completions
\begin{equation}
 \Phi^R\in\bigcap_{1\le q<\infty}
 \mathbb L_{\cP}^q(\mathscr B_R),
 \qquad R\in\mathbb N.
\end{equation}
Put
\[
 \varrho((s,y),(r,z)):=|s-r|^{1/2}+|y-z|.
\]
For every $q>m+2$ and every
$0<\delta<1-(m+2)/q$,
\begin{equation}
 \sup_{P\in\cP}E^P\left[
  \sup_{\substack{(s,y)\ne(r,z)\\|y|,|z|\le R}}
  \frac{\|\Phi^R(s,y)-\Phi^R(r,z)\|_\infty^q}
       {\varrho((s,y),(r,z))^{\delta q}}
 \right]<\infty.
\end{equation}

There are a total jointly Borel raw-causal field
\begin{equation}
 \Phi:\Omega\times\Delta_T\times\mathbb R^m\to\mathbb R^m
\end{equation}
and one sequence $(F_n)$ with the following properties.  Each $F_n$ is a
continuous finite-parameter interpolation field assembled from finitely many
finite-step raw Euler maps.  There is one Borel full-capacity set
$G_{\rm reg}$, independent of the radius, moment exponent, and parameters,
such that
\begin{equation}
 \Phi_{s,t}(x,y)=\Phi^R(x)(s,y)(t)
 \quad
 (x\in G_{\rm reg},\ |y|\le R,\ 0\le s\le t\le T),
\end{equation}
while the right-hand path is frozen before $s$.  In particular,
the field is locally jointly continuous in $(s,t,y)$ on $G_{\rm reg}$.
There is an increasing compact capacity core $(K_j^{\rm E})_{j\ge1}$ on
each member of which $(x,s,t,y)\mapsto\Phi_{s,t}(x,y)$ is jointly continuous
when the parameters range over compact sets.

[Proposition 84 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let $(\Omega,\FF,\PP)$  be a probability space and let $(X,Y)$ be a bivariate absolutely continuous random vector. Denote $f_{(X,Y)}:=\frac{\dd\PP_{(X,Y)}}{\dd \leb^2}$. Then $X$ and $Y$ are both absolutely continuous, 
\begin{equation} 
f_X(x)=\int f_{(X,Y)}(x,y)\leb(dy)\text{ for $\leb$-a.e. }x\in \mathbb{R}\text{ and } f_Y(y)=\int f_{(X,Y)}(x,y)\leb(dx)\text{ for $\leb$-a.e. }y\in \mathbb{R},
\end{equation}
 and $X$ is independent of $Y$ iff 
\begin{equation*}
f_{(X,Y)}(x,y)=f_X(x)f_Y(y) \text{ for $\leb^2$-a.e. $(x,y)\in \mathbb{R}^2$}.
\end{equation*}
When $X$ and $Y$ are independent, then, for all $g\in \mathcal{B}_{\mathbb{R}^2}/\mathcal{B}_{[-\infty,\infty]}$,
\begin{equation}
\PP[g(X,Y)]=\int\int g(x,y)f_X(x)f_Y(y)\leb(\dd x)\leb(\dd y),
\end{equation}
provided $\PP[g^-(X,Y)]\land \PP[g^+(X,Y)]<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop18 of arXiv:2609.02136, 'Gamma approximation and Poisson--Gaussian invariance principle on Poisson chaos'] Fix $q\geq1$ and $\nu>0$.  If
\noindent
\begin{align*}
 F=I_q^\eta(f)\in\mathcal{C}_q^\eta\cap L^4(\Omega),
 \quad
 G=I_q^W(f)\in\mathcal{C}_q^W,
 \quad{\rm and}\quad
 \mathbb{E}[F^2]=\mathbb{E}[G^2]=2\nu,
\end{align*}
then
\noindent
\begin{align}
    \left|\mathbb{E}[F^3]-\mathbb{E}[G^3]\right|
 \leq B_q\sqrt{2\nu\mathcal J_4(F)}
\end{align}
and
\begin{align}
\big|  \sqrt{\mathbb{E}[F^4]}-\sqrt{\mathbb{E}[G^4]} \big|
 \leq C_q\sqrt{\mathcal J_4(F)}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

