[Proposition 46 ({\cite[Theorem~6.2) of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] {zhan2019two}}]

Let $v_-, w_-, w_+, v_+ \in \BR$ with $v_- < w_- < w_+ < v_+$ be such that $0 \in [v_-, v_+]$. Let $(\eta_+,\eta_-)$ be a bichordal SLE$_4$ in $\BH$ with link pattern $\{\{w_+, v_+\}, \{w_-, v_-\}\}$. Then, there exists a universal constant $C \in (0,\infty)$ such that
\begin{equation*}
    \BP[\text{both } \eta_+ \text{ and } \eta_- \text{ exit } B_L(0)] \leq C L^{-4} G_1(w_-, w_+; v_-, v_+) \left(1 + C((v_+ - v_-) / L)^{5/6}\right)
\end{equation*}
for all $L > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:uniform-profile-tail of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:uniform-profile-tail}
We say that the random field satisfies \(({\rm PT})_p\) if, for every
\(a>0\),
\begin{equation}
 \limsup_{N\to\infty}\frac1N\log
 \sup_{x\in\mathbb S^{N-1}(1)}
 \mathbb P\{\left\lverth_N^J(x)\right\rvert\ge a\}
 \le-\frac{a^2}{2}.
\end{equation}
This asymptotic one-profile tail rate, rather than a moment-generating
function bound, is the exact probabilistic input used by the
sparse-profile upper bounds.

[Lem 24 of arXiv:2605.21638, 'Markov renewal theory for transfer operators and point processes on the line'] For every measurable function $F\colon \mathbf{N} \rightarrow \R$,
    \begin{equation}

        \int_{\mathbb{R}^n} F(\delta_{x_0} + \dots + \delta_{x_n}) \, \dd \mu_{n,\beta}^{x_0}(x_1, \dots, x_n) = \frac{1}{\E_{\zeta}[G_\beta(Z_n)]} \E_{\zeta,\beta} \left[ F\left(\sum_{i=0}^n \delta_{x_0+X_i} \right) G_\beta(Z_n) \right]
    \end{equation}

[Proposition 2 of arXiv:2604.21162, '2604.21162'] {\bf(Local weak-type Poincar\'e inequality)} Under {\bf Assumption (H1)}, there exist constants
$C_1>0$, $\kappa_0>1$ and $R_0\ge 2$ so that
for all $y\in \Z^d$, $f:\Z^d \to \R$ and $R\ge R_0$,
\begin{equation}
\int_{B_R(y)}\Big(f(x)-
\oint_{B_R(y)}f\,d\mu
\Big)^2\,\mu(dx)\le\frac{ C_1R^2}{\log R}\mathscr{E}_{B_{\kappa_0R}(y)}^{\w}(f,f);
\end{equation}
moreover, there is a constant $C_2>0$ such that for all $y\in \Z^d$, $f:\Z^d\to \R$ and $R\ge 1$,
\begin{equation}
\int_{B_R(y)}\Big(f(x)-
\oint_{B_R(y)}f\,d\mu
\Big)^2\,\mu(dx)\le C_2R^2\mathscr{E}_{B_{R}(y)}^{\w}(f,f).
\end{equation}

