[Definition def:Y-infty of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] \begin{itemize}
    \item The number of children of the root $\varphi$ in $\mathcal Y_\infty$ is distributed as the variable $D_{l}$, where we define $D_{l}$ inductively as follows. $D_{1}$ has the same distribution as $D_{(s_0,s_1)}$, and inductively, for any $2\leq j \leq l$, having defined $D_{j-1}$, 
    \begin{align*}
        D_{j}\stackrel{d}{=}\sum_{i=1}^{D_{j-1}} D^{(i)}_{(s_{j-2},s_{j-1},s_j)},
    \end{align*}
    the summands on the RHS above being independent of the upper limit of the sum.
    \item For any vertex $v\neq \varphi$ in $\mathcal Y_\infty$, the number of offspring of $v$ in $D$ has the distribution $d_{l}$, where $d_{l}$ is defined inductively as follows. $d_{1}\stackrel{d}{=}D_{(s_{l-1},s_{0},s_1)}$, and inductively for $2\leq j \leq l$, 
    \begin{align*}
        d_{j}\stackrel{d}{=}\sum_{i=1}^{d_{j-1}}D^{(i)}_{(s_{j-2},s_{j-1},s_j)},\addtocounter{equation}{1}\tag{\theequation} 
    \end{align*}
    the summands on the RHS above being independent of the upper limit of the sum.
    \end{itemize}

