[Corollary 9 (Boundary Parisian persistence) of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] Let \(F\in\mathcal K_0^+\), let \(\bm X\) satisfy
Assumptions~\ref{D1}--\ref{D3} on \([0,T]\), and define
\[
  \rho_u=
  \begin{cases}
    u^{-2/\alpha},&\alpha<\beta,\\
    u^{-2/\beta},&\alpha\ge\beta,
  \end{cases}
  \qquad
  E_u=[0,T-\rho_u\max F].
\]
Then, as \(u\to\infty\),
\begin{enumerate}[(a)]
  \item If \(\alpha<\beta\), then
  \begin{equation}

    \pk{
      \exists t\in E_u:\
      \bm X(t+u^{-2/\alpha}s)>u\bm b
      \text{ for every }s\in F
    }
    \sim
    \mathcal H_F^{\mathrm{Par,bd}}
    \Gamma(1/\beta+1)\tau_{\bm w}^{-1/\beta}
    u^{2/\alpha-2/\beta-|I|}\varphi_\Sigma(u\bb).
  \end{equation}

  \item If \(\alpha=\beta\), then
  \begin{equation}

    \pk{
      \exists t\in E_u:\
      \bm X(t+u^{-2/\beta}s)>u\bm b
      \text{ for every }s\in F
    }
    \sim
    \mathcal P_F^{\mathrm{Par,bd}}
    u^{-|I|}\varphi_\Sigma(u\bb).
  \end{equation}

  \item If \(\alpha>\beta\), then
  \begin{equation}

    \pk{
      \exists t\in E_u:\
      \bm X(t+u^{-2/\beta}s)>u\bm b
      \text{ for every }s\in F
    }
    \sim
    \mathcal C_F^{\mathrm{Par,bd}}
    u^{-|I|}\varphi_\Sigma(u\bb).
  \end{equation}
\end{enumerate}
Here
\begin{align*}
  \mathcal H_F^{\mathrm{Par,bd}}
  &=\mathcal H_{\Pi;F,0,\alpha,V_{I,I},\Sigma,\bm b},\\
  \mathcal P_F^{\mathrm{Par,bd}}
  &=\mathcal P_{\Pi;F,0,\alpha,V_{I,I},\bm d_I,\Sigma,\bm b},\\
  \mathcal C_F^{\mathrm{Par,bd}}
  &=\mathcal C_{\Pi;F,0,\bm d,\Sigma,\bm b},
  \qquad \bm d(t)=t^\beta A\bm w,
\end{align*}
and the constants are finite and positive in their respective regimes.  The
first successful start time has the corresponding conditional limits from
Theorem~\ref{thm:exceedance_times}, with the truncated constants carrying the
same fixed footprint \(F\).

[Lemma 4 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] For every $\alpha, \beta,\gamma >0$, there exists a constant $c>0$ such that the following holds for every $\delta < 1/2$.
	Consider $x_0,y \in \cD(\delta)$ with $\Vert x-y \Vert \leq (4/5) r_\delta$ such that $x_0$ and $y$ lie on different sides of some barrier $B_i$ with $i\geq 1$.
	Define
	\begin{align}
		\cE_1 \de \inf\{t\geq 0: s_i(t) \neq s_i(0) \} \quad \text{ and }\quad \cE_2 \de \inf\{t\geq \cE_1: s_i(t)\neq  s_i(\cE_1)\} - \cE_1 \nonumber
	\end{align}
	to be the first two increments between times for which $s_i$ changes value.
	Then,
	\begin{align}
		\bbP\bigl( \cE_1 <  \alpha r_\delta, \,  \cE_2 >  \beta r_\delta, \,  \Vert   W_t - (t/ r_\delta^2) (y- x_0) \Vert \leq   \gamma r_\delta,\, \forall t\leq  r_\delta^2 \bigr) \geq c  r_\delta \lambda_{\min}.  
