[Lemma lem-purely discontinuous-from the proof of main result of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that $\phi \inU$ and a function   $g\colon \mathbb{R} \to \mathbb{R}_+$
satisfies Condition (condition-g function of the paper). Let $C=C(\overline{u})$  be  the set defined by 	equality (equation eqn-C_set of the paper).
Then for every $t \in C$,
\begin{equation}

\overline{\mathbb{E}} \left[\sum_{s\in [0,t]} g(\Delta \langle \overline{u}(s), \phi\rangle)-\int_0^t\int_{Y} g\left( \ip{F(s,\overline{u}(s),y)}{\phi}{H}\right)\, \nu(\mathrm{d} y) \, \mathrm{d}s \right]=0.
\end{equation}

[Lemma expectations of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $(X_t)$ solve the Auffinger--Chen SDE with $X_0=0$ and set $M_t:=\partial_x\Phi_\zeta(t,X_t)$.
		Let $0\le s<t\le 1$.
		\begin{enumerate}[label=(\roman*)]
			\item
			\begin{equation}
				\mathbb{E}[(X_t-X_s)M_s]
				=\mathbb{E}[M_s^2]\int_s^t\zeta([0,u])\,\xi''(u)\,\mathrm{d} u.
			\end{equation}

			\item
			\begin{equation}
				\mathbb{E}[(M_t-M_s)\,X_s]=0.
			\end{equation}

			\item
			\begin{equation}
				\mathbb{E}[X_t M_t]
				=\xi'(t)-\int_{[0,1]}\xi'\bigl(\min(t,u)\bigr)\,\mathbb{E}[M_u^2]\;\zeta(\mathrm{d} u).
			\end{equation}

			Consequently, for all $s,t\in [0,1]$,
			\begin{equation}
				\mathbb{E}[X_s\, M_t]
				=\begin{cases}
					\mathbb{E}[X_s M_s], & s\le t,\\[4pt]
					\mathbb{E}[X_t M_t]+\mathbb{E}[M_t^2]\displaystyle\int_t^s\zeta([0,u])\,\xi''(u)\,\mathrm{d} u, & s\ge t.
				\end{cases}
			\end{equation}

			\item Suppose that $\mathbb{E}[\partial_x\Phi_\zeta(t,X_t)^2]=t$  for $\zeta$-a.e. $t\in [0,1]$. Suppose $\zeta((s,t))=0$ and $s,t\in\mathrm{supp}(\zeta)$. Then
			\begin{equation}
				\mathbb{E}[(M_t-M_s)(X_t-X_s)]
				=\bigl(\xi'(t)-\xi'(s)\bigr)\int_s^1\zeta([0,u])\,\mathrm{d} u.
			\end{equation}
		\end{enumerate}

[Proposition prop_concentration of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Let~$(S,\mathcal{S})$ be a measurable space and~$n \in \N$. Let~$\sigma$ be a probability measure on~$(S,\mathcal{S})$ and~$\p$ be the probability on~$(S^n,\mathcal{S}^n)$ given by the {$n$-fold} product measure of~$\sigma$. Set $X_1, \dots, X_n$ to be independent random elements taking values in~$S$ and let $X_i'$ be an independent copy of $X_i$. Set~$h: S^n \to\R$ to be a measurable function on $(S^n,\mathcal{S}^n,\p)$ and fix
    \[Z:=h(X_1,\dots,X_n), \ \ \text{and} \ \ Z^{(i)}:=h(X_1,\dots,X_{i-1},X_{i}',X_{i+1},\dots,X_n).\]
    Assume that there exist~$\kappa > 0$ and measurable sets~$E_1,\ldots, E_n \in \mathcal{S}^n$ such that, $\p$-a.s., for each $i \in \{1,\ldots,n\}$,
    \begin{equation}            Z^{(i)}-Z \le \kappa \cdot \mathbbm{1}_{E_i}.
    \end{equation}
	Then, 
        \begin{equation} 
            \mathrm{Var}Z \leq \kappa^2 \sum_{i=1}^n\p(E_i).
        \end{equation}
    Furthermore, for any~$\alpha > 0$ such that $\E[e^{\alpha Z}]< +\infty$, one has
    \begin{equation} 
       \E\left[\exp\left\{\alpha (\E[Z]-Z)\right\} \right] \le \E \left[ \exp \left\{ 2 \alpha^2 \kappa^2\sum_{i=1}^n \mathbbm{1}_{E_i}\right\} \right] 
    \end{equation}
    and, if~$\alpha > 0$ is such that $\E[e^{\alpha Z}]< +\infty$, then for all $\lambda \in(0,\alpha)$,
    \begin{equation} 
        \E\left[\exp\left\{\lambda (Z-\E[Z])\right\} \right] \le \E \left[ \exp \left\{ 2\lambda^2 \kappa^2 e^{\alpha\kappa} \sum_{i=1}^n \mathbbm{1}_{E_i}\right\} \right].
    \end{equation}

