body:
[Prop 40 (Finite-window Kearns--Saul inequality) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] {Let $p\in(0,1/2]$ and $a>0$. The inequality}
\begin{align}
    \E\left[e^{\lambda(\berv-p)}\right]
    \leq e^{A\lambda^2}
    \qquad\text{for all }|\lambda|\leq\frac1a

\end{align}
{holds with $A=A_p(a)$ and with no smaller constant, where}
\begin{align}
    A_p(a)
    &=
    \begin{cases}
        \displaystyle
        \frac{1-2p}
        {\displaystyle4\log\left(\frac{1-p}{p}\right)},
        & \displaystyle2\log\left(\frac{1-p}{p}\right)\leq\frac{1}{a},\\[8mm]
        \displaystyle
        a^2\log\left(
            p\,e^{(1-p)/a}
            +(1-p)\,e^{-p/a}
        \right),
        & \displaystyle 2\log\left(\frac{1-p}{p}\right)>\frac{1}{a}.
    \end{cases}

\end{align}
{For $p<1/2$, \eqref{eqn:kswindow} at $A=A_p(a)$ is an equality at exactly one nonzero $\lambda$ of the window: $\lambda=2\log\left((1-p)/p\right)$ on the first branch, $\lambda=1/a$ on the second. At $p=1/2$ the first branch is read by \eqref{eqn:lhopital} as $A_{1/2}(a)=1/8$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 (Strichartz estimates) of arXiv:2609.03558, 'Local well-posedness of the higher-order nonlinear Schr\"{o}dinger equation on the half-li'] Let $s\ge 0$, $(\mu,r)$ be higher-order Schrödinger admissible, and $\psi_0\in H_t^{\frac{s+1}{3}}(\mathbb{R})$, $\psi_1\in H_t^{\frac{s}{3}}(\mathbb{R})$ satisfy \eqref{supp-cond}.  Then, the solution of \eqref{HNLSreduced} represented by the formula \eqref{sol_for_reduced} satisfies 
\begin{equation}
    \left\|v\right\|_{L^\mu_t((0, T); H^{s,r}_x(\mathbb{R}_+))}\lesssim (1+e^{cT'}(T')^{\frac12+\frac 1 \mu})\sum_{b=0}^1\|\psi_b\|_{H_t^{\frac{s+1-b}{3}}},
\end{equation} 
where $c$ and the constant of the inequality may depend only on the fixed parameters such as $s,\alpha,\beta$, and $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 3 of arXiv:2606.17472, '2606.17472'] Let $(A_t, t\ge 0)$ be a positive continuous additive functional of $X$, and let $\nu$ be its Revuz measure. Assume that $\nu$ is a finite measure and has compact support. Then there exists a martingale $M^\nu$ such that
\begin{align}

  \int_\R h(X_t-y)\nu(dy)=\int_\R h(x-y)\nu(dy)+M_t^\nu +A_t,\qquad t\geq 0.
\end{align}
In particular, it holds that
\begin{align}

\varphi_B(X_t)=\varphi_B(x)+M_t^{\mu_B}+\int_B L_t^y \mu_B(dy),\qquad t\geq 0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 59 (All-order singular lattice profiles) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $\Gamma=\mathbb Z^D$, $m\ge2$, and
\[
 \frac{(m-1)D}{2m}<\sigma\le\frac D2,
 \qquad c_x=\langle x\rangle^{-\sigma}.
\]
Put
\[
 \beta_m=m\left(\frac D2-\sigma\right),\qquad
 \gamma_m=2m\sigma-(m-1)D,
\]
and
\begin{equation}

 \Omega_{m,\sigma}(R)=
 \begin{cases}
  R^{\beta_m},&\sigma<D/2,\\
  \log(e+R)^{m/2},&\sigma=D/2.
 \end{cases}
\end{equation}
For $R_+=\max\{L,Q\}$ and $R_-=\min\{L,Q\}$,
\begin{equation}

 \Prof_{m,r}(K_{m,N}^{L,Q}(c))
 \le C\Omega_{m,\sigma}(R_+)R_-^{D/r},
 \qquad2\le r\le\infty.
\end{equation}
If $N\ge M$ and $\sigma<D/2$, then
\begin{align}

 &\Prof_{m,r}(K_{m,N}^{L,Q}(c)-K_{m,M}^{L,Q}(c))\notag\\
 &\quad\le C\Omega_{m,\sigma}(R_+)R_-^{D/r}
 \min\{1,(R_+/M)^{\gamma_m/2}\}.
\end{align}
At $\sigma=D/2$, for every $0<\vartheta<D$ the right side is replaced by
\begin{equation}

 C_\vartheta\Omega_{m,D/2}(R_+)R_-^{D/r}
 \min\{1,(R_+/M)^{\vartheta/2}\}.
\end{equation}

[Theorem thm:sep of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] Let $t: C\to\mathbb P^1$ be cyclic of degree $n$ with branch data $(l_1,\dots,l_r)$, the point at infinity included when it is a branch point. Then there is a birational map from $C$ to a curve $v^n=h(u)$ with $k(u)=k(t)$ and $h\in k[u]$ separable if and only if there is $c\in(\mathbb Z/n\mathbb Z)^\times$ such that

\begin{equation}
c\,l_j\equiv 1\pmod n\quad\text{for every $j$ with at most one exception.}
\end{equation}

[Definizione 14 (Composition law) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let us consider two stochastic transformations $T_1=(\Phi_1, B_1, \eta_1, h_1) \in S_m(M,M')$ and $ T_2=(\Phi_2, B_2, \eta_2, h_2)\in S_m(M',M'')$. We define $ T_2\circ T_1$ as the unique transformation corresponding to the composition $F_{T_2}\circ F_{T_1}$ of the associated isomorphisms, i.e. \begin{equation*}
 T_2 \circ T_1 := \big( \Phi_2 \circ \Phi_1, \ (B_2 \circ \Phi_1)  B_1, \ (\eta_2 \circ f_1)  \eta_1,\ \sqrt{\eta_1}B_1^{-1}( h_2 \circ \Phi_1) + h_1 \big) \in S_m(M,M''),
 \end{equation*}
 where $\Phi_2 \circ \Phi_1=(\tilde{\Phi}_2\circ \tilde{\Phi}_1,f_2\circ f_1).$
 In the same way, we define $\ T_1^{-1}$ as the unique transformation corresponding to the inverse isomorphism $\ F_{T_1}^{-1}$, i.e.
 \begin{equation*}
        T_1^{-1}:=( \Phi_1^{-1}, \ (B_1 \circ \Phi_1^{-1})^{-1}, \ (\eta_1 \circ f_1^{-1})^{-1}, - \frac{1}{\sqrt{\eta_1}} B_1  h_1 \circ \Phi_1^{-1}) \in S_m(M',M).
    \end{equation*}

[Lemma lem:comparison_of_fields of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Fix $b \in (0,a/100)$ deterministic and depending only on $a$.  Suppose that we have the setup described above and let $\hat{\Psi}_1$ denote the GFF on $\BD$ with boundary conditions given by $b_j$ on the counterclockwise arc of $\partial \BD$ from $\hat{x}_j$ to $\hat{x}_{j+1}$ for all $j \in \{1,2,3,4\}$.  Let $\mathcal{Z}_{\varepsilon}$ denote the Radon--Nikodym derivative of the conditional law of $\tilde{\Psi}_1$ restricted to $\BD \setminus \bigcup_{j=1}^4 \overline{B_{\varepsilon^b}(y_j)}$ with respect to the conditional law of $\hat{\Psi}_1$ restricted to $\BD \setminus \bigcup_{j=1}^4 \overline{B_{\varepsilon^b}(y_j)}$,  in both cases given the boundary conditions of $\tilde\Psi_1$ (in particular,  the points $\hat x_j , y_j$ and the values $b_j$).  Then,  for all $p>0$,  we have that
\begin{align*}
\BE[\mathcal{Z}_{\varepsilon}^p ] \to 1 \quad \text{as} \quad \varepsilon \to 0.
\end{align*}

[Lemma lemma_Ato_x_boundary of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $3\le d\le 5$, there exists $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}>0$ such that for any $n\ge 1$, $A\subset \widetilde{B}(\ensuremath{C_{\ref*{const_lemma_Ato_x_boundary1}}}^{-1}n)$, $D\subset \widetilde{B}(\ensuremath{C_{\ref*{const_lemma_Ato_x_boundary1}}}^{-1}n)\cup [\widetilde{B}(\ensuremath{C_{\ref*{const_lemma_Ato_x_boundary1}}}n)]^c$, $x\in B(2n)\setminus B(\frac{1}{2}n)$ and $a \in [4,\frac{1}{2}\ensuremath{C_{\ref*{const_lemma_Ato_x_boundary1}}}]$, 
	\begin{equation}
		\mathbb{P}^D\big( A\xleftrightarrow{\ge 0 } x,\partial B(a n)\big)\lesssim (an)^{-\frac{d}{2}+1}\mathbb{P}^D\big( A\xleftrightarrow{\ge 0}  \partial B(n)\big).
	\end{equation}

