body:
[Proposition prop:lb col intersections of arXiv:2509.02432, 'A threshold for online balancing of sparse i.i.d. vectors'] The following two events each hold with $\calE_{q-1}$--conditional probability of at least $1-\frac{1}{\sqrt{n}}$:
\begin{align*}
\calE_a:=&\big\{
\mbox{For at least $s/2$ indices $i\in I^{(\ell)}$,
$a_{ij}=0$ for all $k<j\leq k_q$}
\big\}\;\cap\\
&\big\{
\mbox{For at least $s/2$ indices $i\in I^{(r)}$,
$a_{ij}=0$ for all $k<j\leq k_q$}
\big\},
\end{align*}
and 
\begin{align*}
\calE_b:=\Big\{
&\text{For at least $\frac{1}{100}\Big(\frac{s}{n}\Big)^2(k_q-k)$ indices $k<j\leq k_q$,}\\
&\mbox{$|\mathrm{supp}({\rm col}_j(A))\cap I^{(\ell)}|=
|\mathrm{supp}({\rm col}_j(A))\cap I^{(r)}|=1$, and}\\
&\mbox{$\big( \mathrm{supp}({\rm col}_j(A)) \cap (I^{(\ell)} \cup I^{(r)})\big)\cap \bigcup\limits_{t\neq j,\,k<t\leq k_q}\mathrm{supp}({\rm col}_t(A)) = \emptyset$}
\Big\}.
\end{align*}

[Lemma Xn T estimates of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let the conditions in Proposition (Proposition-(q u) of the paper) hold and let $\theta\in\left(\frac{d}{2}+p,{s-\max \{3\zeta,1\}}\right)$. Then ${\mathbb P}\text{-}{\rm a.s.}$ the following properties hold:
		\begin{enumerate}[label={\bf (\arabic*)},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item  There is a function $\widehat K: [0,\infty)\times [0,\infty)\to (0,\infty)$, increasing in both variables, such that  for any $R\ge1$ and $T>0$,
			\begin{align}
				\sup_{n\ge1}\mathbb E\Big[\sup_{t\in[0,T]}\|X_n^{(R)}(t)\|^2_{\mathbb H^s}\Big|\mathcal F_0\Big] 
				\leq \widehat K(T,2R+\|\Xi\|_{{\mathbb W}^{p,\infty}})(1+\|\Xi\|_{\mathbb H^s}^2). 
			\end{align} 
			\item   Let
			$$\tau_N^{n,m}(R) \triangleq  N\land \inf\big\{t\ge 0: \|X_n^{(R)}(t)\|_{\mathbb H^s}\lor\|X_m^{(R)}(t)\|_{\mathbb H^s}\ge N\big\},\quad n,m\ge 1, \ N\ge1.$$
			Then 
			\begin{equation} 
				\lim_{n\rightarrow\infty}\sup_{m\ge n}
				\mathbb E\left[\sup_{t\in[0,\tau_N^{n,m}(R)]} \|X_n^{(R)}(t)-X_m^{(R)}(t)\|^2_{\mathbb H^\theta}\bigg|\mathcal F_0\right]=0,\quad N>0.
			\end{equation}

			\item  There exists an $\mathcal{F}_t$-progressively measurable $\mathbb H^s$-valued process $X^{(R)}=(X^{(R)}(t))_{t\ge 0}$ satisfying 
			\begin{equation}
				\mathbb E\Big[\sup_{t\in [0,T]} \|X^{(R)}(t)\|_{\mathbb H^s}^2\Big|\mathcal F_0\Big]\le \widehat K(T,2R+\|\Xi\|_{{\mathbb W}^{p,\infty}})(1+\|\Xi\|^2_{\mathbb H^s}),\quad T>0,
			\end{equation} 
			such that for some subsequence of $\{X_n^{(R)}\}_{n\ge1}$ $($still denoted by $\{X_n^{(R)}\}_{n\ge1}$ for simplicity$)$ and for all $s'\in[\theta,s)$,
			\begin{equation}
				\lim_{n\to\infty}\sup_{t\in[0,T]}\|X_n^{(R)}(t)-X^{(R)}(t)\|_{\mathbb H^{s'}}=0\quad \text{and}\quad  X_n^{(R)}\xrightarrow[]{n\to \infty}X^{(R)} \  {\rm in}\ D([0,T];\mathbb H^{s'}),\quad T>0
				\quad {\mathbb P}\text{-}{\rm a.s.}
			\end{equation}

		\end{enumerate}

[Teo T: Survival of arXiv:2606.10165, 'The frog model with death and drift on free products of complete graphs'] Let $\beta = \frac{1-\alpha}{\Delta-1}$ and assume $m \geq 2$ and $d \geq 2$ are fixed integers. We define the functions

{\allowdisplaybreaks
\begin{equation}

\begin{aligned}
\phi(r)&= -d(m-1)r^2 + 2d(m-1)r,\\[4pt] 
A(\alpha, p) &= 
\frac{
1 - \beta p (m-2)-\sqrt{[1 - \beta p (m-2)]^2 - 4 \alpha \beta p^2 d (m-1)
}}{2 \beta p d (m-1)},\\[10pt]
\gamma(\alpha, p) &= 1 - \beta p \, [d (m-1) A(\alpha, p) + m - 3],\\[10pt]
\mathscr{Q}(\alpha, p) &= -\alpha p \, [\gamma(\alpha, p) + \beta p (m-2)],\\[10pt]
\mathscr{R}(\alpha, p) &= \gamma(\alpha, p) \, [1 - \beta p (d-1) (m-1) A(\alpha, p)] - \beta p^2 (\alpha + \beta) (m-2),\\[10pt]
\mathscr{S}(\alpha, p) &= -\beta p \, [\gamma(\alpha, p) + \beta p (m-2)],\\[10pt]
B(\alpha, p) &= \frac{-\mathscr{R}(\alpha, p) + \sqrt{\mathscr{R}(\alpha, p)^2-4 \, \mathscr{Q}(\alpha, p) \, \mathscr{S}(\alpha, p)}}{2 \, \mathscr{Q}(\alpha, p)}.
\end{aligned}
\end{equation}}

Then, \(\FM{\mathbb{D}_{m,d}}{\alpha,p}\) survives with positive probability for  $(\alpha, p)$ such that $\phi(B(\alpha, p))> 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:71 of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] Let $(\mu,B_\mu)$ be in Lemma~(LM71 of the paper).  Then $({\mathscr E}^{\mu},{\mathscr F}^{\mu})$ is a quasi-regular Dirichlet form on $L^2(\overline\Omega)$ such that
\begin{equation}
(\mathbf{D}, H^{1}_{0}(\Omega))\preceq ({\mathscr E}^{\mu},{\mathscr F}^{\mu})\preceq (\mathbf{D},\tilde{H}^{1}(\Omega)).
\end{equation}

[Lemma den1 of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Let $x\in \mathbb{R}$, $\gamma > 0$ and $n\in \mathbb{N}$. Let $q_n $ and $m_n\left(x\right)$ be as in our standard notation (equation standardnotation of the paper). Then, 
\begin{equation}
    \lim_{n\to\infty} \left(q_n^{m_n\left(z\right)};q_n\right)_\infty = \exp\Big(-\tfrac{1}{\gamma} e^{-\gamma z}\Big).

\end{equation}

[Definition eq:def-ftb of arXiv:2608.23554, 'Provably adaptive sampling with uniform and remasking \\ discrete diffusion models'] Let \(t \geq 0\) and \(b \in \cV\). Define \(\cF: \bR_{\geq 0} \times \cV \to [0, 1]\) as follows:
    \begin{equation*}
    \cF(t, b) \coloneqq \frac{\mathrm{d}}{\mathrm{d} t} \Pr(X_t^i = b) + \Pr(X_t^i = b) = \sum_{a \in \cV} \cQ(a, b) \Pr(X_t^i = a).
    \end{equation*}

[Prop 10 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that the process $X=(X_t)_{t\in [0,T]}$ satisfies Assumption \ref{a1} (i), let $q'\geq \max(Hd,1)$ and $\gamma<\frac{d}{q'}$. Then for any $0 < u < v\leq T$ and any $n \geq 1$, we have
		\begin{multline}
			\int_{[u, v]^n} \Big(\int_{(\mathbb{R}^{d})^n}  \prod_{k=1}^n\psi_\gamma(\Vert \xi_k\Vert)^{q'}\Big\lvert \mathbb{E} \exp \Big( i \sum_{j = 1}^n \langle \xi_j, X_{t_j}\rangle \Big) \Big\rvert^{q'} d\xi\Big)^{\frac{1}{q'}} dt  \\
			\leq c_7^n n^{\left(H\theta  + \frac{Hd}{q'}\right)n}(v-u)^{\left(1-\frac{Hd}{q'}\right)n}[\log(e+(v-u))]^{2 n d}
		\end{multline} 
		with a constant $c_7 > 0$ depending only on $T$, $d$, $\gamma$, $c_0$, $H$ and $q'$. (Proof in the paper; no proof environment follows the statement in the TeX.)

