[Corollary cor:no-macro-contours of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] For sufficiently large $\beta$, and $h$ such that ${\widehat\pi}_\infty(\phi_o\geq h) \leq (1/\log L)^2$, suppose $F \subset V \subset \mathbb Z^2$ and
    \begin{equation}
        |F| \leq \Big(\frac{3\beta}{{\widehat\pi}_\infty(\phi_o > h)}\Big)^2\,.
    \end{equation}
    Then, under the measure $\pi^{h}_{V;F}$, there are no \texttt{large} disagreement polymers in $V$ except with probability $O(L^{-10})$.

[Proposition proposition-connetion-BW-RWRE of arXiv:2507.19222, 'Convergence of the KMP model to the KPZ equation'] Assume that, at discrete-time $n_{0}\in \mathbb{Z}$, we have $\eta(n_{0},x)+\eta(n_{0},x+1)=\mathsf{p}_{n_{0}}(x)$ for all $x\in\mathbb{Z}$. 
		Then, for all $n\in \mathbb{Z}$ such that $n\geqslant n_{0}$, we have 
		\begin{equation}
        \begin{split}
			&\eta(n,x)
			=\mathsf{p}_{n-1}(x-1)B_{n-1,x-1}\quad \text{and}\quad 
		\eta(n,x+1)
		=\mathsf{p}_{n-1}(x+1)\left(1-B_{n-1,x+1}\right)\,.
        \end{split}
		\end{equation}

