[Lemma lem:gamma-square-ibp-A of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] For $t\in(0,1)$,
\begin{equation}

\begin{aligned}
&\frac{\beta}{2}(1-t)^{-1/2}\,\mathop{{}\mathbb{E}}\,\operatorname{tr}_{N}\!\bigl[\chi_k^2\,(A\otimes I_k)\,R\,K_k\,R\bigr]
\\&\qquad=
\beta^2\,\mathop{{}\mathbb{E}}\,\operatorname{tr}_k\!\Bigl[(\operatorname{tr}_n\otimes\id)[\chi_k R]\;(\operatorname{tr}_n\otimes\id)[\chi_k\,R\,K_k\,R]\Bigr]
+\frac{\beta^2}{n}\,\mathop{{}\mathbb{E}}\,\operatorname{tr}_{N}\!\bigl[(\mathsf T\otimes\id)[\chi_k R]\;\chi_k\,R\,K_k\,R\bigr]
+\mathrm{Err}_{A,\chi}(t),
\end{aligned}
\end{equation}
where
\begin{equation}

\mathrm{Err}_{A,\chi}(t)
:=
\frac{\beta}{2}(1-t)^{-1/2}\cdot\frac{1}{n^2}\sum_{i,j=1}^{n}
\mathop{{}\mathbb{E}}\left[
\frac{\partial (\chi_k^2)}{\partial A_{ij}}\;
\operatorname{tr}_{N}\!\bigl[(E_{ij}\otimes I_k)\,R\,K_k\,R\bigr]
\right].
\end{equation}

