[Corollary corollary_compare_boundtoset of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] (1) For any $d\ge 3$, there exists a constant $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d)>0$ such that for any $N\ge 1$, $A\subset \widetilde{B}(N)$, $M_2\ge M_1 \ge \ensuremath{C_{\ref*{const_compare_boundtoset1}}}N^{(1 \boxdot \frac{d-4}{2})+\varsigma_d(N)}$ and $D\subset  \widetilde{B}(N)\cup [\widetilde{B}(2M_2]^c$, 
	\begin{equation}
M_2^{-4\varsigma_d(M_2)}   \lesssim	\frac{\mathbb{P}^D\big(A\xleftrightarrow{\ge 0} \partial B(M_1)\big)}{\mathbb{P}^D\big(A\xleftrightarrow{\ge 0} \partial B(M_2)\big)}\cdot \big(\frac{M_1}{M_2}\big)^{(\frac{d}{2}-1)\boxdot 2}\lesssim  M_2^{4\varsigma_d(M_2)}.
\end{equation}

	(2) For any $d\ge 3$, there exists a constant $
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d)>0$ such that for any $N\ge 1$, $A\subset [\widetilde{B}(N)]^c$, $M_1\le M_2\le  \ensuremath{c_{\ref*{const_compare_boundtoset2}}}N^{(1\boxdot \frac{2}{d-4})-\varsigma_d(N)}$ and $D\subset  [\widetilde{B}(N)]^c \cup \widetilde{B}(\frac{1}{2}M_1)$, 
		\begin{equation}
M_2^{-4\varsigma_d(M_2)}	\lesssim 	\frac{\mathbb{P}^D\big(A\xleftrightarrow{\ge 0}  B(M_1)\big)}{ \mathbb{P}^D\big(A\xleftrightarrow{\ge 0} B(M_2)\big)}\cdot \big(\frac{M_2}{M_1}\big)^{(\frac{d}{2}-1)\boxdot (d-4)}	 \lesssim  M_2^{4\varsigma_d(M_2)}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2608.06011, 'Strong averaging principle for multiscale time-inhomogeneous SDEs with multiplicative $\al'] Suppose that Assumption \ref{cond} holds. Then there exists $C_{\kappa,p,s,T}>0$ such that for all $p\in[1,\alpha)$,
