[Lemma lem: 1009 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] We have
\begin{equation*}
	\int_{\Omega_{0}}\int_{\Omega_{0}'}\frac{\partial\tilde{f}(z)}{\partial\bar{z}}\frac{\partial\tilde{f}(w)}{\partial\bar{w}}
	\partial_{w}\Tr_{\textnormal{op}}\big( \mathcal{C}_{M'M^{-1},I} (1-\mathcal{C}_{M,\widetilde{M}}\mathcal{S})^{-1} \mathcal{C}_{M,\widetilde{M}}\mathcal{S}_{d} \big) \mathrm{d}^{2}w \mathrm{d}^{2}z
	= O\big(N^{-\epsilon_{0}}\big).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma chernoff of arXiv:2509.07372, 'On the edge eigenvalues of sparse random geometric graphs'] Let $X_i\stackrel{\operatorname{i.i.d.}}{\sim}\operatorname{Ber}(p)$ for $i=1,\cdots,n$. Then for any $t\in(0,1)$,
		\begin{align*}
			\mathbb{P}\left(\left|\sum_{i=1}^n X_i-np\right|\geqslant tnp\right)\leqslant2\exp\left(-\frac{t^2np}{3}\right).
		\end{align*}

[Lemma expansion of arXiv:2509.07372, 'On the edge eigenvalues of sparse random geometric graphs'] For $\varphi(\mathbf{x})$ as in (equation eq:varphi of the paper), we have that
		\begin{align}
			\mathcal{T}_n \varphi(\mathbf{x})=\frac{2C_\varphi}{m_2}\sum_{\substack{0\leqslant\bm{s}\leqslant\bm{k}\\ \bm{s}\ne\bm{k}}}\sum_{\bm{\alpha}\in\mathbb{N}^d}\frac{(-1)^{|\bm{\alpha}|}}{\bm{\alpha}!2^{|\bm{\alpha}|}}\mathsf{C}_{\bm{k},\bm{s},\bm{\alpha}}\bm{\sigma}^{-\bm{\gamma}}r_n^{|\bm{\gamma}|-2}\Lambda_{\bm{\gamma}}(r_n;\bm{\sigma},g),
		\end{align}
		with $\Lambda_{\bm{\gamma}}(r_n;\bm{\sigma},g)$ in (equation eq:5.3.0.2 of the paper) and $\mathsf{C}_{\bm{k},\bm{s},\bm{\alpha}}$ in (equation eq:5.3.0.3 of the paper).

