body:
[Definition of arXiv:2510.01838, 'Shadow and percolation I: discrete landscapes with independence'] Let $\ell>0$ and $i\in \mathbb{Z}$. We define the random set $M_\ell(i)$ as
    \begin{equation*}
        M_\ell(i):= \{Y_j - (j-i)\ell\ |\ j>i\}.
    \end{equation*}
    We define the event $\mathcal{T}_\ell(i)$ as
    \begin{equation*}
        \mathcal{T}_\ell(i):= \{\text{the set }M_\ell(i) \text{ admits a maximum}\}.
    \end{equation*}
    On the event $\mathcal{T}_\ell(i)$ we define a random integer $T_\ell(i)$ as
    \begin{equation*}
        T_\ell(i) := \min\{j>i\ |\ Y_j-(j-i)\ell = \max M_\ell(i)\}.
    \end{equation*}

[Lemma lem:ODE-embedding of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Let $\mathcal{Y}^{(0)}:=d\mathcal{S}^{(0)}$ associated to $(S,(x^{(0)}_{e})_{e\in E(\mathbb{Z}^2)})$. Assume also that the collection of masses $(m_e)_{e\in \mathbb{Z}^2}$ vanishes outside the box $\Lambda$. Consider the differential system defined on corners of $ \Upsilon^{\times} \cap  \Lambda  $, whose initial condition is given by $\mathcal{Y}^{(0)}$ and whose dynamic is given for any $\frak{p} \in \Lambda $ by
		\begin{equation}
		\frac{d \mathcal{Y}^{(t)}(\frak{p})}{dt}= \frac{1}{2} \sum\limits_{z_k \in \Lambda}m_k \Bigg[ \mathcal{Y}^{(t)}(c^+_k) \langle \chi_{\frak{p}}\chi_{a^+_k} \rangle_{S(t)} -  \mathcal{Y}^{(t)}(a^+_k) \langle \chi_{\frak{p}}\chi_{c^+_k} \rangle_{S(t)} \Bigg].
	\end{equation}
Then 
\begin{enumerate}
	\item There exist $T_0(\Lambda)>0$ such that the ODE (equation eq:ODE-embedding of the paper) is well defined on $[0;T_0(\Lambda)] $.
	\item For any time $0\leq t \leq T_0(\Lambda) $, the fermion $\mathcal{Y}^{(t)}$ solution to (equation eq:ODE-embedding of the paper) constructs an s-embedding $\mathcal{S}^{(t)}$ of the Ising model $S(t)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:totally_blind_idleness of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] For $j\in \mathbb{N}$, let $\tilde{\theta}_j^{\pi,n}$ denote the $j$th departure epoch of $D^{\pi,n}(t)$, and let $\phi_j^{\pi,n}$ denote the duration for which the server completing service at time $\tilde{\theta}_j^{\pi,n}$ remains idle. Similarly, for any $1\leq k \leq n$, define $\phi_{-k}^{\pi,n}$ to be the amount of time that server $k$ remains idle after time $0$ if it is initially idle, and $0$ otherwise. We say that a tie-breaking rule $\pi$ among idle servers is \emph{totally blind} if, for every $T>0$, it satisfies the following two properties:
\begin{enumerate}
    \item The conditional expectation of the scaled idle duration $\phi_j^{\pi,n}$ becomes asymptotically insensitive to the specific server, i.e.,
    \[
    \sup_{1\leq j\leq D^{\pi,n}(T)} n^{1/2}\,\mathbb{E}\!\left[\left|\mathbb{E}\!\left[\phi_j^{\pi,n}\mid\mathcal{F}_{\tilde{\theta}_j^{\pi,n}-}^n\right]-\mathbb{E}\!\left[\phi_j^{\pi,n}\mid\mathcal{F}_{\tilde{\theta}_j^{\pi,n}}^n\right]\right|\bigm|\mathcal{F}_{\tilde{\theta}_j^{\pi,n}-}^n\right] \stackrel{p}{\longrightarrow} 0.
    \]
    \item The unscaled expected residual idle time of any server becomes negligible:
    \[
    \sup_{0\leq t \leq T}\sup_{-n\leq j\leq D^{\pi,n}(t)} \mathbb{E}\!\left[(\phi_j^{\pi,n}-t+\tilde{\theta}_j^{\pi,n})^+\mid\mathcal{F}_{t}^n\right] \stackrel{p}{\longrightarrow} 0.
    \]

\end{enumerate}
The limiting fairness process under any totally blind tie-breaking rule is given as
\begin{align}
\eta^{\mathrm{TB}}(t)(\mathbb{A}) = \begin{cases}
        \frac{\int_\mathbb{A} \mu dF(\mu)}{\int_\mathbb{S} \mu dF(\mu)} &\mbox{if }t> \tau_0^{\mathrm{TB}}\\
        \delta_0(\mathbb{A}) &\mbox{if }t\leq \tau_0^{\mathrm{TB}}
    \end{cases}.
\end{align}
Moreover, the longest-idle-server-first (LISF) policy, which routes an arriving job to the server that has been idle the longest, and the random routing (RR) policy, which assigns jobs uniformly at random among idle servers, are both totally blind. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 97 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\bfx = (X,\bbx) \in \scrc^{\beta}([0,T],V)$ be a rough path for some index $\beta \in (\frac{1}{3},\frac{1}{2}]$, and let $f_0 \in \Lip([0,T] \times W,D(A))$ and $f \in C_b^{2\beta,3}([0,T] \times W, L(V,D(A^2)))$ be mappings such that
\begin{align}
&f_0|_{[0,T] \times D(A)} \in \Lip([0,T] \times D(A),D(A^2)),
\\  &f|_{[0,T] \times D(A)} \in C_b^{2\beta,3}([0,T] \times D(A), L(V,D(A^3))).
\end{align}
Then for every $\xi \in D(A^2)$ there exists a unique mild solution $$(Y,Y') \in \scrd_X^{2 \beta}([0,T],W)$$ to the RPDE \eqref{RPDE} with $Y_0 = \xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem123 of arXiv:2607.02742, 'Gaussian fluctuations for the parabolic Anderson model with L\'evy white noise'] Let $k\geq 1$ be an integer.
Let $(F_n)_{n\geq 1} \subseteq {\rm dom}(D^k)$ be such that $F_n \to F$ in $L^2(\Omega)$, and
\begin{equation}

\sup_{n\geq 1}\mathbb{E}\|D^kF_n\|_{\mathcal{H}^{\otimes k}}^2 <\infty.
\end{equation}
Then $F \in {\rm dom}(D^k)$ and $(D^kF_n)_{n\geq 1}$ converges to $D^kF$ in the weak topology of $L^2(\Omega;\mathcal{H}^{\otimes k})$.

