[Proposition 7 of arXiv:2609.00087, 'Translational tiles without spectra\\ in finite abelian $p$-groups'] The sets in Appendix~\ref{app:exp4-data} satisfy the following properties.
\begin{enumerate}
\item $E$ is a spectrum of $K$;
\item $E\oplus T_0=H$ and $E\oplus T_1=H$;
\item $K$ does not tile $H$;
\item for every $0\ne d\in K-K$,
\[
 |\widehat{\1_{T_0}}(d)|^2\ne
 |\widehat{\1_{T_1}}(d)|^2.
\]
\end{enumerate}

[Lemma 32 of arXiv:2609.03736, '2609.03736'] If $A$ is feasible for $\operatorname{LP}_n(d)$ with objective $M$, then
\begin{equation}
 A_i^{\mathrm{sh}}=\frac{n-i}{n}A_i
 \qquad(0\leq i\leq n-1)

\end{equation}
is feasible for $\operatorname{LP}_{n-1}(d)$ and has objective at least
$M/2$.  Consequently, for $0<\delta'<\delta<1/2$,
\begin{equation}
 R_D(\delta)\geq
 1-\frac{\delta}{\delta'}\bigl(1-R_D(\delta')\bigr).

\end{equation}

[Openproblem OP:potentially-explosive of arXiv:2511.10223, 'Stochastic Reaction Networks Within Interacting Compartments with Content-Dependent Fragme'] Is the compartment model
\begin{equation}
\begin{tikzcd}
    0\arrow{r}{1}& E&
    E+S\arrow{r}{1}& E+2S & &
    C \arrow[yshift=.5ex]{r}{S_C}& 2C  \arrow[yshift=-.5ex]{l}{2}
\end{tikzcd}
\end{equation}
explosive? (Stated as a problem by the paper; open unless the paper says otherwise.)

[Proposition 6 of arXiv:2605.26439, '2605.26439'] Assume that there exist constants $C,\alpha>0$ and $s\in[0,1)$ such that $f\in H^{-s}(0,1)$ and   \begin{equation*}
        |\langle f,e_n\rangle|\geq C e^{-\alpha \pi^2n^2}\quad \forall\, n\in\N^+.
    \end{equation*} Then system \eqref{controlled H equation} is null-controllable on $L^2(0,1)$ at any time $T>\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm-tail-D-x of arXiv:2504.20963, 'Exponential moments of truncated branching random walk martingales'] Suppose $\Phi '(1) =0$. Define 
\begin{equation}
  X= \sum_{|u|=1} [1+ (V(u))_+] e^{- V(u)} . 
\end{equation}  
If the random variable $X$ admits a finite exponential moment, then  there exists constants $C,c>0$   such that 
\begin{equation}
    \mathbb{P}(D^{(x)}_{n} > y )  \leq  C \,  R(x)e^{-x} \, e^{-c y} 
\end{equation}   
for all $ x >0 $, $y \ge 1$  and $ n \in \mathbb{N} \cup \{ \infty \}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:xiS-etaM-event-inclusion of arXiv:2605.16086, 'Loop pruning and downward deviations for maximum local time of discrete-time simple random'] For any \(k\in\mathbb{N}^+\) and \(\eta\in(0,1)\), on the event \(\{k\le M_\infty\}\),
\begin{equation}
\Biggl\{
\ell_0\bigl(\mathsf{Prune}(S[0,\tau_k],E)\bigr)\le \lceil \eta k\rceil
\Biggr\}
\supset
\Biggl\{
\frac{1}{k}\sum_{i=1}^{k}X_i>1-\eta
\Biggr\}.
\end{equation}

