body:
[Lem thm:admissibility of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $\sigma\in\mathds{R}$ and $w_\sigma:\mathds{R}^d\to\mathds{R}$, $w_\sigma(x)\mathrel{\mathop:}= (1+\left\lVertx\right\rVert_2^2)^{\frac{\sigma}{2}}$.
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{For every multiindex $\beta\in\mathds{N}_0^d$, we have
\begin{equation*}
D^\beta (1+\left\lVertx\right\rVert_2^2)^{\frac{\sigma}{2}}=p_{\sigma,\beta}(x)(1+\left\lVertx\right\rVert_2^2)^{\frac{\sigma}{2}-\left\lVert\beta\right\rVert_1}
\end{equation*}
where $p_{\sigma,\beta}(x)$ is a polynomial of degree at most $\left\lVert\beta\right\rVert_1$.
In particular, we have $\abs{D^\beta (1+\left\lVertx\right\rVert_2^2)^{\frac{\sigma}{2}}}\lesssim (1+\left\lVertx\right\rVert_2^2)^{\frac{\sigma}{2}}$.}
\item{We have $w_\sigma(x)\lesssim w_{\left\lvert\sigma\right\rvert}(x-y)w_\sigma(y)$ for all $x,y\in\mathds{R}^d$.}
\end{enumerate}

[Proposition 71 (Tail--defect rate) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $(F_R)_{R\ge1}$ be an increasing finite exhaustion of $I$.  In the
setting of Theorem~\ref{thm:dominated-stability}, suppose
\begin{align}
 \tau(R)&:=
   \norm{(M_i\mathbf1_{i\notin F_R})_i}_{E(I)}\longrightarrow0,
   \\
 \norm{(\Prof_{m,r}(K_{\nu;i}-K_{\mu;i})
          \mathbf1_{i\in F_R})_i}_{E(I)}
 &\le \delta(\nu)G(R),\qquad \mu\ge\nu.

\end{align}
Then
\begin{equation}

 \Prof_{m,r}(K_\nu-K_\mu)
 \le C_{E,r}\inf_{R\ge1}
 \{\delta(\nu)G(R)+2\tau(R)\}.
\end{equation}
In particular, if
\[
 \delta(N)\lesssim N^{-\theta},\qquad
 G(R)\lesssim R^A,
 \qquad \tau(R)\lesssim R^{-\sigma}
\]
for some $\theta,\sigma>0$ and $A\ge0$, then
\begin{equation}

 \Prof_{m,r}(K_N-K)\lesssim N^{-\theta\sigma/(A+\sigma)}.
\end{equation}
Under the same bounds for $\delta$ and $G$, if instead
$\tau(R)\lesssim\ell_R^{-\sigma}$, then
\begin{equation}

 \Prof_{m,r}(K_N-K)\lesssim\ell_N^{-\sigma}.
\end{equation}
For $2\le r<\infty$, both estimates pass to the Gaussian and Wick evaluations
with the factors in Theorem~\ref{thm:Gaussian-evaluators}.

[Lemma eq:uncut-trace-derivative-formula of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:uncut-logdet-derivatives}
For \(\eta>0\), \(A,C\in\operatorname{Sym}_n\), and \(r\ge1\),
\begin{equation}
 \frac{\,\mathrm d^r}{\,\mathrm d s^r}
 \operatorname{Tr}\ell_\eta(A+sC)\bigg|_{s=0}
 =
 (-1)^{r-1}(r-1)!\,
 \Re\operatorname{Tr}\!\left\{\bigl((A-i\eta I_n)^{-1}C\bigr)^r\right\}.
\end{equation}
Consequently,
\begin{align}
 \abs{D\operatorname{Tr}\ell_\eta(A)[C]}
 &\le\eta^{-1}\sqrt n\left\lVertC\right\rVert_{\mathrm{HS}},
 \\
 \abs{D^r\operatorname{Tr}\ell_\eta(A)[C,\ldots,C]}
 &\le(r-1)!\eta^{-r}
 \left\lVertC\right\rVert_{\mathrm{HS}}^2\left\lVertC\right\rVert_{\mathrm{op}}^{r-2},
 \qquad r\ge2.

\end{align}
The bounds are uniform in \(n,A,C\).

[Lemma lemmas2.1 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] Let \((W,W')\) be two independent cylindrical Wiener processes on \(H\),
and let \(a_t,b_t\) be bounded predictable processes
satisfying \(a_t(x)^2+b_t(x)^2=1\) for all $x\in\mathbb{T}$ (so that both processes lie in $L^\infty(\mathbb{T})$ a.s.) Define

\begin{equation}
\begin{aligned}
dB^0_t&=a_t\,dW_t+b_t\,dW'_t,\\
dB^1_t&=b_t\,dW_t-a_t\,dW'_t.
\end{aligned}

\end{equation}
Then \((B^0,B^1)\) is a pair of independent cylindrical Wiener
processes in the enlarged filtration.

[Definition 3 (Directional pole) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] If \(V_X(t)>0\), let \(C_X(t)\in[0,\infty]\) be the infimum of all \(c\geq0\) such that
\begin{equation}
 K_X(st)\leq \frac{V_X(t)s^2}{2(1-cs)},
 \qquad 0\leq s<1/c.
\end{equation}
The infimum of the empty set is infinity. If \(V_X(t)=0\), set \(C_X(t)=0\).

