[Corollary 12 of arXiv:2604.13149, 'The Distributional Tail of Worst--Case Quickselect'] For every \(t>0\),
\begin{equation}
\PP{\Svar>t}
\le
\inf_{\theta>0}\exp\!\bigl(-\theta t+2e^\theta\bigr).
\end{equation}
In particular, for every \(t>2\),
\begin{equation}
\PP{\Svar>t}
\le
\exp\!\Bigl(-t\log(t/2)+t\Bigr)
=
\exp\!\Bigl(-t\log t+(1+\log 2)t\Bigr).
\end{equation}
Equivalently,
\begin{equation}
-\log \PP{\Svar>t}
\ge
t\log t-(1+\log 2)t,
\qquad t>2.
\end{equation}

[Thm th3 of arXiv:2510.10898, 'A central limit theorem for unbalanced step-reinforced random walks'] Assume that
\begin{eqnarray*}
\sum_{k=1}^n \xi_k  /{a_n}\stackrel{d}{\rightarrow} S,
\end{eqnarray*}
where $S$ is a stable random variable 
with characteristic function $\mathbb{E}(e^{it S})=e^{-|t|^{\alpha}}$ and $\alpha\in (0,2)$.
Suppose further that
\begin{enumerate}
\item[$(A5).$]
$
\frac{1}{n}\sum_{k=1}^n |W_{nk}|^{\alpha} \stackrel{d}{\rightarrow} F,
$ where $F$ is some distribution function;
 \item[$(A6).$]   There exists $\beta\ge 1$ satisfying $\beta>\alpha$ and  $
\lim\limits_{c\rightarrow \infty} \sup\limits_n \frac{1}{n}\sum_{k=1}^n \mathbb{E} (|W_{nk}|^{\beta} I(|W_{nk}|>c))=0.
$
\end{enumerate}
Then we have
\begin{eqnarray*}
\frac{1}{a_n}\sum_{k=1}^n W_{nk} \xi_k \stackrel{d}{\longrightarrow} W^{1/\alpha}  S,
\end{eqnarray*}
where $W$ is a non-negative random variable with distribution function $F$, independent of $S$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:moment-M of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] Let $M$ be as (equation def:noise of the paper). Then for any $p\geqslant1,\gamma>0$, for any $(s,t)\in[0,1]_\leqslant^2$,  there  exists $C=C(\gamma,p,d,\alpha,\epsilon)>0$ so that
    \begin{align}

         \big\||M_t-\Gamma_{t-s}M_s|_{\boldsymbol{a}}^\gamma\wedge1\big\|_{L_p(\Omega)}  \leqslant C|t-s|^{\frac{\gamma}{\alpha}\wedge\frac{1}{p}-\epsilon}.
    \end{align}

