[Proposition 7 of arXiv:2607.22362, 'A Small-Noise Analysis of Controlled Functional Differential Equations with Gaussian Noise'] For all $\varepsilon > 0$, 
\begin{align*}
 V^\varepsilon &= \inf_{a \in \A} \sup_{h \in \mathbb{H}} \E \bigg[ \varphi \Big( \G (a (\sqrt{\varepsilon} \, \X + h), \sqrt{\varepsilon} \, \X + h) \Big) - \frac{1}{2} \| h \|^2_{\M}\bigg]
 \\
 &= \inf_{a \in \A} \sup_{h \in \mathbb{H}} \E \bigg[ \varphi \Big( \G (a (\X + h / \sqrt{\varepsilon} ),  \sqrt{\varepsilon} \, \X + h) \Big) - \frac{1}{2} \| h \|^2_{\M}\bigg].  

\end{align*}

[Thm finiteVsInfinite of arXiv:2609.02588, 'Ramsey-type results for Maker-Breaker games'] {}
    For a given graph $H$, the following three statements are equivalent.
    \begin{itemize}
        \item[(I)]{$\mathcal{M}^1_{MB}(H)$ consists of infinitely many graphs.}
        \item[(II)]{$\mathcal{M}^1_{BM}(H)$ consists of infinitely many graphs.}
        \item[(III)]{At least one connected component of $H$ contains at least three edges.}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:pointwise-trace-concentration of arXiv:2608.21561, '\textbf{Loss-Parameterized Fisher Width Along Learning Trajectories}'] There exist universal constants $C,c>0$ such that
\begin{equation}
    \mathbb E\!\left[
        \operatorname{Tr}\widehat G_n(\theta)
        -
        d\,\widehat m_n(\theta)
    \right]
    =
    m(r)(\kappa(r)-1).

\end{equation}
Moreover, for every $\delta\in(0,1)$, with probability at least
\[
    1-\delta-2e^{-cnm(r)},
\]
\begin{align}
&
\left|
    \operatorname{Tr}\widehat G_n(\theta)
    -
    d\,\widehat m_n(\theta)
    -
    m(r)(\kappa(r)-1)
\right|
\nonumber\\
&\qquad\leq
C\left[
    \sqrt{
        \frac{
            d\,m(r)\log(4/\delta)
        }{n}
    }
    +
    \frac{\log(4/\delta)}{n}
\right].

\end{align}
With probability at least
\[
    1-\delta-4e^{-cnm(r)},
\]
one also has
\begin{align}
\left|
    \frac{
        \operatorname{Tr}\widehat G_n(\theta)
    }{
        d\,\widehat m_n(\theta)
    }
    -1
\right|
\leq
C\left[
    \frac1d
    +
    \sqrt{
        \frac{
            \log(4/\delta)
        }{
            ndm(r)
        }
    }
    +
    \frac{
        \log(4/\delta)
    }{
        ndm(r)
    }
\right].

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem.npoint of arXiv:2411.19145, 'On the intersection of critical percolation clusters and other tree-like random graphs'] Assume $\alpha \in (d/2,d)$. There exists a constant $C>0$, such that for any $L\ge 2$, any $x_1,\dots,x_L,z\in V$, one has 
$$\sum_{y\in V} g_\alpha(z,y) \prod_{\ell =1}^L g_\alpha(y,x_\ell) \le C^L\cdot \sum_{\sigma \in \mathfrak S_L}
g_\alpha(x_{\sigma(1)},z) \prod_{\ell = 1}^{L-1} g_{2\alpha-d}(x_{\sigma(\ell)},x_{\sigma(\ell +1)}). $$

