[Lem 5 of arXiv:2609.02327, 'On the counting function of square-full numbers'] Let $k \ge 2$ be any integer.
			For $\Re (s) > \frac {1}{k}$, we have
			\begin{equation}
				F_k(s) := \sum_{n=1}^{\infty}\frac{f_k(n)}{n^s}=\prod \limits_{p} \left ( 1 + \frac {p^{-ks}}{1-p^{-s}} \right ).
			\end{equation}
			In particular,
			\begin{equation}
				F_2(s) := \sum_{n=1}^{\infty}\frac{f_2(n)}{n^s}= \frac {\zeta (2s) \zeta (3s)}{\zeta (6s)}.
			\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:T2-limit of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] We have
\begin{equation}
    |T_{2, n, q}|
    =
    \begin{cases}
        O(n^{-1})        & \text{if } q \in [-1,\,0), \\
        O(n^{-1}\log n)  & \text{if } q = 0, \\
        O(n^{q-1})       & \text{if } q \in (0,\,1).
    \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 17 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] (\cite[p. 14]{adrs})
  The colligation is called closely inner connected if
  \begin{equation}
    \mathfrak H=\bigvee\left\{{\rm ran}\,A^pB\,:\, p\ge 0\right\}.
  \end{equation}
    The realization is called closely outer connected if
  \begin{equation}
    \mathfrak H=\bigvee\left\{{\rm ran}\,A^{*q}C^*\,:\, q\ge 0\right\}.
    \end{equation}
  The realization is called closely  connected if
  \begin{equation}
    \mathfrak H=\bigvee\left\{{\rm ran}\,A^pB\,,\,{\rm ran}\,A^{*q}C^*:\, p,q\ge 0\right\}.
  \end{equation}$\T$

[Lemma 5 of arXiv:2606.11511, 'Convergence of a Critical Multitype Bellman--Harris Process with One Infinite-Mean Lifetim'] Assume Assumption~\ref{ass:F1-local-increment}. Let \(\kappa>\gamma\), and let
\(h:[0,\infty)\to[0,\infty)\) be a Borel function such that
\begin{equation}
  h(t)
  \le C_h(1+t)^{-\kappa},
  \qquad t\ge0.
\end{equation}
Then there exist constants \(C_h'>0\) and \(\kappa_h'>\gamma\) such that
\begin{equation}
  \int_0^t h(t-s)\,dF_1(s)
  \le C_h'(1+t)^{-\kappa_h'},
  \qquad t\ge0.
\end{equation}

[Lemma 2 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] For any $n \in \mathbb{N}$, any $p \in [1,\infty]$, and any $B \subseteq N_{n}$, let 
	\begin{align}
	 \sqrt{	\operatorname{Var} \left( |B|^{-1/2} \sum_{i \in B} g(Z_{i})   \right) } \lesssim    \min \left\{  	\Gamma^{\mathrm{sum}}_{p}(B) ,  	\Gamma_p^{\sharp}(B) |B|^{1/2p}  \right\} \max_{i \in B}  ||g||_{L^{2p}(P_{Z_{i}})}, 
	\end{align}
where 
\begin{align*}
	\Gamma^{\mathrm{sum}}_{p}(B) : = \left\{  
	\begin{array}{ll}
		\sqrt{ \sum_{\rho \in R(B)}  	\frac{|S_{B}(\rho)|}{|B|}  \left( \alpha_{ \mathcal{F} , B }(\rho)  \right)^{1-\frac{1}{p} } }  & if~p \in (1,\infty] \\
		\sqrt{ \sum_{\rho \in R(B)}  	\frac{|S_{B}(\rho)|}{|B|} }  & if~p = 1
	\end{array}
	\right.
\end{align*}
and \begin{align*}
	\Gamma_p^{\sharp}(B)
	:=
	\left\{  
		\begin{array}{ll}
	\sqrt{ \left(
	\int_0^1
	\left[
	\sum_{\rho\in R(B)}
	\frac{|S_B(\rho)|}{|B|}
	1\{\alpha_{\mathcal F,B}(\rho)\geq u\}
	\right]^{\frac{p}{p-1}}
	du
	\right)^{1-\frac{1}{p} } } & if~p \in (1,\infty] \\
	\sqrt{ \sum_{\rho \in R(B)}  	\frac{|S_{B}(\rho)|}{|B|} }  & if~p = 1	
	 	\end{array}
 		 \right.
\end{align*}
with $R(B) : = \{ r \in \{ 0,1, \ldots, n-1\} \cup \{\infty\}    \colon 	S_{B}(r) \ne \emptyset  \}$.\footnote{We set $d_{n}(i,i) = 0$ and $\alpha_{\mathcal{F} , B }(0) = 1$. The case $r=\infty$ captures pairs that are not connected, which by our conditions are independent and thus $\alpha_{\mathcal{F} , B }(\infty) : =  0$.}

Moreover, if $\max_{i \in B} ||dP_{Z_{i}}/dP_0||_{\infty} \leq C$, for some measure $P_0$, then the norm can be taken to be $||.||_{L^{2p}(P_0)}$ and the factor $|B|^{1/2p}$ in expression  \ref{eqn:var.bound.text} can be dispensed with.

