[Theorem 7 (Vorono\"i summation formula) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] Let $\pi$ be an irreducible cuspidal automorphic representation of $\GL_2(\A_\Q)$ with central character $\omega_\pi$, a adelic lift a Dirichlet character $\chi_\pi$. Let $q(\pi)$ be the arithmetic conductor of $\pi$, and $(a,\, q)=(q,\, q(\pi))=1$. Then for any $X\gg 1$ and $U\in C_c^\infty(\R_{\geq0})$ we have the following identity,
		\begin{equation}
			\begin{split}
				\sum_{n\geq 1}\lambda_\pi(n)e\left(\frac{an}{q}\right)U\left(\frac{n}{X}\right)&=\chi_\pi(-q)i^{k(\pi_\infty)}\eps(\pi)\frac{X}{q\sqrt {q(\pi)}}\\&\times\underset{\pm}{\sum_{n\geq 1}}\lambda_{\bar \pi}(n)e\left(\pm\frac{\overline{a\,q(\pi)}n}{q}\right)U\pm\left(\frac{m}{q(\pi)q^2/X}\right)
			\end{split}
		\end{equation}
		where the integral transform is given by Bessel transforms,
        \begin{equation}
            U_{\pm}(\xi)=\int_0^\infty U(y)\mathcal K_{\pm}(4\pi\sqrt{y\xi})\, dy.
        \end{equation}
        The Bessel kernels depends on the Archimedean local component $\pi_\infty$,
		\begin{itemize}
			\item If $\pi_\infty$ belongs to Discrete series i.e., $\pi$ corresponds to a holomorphic form of weight $\kappa$, then $k(\pi_\infty)=\kappa$, and the kernels are:
			\begin{equation*}
				\mathcal K_+(x)=2\pi i^\kappa J_{\kappa-1}(x),\hspace{0.2cm}\mathcal K_-(x)=0.
			\end{equation*}
			\item If $\pi_\infty$ belongs to Principal series i.e., $\pi$ corresponds to a Maa\ss\ form with eigenvalue $1/4+t^2$ then $k(\pi_\infty)=0$ and the kernels are:
			\begin{equation*}
				\mathcal K_+(x)=\frac{-\pi}{\sin(\pi it)}\left(J_{2it}(x)-J_{-2it}(x)\right),
			\end{equation*}
            and 
            \begin{equation*}
                \mathcal K_-(x)=4\beta_\pi\cosh(\pi t)K_{2it}(x),
            \end{equation*}
            where $\beta_\pi=\pm1$ is the eigenvalue of the corresponding Maa\ss\ form under the reflection operator depending on this we call $\pi$ even or odd; $J_\nu$ and $K_\nu$ are the standard Bessel functions.
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma keyI of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Given a fixed $s_0\in\mathbb{R}$, assume the scaling $(\tilde{\mu}_{n,N},\tilde\sigma_{n,N})$ satisfies the order restriction in (equation restriction of recaling of the paper). Then under the assumption that $\frac{N}{n}\rightarrow\gamma\in(0,1)$, we have:
    \begin{equation*}
        N^{\frac{2}{3}}B_{n,N}(x_N(s))\le C(s_0,\gamma)e^{-\frac{s}{2}}
    \end{equation*}
    for any $s\in\left[s_0,\frac{e_0\tilde{\mu}_{n,N}}{\tilde{\sigma}_{n,N}}\right]$ when $N$ is large enough. Furthermore, with  $\tilde{x}_N(s):=\tilde{\mu}_{n,N}-\tilde{\sigma}_{n,N}s$,
    \begin{equation*}
        N^{\frac{2}{3}}B_{n-1,N}(\tilde{x}_N(s)),~N^{\frac{2}{3}}B_{n,N-1}(\tilde{x}_N(s))\le C(s_0,\gamma)e^{-\frac{s}{2}}
    \end{equation*}
    for $N$ large.

[Definition 8 of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] (Stopping Time \cite[Definition 5.3]{bender3})  
Given a Trajectory Space $\Se$, a \emph{trajectory based stopping time} (or \emph{stopping time} for short) is a function $\tau:\Se\rightarrow \mathbb{N}\cup\{\infty\}$ such that:
\begin{equation*}
    \text{for any}\quad S,S'\in\Se\quad\text{if}\quad S_k=S'_k\quad\text{for}\quad 0\leq k\leq \tau(S),\quad\text{then}\quad \tau(S)=\tau(S').
\end{equation*}

