body:
[Cor 29 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Let $F \in \bD^{k+1, p}$ and $\Delta_F^{-1} \in L^q(\Omega)$ for some $k \in \N$ and $p, q\in (1, \infty)$. 
If $s_j = s_j[p,q] > 1$ for some $j \in \{1, \ldots, k\}$, then for any $i \in \{1, \ldots, j\}$, the linear operator
\begin{equation}
    \sC_F^{(-i, s_i)} \colon \cS_{-i} \to \bW^{-i,s_i}, \qquad \Dom \left(\sC_F^{(-i, s_i)}\right) = \cS(\R),  \qquad \varphi \mapsto \varphi(F) 
\end{equation}
is continuous and can be uniquely extended to the continuous linear operator 
\begin{equation}
    \wt{\sC_F^{(-i, s_i)}} \colon \cS_{-i} \to \bW^{-i,s_i}, \qquad  \Dom \left(\wt{\sC_F^{(-i, s_i)}}\right) = \cS_{-i}. 
\end{equation}
Moreover, for any $i_1, i_2 \in \{1, \ldots, j\}$ with $i_1 \leq i_2$ and any $T \in \cS_{-i_1}$, we have
\begin{equation}
    \wt{\sC_F^{(-i_2, s_{i_2})}}(T) = \wt{\sC_F^{(-i_1, s_{i_1})}}(T) \quad \text{in $\bW^{-i_1, s_1}$}. 
\end{equation}

