[Lemma lem:scaling_limit_diagrams_no_cutoff of arXiv:2508.18807, '{\bf Critical long-range percolation I: High effective dimension}'] We have



\begin{equation*}
\lim_{s \to \infty} \lim_{R\to \infty} \frac{1}{\eta(R)}\mathbb E_{\beta_c,\sigma^{-1}(s R)} \left[ \prod_{i=1}^n\mu_R[\varphi_i]\right] 




= \mathbb N\left[ \prod_{i=1}^n \mu[\varphi_i] \right]

\end{equation*}
for each $n\geq 1$ and sequence of compactly supported continuous functions $\varphi_1,\ldots,\varphi_n :\mathbb R^d \to \mathbb R$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop B-prop of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] For each $n,L\in\mathbb{N}$ with $L\geq n$, the B($n$,$L$) enjoys the following properties:
    \begin{enumerate}[label=(\roman*)]

    \item \textit{Partition of the unity}: for any integer $ 0<L<N/2 $ it holds that
    \begin{align}
    \mathcal{L}_N^{\text{SSEP}}
    =\sum_{n=0}^L\mathcal{L}_N^{n,L};
    \end{align}

    \item \textit{Symmetry}: for any $\eta\in \Omega_N$ it holds that $\mathbf{b}_{n,L}(\eta)=\mathbf{b}_{L-n,L}(\overline{\eta})$, with $\eta\mapsto\overline{\eta}$ the map that exchanges the particles by vacant sites and vice-versa;

    \item \textit{Interpolation}: for each $n\in\mathbb{N}_+$ it holds that \textnormal{B($n$,$n$)$=$PMM($n$)};

    \item \textit{Range}: For each $\eta\in\Omega_N$ it holds that $\mathbf{b}_{n,L}(\eta)\in [0,1]$. 

    \item \textit{Blocked configurations}: there is $\eta\in\Omega_N$ such that $\mathbf{b}_{n,\ell}(\tau^x\eta)=0$ for any $x\in\mathbb{T}$;

    \item \textit{Mobile Clusters}: any box of length $L+2$ with exactly $n+1$ particles constitutes a mobile cluster. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2605.27818, 'Exponential decay of mass for inertial coalescing particles with Hamiltonian noise'] For every $x \in\,\T^2$ it holds\begin{equation}
\nabla H(x)\cdot D\xi(x)\,\xi(x)\;=\;H(x)\,\Lambda(x),
\end{equation}
where
\begin{equation}
\Lambda(x):=2(h_1')^2(x_1)(h_2')^2(x_2)-(h_1')^2(x_1) (h_2 h_2'')(x_2)-(h_1 h_1'')(x_1)(h_2')^2(x_2).
\end{equation}
Moreover
\begin{equation}
\text{{\em div}}(D\xi\,\xi)(x)\;=\;2\,D_H(x),\end{equation}where
\[D_H(x):=(h_1')(x_1)^2(h_2')^2(x_2)-(h_1 h_1'')(x_1)\,(h_2 h_2'')(x_2).
