[Theorem th:3 of arXiv:2608.13559, 'Equi-dependence implying independence'] Take any two nonnegative integers $s$ and $t$. Suppose that condition (equation eq:=p of the paper) holds for all $i\in\mathbb{N}$, and for some $q\in(0,1)$
\begin{equation}

	\frac1{N_{n,s,t}}\,\sum_{(S,T)\in\mathcal{P}_{n,s,t}}\operatorname{\mathsf{P}}(A|B^{S,T})\to q
\end{equation}
as $n\to\infty$. 
Then $\operatorname{\mathsf{P}}(A)=q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition DefAvoidingLawBer of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Let $k \in \mathbb{N}$ and $\mathfrak{W}_k$ denote the set of signatures of length $k$, i.e.
\begin{equation}
\mathfrak{W}_k = \{ \vec{x} = (x_1, \dots, x_k) \in \mathbb{Z}^k: x_1 \geq  x_2 \geq  \cdots \geq  x_k \}.
\end{equation}
Let $\vec{x}, \vec{y} \in \mathfrak{W}_k$, $T_0, T_1 \in \mathbb{Z}$ with $T_0 < T_1$, and $f: \llbracket T_0, T_1 \rrbracket \rightarrow (-\infty, \infty]$ and $g: \llbracket T_0, T_1 \rrbracket \rightarrow [-\infty, \infty)$ be two functions. With the above data we define the {\em $(f,g)$-interlacing geometric line ensemble on the interval $\llbracket T_0, T_1 \rrbracket$ with entrance data $\vec{x}$ and exit data $\vec{y}$} to be the $\Sigma$-indexed geometric line ensemble $\mathfrak{Q}$ with $\Sigma = \llbracket 1, k\rrbracket$ on $\llbracket T_0, T_1 \rrbracket$ and with the law of $\mathfrak{Q}$ equal to $\mathbb{P}^{T_0,T_1, \vec{x},\vec{y}}_{\operatorname{Geom}}$ (the law of $k$ independent uniform increasing paths $\{B_i: \llbracket T_0, T_1 \rrbracket \rightarrow \mathbb{Z} \}_{i = 1}^k$ from $B_i(T_0) = x_i$ to $B_i(T_1) = y_i$), conditioned on 
\begin{equation}
\begin{split}
\mathsf{Inter}  = &\left\{ B_i(r-1) \geq B_{i+1}(r)  \mbox{ for all $r \in \llbracket T_0 + 1, T_1 \rrbracket$ and $i \in \llbracket 0 , k \rrbracket$} \right\},
\end{split}
\end{equation}
with the convention that $B_0(x) = f(x)$ and $B_{k+1}(x) = g(x)$.

The above definition is well-posed if there exist $B_i \in \Omega(T_0,T_1,x_i,y_i)$ for $i \in \llbracket 1, k \rrbracket$ that satisfy the conditions in $\mathsf{Inter}$. We denote by $\Omega_{\mathsf{Inter}}(T_0, T_1, \vec{x}, \vec{y}, f,g)$ the set of collections of $k$ increasing paths that satisfy the conditions in $\mathsf{Inter}$ and then the distribution of $\mathfrak{Q}$ is simply the uniform measure on $\Omega_{\mathsf{Inter}}(T_0, T_1, \vec{x}, \vec{y}, f,g)$. We denote the probability distribution of $\mathfrak{Q}$ as $\mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{T_0,T_1, \vec{x}, \vec{y}, f, g}$ and write $\mathbb{E}_{\mathsf{Inter}, \operatorname{Geom}}^{T_0, T_1, \vec{x}, \vec{y}, f, g}$ for the expectation with respect to this measure. If $f=+\infty$ and $g=-\infty$, we drop them from the notation and simply write $\Omega_{\mathsf{Inter}}(T_0,T_1,\vec{x},\vec{y})$, $\mathbb{P}^{T_0, T_1, \vec{x},\vec{y}}_{\mathsf{Inter}, \operatorname{Geom}}$, and $\mathbb{E}^{T_0, T_1, \vec{x},\vec{y}}_{\mathsf{Inter}, \operatorname{Geom}}$.

[Theorem cor:asy of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an upper probability. Then the following three statements are equivalent:
	\begin{longlist}
		\item $V$ is weakly mixing;
		\medskip
		\item  	there exists $Q\in\operatorname{core}(V)\cap\mathcal{ M}^{wm}(T)$ such that for any $P\in\operatorname{core}(V)$,
		\begin{equation*}
			\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}|P(B\cap T^{-i}C)-P(B)Q(C)|^2=0\text{ for any }B,C\in\mathcal{F}.
		\end{equation*}
		\medskip
		\item 	there exists $Q\in\operatorname{core}(V)\cap\mathcal{ M}(T)$ such that for any $P\in\operatorname{core}(V)$,
		\begin{equation}
			\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}|P(B\cap T^{-i}C)-P(B)Q(C)|^2=0\text{ for any }B,C\in\mathcal{F}.
		\end{equation}
	\end{longlist}

