[Lemma cor:hill-2 of arXiv:2608.08375, 'Algebraic formulas for first-passage times of Markov processes in the linear framework: ge'] With the assumptions above, choose $z \in Z$. Let $W \subseteq \overline{Z} = \mathcal{V}(\mathcal{H}_u[G])$ be the vertex subset of $\mathcal{H}_u[G]$ given by $W = \mathcal{V}_{\text{out}}(u)$. Then,  
\begin{align*}
    \sum_{k \in W : k \to_G z}{\ell(k \to_G z) \, w(\Phi_{\{k\}}(\mathcal{H}_u[G]))}
    & = w(\Phi_{(Z \setminus \{z\}) \cup \{u\} \to Z}(G))\,, \\
    \sum_{z \in Z}{\sum_{k \in W : k \to_G z}{\ell(k \to_G z) \, w(\Phi_{\{k\}}(\mathcal{H}_u[G]))}}
    & = w(\Phi_Z(G))\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 14 of arXiv:2606.30364, 'Distributional comparison for non-commutative infinitely divisible probability measures'] For $\mu_1,\mu_2 \in \mathcal{P}(\R)$, we let $\Gamma_{\!\!\textrm{nc}}(\mu_1,\mu_2)$ denote the set of all tracial $C^{*}$-probability spaces $(\Ac,\varphi)$ containing variables $a_1=a_1^*$ and $a_2=a_2^*$ with analytical distributions $\mu_1$ and $\mu_2$, respectively. 

The \emph{free $p$-Wasserstein distance} between $\mu_1$ and $\mu_2$ is defined as

\begin{align}
	\freeWass{p} (\mu_1,\mu_2) \quad = \inf_{ (\Ac,\varphi) \in \Gamma_{\!\!\textrm{nc}}(\mu_1,\mu_2) } 
			\left\{ \abs{\, a_1-a_2 \,}_p  \, \left| \begin{array}{c}
			a_1=a_1^*,a_2=a_2^* \in \Ac \text{ with } \\  \varphi(a^n_i) = m_n[\mu_i] 
			\text{ for } n \geq 1 \text{ and } i=1,2			
	\end{array} \right.			
			 \right\}	
\end{align}

where $\abs{\, \cdot \,}_p $ is the the $p$-norm in a tracial $C^{\ast}$-probability spaces, see Definition \ref{def:nc_pnorm}.

