[Theorem 82 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Suppose   that $(\sfd_{0},q,p)$ are properly tight.
 Then 
for any $\rho\leq \rho_{b} $, $\cF_{\tau}$-measurable $\bR^{d}$-valued $y$,  and Borel nonnegative $f$ 
given on $\bR^{d+1}$,
we have on $\{\tau<\infty\}$ that  
\begin{equation}

E_{\cF_{\tau}}\int_{0}^{\theta_{\tau}\tau_{\rho}(y) }f( t, x_{\tau+t} -y)\,dt\leq
N(d,\delta,p,q)\rho^{2}\dashnorm f\|_{L_{(q,p)}(C_{\rho})},
\end{equation}
\begin{equation}

E_{\cF_{\tau}}\int_{0}^{\theta_{\tau}\tau'_{\rho}(y)  }f( t, x_{\tau+t}-y)\,dt\leq
N(d,\delta,p,q)\rho^{2}
\sup_{C\in\bC_{\rho}}
 \dashnorm  
f\| _{L_{(q,p)}(C) }.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn counterexample of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Assume that $\gamma$ is a bounded variation path in $R^2$. We say $\gamma$ is a "figure 8" path if $\gamma=\alpha\sqcup\beta$, the concatenation of $\alpha$ and $\beta$, where $\alpha$ and $\beta$ have the same image like a figure 8 but with different orientations.

    \begin{figure}[H]  
    \centering 
    \includegraphics[width=6cm]{3.jpg} \caption{trajectories of $\alpha$ and $\beta$} 

    \end{figure}

    (\textit{The diagram illustrates a trajectory with two orientations: in the first graph, one starts at the intersection and traverses anti-clockwise, while in the second, the traversal is clockwise, both following the given arrow directions to complete the loop.})

[Theorem theo:normald=1 of arXiv:2509.07372, 'On the edge eigenvalues of sparse random geometric graphs'] Fix some small constant $0<\varepsilon<\frac{1}{2(d+4)}$ and assume 
		\begin{align}
			n^{-\tfrac{1}{d+4}+\varepsilon}\ll r_n\ll n^{-\varepsilon}.
		\end{align}
		For some fixed integer $d\in\mathbb{N}^+$, suppose $\mathbf{x}_j\stackrel{\mathrm{i.i.d.}}{\sim}\mathcal{N}_d(\bm{0},\Sigma)$ for $j=1,\cdots,n$, with $\Sigma$ as in (equation eq:2.1.0 of the paper). Moreover, for $\delta$ in (equation eq:2.1 of the paper), we assume that
		\begin{align}
			\delta<\min\{\sigma_1^{-2},\cdots,\sigma_d^{-2}\}.
		\end{align}
		In addition, for $h(y)=\bm{1}_{[0,1]}(y)g(y)$, $y\geqslant0$, we assume that $g\in C^2([0,\infty))$ and $g(\cdot)$ is bounded from above and below on $[0,1]$ by some universal positive constants. Let $\mathbf{L}$ be defined in (equation eq:2.1.2 of the paper) via (equation eq:1.1 of the paper) and (equation eq_originalK of the paper) with $1\leqslant p\leqslant\infty$. Let $M$ be any fixed positive integer and $K_0$ be defined in (equation eq:2.1 of the paper). Then, for sufficiently large $n$, with probability $1-\oo(1)$, $K_0\leqslant n^{1-\tfrac{2}{(d+2)^2+\eta}}$, for some sufficiently small constant $\eta>0$. Moreover,
		\begin{align}
			\lambda_{K_0+k}(\mathbf{L})=\mu_{k+1}(\Delta_\varrho)+\oo(1),\quad k=1,\cdots,M.
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] Under Assumption \ref{ass:att_reg}, the time-marginal error between the interpolated scheme $\hat{X}$ and the true continuous dynamics $\bar X$ satisfies:
    \begin{equ}
        \E\left[\sup_{0\leq t\leq T}\frac{1}{N}\sum_{i=1}^N |\hat{X}^i_t - \bar X^i_t|^2\right] \leq \frac{\mathsf c}{L} (4T+T^2) e^{(4+T)\mathsf cT},
    \end{equ}
    where $\mathsf c > 0$ is a constant independent of $N$, $L$, and $m$.

