[Proposition 1 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Suppose that a nonlinear expectation $\mathbb{\tilde{E}}[\cdot]$
is dominated by a sublinear expectation $\mathbb{\hat{E}}[\cdot]$ on
$(\Omega,\mathcal{H})$. Let $X\in L^{1}(\Omega)$ satisfy $\mathbb{\hat{E}
}[X]=-\mathbb{\hat{E}}[-X]$. Then
\begin{equation}
\mathbb{\tilde{E}}[\alpha X+Y]=\alpha \mathbb{\hat{E}}[X]+\mathbb{\tilde{E}
}[Y]\text{ for each }Y\in L^{1}(\Omega)\text{, }\alpha \in \mathbb{R}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 58 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix integers $j_0 \in [0, \mathfrak{j}]$ and $i_0 \in [0, a_{j_0}]$. Assume that, for any integers $j \in [j_0, \mathfrak{j}]$ and $i \in [0, a_j]$ such that either $j > j_0$ or $i < i_0$, the following holds w.o.p.: 
\begin{flalign}

	\begin{aligned}
		& H_{\mathsf T_{i,j},j} (w) \le \mathcal{H}_{q_{i}} (w) + N^{\delta-1}, \qquad \text{for each $w \in \mathfrak{X}$}; \\
		& H_{\mathsf T_{i,j},j} (w) \le \mathcal{H}_{q_{i}} (w), \qquad \qquad  \quad  \text{for each $w \notin \mathfrak{L}_{q_i}^+ (\delta)$}.
	\end{aligned}
\end{flalign}

\noindent Then w.o.p., we have for any $t \in [\mathsf{T}_{i_0, j_0}, N^5]$ that 
\begin{flalign}

	\begin{aligned}
		& H_{t,j_0} (z_0) \le  \mathcal{H}_{q_{i_0}} (z_0) + N^{\delta-1}, \qquad \text{for each $z_0 \in \mathfrak{X}$}; \\ 
		& H_{t,j_0} (z_0) \le \mathcal{H}_{q_{i_0}} (z_0), \qquad \qquad \quad    \text{for each $z_0 \notin \mathfrak{L}_{q_{i_0}}^+ (\delta)$}.
	\end{aligned} 
\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

