[Corollary 14 (Event identity) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] In the setting of Proposition~\ref{prop:supermart-relax}(iii), for $A \in \cF_t$ with $P(A) > 0$,
\begin{equation}
  -\log\PP(A)
  = \lambda\,\E[Y_t \mid A] - \E[\overline\Psi_t(\lambda) \mid A]
    + \KL\bigl(P(\cdot \mid A)\,\big\|\,\overline Q^\star_t\bigr)
    - \log\E_P[E_t(\lambda)],
\end{equation}
for $\dd\overline Q^\star_t/\dd P \propto E_t(\lambda)$.
Both residuals are nonnegative, and discarding them gives the event bound
\begin{equation}
  \PP(A) \leq \exp\!\bigl(-\lambda\,\E[Y_t \mid A] + \E[\overline\Psi_t(\lambda) \mid A]\bigr);
\end{equation}
if in addition $\lambda \geq 0$ and on $A$ one has $Y_t \geq x$ and $\overline\Psi_t(\lambda) \leq c$,
then $\PP(A) \leq e^{-\lambda x + c}$, at the further cost of the event relaxation $\lambda(\E[Y_t \mid A] - x) + (c - \E[\overline\Psi_t(\lambda) \mid A])$.
Since $E_t(\lambda) > 0$ a.s., the first residual is strictly positive whenever $\PP(A) < 1$: equality in~\eqref{eq:event-bound} holds only if $\PP(A) = 1$ and $\lambda Y_t = \overline\Psi_t(\lambda)$ a.s. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm6.2 of arXiv:2602.23124, '\textsc{ Necessary and Sufficient Conditions for the Lacunary/Hereditary Laws of Large Num'] {\bf Necessity and Sufficiency in the  Classical  WLLN for I.I.D. Sequences:}
  For   real-valued I.I.D. functions $\,h_1, h_2, \cdots,$  the following are equivalent: 

  \smallskip
  \noindent
  {\bf (i)} {\rm WLLN:} There exist ``correctors"     $\,d_1, d_2, \cdots\,$ in $\mathbb R\,,$ so that 
  $ \,
\lim_{N \to \infty} \left( \frac{1}{N} \sum_{n=1}^N h_n - d_N \right) = 0\,$ holds in $\,{\mathbb P}-$probability; i.e., for each $\varepsilon >0$ we have
\begin{equation} 

\pi_N^\star( \varepsilon)\,:= \,  {\mathbb P} \bigg( \, \bigg| \frac{1}{\,N\,} \sum_{n=1}^N h_n - d_N \bigg| > \varepsilon  \bigg)\, \longrightarrow \, 0\,, \quad \text{as}~~ N \to \infty\,.
\end{equation}
 {\bf (ii)} With the notation of (equation 6.7 of the paper), for every $\varepsilon >0$ we have 
 \begin{equation} 

\lim_{M \to \infty} \tau_M (\varepsilon) =0\,.
\end{equation}
{\bf (ii)$^\prime$} With the notation of (equation 6.8 of the paper), for every $\varepsilon >0$ we have 
 \begin{equation} 

\lim_{M \to \infty} \sigma_M (\varepsilon) =0\,.
\end{equation}
{\bf (ii)$^{\prime \prime}$}  With the notation of (equation 6.9 of the paper), for every $\varepsilon >0$ we have 
 \begin{equation} 

\lim_{M \to \infty} v_M (\varepsilon) =0\,.
\end{equation}
{\bf (ii)$^{\prime \prime \prime}$}  With the notation of (equation 6.8a of the paper), for every $\varepsilon >0$ we have 
 \begin{equation} 

\lim_{M \to \infty} \rho_M (\varepsilon) =0\,.
\end{equation}
 {\bf (iii)} With the notation of (equation 6.7 of the paper),   for every $\varepsilon >0$ we have 
 \begin{equation} 

\lim_{M \to \infty} \frac{1}{\,M\,} \int_0^M \tau_t (\varepsilon)\, \mathrm{d} t\, =\,0\,.
\end{equation}
{\bf (iii)$^{\prime}$} With the notation of (equation 6.8 of the paper),   for every $\varepsilon >0$ we have 
 \begin{equation} 

\lim_{M \to \infty} \,M \int_M^\infty \frac{\sigma_t (\varepsilon)}{\,t^2\,}  \, \mathrm{d} t\, =\,0\,.
\end{equation}
{\bf (iii)$^{\prime \prime}$}  With the notation of (equation 6.9 of the paper),   for every $\varepsilon >0$ we have 
 \begin{equation} 

\lim_{M \to \infty} \,M \int_M^\infty \frac{v_t (\varepsilon)}{\,t^2\,}  \, \mathrm{d} t\, =\,0\,.
\end{equation}

When any $($therefore, all$\,)$ of  
(equation 6.16 of the paper)--(equation 6.16c of the paper) hold, then   so does (equation 6.15 of the paper)   with $\, d_N \equiv \delta_N\,$  as in   (equation 6.6 of the paper), and $\,\pi_N^\star( \varepsilon) \equiv \pi_N ( \varepsilon) $ as in  (equation 6.9' of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 31 (Upper bound on series summands) of arXiv:2606.24887, '2606.24887'] Let $ 0 < \epsilon <1$ and $0 < \delta < \frac{1}{4} \epsilon$ be fixed. 
If $d$ satisfies 
\begin{equation}
   1 \le d \le N^{\delta/4}
\end{equation}
then there exist universal constants $C$, $c>0$ such that
    \begin{equation*}
       \abs{ \langle X^{m}\mathbf{e}, \mathbf{e}\rangle } \le N^{-1/2 + \epsilon} , ~~ \text{ for all}~ m \le c \sqrt{d}\log N
    \end{equation*}
    with probability at least $1 - CN^{-\epsilon}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] There exists some $C=C(T)>0$ such that for any $z\in\mathbb Z$,
\begin{equation*}
\limsup_{N\to+\infty}
\mathbb E_N\Big[ \sup_{0\le t\le T} 
|\mathcal V^N_t(h_z)|^2 \Big]
\le C(1+z^4).
\end{equation*}

