body:
[Definition 2 (Regular right edge) of arXiv:2608.27307, '2608.27307'] We call $E_*\in\mb D_0$ a regular right edge of $\bnu$ if
        \begin{align}
                s_{\min}\left(AA^\top-(E_*+g(E_*))(I_M+m(E_*)\Sg)\right) & \geq\tau_0. 
        \end{align}
        $s_{\min}(\cdot)$ denotes the smallest singular value.
        A regular left edge is defined analogously, with the adjacent gap lying to the left of $E_*$.

[Lemma 22 (Mixed Moment Bound) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumption \ref{ass:coefficients} hold. Define the \emph{spatial variation weight} $W: H \times H \to \R$ by:
\begin{equation}

    W(x, y) := (1 + \|x\|_H^{m-1} + \|y\|_H^{m-1})\|x - y\|_H.
\end{equation}
Then there exists a constant $M_2 > 0$, depending only on $T$, $m$ and the Lipschitz constants, such that for all $x, y \in H$ and $t \in [0, T]$, the mild solutions \eqref{eq:mild_solution_eq} satisfy:
\begin{equation}

    \E \left[ \sup_{s \in [t, T]} W\big( X(s; t, x), X(s; t, y) \big) \right] \le M_2 W(x, y).
\end{equation}

[Lemma lem:resolvent-Lipschitz of arXiv:2607.03639, '\vspace{-0.6in}An AI-Assisted Solution to the Signed BAR Conjecture: Uniqueness in the Har'] The function $g$ is bounded and globally Lipschitz on $E$, with
\begin{equation}
 \left\lVert g\right\rVert_\infty\le\frac{\left\lVert h\right\rVert_\infty}{\lambda},
 \qquad
 \operatorname{Lip}(g)\le\frac{K_\Gamma\operatorname{Lip}(h)}{\lambda}.
\end{equation}

[Lemma 17 (Second moment under a constrained strongly convex Gibbs law) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:strong-convex-moment}
Let $K\subset\R^d$ be a compact convex set with nonempty interior and let $\theta_0\in\operatorname{int}(K)$. Suppose $U$ is continuously differentiable on a neighborhood of $K$ and $\beta$-strongly convex on $K$. Then for a probability measure $\check\Pi$ on $\R^d$ such that
    \begin{align*}
    \check\Pi(\d\theta)=Z^{-1}\e^{-U(\theta)}\ind_K(\theta)\d\theta,
    \end{align*}
we have
    \begin{align}
    \int\|\theta-\theta_0\|^2\check\Pi(\d\theta)
    \le \frac{2\|\nabla U(\theta_0)\|^2}{\beta^2}+\frac{2d}{\beta}.
    \end{align}

