body:
[Theorem 10 (Joint probability generating function) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] The joint probability generating function of $(B,R)$ is
\begin{equation}
        \EE[u^Bv^R]
        =\frac{\Ht(uqX;Y)}{\Ht(qX;Y)}
        \frac{\Ht(vX;Y)}{\Ht(X;Y)}.
\end{equation}
Consequently, $B$ and $R$ are independent.

[Lemma lem:moment-bound:uhat of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] { Let} $d\le 3$ { and assume the conditions} of (thm:well-posed of the paper). {Additionally assume that} \nameref{cond:phi:d=3}, \nameref{cond:Q:higher_regularity} hold for $m\ge 2$. Then

\begin{enumerate}[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item There exist $c,C>0$ such that for all $U_0\in\mathcal{H}^0_\mu$ and $t\ge 0$, it holds that
\begin{equation} 
\mathbb{E}\big\|\big(u(t)-\widehat{u}(t),\eta(t)-\widehat{\eta}(t)\big)\big\|^2_{\mathcal{H}^0_\mu}\le Ce^{-ct}\|U_0\|^2_{\mathcal{H}^0_\mu};
\end{equation}

\item There exist positive constants $C$ and $q\in\mathbb{N}$ independent of $U_0$ and $t$ such that
 \begin{equation} 
\mathbb{E} \|(\widehat{u}(t),\widehat{\eta}(t))\|^2_{\mathcal{H}^m_\mu}\le C(\|U_0\|^q_{\mathcal{H}^0_\mu}+1). 
 \end{equation}
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 (Boundary of  weighted $\ell_p$-balls) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] With the above notation, the following hold.
\begin{itemize}
\item[(a)] For every $p>1$, the boundary  $\partial \mathbb B_p^n(a)$ is a $C^1$-hypersurface.  The outer unit normal at $x\in \partial \mathbb B_p^n(a)$ (the Gauss map of $\mathbb B_p^n(a)$ at $x$) is given by
\begin{equation}
\nu(x)=\frac{\nabla F(x)}{\|\nabla F(x)\|}
=
\frac{\left(a_1^p |x_1|^{p-2}x_1,\ldots, a_n^p |x_n|^{p-2}x_n\right)}
{\left(\sum_{i=1}^n a_i^{2p}|x_i|^{2p-2}\right)^{1/2}}.
\end{equation}
Let $q=\frac{p}{p-1}$ be the H\"older conjugate of $p$.  The support function of $\mathbb B_p^n(a)$ is
\begin{equation}
h_{\mathbb B_p^n(a)}(u) := \sup_{x\in \mathbb B_p^n(a)} \langle u, x\rangle
=
\left(\sum_{i=1}^n |u_i/a_i|^q\right)^{1/q}, \qquad u\in \R^n.
\end{equation}
\item[(b)] For every $p>1$, the boundary is $C^2$ near every point $x\in \partial \mathbb B_p^n(a)$ such that $x_i \neq 0$ for every $i=1,\ldots, n$.  If $p\geq 2$, then the boundary $\partial \mathbb B_p^n(a)$ is $C^2$ at every point.
\item[(c)] For all $p>1$, the curvature measures of $\mathbb B_p^n(a)$ do not charge the set $\partial \mathbb B_p^n(a) \cap \{x_1\ldots x_n=0\}$.
\end{itemize}

[Lemma lem:GaussianEigenvalues1 of arXiv:2410.23915, 'Asymptotic Bounds and Online Algorithms for Average-Case Matrix Discrepancy'] Let $X \sim \mathrm{GOE}(m)$. The joint probability density function of the ordered eigenvalues $\lambda_1(X) \leq \ldots \leq \lambda_m(X)$ is given by
        \begin{equation*}
            \lambda \mapsto C_m \exp{-\frac{1}{4}\left\lVert\ifblank{\lambda}{\:\cdot\:}{\lambda}\right\rVert_2^2} \Delta(\lambda)
        \end{equation*}
        on the Weyl chamber $\mathbb{R}^m_\geq \colonequals \{\lambda \in \mathbb{R}^m : \lambda_1 \leq \ldots \leq \lambda_m\}$, where the constant $C_m$ is defined as
        \begin{equation}

            C_m \colonequals 2^{-m(m+3)/4} \prod_{i=1}^m \frac{1}{\Gamma(i/2)}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (Trace incompatibility at the wall) of arXiv:2609.03916, 'Halfspace Theorems for Anisotropic Minimal Surfaces and Perimeter Minimizers'] Let $L\subset H$, let $G:=H\setminus L$, and suppose that on a relatively
open set $\Gamma\subset P$,
\begin{equation}
 \Tr_PL=1\qquad\HH^n\text{-a.e. on }\Gamma.
\end{equation}
Then
\begin{equation}
 |D\chi_L|\llcorner\Gamma=\HH^n\llcorner\Gamma,
 \qquad
 |D\chi_G|\llcorner\Gamma=0.
\end{equation}
Consequently, the identity
\begin{equation}
 |D\chi_G|=\HH^n\llcorner P+|D\chi_L|
\end{equation}
cannot hold when $\HH^n(\Gamma)>0$.

[Lemma 16 (Uniform off-axis scalar bounds) of arXiv:2608.19594, 'Mesoscopic Rectangular Spikes under Subspace Local Laws:\\Outlier Values and Singular Subs'] Let $K\Subset(b,\infty)$ be a compact interval.  For $\theta\ge0$, set
\[
 T_\theta(\zeta):=
 \frac1{1-\theta^2d(\zeta)}
 \begin{pmatrix}
   \phi(\zeta)&\theta d(\zeta)\\
   \theta d(\zeta)&\widetilde\phi(\zeta)
 \end{pmatrix}.
\]
There are $y_0,C_K>0$ such that, uniformly for $x\in K$, $0<|y|\le y_0$, and $\theta\ge0$,
\begin{equation}
  \norm{T_\theta(x+\ii y)}_{\op}\le\frac1{|y|},
  \qquad
  \norm{\left[\Id_2-
  \begin{pmatrix}\phi(x+\ii y)&0\\0&\widetilde\phi(x+\ii y)\end{pmatrix}
  \begin{pmatrix}0&\theta\\\theta&0\end{pmatrix}\right]^{-1}}_{\op}
  \le\frac{C_K}{|y|}.
\end{equation}

[Thm 9 (Scaling limit of the leftmost positive subtree of $T^k$) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] Let $\alpha$ be the unique solution in the interval $(1/2,1)$ to the equation in~\eqref{eq:eq-to-defn-alpha} and recall that $\gamma-1\stackrel{\eqref{eq:gamma-alpha-rel}}{=} \frac{1}{2\alpha}\in (1/2,1)$. 
    Recall also the slowly varying function $\varphi$ of \eqref{eq:good regularity estimates}.
    Then the following convergence in distribution holds for the Gromov--Hausdorff topology: 
    \[\frac{\varphi(k)}{k^{\gamma -1}} \cdot (T^k)^{\lmax} \xrightarrow[k \to \infty]{\mathrm{d}} \mathcal{T}_{\gamma},\]
    where $\mathcal{T}_{\gamma}$ is the self-similar fragmentation tree with self-similarity index $1-\gamma$ and with binary dislocation measure $\nu_{\gamma}$ given by
    \begin{equation}
        \int f(s_1, s_2) \nu_{\gamma} (\mathrm{d}\mathbf{s}) = \int_0^{1/2} f(1-x,x) \, x^{-\gamma} (1-x)^{-\gamma} \, \mathrm{d}x,
    \end{equation}
    for any measurable function $f:[0,1]^2 \to \bbR_{>0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

