[Theorem 21 of arXiv:2603.00353, 'Aldous-type Spectral Gaps in Unitary Groups'] \cite[Cor.~2.4]{collins2006integration} 
    Let $k,d\ge1$, and $i_1,\ldots,i_k,j_1,\ldots,j_k,i'_1,\ldots,i'_k,j'_1,\ldots,j'_k\in[d]$. Then
    \begin{eqnarray} 
        \int_{A\in\U(d)}A_{i_1,j_1}\cdots A_{i_k,j_k}\cdot \overline{A_{i'_1,j'_1}}\cdots \overline{A_{i'_k,j'_k}} ~d\mu_{[d]} = ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nonumber \\
        \sum_{\sigma,\tau\in\sym(k)} \delta_{i_1,i'_{\sigma(1)}}\cdots\delta_{i_k,i'_{\sigma(k)}} \delta_{j_1,j'_{\tau(1)}}\cdots\delta_{j_k,j'_{\tau(k)}}\wg_{k,d}(\tau\sigma^{-1}),
    \end{eqnarray}
    where $\delta_{i,j}$ is the Kronecker delta. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:strong-regularity-condition of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] ),d_{\text{BL},1})\)}]
	A subset \(\mathcal{K}\subset (\mathcal{P}_{\nu}(\mathcal{X}\times [0,1]),d_{\text{BL},1})\) is relatively compact if and only if the following properties hold:
	\begin{enumerate}[label=(\roman*)]
		\item \(\mathcal{K}\) is tight. 
		\item For every \(\varepsilon > 0\), there exists \(m_{\varepsilon}\in \mathbb{N}\) and a partition \(\mathcal{P}_{\varepsilon}=\{A_1,\ldots,A_{m_{\varepsilon}}\}\) of \([0,1]\) such that 
		\begin{equation} 
			\sup_{\mu \in \mathcal{K}} d_{\text{BL},1}(\mu,\mu_{\mathcal{P}_{\varepsilon}}) < \varepsilon.
		\end{equation}
	\end{enumerate}

[Prop 18 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $V$ be such that
\begin{equation*}
    0\leq V\in C^2(\mathbb{R}^d), \quad \overline{\sf L}V\leq \delta_V V \quad \mbox{for some } \delta_V\in(0,\infty).
\end{equation*}    
Then the following assertions hold:
\begin{enumerate}
    \item[(i)] $P_tV\leq e^{\delta_V t}V, t\geq 0$.
    \item[(ii)] $U_{\alpha+\delta_V} |{\sf \overline{L}}V|\leq 2\frac{(\alpha+\delta_V)}{\alpha}V, \quad \alpha>0$.
    \item[(iii)] For every $\varepsilon>0$ we have
    \begin{equation}
        \mathbb{P}_{(s,x)}\left( \sup_{t\in [0,T]} V(X_2(t)) \geq \varepsilon \right)\leq \frac{e^{\delta_V T}}{\varepsilon}V(x), \quad (s,x)\in E.
    \end{equation}
\end{enumerate}

