body:
[Proposition 24 (Cyclotomic-local knot germ) of arXiv:2608.29585, '2608.29585'] Fix a zero-framed knot $K$ and an integer $n\ge2$.  For every $d\ge1$
and $s\in\Z$, the series
\begin{equation}
 \mathscr J_{K,s}(z)=
 \sum_{k\ge0}b_k^{(n)}(K;q)U_k(z)
\end{equation}
converges in $\mathscr A_{d,s}$.  If $i\in\Z_{\ge0}$ and
$z_i\equiv z_s\pmod{\pi_d}$, then continuous evaluation at
$u_s=z_i-z_s$ gives
\begin{equation}
 \mathscr J_{K,s}(z_i)=J_i^{SU(n)}(K;q).
\end{equation}

[Lemma lem_A of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] Suppose the bootstrap assumptions hold, we have
    \begin{equation}
        \left\lVertA-1\right\rVert_{H^s}\lesssim\frac{\epsilon^2}{t^{\frac{2}{3}-\delta_0}}\ln (2+t)+\frac{\lambda(\epsilon+\lambda)}{H^{\frac{3}{2}}},
    \end{equation}
    \begin{equation}
        \left\lVertA-1\right\rVert_{W^{s-3,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{3}{2}-\delta_0}}(\ln (2+t))^2+\frac{\lambda(\epsilon+\lambda)}{H^2}
    \end{equation}
and
\begin{equation}
        \left\lVertA-1\right\rVert_{W^{s-1,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{7}{6}-\delta_0}}(\ln (2+t))^2+\frac{\lambda(\epsilon+\lambda)}{H^2}.
    \end{equation}

