[Lemma lg of arXiv:2411.05204, '\Large\bf Sample Path Properties of the Fractional Wiener--Weierstrass Bridge'] There exist constants $C(s)\in[\frac{1}{L},L],~s\in[0,1]$ such that
\begin{align}
{\mathbb P}\left(\limsup_{t\in[0,1],\,t\to s}\frac{|X(t)-X(s)|}{\Psi(|t-s|)}=C(s)\right)=1.
\end{align}
In addition, \begin{align}
{\mathbb P}\left(\limsup_{\delta\to 0}\sup_{|t-s|<\delta}\frac{|X(t)-X(s)|}{\widetilde{\Psi}(|t-s|)}\leq L\right)=1,
\end{align}where $\widetilde{\Psi}(x)=\sigma(x)\sqrt{-\log x}$.

[Corollary coro:lower_bound_on_partial_square_term_capacity of arXiv:2505.07145, 'Nonamenable Poisson zoo'] Let $A \subset \subset V(G)$ be finite and connected, $B \subseteq \partial_{\mathrm{ext}} A$. Then we have
	\begin{equation}

		\sum_{y \in B} P_y^2 \left( T_{\overline{A}}^+ = +\infty \right) \geq
		(1 - \rho(G))^2 \cdot \left| \overline{A} \right| - ( | \partial_{\mathrm{ext}} A| - |B|).
	\end{equation}

