[Lemma 7 of arXiv:2604.07697, 'Stochastic fractional heat equation with general rough noise'] \begin{itemize}
  \item[(a)]  There exist   finite positive constants $c_{1}$ and $c_{2}$
 such that  for all $t>0$ and $x \in \mathbb R$,
\begin{align}
c_{1}t\left(t^{1/\alpha}+ |x| \right)^{-1-\alpha}\le G_{\alpha}(t, x)\le c_{2}t\left(t^{1/\alpha}+|x| \right)^{-1-\alpha}.
\end{align}


\item[(c)]   There exists a positive constant $c>0$ such that  for all $t>s>0$  and $x\in \mathbb R$,

 \begin{equation}
\begin{split}
 \left|G_{\alpha}(t, x) -G_{\alpha}(s, x) \right|
\le  &\,  c \frac{(t-s)}{s} G(s, x).
\end{split}
\end{equation}
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition WPD-NP-main of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $N \in \left\{ {0,1, \cdots ,10} \right\} $, $n \in {\mathbb{Z}^ + } \cup \left\{ 0 \right\}$ and $t \in \mathrm{supp}_t\ w_{q + 1,n + 1}^{(n)}$, there exists a real number $\alpha \in \left( {\frac{\beta }{{b}},\beta } \right)$ such that the $\left( {n + 1} \right)$-step Newtonian perturbation $w_{q + 1,n + 1}^{(n)}\left( {t,x} \right)$ satisfies
\begin{equation}
{\left\| {w_{q + 1,n + 1}^{(n)}} \right\|_N} \lesssim \mu _{q + 1}^{ - 1}{\delta _{q + 1}}\lambda _q^{N + 1}l_q^{ - \alpha }  ,
\end{equation}
and
\begin{equation}
{\left\| {{{\bar D}_{t,q}}w_{q + 1,n + 1}^{(n)}} \right\|_N} \lesssim {\delta _{q + 1}}\lambda _q^{N + 1}l_q^{ - \alpha }  .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

