[Proposition 17 of arXiv:2607.08696, 'Spectrum of Directed Inhomogeneous Random Graphs'] Let $\tau \in (0,1)$. For any $z\ \in \mathbb{D}_{R,\eps}$, there exists a positive constant $C_{|z|}$ depending on $|z|$ (independent of $\tau)$, such that 
    \begin{equation}
        \int_{-\tau}^\tau |\log|x||\,d\thetalimit(x) \le C_{|z|} \tau |\log(\tau)|.
    \end{equation}
Moreover the distribution $\vartheta_z$ is compactly supported.

[Proposition prop:vol is sqdet of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] If we denote $\vol$ for the volume with respect to the Euclidean volume form, and if $Q$ is a positive definite quadratic form on $\mathbb{R}^m$, we have 
  \begin{equation}
    \vol(B_Q^\circ)=b_m \sqrt{\det Q}
  \end{equation}

[Lemma 19 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $\left(\psi_t^{(1)}\right)_{t\geq 0}$ be a solution to the first equation in \eqref{eq:fast system simplified hopf 2} with $||\bm{\sigma}_1||^2\neq 0$. Consider $\alpha=\alpha(\lambda)\in\C$ such that $\underset{\lambda\to\lambda^*}{\lim} \alpha(\lambda)=\alpha(\lambda^*)\in i \R\setminus\{0\}$. Then, it holds that
\begin{align}
    \left| \frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)} - e^{-i \operatorname{Im}(\alpha(\lambda))\tau} \right| = -\operatorname{Re}(\alpha(\lambda)) \tau \Delta(\tau) + \mathcal{O}\left( \operatorname{Re}(\alpha(\lambda))^2 \right) ,
\end{align}
with $\Delta(\tau)\neq 0$ for almost every $\tau \geq 0$. In particular, for almost every $\tau\ge0$, we have that
\begin{align*}
    &\frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)}
    = e^{-i \operatorname{Im}(\alpha(\lambda^*))\tau} 
    + \cO \left(\operatorname{Re}(\alpha(\lambda))\right) + \cO\left( \operatorname{Im}(\alpha(\lambda)-\alpha(\lambda^*))\right) .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm comparison of arXiv:2605.14910, 'Sharp Phase Transition for the Formation of Infinite Tubes'] Let $1\le k\le d-1$.
  Then
  \begin{equation}
  p_c^{\mathrm{core}}(k,d)
  \le p_c^{\mathrm{tube}}(k,d)
  \le1-p_c^{\mathrm{shield}}(k+1).
  \end{equation}
  Moreover, $p_c^{\mathrm{tube}}(1,d)=p_c^{\mathrm{bond}}(d)$, and
  \begin{equation}
  p_c^{\mathrm{tube}}(k,d)
  <1-p_c^{\mathrm{bond}}(k+1)\quad\text{for $k\ge9$.}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2604.01852, 'The on/off Brownian snake'] Fix $s > 0$ and let $x=(b,s') \in E$ with $s'<s$. We define the time changes
\begin{equation*}
    \eta(s,u,i) \coloneqq \inf \Big\{ t' \geq 0: \int_{r=0}^{t'} \mathbbm{1}_{\{\text{Res}^i_r(s) > 0\}} dr > u\Big\};
\end{equation*}
\begin{equation*}
    \eta(s,u,i, \rm a) \coloneqq \it \inf \Big\{ t' \geq 0: \int_{r=0}^{t'} \mathbbm{1}_{\{\text{Res}^i_r(s) > 0, A^i_r(s) = 1\}} dr > u\Big\};
\end{equation*}    
\begin{equation*}
    \eta(s,u,i, \rm d) \coloneqq \it \inf \Big\{ t' \geq 0: \int_{r=0}^{t'} \mathbbm{1}_{\{\text{Res}^i_r(s) > 0, A^i_r(s) = 0\}} dr > u\Big\}.
\end{equation*}
Then the maps $u \mapsto \text{Res}^i_{\eta(s,u,i)}(s)$, $u \mapsto \text{Res}^i_{\eta(s,u,i, \rm a)}(s)$ and $u \mapsto \text{Res}^i_{\eta(s,u,i, \rm d)}(s)$ are stopped reflecting Brownian motions $\mathbb{N}_x$-a.e. Furthermore we have that the local times of $(\text{Res}^i_{\eta(s,u,i)}(s))_{u \geq 0}$, $(\text{Res}^i_{\eta(s,u,i, \rm a)}(s))_{u \geq 0}$ and $(\text{Res}^i_{\eta(s,u,i, \rm d)}(s))_{u \geq 0}$ at level $0$, denoted by $\hat{\ell}_{s,i}$, $\hat{\ell}^{\rm a}_{s,i}$, $\hat{\ell}^{\rm d}_{s,i}$, are such that 
    \begin{equation*}
        \mathbb{N}_x\Big(\hat{\ell}_{s,i}(\infty)\Big) = \mathbb{N}_x\Big(\hat{\ell}^{\rm a}_{s,i}(\infty)\Big) +  \mathbb{N}_x\Big(\hat{\ell}^{\rm d}_{s,i}(\infty)\Big) = 1.
    \end{equation*}
    \begin{proof}
        Consider the open set $D=\mathbb{R}^d \times [0,s)$ in the setting of Lemma \ref{lemma snake exit open set general}. In this setting the process $(U_{\eta_r}, r \geq 0)$ is exactly the process given by $(\text{Res}^i_{\eta(s,u,i)}(s))_{u \geq 0}$ as
        \begin{equation*}
            \tau^s(X_t) = \inf \{r \geq 0 | (B_t(r), S_t(r)) \notin \mathbb{R}^d \times [0,s)\} = \inf \{r \geq 0 |  S_t(r) \geq s \} = H_t(s),
        \end{equation*}
        and because the Residual process is the difference between the excursion $\zeta^i_t$ and the age process $H^i_t(s)$.
        \par
        Now instead consider the set $D=\mathbb{R}^d \times [0,\infty) \backslash \{s\}$ in the setting of the previous lemma. In this instance the process $(U_{\eta_r}, r \geq 0)$ is exactly the process given by $(\text{Res}^i_{\eta(s,u,i, \rm a)}(s))_{u \geq 0}$  
        \begin{equation*}
            \tau^s(X_t) = \inf \{r \geq 0 | (B_t(r), S_t(r)) \notin \mathbb{R}^d \times [0,\infty) \backslash \{s\} \} = \inf \{r \geq 0 | S_t(r) = s\}, 
        \end{equation*}
        i.e. if the subordinator $S_t(\cdot)$ can take the value $s$, then the particle is in the active state.
        \par
        The final case follows as 
        \begin{equation*}
            \text{Res}^i_t(s) = \text{Res}^i_t(s)\mathbbm{1}_{A_t(s) = 0} + \text{Res}^i_t(s)\mathbbm{1}_{A_t(s) = 1}
        \end{equation*}
        and so the process $(\text{Res}^i_{\eta(s,u,i, \rm d)}(s))_{u \geq 0}$ is a reflecting Brownian motion as it is defined by first taking the process $(\text{Res}^i_{\eta(s,u,i)}(s))_{u \geq 0}$ and removing excursions that correspond to $(\text{Res}^i_{\eta(s,u,i, \rm a)}(s))_{u \geq 0}$. For the final part we use \eqref{equation local time contribution} and note that
        \begin{equation*}
            \mathbb{N}_x\Big(\hat{\ell}_{s,i}(\infty)\Big) = P^\xi_x\Big(\inf(\{y: S(y) \geq s\})<\infty \Big) = 1 >  P^\xi_x\Big(\inf(\{y: S(y) = s\})<\infty\Big) = \mathbb{N}_x\Big(\hat{\ell}^{\rm a}_{s,i}(\infty)\Big),
        \end{equation*}
        where the inequality can be seen in e.g. \cite[Theorem III.5]{bertoin1996levy} and where $S$ denotes the subordinator component of $\xi$. Furthermore we have that 
        \begin{equation*}
            \mathbb{N}_x\Big(\hat{\ell}^{\rm d}_{s,i}(\infty)\Big) = 1 - P^\xi_x(\inf(\{y: S(y) = s\})<\infty) = P^\xi_x(\inf(\{y: S(y) = s\})=\infty) \in (0,1),
        \end{equation*}
        where we note that the final probability is in $(0,1)$ as the subordinator can either cross or hit level $s$, see e.g.\ \cite[Theorem III.5]{bertoin1996levy}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2608.03771, '\vspace{-5ex}\bfseries\scshape{Local law and delocalization for the Sachdev--Ye--Kitaev mo'] Let $\varepsilon\in(0,\frac{1}{2})$ and $q$ be even such that $2\leqslant q\leqslant N^{\frac{1}{2}-\varepsilon}$. Let $H_q$ be the Hamiltonian defined in \eqref{eq:sykhamil}, and let $\psi_j$ be the eigenvectors corresponding to the eigenvalues $\lambda_j$.
    Then,
    \begin{equation}

    \frac{1}{D}\sum_{j=1}^D\E[\mathrm{IPR}(\psi_j)]\le C\alpha_{N,q}^{\frac{1}{5}},
    \end{equation}
    for a $q$-independent constant $C>0$. The same bound holds with $\psi_j$ being replaced with $\psi_j^{\pm}$ being the eigenvectors corresponding to the parity sectors $H_q^{\pm}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 22 of arXiv:2601.16377, '2601.16377'] Given an equilibrium measure $\boldsymbol{\mu}$, the $h$-th \emph{effective potential} is the function of $x \in [\hat{a}'_h,\hat{b}_h']$ defined through
 \begin{equation}
 V^{{\textnormal{eff}}}_h(x)= V_h(x) - \sum_{g =1}^H 2\theta_{h,g}
\int_{\hat a'_{g}}^{\hat b'_g} \log|x-y|\mu_{g}(y)\dd y.
\end{equation}

