[Defn 25 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $  {\boldsymbol v}\in \mathbb R^d$. We define the function $\z_{  {\boldsymbol v}}:I\to \mathbb R$ by 
    \begin{equation*}
         \z_{  {\boldsymbol v}}(   y_1-   y_2) :=\sum_{\substack{r_1+...+r_d=p\\s_1+...+s_d=p}}\frac{  {\boldsymbol v}^{   r+   s}}{   r!   s!}\boldsymbol \eta_{   r,   s}(   y_1-   y_2).
    \end{equation*}

[Proposition \cite{lawler80selfavoiding} of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Two-sided LERW $\hat\eta$ satisfies the following properties:
\begin{enumerate}
	\item the law $\hat\eta$ is absolutely continuous with respect to the law of $\eta$;
	\item $T^k\eta$ converges weakly to $\hat\eta$ as $k\rightarrow\infty$;
	\item $\hat\eta$ is stationary with respect to $T$, i.e., $T\hat\eta\stackrel{d}{=}\hat\eta$;
	\item $\eta$ and $\hat\eta$ are ergodic with respect to $T$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 (Intrinsic Taylor expansion) of arXiv:2608.12225, 'Higher-order variation and\\ pathwise It\^o calculus on manifolds'] Let $p\geq1$, $f\in C^p(M)$, and let $K\subset M$ be compact. For
$(x,y)\in {\mathcal U}\cap K^2$, we have
\begin{equation}
\begin{split}
    f(y)-f(x)
    &=
    \sum_{k=1}^p
    \frac1{k!}
    (\nabla^{(k)}f)_x
    \bigl(e_\nabla(x,y)^{\otimes k}\bigr)
    +
    R_{p,f}(x,y),

\end{split}
\end{equation}
where
\begin{equation}
    |R_{p,f}(x,y)|
    \leq
    \omega_{f,K}(|e_\nabla(x,y)|)
    |e_\nabla(x,y)|^p,\qquad \omega_{f,K}(r)\longrightarrow0
    \qquad\text{as }r\downarrow0.

\end{equation}

[Lemma lem:cond-lem of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $\{ \mathbf{X} _n\}$ be an adapted sequence of $\mathcal{S}_d$-valued random matrices with conditional means $ \mathbb E  ( \mathbf{X} _n | \mathcal{F}_{n-1}) =  \mathbf{M} _n$. Further, suppose there is a predictable and integrable sequence of $\mathcal{S}_d$-valued random matrices $\{ \widehat  \mathbf{X} _n \}$ such that $\lambda_{\min}( \mathbf{X} _n - \widehat  \mathbf{X} _n ) \geqslant -1$. Let
\begin{equation}
      \mathbf{E} _n =  \exp(\gamma_n( \mathbf{X} _n - \widehat{ \mathbf{X} }_n)  - \psi_{\mathrm{E}}(\gamma_n) ( \mathbf{X} _n - \widehat{ \mathbf{X} }_n)^2) ,\quad  \mathbf{F} _n = \exp(\gamma_n ( \mathbf{M} _n - \widehat{ \mathbf{X} }_n)  ),
\end{equation}
where $\{ \gamma_n \}$ are predictable $(0,1)$-valued scalars. Then,
\begin{equation}
     \mathbb E  ( \mathbf{E} _n|\mathcal{F}_{n-1}) \preceq  \mathbf{F} _{n}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sobolev of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] On the unit sphere $\mathbb S^{N-1}$, for any $g \in W^1_2(\mathbb S^{N-1})$, we have the Sobolev inequality
    \begin{align*}
        \left\lVertg\right\rVert_q^2\leq \frac{q-2}{N-1} \left\lVert\nabla g\right\rVert_2^2+\left\lVertg\right\rVert_2^2\,,
    \end{align*}
    where $q=\frac{2(N-1)}{N-3}$.    
    Switching to $\mathbf{S}_N$, for any $f\in W^1_2(\mathbf{S}_N)$, 
    \begin{align*}
        \left\lVertf\right\rVert_q^2\leq \frac{N(q-2)}{N-1} \left\lVert\nabla f\right\rVert_2^2+\left\lVertf\right\rVert_2^2\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

