[Theorem the: characterization of subsequential limits of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] The following property holds with probability one:
	\begin{equation*}
		\int_0^t \angled{\bar r\left(\bar\boldsymbol{\mu}_s\right) h_g^x + h_g^y}{\bar\boldsymbol{\mu}_s}ds < \infty \quad \text{for all} \quad t \geq 0.
	\end{equation*}
	Furthermore, for all $t \geq 0$ and $\varphi \in C_c^1(\mathbbm{R}_+^3)$, we have:
	\begin{align*}
		\angled{\varphi_t}{\bar\boldsymbol{\mu}_t} &= \angled{\varphi_0}{\bar\boldsymbol{\mu}_0} + \lambda_0 \int_0^t \varphi_s(0, 0)ds - \int_0^t \angled{\varphi_s\left[\bar r(\bar \boldsymbol{\mu}_s)h_g^x + h_g^y\right]}{\bar\boldsymbol{\mu}_s}ds \\
		&+ \int_0^t \angled{\partial_t\varphi_s + \bar r\left(\bar \boldsymbol{\mu}_s\right)\partial_x\varphi_s + \partial_y\varphi_s}{\bar\boldsymbol{\mu}_s}ds.
	\end{align*}

