[Prop 39 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $\varepsilon\in (0,1)$ and $z\in D$.
On the event $\{\ell_{0,b}(z) = b,\, 2\pi V_{A_{0,b}}(z)<\vert \log\varepsilon\vert\}$,
\begin{displaymath}
\PP(z\in \Ns_{\varepsilon}(A)\vert A_{0,b},\ell_{0,b}) =
\sum_{k=0}^{+\infty} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\E[\psi_{2k+1, A} \vert A_{0,b},\ell_{0,b}](z)}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}.
\end{displaymath}
On the event $\{\ell_{0,b}(z) = b, \CR(z,D\setminus A_{0,b})\in (\varepsilon,\varepsilon^{-1})\}$,
\begin{displaymath}
\PP(z\in \widetilde{\Ns}_{\varepsilon}(A)\vert A_{0,b},\ell_{0,b}) =
\sum_{k=0}^{+\infty} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\E[\tilde{\psi}_{2k+1, A} \vert A_{0,b},\ell_{0,b}](z)}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}.
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 23 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] Let $0<\gamma<\sqrt{2n}$. Then
	\begin{align*}	Z_\gamma=e^{\gamma^{-2}F(\Lambda)}\E\left[\exp\left(-\frac{na_n\Lambda}{\gamma^2}\scalar{e^{nu}}{\mu^{\gamma h}-1-\gamma h}\right)\right],
	\end{align*}
	where
	\begin{align*}
		F(\Lambda)=-\frac{n^2}2{\mathfrak p}(u,u)-na_n\scalar{\Lambda e^{nu}+nQu}{1}.
	\end{align*}

