[Lemma lem_P_n of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that
$n \in \mathbb{N}$. Then
\begin{trivlist}
\item[(i)] The map $\tilde{P}_n$ is an   ${U}$-orthogonal projection in  ${U}$ (with range equal to ${U}_n$); in particular $\Vert\tilde{P}_n\Vert_{\mathscr{L}(U)}=1$.
\item[(ii)] For all $ u,v  \in U$ and $ {u}^\ast \inU^{\prime }$
\begin{align}  
  \duality{P_n u^\ast }{ v} &= \ip{{P}_{n} {u}^\ast}{v}{H} =\duality{u^\ast }{\tilde{P}_n v} ,
\notag
\end{align}
\item[(iii)]  $\Vert {P}_n\Vert_{\mathscr{L}(U^\prime)}=1$.
\end{trivlist}
Moreover,
\begin{trivlist}
\item[(iv)] For all
 $ u  \in U$ and $ {u}^\ast \inU^{\prime }$,
 \begin{align}
 &\lim_{n \to \infty }  \left\vert{P}_{n} u^\ast -u^\ast \right\vert_{U^\prime}=0,
\notag  \\

 &\lim_{n \to \infty }  \left\vert\tilde{P}_{n} u -u\right\vert_U =0.
\end{align}
\end{trivlist}

