[Theorem thm:Fnk-Mnk of arXiv:2508.12464, 'On the Fitness Landscape in the $\NK$ Model'] For any $\alpha\in (0,1],$ we have that 
	\begin{align*}
		\lim_{N\to\infty}\mathbb{E} F_{N,K}(\beta)&=\left\{\begin{array}{ll}
			\ln 2+\frac{\beta^2}{2},&\forall \beta<\beta_c,\\
			\\
			\beta \beta_c,&\forall \beta \geq \beta_c.
		\end{array}\right.
	\end{align*}
	It follows from (equation eqn:GSEbounds of the paper) that
	$\displaystyle\lim_{N\to\infty}\mathbb{E} M_{N,K}=\beta_c$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 13 of arXiv:2604.00474, 'Trap behaviors for Brownian motions'] Let $Z^\dagger =\{Z_t, \, t < T_D(Z)\}$ be the part process on the bounded domain $D$ of $Z= \{Z_t\}_{t \geq 0}$ with $Z_0=x \in D$. If there exists $\beta \in (0, 1)$ such that
\begin{align}
\int_{D} \mathbf{P}_x(T_D(Z^\dagger) \leq t) \, dx   \simeq   t^\frac{\beta}{2} \quad \textrm{as } t \to 0+ 
\end{align}
then we say that $Z$ exhibits a trap behaviour on $D$.

[Theorem thm:critgauge of arXiv:2412.04607, 'Asymptotics of the partial \(n\)-fold dimer model'] For any \(\vb*{\alpha} \in \mathcal{M}_\mathbb{R}\) and weight function \(w\) there is a unique gauge-equivalent weight function \(w'\) with the property that for all \(v\) the sum of weights of tiles containing vertex \(v\) (counted with multiplicity) is \(\alpha_v\), that is 
\(\sum_{t} t_v w'(t) = \alpha_v\).
The corresponding gauge transformations \(f\colon V\to \mathbb{R}_{>0}\) are exactly those which solve the "criticality equations" 
\begin{equation} 
\frac{x_v \partial_{x_v} P}{P} = \alpha_v
\end{equation}
with \(x_v = f(v)\). The growth rate of \(Z_{w,\vb{n},N}\) is 
\begin{equation}
\sigma(w, \vb*{\alpha}) \coloneq \lim_{n_v, N\to \infty} \frac1N \log Z_{w,\vb{n},N} = \log P(\vb{x}) - \sum_v \alpha_v \log(\mathrm{x}_v) 
\end{equation}
for any solution \(\vb{x}\) to ((eqn:crit of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor22 of arXiv:2412.04334, 'Fractional counting process at L\'{e}vy times and its applications'] If $\{Y_n, n\geq 1\}$ are integer-valued discrete random variables, we set
    \begin{equation*}
        b_s^{*m} = \mathbb{P}\left[Y_1+Y_2+\cdots +Y_m= s\right],\;\; s\in\mathbb{N}_{0}.
    \end{equation*}
    Then, for $s\in \mathbb{N}_{0}$, we have that
    \begin{align}
        \mathbb{P}\left[Z(t)=s\right]= &\;\mathbb{I}_{\{ s= 0\}} \sum_{k=0}^{\infty}\frac{(\zeta )_k\mathit{\Gamma } ( \vartheta )(-\lambda_{\theta})^k}{k!\mathit{\Gamma } (\mu k+ \vartheta )} \mathbb{E}\left[(H(t))^{\theta k}\right]\\ & + \mathit{\Gamma } ( \vartheta )\sum_{m=1}^{\infty}\frac{\lambda_{\theta}^m(\zeta )_m}{m!}b_s^{*m} \sum_{l=0}^{\infty}\frac{(\zeta  + m)_{l}(-\lambda_{\theta})^l}{l! \mathit{\Gamma } (\mu (l+m)+ \vartheta )}\mathbb{E}\left[(H(t))^{\theta(l+m) }\right].\nonumber
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Covariance-existence criterion) of arXiv:2607.09994, '2607.09994'] Suppose Assumptions~\ref{ass:stationarity}, \ref{ass:innovations} and \ref{ass:perron-excitation} hold. Then the following are equivalent:
\begin{enumerate}
    \item the stationary solution is square-integrable, \( \mathbb E\|Z\|^2<\infty \);
    \item the second-order spectral radius satisfies \( \rho(\Top)<1 \).
\end{enumerate}
Equivalently,
\begin{equation}
\mathbb E\|Z\|^2<\infty
\quad\Longleftrightarrow\quad
\rho(\Tmat)<1.

\end{equation}

When \eqref{eq:main-equivalence} holds, the regime-weighted second moments \(M_1,\ldots,M_M\) are the unique finite solution of
\begin{equation}
M_j
=
\sum_{i=1}^M p_{ij}A_jM_iA_j^\top+\pi_jQ_j,
\qquad j=1,\ldots,M.

\end{equation}
Equivalently, in vectorised form,
\begin{equation}
\operatorname{vec}(M)
=
\Tmat\operatorname{vec}(M)+q,

\end{equation}
and therefore
\begin{equation}
\operatorname{vec}(M)
=
(I-\Tmat)^{-1}q.

\end{equation}

Moreover, the following second-order quantities are well-defined.
\begin{enumerate}
    \item The covariance matrix is
    \begin{equation}
    \Sigma
    =
    \operatorname{Var}(Z)
    =
    \mathbb E[ZZ^\top]
    =
    \sum_{j=1}^M M_j.

    \end{equation}

    \item For components \(Z^a\) and \(Z^b\),
    \begin{equation}
    \operatorname{Var}(Z^a)=\Sigma_{aa},
    \qquad
    \operatorname{Cov}(Z^a,Z^b)=\Sigma_{ab}.

    \end{equation}

    \item If \(\Sigma_{aa}>0\) and \(\Sigma_{bb}>0\), then
    \begin{equation}
    \operatorname{Corr}(Z^a,Z^b)
    =
    \frac{\Sigma_{ab}}{\sqrt{\Sigma_{aa}\Sigma_{bb}}}.

    \end{equation}
\end{enumerate}

[Defn tfd of arXiv:2606.11043, 'Thick points under Gaussian free field dynamics'] Let $\varPhi$ be a realization of the OU-GFF.
    For $x\in D$ we define 
    \begin{align}
        \begin{aligned}

        &\gamma_x^{+}(t): = 
        \limsup_{\varepsilon\to0}
        \frac{\Phi_{\varepsilon}(x,t)}{\ln(\frac{1}{\varepsilon})}, \\
        &\gamma_x^{-}(t):= \liminf_{\varepsilon \to 0 } \frac{\Phi_{\varepsilon}(x,t) }{\ln\left(\frac{1 }{\varepsilon }\right )  }, \\
        &\gamma_x(t): = \begin{cases}
         \gamma_x^+(t) & \text{ if } \gamma_x^+(t)=\gamma_x^-(t),\\
        \dagger& \text{else}.\end{cases}
        \end{aligned}
    \end{align}
   We call them the sup-thickness function, inf-thickness function and thickness function respectively.

