      there exist an FS $(\tau_n)$ for $\mathbb{C}$ such that for each $n\in \mathbf{N}^+$, $H^{\tau_n}\in \mathcal{L}_s(A^{\tau_n})$.
  \item [$(2)$] Suppose that $H\in\mathcal{L}^\mathbb{C}_s(A)$ and $(\tau_n)$ is an FS for $\mathbb{C}$. Then $(\tau_n,H^{\tau_n}.A^{\tau_n})$ is an FCS for $H_{\bullet}A\in\mathcal{V}^\mathbb{C}$, and $H_{\bullet}A$ can be expressed as
      \begin{equation}
      H_{\bullet}A=\left((H_0A_0)I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}
      (H^{\tau_n}.A^{\tau_n})I_{\rrbracket{\tau_{n-1},\tau_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{C},\quad \tau_0=0.
      \end{equation}
      Furthermore, if $(\widetilde{\tau}_n)$ is also an FS for $\mathbb{C}$, then $H_{\bullet}A=X$ where $X$ is given by
      \begin{equation*}
      X=\left((H_0A_0)I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}
      (H^{\widetilde{\tau}_n}.A^{\widetilde{\tau}_n})I_{\rrbracket{\widetilde{\tau}_{n-1},\widetilde{\tau}_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{C},\quad \widetilde{\tau}_0=0.
      \end{equation*}
      In this case, we say that the expression of \eqref{HA-expression0} is independent of the choice of FS $(\tau_n)$ for $\mathbb{C}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 20 of arXiv:2609.03777, '2609.03777'] Let $N,r\in\ZZ_{>0}$. For $\tau\in C$ and $\mu_1,\mu_2\in\Lambda_\tau$ with $\mu_1\ordN\mu_2$ and $\mu_1\succ\mu_2$, we have
