[Proposition thm3 of arXiv:2411.13430, 'Optimal subelliptic super-Poincar\'e and isoperimetric inequalities on stratified Lie grou'] Assume as in Theorem (thm1 of the paper) except that $n_1 = 1$. If $p = \alpha + 1$ then $I_\mu \gtrsim \mathcal{U}_1$, and otherwise if $p > \alpha + 1$ then $I_\mu$ satisfies 
    \begin{equation}
        I_\mu \gtrsim_\delta \mathcal{U}_r, \quad r = \frac{(\alpha+1-\delta)p}{\alpha+1-\delta + \alpha(p-\delta)} \in \left[1, \frac{(\alpha+1)p}{\alpha+1+\alpha p}\right)
    \end{equation}
    for each $\delta \in (0, 1]$ and where $\gtrsim_\delta$ indicates the constant depends on $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:projection-FMM of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $ \mathsf{P}_{ n}$ a point process with $ n$ distinct points a.s.. Then  for $ 1\leqslant k<n$, we have the projection
\begin{align*}
 \mu ^{ (k)}_{ \mathsf{P}_{ n}}  = \frac{ 1}{(n-k)!} \mu ^{(n)}_{ \mathsf{P}_{ n}}(\cdot ,\dots ,\cdot , \mathbb{R}^{ d}\times \dots \times \mathbb{R}^{ d}).
\end{align*}

[Prop counterexample sigma=0 of arXiv:2505.12127, 'Generalised principal eigenvalues and global survival of branching Markov processes'] We suppose that $\sigma=0$. Then we have the inequalities
\begin{align}
\lambda'(L_0)\leq -D,\\
\lambda''(L_0)\geq \frac{4}{5}-\frac{D}{5}.
\end{align}
In particular we obtain
\begin{equation}
    \lambda''(L_0)>\lambda'(L_0).
\end{equation}

[Proposition thm:potential-single of arXiv:2602.19192, 'Bakry--\'Emery Curvature of the Fractional Laplacian\\ via Fractional Brownian Covariance'] For $f(x) = \cos x$ and $V(x) = -\omega^2\cos x$:
\begin{equation}
  \frac{\Gamma_{L,2}(f,f)(x)}{\Gamma(f,f)(x)}
  = \frac{1 + \alpha^2\cos 2x + \tfrac{\omega^2}{2}(\cos x + \beta\cos 3x)}
         {1 + \alpha\cos 2x},
\end{equation}
where
$\alpha(\gamma) = 1 - 2^{\gamma-1}$ and
$\beta(\gamma) = (2^{\gamma+1} - 3^\gamma - 1)/2$.
At $\gamma = 1$: $\alpha = \beta = 0$, giving
$\Gamma_{L,2}/\Gamma = 1 + \frac{\omega^2}{2}\cos x$
with minimum $1 - \omega^2/2$ at $x = \pi$.

[Lemma lem:T1-T2 of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] Define
\begin{align}
    T_{1, n, q} &:= \sum_{k = 1}^n \frac{H(k,q) I(k, q)}{k^2} \cdot \int_0^1 \frac{u^{k+q-1} (1-u)^{1 - q}}{1 + u} \, du, \\ 
    T_{2, n, q} &:= \int_0^1 \frac{u^{n + q} (1 - u)^{-q}}{1 + u}\, du \sum_{k = 1}^n (-1)^{n - k} \frac{H(k, q) I(k, q)}{k^2},
\end{align}
where $H(k, q)$ is as in (equation eq:H_defn of the paper) and
\begin{equation}
    I(k, q) := \bigg(\int_0^1 u^{k + q - 1} (1 - u)^{-q} \, du\bigg)^{-1} = \frac{\Gamma(k + 1)}{\Gamma(k + q)\Gamma(1 - q)}.
\end{equation}
Then for any $n \ge 0$,
\begin{equation}
    \mathbb{E}[\tilde{Z}_{n + 1}^2] = T_{1, n, q} + 2 \, T_{2, n, q}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2605.17494, 'Generalized intersection exponents and local cut points for three-dimensional Brownian loo'] There exist constants $c_1,c_2$ such that the following. For every $0<\epsilon<\frac{1}{2}$, define
    $$V^-=((u+A_{\frac{1}{20}})\cup \mathcal{B}_{\frac{\epsilon}{2}}(u))\cap \mathcal{B}_e, V=((u+A)\cup \mathcal{B}_{\epsilon}(u))\cap \mathcal{B}_e.$$
    Then if $x \in S_0,|x-u| \le \frac{\epsilon}{4}$,
\begin{equation}
    \Pb^{x}(B[0,T_1] \subseteq V^-) \ge c_1\epsilon^{c_2}.    
    \end{equation}

