[Lem 31 (Spatial Markov property at level $7\ell$) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] Fix $\ell\in\mathrm{GoodScales}$ and $k,k'\geq 7\ell+1$. Let $\DMC$ and $\DMC'$ be defined under the black-golden coupling $\mathbb{P}_{k,k'}$ of~\cref{defn:black-golden coupling}. Then the following assertions are true:
\begin{enumerate}
\item 
For $m\in\intervalleentier{7\ell +1}{k}$ and  $m'\in\intervalleentier{7\ell +1}{k'}$, the $\Gf_\ell$-conditional distribution of $(\DMC(H_{7\ell}), \DMC'(H'_{7\ell}))$ on the event $\{\DMC(H_{7\ell}-1)=m, \DMC'(H'_{7\ell}-1)=m'\}$ is given by
\begin{align}
\Law\left((\DMC(H_{7\ell}), \DMC'(H'_{7\ell})) \ | \  \Gf_\ell \right) = \Law((B_m,B_{m'}) \ | \ B_m \leq 7\ell, B'_m \leq 7\ell).
\end{align}
\item Conditionally on $\sigma(\Gf_{\ell}, (\DMC(H_{7\ell}),\DMC'(H'_{7\ell}))$, the chains $(\DMC(H_{7\ell}+t))_{t\geq 0}$ and $(\DMC'(H'_{7\ell}+t))_{t\geq 0}$ have the distribution of $\DMC$ and $\DMC'$ under the black-golden coupling $\bbP_{\DMC(H_{7\ell}),\DMC'(H'_{7\ell})}$.
\end{enumerate}

[Lemma 19 of arXiv:2607.17943, 'Coadjoint averaging and cross-scale fluxes in a fast-slow stochastic Euler-Arnold system o'] For the quadratic observable $Q$ introduced in \emph{(\ref{Eq:QuadraticObservableGeneralizingEnergyEnstrophy})}, any $z$ in the interior of $\mathcal{A}_{\mathrm{regular}}$, and the coadjoint orbit invariant measure $dm_z(\Omega)=dm_{\text{KKS},z}(\Omega)$, assume $\mathcal{O}^*(z)=\mathcal{O}^*(\Lambda)$ for $\Lambda=\text{diag}(i\lambda_1,...,i\lambda_N)\in \su(N)$, then we have
\begin{equation}
\begin{array}{ll}
\overline{j_Q^\alpha}(z) & = \dfrac{\alpha \|\Lambda\|^2}{c_N(N^2-1)}\sum\limits_{k\in \mathcal{K}_N} b_{k, -k} \ ;
\\
\overline{j_Q^\nu}(z) & = \dfrac{\nu \|\Lambda\|^2}{c_N(N^2-1)}\sum\limits_{k\in \mathcal{K}_N}|k|^2 b_{k, -k} \ ;
\\
\overline{j_Q^\delta}(z) & =-\dfrac{\delta^2}{2}\sum\limits_{k\in \mathcal{K}_N^+} b_{k, -k} \ ;
\\
\overline{j_Q^f}(z) & = -\dfrac{1}{2}\sum\limits_{k\in \mathcal{K}_N^+, |k|\approx k_f}q_k^2 b_{k, -k} \ .
\end{array}
\end{equation}

