[Corollary c4.10 of arXiv:2603.14447, '\Large \bf Backward doubly stochastic differential equations with and without reflection u'] \sl
	Assume that 
	the conditions \(\textbf{(A2)}\), \(\textbf{(G1)}\) and \(\textbf{(G2)}\) hold with \(\lambda(t)=0\) for all \(t\in[0,T]\).    For any \((t,y,z)\in[0,T]\times\mathbb{R}\times\mathbb{R}^d\), we have
	\begin{align*}
		f^1(t,y,z)\leqslant f^2(t,y,z) \quad\  \hbox{and} \quad\ \xi^1\leqslant \xi^2, \quad\ \hbox{a.s.}
	\end{align*}
	Moreover, assume that $f^2$ satisfies \(\textbf{(F3')}\).
	Then for any \(t\in [0,T]\), $Y_t^1\leqslant Y_t^2,  \mathbb{P} $-a.s., where $(Y^1,Z^1)\in S^\infty_{\mathbb{F}}([0,T];\mathbb{R})\times L^2_{\mathbb{F}}([0,T];\mathbb{R}^d)$ is a bounded solution of  BDSDE (equation 1 of the paper) with parameters $(\xi^1,f^1,g)$,
	$(Y^2,Z^2)\in S^\infty_{\mathbb{F}}([0,T];\mathbb{R})\times L^2_{\mathbb{F}}([0,T];\mathbb{R}^d)$ is a maximal solution of the BDSDE (equation 1 of the paper) with parameters $(\xi^2,f^2,g)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T3.5 of arXiv:2512.18990, '\bf Hybrid Stochastic Functional Differential Equations with Infinite Delay: Approximation'] Let Assumptions (A2.1 of the paper), (A2.2 of the paper) and  (A3.4 of the paper) hold.  Set $\lambda  = (b_4 - r\bar q) \wedge { (b_5- r\beta)}$. Then
  the solutions of equations ((sfde of the paper)) and ((sfde2 of the paper)) have the properties
  that, for all $T >0$,
  \begin{align}
  \limsup_{k\to\8} \frac{1}{k}  \log\big(  \mathbb{E}|x(T)-x^k(T)|^{\bar q} \big) \le -\lambda,
  \end{align}
  and
   \begin{align}
  \limsup_{k\to\8} \frac{1}{k}  \log (|x(T)-x^k(T)|)  \le -\frac{\lambda}{\bar q}  \ \ \hbox{ a.s. }
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 6 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma>0$ and $\alpha\in\mathbb{R}$.

\begin{enumerate}
\item If $\gamma\in(0,1)$ and a semigroup increment $R\in E^{\gamma}(\Delta_T^2; B_\alpha)$ of a given semigroup defect is available, then its canonical information at this regularity is its class in $\mathfrak E_2^{\gamma}(\Delta_T^2; B_\alpha)$. \mlabel{it:canona}

\item If $\gamma=1$ and a semigroup increment $R\in E_{\log}^{1}(\Delta_T^2; B_\alpha)$ is available, then its canonical information is its class in $\mathfrak E_{\log}^{1}(\Delta_T^2; B_\alpha)$. \mlabel{it:canonb}

\item If $\gamma>1$, this quotient ambiguity disappears. \mlabel{it:canonc}
\end{enumerate}

[Proposition 25 (Uniform radial expansion of the solution map) of arXiv:2608.06393, 'Intrinsic Tangential Hadamard Differentiability of Rough-BSDE Solution Maps'] For every $R,B<\infty$,
\begin{equation}
 \lim_{\varepsilon\to0}
 \sup_{\substack{
       \tau\in\mathbb T_{\mathbf x}^p,
       \,\|\tau\|_{\mathbb T_{\mathbf x}^p}\leq R\\
       (\mathbf Z,a)\in\operatorname{Rep}_{\mathbf x}(\tau),
       \,\mathfrak b(\mathbf Z,a)\leq B}}
 \left\|
  \frac{
   \mathcal S(\mathbf x^{\varepsilon;\mathbf Z,a})
   -\mathcal S(\mathbf x)}{\varepsilon}
  -A_{\mathbf x}\tau
 \right\|_{\mathcal X}
 =0.
\end{equation}

[Theorem 1 of arXiv:2607.02406, 'On the range of competing random walks'] Under \ref{Assumption A1} and \ref{Assumption A2}, we have 

    Under \ref{Assumption A1}, \ref{Assumption A2}, \ref{Assumption A3}, we have, for all $k\in\{1,\dots,N\}$,
    \begin{equation*}
        \frac{h(n)}{n}\R_n^k\underset{n\rightarrow\infty}{\overset{L^2}\longrightarrow}1.
    \end{equation*}
    Furthermore, if $s(n)\ge1$ for all $n\ge1$, then the previous convergence also holds almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2506.15044, '2506.15044'] \begin{itemize}
  \item [$(1)$] $H$ is a $\mathbb{B}$-predictable (resp. $\mathbb{B}$-locally bounded predictable) process if and only if there exists a predictable (resp. locally bounded predictable) process $\widetilde{H}$ satisfying
\begin{equation}
H=\widetilde{H}\mathfrak{I}_\mathbb{B}.
\end{equation}
  The process $\widetilde{H}$ is called a {\bf coupled  predictable} (resp. {\bf locally bounded predictable}) {\bf process} for $H$.
  \item [$(2)$] Let $X$ be a $\mathbb{B}$-optional process. Then $X$ is a $\mathbb{B}$-thin process if and only if $XI_\mathbb{B}$ is a thin process. Provided that for all $t>0$,
      $\sum_{s\leq t}|(XI_\mathbb{B})_s|$ is a.s. finite, the $\mathbb{B}$-restriction of $\sum_{s\leq \cdot}(XI_\mathbb{B})_s$ is called the $\mathbb{B}$-{\bf summation process} of $X$, denoted by $\Sigma X$, i.e.,
   \[
   \Sigma X=\left(\sum_{s\leq \cdot}(XI_\mathbb{B})_s\right)\mathfrak{I}_\mathbb{B}.
   \]
  \item [$(3)$] Let $\mathcal{D}$ be a class of processes which is stable under stopping, and suppose that $X\in \mathcal{D}^\mathbb{B}$ with the FCS $(T_n,X^{(n)})$. Define the predictable set $\mathbb{C}$ of interval type as
\[
\mathbb{C}=\bigcup\limits_{n}\llbracket{0,T_n}\rrbracket.
\]
Then there exists $\widetilde{X}\in\mathcal{D}^\mathbb{C}$ with the FCS $(T_n,\widetilde{X}^{T_{n}})$ satisfying $XI_\mathbb{B}=\widetilde{X}I_\mathbb{B}$ and
\begin{equation}
\widetilde{X}^{T_1}=(X^{(1)})^{T_1},\quad \widetilde{X}^{T_{n+1}}=\widetilde{X}^{T_{n}}+(X^{(n+1)})^{T_{n+1}}-(X^{(n+1)})^{T_n}, \; n\in \mathbf{N}^+.
\end{equation}
  The sequence $((T_n,X^{(n)}),\widetilde{X})$ (or simply $(T_n,X^{(n)},\widetilde{X})$) is called a {\bf continuation} for $X\in \mathcal{D}^\mathbb{B}$.
  \item [$(4)$] Let $\mathbb{B}$ be given by \eqref{B}, and let $\mathcal{D}$ be a class of processes. Suppose that $(X^{(n)})\subseteq \mathcal{D}$ denotes a sequence of processes, and that $(T_n)$ is an increasing sequence of stopping times, satisfying $T_n\uparrow T$ and $\bigcup\limits_{n=1}^{{+\infty}}\llbracket{0,T_n}\rrbracket\supseteq \mathbb{B}$. If for any $k, l\in \mathbf{N}^+$ with $k\leq l$,
      \begin{equation*}
      X^{(k)}I_{\mathbb{B}\llbracket{0,T_k}\rrbracket}=X^{(l)}I_{\mathbb{B}\llbracket{0,T_k}\rrbracket},
      \end{equation*}
then $X\in \mathcal{D}^\mathbb{B}$ with the FCS $(T_n,X^{(n)})$, where $X$ is defined by
\begin{equation*}
      X=\left(X^{(1)}_0I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}X^{(n)}I_{\rrbracket{T_{n-1},T_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{B},\quad T_0=0.
      \end{equation*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

