[Proposition prop:equivalent_Gcausal of arXiv:2608.13716, 'Graph Causal Optimal Transport \\ and Wasserstein Distances'] Suppose $G$ is a DAG, $\mu \in \Gprobabilities{\mathcal{X}}$, $\nu \in \Gprobabilities{\mathcal{Y}}$, and $\pi \in \couplings{\mu}{\nu}$. Then the following are equivalent:

    \begin{enumerate}
        \item[1)] $\pi$ is $G$-causal in the sense of Definition (G_causal_definition of the paper);
        \item[2)] $\pi$ is $G$-causal in the sense of Definition (G_causal_definition_2 of the paper).
    \end{enumerate}
    If $G$ is a sorted $DAG$, the above are further equivalent to the following:
    \begin{enumerate}
        \item[3)] When $(X,Y) \sim \pi$ the following conditional independence relations hold for $1 \leq i \leq n$:
            $$\condindep{Y_i}{X_i, X_{\mathrm{pa}_{i}}, Y_{\mathrm{pa}_{i}}}{(X, Y_{1:i-1})}.$$
    \end{enumerate}

[Theorem 9 ({\cite[Theorem 3.4, 3.5) of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] {SikicSongVondracek2006}}]

    For $\alpha \in (0,2)$,
    \begin{align}

      J(x,y) \sim
      \begin{dcases}
        \frac{\alpha \Gamma(d/2)}{2|x-y|^{d}}, & |x-y| \to 0, \\
       \frac{\alpha \Gamma(d/2)}{2^{\alpha + 1} \pi^{d/2}
      \Gamma(1 - \alpha/2)} \frac{1}{|x-y|^{d+\alpha}}, & |x-y| \to \infty.
      \end{dcases}
    \end{align}
    For $\alpha = 2$, 
    \begin{align}

      J(x,y) \sim
      \begin{dcases}
        \frac{\Gamma(d/2)}{|x-y|^{d}}, & |x-y| \to 0, \\
        2^{-d/2} \pi^{-\frac{d-1}{2}} \frac{e^{-|x-y|}}{|x-y|^{\frac{d+1}{2}}}, & |x-y| \to \infty
      \end{dcases}
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theorem3 of arXiv:2412.01070, 'A note on Lévy-driven McKean-Vlasov SDEs under monotonicity'] Assume that Assumptions $({\bf B}_0)$-$({\bf B}_{3})$  hold, and suppose further $X_0\in L^\beta(\Omega^1\to\mathbb R^d,\mathscr F^1_0,\mathbb{P}^1)$.
Then, the McKean-Vlasov  SDE with common noise (equation common of the paper) admits a unique strong solution $(X_t)_{t\ge0}$ satisfying that,
for any fixed $T>0$, there exists a constant $C_T>0$ such that
\begin{align}
\mathbb{E}|X_t|^\beta \le C_T(1+\mathbb{E}|X_0|^{\beta}),\quad 0\le t\le T.
\end{align}
Furthermore,
if $\beta\in (1,2]$, then for all $p\in [1,\beta)$ and $T>0$,
 there exists a constant $C_T'>0$ such that
 \begin{align}
 \mathbb{E}\Big(\sup_{0\le t\le T}  |X_t|^p\Big)   \le C_T'(1+\mathbb{E}|X_0|^{\beta}).
\end{align}

