body:
[Theorem cor1-1 of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume that $({\bf A}_0)$, $ ({\bf A}_2)$,  $ ({\bf A}_3)$ and $ ({\bf A}_5)$ hold.
Then,  there are constants $C_0,\sigma_0,\lambda_\star>0$   such that  for all
$\delta\in(0,\delta_{3}^\star]$, $\mu\in \mathscr P_{p_\star}(\mathds R^d)$ and the noise intensity $\sigma$ satisfying  $|\sigma|\ge\sigma_0$,
 \begin{align}
	\mathbb{W}_2(\mu P_{n\delta}^{(\delta)},\pi_\8)\le  C_0\big(\text{\rm{e}}^{-\lambda_\star n\delta}\mathbb{W}_2(\mu,\pi_\8)+\delta d^{\ell_{\star\star}}\big),
\end{align}
where $\pi_\8$ is the unique IPM of $(X_t)_{t\ge0}$, and
\begin{equation}
\begin{split}
\delta^\star_3:&= (L^2_2/(32L_0^4))\wedge(2\sqrt2/{L_2})\wedge (1/2),\quad   p_\star:=2(4\vee(2\ell_0^\star)\vee( 3\ell_0+1 ))
\\
 \ell_{\star\star}:&= (1+3\ell_0)\vee (\ell_0^\star+2).
\end{split}
\end{equation}
Consequently,
\begin{align} 
	\mathbb{W}_2(\pi_\8^{(\delta)},\pi_\8)\le  C_0\delta  d^{\ell_{\star\star}},
\end{align}
where $\pi_\8^{(\delta)}$ is the IPM of $(X_{n\delta}^\delta)_{n\ge0}$ determined by (equation RT3 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 16 ({{\cite{crainic2004integrabilityliebrackets}}}) of arXiv:2608.30077, 'Lie groupoid integration of singular isometries of the Poincaré disk'] Whenever a Lie algebroid $\mathcal{A}$ is integrable, the quotient 
\begin{equation}
    \mathcal{G}(\mathcal{A}) = \frac{\mathcal{P}({\mathcal{A})}}{\mathcal{A}{\text{-path homotopy }}}
\end{equation}
admits a smooth structure, and it is the unique (up to isomorphisms) source-simply connected Lie groupoid integrating $\mathcal{A}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 47 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $T>0$ and let $F\in \mathcal{SB}_T$. Then,
  \begin{equation}
    \det(F(z)+\frac{T}{2}+\e I_m)\not=0,\quad \e>0,\quad z\in\mathbb C_r.
  \end{equation}
Furthermore,
  \begin{equation}
    \det(F(z)+T)\not=0,\quad z\in\mathbb C_r.
\end{equation}

[Proposition eq:inv_sig_dyn of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] The inverse signature $\sigX^{-1}$ is a continuous semimartingale (elementwise) satisfying
    \begin{equation}
        d\sigX^{-1} = -\, dX_t \otimes \sigX^{-1}, 
        \qquad \sigX[0]^{-1} = {\color{NavyBlue}{\mathbf{\varnothing}}}.
    \end{equation}

