[Definition 7 of arXiv:2608.04937, '2608.04937'] We say that a quadruple $(X,Y,Z,R)$ of $\mathbb{F}$-adapted processes is a solution to the mean-field forward-backward stochastic differential equation with reflection on $[0,T]$, with generators $B$ and $f$, diffusion coefficient $\sigma$, initial condition $\xi$, terminal function $h$, lower barrier $L$, and upper barrier $U$ (MF-FBSDER$^T(\xi,h,B,\sigma,f,L,U)$ for short), if
\begin{enumerate}[(a)]
\item $X,Y$ are regulated processes and $Z\in\mathcal{H}_{\mathbb{F}}(0,T)$,
\item $R\in\mathcal{V}_{0,\mathbb{F}}(0,T)$, $L_t\le Y_t\le U_t$, $t\in[0,T]$, and
\begin{equation*}
\begin{split}
&\int^T_0(Y_{r-}-\overrightarrow{L}_r)\,dR^{+,*}_r+\sum_{0\le r<T}(Y_r-L_r)\Delta^+R^+_r\\&
=\int^T_0(\underrightarrow{U}_r-Y_{r-})\,dR^{-,*}_r+\sum_{0\le r<T}(U_r-Y_r)\Delta^+R^-_r=0,
\end{split}
\end{equation*}
where $R=R^+-R^-$ is the Jordan decomposition of $R$,
\item $\int^T_0|B(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))|+|f(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))|\,dr<\infty$,
\item $X_t=\xi+\int^t_0 B(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))\,dr+\sigma W_t$, $t\in[0,T]$,
\item $Y_t=h(X_T,\mathcal{L}(X_T))+\int^T_t f(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))\,dr+R_T-R_t-\int^T_t Z_r \,dW_r$, $t\in[0,T]$.
\end{enumerate}

[Corollary cor:arc_chain_identity of arXiv:2605.03896, 'Dimer models on astroidal zig-zag graphs'] Let $\mathsf b \in B(\mathsf G_{c, \mathsf f_0})$ and $\mathsf w \in W(\mathsf G_{c, \mathsf f_0})$. Let $J=[a,b]$ and $K=[c,d]$ be any two nontrivial closed intervals in $\partial N$ with endpoints in $V(N)$. Then
\begin{equation}
\begin{aligned}
\frac{1}{2 \pi \mathrm{i}} \int_{C(J \cap K)} g_{\mathsf b,\mathsf w}
= -\langle \partial J \cap K,\mathsf A_{\mathsf b,\mathsf w} \rangle
-\langle \partial K \cap J,\mathsf A_{\mathsf b,\mathsf w} \rangle 
-\mathbf 1_{\{a=c\}} \mathsf A_{\mathsf b,\mathsf w}^{a}
+\mathbf 1_{\{b=d\}} \mathsf A_{\mathsf b,\mathsf w}^{b}.
\end{aligned}
\end{equation}

[Lemma 35 (One-dimensional block integral) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $x:[0,T]\to\R$ be continuous and of bounded variation, and let $0\leq a<b\leq T$.
For $n\geq 0$,
\begin{equation}
\int_{a<s_1<\cdots<s_n<b}
\dd x_{s_1}\cdots\dd x_{s_n}
 =\frac{(x_b-x_a)^n}{n!}.
\end{equation}

[Lem IntegralFinite of arXiv:2602.08739, '\large \bf MOMENTS OF C$\beta$E FIELD PARTITION FUNCTION, $\mathsf{Sine}_{\beta}$ CORRELAT'] Let $m\in \mathbb{N}$, $a,b \in \mathbb{R}_+$ such that $a+(m-1)b/2>1$ and $ma>1$. Then,
\begin{equation*}
\int_{\mathbb{R}^m}\prod_{j=1}^m\frac{1}{1+|x_j|^a}\prod_{1\le i< j \le m}\frac{1}{1+|x_i-x_j|^b}\mathrm{d}x_1\cdots\mathrm{d}x_m<\infty.
\end{equation*}

