[Prop sub-halfin-whitt-mixing-integral-lambda of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Let $\pi_{n,t}, \nu_n$ be the queue length distribution at time $t$ and the steady state distribution of the continuous-time $M/M/n$ system with unit service rate respectively and let $\{\lambda_n\}$ be a sequence of integer arrival rates ($\lambda_n \in \Z$) such that $\lambda_n \geq 0, n-\lambda_n \geq 1, \frac{\log\br{n-\lambda_n}}{\log n} \in (1/2,1)$ and
    \begin{align}
        \lim_{n \rightarrow \infty} \frac{\log\br{n-\lambda_n}}{\log n} = 1-\alpha
    \end{align}
    where $\alpha < 1/2$. Then, we have
    \begin{align}

        \chi(\pi_{n,t},\nu_n) \leq e^{-\overline{D}_n t} \chi(\pi_{n,0},\nu_n) \, \forall t \geq 0
    \end{align}
    such that $\overline{D}_n > 0$ and $\lim_{n \rightarrow \infty} \overline{D}_n = 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Assume \textnormal{(A1)-(A4)}. Let $T>0$, $R>0$ and $\omega\in\Omega_0$. There exists $C_{T,\omega,R}>0$ such that, for every $\epsilon\in(0,\epsilon_0]$, $x_\epsilon,x_0\in H$ and $\mu_\epsilon,\mu_0\in P$ satisfying
	\begin{align*}
		\|x_\epsilon\|^2+\|x_0\|^2
		+M_2(\mu_\epsilon)+M_2(\mu_0)\leq R,
	\end{align*}
	one has
	\begin{align}
		\sup_{0\leq t\leq T}
		\left\|
		\varphi_H^\epsilon(t,\omega,x_\epsilon,\mu_\epsilon)
		-\varphi_H^0(t,\omega,x_0,\mu_0)
		\right\|^2
	\leq
		C_{T,\omega,R}
		\left(
		\|x_\epsilon-x_0\|^2
		+\mathcal W_2^2(\mu_\epsilon,\mu_0)
		+\epsilon
		\right).
	\end{align}
	Consequently, for every compact set $\mathcal C\subset\mathbb X$,
	\begin{align}
		\lim_{\epsilon\to0}
		\sup_{(x,\mu)\in \mathcal C}\sup_{0\leq t\leq T}
		d_{\mathbb X}\big(
		\Phi^\epsilon(t,\omega)(x,\mu),
		\Phi^0(t,\omega)(x,\mu)
		\big)=0.
	\end{align}

