body:
[Lemma 9 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Define the functions

\begin{align}
\begin{aligned}
R_\varepsilon(y) &\coloneqq \rho_\varepsilon(y) - \rho_\varepsilon(y)V_K(y)\int_{\mb T^d}\m K_\varepsilon(y-x)U_K(x)\rho_0(x)\,\dd x,\\
Q_\varepsilon(x) &\coloneqq \rho_0(x) - \rho_0(x) U_K(x)\int_{\mb T^d} \m K_\varepsilon(x-y) V_K(y)\rho_\varepsilon(y)\,\dd y.
\end{aligned}
\end{align}

Then, we have
\begin{align*}
\Big\|\frac{R_\varepsilon}{\rho_\varepsilon}\Big\|_{L^2(\mb T^d)} \leq C\varepsilon^{K+1}
\quad\mx{and}\quad
\Big\|\frac{Q_\varepsilon}{\rho_0}\Big\|_{L^2(\mb T^d)} \leq C\varepsilon^{K+1},
\end{align*}

for some constant $C > 0$ depending on the regularity set $\mathcal{RS}_{\rm SBE}^{(K)}(0, \varepsilon)$. Here, the set $\mathcal{RS}_{\rm SBE}^{(K)}(t, t+\varepsilon)$ with a given time point $0\leq t\leq 1-\varepsilon$ contains the elements
\begin{align}
\begin{cases}
\|u_{t,0}\|_{\m C^0}, \cdots \|u_{t,K}\|_{\m C^0}, \|u_{t,0}\|_{H^{2K+2}}, \cdots, \|u_{t,K}\|_{H^{2K+2}},\\
\|v_{t,0}\|_{\m C^0}, \cdots \|v_{t,K}\|_{\m C^0}, \|v_{t,0}\|_{H^{2K+2}}, \cdots, \|v_{t,K}\|_{H^{2K+2}},\\
\sup\big\{\|\rho_s^{(k)}\|_{\m C^{2k'}}: t\leq s\leq t+\varepsilon, \,\, k,k'\in\mb N,\,\,k+k'\leq K+1\big\},
\end{cases}
\end{align}
where $u_{t, k}$ and $v_{t,k}$ are defined by Equation~\eqref{eqn: uvtk}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Assume that the function $\phi$  satisfies \ref{assphi}, and take $u\in \DD(G)$. Then a pointwise solution to \eqref{eq_over}
		is given by $q^+(x,t)=\mathds{E}^{(x,0)}[u(M({D_t}))]$, $t\ge0$ and a pointwise solution to \eqref{eq_under} is $q(x,t) = \mathds{E}^{(x,0)}u(M(H(t-)))$. 
		Furthermore, these solutions are the unique in the class of jointly continuous functions in $E\times [0,+\infty)$ with property $\lim_{t\to +\infty} q(x,t)=0$, for all $x\in E$.

[Lemma 2 (Cap Move) of arXiv:2608.22816, 'A Cap-Move Reformulation of Ling's Proof of Samuels' Conjecture'] Let $S = \sum_{i=1}^n X_i$ with $\bE[S]<\lambda$, and $S_i^a$ be the counterpart after applying the cap move $X_i \mapsto X_i\wedge a$. Also define $p=\bP(S<\lambda), p_i^a=\bP(S_i^a<\lambda)$, and
\begin{align}
	b(S) &:= \bE[S] - \bE\qth{S\mid S < \lambda },  \\
	r(S) &:= \lambda - \bE\qth{S\mid S < \lambda }.  
\end{align}
Then $b(S)\ge b(S_i^a)$, and 
\begin{align*}
\frac{p_i^a}{p} \le \frac{r(S)}{r(S) - (b(S)-b(S_i^a))}. 
\end{align*}

