[Theorem thm:R1b of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha\in(\frac{d}{2},2)$ (in particular $d=2,3$) and $(\zeta,\gamma)\in R_1$ (see Figure (diagram2 of the paper)). Then $(S_n)_{0\leq n \leq N}$ has end-to-end fluctuations of order $N^{\xi}$ under ${\ensuremath{\mathbf P}} _N$ with $\xi=\frac12$ and we have the following scaling limits for ${\ensuremath{\mathbf Z}} _N$.

\noindent{\rm (i)} If $\zeta\in(1,\gamma+\frac{d(\alpha-1)}{2\alpha})$, then
\begin{equation}
\frac{1}{h_N{\ensuremath{\mathbf E}} [|{\ensuremath{\mathcal R}} _N|]}\log{\ensuremath{\mathbf Z}} _N\overset{{\ensuremath{\mathbbm P}} }{\longrightarrow}-1.
\end{equation}

\noindent{\rm (ii)} If $\zeta>\gamma+\frac{d(\alpha-1)}{2\alpha}$, then setting $v_N=\log N$ for $d=2$ and $v_N=\sqrt{N}$ for $d=3$, we have that
\begin{equation}
\frac{v_N}{\beta_N N^{\frac{d}{2\alpha}}}\log{\ensuremath{\mathbf Z}} _N\overset{(d)}{\longrightarrow}{\ensuremath{\mathcal W}} ,
\end{equation}
where
\begin{equation}
{\ensuremath{\mathcal W}} :=\int_{{\ensuremath{\mathbbm R}} ^d\times{\ensuremath{\mathbbm R}} }\omega f(x)({\ensuremath{\mathcal P}} -\eta)({\ensuremath{\mathrm d}}  x,{\ensuremath{\mathrm d}}  w)
\end{equation}
is a well-defined random variable with
\begin{equation}
f(x):=\begin{cases}
\int_{\|x\|^2/2}^{\infty}u^{-1}e^{-u}{\ensuremath{\mathrm d}}  u,\quad&\text{if}~d=2,\\
2\lambda_d\int_0^1\rho_d(u,x){\ensuremath{\mathrm d}}  u,\quad&\text{if}~d=3,
\end{cases}
\end{equation}
a Poisson point process ${\ensuremath{\mathcal P}} $ with intensity measure $\eta({\ensuremath{\mathrm d}}  x,{\ensuremath{\mathrm d}} \omega)=\alpha p^{\mathbbm{1}_{\{\omega>0\}}}q^{\mathbbm{1}_{ \{\omega<0\}}}|\omega|^{-(1+\alpha)}{\ensuremath{\mathrm d}}  x{\ensuremath{\mathrm d}}  \omega$, $\lambda_d={\ensuremath{\mathbf P}} (S_n\neq0,\forall n\geq1)$, and the Gaussian kernel $\rho_d(t,x)=(2\pi t/d)^{-d/2}\exp(-d\|x\|^2/2t)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 16 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Let \(Y_t\) be the Ornstein-Uhlenbeck process defined in~\eqref{OU_a0}. Then, for any \(p\geq 1\), it holds that
        \[
        \left(
        \E_{\PP^{OU}_y}\left[
        \Vert Y_t\Vert_2^p
        \right]
        \right)^{1/p}
        \leq 2^{1-1/p}\left(
        e^{-2a_0 t} 
        \Vert y\Vert_2
        +\sqrt{\frac{1-e^{-4a_0 t}}{a_0}}
        \left(
        \frac{\Gamma((d+p)/2)}{\Gamma(d/2)}
        \right)^{1/p}
        \right).
        \]

[Lemma 5 of arXiv:2605.30091, 'Computing lower expectations with respect to total variation distance and chi-squared dive'] For any $k\in\{\ell+1,\ldots,n\}$, the following are equivalent:
\begin{equation*}
\mathcal{Q}_k\neq\emptyset
\Leftrightarrow
m_k\delta-(1-m_k)\geq0
\Leftrightarrow
\delta\geq\frac{1-m_k}{m_k}.
\end{equation*}
Whenever either of these is true, we have that
\begin{equation}
    \min_{q\in\mathcal{Q}_k} E_q(f)=\mu_k-\sigma_k\sqrt{m_k\delta-(1-m_k)}.
\end{equation}
The minimum is then furthermore attained uniquely for $q_k\in\mathbb{R}^\mathcal{X}$ with $q_k(x_i)=0$ for all $i>k$ and, for all $i\in\{1,\ldots,k\}$,
\begin{equation}
    q_k(x_i)
    =\frac{p(x_i)}{m_k}\left(1-\frac{f(x_i)-\mu_k}{\sigma_k}\sqrt{m_k\delta-(1-m_k)}\right).
\end{equation}
Finally, $q_k(x_k)>0$ (and then also $q_k(x_i)>0$ for all $i\in\{1,\ldots,k\}$) if and only if $\delta<\delta_k$, and $q_k(x_k)=0$ (and then also $q_k(x_i)\geq0$ for all $i\in\{1,\ldots,k\}$) if and only if $\delta=\delta_k$

