[Theorem 15 of arXiv:2601.16377, '2601.16377'] For the discrete ensemble of the C-shaped domain, the nine functions in the table
\begin{equation*}
\begin{array}{|c|c|c|}
\hline
(\mathcal{F}_{1,1} + \mathcal{F}_{2,1} + \mathcal{F}_{1,2} + \mathcal{F}_{2,2})(z_1,z_2) + \frac{1}{(z_1 - z_2)^2} & -(\mathcal{F}_{1,1} + \mathcal{F}_{1,2})(z_1,z_2) & - (\mathcal{F}_{2,1} + \mathcal{F}_{2,2})(z_1,z_2) \\[2pt]
\hline
-(\mathcal{F}_{1,1} + \mathcal{F}_{2,1})(z_1,z_2) & \mathcal{F}_{1,1}(z_1,z_2) + \frac{1}{(z_1 - z_2)^2} & \mathcal{F}_{2,1}(z_1,z_2) \\[2pt]
\hline
-(\mathcal{F}_{1,2} + \mathcal{F}_{2,2})(z_1,z_2) & \mathcal{F}_{1,2}(z_1,z_2) & \mathcal{F}_{2,2}(z_1,z_2) + \frac{1}{(z_1 - z_2)^2} \\[2pt]
\hline
\end{array}
\end{equation*}
are the nine branches of the meromorphic function on $\Sigma^2$
\begin{equation}

\frac{1}{Z'(\zeta_1)Z'(\zeta_2)(\zeta_1 - \zeta_2)^2} = \partial_{z_1}\partial_{z_2}\log(\zeta_1 - \zeta_2)
\end{equation}
that we get when expressing it in terms of $z_1 = Z(\zeta_1)$ and $z_2 = Z(\zeta_2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:weak_solutions of arXiv:2601.04997, 'Fluctuations of the Boundary-Driven Symmetric Zero-Range Process from the NESS'] We say that $\rho:[0, T]\times [0, 1]\to[0, \infty)$ is a weak solution of the PDE (equation eq:pde_zr of the paper) if:
\begin{enumerate}[i)]

    \item $\rho \in L^2([0, T]\times [0, 1])$,

    \item $\Phi(\rho)\in L^2([0,T], \mathcal H^1)$,

    \item for any $t\in[0,T]$ and $G\in C^{1,2}([0,T]\times [0,1])$,
    \begin{equation*} 
        \begin{split}
        \langle\rho_t, G_t\rangle &- \langle\gamma, G_0\rangle - \int_0^t\{\langle \rho_s, \partial_s G_s\rangle + \langle\Phi(\rho_s), \Delta G_s\rangle\}\de s
        \\&+\int_0^t \{\Phi(\rho_s(1))\partial_u G_s(1)-\Phi(\rho_s(0))\partial_u G_s(0) \}\de s
        \\&-\boldsymbol{1}_{\{1\}}(\theta)\int_0^t \big\{(\beta-\delta\Phi(\rho_s(1)))G_s(1) - (\lambda \Phi(\rho_s(0))-\alpha)G_s(0) \big\}\de s = 0,
        \end{split}
    \end{equation*}
    where $\langle \cdot, \cdot\rangle$ denotes the inner product $\langle f, h\rangle:=\int_0^1 f(u)h(u)\de u$ on the set of measurable functions in $L^2([0,1])$.

\end{enumerate}

[Proposition Prop:PW_estimate of arXiv:2609.02325, 'A Payne-Weinberger inequality\\for quantum dot Dirac operators'] Let 
    $\Omega\subset \mathbb{R}^2$ be a bounded simply connected domain with $C^2$~boundary. Set
    $$r_1 := \dfrac{1}{2\pi}\sqrt{|\partial\Omega|^2-4\pi |\Omega|} \quad \text{and} \quad r_2:= \dfrac{1}{2\pi}|\partial\Omega|.$$
    Then, 
    \begin{equation} 
        \mu_\Omega^\mathrm{Rob}(a) \leqslant  \dfrac{{ \int_{r_1}^{r_2} |\frac{d}{dr} v(r)|^2 \, rdr + ar_2|v(r_2)|^2 } }{{ \int_{r_1}^{r_2} |v(r)|^2 \, rdr } }
    \end{equation} 
for all $a>0$ and all $v\in C^1([r_1,r_2])\setminus\{0\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Prop:relations1-10 of arXiv:2608.27771, 'A normal form for the Thin Flat Surfaces category'] The relations in Figure (Fig:relations of the paper) are sufficient relations in the $\mathbf{TFS}$ category. 
    \begin{center}
  \includegraphics[width=0.99\textwidth]{Normal/Relations.pdf}
  \captionof{figure}{Sufficient relations in the $\mathbf{TFS}$ category.} 


\end{center} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2608.22112, '2608.22112'] \textbf{(Control of standard deviation under bounded trajectories).}
Suppose that the true and predicted trajectories satisfy a uniform bound
\[
\|\x(j)\|_2 \le M, \quad \|\tilde{\x}(j)\|_2 \le \tilde{M}
\quad \text{for all } j=1,\dots,m.
\]
Then the difference between the variances satisfies
\begin{equation}
\|\bm \sigma^2 - \tilde{\bm \sigma}^2\|_2 \le 2(M+\tilde{M}) \, \mathrm{RMSE}.
\end{equation}
Moreover, the difference between the standard deviations satisfies
\begin{equation}
\|\bm \sigma - \tilde{\bm \sigma}\|_2^2
\le
C \, \mathrm{RMSE},
\end{equation}
where $C = 2\sqrt{n}(M+\tilde{M}) >0$ depends only on $M$ and $n$ (and not on $m$).

