[Proposition 29 of arXiv:2605.02499, '2605.02499'] Fix $r\geq 0$, $\kappa \geq 0$, and $N \in \Nb$. Assume that $Nu^{(N)}\to \theta\geq 0$, $N s^{(N)}_m \to \sigma_m\in \Rb_+$, and $\sum_{m=1}^\infty N s_m^{(N)} \to \sum_{m=1}^\infty \sigma_m$, with $\sum_{m=1}^\infty m\,\sigma_m<\infty$. Suppose that $X_0^{(N)}/N \to X_0$ in distribution as $N \to \infty$. Then $\Big( X^{(N)}_{Nt}/N\Big)_{t \geq 0}$ converges in distribution to the solution $(X_t)_{t \geq 0}$ of the SDE
    \begin{equation*}
        \dd X_t = \Big(-\sum_{m=1}^{\infty}\big(\sigma_m X_t(1-X_t^m)\big) +\theta \, \nu_0 (1-X_t)-\theta \, \nu_1 X_t \Big) \dd t + \sqrt{X_t(1-X_t)\big(r+\kappa(1-X_t)\big)} \dd B_t,
    \end{equation*}
    with initial value $X_0=x_0$ and $B$ standard Brownian motion. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:regular of arXiv:2609.00668, 'Rigidity of Euclidean Minimal Hypersurfaces under Nonuniform Diagonal Dilations'] Let $\Sigma\subset\mathbb R^n$ be a $C^2$ hypersurface. A $C^2$ function $F$ on a neighborhood $U$ of a point of $\Sigma$ is a \emph{regular defining function} if
\begin{equation}
\Sigma\cap U=\{x\in U:F(x)=0\},\qquad \nabla F\ne0\quad\text{on }\Sigma\cap U.
\end{equation}

[Lemma 23 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(X\) be an fpqc algebraic stack and let \(K \in \mcalD_{\qcoh}(X)\).
  Assume that \(\mcalH^i(K)\) is a flat \(\cO_X\)-module for every \(i \in \Z\).
  Let \(E_i\) be a quasi-coherent \(\cO_X\)-module with an isomorphism
  \begin{equation*}
    c_i\colon \mcalH^i(K) \xrightarrow{\simeq} E_i
  \end{equation*}
  for every \(i \in \Z\).

  Let \(A \in \CAlg(\mcalD_{\qcoh}(X))\).
  Suppose that $A$ is coconnective and there is an isomorphism
  \begin{equation*}
    \alpha\colon A\otimes_{\cO_X}^{L}K \xrightarrow{\simeq} A\otimes_{\cO_X}^{L}\parenlr{\bigoplus_{i \in \Z}E_i[-i]}
  \end{equation*}
  in \(\Mod_A\parenlr{\mcalD_{\qcoh}(X)}\).

  Then there exists an isomorphism
  \begin{equation*}
    \varphi(\alpha)\colon A\otimes_{\cO_X}^{L}K \xrightarrow{\simeq} A\otimes_{\cO_X}^{L}\parenlr{\bigoplus_{i \in \Z}E_i[-i]}
  \end{equation*}
  in \(\Mod_A\parenlr{\mcalD_{\qcoh}(X)}\) with the following properties.
  \begin{enumerate}
    \item Equipped with the filtered structures on both sides given by the canonical truncations
  \begin{equation*}
    \bracelr{\tau_{\leq m}K}_{m \in \Z} \qquad\text{and}\qquad \bracelr{\bigoplus_{i \leq m}E_i[-i]}_{m \in \Z},
  \end{equation*}
  the isomorphism \(\varphi(\alpha)\) induces a filtered isomorphism
  \begin{equation*}
    \bracelr{\varphi(\alpha)_{\leq m}\colon A\otimes_{\cO_X}^{L}\tau_{\leq m}K \xrightarrow{\simeq} A\otimes_{\cO_X}^{L}\parenlr{\bigoplus_{i \leq m}E_i[-i]}}_{m \in \Z}
  \end{equation*}
  in \(\Mod_A\parenlr{\mcalD_{\qcoh}(X)}\).

  \item For every \(m \in \Z\), the associated graded part
  \begin{equation*}
    \gr_m\parenlr{\varphi(\alpha)_{\leq\bullet}}\colon A\otimes_{\cO_X}^{L}\mcalH^m(K)[-m] \xrightarrow{\simeq} A\otimes_{\cO_X}^{L}E_m[-m]
  \end{equation*}
  coincides with
  \begin{equation*}
    \parenlr{\id_A\otimes c_m}[-m].
  \end{equation*}
  Equivalently, the induced isomorphism
  \begin{equation*}
    \varphi(\alpha)_m\colon A\otimes_{\cO_X}^{L}\mcalH^m(K) \xrightarrow{\simeq} A\otimes_{\cO_X}^{L}E_m
  \end{equation*}
  coincides with \(\id_A\otimes c_m\).
  \end{enumerate}

