[Corollary cor:directional-recurrence of arXiv:2609.00399, 'Shannon's problem on the monotonicity of entropy and a Conjecture of Tao'] Under the hypotheses of Theorem~(thm:transport-cover of the paper), fix
$J\in\mathbb Z_{\geq2}$.  If
\begin{equation}
 J^{M_{\rm tr}(a,L)}<N_1/2,
\end{equation}
there is an integer $R$ satisfying
\begin{equation}
 1\leq R\leq J^{M_{\rm tr}(a,L)}
\end{equation}
such that, for $r=Rv_1$,
\begin{equation}
 |\chi(r)-1|
 \leq2\pi\left(\frac1J+
 \frac{J^{M_{\rm tr}(a,L)}}{2N_1+1}\right)
 \qquad(\chi\in\Lambda_a).
\end{equation}
In particular, $r\neq0$.

[Lemma lem:nonlinear_est_cutoff of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] For all $g$ verifying (hp_correction of the paper), every $r \in (-1/2, 0)$  and every $\omega, \xi \in H^0_g$, denoting $u=K[\omega]$, $v=K[\xi]$, there exists $\delta_0 \in (r,0) $ and $k(r, \delta_0) \in (0,1)$ such that for every $\delta >\delta_0$
    \begin{equation}
        \|\mathcal{L}_u \omega \|_{H^{-2}_g} \lesssim \|\omega\|^{1-k}_{H^\delta_g}\|\omega \|^{1+k}_{H^r_g}.
    \end{equation}
    As a consequence, denoting $F_{R,r}(\omega):= \phi_R(\|\omega\|_{H_g^r})\mathcal{L}_u \omega$, it holds
    \begin{equation}
        \|F_{R,r}( \omega) - F_{R,r}( \xi) \|_{H^{-2}_g} \lesssim (1 +\|\xi\|_{H^\delta_g})\|\omega - \xi\|_{H^r_g} + (\|\omega\|_{H^{-1/4}_g}+\|\xi\|_{H^{-1/4}_g})\|\omega - \xi\|_{H^{-1/4}_g}. 
    \end{equation}

