[Theorem mainthm of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Fix $n \geq 2$. 
Let $K_{\mathrm{PF}}$ be the transition kernel of the Burnside process on $\mathrm{PF}_n$ and let $\pi_{\mathrm{PF}}$ be its stationary distribution. 
Then $\lambda_{2,\mathrm{PF}} = \lambda_2(K_{\mathrm{PF}}) = \frac{n}{2(n+1)}$, and for all $t\ge1$, 
\begin{equation}
 \max\left\{
  \frac{n}{n+2}\lambda_{2,\mathrm{PF}}^t,\,
  1-\frac{t+\log 3}{\log n}
 \right\}
 \le d_{K_{\mathrm{PF}}}(t)
 \le n\sqrt{\frac{n+1}{2}} \lambda_{2,\mathrm{PF}}^{t/2}.

\end{equation}
Consequently, for every fixed $0<\varepsilon<1$,
\[
 t_{\mathrm{mix},K_{\mathrm{PF}}}(\varepsilon)=\Theta_\varepsilon(\log n).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 1 of arXiv:2608.30967, 'B-Frames, B-Riesz basis, and Their tensor products'] Let $\{e_j\}_{j \in \mathcal{K}}$ be an orthonormal basis  for $\mathcal{H}$ and let $\{x_k\}_{k \in \mathcal{K}} \subset \mathcal{B}$.
\begin{enumerate}
\item $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$ is a b-frame for $\mathcal{Z}$ with the b-frame bounds $A$ and $B$  if and only if $\{\mathfrak{b}(e_j,x_k)\}_{j,k \in \mathcal{K}}$ is a frame for $\mathcal{Z}$ with the frame bounds $A$ and $B$.
  \item Suppose $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$ is a b-frame for $\mathcal{Z}$.
  \begin{enumerate}
    \item $S$ is the b-frame operator of $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$, if and only if $S$ is the frame operator of $\{b(e_j,x_k)\}_{j,k \in \mathcal{K}}$.
     \item $(\{x_k\}_{k \in \mathcal{K}},\tilde{\mathfrak{b}})$ is a b-frame for $\mathcal{Z}$ with the frame bounds $B^{-1}$ and $A^{-1}$. We call $(\{x_k\}_{k \in \mathcal{K}},\tilde{\mathfrak{b}})$ the canonical dual b-frame of the b-frame $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$.
    \item For each $z \in \mathcal{Z}$, we have the following b-frame expansion
    \begin{eqnarray}
z=\sum_{k \in \mathcal{K}}\tilde{\mathfrak{ b }}(\langle z / x_k \rangle,x_k )=\sum_{k \in \mathcal{K}} \mathfrak{ b }(\langle z / x_k \rangle\tilde{ \ },x_k ),
\end{eqnarray}
where $\langle . / . \rangle\tilde{\ }$ is the b-frame product with respect to $\tilde{\mathfrak{ b }}$.
\end{enumerate}
\end{enumerate}

