[Theorem LUE left soft of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] (left soft edge) Consider an LUE $L_{a,N}$ such that $\lim\limits_{N\rightarrow\infty}\frac{N}{n}=\gamma\in(0,1)$ where $n:=N+a$. Let $I\subset[s,+\infty)$ for $s>-\infty$. Define parameters:
    \begin{equation*}
      \begin{array}{ll}
      \mu^L_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)^2,\\
      \sigma^L_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)\left(\left(m+\frac{1}{2}\right)^{-\frac{1}{2}}-\left(k+\frac{1}{2}\right)^{-\frac{1}{2}}\right)^{\frac{1}{3}},
      \end{array}
    \end{equation*}
\begin{equation*}
    \mu_L=\left(\frac{1}{\sqrt{\sigma_{n-1,N}^{L}}}+\frac{1}{\sqrt{\sigma_{n,N-1}^{L}}}\right)\left(\frac{1}{\mu^L_{n-1,N}\sqrt{\sigma_{n-1,N}^L}}+\frac{1}{\mu^L_{n,N-1}\sqrt{\sigma_{n,N-1}^{L}}}\right)^{-1}
\end{equation*}
and
\begin{equation*}
    \sigma_L=\left(\frac{\sqrt{\sigma_{n-1,N}^{L}}}{\mu^L_{n-1,N}}+\frac{\sqrt{\sigma_{n,N-1}^{L}}}{\mu^L_{n,N-1}}\right)\left(\frac{1}{\mu^L_{n-1,N}\sqrt{\sigma_{n-1,N}^{L}}}+\frac{1}{\mu^L_{n,N-1}\sqrt{\sigma_{n,N-1}^{L}}}\right)^{-1}.
\end{equation*}
Let $\mathcal{X}_{L_{a,N}}^{LS}$ denote the left-soft-edge-scaled point process for $L_{a,N}$ with the kernel $K_{L_{a,N}}^{LS}(x,y):=\sigma_{L}K_{L_{a,N}}(t_{L_{N}}(x),t_{L_{N}}(y))$ where $t_{L_N}(x):=\mu_{L}-\sigma_{L}x$ for any $x\in I$. Then on $A\subset I$, there exists $n(s,\gamma)\in\mathbb{N}$ such that for any $N>n(s,\gamma)$,
\begin{equation}
W_1(\mathcal{N}_{L_{a,N}}^{LS},\mathcal{N}_{Ai})\le\frac{g(s,\gamma)e^{-s}}{N^{\frac{2}{3}}}
\end{equation}
where $g(s,\gamma)$ is continuous and non-increasing with respect to $s$ for any fixed $\gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:theta_hjb_mkv of arXiv:2507.22577, 'A Mean-Field Theory of $\Theta$-Expectations'] Let $(\mu_t)_{t\in[0,T]}$ be a given flow of probability measures in $\mathcal{P}_2(\mathbb{R})$. The \textbf{$\Theta$-HJB-McKean-Vlasov (HJB-MKV) equation} is the terminal-value problem for a function $v: [0,T]\times\mathbb{R}^k \to \mathbb{R}$:
\begin{equation}
\begin{cases}
    -\partial_t v - \sup_{a \in \mathcal{U}_{g(\mu_t)}} \Big\{ \mathcal{L}^{t,x,a,\mu_t} v(t,x) + F(t, x, v, (\nabla_x v)\sigma(t,x,a,\mu_t), a, \mu_t) \Big\} = 0, \\
    v(T,x) = \Phi(x),
\end{cases}
\end{equation}
for $(t,x) \in [0,T) \times \mathbb{R}^k$, where the second-order operator is given by
\[ (\mathcal{L}^{t,x,a,\mu} \phi)(x) \coloneqq \scpr{b(t,x,a,\mu)}{\nabla_x \phi(x)} + \frac{1}{2} \mathrm{Tr}\big(\sigma\sigma^T(t,x,a,\mu) \nabla_x^2 \phi(x)\big). \]

[Lemma lem:pnqn of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume (hyp:M of the paper) holds for $(G_k)$ along $(k_{n})$ with respect to $(M_{n})$. Set $p_n = \P(I_1^{(M_n)}=1)$ and $r_n = \sqrt{a_{M_n} a_n}$. Then:
\begin{enumerate}
\item[(i)] $\P(I_1^{(M_n)} = 1, |S_{M_n}| > r_n) = o(p_n)$.
\item[(ii)] $p_n \sim q_n \sim \pi_n$.
\end{enumerate}

[Proposition prop:moderatetransflucts of arXiv:2608.11378, 'On the most likely geodesic in last passage percolation'] Consider $d = 2$ with $\omega_x \sim \mathrm{Exp}(1)$. Take $\alpha \in (\frac{2}{3}, 1]$. There is $c > 0$ such that
\[
\mathbb{P}(Q(\gamma_n^*) \ge n^{\alpha}) \le e^{-c n^{3 \alpha - 2}}.
\]
The same is true of $Q(\gamma^{\mathord{\text{
\tikz[baseline=0.1ex, line join=round] {
\draw[line width=0.06em] (0,0) -- (1ex,0) -- (1ex,1ex) -- cycle;
}
}}}_n)$.
\begin{proof}
    For simplicity we treat only the point-to-point geodesic $\gamma^*_n$, but the proof goes through essentially unchanged for $\gamma^{\mathord{\text{
\tikz[baseline=0.1ex, line join=round] {
\draw[line width=0.06em] (0,0) -- (1ex,0) -- (1ex,1ex) -- cycle;
}
}}}_n$ (and for point-to-line geodesics, should we need them). The case $\alpha = 1$ has been treated in Appendix~(app:cornerpathprob of the paper), so assume $\alpha < 1$. We abbreviate taking integer parts. 

    For $t$ such that $n^{\alpha-1}\le t\le1-n^{\alpha-1}$, put $z_t=(tn+n^\alpha,tn-n^\alpha)$ and let $A_t$ be the event that $z_t\in\gamma_n^*$. The event that the geodesic exits the other side of the tube may be handled in the same way. On the event $A_t$ we have
    \[
    L(0, 0; n, n) = L(0, 0; z_{t,1},z_{t,2}) + L(z_{t,1},z_{t,2}; n, n)-\omega_{z_t}.
    \]
    Let $L_0(a, b; c, d) = L(a, b; c, d) - \mu(c - a, d - b)$ be centred passage times. A second-order Taylor expansion of the shape function in the transverse direction gives
    \[
        \mu(n, n) - \mu(t n + n^{\alpha}, t n - n^{\alpha}) - \mu\bigl((1 - t) n - n^{\alpha}, (1 - t) n + n^{\alpha})\bigr) \ge \frac{1}{2t(1 - t)}n^{2\alpha - 1},
    \]
    for $n$ large enough. Since $\omega_{z_t}\ge0$, dropping the resulting nonpositive term gives the inequality
    \begin{multline}

        L_0(0, 0; n, n) \le L_0(0, 0; t n + n^{\alpha}, t n - n^{\alpha}) \\ + L_0(t n + n^{\alpha}, t n - n^{\alpha}; n, n) -\frac{1}{2t(1 - t)}n^{2\alpha - 1}.
    \end{multline}
    Set
    \begin{align*}
        L_0^1 &= L_0(0, 0; n, n)\\
        L_0^2 &= L_0(0, 0; t n + n^{\alpha}, t n - n^{\alpha})\\
        L_0^3 &= L_0(t n + n^{\alpha}, t n - n^{\alpha}; n, n).
    \end{align*}
    Observe that $L_0^3 \ensuremath{\stackrel{d}{=}} L_0(0, 0; (1 - t) n + n^{\alpha}, (1 - t) n - n^{\alpha})$. As in the proof of the upper bound for Theorem~(thm:probability of the paper), we apply a union bound to the event in (equation eq:transfluctsineq of the paper). For each summand, the Harris inequality bounds the intersection of the decreasing event for $L_0^1$ and the increasing event for $L_0^2$ or $L_0^3$ by the product of their probabilities. Using also $t(1 - t) \le \frac{1}{4}$, we obtain
    \begin{equation}

        \mathbb{P}(A_t) \le \sum_{a = - \infty}^{\infty} \mathbb{P}(L_0^1 \le a + 1)\brac[\Big]{\mathbb{P}\brac[\big]{2 L_0^2 \ge a + n^{2 \alpha - 1}} + \mathbb{P}\brac[\big]{2 L_0^3 \ge a + n^{2 \alpha - 1}}}.
    \end{equation}
    Larger values of $a$ relax the condition on $L_0^1$ while forcing $L^2_0$ and $L^3_0$ further into their upper-tail, while smaller values push $L_0^1$ into its lower-tail and increase the probabilities for the remaining times. 

    The passage times are asymptotically Tracy-Widom GUE variables, and as such they have asymmetric tails. The estimates in [LR:betadeviations] tell us that the upper-tail decays as $\exp(- c t^{3/2}/\sqrt{n})$, whereas the lower-tails have the much harsher $\exp( - c t^3 / n)$ decay. We find that the main contribution to the sum will happen at $a \sim - n^{\alpha / 2}$, and that the leading cost is on the scale $\exp(-c n^{3 \alpha - 2})$. Moreover, the contribution of $L^2_0$ dominates if $t \ge \frac{1}{2}$, and otherwise $L^3_0$ dominates. An appeal to Laplace's method shows
    \[
        \mathbb{P}(A_t) \le e^{- c_t n^{3 \alpha - 2}}.
    \]
    The dependence on $t$ in the constant $c_t$ is through the scaling needed to bring the passage times to their Tracy-Widom approximations. A more careful accounting shows that it may be taken uniform in $t$.

    To complete the pro (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition lazy-cycle-criterion of arXiv:2412.08400, '\vspace{-1.0cm} Characterization of Exponential Families of \\ Lumpable Stochastic Matrice'] If any of the following two equivalent conditions are satisfied, then $\mathcal{W}_{\kappa}(\mathcal{Y}, \mathcal{E})$ forms an e-family.
    \begin{enumerate}
        \item[(i)\xspace] For any $P \in \mathcal{W}_{\kappa}(\mathcal{Y}, \mathcal{E})$, there exist a pair of non-negative matrices $D$ and $\Pi$ such that
    \begin{equation*}
        P = D + \Pi,
    \end{equation*}
    where $\kappa_\star \Pi$ is a permutation matrix over $\mathcal{X}$ and $D$ is diagonal.
    \item[(ii)\xspace] For any $(y,y') \in \mathcal{E}, \kappa(y) = \kappa(y')$ implies that $ y = y'$ and the graph $$\left( \mathcal{X},   \left\{  (\kappa(y),\kappa(y')) \colon (y,y') \in \mathcal{E}, \kappa(y) \neq \kappa(y') \right\}  \right)$$ is a cycle.
    \end{enumerate}

[Theorem theorem3.1 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $\zeta\in \Gamma_B$ for some $B>0$. Let $A_n$ be any $n\times n$ symmetric matrix with $A_n\in\mathcal{E}$ (see Lemma (mainquasirandomness1 of the paper) for the event $\mathcal{E}$, and let $c_*>0$, $\mu>0$ be the two constants given there) and let $X\sim \operatorname{Col}_n(\zeta)$ be a random vector independent of $A_n$. Consider two fixed locations $\lambda_1,\lambda_2\in[-4\sqrt{n},4\sqrt{n}]\subset\mathbb{R}$.


  For each $i=1,2$ denote by $\mu_1(\lambda_i):=\sigma_{\operatorname{max}}\left((A_n-\lambda_i I_n)^{-1}\right)$. Then, for any $t_1,t_2\in\mathbb{R}$ and any $u\in\mathbb{S}^{n-1}$, we have the estimate for any $\delta_1,\delta_2\in[e^{-c_*n/2},1]:$
\begin{equation}\begin{aligned}
    &\mathbb{P}_X\left(\left| \left\langle (A_n-\lambda_iI_n)^{-1}X,X\rangle-t_i\right|\leq \delta_i\mu_1(\lambda_i),\quad i=1,2;\quad \langle X,u\right\rangle\geq s\right)\\&\lesssim \delta_1\delta_2\cdot e^{-s}\cdot \int_{\{\theta\in\mathbb{R}^2:\sum_{i=1}^2 |\theta_i\delta_i|^2\leq 2\}} I(\theta)^\frac{1}{2}d\theta+e^{-\Omega(n)},\end{aligned}
\end{equation}
where $I(\theta)$ is defined as follows: 
\begin{equation}
I(\theta):=\mathbb{E}_{J,X_J,X_J'}\exp\left(\langle (X+X')_J,u\rangle-c\left\|\sum_{i=1}^2 \frac{\theta_i}{\mu_1(\lambda_i)}(A_n-\lambda_iI_n)^{-1}(X-X')_J\right\|_2^2
    \right),
\end{equation} where $X'\sim\operatorname{Col}_n(\zeta)$ is independent of $X$ and we take $J\subseteq [n]$ to be a $\mu$-random set (i.e., a subset where each element in $[n]$ has (indepndently) probability $\mu$ to belong to this subset). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cdE of arXiv:2601.10624, 'Source localisation in simple random walks'] For each $d \geqslant 5$, we have
    \begin{equation*}
        \widetilde{c}(d) \geqslant \mathbb{E}[J]^{-1}.
    \end{equation*}
    Consequently, $\widetilde{c}(d) > 0$ for each $d \geqslant 5$, and
    \begin{equation*}
        \widetilde{c}(d) = 1 - O(1/d).
    \end{equation*}

