[Proposition 101 of arXiv:2601.16377, '2601.16377'] Consider a variational datum satisfying Assumptions~\ref{Assumption_A}, \ref{Assumption_B} and \ref{Assumption_C} with $H=1$ and admitting a single band --- we drop the indices $h$ from the notations. Let $\Delta V(z)$ be a holomorphic function in a complex neighborhood of $[\hat a', \hat b']$. Consider the family of variational data parameterized by a real $\epsilon$ in a small enough neighborhood of $0$ and differing from the original variational datum only by the potential $V^t(x) = V(x) + \epsilon \Delta V(x)$. Then, denoting with exponent ${}^{\epsilon}$ all the associated quantities, $\epsilon \mapsto \I^\epsilon[\boldsymbol{\mu}^{\epsilon}]$ is differentiable at $\epsilon = 0$ and its derivative can be computed as
 \begin{equation}

\partial_{\epsilon}\I^\epsilon[\mu^\epsilon]\big|_{\epsilon =0}=-\int_{\hat a'}^{\hat b'} \Delta V(x)\,\mu^0(x)\dd x.
 \end{equation}

[Proposition 16 (Static and pair-specific score weighting) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] For every $0\le\gamma\le1$,
\begin{equation}

g_{s,\lambda,\gamma}(x,y)
=
\sup_{h\in\mathcal H_{\lambda,\gamma}}
\{h(x)-h(y)\},
\end{equation}
\begin{equation}

\mathfrak R_{s,\lambda,\gamma}(P,Q)
=
\frac{1-\gamma}{2}M_s(P,Q)
-
\frac{1+\gamma}{2}\Delta_s(P,Q),
\end{equation}
and
\begin{equation}

\mathfrak D_{s,\lambda,\gamma}(P,Q)
=
\mathfrak R_{s,\lambda,\gamma}(P,Q)
+
\frac{1-\gamma}{2}
\{W_s(P,Q)-M_s(P,Q)\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p:dov-pointwise of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {dov}}] 
    For all $L\geqslant 1$, there exists a random constant $\mathfrak{C}_{(p:dov-pointwise of the paper)}>0$ 
    such that the following is true.
    First, we have
    \begin{align*}
        \mathbb{P}(\mathfrak{C}_{(p:dov-pointwise of the paper)} > m) \leqslant C L^{12} e^{-c m^{3/2}}
        \qquad\text{for all $m\geqslant 0$},
    \end{align*}
    where $C,c>0$ are universal constants.
    Second, for all $(s,x;t,y)\in [-2L,2L]^4\cap\mathbb{R}^{4}_{\uparrow}$, we have
    \begin{align*}
        \left|\mathcal{L}(s,x;t,y) + \frac{(y-x)^2}{t-s}
        \right|
        \leqslant \mathfrak{C}_{(p:dov-pointwise of the paper)}
        (t-s)^{1/3}\log^{4/3}\left(\frac{8L}{t-s}\right).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:LS-2-stage of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] Let $\Omega = \ball{r}{x_0}$ for some $x_0\in \{\pm 1\}^n$.
    Suppose $A\in \mathbb R^{n\times n}$ is a PSD matrix and $h\in \mathbb R^n$ such that for all $xx^{\mathsf{T}} \preceq A$, $h\in \mathbb R^n$, if we define
    \begin{align}
p(u) &\propto  \exp\pa{-\fc{u^2}2}
\sum_{\sigma\in \Omega} \exp\pa{\an{
u\sqrt{\lambda}x+h, \sigma}},
    \end{align}
    then $\mathop{{}\boldsymbol{\mathrm{Var}}}(p)\leqslant V(\lambda)$, for some non-decreasing function $V:[0,1]\to \mathbb R_{\geqslant 0}$. 
    Then 
    \[
\rho_{\mathrm{EC}}(\mu_{A,h}|_{\ball{r}{x_0}})
\geqslant \frac{1}{n} \exp\pa{-2\ensuremath{\left\lVert A \right\rVert_\mathsf{op}}\left( {1 + \int_0^1 V(\lambda)\,d\lambda} \right)}
\geqslant \frac{1}{n}  \exp\pa{-2\ensuremath{\left\lVert A \right\rVert_\mathsf{op}}\left( {1+V(1)} \right)}.
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5. lem: pcpt of aging functions off diagonal of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] For every $l \in \mathbb{N}$ and $\eta > 0$,
  \begin{equation}
    \lim_{\delta \to 0} 
    \limsup_{n \to \infty} 
    \sup_{\substack{(s,t) \in T_{2}(l, \eta)\\ |t-t'| \vee |s-s'| < \delta} }
    |\Phi_{n}^{\nu_{n}}(s,t) - \Phi_{n}^{\nu_{n}}(s',t')| 
    = 0.
  \end{equation}

[Lem 29 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Let $X\sim \Hyp(n_1,n,m)$ and let $\sigma^2=\frac{n_1m(n-n_1)(n-m)}{n^2(n^2-1)}$ be the variance of $X$. There exists an absolute constant $C$ such that for each $k\geq 0$,
    \begin{equation}
        \mathbb P(X=k)\leq \frac{C}{\sigma}.
    \end{equation}

