[Thm tcl of arXiv:2412.06480, 'A SIR epidemic model on a refining spatial grid \\ II-Central limit theorem'] For $3/2<\gamma <2$, as $\varepsilon \to 0$, $\{\mathscr{Y}_{\varepsilon}(t)\; , \;  0\le t\le T \}_{0<\varepsilon<1} \Longrightarrow \{\mathscr{Y}(t)\; , \;  0\le t\le T \}$ in $C\big([0,T]\, ; \,  (\mathrm{H}^{-\gamma})^3\big)\cap  L^2\big(0,T; (\mathrm{H}^{-1})^3\big)$, where the limit $\mathscr{Y}$ is solution of the following system of SPDEs : for all $\varphi \in \mathrm{H}^{1}$
	\begin{equation}
	\left\{
	\begin{aligned}
	\big\langle \,  \mathscr{U}(t), \varphi \ \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}}
	&=\mu_S\int_0^t\!\! \big\langle \;  \mathscr{U}(r)\; ,\; \Delta\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr +\!\! \int_0^t\!\! \big\langle \, \mathscr{V}(r) , \,\beta(.) \dfrac{\mathbf{i}(r)\big(\mathbf{i}(r)+\mathbf{r}(r)\big)}{\mathbf{a}^2(r)}\varphi \, \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr\\
	&\hspace{-0.5cm}+ \int_0^t \big\langle \; \mathscr{U}(r), \, \beta(.) \dfrac{\mathbf{s}(r)\big(\mathbf{s}(r)+\mathbf{r}(r)\big)}{\mathbf{a}^2(r)}\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr + \big\langle\, \mathscr{M}^S(t)\, , \, \varphi\; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} 
	\\[2mm]
	\big\langle \;  \mathscr{V}(t), \varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} &= \mu_I\int_0^t \!\!\big\langle \,  \mathscr{V}(r)\; ,\; \Delta\varphi \, \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr - \int_0^t\big\langle \; \mathscr{V}(r), \, \beta(.) \dfrac{\mathbf{i}(r)\big(\mathbf{i}(r)+\mathbf{r}(r)\big)}{\mathbf{a}^2(r)}\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}}  dr\\
	& \hspace{-2cm}- \int_0^t \big\langle \;  \mathscr{U}(r), \, \beta(.) \dfrac{\mathbf{s}(r)\big(\mathbf{s}(r)+\mathbf{r}(r)\big)}{\mathbf{a}^2(r)}\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr + \int_0^t\big\langle \; \mathscr{V}(r), \alpha(.)\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr+\big\langle\, \mathscr{M}^I(t)\, , \, \varphi\; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} 
	\\[3mm] 
	\big\langle \;  \mathscr{W}(t), \varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}}
	&= \mu_R \int_0^t \big\langle \;  \mathscr{W}(r)\,,\,\Delta\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr - \int_0^t\big\langle \; \mathscr{V}(r), \alpha(.)\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr + \big\langle\; \mathscr{M}^R(t)\, , \, \varphi\; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} \, .
	\end{aligned}
	\right.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

