\begin{equation}

 \norm{P_L\lambda_wP_Q}_{\Sch_2}^2
 =\#\{x\in A_Q:wx\in A_L\}
 \le C_\Gamma\min\{L,Q\}^{D}.
\end{equation}
Moreover $\norm{P_L\lambda_wP_Q}_{\cL}\le1$.

[Corollary COR63 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that the assumptions of Theorems~(THM61-2 of the paper) and (THM61 of the paper) are both satisfied. If the transition density function of $X$ satisfies
      \begin{equation}
    p(t,y,z)\asymp \frac{1}{t^{\alpha/\beta}}\exp \left\{-C_2\left(\frac{d(y,z)}{t^{1/\beta}}\right)^{\beta/(\beta-1)} \right\},\quad 0<t\leq T, y,z\in E
 \end{equation}
 for some $\alpha>0,\beta>1, C_2>0$ and $T>0$, then
 for any $x\in E$ and $B\in \mathscr{B}^n(E)$,
    \begin{equation}
        \lim_{t\downarrow 0}\frac{-t^{1/(\beta-1)}\cdot \left(\log \mathbb{P}^x[\sigma_B\leq t]\right)}{C_2}= \widetilde d(x,B)^{\beta/(\beta-1)}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2607.08129, '2607.08129'] There is a constant $C<\infty$ such that, for all sufficiently large $n$,
\begin{equation}
 \sup_{0\le t\le1}
 \abs{\log L_{\floor{nt}}-S_n(t)}
 \le C\sqrt n.
\end{equation}

[Lem bound_on_bm of arXiv:2509.06730, 'Hyperbolic branching Brownian motion: \\ the empirical limit measure'] For any $x\in \ensuremath{\mathbb{R}}$, $y\in (0,\infty)$ and any interval $I\subseteq \ensuremath{\mathbb{R}}$ we have that
    \begin{equation*}
        \ensuremath{\mathbb{P}}_{(x,y)} (X_\infty\in I)\leq\left( \frac{1}{\pi} \frac{\vert I \vert}{y} \right)\wedge 1,
    \end{equation*}
    {where $\vert I \vert$ is the length of the interval.}

