body:
[Theorem 12 (Properties of the signature) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Let $H > 1/4$ and $\lambda > 0$.
\begin{enumerate}[label=(\alph*)]
  \item \textbf{Existence and convergence:}
    $S(\mathbf{B}_{H,\lambda})_{0,T}$ exists in $T((\mathbb{R}^d))$,
    converges absolutely almost surely and in $L^q(\Omega)$ for all
    $q \ge 1$.
  \item \textbf{Factorial decay:} For each $k \ge 1$,
    \begin{equation}

    \mathbb{E}\bigl[|\mathbb{B}^{(k)}_{H,\lambda}(0,T)|^2\bigr]^{1/2}
    \le \frac{C(H,\lambda)^k\,T^{kH}}{(k/2)!},
    \end{equation}
    where $(k/2)! := \Gamma(k/2+1)$ and
    $C(H,\lambda) = C_2(H,\lambda)^{1/2}$ is the square root of
    the constant in \eqref{eq:moment2} with $q=2$.
  \item \textbf{Expected signature:}
    $\mathbb{E}[S(\mathbf{B}_{H,\lambda})_{0,T}]$ is well-defined
    in $T((\mathbb{R}^d))$ and uniquely determines the law of
    $B_{H,\lambda}$ among centred Gaussian processes with the same
    covariance structure \cite{Chevyrev2018}.
\end{enumerate}

[Lemma 6 of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Suppose $x^\star \thicksim \mathcal{G}_n$, $\mathcal{G}_n = diag(\sigma_1,\dots,\sigma_n)$ has singular values $\sigma_1 \geq \sigma_2 \geq \dots \geq \sigma_n >0 $. Let $G_k = diag(\sigma_1,\dots,\sigma_k)$. Let $A \in \R ^{m\times n}$, $A_{ij}\stackrel{i.i.d}{\sim} \mathcal{N}(0,1)$. For fixed $A$, for $k \in [m,n]$,  and the MAP estimator from $\eqref{eq2}$ obeys 
\begin{align}
    \mathrm E_{x^\star \sim \mathcal{G}_n} \big\| \hat{x}(k) - x^\star \big\|_2^2 = \Big\| G_k P_{G_k^T A_k^T} - G_k \Big\|_F^2 + \big\| \widetilde{G}_k \big\|_F^2 \nonumber + \Big\| G_k (A_k G_k)^\dagger \widetilde{A}_k \widetilde{G}_k \Big\|_F^2,
\end{align}
furthermore,
\begin{align*}
    \mathrm E(k) &=\mathrm E_A \mathrm E_{x^\star \sim \mathcal{G}_n} \big\| \hat{x}(k) - x^\star \big\|_2^2 \\
    &= \mathrm E_{A_k} \left( \| G_n \|_F^2 - \Big\langle G_k^2, P_{G_k^T A_k^T} \Big\rangle + \Big\| G_k (A_k G_k)^\dagger \Big\|_F^2 \sum_{i = k+1}^n \sigma_i^2 \right)
\end{align*}
where $P_{G_k^T A_k^T} = G_k^T A_k^T (A_k G_k G_k^T A_k^T)^{-1} A_k G_k$.

