[Lemma convergence of the truncated polymer partition function of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] {}
	Assume that $\lim_{N\to\infty} \beta_N V_N (a_N)^{-d}= \hat{\beta} \in [0,\infty)$.
	Then, for every $A > 0$, we have the following convergence in distribution: 
	\begin{equation}
	Z_{N,A}^{\omega,\beta_N} \xrightarrow[\ N\to\infty\ ]{(d)}
	{\ensuremath{\mathcal Z}}_A^{\boldsymbol\zeta, \hat{\beta}} = \sum\limits_{k \, \geqslant\, 0} \hat{\beta}^k \int_{0 < t_1 < \dots < t_k < 1} \int_{({\ensuremath{\mathbb R}} ^{d})^k} \boldsymbol\psi_A^{(k)}\big((t_1,x_1),\dots,(t_k,x_k)\big) \prod\limits_{j=1}^k \boldsymbol\zeta(\mathrm{d} t_j \mathrm{d} x_j),
	\end{equation}
	where $\boldsymbol\psi_A^{(k)}\big((t_1,x_1),\dots,(t_k,x_k)\big) := \prod\limits_{j=1}^k g_{t_j-t_{j-1}}(x_j - x_{j-1})\, \mathrm{E}[f_A({\ensuremath{\mathbf X}} ^*) \mid {\ensuremath{\mathbf X}} _{t_1} = x_1, \dots , {\ensuremath{\mathbf X}} _{t_k} = x_k]$. 

	\noindent
	The convergence also holds for the finite-dimensional marginal distributions of the process $(Z_{N,A}^{\omega,\beta_N})_{A > 0}$.

	\noindent
	Furthermore, for every $p \in [1,\gamma)$, $\lim\limits_{N \to +\infty} \mathds{E}[|Z_{N,A}^{\omega,\beta_N}|^p] = \mathds{E}[|{\ensuremath{\mathcal Z}}_A^{\boldsymbol\zeta,\hat{\beta}}|^p] < +\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 16 (Finite-scale RG pointwise dimension) of arXiv:2606.07931, 'Pointwise Complexity for Gaussian Fields:\\Upper Envelopes, Algorithmic Lower Bounds, and '] Assume the metric domination \eqref{eq:rg-metric-domination}.  Choose resolutions \(u_j>0\) such that \(\sum_{j=0}^{J-1}u_j^2\le c\varepsilon^2\).  Construct a trajectory-independent hierarchical prior \(\Pi\) by independently, at each level \(j\), sampling a phase label \(a\), an effective rank \(r\), a reference subspace \(\bar V\in\operatorname{Gr}(p_j,r)\), and then sampling \(g_j\) uniformly in \(B_2(2R_j)\cap\bar V\).  Then, there exists an absolute constant $C>0$ such that uniformly for every trajectory \(g\),
\begin{equation}
\log\frac1{\Pi(B_\rho(g,\varepsilon))}
\le
C\sum_{j=0}^{J-1}
\left[
 d_{\mathrm{eff}}(G_j(g,\varepsilon),R_j,u_j)
 +
 \mathfrak A_j(g,\varepsilon,u_j)
\right].
\end{equation}

