[Proposition 17 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] (\cite[Proposition~7.1]{kavvadias2025continuity})

Suppose that we have the same setup described above. Let $U \subseteq \CC$ be open and connected and let $K_1,K_2 \subseteq U$ be connected , disjoint compact sets which are not singletons. Then, for all $r>0$, it holds with probability at least $1-O_A(A^{-b(\xi) \sqrt{M(\xi)}})$ as $A \to \infty$, at a rate which is uniform in the choice of $r$ and $\xi$ and depends only on $K_1,K_2$, and $U$, that
\begin{equation}
    \widetilde{D}_h^{\xi}(r K_1,rK_2 ; r U) \leq A r^{\xi Q(\xi)} e^{\xi h_r(0)}.
\end{equation}  
More precisely, there exist constants $c,A_0>0$ depending only on $K_1,K_2$, and $U$, such that for all $A \geq A_0$, we have that \eqref{eq:lqg_bound} holds with probability at least $1-C A^{-b(\xi) \sqrt{M(\xi)}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 22 of arXiv:2607.27932, '2607.27932'] For $N$ sufficiently large, it holds:
	for any $\delta>0$, $1\le i\le N$,
	\begin{equation}

		\lim_{\sigma\to0}\PP\left(\exp\left[\frac{2}{\sigma^2}\left(H_0(\lambda_0)-\delta\right)\right]<
		C^i_N(\sigma)<\exp\left[\frac{2}{\sigma^2}\left(H_0(\lambda_0)+\delta\right)\right]\right)=1\,,
	\end{equation}
	and
	\begin{equation*}
		\lim_{\sigma\to0}\PP\left(\max\big(| X^{i,N}_{C^i_N(\sigma)}-\lambda_0|;| Y^{i,N}_{C^i_N(\sigma)}-\lambda_0|\big)\leq\delta\right)=1\,.
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (Hyperbolic score reduction) of arXiv:2609.02362, '\textbf{Farthest-cell triplet entropy: high-dimensional shell limits and hyperbolic curvat'] Under \cref{eq:hyper-thin}, the farthest ordering in \cref{eq:hyper-score-exact} is the ordering of
\begin{equation}
 S^{\mathbb H}_{i,d}=\lambda_{d,\mathbb H}\xi_{i,d}-Z_{i,d}+r^{\mathbb H}_{i,d},

\end{equation}
with the same conditional Gaussian angular limit as in \cref{lem:euclidean-score-reduction}. The remainder $r^{\mathbb H}_{i,d}$ is $o_p(1)$ if $\lambda_{d,\mathbb H}=O(1)$ and $o_p(\lambda_{d,\mathbb H})$ if $\lambda_{d,\mathbb H}\to\infty$.

[Lemma lemma6 of arXiv:2412.03450, 'On intermediate levels of nested occupancy scheme in random environment generated by stick'] For each $k \in \mathbb{N}$, let $y_k : [0,\infty) \to \mathbb{R}
$ be a right-continuous bounded and nondecreasing function. Assume that $\lim_{k\to \infty} x_k = x$
on $\mathcal{D}$ and that, for each $t\geq 0$, $\lim_{k\to \infty}y_k(t) = y(t)$, where $y : [0,\infty) \to \mathbb{R}
$ is a bounded continuous function. Then, for all $a,b\geq 0$, a<b,
$$\lim_{k\to \infty} \int_{[a,\,b]} x_k(t) {\rm d} y_k(t) = \int_{[a,\,b]} x(t) {\rm d} y(t).$$

[Corollary 16 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] There exist absolute constants $\delta_0, \gamma,c,C>0$ such that the following holds for $\delta \leq \delta_0$ and $\varepsilon \leq \gamma r_\delta$.
	Let $T \de (2\lceil 10 \Delta /  r_\delta \rceil + 2) r_\delta^2$.
	Then, for $x_0, y \in \cD(\delta)$,
	\begin{align}
		\bbP(X_T \in \sB(y, \varepsilon) \mid X_0 = x_0) \geq (c  r_\delta \lambda_{\min})^{C\Delta/ r_\delta} (\varepsilon/ r_\delta)^2.
	\end{align}

