\begin{center}
$ \exists \eta \in (0,1), \quad \kappa_{1} \leq \alpha \leq \max(\kappa_{2},1-\eta)$ and $\beta \leq \max(\kappa_{2},1-\eta)$.
\end{center}

[Lemma p-moment-X_m of arXiv:2411.13923, 'Harmonic analysis of multiplicative chaos \\ Part I: the proof of Garban-Vargas conjecture'] For any $\gamma\in(0,\sqrt{2})$, any $t\in[0,1]$ and any $p>0$, we have
		\[
		\mathbb{E}[X_j^p(t)]=\left\{\begin{array}{cl}
			e^{\frac{p(p-1)\gamma^2}{2}} &  \text{if $j=0$}
			\vspace{2mm}
			\\
			2^{\frac{p(p-1)\gamma^2}{2}} & \text{if $j\geq1$}
		\end{array}\right..
		\]

[Proposition 24 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] There are product measures $\Pp,Q$ on $\{-1,1\}^n$ such that
$D(Q\Vert \Pp)\asymp H$ and
\begin{equation}
 W_2(\Pp,Q)^2\ge c\sqrt{nH}
\end{equation}
whenever $0<H\le cn$. Thus the term $\sqrt{nH}$ in
\eqref{eq:product-strong} is optimal.

[Lemma 6 of arXiv:2605.13518, 'The inertial It\^{o} drift and its applications to particle collision'] Let $\mathcal{R}^1_{\epsilon}(t)$ and $\mathcal{R}^2_{\epsilon}(t)$ be the mappings defined in \eqref{smf69} and \eqref{smf70}, respectively. For every $T>0$ and $p\geq 1$ and for every $\e \in\,(0,1)$  we have
\begin{equation}
\mathbb{E}\sup_{t \in\,[0,T]}	\vert \mathcal{R}^1_{\epsilon}(t)\vert^p \leq c_{p,T}\left(\mu(\e)+\epsilon\right)^{p/4}.	
\end{equation}
 \begin{equation}\sup_{\e \in\,(0,1)}\mathbb{E}\sup_{0\leq s<t\leq T}\Big|\frac 1{\sqrt{t-s}}\int_s^t\mathcal{R}^2_{\epsilon}(r)\,dr\Big|^p\leq c_{p,T}. \end{equation}

