[Proposition eq:ssshortrange of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] \label[proposition]{thm:ssshortrange}
    Let $\lambda\in[0,2]$ and $\delta\in (0,1)$ be fixed. For any $x,y\in V_N^\delta$, if $\|x-y\|\ll N^{\lambda/2}$, then
    \begin{equation}
        \bar{G}_N(x,y)=\frac{2-\lambda}{\pi}\log N+O(1).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Ito's formula Theorem of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] Let $Y=\left(Y^1,Y^2,\cdots,Y^n\right)$ be an adapted $n$-dimensional process with regulated trajectories admitting the representation
		\begin{equation}
			Y_t=Y^{\ast}_t+\sum_{0 \leq s <t} \Delta_{+} Y_s,\quad \forall t \in [0,T],

		\end{equation}
		where $Y^{\ast}=\left(Y^{\ast,1},Y^{\ast,2},\cdots,Y^{\ast,n}\right)$ is an adapted $n$-dimensional RCLL semimartingale and $\sum_{s <t} \left|\Delta_{+}  Y_s\right|  <+\infty$  a.s. Let $F$ be
		a twice continuously differentiable function on $\mathbb{R}^n$. Then the process
		$\left(F\left(Y_t\right)\right)_{t \leq T}$ admits a representation of the form (equation form of the process for Ito of the paper). Furthermore, almost surely, for each $n \geq 1$ and all $t \leq T$,
		\begin{equation*}
			\begin{split}
				F\left(Y_t\right)
				&=F\left(Y_0\right)+\sum_{k=1}^n \int_{0}^{t} D^k F\left(Y_{s-}\right)dY^{\ast,k}_s+\dfrac{1}{2}\sum_{k,l=1}^n  \int_{0}^{t} D^k D^l F\left(Y_{s-}\right) d\left[Y^{\ast,k},Y^{\ast,l}\right]^c_s\\
				& \quad+\sum_{0 < s \leq t}\left\{ F\left(Y_s\right)-F\left(Y_{s-}\right)-\sum_{k=1}^n  D^k F\left(Y_{s-}\right)\Delta_{-}Y^{\ast,k}_s\right\}
				+\sum_{0 \leq s < t} \left\{F\left(Y_{s+}\right)-F\left(Y_{s}\right)\right\},
			\end{split}
		\end{equation*}
		where $D^k$ denotes the differentiation operator with respect to the $k$-th coordinate, while $\left[\cdot,\cdot\right]^c$ stands for the continuous part of the quadratic variation $\left[\cdot,\cdot\right]$.

