[Lemma EHI:l:PE of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X \in \mathcal{I}(d, r_0)$, and let $T$ be a random variable with Exponential($\lambda$) distribution, independent of $X$. For all $x \in \mathbb{R}^d$ and $r>0$, we have each of the following:
    \begin{equation} 
        \mathbb{P}_x(\tau_{B(x, r)}>T) \geq (1-e^{-1}) \left(1 - \frac{2m_2(X)}{r^2 \lambda} \right)
    \end{equation}
    and
    \begin{equation} 
        \mathbb{E}_x \left[ \tau_{B(x, r)} \wedge T \right] \geq e^{-1} \left(1 - \frac{2m_2(X)}{r^2 \lambda} \right) \frac{1}{\lambda} = e^{-1} \left(1 - \frac{2m_2(X)}{r^2 \lambda} \right) \mathbb{E}[T].
    \end{equation}

