[Corollary lim int M_eta ... of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Let $M_{\lambda,\eta}$ be the solution to equation (equation eq de M_eta + cont. of the paper). Then, for all $\lambda \in \mathbb{C}$ such that, $|\lambda| \leqslant \lambda_0$ with $\lambda_0$ small enough, the following limit holds:
\begin{equation}
\underset{\eta \to 0}{\mathop{\rm lim} } \int_{\mathbb{R}^d} \eta^{\frac{1}{3}} v_1 M_{\lambda,\eta}(v)M(v) \mathrm{d}v = 0 .
\end{equation}
For $\lambda =0$, one has
\begin{equation}
\underset{\eta \to 0}{\mathop{\rm lim} } \int_{\mathbb{R}^d} M_{0,\eta}(v)M(v) \mathrm{d}v = \int_{\mathbb{R}^d} M^2(v) \mathrm{d}v .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1 < p <\infty$ and let $W$ be a matrix weight. There exist a sequence of matrix-valued functions $\widehat W_n$ such that for every $n$, the  entries of $\widehat W_n$ are adapted to $ \mathcal F_n$ and
		\begin{equation}
			\|\widehat W_ne\|^{p'}_{\mathbb C^d}\thickapprox_d \mathbb E_n\big(\|W^{-\frac1p}e\|_{\mathbb C^d}^{p'}),\quad \forall e\in\mathbb C^d.
		\end{equation}
Moreover, for all $n\in\mathbb N$ we have
\begin{equation}
\mathbb E_n\big(\|W^{-\frac1p}\widehat W_n^{-1}\|^{p'}\big)=\mathbb E_n\big(\|\widehat W_n^{-1}W^{-\frac1p}\|^{p'})\lesssim_{p,d} 1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For $k\geq0$,
\begin{equation}
        \Prob(B=k)
        =\left(\frac{1-a}{1+a}\right)^L
        a^k
        \sum_{j=0}^{\min(L,k)}
        \binom{L}{j}\binom{L+k-j-1}{k-j}.
\end{equation}
The mean and variance are
\begin{equation}
        \EE B=\frac{2La}{1-a^2},
\end{equation}
\begin{equation}
        \Var(B)=\frac{2La(1+a^2)}{(1-a^2)^2}.
\end{equation}
The same formulas hold for $R$ after replacing $a$ by $b$.

[Corollary 47 (Concentration bounds, very high probability) of arXiv:2606.24887, '2606.24887'] Fix $\delta \in (0,1)$. Under the assumptions of \cref{prop:lardev}, if furthermore we have $\psi/ \gamma \ge N^{\delta/ 4}$ then with very high probability
		\begin{equation*}
			\absbb{ \sum_{i} a_i X_{i}} \le \mathcal{C} \psi,~~~\absbb{ \sum_{i  \neq  j} b_{ij} X_{i}X_{j}} \le \mathcal{C} \psi ~~ \text{and} ~~  \absbb{\sum_{i,j} b_{ij} X_i Y_j} \leq \mathcal C \psi. 
		\end{equation*}

