[Proposition 18 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] If $\mathbf{f} \in \cC^k_1(\cB)$, then $f^{\cA} \in C^k\big(\cA_{c,\sa}^{\cB};\cA\big)$, and
\begin{equation}
    Df^{\cA}(x)[y] = \partial f^{\cA}(x,x)\sh y + \tau\otimes\id_{\cA}\left( \widetilde{\partial}f^{\cA} \sh (y\otimes 1) \right) \qquad \left(x, y \in \cA_{c,\sa}^{\cB}\right), 
\end{equation}
where $D$ denotes the Fr\'echet derivative---in particular, $D^0f^{\cA}=f^{\cA}$ and,
$$ D^jf^{\cA}(x)[y_1,\dots,y_j] = \lim_{t\to 0} \frac{D^{j-1}f^{\cA}(x+ty)[y_1,\dots,y_{j-1}] - D^{j-1}f^{\cA}(x)[y_1,\dots,y_{j-1}]}{t}. $$
Besides, there exists a universal constant $C_j$ such that for all $x\in \cA^{\cB}_{c,\sa}$ with $\norm{x}_{\cA,c}\leq R$,
\begin{equation}

    \norm{D^jf^{\cA}(x)[y]}_{\cA^{0,1}} \leq C_j \norm{f}_{j,c,R} \norm{y_1}_{\cA,c}\dots \norm{y_j}_{\cA,c}.
\end{equation}

[Lemma 2 of arXiv:2608.30232, 'Strong Unique Continuation for Fractional Schr\"odinger Operators'] The exponents above satisfy
\begin{equation}
    1<Q<2<P<p_*,
    \qquad
    \frac1Q-\frac1P=\frac{\alpha}{n},
    \qquad
    Q<\frac n\alpha.
\end{equation}
Moreover
\begin{equation}
    \frac1Q=\frac1{n/\alpha}+\frac1P,
\end{equation}
and
\begin{equation}
    1<S<\frac n\beta,
    \qquad
    \frac1S-\frac1R=\frac\beta n.
\end{equation}

[Lemma 28 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $\eps > 0$. Then, there exists $C = C(\eps,P,\G)$ such that 
	\begin{equation}
	\left< |\vp_o| \right>_{\G,\beta,h} \leq C
	\end{equation} 
	for all $0 \leq \beta \leq 1 / \eps$ and $0 \leq h \leq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:powermean of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] For $-\infty \leq q \leq \infty$, the \emph{$q$-power mean} \\ $\mathcal{M}_{q}(a,b)$ of two numbers $a, b > 0$ is given by
	\begin{equation} 
		\mathcal{M}_{q}(a,b) = 
		\begin{cases}
			\min(a,b), & \text{ if } q = -\infty, \\
			\left(\frac{ a^q + b^q }{2}\right)^{\frac{1}{q}}, & \text{ if } q \in (-\infty,0) \cup (0,\infty), \\
			\sqrt{a b}, & \text{ if } q = 0, \\
			\max(a,b), & \text{ if } q = \infty. \\
		\end{cases}
	\end{equation}

