[Definition 77 (Antipode) of arXiv:2605.14630, '2605.14630'] The \emph{antipode} $\cA:\spanF\to\spancF$ is defined inductively by $\cA(\unit)=\unit$ and 
\begin{align}
 \cA(\Gamma) &= -\Gamma - 
 \sum_{\substack{\unit\neq\overline\Gamma\subsetneq\Gamma, \overline\Gamma \in \Fminus}} 
\cA(\overline\Gamma)\cdot(\Gamma/\overline\Gamma)\\
&= - \Gamma - \cM(\cA\otimes\id) \DeltaCKred(\Gamma)\;.

\end{align} 
Here $\DeltaCKred = \DeltaCK - \Gamma\otimes\unit - \unit\otimes\Gamma$ 
denotes the \emph{reduced coproduct}, and the map $\cM:\spancF\otimes \spancF\to\spancF$ denotes multiplication, defined 
by $\cM(\Gamma_1\otimes\Gamma_2) = \Gamma_1 \cdot \Gamma_2$.

[Definition def:collapse of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] For $i\in\{1,2\}$, the non-positive definite self-adjoint linear operators $({\mathcal{C}}_i,\dom({\mathcal{C}}_i))$ on $\mathbb{H}^l$ defined by 
    \begin{eqnarray*}
        \langle f,-{\mathcal{C}}_ig\rangle &=& \mathcal{E}_i^\mathcal{L}(f,g)\qquad\text{for all }f\in\dom(\mathcal{E}_i^\mathcal{L})\cap\mathbb{H}^l\text{ and }g\in\dom({\mathcal{C}}_i)\,  ,\\
        \dom({\mathcal{C}}_i) &=& \left\{  g\in \mathbb{H}^l:\exists\, h\in \mathbb{H}^l\text{ s.t.\ }\mathcal{E}_i^\mathcal{L}(f,g)=\langle f,h\rangle \text{ for all }f\in\dom(\mathcal{E}_i^\mathcal{L})\cap\mathbb{H}^l\right\}
    \end{eqnarray*}
    are called the
    \emph{symmetric first- and second-order collapse of $\mathcal{L}$}.

[Prop 9 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] The family $\{({\zeta}_t^{(h)})_{0 \leq t \le T}\}_{{h \in T/{\mathbb N}^*}}$ given by \eqref{interpo1} induces a tight family of probability measures on the space $\mathbb{D}([0,T],\mathcal{H}^{-2}_{\mathrm{Sym}}(\mathbb{S}))$ of c\`adl\`ag functions from $[0,T]$ to $\mathcal{H}^{-2}_{\mathrm{Sym}}(\mathbb{S})$.
In addition, there exists a constant $C$ such that, for any $h \in {T/{\mathbb N}^*}$, 
    \begin{equation}
    \begin{split}
	 \mathbb{E}\Big[ \sup_{0\leq t\leq T}\|{\zeta}_t^{(h)}\|_{2,-2}^{2} \Big]&\leq C (1+\mathbb{E}\|X_0\|_2^{2})
    \\
	\mathbb{E}\|\zeta_{t}^{(h)}-\zeta_{s}^{(h)}\|_{2,-2}^{2} &\leq  C(t-s)  + {\mathcal O}_h(1), \quad 0 \leq s < t \leq T,
    \end{split}
\end{equation}
where the Landau term 
${\mathcal O}_h(1)$ tends to $0$ with $h$, and is independent of the parameters 
$s$ and $t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 75 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $l\geq 1$.
There are constants $c_{l},c'_{l}>0$,
depending only on $l$,
same as in Lemma \ref{Lem moment nu eps},
such that for every $\varepsilon>0$ and $z\in\C$,
\begin{displaymath}
\E[\vert\nu^{\rm gen}_{0,\varepsilon}\vert(z)^{2 l}\vert \mathcal{F}_{m}^{\rm gen}]
= c_{l} (2\lambda)^{2l} + c'_{l} G_{D\setminus A^{\rm gen}_{0},\varepsilon,\varepsilon}(z,z)^{l}
~~\text{a.s.}
\end{displaymath}
In particular,
\begin{displaymath}
\E[\vert\nu^{\rm gen}_{0,\varepsilon}\vert(z)^{2 l}]
= c_{l} (2\lambda)^{2l} + c'_{l} G_{D,\varepsilon,\varepsilon}(z,z)^{l}.
\end{displaymath}

