[Theorem thm:first of arXiv:2605.05904, 'Schr\"odinger's problem with constraints'] Under Assumptions~(a:main of the paper) and (ass:f of the paper), the SDE 
\begin{equation}

\begin{split}
X_t &=x_0+\int_0^t \mathbf{I}(u, X_u)\cdot
\left\{\mathbf{b}(u,X_u) + \Sigma^2(u,X_u)\frac{(\nabla h(u,X_u))^*}{h(u,X_u)}\right\} du\\
&\hspace{1cm}+\int_0^t \mathbf{I}(u, X_u)\cdot\Sigma(u,X_u)d\beta_u
\end{split}
	\end{equation}
 admits a unique weak solution,	where $A^*$ stands for the transpose of matrix $A$, $x_0=(z_0,z_0)$, and $\beta$ is a 2-dimensional standard Brownian motion. The corresponding   law of the solution coincides with the unique minimiser $P^*$ of the \sch problem $\mathcal{S}_E(\mu_0,\mu_1)$ in (equation P:unconstrainedeps of the paper). In particular, for every $t\in [0,1]$, $\frac{dP^*}{dR}|_{\cF_t}=h(t,X_t)$.

[Lemma lem:ineq-pivot-site-bond of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $0 < p, q < 1$ and $n \in \mathbb N^*$. Then for $e \in V_1$ with neighbours $x, y$,
  \begin{equation}
    \mathbb P(e \text{ pivotal for } A_n) \leqslant \frac qp (\mathbb P(x \text{ pivotal for } A_n) + \mathbb P(y \text{ pivotal for } A_n))
  \end{equation}
  and, for $x \in V_0$,
  \begin{equation}
    \mathbb P(x \text{ pivotal for } A_n) \leqslant \frac {(2d-1)p} {q (1-p)^{2d-1}} \sum\limits_{e \in \mathcal N(x)} \mathbb P(e \text{ pivotal for } A_n),
  \end{equation}
  where $\mathcal N(x)$ denotes the set of vertices adjacent to vertex~$x$\footnote{Note that $\mathcal N(x) \subset V_1$ corresponds to the set of edges adjacent to $x$ in the original graph.}.

[Definition Lower_env of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Associated with the marked Poisson point process of the stations
$\tilde{\Phi}=\sum_{i\in \mathbb{N}}\delta_{(R_i,\alpha_i)}$, define the function

$$t\mapsto L(t):=\inf_{i\in \mathbb{N}} f((R_i,\alpha_i), t).$$

The stochastic process $\{{\mathcal L }(t)=(t,L(t))\}_{t\in \mathbb{R}}$ is called the lower envelope process, where the random variable $L(t)$ represents the distance of the closest station at time $t$. 
The \textbf{lower envelope} is the random closed set on $\mathbb{H}^+$ defined as 

\begin{equation}
	{\mathcal L }_e:=\{(t, L(t)),\ t\in \mathbb R\} \subset \mathbb{H}^+.{\nonumber}

\end{equation}

[Prop 12 (A priori controls on the densities in the H\"older case) of arXiv:2604.20323, '2604.20323'] Set $\gamma:=\alpha-1+\beta$. 
\begin{itemize}
\item Aronson type bounds.\\
There exists $C:=C(\textcolor{black}{d},b,\alpha,T)<\infty$ s.t. for all $0\le s<t\le T,\ x,y,\in \R^d$,
\begin{align}

			\Gamma(s,x,t,y)\le C\bar p_\alpha(t-s,y-x).
			\end{align}
{Similarly, there exists $C<\infty$ such that for $h=\frac{T}{n},\ n\in \mathbb N^*$, $0\le t_k<t\le T$, $x,y\in\R^d$,}
                 		\begin{align}
			&\Gamma^h(t_k,x,t,y)\le C \bar p_\alpha (t-t_k,y-x).
		\end{align}

\item Forward regularity of the density of the diffusion. 
For $\varepsilon \in (0,\textcolor{black}{\gamma\wedge 1}] $, there exists $C_\varepsilon :=C_\varepsilon(\textcolor{black}{d},b,\alpha,T)$ s.t. for all $0\le s<t\le T,\ x,y,w\in \R^d$ s.t.  $|y-w|\le (t-s)^{\frac 1\alpha} $,
\begin{align}

			|\Gamma(s,x,t,y)-\Gamma(s,x,t,w)|\le \textcolor{black}{C_\varepsilon}\left(\frac{|y-w|}{(t-s)^{\frac1\alpha}} \right)^{\textcolor{black}{\gamma_\varepsilon}}\bar p_\alpha(t-s,w-x),\ \gamma_\varepsilon:=(\gamma\wedge 1)-\varepsilon.
\end{align}
\item Forward regularity of the density of the scheme.
		For all $0< t_j<t_k\le T $, $x,y,w\in \R^d $, $|y-w|\le (t_k-t_j)^{\frac 1\alpha} $,
		\begin{align}

			|\Gamma^h(t_j,x,t_k,y)-\Gamma^h(t_j,x,t_k,w)|\le \textcolor{black}{C_\varepsilon} \left(\frac{|y-w|\textcolor{black}{+h^{\frac 1\alpha}}}{(t_k-t_j)^{\frac1 \alpha}} \right)^{\textcolor{black}{\gamma_\varepsilon}}\bar p_\alpha(t_k-t_j,w-x).
			\end{align}
If additionally $\alpha-1>\beta $ it holds that,
		for all $0< t_j<t_k\le T $, $x,y,w\in \R^d $, $|y-w|\le (t_k-t_j)^{\frac 1\alpha} $,
		\begin{align}

			|\Gamma^h(t_j,x,t_k,y)-\Gamma^h(t_j,x,t_k,w)|\le C \left(\frac{|y-w|}{(t_k-t_j)^{\frac1 \alpha}} \right)^{\beta}\bar p_\alpha(t_k-t_j,w-x).
			\end{align}
\item Besov norms involving the drift and the density of the diffusion.
There exists a constant $C\ge 1$ s.t.	 for 
 $s\in [h,t] $, $2h\le t\le T $,	and $\Psi\in B_{\infty,\infty}^\beta $,	
		\begin{align}

			\|\Gamma(0,x,s,\cdot)\Psi\|_{B_{1,\infty}^{\beta}}\le C(1+s^{-\frac \beta\alpha})\|\Psi\|_{B_{\infty,\infty}^\beta},
			\end{align}
\item Besov norms involving the drift and the density of the {Euler scheme}.
Assume that $\alpha-1>\beta $. There exists a constant $C\ge 1$ s.t.	 for  
$s\in [h,t] $, $2h\le t\le T $,	and $\Psi\in B_{\infty,\infty}^\beta $,	
		\begin{align}

			\|\Gamma^h(0,x,\tau_s^h,\cdot)\Psi\|_{B_{1,\infty}^{\beta}}\le C(1+s^{-\frac \beta\alpha})\|\Psi\|_{B_{\infty,\infty}^\beta}.
			\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

