[Cor exponents of arXiv:2606.19583, 'Power-law hypothesis and (un)fairness of PageRank on undirected multi-type PAMs'] For $k \in S$,
\begin{align}
&\liminf_{n \rightarrow \infty} \mathbb{P}(R_{\phi_n}(G_n)>r \mid X_{\phi_n}=k) \geq (1+o(1))\frac{\Gamma(m_k+\frac{2}{\varphi_k^{\boldsymbol{m}}})}{\Gamma(m_k)}\gamma^{-(\lambda_k^{\boldsymbol{m}}-1)}r^{-(\lambda_k^{\boldsymbol{m}}-1)}\cr
&\limsup_{n \rightarrow \infty} \mathbb{P}(R_{\phi_n}(G_n)>r \mid X_{\phi_n}=k) \leq (1+o(1))\frac{\Gamma(m_k+\frac{2}{\varphi_k^{\boldsymbol{m}}})}{\Gamma(m_k)}r^{-(\lambda_k^{\boldsymbol{m}}-1)}.  
\end{align}
Thus, the exponent for the limiting power-law tails of the PageRank of a uniformly chosen vertex of color $k$ is $\lambda_k^{\boldsymbol{m}}-1=\frac{2}{\varphi_k^{\boldsymbol{m}}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 2 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] The Liouville Brownian motion $(Z_t)_{t\ge 0}$ is the process obtained as a time-change of $X$, namely $Z_t = X_{F^{-1}(t)}$, where $F^{-1} (t)$ denotes the inverse of the additive functional of $X$ (the so-called quantum clock) given by 
\begin{equation}
F(t) = \int_0^t e^{\gamma \ph(X_s)} \dd s := \lim_{\eps \to 0} \int_0^t \eps^{\gamma^2/2} e^{\gamma \ph_\eps(X_s)  } \dd s.
\end{equation}

[Lemma 8 of arXiv:2607.25986, 'Asymptotics of a two-species particle system associated to the doubly parabolic Keller-Seg'] For any $\sigma \in (0,\frac 12]$, any $\alpha>0$, any $\gamma \in (\frac 32,2)$, any $T>0$, any $\eta>0$,
there exists a constant $A_{\sigma,\eta,T}$ (also depending on $\lambda,\theta,\gamma,\alpha,c_0$) such that 
if $(N,M,\e)\in \Aa_\sigma$, for all $u\in [0,T]$,
\begin{align*}
\E\Big[\int_0^u |D^1_t|^{2\gamma-2} \dd t \Big] \leq &
\Big((1+\eta)C_4(\theta,\alpha,\gamma)\Big)^{2\gamma-2}
\E\Big[\int_0^u \int_0^t \int_{\R^2} \frac{\phi(y) \dd y\dd s\dd t}{(t-s+\alpha|R^{1,2}_{t,s}-\sqrt \e y|^2)^{\gamma}}\Big]
+ A_{\sigma,\eta,T},
\end{align*}
where $C_4(\theta,\alpha,\gamma)=C_3(\theta,\alpha)\kappa(\frac{1}{2}, \gamma-1\big)$.

[Lemma 16 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] Given $x \in \ell_\rho^{2\theta}(\mathbb{Z}^+)$, let $\{ \Lambda_n \}$ be a sequence of finite sets of $\mathbb{Z}^+$ with $\{ X^{(n),x} \}$ being the solutions to the associated finite-dimensional SDEs (\ref{CUTSDE}).
		For $k\leq n$, we denote by $X^{(n), x}_{(k)}$ the part of $X^{(n), x}$ that lives in the finite set $\Lambda_k$, that is, $X^{(n), x}_{(k)} = (X^{(n),x}_{1}, \ldots, X^{(n),x}_{k})$. Then for any $k>0$, $\epsilon > 0$ and $T > 0$ there exists a constant $V(\epsilon,T,k) > 0$ such that for any $n, m \geq V(\epsilon,T,k)$
		\begin{align} 
			\mathbb{E}\sup_{t \in [0, T]} \| X^{(n), x}_{(k)}(t) - X^{(m),x}_{(k)}(t) \|^2_{\mathbb{R}^{\Lambda_k}} \leq \epsilon.
		\end{align}

