[Definition 28 (Wick exponential) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $W$ be a real isonormal Gaussian process over $\cH$.  For $h\in\cH$, the
\emph{Wick exponential} of $W(h)$ is
\begin{equation*}
  \mathcal E_W(h)
  :=\exp\left(W(h)-\frac12\|h\|_{\cH}^2\right).
\end{equation*}

[Lemma 49 (Two-parameter Banach-valued time lift) of arXiv:2607.10813, '2607.10813'] Let $B$ be a separable Banach space and
$\Delta_T=\{(t,s):0\le s\le t\le T\}$, equipped with the Euclidean metric.
Let $X:\Delta_T\to L^{p_0}(\Omega;B)$ satisfy, for some $p_0\ge2$ and
$\theta>0$,
\begin{equation}
 \sup_{u\in\Delta_T}\|X(u)\|_{L^{p_0}(\Omega;B)}\le A,
 \qquad
 \|X(u)-X(v)\|_{L^{p_0}(\Omega;B)}\le B_0|u-v|^\theta.
\end{equation}
If $p_0\theta>2$, then $X$ has a $B$-valued continuous modification and,
for every $2\le p\le p_0$,
\begin{equation}
 \|X\|_{L^p(\Omega;C(\Delta_T;B))}
 \lesssim_{T,p_0,\theta}A+B_0.
\end{equation}
The same assertion holds for a sequence of kernels, and for their differences,
with constants uniform whenever the two bounds in
\eqref{eq:time-lift-hypotheses} are uniform.

[Corollary c:BSCFeller of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] In the setting of Theorem~(t:BendikovSaloffCoste of the paper) and under assumptions~(i:t:BendikovSaloffCoste:a of the paper)--(i:t:BendikovSaloffCoste:f of the paper) there, suppose further that
\begin{enumerate}[$(a)$]\setcounter{enumi}{4}
\item $(t,x,y)\mapsto\mssh_{k,t}(x,y)$ is continuous on~${\mathbb R}^+\times M_k^{\scriptscriptstyle\times 2}$ for every~$k$, and~$\mssh_{k,t}\in\mcC_b(\tau_k^{\scriptscriptstyle\times 2})$ for every~$t>0$ and every~$k$.
\end{enumerate}

Then,
\begin{enumerate}[$(i)$]\setcounter{enumi}{7}
\item $(t,\mbfx,\mbfy)\mapsto \boldsymbol\mssh_t(\mbfx,\mbfy)$ is continuous on~${\mathbb R}^+\times \mbfM^{\scriptscriptstyle\times 2}$ and~$\boldsymbol\mssh_t\in\mcC_b(\tau_\mrmp^{\scriptscriptstyle\times 2})$ for every~$t>0$.
\end{enumerate}

In particular, there exists a unique $\boldsymbol\nu$-version of~$\boldsymbol\mssW$ with space-time continuous transition kernel.
\begin{proof}
(i:c:BSCFeller:1 of the paper) is~[BenSaC97].
The uniqueness of~$\boldsymbol\mssW$ follows since~$\boldsymbol\nu$ is Radon and has full $\tau_\mrmp$-support.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn eq:-19 of arXiv:2411.13403, 'Path weighting method for spot sensitivities and its variance reduction'] We denote by $\hat{Z}$ the vector obtained by reflecting the first
element of $Z$, i.e.
\begin{equation}
\hat{Z}=(-Z_{1},Z_{2},\dots,Z_{N}),
\end{equation}
and by $\bar{Z}$ the vector obtained by replacing the first element
of $Z$ by zero, i.e.
\begin{equation}
\bar{Z}=(0,Z_{2},\dots,Z_{N}).
\end{equation}
Moreover, the process $\hat{S}_{t}$ and $\bar{S}_{t}$ are defined
to be generated by replacing $Z$ with $\hat{Z}$ and $\bar{Z}$ in
((eq:-1 of the paper)) respectively, i.e. 
\begin{align}
\hat{S}_{t_{i+1}} & =H_{i}(\hat{S}_{t_{i}},\sqrt{\Delta t_{i+1}}\hat{Z}_{i+1}),\;\hat{S}_{t_{0}}=s,\\
\bar{S}_{t_{i+1}} & =H_{i}(\bar{S}_{t_{i}},\sqrt{\Delta t_{i+1}}\bar{Z}_{i+1}),\;\bar{S}_{t_{0}}=s.
\end{align}

[Proposition 23 of arXiv:2606.05430, 'On a random matrix proof of\\ a bipartite Harer-Zagier formula'] For any $k \geq 1$ and $-M \leq N \leq M$, we have the following equality
        \begin{align*}
            T_{k,M}(N) 
            &= \frac{1}{kM+1}\left[F_{kM+1}^+(N)+(-1)^k\Fm{kM+1}{N}\right] \\
            &= \frac{1}{kM+1}\left[F_{kM+1}^+(N)+(-1)^k\Fp{kM+1}{N-kM}\right]
        \end{align*}

[Theorem 62 (All-degree canonical Gaussian factor and raw-register maximality) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] The series \eqref{all:eq:4.7}--\eqref{all:eq:4.8} converge in $L^2$ and
\begin{equation}
 F=A^{\can}+G^{\can},
 \qquad
 G^{\can}\indep A^{\can}.

\end{equation}
Let $T=\bigoplus_sT_s$ be a closed graded subspace and define the Gaussian factor extracted
from the linear part of $F$ by
\begin{equation}
 G_{T,a}=\sum_{s\ge1}I_1(P_{T_s}\ell_{a,s}).

\end{equation}
Assume that its one-leg raw register against the nonlinear terminal vanishes:
\begin{equation}
 L_{s,\nu}^*t=0
 \qquad(t\in T_s,\ \nu\ge1).

\end{equation}
Then $T_s\subset\cN_s(F)^\perp$ for every $s$, and
\begin{equation}
 \operatorname{Cov}(G_T)
 \preccurlyeq\operatorname{Cov}(G^{\can}).

\end{equation}

[Proposition entropy estimate of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let the interaction $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper) under the condition that (equation eq:small-KS of the paper) holds. Given $\rho_0\in \mathrm{Ent}(\mathbb{T}^2)$ and the solution $\rho^{\gamma, \eta}$ as in Proposition (entropy-mollified-DK-existence of the paper), we have
\begin{align}
\mathbb{E}\left(\int_{\mathbb{T}^2}\Psi(\rho^{\gamma, \eta}(T))\right) + \sigma\mathbb{E}\left(\int_0^T\|\nabla\sqrt{\rho^{\gamma, \eta}}\|_{L^2_{\mathbb{T}^2}}^2\mathrm{d}s\right)\lesssim \int_{\mathbb{T}^2}\Psi(\rho_0) + \varepsilon N_KT, 
\end{align}
for some $\sigma > 0$ which is independent of $\gamma,\eta,\varepsilon$ and $K$.

