[Cor 3 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p$, $\delta$ and $Q_N$ be as in Theorem \ref{Théorème final}. Let $R_N$ be an $N^d\times N^d$ complex deterministic matrix such that there exists $0<\kappa_4\leq d$ so that
    \begin{equation}
        \mathrm{rank}(R_N)=\mc{O}(N^{d-\kappa_4})\m\m\m\m\text{and}\m\m\m\m \norme{R_N}=\mc{O}(1) .

    \end{equation}
    Then, the empirical spectral measure $\mu_N$ of $M_N(p)+R_N+\delta Q_N$ converges weakly in probability to $p_*\mathrm{L}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 21 ({\cite{BF85}*{Theorem 4(c)}}) of arXiv:2609.03836, 'Koszul Orlik--Solomon Algebras from Non-supersolvable Arrangements'] \label[Thm]{thm:tensor_product_Koszul}
    Let $R, S$ be standard graded-commutative  $\mathbb{K}$-algebras.
    The graded-commutative tensor product algebra $R \otimes_{\mathbb{K}} S$ is Koszul if and only if both $R$ and $S$ are. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:entropic_stability of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Let (ass:differentiability of the paper) hold and $\pi_\varepsilon^{\rho\nu},\,\pi_\varepsilon^{\rho\mu}$  be the unique optimizers in (equation EOT of the paper) for the set of marginals $(\rho,\nu)$ and $(\rho,\mu)$. If there exists $\Lambda>0$ such that 
\begin{equation*}
y\mapsto c(x,y)+\psi^{\nu}_\varepsilon(y)
\end{equation*}
is $\Lambda$-semiconcave uniformly in $x\in\supp(\rho)$, then
\begin{equation*}
\mathrm{KL}(\pi_\varepsilon^{\rho\mu}|\pi_\varepsilon^{\rho\nu})\leq \mathrm{KL}(\mu|\nu)+\frac{\Lambda}{2{\varepsilon}}\,\mathbf{W}_2^2(\mu,\nu)\,.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] [Harrem\"oes, Johnson and Kontoyiannis \cite{HJK3}]
    Let $(X_{i})_{1 \le i \le n}$ be independent $\N$--valued random variables. Then, we have
    \begin{displaymath}
        I \Bigg( \sum_{i=1}^{n} X_{i} \Big| \pi_{\lambda} \Bigg) \le \sum_{i=1}^{n} \frac{\E X_{i}}{\lambda} I \Big( X_{i} \big| \pi_{\E X_{i} } \Big) 
    \end{displaymath}
    where $\lambda := \sum_{i=1}^{n} \E X_{i}  .$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 15 of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] Let $v^1,\ldots,v^k$ be vertices in $\mathbb{Z}^2$. Then we have 
\begin{align*}
\mathbb{P} \left( \bigcap_{i=1}^k V_{t_i}(v^i) \right) = \left(\prod_{ j =1}^k a_{t_j}\right) \det_{i,j=1}^{2k}L(x^i,y^j),
\end{align*}
where $L$ is as in \eqref{eq:Ldef}, and $\{ x^i,y^j : 1 \leq i,j \leq 2k \}$ are mid-edges in $\midedge$ defined from the intersection $ \bigcap_{i=1}^k V_{t_i}(v^i)$ as follows. For each $1 \leq i \leq k$ we have
\begin{align*}
x^{2i-1} = W_{v^i} \quad \text{and} \quad x^{2i} = S_{v^i}.
\end{align*} 
As for $y^1,\ldots,y^{2k}$, for each $1 \leq i \leq k$ we have
\begin{align*}
t_i = 1 &\implies y^{2i-1} = W_{v^i} \quad \text{and} \quad y^{2i} = S_{v^i}\\
t_i = 2 &\implies y^{2i-1} = N_{v^i} \quad \text{and} \quad y^{2i} = E_{v^i}\\
t_i = 3 &\implies y^{2i-1} = W_{v^i} \quad \text{and} \quad y^{2i} = N_{v^i}\\
t_i = 4 &\implies y^{2i-1} = E_{v^i} \quad \text{and} \quad y^{2i} = S_{v^i}\\
t_i = 5 &\implies y^{2i-1} = W_{v^i} \quad \text{and} \quad y^{2i} = E_{v^i}\\
t_i = 6 &\implies y^{2i-1} = N_{v^i} \quad \text{and} \quad y^{2i} = S_{v^i}.
\end{align*}
In other words, Theorem~\ref{thm:main} holds, once we note that $[M(w_1,w_2)^{-1}]_{c_1,c_2} = g(w_1,w_2,c_1,c_2)$ as defined in Equations \eqref{eq:gdef1} to \eqref{eq:gdef3}.

