[Prop 33 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] For any fixed integer $N\geq0$ the following factorization holds on any alphabet $(w_1,\dots,w_N)$:
	\begin{equation}

		\sum_{\sigma\in\mathcal{B}_N} \sigma\left(\prod_{1\leq i<j\leq N}
		\left[\frac{w_i-qw_j}{w_i-w_j}\frac{1-w_iw_j}{1- qw_iw_j}\right]\right)=\frac{1}{V_N},
	\end{equation}
    where the constant $V_N$ is given by \eqref{eq:V-normalization}.

[Lemma lem:est for G-SDE of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Suppose Assumption (Assumption G-SDE of the paper) holds. Then we have the following results:
        \begin{itemize}
            \item [(i)] For any $\xi,\eta\in (L_G^2(\hat{\Omega}_s))^n$ and $t\geq s$,
            \begin{equation}
		      \hat{\mathbb{E}}[|X_t^{s,\xi}-X_t^{s,\eta}|^2]\leq e^{-2\alpha(t-s)}\hat{\mathbb{E}}[|\xi-\eta|^2].
	        \end{equation}
            \item [(ii)] For any $p\geq 2$, there exists $C_{\alpha,p}>0$ depending also on $|b(0)|,|h_{ij}(0)|$ and the bound of $\sigma$ such that 
            \begin{equation}
		      \hat{\mathbb{E}}[|X_t^{s,\xi}|^p]\leq C_{\alpha,p}(1+\hat{\mathbb{E}}[|\xi|^p]), \text{ for all } t\geq s, \ \xi\in (L_G^p(\hat{\Omega}_s))^n.
	        \end{equation}
        \end{itemize}

