	\mathbb{P}\big(\mathsf{H}_h^{\diamond}[n,m] \big):=	\mathbb{P}\big(\mathsf{H}_h^{\diamond} , \widetilde{ \mathcal{L}}_{1/2}[n,m]\neq \emptyset  \big)\lesssim u^{-1}\mathbb{P}\big(\mathsf{H}_h^{\diamond}  \big). 
	\end{equation}

