[Lemm 6 of arXiv:2605.23292, 'Second-order Poincaré inequalities and localization on the Poisson space'] Let $h \in L^2(\mathbf{N} \times \WW)$ and let $\tau \in (0,1)$. Then $P_\tau h$ satisfies
    \begin{equation}
        \E \int_\WW \int_\WW \left( D_z P_\tau h(\eta,w) \right)^2 \mu(dz)\mu(dw) < \infty.
    \end{equation}
and $P_\tau h \rightarrow h$ in $L^2(\mathbf{N} \times \WW)$ as $\tau \rightarrow 1$. Moreover, for $w,z \in \WW$ and all $p \geq 1$,
\begin{align*}
    \E |P_\tau h(\eta,w)|^p \leq \E |h(\eta,w)|^p\\
    \intertext{and}
    \E |D_zP_\tau h(\eta,w)|^p \leq \E |D_zh(\eta,w)|^p.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] For all graphs $G=(V,(c_{xy})_{x,y\in V})$,  and site weights $\alpha=(\alpha_x)_{x\in V}$, $\omega=(\omega_x)_{x\in V}$ with $\omega\neq 0$, we have
	\begin{equation}
		{\rm gap}_{\rm BEP}(G,\alpha,\omega,\varrho) = {\rm gap}_{\rm RW}(G,\alpha,\omega)\; \text{,}\;\; \qquad \varrho > 0\; \text{,}\;\;
	\end{equation}
	where ${\rm gap}_{\rm RW}(G,\alpha,\omega)$ is defined in (equation eq:gap-rw-abs of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2609.02801, 'Ratio and limiting zero distribution asymptotics for symmetric multiple orthogonal polynom'] Let \(\Phi(z,t)\) is the solution  of  \eqref{eq:ratio} such that $z^r\Phi(z,t) \to 1$ as $z \to \infty$. 
Then, one has 
\begin{equation}   
   \lim_{N \to \infty} \frac{1}{N} \frac{Q_N'(z,N)}{Q_N(z,N)} = - \frac{1}{r} \int_0^1 \frac{\displaystyle \partial_z \Phi(z,t) }{\Phi(z,t)} \, \mathrm{d}t , 
\end{equation}
uniformly on compact sets of $\mathbb{C} \setminus \Sigma$.

