            \displaystyle |\partial_a^2\widetilde{R}|\lesssim t\left[\frac{a}{(a^0)^5}+\frac{1}{(a^0)^3}\left(\frac{a^0}{\widetilde{R}a^3}+\frac{\sqrt{\ell}}{\widetilde{R}a^2}\right)\right]+t^2\frac{1}{\widetilde{R}(a^0)^5}+\left(\frac{1}{a^2}+\frac{\sqrt{\ell}}{a^3}+\frac{1}{a^4}\right)\log\left\langle \frac{\widetilde{R}}{p}\right\rangle.
        \end{array}
    \end{equation}
    Finally, inside the bulk $\mathcal{B}_t$ defined in (equation equation_def_bulk of the paper), provided that $t \geq C(m)$ for a constant $C(m)$ depending only on $m$, the following holds
    \begin{equation}

        \frac{t\widehat a}{4}\leq |\widetilde{R}|\leq 2t\widehat a,\qquad \partial_a \widetilde{R}\geq \frac{3}{4}t\frac{m^2}{(a^0)^3}.
    \end{equation}

