[Definition 2 of arXiv:2605.16868, '\ttl'] The infinite-dimensional fluid model is defined as follows: 
\begin{equation}

    \bar{Q}(t) =    \bar{X}(t) + ({\bf1}-\boldsymbol{G}^T) \bar{Y}(t),
\end{equation}
where 
\begin{equation}

  \bar{X}(t) =\bar{Q}(0) + \big[\lambda  - ({\bf1} - \boldsymbol{G}^T)\mu \big]  t,
\end{equation}
\begin{equation}

\bar{Y}(t)=\operatorname{diag}(\mu) \bar{I}(t),
\end{equation}
and $ \bar{I}(t)$ satisfies 
\begin{equation}

d\bar{I}_u(t)\geq0\,, \quad \bar{I}_u(0) = 0\,, \mbox{ and } \int_0^\infty 1_{\{\bar{Q}_u(s)>0\}} \bar{I}_u(ds)=0, \quad \forall\,u \in [0,1].
\end{equation}
We denote $\bar{Q} =\Phi_{\boldsymbol{G}^T}(\bar{X}) $ and $\bar{Y} =\Psi_{\boldsymbol{G}^T}(\bar{X})$ and call them as the reflected process and regulator, respectively. It is apparent that $\bar{Q}(0)\ge0$ and $\bar{X}\in\mathcal{C}_T(L_1)$.

[Theorem 2 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Let $V\in\cC^{4k+7}(X_1,\dots,X_d)$ be a $k$-regular potential (see Definition \ref{definition:kregular}), and $Y^N$ a multimatrix model with potential $V$ (see Definition \ref{def:randompot}). There exists a transport map $T^N$ between the law of $Y^N$ and the one of a $d$-tuple of independent GUE random matrices $X^N$, i.e., $T^N$ such that for all measurable functions $f$,
    $$ \E\left[ f(Y^N) \right] = \E\left[ f\circ T^N(X^N) \right].$$

    \noindent Moreover, there exists $T^0 \in (\cC^k(X_1,\dots,X_d))^d$, as well as $T^m\in (\cC^{k+1-m}(X_1,\dots,X_d))^d$ for $m\in [1,k]$, such that, for all $N\geq 1$,
    \begin{equation}

        \sup_{H\in\M_N(\C)_{sa}^d}\ \norm{T^N(H) - \sum_{i=0}^k \frac{T^i(H)}{N^{2i}} } \leq \frac{C_{V,k}}{N^{2k+2}},
    \end{equation}
    for some constant $C_{V,k}$. Besides, there exists another constant $C_{V,k}$ such that
    \begin{align}

        \norm{T^0 - \id }_{\cC^k,\infty}\leq C_{V,k}, \quad\quad \norm{T^m}_{\cC^{k+1-m},\infty}\leq C_{V,k},\quad 1\leq m\leq k.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq_besselfirstmom of arXiv:2411.09976, 'Occupation times on the legs of a diffusion spider'] For any $r\in\{1,\dotsc,R\}$, 
\begin{equation} 
\mathbf{E}_\mathbf{0}\left(A_1^{(1)} A_1^{(2)} \dotsm A_1^{(r)}\right) = (-\nu)^{r-1} \beta_1 \beta_2 \dotsm \beta_r.  
\end{equation}

