[Theorem 4 (Asymptotics of Schr\"odinger potentials) of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Suppose $(\rho_t^\mu)_{t\in[0, 1]}$ is a strictly positive density evolution satisfying Assumption~\ref{assump: density_expansion}. Moreover, assume that there exists a constant $L_\rho\in(0, 1)$ such that 
\begin{align*}
\hbox{$L_\rho \leq \rho_t^\mu(x) \leq L_\rho^{-1}$ for all $x\in\mb T^d$ and $t\in [0,1]$.}
\end{align*}
Then, for each $K \in \mb N^\ast$, there exists a constant
\begin{align*}
    \hbox{$\varepsilon_{\rm thres} > 0$ depending only on $K, d, L_\rho$, and $\sup_{0\leq t\leq 1}\big\{\|\rho_t^{(i)}\|_{\m C^{s+4K-2i+5}}: 0\leq i\leq 2K+2\big\}$}
\end{align*}
 for which the following holds:

If $\max_{j\in[m]}\varepsilon_j \leq \varepsilon_{\rm thres}$, then for every $j\in[m]\coloneqq\{1, 2,\cdots,m\}$, 
there exist continuous functions $\{f_{j,k}: j\in[m], 1\leq k<K\}$ and $\{g_{j,k}: j\in[m], 1\leq k<K\}$ 
on $[0,1] \times \mathbb{T}^d$

satisfying
\begin{align}
\min_{c_j\in\mb R}\bigg\{\Big\|\phi_j^\mu + c_j - \sum_{k=1}^{K-1} \varepsilon_j^k f_{j,k}\Big\|_{L^2(\rho_{t_{j-1}}^\mu)} +
\Big\|\psi_j^\mu - c_j - \sum_{k=1}^{K-1} \varepsilon_j^k g_{j,k}\Big\|_{L^2(\rho_{t_j}^\mu)}\bigg\}
\leq O(\varepsilon_j^K),
\end{align}
where  the big-O notation depends only on 
\begin{align*}
\alpha\in(0, 1),\,\, d,\,\,K,\,\,\mbox{and}\,\, \sup\big\{\|\rho_t^{(k)}\|_{\m C^{\max\{2+\lceil\frac{d+1}{2}\rceil, 4K\}+k',\alpha}}: t\in[0, 1],\,\, 2k+k'=4K+2,\,\,k,k'\in\mb N\big\}.
\end{align*}

\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6 of arXiv:2608.03771, '\vspace{-5ex}\bfseries\scshape{Local law and delocalization for the Sachdev--Ye--Kitaev mo'] Under the assumptions of Theorem~\ref{theo:isolaw}, for any deterministic orthonormal basis $({\bm u}_a^\tau)_{1\leqslant a\leqslant D^\tau}$ of $\Hcal_N^\tau$, we have
\begin{equation}

\mathbb{P}\left(
\max_{j:|\lambda_j^{(\tau)}|\leqslant L}
\max_{1\leqslant a\leqslant D^\tau}
\left|\left\langle {\bm u}_a^\tau,\psi_j^{(\tau)}\right\rangle\right|^2
\geqslant Cu
\right)
\leqslant
\exp\left(-cN^{\frac{q}{2}}u^2\right),
\end{equation}
for $N^{-\frac{1}{2}+\delta}\leqslant u\leqslant 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3G of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small constants $\epsilon,\tau>0$. For any deterministic matrices $\|A_1\|+\|A_2\| \lesssim 1$ and vectors $\|{\bm x}\|, \|{\bm y}\| \lesssim 1$, the following holds
	\begin{equation}

		\Big| \big\langle {\bm x}, \big( G^{z_1}(\mathrm{i} \eta_1)A_1G^{z_2}(\mathrm{i} \eta_2)A_2G^{z_1}(\mathrm{i} \eta_1)-M_{121}^{A_1,A_2}\big) {\bm y} \big \rangle \Big|\prec \frac{1}{\eta_*\gamma}.
	\end{equation}
	uniformly for any $ |z_i|\leq 1+\tau$ and $\min_{i=1}^2 \{|\eta_i| \rho_i \} \geq n^{-1+\epsilon}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem i=0 of arXiv:2412.08334, 'Maker-Breaker on Galton-Watson trees'] Consider $\xi$ with $p_0=0$, where as before $p_k=\mathbb{P}(\xi=k)$, for $k\in\mathbb{N}_0$, is the distribution's pmf and $g$ its pgf. Then the probability $p$ of Breaker winning on a GW-tree arising from offspring distribution $\xi$, when the nodes carry no further information is a solution to
	\begin{equation}
		x^2=g(x).
	\end{equation}
    It is equal to $0$ if $p_1=0$, to $1$ if $\mu\leq 2,\ p_1>0$ and to the (unique) solution in $(0,1)$ in all non-trivial cases ($\mu>2,\ p_1>0$). When Maker begins, the probability of Breaker winning becomes $\bar{p}=g(p)=p^2$.

