body:
[Proposition cor:control of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] The following two hold with $T_\star = 8 \pi$:
  \begin{enumerate}[label=(\roman*)]
    \item Let $\varpi$ be as in (equation eq:shell-reduced of the paper), and set $(a, b) = \mathcal{F}_1
\varpi$. Then (equation eq:shell-reduced of the paper) for $\varpi$ reduces to
      \begin{equation}
        \text{(PSA)}\quad
        \left\{
        \begin{aligned}
          \dot a &= - \frac12 q b + \frac12 p \bar b,\\
          \dot b &= \frac12 \bar q a - \frac12 p \bar a,
        \end{aligned}
        \right.
        \qquad
        \text{(LNS)}\quad
        \left\{
        \begin{aligned}
          \dot a &= \frac12 q b - \frac12 p \bar b,\\
          \dot b &= - \frac12 \bar q a + \frac12 p \bar a .
        \end{aligned}
        \right.
      \end{equation}
depending on whether the evolution is governed by (equation eq:two_operators_intro_PS of the paper) or (equation eq:two_operators_intro_NS of the paper).
    \item With $N_{p,q}$ the generator of that system,
defined in~(equation eq:reduced_undamped of the paper) below, for any $\delta \in (0,1)$ and any $(a_0, b_0), (a_{\star}, b_{\star}) \in \{ \psi \in \mathbf{C}^2  \colon  |\psi|=1\}$ there exists a control $q = q_\delta \in C^{\infty}_c ((0, T_\star); \mathbf{C})$ (with compact support, and $\|q\|_{L^\infty} \leqslant 2$) such that the solution to
      \begin{equation*}
        \partial_t (a, b) = N_{0, q} \cdot (a, b),
      \end{equation*}
with initial condition $(a_0, b_0)$, satisfies $|(a_{T_\star}, b_{T_\star}) - (a_{\star}, b_{\star})| \leqslant \delta$.
  \end{enumerate}

