[Theorem 1 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] Let $X_1,\ldots,X_n$ be independent. Assume that
\[
 \E X_i=0,\qquad \E X_i^2=1,\qquad \norm{X_i}_{\psi_2}\le K.
\]
Let $L>0$, let $f:H_d\to\R$ be convex and $L$-Lipschitz, and put
$Z=f(X^{\otimes d})$. There are constants $c_K,C_K>0$ such that
\begin{equation}
 \Pp\left\{
 \abs{Z-\E Z}>
 C_KL n^{(d-1)/2}
 \left(d\sqrt u+\sqrt{d u\log\left(e+\frac nu\right)}\right)
 \right\}
 \le C e^{-c_Ku}
\end{equation}
whenever
\[
 1\le u\le c_K\frac{n}{d^2}.
\]
The corresponding moment estimate is the following. If $d\le c_K\sqrt n$, then
\begin{equation}
 \norm{Z-\E Z}_{L_p}
 \le C_KL n^{(d-1)/2}
 \left(d\sqrt p+\sqrt{d p\log\left(e+\frac np\right)}\right)
\end{equation}
for
\[
 1\le p\le c_K\frac{n}{d^2}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2-l05 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] There exists a finite constant ${\mathfrak c}({\boldsymbol u}^N)$, depending only on
${\boldsymbol u}^N$, $A$ and the dimension $d$, uniformly bounded in $N$
($\sup_N {\mathfrak c}({\boldsymbol u}^N) < \infty$), such that
\begin{equation*}
\begin{aligned}
& K\, \int  {\mathcal W}^{(2)}_\ell \, f\; d\nu^N \; \le\;
\delta\, N^2 \, I^E_{N}(f; \nu^N)
\; +\; {\mathfrak c}({\boldsymbol u}^N)  \, K\, \sum_{x\in{\mathbb T}_N^d}
\int (\omega^{\ell} _{x})^2 \, f \; d\nu^N
\\
& \;+\; {\mathfrak c}({\boldsymbol u}^N)  \, 
\Big(\frac{K}{N}\Big)^2 \Big\{ \, \frac{1}{\delta}\, \Big[ \, 1 \,+\, 
\frac{K\, s_d(\ell) \,}{N^2} \,\Big] \,+ \,  (1+\lambda)  \Big\} \, \,
\int \sum_{k=1}^d \sum_{x\in{\mathbb T}_N^d} (H^{(\ell)}_{k,x})^2 \, f  \;
d\nu^N
\\
& \quad \;+\; {\mathfrak c} ({\boldsymbol u}^N)\, K^2\, N^{d-2}
\,\Big\{\, \delta \,+\, \frac{s_d(\ell)}{\lambda} \,\Big\} 
\end{aligned}
\end{equation*}
for all $0<\delta<1$, $\lambda>0$, density $f$ with respect to $\nu^N$
and $N> 4\ell$. In this formula, $s_d(\ell)$ is the sequence
introduced in (equation 2-18 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

