[Corollary C:smallball of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose condition (equation E:main of the paper) holds.
  \begin{enumerate}[\rm (i)]

    \item Suppose $\beta\in(0,2)$; or $\beta=2$, $\gamma\in[0,1]$, $\ell<\alpha(\gamma+1/2)$. If $\rho \in (0,1)$,
          then for any compact interval $I\subset (0,\infty)$, there exist two
          constants $0<C_7\le C_7'<\infty$ such that for all $x_0\in \mathbb{R}^d$ and all
          $\varepsilon \in (0, 1)$,
          \begin{align}
            \exp\left( - \frac{C_7'}{\varepsilon^{1/\rho}} \right)
            \le \mathbb{P}\left\{ \sup_{t\in I} |u(t,x_0)| \le \varepsilon \right\}
            \le \exp\left( - \frac{C_7}{\varepsilon^{1/\rho}} \right).
          \end{align}

    \item If $\tilde\rho\in (0,1)$, then for any $t_0>0$ and compact rectangle
          $J$ in $\mathbb{R}^d$, there exist two constants $0<C_8\le C_8'<\infty$ such that
          for all $\varepsilon\in(0,1)$,
          \begin{align}
            \exp\left( - \frac{C_8'}{\varepsilon^{d/\tilde\rho}} \right)
            \le \mathbb{P}\left\{ \sup_{x\in J} |u(t_0,x)| \le \varepsilon \right\}
            \le \exp\left( - \frac{C_8}{\varepsilon^{d/\tilde\rho}} \right).
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma local12 of arXiv:2507.20324, 'Non-existence of several random fractals in Brownian motion and Brownian loop soup'] For $d=2,3$, let $W_{i}$, $i=1,2,3$, be independent Brownian excursions from $\mathcal{C}_{0}$ to $\mathcal{C}_{n}$. Let $E_{1}$ denote the event that $W_{1}\cap(W_{2}\cup W_{3})=\varnothing$. Let $E_{i,j}$ be the event that $W_{i}$ returns to $\mathcal{C}_{jL}$ after hitting $\mathcal{C}_{(j+1)L}$. Then there exists $c$, such that for any integer $j\leq[n/L]-1$, and $i=1,2,3$,
\begin{equation}
\mathbb{P}(E_{i,j}\cap E_{1})\leq cn^{3(3-d)}2^{-L}2^{-(4-d)n}.
\end{equation}

