body:
[Lem lem-fixed-pos of arXiv:2411.06301, 'Inverting the operation of conditioning a branching process on extinction'] Consider a $d$-type branching process $X = \{X(n)\}_{n\in\mathbbm N_0}$ for which the extinction probability started from any state is one. Let $f$ be the corresponding generating function and let $q \in (0,\infty)^d$ solve $f(q) = q$. Then   
\begin{equation} 
q_k \geq 1, \quad \forall k \in \{1, \dots, d\}  .
\end{equation} 
Moreover, if the branching process is positive regular, then either $q_k = 1$ for every $k\in \{1,\dots,d\}$ or $q_k > 1$ for every $k \in \{1,\dots,d\}$.

[Theorem of arXiv:2505.15283, 'Quantization of Probability Distributions via Divide-and-Conquer: Convergence and Error Pr'] Assume that $\mu$ is a continuous probability measure with finite mean and assume that $\mathrm{supp}\,(\mu) = {\mathbb{R}}_+$ and let $\mu^{(n)} = T(\mu,n)$. Let $X$ be a random variable with distribution $\mu$, $\omega_{-1}= 0,\ \omega_0 = \int_{{\mathbb{R}}_+} t \mathrm{d} \mu(t)$ and define $\omega_{j+1} = {\mathbb{E}}[X | X \geq \omega_{j}], j\geq 0$ and $\Omega_j :=[\omega_{j-1},\omega_{j}]$, then for any $n\geq 0$ we have
    \begin{equation*}
        \begin{split}        
            W_1(\mu,\mu^{(n)}) 
            \leq
            \sum_{j=0}^{n-1} 
                \frac{
                        (\omega_{j}-\omega_{j-1})\mu(\Omega_{j})
                    }
                    {2^{n-j}} 
            + {\mathbb{E}}[ |X - \omega_{n}| ; X \geq \omega_{n-1}].
        \end{split}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem non i.i.d of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $(\sigma_n)_{n\ge 1}$ be positive numbers. Let $(g_n)_{n\ge 1}$ be simple graphs where $V(g_n)=[n]$ and consider the weighted graph $(g_n,\sigma^2)$, where $\sigma^2(i)=\sigma_i^2$. Assume that $(g_n,\sigma^2)_n$ converges to a graphon $w$, and that
    \begin{align*}
        &\vert \sigma^2\vert =\sum_{k\in [n]}\sigma_i^2 \to \infty; \quad \frac{\sigma_{\max}^2}{\vert \sigma^2\vert}\to 0.
    \end{align*}
    Let $a_1^{(n)},\ldots,a_n^{(n)} \in \mathcal{A}$ be $g_n$-independent centered random variables with variance $\operatorname{var}(a_k^{(n)})=\sigma_k^2$, for every $n \ge 1$. 
    Assume that there exist constants $C_p\ge 1$ that depends only on $p\ge 1$ such that for any $n,k,p\ge 1$, we have 
    \begin{align*}
       \tau\left(|a_k^{(n)}|^p\right)\le C_p\sigma_k^p.
    \end{align*}
    Then
    \begin{align*}
        S_n=\frac{1}{\sqrt{\vert\sigma^2\vert}}\sum_{k \in [n]} a_k^{(n)}
    \end{align*}
    converges in distribution to $\mu_w$, the law defined in (equation eq: definition of mu_w of the paper).

