body:
[Proposition 2 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Let $\Omega$ be a bounded, open set with $C^{1,1}$ boundary and $X=(X_t)_{t\ge 0}$ be a translation invariant isotropic process such that 
		\begin{align*}
			\E_0\left[\left(\overline{X}^{(1)}_T\right)^p\right]<\infty
		\end{align*}
		for some $T>0$ and $p>1$, and 
		\begin{align*}
			\lim_{t\downarrow 0}\frac{\E_0\left[\left(\overline{X}^{(1)}_t\right)^p\right]}{\E_0\left[\overline{X}^{(1)}_t\right]}=0.
		\end{align*}
		Then, 
		\begin{align*}
				\lim_{t\downarrow 0}\frac{\Vol(\Omega)-Q^X_\Omega(t)}{\E_0\left[\overline{X}^{(1)}_t\right]}=\Per(\Omega).
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2609.00687, 'A unification of Euler-Maclaurin and Euler-Boole summation formulas'] Let $q\in\mathbb{N}$, $m\in\mathbb{N}_{0}$ and $a,b\in\mathbb{R}$ with $a<b$. Let $\chi$ be a Dirichlet character modulo $q$ and let $f(t)$ be an $m+1$
times continuously differentiable function on the interval $[a,b]$. Then
\begin{eqnarray}
&&\sum_{\substack{a<k\leqslant b\\k\in\mathbb{Z}}}\chi(k)f(k)\nonumber\\
&&\qquad=\sum_{k=0}^{m}\frac{(-1)^{k+1}}{(k+1)!}\bigl(B_{k+1}(\{b\}_{\chi},\chi^{-})f^{(k)}(b)-B_{k+1}(\{a\}_{\chi},\chi^{-})f^{(k)}(a)\bigl)\nonumber\\
&&\qquad\quad+B_{0}(\chi^{-})\int_{a}^{b}f(t)dt\nonumber\\
&&\qquad\quad+\frac{(-1)^{m}}{(m+1)!}\int_{a}^{b}B_{m+1}(\{t\}_{\chi},\chi^{-})f^{(m+1)}(t)dt,
\end{eqnarray}
where
\begin{equation*}
B_{0}(\chi^{-})=\frac{1}{q}\sum_{r=1}^{q}\chi(-r),
\end{equation*}
and
\begin{equation*}
B_{m}(\{x\}_{\chi},\chi^{-})=q^{m-1}\sum_{r=1}^{q}\chi(-r)B_{m}\biggl(\biggl\{\frac{x+r}{q}\biggl\}\biggl).
\end{equation*}

[Lemma lem:estimate-contour of arXiv:2511.17101, 'Central limit theorem for the range of critical branching random walk'] For every $\gamma>2$, 
every $n, k\ge 1$,
\begin{align}     {\mathbb P}(C_{n}-2\min_{0\le i\le n}C_{i}\le  k) & \lesssim \, k^3 \, n^{-\frac 3 2},  \\
 {\mathbb E}[ (1+C_{n}-2\min_{0\le i\le n}C_{i})^{-\gamma}] & \lesssim_\gamma \, \begin{cases}
 n^{-\gamma/2}, & \mbox{if $\gamma< 3$}, \\
 n^{-3/2} \log (1+n),  & \mbox{if $\gamma= 3$}, \\
 n^{-3/2}, & \mbox{if $\gamma>3$}. \end{cases}

\end{align}

[Lemma 11 of arXiv:2607.16954, 'Repeated differentiation of deterministic polynomials with asymptotically radial root dist'] With the notation introduced above, we have that
\begin{equation}

\coef{k}{\rr}=\coef{k}{\pp}\prod_{j=0}^{ml-1} \falling{mn-mk+j\Delta}{b},\qquad \text{for } 0\leq k\leq n.
\end{equation}
By dividing (non-zero) consecutive coefficients, we then obtain
\begin{equation}

\frac{\coef{k}{\rr}}{\coef{k-1}{\rr}}=\frac{\coef{k}{\pp}}{\coef{k-1}{\pp}} \prod_{j=0}^{ml-1}  \frac{\falling{mn-mk+j\Delta}{b}}{\falling{mn-mk+m+j\Delta}{b}} \qquad \text{for } 1\leq k\leq n-c_\rr,
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ X = (X_{1}, \cdots, X_{n}) $ be a $ \mathbb{R}^{n} $-valued random variable. The function 
    \begin{align*}
        F(x) \equiv F\left(x_1, \cdots, x_n\right) \mathop{\buildrel\Delta\over=} \mathbb{P}\left\{X_1 \leq x_1, \cdots, X_n \leq x_n\right\}
    \end{align*}
    is called the distribution function of $ X $. 
    Furthermore, if there exists a nonnegative function $ f(\cdot) $ such that 
    \begin{align*}
        F(x) \equiv F\left(x_1, \cdots, x_n\right)=\int_{-\infty}^{x_1} \cdots \int_{-\infty}^{x_n} f\left(\xi_1, \cdots, \xi_n\right) d \xi_1 \cdots d \xi_n,
    \end{align*}
    then the function $ f(\cdot) $ is called the density of $ X $.

[Lemma diff between homo and homoinj of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] For any simple graph $f$ and node-weighted graph $(g,\alpha)$ with $|V(g)|\ge |V(f)|$, we have
    \begin{align*}
        |\rho(f,(g,\alpha))-\rho_{\operatorname{inj}}(f,(g,\alpha))|\le \frac{C_f\alpha_{\max}}{\vert\alpha\vert},
    \end{align*}
    where $C_f$ is a constant that depends only on $f$.

