body:
[Theorem 6 (Convergence rates for the averaged \Adam\ optimizer) of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] Consider
\begin{enumerate}[label=(\roman*)]
\item $ \alpha, \beta \in [0,1) $, $ \epsilon \in (0,\infty) $ with $ \alpha < \sqrt \beta $ (the \emph{damping factors}),
\item a decreasing $(0,\infty)$-valued sequence $(\gamma_{n})_{n\in\N}$ (\emph{sequence of step-sizes}), and
\item an $(X,U)$ be an innovation

\end{enumerate}
Let $ ( \theta_n )_{ n \in \N_0 } $ be an \Adam\ algorithm with innovation $ (X, U) $ and damping factors $ \alpha, \beta, \epsilon $,
let $ n_0 \in \N $ and for every $ n \in \{ n_0 + 1, \dots \} $ let
\bas{
  \bar\theta_n=\frac1{n-n_0}\sum_{k=n_0+1}^n \theta_k .
}
Moreover, denote by $f$ its \Adam\ vector field and by $\theta^{*}\in\R^{d}$ a zero of $f$. We assume the following assumptions:
\smallskip

\begin{enumerate}[label=(\alph*)]
\item \emph{Regularity of innovations.} There exist $p\in(2,\infty)$, $\cK,\delta\in(0,\infty)$,  $q\in(1-\beta,1]$
and a neighbourhood $ V $ of $ \theta^{*} $ such that
for every $ \theta, \theta' \in V $, $ i \in \{ 1, \dots, d \} $ one has
\bas{
  \E[|X(\theta,U)|^{p}]^{1/p}\le \cK,
  \qquad
  \E[|X(\theta,U)-X(\theta',U)|^{p}]^{1/p} \le \cK  \,|\theta-\theta'| ,
}
\bas{
  \text{and}
  \qquad
  \P( | X^{(i)}(\theta,U) |^2 \ge \delta )\ge q .
}
\item \emph{Stable attractor.} There exists a matrix $H\in\R^{d\times d}$  such that
\bas{
\sup\{\mathrm{Re}(\varrho):\varrho\text{ complex eigenvalue of }H\}<0
}
and there exist 
$ C \in ( 0, \infty ) $, $ \lambda \in (0,1] $ such that for all $ \theta \in V $ one has
\bas{
|f(\theta)-H(\theta-\theta^{*})|\le C\, |\theta-\theta^*|^{1+\lambda}.
}
\item \emph{Step-sizes.} One has
\bas{
\lim_{n\to\infty}\frac { \gamma_{n}- \gamma_{n+1}}{ \gamma_{n}^{2}}=0
}
and
\bas{
\lim_{n\to\infty} \frac1{\sqrt n}\sum_{k=1}^n \gamma_{k}^{\frac{1+\lambda}2}=0.
}

\end{enumerate}
Let $\Gamma=(\Gamma_{i,j})_{i,j=1,\dots,d}\in\R^{d\times d}$ be the matrix with
\bas{
\Gamma_{i,j} =\E[\cD^{(i)} \cD^{(j)}],
}
where
\bas{\cD =  g(\bX^{\theta^{*}}(1))+\Psi_{\theta^{*}}(\bX^{\theta^{*}}(1))-\Psi_{\theta^{*}}(\bX^{\theta^{*}}(0)) 
}
and $\bX^{\theta^{*}}(n)=(X(\theta^{*},U_{n+k}))_{k\in-\N_{0}}$ for all $n\in\N$.
Then one has, on the event $\{\lim_{n\to\infty}\theta_{n}=\theta^{*}\}$, weak convergence
\bas{

\sqrt n\,(\bar \theta_{n}-\theta^{*})\Rightarrow \cN\bigl(0,H^{-1} \Gamma (H^{-1})^{\dagger}\bigr).
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:kronecker-coordinate-formula of arXiv:2608.29719, 'Persistence Pairing Graphs: Tracking Changes of Selected Homology Bases'] For every $u\in\mathcal D_t^{(q)}$ and $v\in\mathcal S_t^{(q)}$, the transition coefficient $w_{uv}$ satisfies
\begin{equation}

w_{uv} = \left\langle\alpha_v^t, (i_t)_*[z_u]_{t^-}\right\rangle_t = \left\langle i_t^*\alpha_v^t, [z_u]_{t^-} \right\rangle_{t^-}.
\end{equation}

[Corollary cor:hit_moments of arXiv:2607.08914, 'Linear spreading speed in non-monotone population models'] For every $\eta_0$ which is non-zero only at the origin and every $k>0$
  there is a constant $c = c(k)$ such that for every $x\in \mathbb{N}$
  \begin{equation*}
    \mathbb{E}_{\eta_0}[\tau_\mathrm{hit}(x)^k \mathbf{1}_{\tau_\mathrm{hit}(x)<\infty}] \le c x^k.
  \end{equation*}

