body:
[Corollary of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Let $X_n,n\geq 1$ be a sequence of random variables such that each $X_n$ belongs to $\mathcal{A}$ has zero mean and admits a density. Set $F_n=X_n+m$ for $m=\E{\mathcal{Y}}$ and $h_{F_n}=\Gamma\brac{F_n,-L^{-1}2a(F_n)}$. Denote the density function of $F_n$ by $p_{F_n}$. Assume the moment bound
   \begin{align*}
&\sup_{n\geq 1}\Bigg\{\mathds{1}_{\{F_n\geq u \} }\Bigg(\E{\abs{\frac{-2a'(F_n)+b''(F_n)}{b(F_n)^2a(F_n)^2}} } +\E{\abs{\frac{(-2a(F_n)+b'(F_n))^2b'(F_n)^2}{b(F_n)^4a(F_n)^2}} }   \\
&\qquad+\E{\abs{\frac{-2a(F_n)+b'(F_n)}{b(F_n)^2a(F_n)^4}} }+\E{\abs{\frac{-2a(F_n)+b'(F_n)}{b(F_n)^2a(F_n)^2}} }\Bigg)\\
&\qquad\quad+\mathds{1}_{\{F_n\notin (\ell,u) \} }\E{\left\vert a(F_n) \right\rvert^{-4}}\\
&\qquad\quad\quad+\mathds{1}_{\{F_n\leq \ell \} }\Bigg(\E{\abs{\frac{-2a'(F_n)+b''(F_n)}{b(F_n)^2a(F_n)^2}} } +\E{\abs{\frac{(-2a(F_n)+b'(F_n))^2b'(F_n)^2}{b(F_n)^4a(F_n)^2}} }   \\
&\qquad\quad\quad\quad+\E{\abs{\frac{-2a(F_n)+b'(F_n)}{b(F_n)^2a(F_n)^4}} }+\E{\abs{\frac{-2a(F_n)+b'(F_n)}{b(F_n)^2a(F_n)^2}} }\Bigg)\\
&\qquad\quad\quad\quad\quad+\E{\Gamma\brac{-L^{-1}2a(F_n),F_n}^2}+\E{\brac{\frac{2a(F_n)-b'(F_n)}{h_{F_n} b(F_n)}}^2 }\\
&\qquad\qquad\qquad\qquad+\E{\frac{\Gamma(-L^{-1}2a(F_n) )}{h_{F_n}^4}}+\E{(L(h_{F_n}+b(F_n)))^2}+\E{\frac{2}{\abs{h_{F_n}}}}\\
&\qquad\quad+\mathds{1}_{\{F_n\in (\ell,u) \} }\brac{\E{\abs{\frac{a(F_n)}{b(F_n)}}^2}+\E{\frac{\left\vert -2a(F_n)+b'(F_n) \right\rvert^2}{\left\vert b(F_n) \right\rvert^4}}+\E{\left\vert b(F_n) \right\rvert^{-2}}}\Bigg\}<\infty; 
\end{align*}
and also that
\begin{align*}
&\E{\brac{\Gamma(-L^{-1}2a(F_n), h_F)+b'(F_n)h_{F_n}}^2}\to 0;\\
    &\E{\brac{h_{F_n}+b(F_n)}^2}\to 0;\quad\mathbb{E}{\left[ a(F_n)\right]}\to 0. 
\end{align*} 
Then it holds for $x\in \mathbb{R}$ that 
\begin{align*}
    \lim_{n\to \infty}p_{F_n}(x)=p_{\mathcal{Y}}(x). 
\end{align*}

