body:
[Lemma 20 of arXiv:2608.14802, 'Dynamical Gibbs-non-Gibbs transitions for finite-alphabet models on trees'] Let $l,\widetilde{l}\in \left(\Delta^{q-1}\right)^{d+1}$ with $l=(l^{(1)},\dots,l^{(d+1)})$ and $\widetilde{l}=(\widetilde{l}^{(1)},\dots,\widetilde{l}^{(d+1)})$. Define 
    \begin{equation}
R_{t,k}(l)
:=\frac{1}{Z(l)}\sum_{a\in S} P_t(a,k)H_a(l)~~\text{where}~~H_a(l)
:=\prod_{m=1}^{d+1}\sum_{b\in S} Q(a,b)l^{(m)}(b)
\end{equation}
and $Z(l):=\sum_{a\in S}H_a(l)$ for all $t>0$ and $k,a \in S$. Then, the following estimate in terms of $l$ and $\widetilde{l}$ holds for the root marginals 
\begin{equation}
    |R_{t,k}(l)-R_{t,k}(\widetilde{l})|\leq 2\left(\frac{\max_{i,j\in S}Q(i,j)}{\min_{i,j\in S}Q(i,j)}\right)^{d+1}\sum^{d+1}_{i=1}\|l^{(i)}-\widetilde{l}^{(i)}\|_{1}.
\end{equation}

