\begin{align}
{\lambda}\pi_0 &=\mu\pi_1+{\kappa}\sum\limits_{j = 1}^{\infty}\pi_j ,   \\
({\lambda} +i \mu+{\kappa} )\pi_i&={\lambda}\pi_{i-1}+ (i+1)\mu\pi_{i+1}, \quad i \ge 1,  \\
\sum_{j=0}^{\infty} \pi_j &=1.  
\end{align}
