body:
[Thm SigT of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For ${\boldsymbol{\gamma}} \in {\mathbb R}^{d_1}$ with ${\gamma}_i  > -1$, $1\le i \le d_1$ and ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with ${\kappa}_i > -1$, $1 \le i \le d_2$, define
\begin{align} 
  {\mathfrak D}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} u  : =  &
    \sum_{i=1}^{d_1} \left(x_i \partial_{x_i}^2 + ({\gamma}_i +1- x_i) \partial_{x_i} \right)  
    + \sum_{i=1}^{d_2} \left( y_i \partial_{y_i}^2 + (\kappa_i +1 - y_i) \partial_{y_i} \right)  \\
   & + 2 {\langle} {\bm x}, \nabla_{{\bm x}} {\rangle} \partial_{y_{d_2}} 
     - 2 {\langle} \bm y, \nabla_{\bm y} {\rangle} \partial_{y_{d_2}} + 2 |{\bm y}| \partial_{y_{d_2}}^2 \notag \\
     & + (|{\boldsymbol{\gamma}}| -|{\bm k}'| +d_1 - d_2 +1) \partial_{y_{d_2}}. \notag
\end{align}
Then ${\mathcal V}_n(\triangle^{d_1}  \rtimes {\mathbb R}_\Sigma^{d_2}, \bm W_{{\boldsymbol{\gamma}}, {\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma})$ is an eigenspace 
of $ {\mathfrak D}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma}$ for each $n \in {\mathbb N}_0$. More precisely, 
\begin{align} 
  {\mathfrak D}_{\mu,{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} u = - n  u, \qquad \forall u \in {\mathcal V}_n\big(\triangle^{d_1}  \rtimes {\mathbb R}_\Sigma^{d_2}, \bm W_{{\boldsymbol{\gamma}}, {\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma}\big).
\end{align}

[Lemma lem-measurability of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that a function  $g \colon  \mathbb{R} \to \mathbb{R}_+$  satisfies Condition (condition-g function of the paper).
 If  $ {z}_k \to {z}$ in $\mathscr{Z}_T$,  then
\begin{equation*}
\int_0^t \int_Y g(\ip{P_k F(s,z_k(s),y)}{\phi}{H})\, \nu(\mathrm{d} y) \, \mathrm{d}s
\to \int_0^t \int_Y g(\ip{F(s,z(s),y)}{\phi}{H})\, \nu(\mathrm{d} y) \, \mathrm{d}s.
\end{equation*}

