body:
[Theorem 39 ({\cite[Theorem 1.2 and Theorem 1.5) of arXiv:2607.18104, '2607.18104'] {BLL:FixedPointGeneral}}]
Suppose that $\lambda_N \in \Lambda_{N,k}$ with $k=\lfloor \theta N\rfloor$ for some $\theta \in (0,1)$ is a family of TASEP initial conditions so that for some $\hfixp_0 \in \UCp$
\begin{equation}
  \frac{-\hpTASEP(\lambda_N;\alpha N,0) + \theta\alpha N}{-\sqrt{2\theta(1-\theta)}N^{1/2}}   \rightarrow \hfixp_0(\alpha)
\end{equation} as $N\to \infty$ where the convergence is as a process in $\alpha$ in the space $\UCp$. Then for all $M \in \N$, 
and all $\tau=(\tau_i)_{i \in \lbr M \rbr}$, $\alpha=(\alpha_i)_{i \in \lbr M \rbr}$ and $\beta=(\beta_i)_{i \in \lbr M \rbr}$, 
 \begin{equation}
 \lim_{N \rightarrow \infty} \P\left( \bigcap_{i=1}^{M} \left\{ \frac{-\hpTASEP(\lambda_N;y_i,t_i)+\theta y_i-\theta(1-\theta)t_i}{ -\sqrt{2\theta(1-\theta)}N^{1/2}}\leq \beta_i \right\} \right) = F_{\hfix_0}^M(\beta,\alpha,\tau) , 
 \end{equation}
 where we set
 \begin{equation}
     t_i := \frac{\tau_i N^{3/2}}{\sqrt{\theta(1-\theta)}}, \quad y_i := \alpha_i N + (1-2\theta)t_i , 
 \end{equation}
 and $(F_{\hfix_0}^M)$ has an explicit formula given in Definition~2.1 of \cite{BLL:FixedPointGeneral}. Moreover, the family $(F_{\hfix_0}^M)$ defines a random field $(\alpha,\tau) \mapsto \mathcal{H}^{\per}_1(\hfixp_0;\alpha,\tau)$, called the \textbf{periodic KPZ fixed point}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Cayleyformula of arXiv:2609.01990, 'Jacquet-Zagier treatment of the beyond endoscopy trace formula for \(\GL_2\)'] For $\text{GL}_2$, the representation $\text{Sym}^m(\sigma_k)$ decomposes into irreducible as 
    \begin{equation}
        \text{Sym}^{m}(\sigma_k) = \bigoplus_{r=0}^{km/2} \mathfrak{c}(k,m,r) \left(\text{Sym}^{km-2r}(W) \otimes (\det)^r \right) 
    \end{equation}
    where the Plethysm coefficients $\mathfrak{c}(k,m,r)$ denote the multiplicities in the decomposition. These are given by the Cayley-Sylvester formula: 
    \begin{equation}
        \mathfrak{c}(k,m,r) = p_{m.k}(r) - p_{m,k}(r-1), \qquad p_{m,k}(-1) = 0, \qquad 0 \leq r \leq \lfloor \frac{km}{2} \rfloor 
    \end{equation}
    with $p_{m,k}(r)$ defined by 
    \begin{equation}
        \sum_{r=0}^{km} p_{m,k}(r) q^{r} = \prod_{j=1}^{k} \frac{1-q^{m+j}}{1-q^j} = \qbinom{m+k}{k}_q 
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:two-large-position of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$, then
\begin{equation}
  \kappa\le\floor*{\frac{3m}{2}}+\mu(d)+2\mu(\kappa),
  \qquad 1\le d<\frac\kappa2.
\end{equation}
Moreover
\begin{equation}
  \kappa\le3m,
\end{equation}
and, setting $\Pi_m=\floor{5m/2}+1$,
\begin{equation}
  p=\kappa-d-1\le \Pi_m.
\end{equation}

[Lemma lem:weighted-energy-detailed of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] For every $0<\sigma\leq1$, the normalized endomorphisms $H_i$ satisfy
\begin{align}
 &\|H_i^{-\sigma/2}\partial^{h_{\rm ref}}H_i^\sigma\|_{L^2}^2
 +\|H_i^{-\sigma/2}[\theta_{h_{\rm ref}}^*,H_i^\sigma]\|_{L^2}^2
 \leq C,
\end{align}
where $C$ is independent of both $i$ and $\sigma$.  Moreover, the constant below can be chosen independent of $\sigma$:
\begin{equation}
 \int_M\operatorname{tr}(H_i^\sigma)\,\omega\geq c_0>0.
\end{equation}

[Lemma 11 of arXiv:2608.26038, 'Rotated semicircle laws for permanental roots of Gaussian random matrices'] There is a constant \(C>0\), independent of \(N\), such that
\begin{equation}
  \sup_{x\in\R}K_N(x,x)\le CN,
  \qquad N\ge1.
\end{equation}
Consequently, every complex polynomial \(M\) of degree at most \(N\)
satisfies
\begin{equation}
  \sup_{x\in\R}|M(x)|e^{-Nx^2/4}
  \le
  \sqrt{CN}\,\|M\|_N.
\end{equation}

