[Lem 28 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For any $y\in \al, z\in \ar$ and $x\in A_{y,z}$, there exists $\mathcal S'$ with $\mathbb P(\mathcal S')\geq 1-\exp(-N^{\delta})$ such that the following holds.
    \begin{equation}
         \max_{j\in [N]}\mathbb P(\iota(x)=j,S_K\in\cS'|U_x) =O(N^{-c_F(x)+2\delta}),
    \end{equation}
    \begin{equation}
         \max_{j\in [N]}\mathbb P(\tau(x)=j,S_K\in\cS'|U_x) =O(N^{-c_F(x)+2\delta}).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary e:induction_eq2 of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] The quantity $V_m(F_1, j \vert F_2)$ satisfies the recurrence equation
			\begin{equation}
				\nabla \cdot ({\mathbf{a}}^{F_1} \nabla V_m(F_1,j \vert F_2)) = -\nabla \cdot \mathbf{W}_m(F_1,j \vert F_2) \quad \text{in } \mathrm{int}({\scaleobj{1}{\square}}_m),
			\end{equation}
			where 
			\begin{align}

				&\mathbf{W}_m(F_1,j \vert F_2) \\
				\nonumber &:= \sum_{e\in (E_d({\scaleobj{1}{\square}}_m) \setminus F_2) \setminus F_1}({\mathbf{a}}^{e}-\mathbf{a})\Big(\nabla V_m(F_1,j-1 \vert F_2) - \nabla V_m(F_1\cup \{e\}, j-2 \vert F_2) \\
				\nonumber & \qquad  + \nabla V_m(F_1\cup \{e\}, j-1\vert F_2)\Big) \\
				\nonumber &\qquad +\sum_{e\in F_1}({\mathbf{a}}^{e}-\mathbf{a})\Big(\nabla V_m(F_1\setminus\{e\},j \vert F_2)-\nabla V_m(F_1,j-1\vert F_2)\Big).
			\end{align}

[Definition EHI:d:smalllarge of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X=(X_t)_{t \geq 0}$ be an isotropic unimodal L\'{e}vy jujmp process on $\mathbb{R}^d$ with jump kernel $j(r)$. For each $r_0>0$, we define the \emph{small/large decomposition} of $X$ at $r_0$ as follows: For all $r>0$, let
    \begin{equation*}
        j^{(r_0)}(r) := j(r) \mathbf{1} \left\{ r \leq r_0 \right\}, \qquad \hat{j}^{(r_0)}(r) := j(r) \mathbf{1} \left\{ r>r_0 \right\}.
    \end{equation*}
    Let $X = X^{(r_0)} + \hat{X}^{(r_0)}$ be a Meyer decomposition of $X$, such that $X^{(r_0)}_0 = X_0$, $\hat{X}^{(r_0)}_0=0$, $X^{(r_0)}$ has jump kernel $j^{(r_0)}(r)$, $\hat{X}^{(r_0)}$ has jump kernel $\hat{j}^{(r_0)}(r)$, and $X^{(r_0)}$ and $\hat{X}^{(r_0)}$ are independent.
    Let
    \begin{equation}
        m_2(r_0) := \int_{\mathbb{R}^d} |x|^2 j^{(r_0)}(|x|) \; \mathrm{d} x \qquad \mbox{and} \qquad \lambda(r_0) := \int_{\mathbb{R}^d} \hat{j}^{(r_0)}(|x|) \; \mathrm{d} x.
    \end{equation}
    By the L\'{e}vy-Khintchine condition, $\lambda(r_0)<\infty$.
    Let $T^{(r_0)} := \inf\{ t>0 : \hat{X}^{(r_0)}_t \neq 0 \}$ be the first time that the process $\hat{X}^{(r_0)}$ takes a jump, and note that $T^{(r_0)}$ is Exponential($\lambda(r_0)$) and independent of the process $X^{(r_0)}$.

    Denote exit times for the process $X^{(r)}$ by $\tau^{(r)}_U := \inf \{t \geq 0 : X^{(r)}_t \notin U \}$.

[Proposition 14 of arXiv:2605.08345, '\vspace{-18mm}\textbf{Quantitative ergodicity for gene regulatory networks with transcript'] If the inequality 
\begin{equation} 
\Vert Z^{1}(t) - Z^{2}(t) \Vert +  \weightnorm{Y^{1}(t) - Y^{2}(t)}  \le \CompL(t) 
\end{equation}
is verified at time \( t = 0 \), then it is verified for all \( t \ge 0 \).

