body:
[Theorem log_analyticity_general of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $\bm p \in \mathcal B\,$, and $\bm u$ be as in Theorem (theorem:analyticity_general of the paper). Assume that $\bm{u}_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}} =\mathbb{E}[\exp(\bracket{\bm p}{\sigW[t,T]})] \neq 0$ for all $t \in [0\,,T]\,$, and define  $\bm \psi := \log^{\mathrel{\sqcup \mkern -3mu \sqcup}}(\bm u)$ as in (equation eq:def_log_shuffle_psi of the paper). It holds that:
    \begin{enumerate}
        \item For all $t \in [0,T]$ and $\sigX[] \in G$ such that $\|\bm u_t\|_{\sigX[]} < 2 |\bm u_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}|\,$, we have $\bm \psi_t \in \mathcal A_{\sigX[]}$ and 
        $$
        \mathbb{E}\left[\exp\left(\bracket{\bm p}{\sigX[] \otimes \sigW[t,T]}\right)\right] = \exp (\bracket{\bm \psi_t}{\sigX[]})\,.
        $$
        \item For any $\varepsilon \in (0\,,1)\,$, there exists $r = r(\bm p, T, \varepsilon) >0\,$, such that $\|\bm u_t\|_{\sigX[]} \leq (2-\varepsilon)|\bm u_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}|$ for all $t \in [0\,,T]$ and $\sigX[] \in G_{\bm p, r}\,$, so that $\bm \psi_t \in \mathcal A_{\bm p, r}\,$. Moreover,
        $$
        \sup_{t \in [0, T]} \|\bm \psi_t\|_{\sigX[]} \leq \sup_{t \in [0, T]} |\bm \psi_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}| + \log\left({\varepsilon}^{-1}\right) < + \infty\,, \quad \sigX[] \in G_{\bm p, r}.
        $$
        The Fourier--Laplace transform {thus} reads 
        \begin{align}
        \mathbb{E}\left[\exp \left(\bracket{\bm p}{\sigW[T]}\right) \, |\, \mathcal F _t\right] = \exp(\bracket{\bm{\psi}_t}{\sigW[t]}),     
        \end{align}
        for all $t \in [0, T]$ such that $|M_{\bm{p}}(\sigW)| \leq r$. In particular, (equation eq:logcharsigexpansion of the paper) holds for all  $t \in \llbracket  0, \tau \rrbracket$, where $\tau$ is a positive stopping time given by
        \begin{equation}
                \tau := \inf\{t \geq 0\colon\ |M_{\bm p}(\sigW[t])| \geq r \}.
        \end{equation}
        \item $t \mapsto \bm \psi_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}$ is continuous on $[0\,, T]\,$.
    \end{enumerate}

