[Theorem 11 of arXiv:2609.02699, '\vspace{-0.5 cm}Gauge theory and symplectic structures'] In dimension $6$, on a closed K\"ahler $3$-fold, for any $(A,\beta,\phi)$, we have the inequality
    \begin{align*}
        \mathcal E(A,\beta,\phi)\geq -8\pi^2\langle c_1(\mathcal L)^2\cup [\omega],[M]\rangle
    \end{align*}
    with equality if and only if $(A,\beta,\phi)$ solves the equations \eqref{Dirac}, \eqref{Curvature}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 23 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Let $\bar w_k, 0\le k\le n-1$ be the solution to the recursion
    \begin{equation}
    \bar w_{k+1}=\frac{X_k^2+Y_k^2-\mu_n}{Y_k^2} \,  \gamma_k  \bar w_k-\frac{X_k^2}{Y_k^2}  \gamma_k \gamma_{k-1} \bar w_{k-1},\qquad \bar w_0=\bar w_1=m_n.
    \end{equation}
    Let $\psi_*$ be the solution to the SDE \eqref{AirySDE_1} with Neumann initial condition $\psi_*(0)=1,\psi_*'(0)=0$. Then we have
        \begin{align}
        (m_n^{-1}\bar w_{\lfloor xm_n\rfloor}, \bar w_{\lfloor xm_n\rfloor +1}-\bar w_{\lfloor xm_n\rfloor}) \Rightarrow (\psi_*(x),\psi_*'(x)),
    \end{align}
    in law with respect to the Skorokhod topology on compact subsets of $\R_+$. Moreover, the convergence results \eqref{eq:ubar_conv} and \eqref{eq:wbar_conv} hold jointly. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:error-estimate-ms of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $Q, G$ be as defined in (equation eq:CG-res-gen of the paper). Then, there exist constants $\varepsilon_0, c_0, C_0, C_1,C_2, \beta > 0$ such that the following result holds. For $\varepsilon \in (0,\varepsilon_0)$ let $t \mapsto \mu^\varepsilon_t \in \mathcal{P}(\mathcal{X})$ and $t \mapsto \eta^\varepsilon_t\in \mathcal{P}(\mathcal{Y})$ be the solutions to
    \begin{equation*}
        \begin{dcases}
            \dfrac{\,\mathrm{d}}{\,\mathrm{d} t} \mu^\varepsilon_t = (L^\varepsilon)^T \mu_t^\varepsilon, \\
            \mu_{t = 0}^\varepsilon = \mu_0^\varepsilon,
        \end{dcases} \qquad \begin{dcases}
            \dfrac{\,\mathrm{d}}{\,\mathrm{d} t} \eta^\varepsilon_t = (N^\varepsilon)^T \eta_t^\varepsilon, \\
            \eta^\varepsilon_{t = 0} = \eta_0^\varepsilon,
        \end{dcases}
    \end{equation*}
    where we assume the following on the initial conditions $\mu_0^\varepsilon, \eta_0^\varepsilon$: 
    \begin{itemize}
        \item (strictly positive initial data) $\hat{\mu}_0^\varepsilon(x) \geq c_0$ and $\eta_0^\varepsilon(y) \geq c_0$ for all $\varepsilon \in (0, \varepsilon_0)$ and for all $x \in \mathcal{X}$ and all $y \in \mathcal{Y}$ respectively,
        \item (convergence) $\mu^\varepsilon_0$, $\hat{\mu}_0^\varepsilon = \xi_\#\mu^\varepsilon_0$ (see (equation eq:CGDyn-def of the paper)) and $\eta_0^\varepsilon$ converge in $\mathcal{P}(\mathcal{Y})$ as $\varepsilon \rightarrow 0$, 
        and
        \item (relative entropy estimate) for all $\varepsilon \in (0,\varepsilon_0)$
        \begin{equation*} 
        \mathscr{H}_{\eta_0^\varepsilon}\left(\frac{\hat{\mu}_0^\varepsilon}{\eta_0^\varepsilon}\right) \leq C_0 \varepsilon.
    \end{equation*}
    \end{itemize}
    Then, the estimate
    \begin{equation}
        \mathscr{H}_{\eta_t^\varepsilon} \left(\frac{\hat{\mu}_t^\varepsilon}{\eta_t^\varepsilon}\right) \leq \varepsilon C_1 e^{-\beta t}
    \end{equation}
    holds for all $t \geq 0$ and all $\varepsilon \in (0,\varepsilon_0)$. 
    In particular, the time-uniform estimate
    \begin{equation}
        \sup_{t \geq 0} \mathscr{H}_{\eta_t^\varepsilon} \left(\frac{\hat{\mu}_t^\varepsilon}{\eta_t^\varepsilon}\right) \leq C_2 \varepsilon
    \end{equation}
    holds for all $\varepsilon \in (0,\varepsilon_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 4 of arXiv:2606.21778, 'Pontryagin Maximum Principle in Free Probability Theory'] A free Brownian motion $(W_t)_{t\geq 0}$ is a family elements of $\mathcal{A}$ adapted to the filtration $\mathbb{F}=(\mathcal{A}_t)_{t\geq 0}$, which admits the following properties:
	\begin{enumerate}
		\item $W_t$ is a self-adjoint element of $\mathcal{A}$ with semi-circular distribution of mean zero and variance $t$, 		
		\item For all $s,t$ with $s\leq t$, the element $W_t-W_s$ is free of $\mathcal{A}_s$ and has a semi-circular distribution with mean $0$ and variance $t-s$.
	\end{enumerate}

